import itertools

_CACHE = {}


def _visible_count(seq):
    seen = 0
    tallest = 0
    for x in seq:
        if x > tallest:
            tallest = x
            seen += 1
    return seen


def _prepare(n):
    if n in _CACHE:
        return _CACHE[n]

    perms = list(itertools.permutations(range(1, n + 1)))
    pcount = len(perms)
    full_mask = (1 << pcount) - 1

    pos_val_mask = [[0] * (n + 1) for _ in range(n)]
    exact_clue_mask = {}

    for idx, perm in enumerate(perms):
        bit = 1 << idx
        lv = _visible_count(perm)
        rv = _visible_count(reversed(perm))
        exact_clue_mask[(lv, rv)] = exact_clue_mask.get((lv, rv), 0) | bit
        for pos, val in enumerate(perm):
            pos_val_mask[pos][val] |= bit

    clue_mask = {}
    for l in range(n + 1):
        for r in range(n + 1):
            mask = 0
            for lv in range(1, n + 1):
                if l and lv != l:
                    continue
                for rv in range(1, n + 1):
                    if r and rv != r:
                        continue
                    mask |= exact_clue_mask.get((lv, rv), 0)
            clue_mask[(l, r)] = mask

    subset_pos_mask = [[0] * (1 << n) for _ in range(n)]
    for pos in range(n):
        for bits in range(1, 1 << n):
            lsb = bits & -bits
            val = lsb.bit_length()
            subset_pos_mask[pos][bits] = subset_pos_mask[pos][bits ^ lsb] | pos_val_mask[pos][val]

    cache = {
        "n": n,
        "perms": perms,
        "full_mask": full_mask,
        "pos_val_mask": pos_val_mask,
        "clue_mask": clue_mask,
        "subset_pos_mask": subset_pos_mask,
    }
    _CACHE[n] = cache
    return cache


def _value_bits(mask, pos, pos_val_mask, n):
    bits = 0
    for v in range(1, n + 1):
        if mask & pos_val_mask[pos][v]:
            bits |= 1 << (v - 1)
    return bits


def _iter_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit
        mask ^= bit


def _propagate(row_masks, col_masks, data):
    n = data["n"]
    pos_val_mask = data["pos_val_mask"]
    subset_pos_mask = data["subset_pos_mask"]

    while True:
        changed = False

        row_bits = [[0] * n for _ in range(n)]
        col_bits = [[0] * n for _ in range(n)]

        for r in range(n):
            rm = row_masks[r]
            if rm == 0:
                return None
            for c in range(n):
                bits = _value_bits(rm, c, pos_val_mask, n)
                if bits == 0:
                    return None
                row_bits[r][c] = bits

        for c in range(n):
            cm = col_masks[c]
            if cm == 0:
                return None
            for r in range(n):
                bits = _value_bits(cm, r, pos_val_mask, n)
                if bits == 0:
                    return None
                col_bits[r][c] = bits

        for r in range(n):
            new_mask = row_masks[r]
            for c in range(n):
                allowed = col_bits[r][c]
                if row_bits[r][c] & allowed == 0:
                    return None
                new_mask &= subset_pos_mask[c][allowed]
                if new_mask == 0:
                    return None
            if new_mask != row_masks[r]:
                row_masks[r] = new_mask
                changed = True

        for c in range(n):
            new_mask = col_masks[c]
            for r in range(n):
                allowed = row_bits[r][c]
                if col_bits[r][c] & allowed == 0:
                    return None
                new_mask &= subset_pos_mask[r][allowed]
                if new_mask == 0:
                    return None
            if new_mask != col_masks[c]:
