        # if a value can only appear once in a row/column position-wise,
        # the dual row/column permutation filtering above will force it naturally.
        if not changed:
            return row_masks, col_masks


def _is_singleton(mask):
    return mask and (mask & (mask - 1) == 0)


def _mask_to_index(mask):
    return mask.bit_length() - 1


def _extract_grid(row_masks, data):
    perms = data["perms"]
    grid = []
    for mask in row_masks:
        if not _is_singleton(mask):
            return None
        grid.append(list(perms[_mask_to_index(mask)]))
    return grid


def _search(row_masks, col_masks, data):
