            best_idx = i
            best_mask = m
            best_count = bc

    if best_kind is None:
        return None

    for bit in _iter_bits(best_mask):
        new_rows = row_masks[:]
        new_cols = col_masks[:]
        if best_kind == "row":
            new_rows[best_idx] = bit
        else:
            new_cols[best_idx] = bit
        result = _search(new_rows, new_cols, data)
        if result is not None:
            return result

    return None


def solve(observation):
