        row_masks.append(mask)

    for c in range(n):
        mask = clue_mask.get((U[c], D[c]), 0)
        if mask == 0:
            return "No Solution"
        col_masks.append(mask)

    grid = _search(row_masks, col_masks, data)
    if grid is None:
        return "No Solution"
    return str(grid)


