# Generalized Minesweeper-style solver using:
# - equation building from clues
# - repeated direct propagation
# - subset-difference deductions
# - overlap-bound deductions
# - connected-component decomposition
# - tightly pruned backtracking only when logic alone is insufficient

from collections import defaultdict, deque

def neighbors(r, c, rows, cols):
    for dr in (-1, 0, 1):
        nr = r + dr
        if not (0 <= nr < rows):
            continue
        for dc in (-1, 0, 1):
            nc = c + dc
            if dr == 0 and dc == 0:
                continue
            if 0 <= nc < cols:
                yield nr, nc

def build_constraints(data):
    rows = len(data)
    cols = len(data[0]) if rows else 0
    constraints = {}
    variables = set()

    for r in range(rows):
        for c in range(cols):
            if data[r][c] is None:
                variables.add((r, c))

    for r in range(rows):
        for c in range(cols):
            clue = data[r][c]
            if clue is None:
                continue
            unknowns = []
            for nr, nc in neighbors(r, c, rows, cols):
                if data[nr][nc] is None:
                    unknowns.append((nr, nc))
            key = frozenset(unknowns)
            prev = constraints.get(key)
            if prev is not None and prev != clue:
                return None, None
            constraints[key] = clue

    return variables, constraints

def simplify_constraints(assignments, constraints):
    new_constraints = {}
    for cells, total in constraints.items():
        rem = []
        t = total
        for v in cells:
            val = assignments.get(v)
            if val is None:
                rem.append(v)
            else:
                t -= val
        if t < 0 or t > len(rem):
            return None
        rem = frozenset(rem)
        if not rem:
            if t != 0:
                return None
            continue
        prev = new_constraints.get(rem)
        if prev is not None and prev != t:
            return None
        new_constraints[rem] = t
    return new_constraints

def propagate(assignments, constraints):
    assignments = dict(assignments)
    constraints = dict(constraints)

    while True:
        constraints = simplify_constraints(assignments, constraints)
        if constraints is None:
            return None

        changed = False

        # Direct rules: all safe / all mines
        forced = []
        for cells, total in constraints.items():
            if total == 0:
                for v in cells:
                    if v not in assignments:
                        forced.append((v, 0))
            elif total == len(cells):
                for v in cells:
                    if v not in assignments:
                        forced.append((v, 1))

        if forced:
            for v, val in forced:
                cur = assignments.get(v)
                if cur is not None and cur != val:
                    return None
                if cur is None:
                    assignments[v] = val
                    changed = True
            if changed:
                continue

        items = sorted(constraints.items(), key=lambda x: (len(x[0]), x[1]))

        # Subset-difference deductions
        derived = {}
        n = len(items)
        for i in range(n):
            a_cells, a_total = items[i]
            for j in range(i + 1, n):
                b_cells, b_total = items[j]

                if len(a_cells) == len(b_cells):
                    if a_cells == b_cells and a_total != b_total:
                        return None
                    continue

                small_cells, small_total = (a_cells, a_total) if len(a_cells) < len(b_cells) else (b_cells, b_total)
                big_cells, big_total = (b_cells, b_total) if len(a_cells) < len(b_cells) else (a_cells, a_total)

                if small_cells.issubset(big_cells):
                    diff = big_cells - small_cells
                    diff_total = big_total - small_total
                    if diff_total < 0 or diff_total > len(diff):
                        return None
                    if diff:
                        prev = constraints.get(diff)
                        if prev is not None and prev != diff_total:
                            return None
                        prev = derived.get(diff)
                        if prev is not None and prev != diff_total:
                            return None
                        if prev is None and diff not in constraints:
                            derived[diff] = diff_total

        if derived:
            constraints.update(derived)
            changed = True
            continue

        # Overlap-bound deductions
        overlap_forced = []
        items = list(constraints.items())
        n = len(items)
        for i in range(n):
            a_cells, a_total = items[i]
            for j in range(i + 1, n):
                b_cells, b_total = items[j]
                inter = a_cells & b_cells
                if not inter:
                    continue

                a_only = a_cells - inter
                b_only = b_cells - inter

                low_inter = max(0, a_total - len(a_only), b_total - len(b_only))
                high_inter = min(len(inter), a_total, b_total)
                if low_inter > high_inter:
                    return None

                if high_inter == 0:
                    for v in inter:
                        if v not in assignments:
                            overlap_forced.append((v, 0))
                elif low_inter == len(inter):
                    for v in inter:
                        if v not in assignments:
                            overlap_forced.append((v, 1))

                a_only_low = a_total - high_inter
                a_only_high = a_total - low_inter
                if a_only_low < 0 or a_only_high > len(a_only) or a_only_low > a_only_high:
                    return None
                if a_only:
                    if a_only_high == 0:
                        for v in a_only:
                            if v not in assignments:
                                overlap_forced.append((v, 0))
                    elif a_only_low == len(a_only):
                        for v in a_only:
                            if v not in assignments:
                                overlap_forced.append((v, 1))

                b_only_low = b_total - high_inter
                b_only_high = b_total - low_inter
                if b_only_low < 0 or b_only_high > len(b_only) or b_only_low > b_only_high:
                    return None
                if b_only:
                    if b_only_high == 0:
                        for v in b_only:
                            if v not in assignments:
                                overlap_forced.append((v, 0))
                    elif b_only_low == len(b_only):
                        for v in b_only:
                            if v not in assignments:
                                overlap_forced.append((v, 1))

        if overlap_forced:
            for v, val in overlap_forced:
                cur = assignments.get(v)
                if cur is not None and cur != val:
                    return None
                if cur is None:
                    assignments[v] = val
                    changed = True
            if changed:
                continue

        if not changed:
            return assignments, constraints

def split_components(constraints):
    if not constraints:
        return []

    items = list(constraints.items())
    var_to_cons = defaultdict(list)
    for idx, (cells, _) in enumerate(items):
        for v in cells:
            var_to_cons[v].append(idx)

    seen_vars = set()
    components = []

    for v in list(var_to_cons):
        if v in seen_vars:
            continue
        q = deque([v])
        seen_vars.add(v)
        comp_vars = set([v])
        comp_cons_idx = set()

        while q:
            cur = q.popleft()
            for ci in var_to_cons[cur]:
                if ci not in comp_cons_idx:
                    comp_cons_idx.add(ci)
                    cells, _ = items[ci]
                    for u in cells:
                        if u not in seen_vars:
                            seen_vars.add(u)
                            comp_vars.add(u)
                            q.append(u)

        comp_constraints = {}
        for ci in comp_cons_idx:
            cells, total = items[ci]
            comp_constraints[cells] = total
        components.append((comp_vars, comp_constraints))

    components.sort(key=lambda x: (len(x[0]), len(x[1])))
    return components

def choose_branch_variable(constraints):
    occur = defaultdict(int)
    min_size = {}
    density = defaultdict(float)
    density_count = defaultdict(int)

    for cells, total in constraints.items():
        size = len(cells)
        frac = total / size
        for v in cells:
            occur[v] += 1
            if v not in min_size or size < min_size[v]:
                min_size[v] = size
            density[v] += frac
            density_count[v] += 1

    best = None
    best_key = None
    for v in occur:
        avg_density = density[v] / density_count[v]
        key = (min_size[v], -occur[v], -abs(avg_density - 0.5))
        if best_key is None or key < best_key:
            best_key = key
            best = v
    return best

def branch_order(var, constraints):
    total = 0.0
    cnt = 0
    for cells, clue in constraints.items():
        if var in cells:
            total += clue / len(cells)
            cnt += 1
    p = total / cnt if cnt else 0.5
    return (1, 0) if p > 0.5 else (0, 1)

def backtrack_component(constraints):
    res = propagate({}, constraints)
    if res is None:
        return None
    assignments, constraints = res
    if not constraints:
        return assignments

    var = choose_branch_variable(constraints)
    if var is None:
        return assignments

    for val in branch_order(var, constraints):
        new_assignments = dict(assignments)
        new_assignments[var] = val
        sub = backtrack_component_with_seed(new_assignments, constraints)
        if sub is not None:
            return sub
    return None

def backtrack_component_with_seed(assignments, constraints):
    res = propagate(assignments, constraints)
    if res is None:
        return None
    assignments, constraints = res
    if not constraints:
        return assignments

    var = choose_branch_variable(constraints)
    if var is None:
        return assignments

    for val in branch_order(var, constraints):
        if var in assignments and assignments[var] != val:
            continue
        new_assignments = dict(assignments)
        new_assignments[var] = val
        sub = backtrack_component_with_seed(new_assignments, constraints)
        if sub is not None:
            return sub
    return None

def validate_solution(data, assignment):
    rows = len(data)
    cols = len(data[0]) if rows else 0
    for r in range(rows):
        for c in range(cols):
            clue = data[r][c]
            if clue is None:
                continue
            count = 0
            for nr, nc in neighbors(r, c, rows, cols):
                count += assignment.get((nr, nc), 0)
            if count != clue:
                return False
    return True

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0

    variables, constraints = build_constraints(data)
    if variables is None:
        return "No Solution"

    initial = propagate({}, constraints)
    if initial is None:
        return "No Solution"
    fixed_assignments, simplified_constraints = initial

    final_assignment = dict(fixed_assignments)

    components = split_components(simplified_constraints)
    for comp_vars, comp_constraints in components:
        sol = backtrack_component(comp_constraints)
        if sol is None:
            return "No Solution"
        final_assignment.update(sol)

    # Any unconstrained unknown cell is free; default it to safe.
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is None and (r, c) not in final_assignment:
                final_assignment[(r, c)] = 0

    if not validate_solution(data, final_assignment):
