from collections import deque
import sys

sys.setrecursionlimit(1000000)


def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0

    U, B, W = -1, 0, 1
    to_int = {'B': B, 'W': W, None: U}
    to_chr = {B: 'B', W: 'W'}

    def idx(r, c):
        return r * cols + c

    n = rows * cols
    neighbors = [[] for _ in range(n)]
    for r in range(rows):
        for c in range(cols):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < rows:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < cols:
                neighbors[i].append(idx(r, c + 1))

    boxes = []
    cell_boxes = [[] for _ in range(n)]
    for r in range(rows - 1):
        for c in range(cols - 1):
            box = (idx(r, c), idx(r, c + 1), idx(r + 1, c), idx(r + 1, c + 1))
            boxes.append(box)
            for i in box:
                cell_boxes[i].append(box)

    initial = [to_int[x] for row in data for x in row]

    # Partial connectivity feasibility:
    # all currently colored cells of a color must still be connectable through cells
    # that are either that color or still unknown.
    def color_feasible(arr, color):
        opp = W if color == B else B
        starts = [i for i, v in enumerate(arr) if v == color]
        allowed_exists = any(v != opp for v in arr)
        if not allowed_exists:
            return False
        if not starts:
            return True

        start = starts[0]
        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            for nb in neighbors[cur]:
                if nb not in seen and arr[nb] != opp:
                    seen.add(nb)
                    dq.append(nb)

        for i in starts:
            if i not in seen:
                return False
        return True

    def exact_color_connected(arr, color):
        cells = [i for i, v in enumerate(arr) if v == color]
        if not cells:
            return False
        start = cells[0]
        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            for nb in neighbors[cur]:
                if nb not in seen and arr[nb] == color:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(cells)

    def local_2x2_ok(arr):
        for a, b, c, d in boxes:
            va, vb, vc, vd = arr[a], arr[b], arr[c], arr[d]
            if va != U and va == vb == vc == vd:
                return False
        return True

    def partial_consistent(arr):
        if not local_2x2_ok(arr):
            return False
        if not color_feasible(arr, B):
            return False
        if not color_feasible(arr, W):
            return False
        return True

    def final_consistent(arr):
        if any(v == U for v in arr):
            return False
        if not local_2x2_ok(arr):
            return False
        if not exact_color_connected(arr, B):
            return False
        if not exact_color_connected(arr, W):
            return False
        return True

    # Deterministic human-like propagation:
    # 1) No 2x2 monochrome -> if 3 cells in a 2x2 are same color, 4th is forced opposite.
    def basic_propagate(arr):
        arr = arr[:]
        while True:
            changed = False

            for box in boxes:
                vals = [arr[i] for i in box]

                if vals[0] != U and vals.count(vals[0]) == 4:
                    return None

                for color in (B, W):
                    if vals.count(color) == 3 and vals.count(U) == 1:
                        pos = box[vals.index(U)]
                        forced = W if color == B else B
                        if arr[pos] == U:
                            arr[pos] = forced
                            changed = True
                        elif arr[pos] != forced:
                            return None

            if not partial_consistent(arr):
                return None

            if not changed:
                return arr

    def influence(i, arr):
        score = 0
        for nb in neighbors[i]:
            if arr[nb] != U:
                score += 3
        for box in cell_boxes[i]:
            unknowns = 0
            same_pressure = False
            vals = []
            for j in box:
                vals.append(arr[j])
                if arr[j] == U:
                    unknowns += 1
            score += 4 - unknowns
            if vals.count(B) >= 2 or vals.count(W) >= 2:
                same_pressure = True
            if same_pressure:
                score += 2
        return score

    # One-step contradiction reasoning:
    # try both colors; if one fails under deterministic propagation, force the other.
    def propagate(arr):
        arr = basic_propagate(arr)
        if arr is None:
            return None

        while True:
            unknowns = [i for i, v in enumerate(arr) if v == U]
            if not unknowns:
                return arr

            unknowns.sort(key=lambda i: -influence(i, arr))
            progress = False

            for i in unknowns:
                results = {}
                possible = []

                for color in (B, W):
                    trial = arr[:]
                    trial[i] = color
                    trial = basic_propagate(trial)
                    if trial is not None:
                        possible.append(color)
                        results[color] = trial

                if not possible:
                    return None

                if len(possible) == 1:
                    arr = results[possible[0]]
                    progress = True
                    break

            if not progress:
                return arr

    def option_score(i, color, arr):
        score = 0
        other = W if color == B else B

        for nb in neighbors[i]:
            if arr[nb] == color:
                score += 4
            elif arr[nb] == other:
                score -= 1

        for box in cell_boxes[i]:
            others = [arr[j] for j in box if j != i]
            score += 2 * others.count(color)
            score -= 1 * others.count(other)

        return score

    memo = {}

    def search(state):
        if state in memo:
            return memo[state]

        arr = propagate(list(state))
        if arr is None:
            memo[state] = None
            return None

        state2 = tuple(arr)
        if state2 in memo:
            return memo[state2]

        if U not in state2:
            ans = state2 if final_consistent(arr) else None
            memo[state] = ans
            memo[state2] = ans
            return ans

        best_i = None
        best_options = None
        best_trials = None
        best_key = None

        unknowns = [i for i, v in enumerate(arr) if v == U]
        unknowns.sort(key=lambda i: -influence(i, arr))

        for i in unknowns:
            options = []
            trials = {}

            for color in (B, W):
                trial = arr[:]
                trial[i] = color
                trial = basic_propagate(trial)
                if trial is not None:
                    options.append(color)
                    trials[color] = tuple(trial)

            if not options:
                memo[state] = None
                memo[state2] = None
                return None

            key = (len(options), -influence(i, arr))
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
                best_options = options
                best_trials = trials

            if len(options) == 1:
                break

        best_options.sort(key=lambda color: -option_score(best_i, color, arr))

        for color in best_options:
            result = search(best_trials[color])
            if result is not None:
                memo[state] = result
                memo[state2] = result
                return result

        memo[state] = None
        memo[state2] = None
        return None

    sol = search(tuple(initial))
    if sol is None:
        return "No Solution"

    out = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append(to_chr[sol[idx(r, c)]])
        out.append(row)
    return out


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 1, None], [None, 1, 2, 3, 3], [None, 2, None, None, None], [None, None, None, None, None], [1, None, 2, None, 0]]}

# Generalized Minesweeper-style solver with human-like deduction:
# - direct count rules
# - subset/difference rules between clue neighborhoods
# - connected-component decomposition
# - residual subcomponent splitting during search
# - constrained branching only when logic stalls

def solve(observation):
    data = observation['data']
    h = len(data)
    w = len(data[0]) if h else 0

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if nr < 0 or nr >= h:
                continue
            for dc in (-1, 0, 1):
                nc = c + dc
                if dc == 0 and dr == 0:
                    continue
                if 0 <= nc < w:
                    yield nr, nc

    # Build clue constraints over unknown cells only.
    var_index = {}
    var_cells = []
    raw_constraints = []

    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            cells = []
            for nr, nc in neighbors(r, c):
                if data[nr][nc] is None:
                    if (nr, nc) not in var_index:
                        var_index[(nr, nc)] = len(var_cells)
                        var_cells.append((nr, nc))
                    cells.append(var_index[(nr, nc)])
            if clue < 0 or clue > len(cells):
                return "No Solution"
            if cells:
                raw_constraints.append((tuple(sorted(set(cells))), clue))
            elif clue != 0:
                return "No Solution"

    nvars = len(var_cells)

    # Unknown cells not adjacent to any clue are unconstrained; choose safe by default.
    unconstrained_unknowns = []
    for r in range(h):
        for c in range(w):
            if data[r][c] is None and (r, c) not in var_index:
                unconstrained_unknowns.append((r, c))

    if nvars == 0:
        answer = [[None for _ in range(w)] for _ in range(h)]
        if _verify(data, answer):
            return repr(answer)
        return "No Solution"

    # Merge duplicate constraints if present.
    merged = {}
    for cells, target in raw_constraints:
        key = cells
        if key in merged and merged[key] != target:
            return "No Solution"
        merged[key] = target
    raw_constraints = [(cells, target) for cells, target in merged.items()]

    # Build connected components of the frontier.
    var_to_cons = [[] for _ in range(nvars)]
    for ci, (cells, target) in enumerate(raw_constraints):
        for v in cells:
            var_to_cons[v].append(ci)

    visited_v = [False] * nvars
    global_assignment = [0] * nvars

    for start_v in range(nvars):
        if visited_v[start_v]:
            continue

        stack_vars = [start_v]
        comp_vars = []
        comp_cons = set()
        visited_v[start_v] = True

        while stack_vars:
            v = stack_vars.pop()
            comp_vars.append(v)
            for ci in var_to_cons[v]:
                if ci not in comp_cons:
                    comp_cons.add(ci)
                    cells, _ = raw_constraints[ci]
                    for u in cells:
                        if not visited_v[u]:
                            visited_v[u] = True
                            stack_vars.append(u)

        comp_vars.sort()
        local_of_global = {gv: i for i, gv in enumerate(comp_vars)}
        local_constraints = []
        for ci in sorted(comp_cons):
            cells, target = raw_constraints[ci]
            mask = 0
            for gv in cells:
                mask |= 1 << local_of_global[gv]
            local_constraints.append((mask, target))

        comp_solution = _solve_component(len(comp_vars), local_constraints)
        if comp_solution is None:
            return "No Solution"

        for i, gv in enumerate(comp_vars):
            global_assignment[gv] = comp_solution[i]

    answer = [[None for _ in range(w)] for _ in range(h)]
    for idx, (r, c) in enumerate(var_cells):
        if global_assignment[idx] == 1:
            answer[r][c] = 'F'
    for r, c in unconstrained_unknowns:
        answer[r][c] = None

    if not _verify(data, answer):
        return "No Solution"
    return repr(answer)


def _iter_bits(mask):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length() - 1
        mask ^= lsb


def _reduce_constraints(constraints, assign):
    reduced = {}
    involved_mask = 0

    for mask, target in constraints:
        rem_mask = 0
        rem_target = target
        m = mask
        while m:
            lsb = m & -m
            i = lsb.bit_length() - 1
            val = assign[i]
            if val == -1:
                rem_mask |= lsb
            elif val == 1:
                rem_target -= 1
            m ^= lsb

        if rem_target < 0 or rem_target > rem_mask.bit_count():
            return None, None

        if rem_mask == 0:
            if rem_target != 0:
                return None, None
            continue

        prev = reduced.get(rem_mask)
        if prev is not None and prev != rem_target:
            return None, None
        reduced[rem_mask] = rem_target
        involved_mask |= rem_mask

    return reduced, involved_mask


def _subset_closure(reduced):
    cons = dict(reduced)

    while True:
        items = list(cons.items())
        changed = False
        n = len(items)

        for i in range(n):
            mask_a, ta = items[i]
            for j in range(i + 1, n):
                mask_b, tb = items[j]

                if mask_a == mask_b:
                    if ta != tb:
                        return None
                    continue

                if (mask_a & ~mask_b) == 0:
                    diff = mask_b ^ mask_a
                    td = tb - ta
                elif (mask_b & ~mask_a) == 0:
                    diff = mask_a ^ mask_b
                    td = ta - tb
                else:
                    continue

                if td < 0 or td > diff.bit_count():
                    return None
                if diff == 0:
                    if td != 0:
                        return None
                    continue

                prev = cons.get(diff)
                if prev is not None:
                    if prev != td:
                        return None
                else:
                    cons[diff] = td
                    changed = True

        if not changed:
            return cons


def _propagate(num_vars, constraints, assign):
    assign = assign[:]

    while True:
        changed = False

        reduced, involved_mask = _reduce_constraints(constraints, assign)
        if reduced is None:
            return None

        # Cells no longer participating in any residual constraint are safely non-mines.
        for i in range(num_vars):
            if assign[i] == -1 and ((involved_mask >> i) & 1) == 0:
                assign[i] = 0
                changed = True

        if changed:
            continue

        closure = _subset_closure(reduced)
        if closure is None:
            return None

        for mask, target in closure.items():
            cnt = mask.bit_count()

            if target == 0:
                m = mask
                while m:
                    lsb = m & -m
                    i = lsb.bit_length() - 1
                    if assign[i] == -1:
                        assign[i] = 0
                        changed = True
                    elif assign[i] != 0:
                        return None
                    m ^= lsb

            elif target == cnt:
                m = mask
                while m:
                    lsb = m & -m
                    i = lsb.bit_length() - 1
                    if assign[i] == -1:
                        assign[i] = 1
                        changed = True
                    elif assign[i] != 1:
                        return None
                    m ^= lsb

        if not changed:
            reduced_after, _ = _reduce_constraints(constraints, assign)
            if reduced_after is None:
                return None
            return assign, reduced_after


def _split_groups(num_vars, reduced_constraints, assign):
    unassigned = [i for i in range(num_vars) if assign[i] == -1]
    if not unassigned:
        return []

    involved = 0
    for mask, _ in reduced_constraints:
        involved |= mask

    vars_involved = [i for i in unassigned if ((involved >> i) & 1)]
    if not vars_involved:
        return []

    adj = {i: set() for i in vars_involved}
    for mask, _ in reduced_constraints:
        bits = [i for i in _iter_bits(mask)]
        if len(bits) >= 2:
            first = bits[0]
            for b in bits[1:]:
                adj[first].add(b)
                adj[b].add(first)

    seen = set()
    groups = []
    for v in vars_involved:
        if v in seen:
            continue
        stack = [v]
        seen.add(v)
        comp = []
        while stack:
            x = stack.pop()
            comp.append(x)
            for y in adj.get(x, ()):
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        groups.append(sorted(comp))

    if len(groups) <= 1:
        return []

    group_data = []
    for gvars in groups:
        gset = set(gvars)
        gmap = {gv: i for i, gv in enumerate(gvars)}
        gcons = []
        for mask, target in reduced_constraints:
            bits = [i for i in _iter_bits(mask)]
            if bits and all(b in gset for b in bits):
                gmask = 0
                for b in bits:
                    gmask |= 1 << gmap[b]
                gcons.append((gmask, target))
        group_data.append((gvars, gcons))

    return group_data


def _choose_branch_var(num_vars, reduced_constraints, assign):
    score = [0] * num_vars
    support = [0] * num_vars
    mine_bias_num = [0.0] * num_vars
    mine_bias_den = [0] * num_vars

    for mask, target in reduced_constraints:
        cnt = mask.bit_count()
        if cnt == 0:
            continue
        weight = 100 - cnt
        ratio = target / cnt
        m = mask
        while m:
            lsb = m & -m
            i = lsb.bit_length() - 1
            score[i] += weight
            support[i] += 1
            mine_bias_num[i] += ratio
            mine_bias_den[i] += 1
            m ^= lsb

    best = None
    best_key = None
    for i in range(num_vars):
        if assign[i] != -1:
            continue
        if support[i] == 0:
            continue
        avg_ratio = mine_bias_num[i] / mine_bias_den[i]
        key = (support[i], score[i], avg_ratio, -i)
        if best_key is None or key > best_key:
            best_key = key
            best = i
    return best


def _solve_component(num_vars, constraints):
    memo = {}

    def search(assign):
        prop = _propagate(num_vars, constraints, assign)
        if prop is None:
            return None

        cur_assign, reduced = prop

        ones = 0
        zeros = 0
        for i, v in enumerate(cur_assign):
            if v == 1:
                ones |= 1 << i
            elif v == 0:
                zeros |= 1 << i
        key = (ones, zeros)
        if key in memo:
            return memo[key]

        if all(v != -1 for v in cur_assign):
            memo[key] = cur_assign
            return cur_assign

        groups = _split_groups(num_vars, reduced, cur_assign)
        if groups:
            merged = cur_assign[:]
            for gvars, gcons in groups:
                sub_sol = _solve_component(len(gvars), gcons)
                if sub_sol is None:
                    memo[key] = None
                    return None
                for local_i, gv in enumerate(gvars):
                    merged[gv] = sub_sol[local_i]
            # Re-run through search to absorb any now-forced unconstrained cells cleanly.
            result = search(merged)
            memo[key] = result
            return result

        var = _choose_branch_var(num_vars, reduced, cur_assign)
        if var is None:
            # Remaining cells are unconstrained.
            final = cur_assign[:]
            for i in range(num_vars):
                if final[i] == -1:
                    final[i] = 0
            memo[key] = final
            return final

        # Prefer the value more suggested by local clue ratios.
        numer = 0.0
        denom = 0
        for mask, target in reduced:
            if (mask >> var) & 1:
                cnt = mask.bit_count()
                numer += target / cnt
                denom += 1
        prefer_mine = denom > 0 and (numer / denom) >= 0.5
        order = (1, 0) if prefer_mine else (0, 1)

        for val in order:
            nxt = cur_assign[:]
            nxt[var] = val
            res = search(nxt)
            if res is not None:
                memo[key] = res
                return res

        memo[key] = None
        return None

    return search([-1] * num_vars)


def _verify(data, answer):
    h = len(data)
    w = len(data[0]) if h else 0

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if nr < 0 or nr >= h:
                continue
            for dc in (-1, 0, 1):
                nc = c + dc
                if dr == 0 and dc == 0:
                    continue
                if 0 <= nc < w:
                    yield nr, nc

    for r in range(h):
        for c in range(w):
            if data[r][c] is not None and answer[r][c] == 'F':
                return False

    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            cnt = 0
            for nr, nc in neighbors(r, c):
                if answer[nr][nc] == 'F':
                    cnt += 1
            if cnt != clue:
                return False
    return True


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [1, 22, 12, 12, 27, 11, 34, 16, 27], 'col_sum': [43, 27, 35, 10, 10, 26, 14, 39, 9]}

# Weighted black-cell puzzle solver.
# General model:
# - Each row chooses a subset of columns whose column-weights sum to the row target.
# - Each column chooses a subset of rows whose row-weights sum to the column target.
# - A cell is black iff both the row-pattern and the column-pattern say it is black.
#
# The solver works like a human line-based deduction engine:
# 1) Enumerate all valid patterns for every row and column.
# 2) Repeatedly remove row patterns that are incompatible with every remaining column pattern, and vice versa.
# 3) If deduction stalls, branch on the most constrained line (smallest remaining domain), then propagate again.
#
# No external solvers are used.

def solve(observation):
    row_sum = list(observation["row_sum"])
    col_sum = list(observation["col_sum"])

    m = len(row_sum)
    n = len(col_sum)

    row_weight = list(observation.get("row_weight", list(range(1, m + 1))))
    col_weight = list(observation.get("col_weight", list(range(1, n + 1))))

    if len(row_weight) != m or len(col_weight) != n:
        return "No Solution"

    # Necessary weighted consistency:
    # sum_r row_weight[r] * row_sum[r] == sum_c col_weight[c] * col_sum[c]
    lhs = sum(row_weight[r] * row_sum[r] for r in range(m))
    rhs = sum(col_weight[c] * col_sum[c] for c in range(n))
    if lhs != rhs:
        return "No Solution"

    total_row_capacity = sum(col_weight)
    total_col_capacity = sum(row_weight)

    for t in row_sum:
        if t < 0 or t > total_row_capacity:
            return "No Solution"
    for t in col_sum:
        if t < 0 or t > total_col_capacity:
            return "No Solution"

    def subsets_by_sum(weights):
        # Enumerate all subset masks, grouped by achieved sum.
        k = len(weights)
        total = sum(weights)
        out = [[] for _ in range(total + 1)]

        def dfs(i, acc, mask):
            if i == k:
                out[acc].append(mask)
                return
            dfs(i + 1, acc, mask)
            dfs(i + 1, acc + weights[i], mask | (1 << i))

        dfs(0, 0, 0)
        return out

    row_templates = subsets_by_sum(col_weight)  # masks over columns
    col_templates = subsets_by_sum(row_weight)  # masks over rows

    row_masks = []
    row_support = []  # row_support[r][c][bit] -> bitset of candidate indices
    row_full = []

    for target in row_sum:
        if target > sum(col_weight):
            return "No Solution"
        masks = list(row_templates[target])
        if not masks:
            return "No Solution"
        row_masks.append(masks)
        full = (1 << len(masks)) - 1
        row_full.append(full)
        supports = []
        for c in range(n):
            ones = 0
            for i, mask in enumerate(masks):
                if (mask >> c) & 1:
                    ones |= 1 << i
            zeros = full ^ ones
            supports.append((zeros, ones))
        row_support.append(supports)

    col_masks = []
    col_support = []  # col_support[c][r][bit] -> bitset of candidate indices
    col_full = []

    for target in col_sum:
        if target > sum(row_weight):
            return "No Solution"
        masks = list(col_templates[target])
        if not masks:
            return "No Solution"
        col_masks.append(masks)
        full = (1 << len(masks)) - 1
        col_full.append(full)
        supports = []
        for r in range(m):
            ones = 0
            for i, mask in enumerate(masks):
                if (mask >> r) & 1:
                    ones |= 1 << i
            zeros = full ^ ones
            supports.append((zeros, ones))
        col_support.append(supports)

    def iter_bits(bitset):
        while bitset:
            lsb = bitset & -bitset
            yield lsb.bit_length() - 1
            bitset ^= lsb

    def singleton_index(bitset):
        return bitset.bit_length() - 1

    def propagate(row_dom, col_dom):
        # Arc-consistency between row-variables and column-variables.
        changed = True
        while changed:
            changed = False

            # Prune row domains using current column domains.
            for r in range(m):
                dom = row_dom[r]
                if dom == 0:
                    return False

                invalid = 0
                for c in range(n):
                    col_has_0 = (col_dom[c] & col_support[c][r][0]) != 0
                    col_has_1 = (col_dom[c] & col_support[c][r][1]) != 0

                    if not col_has_0 and not col_has_1:
                        return False
                    if not col_has_0:
                        invalid |= row_support[r][c][0]
                    if not col_has_1:
                        invalid |= row_support[r][c][1]

                new_dom = dom & ~invalid
                if new_dom != dom:
                    if new_dom == 0:
                        return False
                    row_dom[r] = new_dom
                    changed = True

            # Prune column domains using current row domains.
            for c in range(n):
                dom = col_dom[c]
                if dom == 0:
                    return False

                invalid = 0
                for r in range(m):
                    row_has_0 = (row_dom[r] & row_support[r][c][0]) != 0
                    row_has_1 = (row_dom[r] & row_support[r][c][1]) != 0

                    if not row_has_0 and not row_has_1:
                        return False
                    if not row_has_0:
                        invalid |= col_support[c][r][0]
                    if not row_has_1:
                        invalid |= col_support[c][r][1]

                new_dom = dom & ~invalid
                if new_dom != dom:
                    if new_dom == 0:
                        return False
                    col_dom[c] = new_dom
                    changed = True

        return True

    def solved(row_dom, col_dom):
        return all(d.bit_count() == 1 for d in row_dom) and all(d.bit_count() == 1 for d in col_dom)

    def choose_branch_variable(row_dom, col_dom):
        # Most constrained line first.
        best_kind = None
        best_idx = -1
        best_size = 10**9

        for r in range(m):
            size = row_dom[r].bit_count()
            if 1 < size < best_size:
                best_size = size
                best_kind = "row"
                best_idx = r

        for c in range(n):
            size = col_dom[c].bit_count()
            if 1 < size < best_size:
                best_size = size
                best_kind = "col"
                best_idx = c

        return best_kind, best_idx

    def ordered_candidates(kind, idx, row_dom, col_dom):
        # Least-supporting candidate first: usually causes stronger pruning.
        scored = []

        if kind == "row":
            dom = row_dom[idx]
            for cand_idx in iter_bits(dom):
                mask = row_masks[idx][cand_idx]
                score = 0
                for c in range(n):
                    bit = (mask >> c) & 1
                    score += (col_dom[c] & col_support[c][idx][bit]).bit_count()
                scored.append((score, cand_idx))
        else:
            dom = col_dom[idx]
            for cand_idx in iter_bits(dom):
                mask = col_masks[idx][cand_idx]
                score = 0
                for r in range(m):
                    bit = (mask >> r) & 1
                    score += (row_dom[r] & row_support[r][idx][bit]).bit_count()
                scored.append((score, cand_idx))

        scored.sort()
        return [cand_idx for _, cand_idx in scored]

    fail_cache = set()

    def search(row_dom, col_dom):
        if not propagate(row_dom, col_dom):
            return None

        state = tuple(row_dom + col_dom)
        if state in fail_cache:
            return None

        if solved(row_dom, col_dom):
            return row_dom, col_dom

        kind, idx = choose_branch_variable(row_dom, col_dom)
        if kind is None:
            # Should already be solved, but keep safe.
            return row_dom, col_dom

        for cand_idx in ordered_candidates(kind, idx, row_dom, col_dom):
            new_row_dom = row_dom[:]
            new_col_dom = col_dom[:]

            if kind == "row":
                new_row_dom[idx] = 1 << cand_idx
            else:
                new_col_dom[idx] = 1 << cand_idx

            result = search(new_row_dom, new_col_dom)
            if result is not None:
                return result

        fail_cache.add(state)
        return None

    row_dom0 = row_full[:]
    col_dom0 = col_full[:]

    result = search(row_dom0, col_dom0)
    if result is None:
        return "No Solution"

    row_dom, col_dom = result

    # Build answer from singleton row patterns.
    grid = []
    for r in range(m):
        if row_dom[r].bit_count() != 1:
            return "No Solution"
        ridx = singleton_index(row_dom[r])
        mask = row_masks[r][ridx]
        grid.append(['B' if ((mask >> c) & 1) else None for c in range(n)])

    # Final verification.
    for r in range(m):
        s = sum(col_weight[c] for c in range(n) if grid[r][c] == 'B')
        if s != row_sum[r]:
            return "No Solution"

    for c in range(n):
        s = sum(row_weight[r] for r in range(m) if grid[r][c] == 'B')
        if s != col_sum[c]:
            return "No Solution"

    return repr(grid)


