OBSERVATION = {'row_sum': [9, 8, 18, 5, 5, 10, 15, 5, 25], 'col_sum': [13, 18, 8, 19, 20, 16, 1, 14, 10]}

from functools import lru_cache


def make_subset_enumerator(weights):
    weights = tuple(weights)
    n = len(weights)
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]

    @lru_cache(maxsize=None)
    def rec(i, rem):
        if rem < 0 or rem > suffix[i]:
            return ()
        if i == n:
            return (0,) if rem == 0 else ()

        out = list(rec(i + 1, rem))
        w = weights[i]
        if rem >= w:
            bit = 1 << i
            out.extend(mask | bit for mask in rec(i + 1, rem - w))
        return tuple(out)

    return rec


def summarize_domains(domains):
    any_bits = [0] * len(domains)
    all_bits = [0] * len(domains)
    for i, dom in enumerate(domains):
        first = dom[0]
        a = first
        u = first
        for mask in dom[1:]:
            a &= mask
            u |= mask
        any_bits[i] = u
        all_bits[i] = a
    return any_bits, all_bits


def propagate(row_domains, col_domains, n_rows, n_cols):
    full_row_mask = (1 << n_rows) - 1
    full_col_mask = (1 << n_cols) - 1

    row_domains = list(row_domains)
    col_domains = list(col_domains)

    while True:
        changed = False

        # Columns -> Rows
        col_any, col_all = summarize_domains(col_domains)
        row_must1 = [0] * n_rows
        row_must0 = [0] * n_rows

        for c in range(n_cols):
            col_bit = 1 << c

            mask = col_all[c]
            while mask:
                lsb = mask & -mask
                r = lsb.bit_length() - 1
                row_must1[r] |= col_bit
                mask ^= lsb

            mask = full_row_mask & ~col_any[c]
            while mask:
                lsb = mask & -mask
                r = lsb.bit_length() - 1
                row_must0[r] |= col_bit
                mask ^= lsb

        for r in range(n_rows):
            must1 = row_must1[r]
            must0 = row_must0[r]
            if must1 & must0:
                return None

            dom = row_domains[r]
            new_dom = tuple(mask for mask in dom if (mask & must1) == must1 and (mask & must0) == 0)
            if not new_dom:
                return None
            if len(new_dom) != len(dom):
                row_domains[r] = new_dom
                changed = True

        # Rows -> Columns
        row_any, row_all = summarize_domains(row_domains)
        col_must1 = [0] * n_cols
        col_must0 = [0] * n_cols

        for r in range(n_rows):
            row_bit = 1 << r

            mask = row_all[r]
            while mask:
                lsb = mask & -mask
                c = lsb.bit_length() - 1
                col_must1[c] |= row_bit
                mask ^= lsb

            mask = full_col_mask & ~row_any[r]
            while mask:
                lsb = mask & -mask
                c = lsb.bit_length() - 1
                col_must0[c] |= row_bit
                mask ^= lsb

        for c in range(n_cols):
            must1 = col_must1[c]
            must0 = col_must0[c]
            if must1 & must0:
                return None

            dom = col_domains[c]
            new_dom = tuple(mask for mask in dom if (mask & must1) == must1 and (mask & must0) == 0)
            if not new_dom:
                return None
            if len(new_dom) != len(dom):
                col_domains[c] = new_dom
                changed = True

        if not changed:
            return tuple(row_domains), tuple(col_domains)


def choose_branch(row_domains, col_domains):
    best = None

    for r, dom in enumerate(row_domains):
        if len(dom) > 1:
            key = (len(dom), 0, r)
            if best is None or key < best[0]:
                best = (key, "row", r)

    for c, dom in enumerate(col_domains):
        if len(dom) > 1:
            key = (len(dom), 1, c)
            if best is None or key < best[0]:
                best = (key, "col", c)

    return None if best is None else (best[1], best[2])


def build_grid(row_domains, n_rows, n_cols):
    grid = []
    for r in range(n_rows):
        mask = row_domains[r][0]
        row = []
        for c in range(n_cols):
            row.append('B' if (mask >> c) & 1 else None)
        grid.append(row)
    return grid


def validate(grid, row_weights, col_weights, row_sum, col_sum):
    n_rows = len(grid)
    n_cols = len(grid[0]) if n_rows else 0

    for r in range(n_rows):
        s = 0
        for c in range(n_cols):
            if grid[r][c] == 'B':
                s += col_weights[c]
        if s != row_sum[r]:
            return False

    for c in range(n_cols):
        s = 0
        for r in range(n_rows):
            if grid[r][c] == 'B':
                s += row_weights[r]
        if s != col_sum[c]:
            return False

    return True


def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]
    n_rows = len(row_sum)
    n_cols = len(col_sum)

    row_weights = observation.get("row_weight", list(range(1, n_rows + 1)))
    col_weights = observation.get("col_weight", list(range(1, n_cols + 1)))

    if len(row_weights) != n_rows or len(col_weights) != n_cols:
        return "No Solution"

    max_row_sum = sum(col_weights)
    max_col_sum = sum(row_weights)
    if any(s < 0 or s > max_row_sum for s in row_sum):
        return "No Solution"
    if any(s < 0 or s > max_col_sum for s in col_sum):
        return "No Solution"

    row_enum = make_subset_enumerator(col_weights)
    col_enum = make_subset_enumerator(row_weights)

    row_domains = []
    for s in row_sum:
        dom = row_enum(0, s)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for s in col_sum:
        dom = col_enum(0, s)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    state = propagate(tuple(row_domains), tuple(col_domains), n_rows, n_cols)
    if state is None:
        return "No Solution"

    failed = set()

    def search(row_domains, col_domains):
        key = (row_domains, col_domains)
        if key in failed:
            return None

        branch = choose_branch(row_domains, col_domains)
        if branch is None:
            grid = build_grid(row_domains, n_rows, n_cols)
            if validate(grid, row_weights, col_weights, row_sum, col_sum):
                return grid
            failed.add(key)
            return None

        kind, idx = branch

        if kind == "row":
            for mask in row_domains[idx]:
                new_row_domains = list(row_domains)
                new_row_domains[idx] = (mask,)
                nxt = propagate(tuple(new_row_domains), col_domains, n_rows, n_cols)
                if nxt is None:
                    continue
                ans = search(*nxt)
                if ans is not None:
                    return ans
        else:
            for mask in col_domains[idx]:
                new_col_domains = list(col_domains)
                new_col_domains[idx] = (mask,)
                nxt = propagate(row_domains, tuple(new_col_domains), n_rows, n_cols)
                if nxt is None:
                    continue
                ans = search(*nxt)
                if ans is not None:
                    return ans

        failed.add(key)
        return None

    result = search(*state)
    if result is None:
        return "No Solution"
    return repr(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [0, 5, 0, 0, 3], 'D': [2, 0, 4, 0, 0], 'L': [0, 4, 0, 0, 0], 'R': [3, 0, 0, 0, 3]}

import itertools
from functools import lru_cache


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    if not (len(D) == len(L) == len(R) == N):
        return "No Solution"

    bits = [0] + [1 << (v - 1) for v in range(1, N + 1)]
    full_mask = (1 << N) - 1
    single_masks = bits[1:]

    def is_singleton(mask):
        return mask and (mask & (mask - 1)) == 0

    def mask_to_value(mask):
        return mask.bit_length()

    def visible_count(seq):
        m = 0
        seen = 0
        for x in seq:
            if x > m:
                m = x
                seen += 1
        return seen

    @lru_cache(None)
    def precompute(n):
        nums = tuple(range(1, n + 1))
        perms = []
        exact = {}
        left_map = {i: [] for i in range(1, n + 1)}
        right_map = {i: [] for i in range(1, n + 1)}
        for p in itertools.permutations(nums):
            lv = visible_count(p)
            rv = visible_count(reversed(p))
            perms.append(p)
            exact.setdefault((lv, rv), []).append(p)
            left_map[lv].append(p)
            right_map[rv].append(p)
        return perms, exact, left_map, right_map

    perms, exact_map, left_map, right_map = precompute(N)

    def initial_line_candidates(a, b):
        if a and b:
            return list(exact_map.get((a, b), ()))
        if a:
            return list(left_map.get(a, ()))
        if b:
            return list(right_map.get(b, ()))
        return list(perms)

    domains = [[full_mask for _ in range(N)] for _ in range(N)]
    row_cands = [initial_line_candidates(L[r], R[r]) for r in range(N)]
    col_cands = [initial_line_candidates(U[c], D[c]) for c in range(N)]

    if any(not c for c in row_cands) or any(not c for c in col_cands):
        return "No Solution"

    def apply_mask(r, c, mask):
        new_mask = domains[r][c] & mask
        if new_mask == 0:
            return False
        domains[r][c] = new_mask
        return True

    # Direct clue-to-domain deductions.
    def apply_edge(indices, clue):
        if clue == 0:
            return True
        if clue == 1:
            r, c = indices[0]
            return apply_mask(r, c, bits[N])
        if clue == N:
            for i, (r, c) in enumerate(indices):
                if not apply_mask(r, c, bits[i + 1]):
                    return False
            return True
        for i, (r, c) in enumerate(indices):
            max_h = N - clue + 1 + i
            if max_h < N:
                if not apply_mask(r, c, (1 << max_h) - 1):
                    return False
        return True

    for r in range(N):
        if not apply_edge([(r, c) for c in range(N)], L[r]):
            return "No Solution"
        if not apply_edge([(r, c) for c in range(N - 1, -1, -1)], R[r]):
            return "No Solution"
    for c in range(N):
        if not apply_edge([(r, c) for r in range(N)], U[c]):
            return "No Solution"
        if not apply_edge([(r, c) for r in range(N - 1, -1, -1)], D[c]):
            return "No Solution"

    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]

    def copy_state(domains, row_cands, col_cands):
        return [row[:] for row in domains], [lst[:] for lst in row_cands], [lst[:] for lst in col_cands]

    def line_peer_elimination(cells, domains):
        changed = False
        seen = 0
        for r, c in cells:
            m = domains[r][c]
            if is_singleton(m):
                if seen & m:
                    return False, changed
                seen |= m
        for r, c in cells:
            m = domains[r][c]
            if not is_singleton(m):
                nm = m & ~seen
                if nm == 0:
                    return False, changed
                if nm != m:
                    domains[r][c] = nm
                    changed = True
        return True, changed

    def line_hidden_singles(cells, domains):
        changed = False
        for vmask in single_masks:
            found = None
            count = 0
            for r, c in cells:
                if domains[r][c] & vmask:
                    found = (r, c)
                    count += 1
                    if count > 1:
                        break
            if count == 0:
                return False, changed
            if count == 1:
                r, c = found
                if domains[r][c] != vmask:
                    domains[r][c] = vmask
                    changed = True
        return True, changed

    def line_identical_subset_elimination(cells, domains):
        changed = False
        groups = {}
        for idx, (r, c) in enumerate(cells):
            m = domains[r][c]
            if not is_singleton(m):
                groups.setdefault(m, []).append(idx)
        for m, idxs in groups.items():
            k = m.bit_count()
            if k > 1 and len(idxs) == k:
                for idx, (r, c) in enumerate(cells):
                    if idx not in idxs:
                        nm = domains[r][c] & ~m
                        if nm == 0:
                            return False, changed
                        if nm != domains[r][c]:
                            domains[r][c] = nm
                            changed = True
        return True, changed

    def filter_row_candidates(r, domains, row_cands):
        old = row_cands[r]
        new = []
        supports = [0] * N
        for p in old:
            ok = True
            for c, v in enumerate(p):
                if not (domains[r][c] & bits[v]):
                    ok = False
                    break
            if ok:
                new.append(p)
                for c, v in enumerate(p):
                    supports[c] |= bits[v]
        if not new:
            return False, False
        changed = len(new) != len(old)
        row_cands[r] = new
        for c in range(N):
            nm = domains[r][c] & supports[c]
            if nm == 0:
                return False, False
            if nm != domains[r][c]:
                domains[r][c] = nm
                changed = True
        if len(new) == 1:
            p = new[0]
            for c, v in enumerate(p):
                if domains[r][c] != bits[v]:
                    domains[r][c] = bits[v]
                    changed = True
        return True, changed

    def filter_col_candidates(c, domains, col_cands):
        old = col_cands[c]
        new = []
        supports = [0] * N
        for p in old:
            ok = True
            for r, v in enumerate(p):
                if not (domains[r][c] & bits[v]):
                    ok = False
                    break
            if ok:
                new.append(p)
                for r, v in enumerate(p):
                    supports[r] |= bits[v]
        if not new:
            return False, False
        changed = len(new) != len(old)
        col_cands[c] = new
        for r in range(N):
            nm = domains[r][c] & supports[r]
            if nm == 0:
                return False, False
            if nm != domains[r][c]:
                domains[r][c] = nm
                changed = True
        if len(new) == 1:
            p = new[0]
            for r, v in enumerate(p):
                if domains[r][c] != bits[v]:
                    domains[r][c] = bits[v]
                    changed = True
        return True, changed

    def propagate(domains, row_cands, col_cands):
        changed = True
        while changed:
            changed = False

            for r in range(N):
                ok, ch = filter_row_candidates(r, domains, row_cands)
                if not ok:
                    return False
                changed |= ch

            for c in range(N):
                ok, ch = filter_col_candidates(c, domains, col_cands)
                if not ok:
                    return False
                changed |= ch

            for r in range(N):
                ok, ch = line_peer_elimination(row_cells[r], domains)
                if not ok:
                    return False
                changed |= ch
                ok, ch = line_hidden_singles(row_cells[r], domains)
                if not ok:
                    return False
                changed |= ch
                ok, ch = line_identical_subset_elimination(row_cells[r], domains)
                if not ok:
                    return False
                changed |= ch

            for c in range(N):
                ok, ch = line_peer_elimination(col_cells[c], domains)
                if not ok:
                    return False
                changed |= ch
                ok, ch = line_hidden_singles(col_cells[c], domains)
                if not ok:
                    return False
                changed |= ch
                ok, ch = line_identical_subset_elimination(col_cells[c], domains)
                if not ok:
                    return False
                changed |= ch

            for r in range(N):
                for c in range(N):
                    if domains[r][c] == 0:
                        return False

        return True

    def is_solved(domains):
        for r in range(N):
            for c in range(N):
                if not is_singleton(domains[r][c]):
                    return False
        return True

    def domains_to_grid(domains):
        return [[mask_to_value(domains[r][c]) for c in range(N)] for r in range(N)]

    def verify(grid):
        need = set(range(1, N + 1))
        for r in range(N):
            row = grid[r]
            if set(row) != need:
                return False
            if L[r] and visible_count(row) != L[r]:
                return False
            if R[r] and visible_count(reversed(row)) != R[r]:
                return False
        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if set(col) != need:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(reversed(col)) != D[c]:
                return False
        return True

    def choose_branch(domains, row_cands, col_cands):
        best = None

        for r in range(N):
            k = len(row_cands[r])
            if 1 < k and (best is None or k < best[0] or (k == best[0] and best[1] == 'cell')):
                best = (k, 'row', r)

        for c in range(N):
            k = len(col_cands[c])
            if 1 < k and (best is None or k < best[0] or (k == best[0] and best[1] == 'cell')):
                best = (k, 'col', c)

        for r in range(N):
            for c in range(N):
                k = domains[r][c].bit_count()
                if 1 < k and (best is None or k < best[0]):
                    best = (k, 'cell', (r, c))

        return best

    def search(domains, row_cands, col_cands):
        if not propagate(domains, row_cands, col_cands):
            return None

        if is_solved(domains):
            grid = domains_to_grid(domains)
            return grid if verify(grid) else None

        choice = choose_branch(domains, row_cands, col_cands)
        if choice is None:
            return None

        _, kind, payload = choice

        if kind == 'row':
            r = payload
            options = row_cands[r]
            for p in options:
                nd, nr, nc = copy_state(domains, row_cands, col_cands)
                nr[r] = [p]
                for c, v in enumerate(p):
                    nd[r][c] = bits[v]
                res = search(nd, nr, nc)
                if res is not None:
                    return res
            return None

        if kind == 'col':
            c = payload
            options = col_cands[c]
            for p in options:
                nd, nr, nc = copy_state(domains, row_cands, col_cands)
                nc[c] = [p]
                for r, v in enumerate(p):
                    nd[r][c] = bits[v]
                res = search(nd, nr, nc)
                if res is not None:
                    return res
            return None

        r, c = payload
        mask = domains[r][c]
        while mask:
            lsb = mask & -mask
            mask ^= lsb
            nd, nr, nc = copy_state(domains, row_cands, col_cands)
            nd[r][c] = lsb
            res = search(nd, nr, nc)
            if res is not None:
                return res
        return None

    result = search(domains, row_cands, col_cands)
    return result if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

