from itertools import combinations


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    def parse_coord(s):
        s = s.strip()
        if not (s.startswith('(') and s.endswith(')')):
            raise ValueError("Bad coordinate")
        a, b = s[1:-1].split(',')
        return float(a.strip()), float(b.strip())

    def build_constraints(horizontal_left_less=True, vertical_caret_top_less=True):
        constraints = []

        # Horizontal: relation between (r,c) and (r,c+1)
        for key, sym in observation.get('horizontal', {}).items():
            r_f, c_f = parse_coord(key)
            r = int(round(r_f))
            c = int(round(c_f - 0.5))
            if not (0 <= r < n and 0 <= c < n - 1):
                return None
            a = r * n + c
            b = r * n + (c + 1)

            if sym == '<':
                left_less_right = horizontal_left_less
            elif sym == '>':
                left_less_right = not horizontal_left_less
            else:
                return None

            # rel = -1 means a < b, +1 means a > b
            rel = -1 if left_less_right else 1
            constraints.append((a, b, rel))

        # Vertical: relation between (r,c) and (r+1,c)
        for key, sym in observation.get('vertical', {}).items():
            r_f, c_f = parse_coord(key)
            r = int(round(r_f - 0.5))
            c = int(round(c_f))
            if not (0 <= r < n - 1 and 0 <= c < n):
                return None
            a = r * n + c
            b = (r + 1) * n + c

            if sym == '^':
                top_less_bottom = vertical_caret_top_less
            elif sym == 'v':
                top_less_bottom = not vertical_caret_top_less
            else:
                return None

            rel = -1 if top_less_bottom else 1
            constraints.append((a, b, rel))

        return constraints

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def mask_values(mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask ^= bit

    def to_value(single_mask):
        return single_mask.bit_length()

    all_mask = (1 << n) - 1
    cell_count = n * n
    units = []
    row_units = []
    col_units = []

    for r in range(n):
        unit = [r * n + c for c in range(n)]
        row_units.append(unit)
        units.append(unit)
    for c in range(n):
        unit = [r * n + c for r in range(n)]
        col_units.append(unit)
        units.append(unit)

    peers = []
    for idx in range(cell_count):
        r, c = divmod(idx, n)
        s = set(row_units[r])
        s.update(col_units[c])
        s.remove(idx)
        peers.append(tuple(s))

    def validate_grid(grid, constraints):
        target = list(range(1, n + 1))
        for r in range(n):
            if sorted(grid[r]) != target:
                return False
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if sorted(col) != target:
                return False
        for a, b, rel in constraints:
            ra, ca = divmod(a, n)
            rb, cb = divmod(b, n)
            va = grid[ra][ca]
            vb = grid[rb][cb]
            if rel == -1 and not (va < vb):
                return False
            if rel == 1 and not (va > vb):
                return False
        return True

    def solve_with_constraints(constraints):
        if constraints is None:
            return None

        ineq_degree = [0] * cell_count
        for a, b, _ in constraints:
            ineq_degree[a] += 1
            ineq_degree[b] += 1

        dom = [all_mask] * cell_count
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    dom[r * n + c] = 1 << (v - 1)

        dead = set()

        def push_if_single(queue, queued, idx):
            if is_single(dom_work[idx]) and not queued[idx]:
                queue.append(idx)
                queued[idx] = True

        def prune_inequality(da, db, rel):
            if rel == -1:
                max_b = db.bit_length()
                min_a = (da & -da).bit_length()
                new_da = da & (((1 << (max_b - 1)) - 1) if max_b > 1 else 0)
                new_db = db & (all_mask & ~((1 << min_a) - 1))
            else:
                min_b = (db & -db).bit_length()
                max_a = da.bit_length()
                new_da = da & (all_mask & ~((1 << min_b) - 1))
                new_db = db & (((1 << (max_a - 1)) - 1) if max_a > 1 else 0)
            return new_da, new_db

        def propagate(dom_start):
            nonlocal dom_work
            dom_work = dom_start
            queue = []
            queued = [False] * cell_count

            for idx in range(cell_count):
                if dom_work[idx] == 0:
                    return None
                if is_single(dom_work[idx]):
                    queue.append(idx)
                    queued[idx] = True

            changed = True
            while changed:
                changed = False

                # Basic singleton propagation through row/column peers.
                while queue:
                    idx = queue.pop()
                    queued[idx] = False
                    valmask = dom_work[idx]
                    if not is_single(valmask):
                        continue
                    for j in peers[idx]:
                        if dom_work[j] & valmask:
                            new_mask = dom_work[j] & ~valmask
                            if new_mask == 0:
                                return None
                            if new_mask != dom_work[j]:
                                dom_work[j] = new_mask
                                changed = True
                                if is_single(new_mask) and not queued[j]:
                                    queue.append(j)
                                    queued[j] = True

                # Inequality pruning.
                for a, b, rel in constraints:
                    da = dom_work[a]
                    db = dom_work[b]
                    nda, ndb = prune_inequality(da, db, rel)
                    if nda == 0 or ndb == 0:
                        return None
                    if nda != da:
                        dom_work[a] = nda
                        changed = True
                        if is_single(nda) and not queued[a]:
                            queue.append(a)
                            queued[a] = True
                    if ndb != db:
                        dom_work[b] = ndb
                        changed = True
                        if is_single(ndb) and not queued[b]:
                            queue.append(b)
                            queued[b] = True

                # Hidden singles + impossible-value checks in each unit.
                for unit in units:
                    counts = [0] * n
                    last_pos = [-1] * n
                    for idx in unit:
                        m = dom_work[idx]
                        if m == 0:
                            return None
                        mm = m
                        while mm:
                            bit = mm & -mm
                            v = bit.bit_length() - 1
                            counts[v] += 1
                            last_pos[v] = idx
                            mm ^= bit

                    for v in range(n):
                        if counts[v] == 0:
                            return None
                        if counts[v] == 1:
                            idx = last_pos[v]
                            bit = 1 << v
                            if dom_work[idx] != bit:
                                dom_work[idx] = bit
                                changed = True
                                if not queued[idx]:
                                    queue.append(idx)
                                    queued[idx] = True

                # Naked identical tuples and small naked subsets.
                for unit in units:
                    # Identical-domain Hall checks.
                    groups = {}
                    for idx in unit:
                        m = dom_work[idx]
                        pc = m.bit_count()
                        if 1 < pc < n:
                            groups.setdefault(m, []).append(idx)

                    for m, cells in groups.items():
                        k = len(cells)
                        pc = m.bit_count()
                        if k > pc:
                            return None
                        if k == pc:
                            cellset = set(cells)
                            for idx in unit:
                                if idx not in cellset and (dom_work[idx] & m):
                                    new_mask = dom_work[idx] & ~m
                                    if new_mask == 0:
                                        return None
                                    if new_mask != dom_work[idx]:
                                        dom_work[idx] = new_mask
                                        changed = True
                                        if is_single(new_mask) and not queued[idx]:
                                            queue.append(idx)
                                            queued[idx] = True

                    # Generic naked pairs/triples/quads.
                    cand = [idx for idx in unit if 1 < dom_work[idx].bit_count() <= 4]
                    max_k = min(4, len(cand))
                    for k in range(2, max_k + 1):
                        for combo in combinations(cand, k):
                            union = 0
                            for idx in combo:
                                union |= dom_work[idx]
                            pc = union.bit_count()
                            if pc < k:
                                return None
                            if pc == k:
                                combo_set = set(combo)
                                for idx in unit:
                                    if idx not in combo_set and (dom_work[idx] & union):
                                        new_mask = dom_work[idx] & ~union
                                        if new_mask == 0:
                                            return None
                                        if new_mask != dom_work[idx]:
                                            dom_work[idx] = new_mask
                                            changed = True
                                            if is_single(new_mask) and not queued[idx]:
                                                queue.append(idx)
                                                queued[idx] = True

                # If new singles were created late in the loop, process them now.
                while queue:
                    idx = queue.pop()
                    queued[idx] = False
                    valmask = dom_work[idx]
                    if not is_single(valmask):
                        continue
                    for j in peers[idx]:
                        if dom_work[j] & valmask:
                            new_mask = dom_work[j] & ~valmask
                            if new_mask == 0:
                                return None
                            if new_mask != dom_work[j]:
                                dom_work[j] = new_mask
                                changed = True
                                if is_single(new_mask) and not queued[j]:
                                    queue.append(j)
                                    queued[j] = True

            return dom_work

        def choose_branch_cell(dom_cur):
            best_idx = -1
            best_key = None
            for idx, m in enumerate(dom_cur):
                pc = m.bit_count()
                if pc > 1:
                    r, c = divmod(idx, n)
                    row_uncert = sum(1 for j in row_units[r] if not is_single(dom_cur[j]))
                    col_uncert = sum(1 for j in col_units[c] if not is_single(dom_cur[j]))
                    key = (pc, -(ineq_degree[idx] + row_uncert + col_uncert), idx)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_idx = idx
            return best_idx

        def order_values(dom_cur, idx):
            r, c = divmod(idx, n)
            options = []
            for bit in mask_values(dom_cur[idx]):
                score = 0
                for j in peers[idx]:
                    if dom_cur[j] & bit:
                        score += 1
                # Prefer values that better fit inequalities incident to the cell.
                v = to_value(bit)
                for a, b, rel in constraints:
                    if a == idx:
                        other = dom_cur[b]
                        if rel == -1:
                            score += sum(1 for ob in mask_values(other) if v >= to_value(ob))
                        else:
                            score += sum(1 for ob in mask_values(other) if v <= to_value(ob))
                    elif b == idx:
                        other = dom_cur[a]
                        if rel == -1:
                            score += sum(1 for ob in mask_values(other) if to_value(ob) >= v)
                        else:
                            score += sum(1 for ob in mask_values(other) if to_value(ob) <= v)
                options.append((score, v, bit))
            options.sort()
            return [bit for _, _, bit in options]

        def search(dom_cur):
            dom_cur = propagate(dom_cur)
            if dom_cur is None:
                return None

            key = tuple(dom_cur)
            if key in dead:
                return None

            if all(is_single(m) for m in dom_cur):
                grid = [[to_value(dom_cur[r * n + c]) for c in range(n)] for r in range(n)]
                if validate_grid(grid, constraints):
                    return grid
                dead.add(key)
                return None

            idx = choose_branch_cell(dom_cur)
            if idx < 0:
                dead.add(key)
                return None

            original = dom_cur[idx]
            for bit in order_values(dom_cur, idx):
                next_dom = dom_cur[:]
                next_dom[idx] = bit
                result = search(next_dom)
                if result is not None:
                    return result

            dead.add(key)
            dom_cur[idx] = original
            return None

        return search(dom[:])

    # Try all plausible symbol conventions to remain robust to source notation.
    convention_orders = [
        (True, True),
        (True, False),
        (False, True),
        (False, False),
    ]

    for horizontal_left_less, vertical_caret_top_less in convention_orders:
        constraints = build_constraints(horizontal_left_less, vertical_caret_top_less)
        result = solve_with_constraints(constraints)
        if result is not None:
            return str(result)

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 2, 4, 2, 3], 'D': [2, 2, 1, 4, 3], 'L': [1, 3, 3, 2, 2], 'R': [4, 2, 1, 3, 2]}

from itertools import permutations
from functools import lru_cache


def visible_count(seq):
    tallest = 0
    seen = 0
    for x in seq:
        if x > tallest:
            tallest = x
            seen += 1
    return seen


@lru_cache(maxsize=None)
def build_catalog(n):
    # Maps (left_clue_or_0, right_clue_or_0) -> all permutations matching those clues.
    catalog = {(l, r): [] for l in range(n + 1) for r in range(n + 1)}
    for p in permutations(range(1, n + 1)):
        lv = visible_count(p)
        rv = visible_count(reversed(p))
        for l in (0, lv):
            for r in (0, rv):
                catalog[(l, r)].append(p)
    return catalog


def is_singleton(mask):
    return mask != 0 and (mask & (mask - 1)) == 0


def mask_to_value(mask):
    # For masks of form 1<<(v-1), bit_length gives v.
    return mask.bit_length()


def iter_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit
        mask ^= bit


def position_masks(candidates, n):
    masks = [0] * n
    for p in candidates:
        for i, v in enumerate(p):
            masks[i] |= 1 << (v - 1)
    return masks


def enforce_latin(domains, n):
    # Standard human-style Latin deductions:
    # 1) Fixed values remove themselves from peers in the same row/col.
    # 2) Hidden singles: if a value can appear in only one position in a row/col, fix it there.
    changed = False
    value_bits = [1 << i for i in range(n)]

    # Rows
    for r in range(n):
        used = 0
        for c in range(n):
            d = domains[r][c]
            if d == 0:
                return False, changed
            if is_singleton(d):
                if used & d:
                    return False, changed
                used |= d

        if used:
            for c in range(n):
                d = domains[r][c]
                if not is_singleton(d):
                    nd = d & ~used
                    if nd == 0:
                        return False, changed
                    if nd != d:
                        domains[r][c] = nd
                        changed = True

        for bit in value_bits:
            spots = []
            for c in range(n):
                if domains[r][c] & bit:
                    spots.append(c)
            if not spots:
                return False, changed
            if len(spots) == 1:
                c = spots[0]
                if domains[r][c] != bit:
                    domains[r][c] = bit
                    changed = True

    # Columns
    for c in range(n):
        used = 0
        for r in range(n):
            d = domains[r][c]
            if d == 0:
                return False, changed
            if is_singleton(d):
                if used & d:
                    return False, changed
                used |= d

        if used:
            for r in range(n):
                d = domains[r][c]
                if not is_singleton(d):
                    nd = d & ~used
                    if nd == 0:
                        return False, changed
                    if nd != d:
                        domains[r][c] = nd
                        changed = True

        for bit in value_bits:
            spots = []
            for r in range(n):
                if domains[r][c] & bit:
                    spots.append(r)
            if not spots:
                return False, changed
            if len(spots) == 1:
                r = spots[0]
                if domains[r][c] != bit:
                    domains[r][c] = bit
                    changed = True

    return True, changed


def propagate(row_cands, col_cands, domains, n):
    while True:
        any_changed = False

        ok, changed = enforce_latin(domains, n)
        if not ok:
            return None
        any_changed |= changed

        # Candidate support masks
        row_masks = []
        for r in range(n):
            if not row_cands[r]:
                return None
            row_masks.append(position_masks(row_cands[r], n))

        col_masks = []
        for c in range(n):
            if not col_cands[c]:
                return None
            col_masks.append(position_masks(col_cands[c], n))

        # Intersect cell domains with row/column candidate support.
        for r in range(n):
            for c in range(n):
                nd = domains[r][c] & row_masks[r][c] & col_masks[c][r]
                if nd == 0:
                    return None
                if nd != domains[r][c]:
                    domains[r][c] = nd
                    any_changed = True

        ok, changed = enforce_latin(domains, n)
        if not ok:
            return None
        any_changed |= changed

        # Filter row candidates using cell domains and current column support.
        rows_changed = False
        for r in range(n):
            cross = [col_masks[c][r] for c in range(n)]
            old = row_cands[r]
            new = []
            for p in old:
                good = True
                for c, v in enumerate(p):
                    bit = 1 << (v - 1)
                    if not (domains[r][c] & bit):
                        good = False
                        break
                    if not (cross[c] & bit):
                        good = False
                        break
                if good:
                    new.append(p)
            if not new:
                return None
            if len(new) != len(old):
                row_cands[r] = new
                rows_changed = True

        # Recompute row masks after possible row filtering.
        row_masks = []
        for r in range(n):
            if not row_cands[r]:
                return None
            row_masks.append(position_masks(row_cands[r], n))

        # Filter column candidates using cell domains and current row support.
        cols_changed = False
        for c in range(n):
            cross = [row_masks[r][c] for r in range(n)]
            old = col_cands[c]
            new = []
            for p in old:
                good = True
                for r, v in enumerate(p):
                    bit = 1 << (v - 1)
                    if not (domains[r][c] & bit):
                        good = False
                        break
                    if not (cross[r] & bit):
                        good = False
                        break
                if good:
                    new.append(p)
            if not new:
                return None
            if len(new) != len(old):
                col_cands[c] = new
                cols_changed = True

        any_changed |= rows_changed or cols_changed

        if not any_changed:
            return row_cands, col_cands, domains


def clone_state(row_cands, col_cands, domains):
    return (
        [list(cands) for cands in row_cands],
        [list(cands) for cands in col_cands],
        [row[:] for row in domains],
    )


def grid_from_domains(domains, n):
    return [[mask_to_value(domains[r][c]) for c in range(n)] for r in range(n)]


def validate_grid(grid, observation):
    n = len(grid)
    target = set(range(1, n + 1))

    for r in range(n):
        if set(grid[r]) != target:
            return False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if set(col) != target:
            return False

    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]

    for r in range(n):
        if L[r] and visible_count(grid[r]) != L[r]:
            return False
        if R[r] and visible_count(reversed(grid[r])) != R[r]:
            return False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if U[c] and visible_count(col) != U[c]:
            return False
        if D[c] and visible_count(reversed(col)) != D[c]:
            return False

    return True


def choose_branch(row_cands, col_cands, domains, n):
    # Prefer smallest branching factor.
    # Tie-break toward row/column candidates over raw cell guesses because they preserve more structure.
    best = None
    best_key = None

    for r in range(n):
        k = len(row_cands[r])
        if 1 < k:
            key = (k, 0, r)
            if best_key is None or key < best_key:
                best_key = key
                best = ("row", r)

    for c in range(n):
        k = len(col_cands[c])
        if 1 < k:
            key = (k, 0, n + c)
            if best_key is None or key < best_key:
                best_key = key
                best = ("col", c)

    for r in range(n):
        for c in range(n):
            k = domains[r][c].bit_count()
            if 1 < k:
                key = (k, 1, r * n + c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = ("cell", r, c)

    return best


def search(row_cands, col_cands, domains, observation, n):
    state = propagate(row_cands, col_cands, domains, n)
    if state is None:
        return None

    row_cands, col_cands, domains = state

    solved = True
    for r in range(n):
        for c in range(n):
            if not is_singleton(domains[r][c]):
                solved = False
                break
        if not solved:
            break

    if solved:
        grid = grid_from_domains(domains, n)
        return grid if validate_grid(grid, observation) else None

    branch = choose_branch(row_cands, col_cands, domains, n)
    if branch is None:
        return None

    kind = branch[0]

    if kind == "row":
        r = branch[1]
        for p in row_cands[r]:
            nr, nc, nd = clone_state(row_cands, col_cands, domains)
            nr[r] = [p]
            for c, v in enumerate(p):
                nd[r][c] = 1 << (v - 1)
            ans = search(nr, nc, nd, observation, n)
            if ans is not None:
                return ans
        return None

    if kind == "col":
        c = branch[1]
        for p in col_cands[c]:
            nr, nc, nd = clone_state(row_cands, col_cands, domains)
            nc[c] = [p]
            for r, v in enumerate(p):
                nd[r][c] = 1 << (v - 1)
            ans = search(nr, nc, nd, observation, n)
            if ans is not None:
                return ans
        return None

    r, c = branch[1], branch[2]
    for bit in iter_bits(domains[r][c]):
        nr, nc, nd = clone_state(row_cands, col_cands, domains)
        nd[r][c] = bit
        ans = search(nr, nc, nd, observation, n)
        if ans is not None:
            return ans
    return None


def solve(observation):
    try:
        U = [0 if x in (None, 0) else int(x) for x in observation["U"]]
        D = [0 if x in (None, 0) else int(x) for x in observation["D"]]
        L = [0 if x in (None, 0) else int(x) for x in observation["L"]]
        R = [0 if x in (None, 0) else int(x) for x in observation["R"]]
    except Exception:
        return "No Solution"

    n = len(U)
    if not (len(D) == len(L) == len(R) == n and n > 0):
        return "No Solution"

    for clue_list in (U, D, L, R):
        for x in clue_list:
            if not (0 <= x <= n):
                return "No Solution"

    catalog = build_catalog(n)

    row_cands = []
    for r in range(n):
        cands = list(catalog[(L[r], R[r])])
        if not cands:
            return "No Solution"
        row_cands.append(cands)

    col_cands = []
    for c in range(n):
        cands = list(catalog[(U[c], D[c])])
        if not cands:
            return "No Solution"
        col_cands.append(cands)

    full = (1 << n) - 1
    domains = [[full for _ in range(n)] for _ in range(n)]

    result = search(row_cands, col_cands, domains, {"U": U, "D": D, "L": L, "R": R}, n)
    return str(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[2, None, 2, 2, None], [None, 3, None, None, None], [3, None, None, 3, None], [None, None, None, 1, None], [3, None, None, 1, 1]]}

from collections import deque


def neighbors(r, c, rows, cols):
    for dr in (-1, 0, 1):
        nr = r + dr
        if not (0 <= nr < rows):
            continue
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nc = c + dc
            if 0 <= nc < cols:
                yield nr, nc


def build_problem(data):
    rows = len(data)
    cols = len(data[0]) if rows else 0

    var_cells = []
    var_index = {}
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is None:
                idx = len(var_cells)
                var_cells.append((r, c))
                var_index[(r, c)] = idx

    constraints = []
    var_to_constraints = [[] for _ in range(len(var_cells))]

    for r in range(rows):
        for c in range(cols):
            clue = data[r][c]
            if clue is None:
                continue
            scope = []
            for nr, nc in neighbors(r, c, rows, cols):
                if data[nr][nc] is None:
                    scope.append(var_index[(nr, nc)])
            ci = len(constraints)
            constraints.append((tuple(scope), clue))
            for v in scope:
                var_to_constraints[v].append(ci)

    return rows, cols, var_cells, var_index, constraints, var_to_constraints


def connected_components(num_vars, constraints, var_to_constraints):
    seen = [False] * num_vars
    components = []

    for start in range(num_vars):
        if seen[start] or not var_to_constraints[start]:
            continue

        stack = [start]
        seen[start] = True
        comp_vars = []
        comp_cons = set()

        while stack:
            v = stack.pop()
            comp_vars.append(v)
            for ci in var_to_constraints[v]:
                if ci not in comp_cons:
                    comp_cons.add(ci)
                    scope, _ = constraints[ci]
                    for u in scope:
                        if not seen[u]:
                            seen[u] = True
                            stack.append(u)

        components.append((sorted(comp_vars), sorted(comp_cons)))

    return components


def solve_component(num_vars, constraints):
    # Local assignments: -1 unknown, 0 safe, 1 mine
    assignments = [-1] * num_vars
    trail = []

    var_to_constraints = [[] for _ in range(num_vars)]
    for ci, (scope, _) in enumerate(constraints):
        for v in scope:
            var_to_constraints[v].append(ci)

    def assign_var(v, val, queue):
        cur = assignments[v]
        if cur == val:
            return 0
        if cur != -1:
            return -1
        assignments[v] = val
        trail.append(v)
        for ci in var_to_constraints[v]:
            queue.append(ci)
        return 1

    def residual(scope, req):
        mines = 0
        unknown = []
        for v in scope:
            a = assignments[v]
            if a == 1:
                mines += 1
            elif a == -1:
                unknown.append(v)
        rem = req - mines
        return rem, unknown

    def propagate(queue):
        while True:
            progress = False

            while queue:
                ci = queue.popleft()
                scope, req = constraints[ci]
                rem, unknown = residual(scope, req)

                if rem < 0 or rem > len(unknown):
                    return False

                if not unknown:
                    if rem != 0:
                        return False
                    continue

                if rem == 0:
                    for v in unknown:
                        status = assign_var(v, 0, queue)
                        if status < 0:
                            return False
                        if status > 0:
                            progress = True
                elif rem == len(unknown):
                    for v in unknown:
                        status = assign_var(v, 1, queue)
                        if status < 0:
                            return False
                        if status > 0:
                            progress = True

            # Human-like pairwise overlap/subset deductions on residual constraints.
            reduced = {}
            for scope, req in constraints:
                rem, unknown = residual(scope, req)
                if rem < 0 or rem > len(unknown):
                    return False
                if not unknown:
                    if rem != 0:
                        return False
                    continue
                key = frozenset(unknown)
                prev = reduced.get(key)
                if prev is not None and prev != rem:
                    return False
                reduced[key] = rem

            items = [(set(k), v) for k, v in reduced.items()]

            for i in range(len(items)):
                s1, r1 = items[i]
                for j in range(i + 1, len(items)):
                    s2, r2 = items[j]
                    inter = s1 & s2
                    if not inter:
                        continue

                    only1 = s1 - s2
                    only2 = s2 - s1

                    # Bounds on overlap and exclusive parts.
                    lower_inter = max(0, r1 - len(only1), r2 - len(only2))
                    upper_inter = min(len(inter), r1, r2)
                    if lower_inter > upper_inter:
                        return False

                    lower_only1 = r1 - upper_inter
                    upper_only1 = r1 - lower_inter
                    lower_only2 = r2 - upper_inter
                    upper_only2 = r2 - lower_inter

                    if lower_only1 < 0 or upper_only1 > len(only1) or lower_only1 > upper_only1:
                        return False
                    if lower_only2 < 0 or upper_only2 > len(only2) or lower_only2 > upper_only2:
                        return False

                    if only1:
                        if upper_only1 == 0:
                            for v in only1:
                                status = assign_var(v, 0, queue)
                                if status < 0:
                                    return False
                                if status > 0:
                                    progress = True
                        elif lower_only1 == len(only1):
                            for v in only1:
                                status = assign_var(v, 1, queue)
                                if status < 0:
                                    return False
                                if status > 0:
                                    progress = True

                    if only2:
                        if upper_only2 == 0:
                            for v in only2:
                                status = assign_var(v, 0, queue)
                                if status < 0:
                                    return False
                                if status > 0:
                                    progress = True
                        elif lower_only2 == len(only2):
                            for v in only2:
                                status = assign_var(v, 1, queue)
                                if status < 0:
                                    return False
                                if status > 0:
                                    progress = True

            if not progress:
                break

        return True

    def pick_branch_var():
        best_v = None
        best_key = None
        best_prob = 0.5

        for v in range(num_vars):
            if assignments[v] != -1:
                continue

            min_scope = 10**9
            degree = 0
            probs = []

            for ci in var_to_constraints[v]:
                scope, req = constraints[ci]
                rem, unknown = residual(scope, req)
                if v in unknown:
                    degree += 1
                    size = len(unknown)
                    if size < min_scope:
                        min_scope = size
                    probs.append(rem / size)

            avg_prob = (sum(probs) / len(probs)) if probs else 0.5
            key = (min_scope, -degree, -abs(avg_prob - 0.5), v)

            if best_key is None or key < best_key:
                best_key = key
                best_v = v
                best_prob = avg_prob

        return best_v, (1, 0) if best_prob > 0.5 else (0, 1)

    def all_satisfied():
        for scope, req in constraints:
            total = 0
            for v in scope:
                if assignments[v] == 1:
                    total += 1
                elif assignments[v] == -1:
                    return False
            if total != req:
                return False
        return True

    memo = set()

    def dfs():
        key = tuple(assignments)
        if key in memo:
            return None

        if all(a != -1 for a in assignments):
            if all_satisfied():
                return assignments[:]
            memo.add(key)
            return None

        v, order = pick_branch_var()
        if v is None:
            if all_satisfied():
                return assignments[:]
            memo.add(key)
            return None

        for val in order:
            mark = len(trail)
            queue = deque()
            status = assign_var(v, val, queue)
            if status >= 0 and propagate(queue):
                ans = dfs()
                if ans is not None:
                    return ans
            while len(trail) > mark:
                assignments[trail.pop()] = -1

        memo.add(key)
        return None

    if not propagate(deque(range(len(constraints)))):
        return None
    return dfs()


def solve(observation):
    data = observation.get("data", [])
    if not data:
        return repr([])

    rows, cols, var_cells, var_index, constraints, var_to_constraints = build_problem(data)

    # Immediate impossibility from clue cells with no available unknown neighbors.
    for scope, req in constraints:
        if not scope and req != 0:
            return "No Solution"

    global_assignments = [0] * len(var_cells)

    for comp_vars, comp_cons in connected_components(len(var_cells), constraints, var_to_constraints):
        local_map = {gv: i for i, gv in enumerate(comp_vars)}
        local_constraints = []

        # Deduplicate identical local scopes with same requirement.
        seen = {}
        for ci in comp_cons:
            scope, req = constraints[ci]
            local_scope = tuple(sorted(local_map[v] for v in scope))
            prev = seen.get(local_scope)
            if prev is not None and prev != req:
                return "No Solution"
            seen[local_scope] = req

        for local_scope, req in seen.items():
            local_constraints.append((local_scope, req))

        local_solution = solve_component(len(comp_vars), local_constraints)
        if local_solution is None:
            return "No Solution"

        for gv, lv in local_map.items():
            global_assignments[gv] = local_solution[lv]

    answer = [[None for _ in range(cols)] for _ in range(rows)]
    for (r, c), idx in var_index.items():
        if global_assignments[idx] == 1:
            answer[r][c] = 'F'

    return repr(answer)


