OBSERVATION = {'data': [[None, 'B', None, None, None, None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None], [None, None, 'B', 'B', None, None], [None, None, None, None, 'B', None], [None, 'B', None, None, None, None]]}

from collections import deque


class YinYangSolver:
    def __init__(self, observation):
        data = observation["data"]
        self.n = len(data)
        self.board0 = [[-1] * self.n for _ in range(self.n)]
        for r in range(self.n):
            for c in range(self.n):
                v = data[r][c]
                if v == "B":
                    self.board0[r][c] = 1
                elif v == "W":
                    self.board0[r][c] = 0

        self.nei = {}
        self.blocks_of = {}
        for r in range(self.n):
            for c in range(self.n):
                lst = []
                if r > 0:
                    lst.append((r - 1, c))
                if r + 1 < self.n:
                    lst.append((r + 1, c))
                if c > 0:
                    lst.append((r, c - 1))
                if c + 1 < self.n:
                    lst.append((r, c + 1))
                self.nei[(r, c)] = lst

                bl = []
                for br in (r - 1, r):
                    for bc in (c - 1, c):
                        if 0 <= br < self.n - 1 and 0 <= bc < self.n - 1:
                            bl.append((br, bc))
                self.blocks_of[(r, c)] = bl

        self.dead = set()

    def copy_board(self, board):
        return [row[:] for row in board]

    def encode(self, board):
        return tuple(v for row in board for v in row)

    def unknown_count(self, board):
        return sum(v == -1 for row in board for v in row)

    def assign(self, board, r, c, val):
        cur = board[r][c]
        if cur != -1 and cur != val:
            return False, False
        if cur == val:
            return True, False
        board[r][c] = val
        return True, True

    def rule_no_2x2(self, board):
        changed = False
        for r in range(self.n - 1):
            for c in range(self.n - 1):
                cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                vals = [board[x][y] for x, y in cells]
                if vals.count(-1) == 0:
                    if vals.count(0) == 4 or vals.count(1) == 4:
                        return None
                    continue
                if vals.count(1) == 3 and vals.count(-1) == 1:
                    i = vals.index(-1)
                    ok, ch = self.assign(board, cells[i][0], cells[i][1], 0)
                    if not ok:
                        return None
                    changed |= ch
                if vals.count(0) == 3 and vals.count(-1) == 1:
                    i = vals.index(-1)
                    ok, ch = self.assign(board, cells[i][0], cells[i][1], 1)
                    if not ok:
                        return None
                    changed |= ch
        return changed

    def reachable_component(self, board, color):
        terminals = [(r, c) for r in range(self.n) for c in range(self.n) if board[r][c] == color]
        if not terminals:
            return set(), set()

        opp = 1 - color
        start = terminals[0]
        q = deque([start])
        seen = {start}
        while q:
            u = q.popleft()
            for v in self.nei[u]:
                if v not in seen and board[v[0]][v[1]] != opp:
                    seen.add(v)
                    q.append(v)

        for t in terminals:
            if t not in seen:
                return None, None
        return set(terminals), seen

    def articulation_forces(self, board, color):
        terminals, nodes = self.reachable_component(board, color)
        if terminals is None:
            return None
        if len(terminals) < 2:
            return set()

        root = next(iter(terminals))
        node_set = nodes
        disc = {}
        low = {}
        parent = {}
        required = set()
        total_terms = len(terminals)
        time = 0

        def dfs(u):
            nonlocal time
            time += 1
            disc[u] = time
            low[u] = time
            term_total = 1 if u in terminals else 0
            root_term_children = 0

            for v in self.nei[u]:
                if v not in node_set:
                    continue
                if v not in disc:
                    parent[v] = u
                    sub_terms = dfs(v)
                    term_total += sub_terms
                    low[u] = min(low[u], low[v])

                    if u == root:
                        if sub_terms > 0:
                            root_term_children += 1
                    else:
                        if low[v] >= disc[u] and sub_terms > 0 and (total_terms - sub_terms) > 0:
                            required.add(u)
                elif parent.get(u) != v:
                    low[u] = min(low[u], disc[v])

            if u == root and root_term_children >= 2:
                required.add(u)

            return term_total

        dfs(root)
        return {u for u in required if board[u[0]][u[1]] == -1}

    def connectivity_feasible(self, board):
        for color in (0, 1):
            terminals, nodes = self.reachable_component(board, color)
            if terminals is None:
                return False
        return True

    def propagate_core(self, board):
        while True:
            progress = False

            res = self.rule_no_2x2(board)
            if res is None:
                return None
            progress |= res

            if not self.connectivity_feasible(board):
                return None

            for color in (0, 1):
                forced = self.articulation_forces(board, color)
                if forced is None:
                    return None
                for r, c in forced:
                    ok, ch = self.assign(board, r, c, color)
                    if not ok:
                        return None
                    progress |= ch

            if not self.connectivity_feasible(board):
                return None

            if not progress:
                return board

    def local_score(self, board, r, c):
        s = 0
        s += 3 * sum(board[nr][nc] != -1 for nr, nc in self.nei[(r, c)])
        for br, bc in self.blocks_of[(r, c)]:
            vals = [
                board[br][bc],
                board[br][bc + 1],
                board[br + 1][bc],
                board[br + 1][bc + 1],
            ]
            assigned = 4 - vals.count(-1)
            s += assigned
            if assigned >= 3:
                s += 2
        return s

    def trial_branches(self, board, r, c):
        out = []
        cur_unknowns = self.unknown_count(board)
        for val in (1, 0):
            b2 = self.copy_board(board)
            b2[r][c] = val
            b2 = self.propagate_core(b2)
            if b2 is not None:
                impact = cur_unknowns - self.unknown_count(b2)
                out.append((val, b2, impact))
        out.sort(key=lambda x: (-x[2], -x[0]))
        return out

    def propagate(self, board):
        while True:
            board = self.propagate_core(board)
            if board is None:
                return None

            made = False
            unknowns = [(r, c) for r in range(self.n) for c in range(self.n) if board[r][c] == -1]
            unknowns.sort(key=lambda p: -self.local_score(board, p[0], p[1]))

            for r, c in unknowns:
                branches = self.trial_branches(board, r, c)
                if not branches:
                    return None
                if len(branches) == 1:
                    board = branches[0][1]
                    made = True
                    break

            if not made:
                return board

    def complete(self, board):
        return all(v != -1 for row in board for v in row)

    def color_connected(self, board, color):
        cells = [(r, c) for r in range(self.n) for c in range(self.n) if board[r][c] == color]
        if not cells:
            return False
        q = deque([cells[0]])
        seen = {cells[0]}
        while q:
            u = q.popleft()
            for v in self.nei[u]:
                if v not in seen and board[v[0]][v[1]] == color:
                    seen.add(v)
                    q.append(v)
        return len(seen) == len(cells)

    def final_valid(self, board):
        for r in range(self.n - 1):
            for c in range(self.n - 1):
                vals = [board[r][c], board[r][c + 1], board[r + 1][c], board[r + 1][c + 1]]
                if vals.count(0) == 4 or vals.count(1) == 4:
                    return False
        return self.color_connected(board, 0) and self.color_connected(board, 1)

    def choose_branch(self, board):
        best = None
        best_key = None

        unknowns = [(r, c) for r in range(self.n) for c in range(self.n) if board[r][c] == -1]
        unknowns.sort(key=lambda p: -self.local_score(board, p[0], p[1]))

        for r, c in unknowns:
            branches = self.trial_branches(board, r, c)
            if not branches:
                return None
            key = (len(branches), -self.local_score(board, r, c), -max(b[2] for b in branches))
            if best is None or key < best_key:
                best = branches
                best_key = key
                if len(branches) == 1:
                    return branches
        return best

    def dfs(self, board):
        board = self.propagate(board)
        if board is None:
            return None

        key = self.encode(board)
        if key in self.dead:
            return None

        if self.complete(board):
            if self.final_valid(board):
                return board
            self.dead.add(key)
            return None

        branches = self.choose_branch(board)
        if not branches:
            self.dead.add(key)
            return None

        for _, b2, _ in branches:
            ans = self.dfs(b2)
            if ans is not None:
                return ans

        self.dead.add(key)
        return None

    def solve(self):
        start = self.copy_board(self.board0)
        ans = self.dfs(start)
        if ans is None:
            return "No Solution"
        return [["B" if v == 1 else "W" for v in row] for row in ans]


def solve(observation):
    return YinYangSolver(observation).solve()


