    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, 'W'], [None, None, 'B', 'W', None, None], [None, None, None, 'W', 'B', None], [None, None, 'W', None, 'W', None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None]]}

B = 1
W = 2
BOTH = 3
OPP = {B: W, W: B}


def solve(observation):
    data = observation["data"]
    n = len(data)
    nn = n * n

    def idx(r, c):
        return r * n + c

    neighbors = [[] for _ in range(nn)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    blocks = []
    cell_blocks = [[] for _ in range(nn)]
    for r in range(n - 1):
        for c in range(n - 1):
            b = (idx(r, c), idx(r, c + 1), idx(r + 1, c), idx(r + 1, c + 1))
            bi = len(blocks)
            blocks.append(b)
            for i in b:
                cell_blocks[i].append(bi)

    dom0 = [BOTH] * nn
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                dom0[idx(r, c)] = B
            elif v == 'W':
                dom0[idx(r, c)] = W

    def build_components(dom, color):
        comp_id = [-1] * nn
        comps = []
        for i in range(nn):
            if comp_id[i] != -1 or not (dom[i] & color):
                continue
            cid = len(comps)
            stack = [i]
            comp_id[i] = cid
            comp = []
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in neighbors[u]:
                    if comp_id[v] == -1 and (dom[v] & color):
                        comp_id[v] = cid
                        stack.append(v)
            comps.append(comp)
        return comps, comp_id

    def exact_connected(dom, color):
        cells = [i for i, d in enumerate(dom) if d == color]
        if not cells:
            return False
        seen = {cells[0]}
        stack = [cells[0]]
        while stack:
            u = stack.pop()
            for v in neighbors[u]:
                if dom[v] == color and v not in seen:
                    seen.add(v)
                    stack.append(v)
        return len(seen) == len(cells)

    def exact_valid(dom):
        if any(d == BOTH or d == 0 for d in dom):
            return False
        for b in blocks:
            vals = [dom[i] for i in b]
            if vals[0] == vals[1] == vals[2] == vals[3]:
                return False
        return exact_connected(dom, B) and exact_connected(dom, W)

    def connectivity_prune(dom, color):
        changed = False
        comps, comp_id = build_components(dom, color)
        fixed = [i for i, d in enumerate(dom) if d == color]

        if fixed:
            main = comp_id[fixed[0]]
            if main == -1:
                return None
            for i in fixed[1:]:
                if comp_id[i] != main:
                    return None

            # Any possible component not containing a fixed cell of this color
            # can never be part of the final connected region.
            for cid, comp in enumerate(comps):
                if cid == main:
                    continue
                for x in comp:
                    nd = dom[x] & OPP[color]
                    if nd == 0:
                        return None
                    if nd != dom[x]:
                        dom[x] = nd
                        changed = True

            # Bridge rule: if removing an undecided cell disconnects all fixed cells
            # of this color in the possible graph, that cell must be this color.
            if len(fixed) >= 2:
                fixed_set = set(fixed)
                main_cells = comps[main]
                for x in main_cells:
                    if dom[x] != BOTH:
                        continue
                    start = fixed[0]
                    seen = {start}
                    stack = [start]
                    while stack:
                        u = stack.pop()
                        for v in neighbors[u]:
                            if v == x:
                                continue
                            if (dom[v] & color) and v not in seen:
                                seen.add(v)
                                stack.append(v)
                    if any(f not in seen for f in fixed_set):
                        dom[x] = color
                        changed = True

        return changed

    def propagate_core(dom):
        while True:
            if any(d == 0 for d in dom):
                return None

            changed = False

            # 2x2 rule
            for b in blocks:
                cnt_b = 0
                cnt_w = 0
                unknowns = []
                for i in b:
                    if dom[i] == B:
                        cnt_b += 1
                    elif dom[i] == W:
                        cnt_w += 1
                    else:
                        unknowns.append(i)

                if cnt_b == 4 or cnt_w == 4:
                    return None

                if cnt_b == 3:
                    for i in unknowns:
                        nd = dom[i] & W
                        if nd == 0:
                            return None
                        if nd != dom[i]:
                            dom[i] = nd
                            changed = True

                if cnt_w == 3:
                    for i in unknowns:
                        nd = dom[i] & B
                        if nd == 0:
                            return None
                        if nd != dom[i]:
                            dom[i] = nd
                            changed = True

            # Connectivity pruning for both colors
            for color in (B, W):
                res = connectivity_prune(dom, color)
                if res is None:
                    return None
                if res:
                    changed = True

            if not changed:
                return dom

    def cell_score(dom, i):
        score = 0
        for v in neighbors[i]:
            if dom[v] != BOTH:
                score += 2
        for bi in cell_blocks[i]:
            b = blocks[bi]
            cnt_b = sum(1 for x in b if dom[x] == B)
            cnt_w = sum(1 for x in b if dom[x] == W)
            score += 3 * max(cnt_b, cnt_w) + cnt_b + cnt_w
        return score

    def value_order(dom, i):
        nb_b = sum(1 for v in neighbors[i] if dom[v] == B)
        nb_w = sum(1 for v in neighbors[i] if dom[v] == W)
        blk_b = 0
        blk_w = 0
        for bi in cell_blocks[i]:
            b = blocks[bi]
            blk_b += sum(1 for x in b if x != i and dom[x] == B)
            blk_w += sum(1 for x in b if x != i and dom[x] == W)
        sb = nb_b + blk_b
        sw = nb_w + blk_w
        return (B, W) if sb >= sw else (W, B)

    def propagate(dom):
        dom = propagate_core(dom)
        if dom is None:
            return None

        # One-step contradiction probing.
        while True:
            progress = False
            undecided = [i for i, d in enumerate(dom) if d == BOTH]
            undecided.sort(key=lambda i: -cell_score(dom, i))

            for i in undecided:
                for color in value_order(dom, i):
                    if not (dom[i] & color):
                        continue
                    test = dom[:]
                    test[i] = color
                    if propagate_core(test) is None:
                        nd = dom[i] & OPP[color]
                        if nd == 0:
                            return None
                        if nd != dom[i]:
                            dom[i] = nd
                            progress = True
                            break
                if progress:
                    dom = propagate_core(dom)
                    if dom is None:
                        return None
                    break

            if not progress:
                return dom

    dead = set()

    def select_cell(dom):
        undecided = [i for i, d in enumerate(dom) if d == BOTH]
        return max(undecided, key=lambda i: cell_score(dom, i))

    def search(dom):
        dom = propagate(dom[:])
        if dom is None:
            return None

        key = tuple(dom)
        if key in dead:
            return None

        if all(d != BOTH for d in dom):
            if exact_valid(dom):
                return dom
            dead.add(key)
            return None

        i = select_cell(dom)
        for color in value_order(dom, i):
            if not (dom[i] & color):
                continue
            nxt = dom[:]
            nxt[i] = color
            res = search(nxt)
            if res is not None:
                return res

        dead.add(key)
        return None

    res = search(dom0)
    if res is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if res[idx(r, c)] == B else 'W')
        out.append(row)
    return out


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 4, None, None, None, 6, None], [None, None, None, None, None, None, None], [None, None, 4, None, None, None, 6], [None, None, None, None, None, None, 4], [None, None, 3, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None]], 'horizontal': {'(0,0.5)': '>', '(0,3.5)': '<', '(1,1.5)': '>', '(2,0.5)': '<', '(3,0.5)': '>', '(3,1.5)': '>', '(5,0.5)': '>', '(5,1.5)': '>', '(5,4.5)': '<', '(5,5.5)': '<'}, 'vertical': {'(1.5,6)': 'v', '(2.5,2)': 'v', '(4.5,4)': '^'}}

import ast
from collections import deque


def solve(observation):
    data = observation["data"]
    n = len(data)
    total = n * n
    full_mask = (1 << n) - 1
    bit_of = [0] + [1 << (v - 1) for v in range(1, n + 1)]

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    units = rows + cols

    lt_mask = [0] * (n + 2)  # values < t
    gt_mask = [0] * (n + 2)  # values > t
    for t in range(n + 2):
        if t <= 1:
            lt_mask[t] = 0
        else:
            lt_mask[t] = (1 << (t - 1)) - 1
        if t >= n:
            gt_mask[t] = 0
        else:
            gt_mask[t] = full_mask & ~((1 << t) - 1)

    def parse_key(s):
        return ast.literal_eval(s)

    def idx(r, c):
        return r * n + c

    def is_single(mask):
        return mask and (mask & (mask - 1) == 0)

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def value_mask(lo, hi):
        if lo > hi:
            return 0
        return ((1 << hi) - 1) & ~((1 << (lo - 1)) - 1)

    def masks_to_grid(domains):
        out = []
        for r in range(n):
            row = []
            for c in range(n):
                row.append(domains[idx(r, c)].bit_length())
            out.append(row)
        return out

    horiz = []
    for k, sym in observation.get("horizontal", {}).items():
        r, x = parse_key(k)
        r = int(round(r))
        c = int(round(x - 0.5))
        a = idx(r, c)
        b = idx(r, c + 1)
        if sym == "<":
            horiz.append((a, b))
        else:
            horiz.append((b, a))

    vert_raw = []
    for k, sym in observation.get("vertical", {}).items():
        y, c = parse_key(k)
        r = int(round(y - 0.5))
        c = int(round(c))
        up = idx(r, c)
        down = idx(r + 1, c)
        vert_raw.append((up, down, sym))

    base_domains = [full_mask] * total
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                base_domains[idx(r, c)] = bit_of[v]

    # Shared existence checker for unit matching.
    def make_exists_cache():
        cache = {}

        def exists(masks):
            key = tuple(sorted(masks, key=lambda m: (m.bit_count(), m)))
            if key in cache:
                return cache[key]
            ordered = key
            mlen = len(ordered)

            memo = {}

            def rec(i, used):
                state = (i, used)
                if state in memo:
                    return memo[state]
                if i == mlen:
                    memo[state] = True
                    return True

                union = 0
                for j in range(i, mlen):
                    union |= ordered[j] & ~used
                if union.bit_count() < (mlen - i):
                    memo[state] = False
                    return False

                opts = ordered[i] & ~used
                while opts:
                    b = opts & -opts
                    if rec(i + 1, used | b):
                        memo[state] = True
                        return True
                    opts ^= b
                memo[state] = False
                return False

            ans = rec(0, 0)
            cache[key] = ans
            return ans

        return exists

    def build_inequalities(vertical_mode):
        # horizontal: symbol is unambiguous, left/right
        # vertical_mode 0: '^' => upper < lower, 'v' => upper > lower
        # vertical_mode 1: '^' => upper > lower, 'v' => upper < lower
        rels = list(horiz)
        for up, down, sym in vert_raw:
            if vertical_mode == 0:
                if sym == "^":
                    rels.append((up, down))
                else:  # 'v'
                    rels.append((down, up))
            else:
                if sym == "^":
                    rels.append((down, up))
                else:  # 'v'
                    rels.append((up, down))
        edges = [[] for _ in range(total)]
        rev = [[] for _ in range(total)]
        for a, b in rels:
            edges[a].append(b)
            rev[b].append(a)
        return rels, edges, rev

    def static_path_prune(domains, edges, rev):
        indeg = [len(rev[i]) for i in range(total)]
        q = deque(i for i in range(total) if indeg[i] == 0)
        topo = []
        while q:
            u = q.popleft()
            topo.append(u)
            for v in edges[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        if len(topo) != total:
            return False

        longest_before = [0] * total
        for u in topo:
            best = 0
            for p in rev[u]:
                cand = longest_before[p] + 1
                if cand > best:
                    best = cand
            longest_before[u] = best

        longest_after = [0] * total
        for u in reversed(topo):
            best = 0
            for v in edges[u]:
                cand = longest_after[v] + 1
                if cand > best:
                    best = cand
            longest_after[u] = best

        for i in range(total):
            lo = 1 + longest_before[i]
            hi = n - longest_after[i]
            nm = domains[i] & value_mask(lo, hi)
            if nm == 0:
                return False
            domains[i] = nm
        return True

    def propagate_unit(domains, unit):
        changed = False

        fixed_mask = 0
        for cell in unit:
            m = domains[cell]
            if m == 0:
                return None
            if is_single(m):
                if fixed_mask & m:
                    return None
                fixed_mask |= m

        if fixed_mask:
            inv = ~fixed_mask
            for cell in unit:
                m = domains[cell]
                if not is_single(m):
                    nm = m & inv
                    if nm == 0:
                        return None
                    if nm != m:
                        domains[cell] = nm
                        changed = True

        counts = [0] * (n + 1)
        pos = [-1] * (n + 1)
        for cell in unit:
            m = domains[cell]
            mm = m
            while mm:
                b = mm & -mm
                v = b.bit_length()
                counts[v] += 1
                if counts[v] == 1:
                    pos[v] = cell
                else:
                    pos[v] = -1
                mm ^= b

        for v in range(1, n + 1):
            if counts[v] == 0:
                return None
            if counts[v] == 1:
                cell = pos[v]
                if domains[cell] != bit_of[v]:
                    domains[cell] = bit_of[v]
                    changed = True

        fixed_mask = 0
        unknown_cells = []
        unknown_masks = []
        for cell in unit:
            m = domains[cell]
            if m == 0:
                return None
            if is_single(m):
                if fixed_mask & m:
                    return None
                fixed_mask |= m
            else:
                unknown_cells.append(cell)

        rem_mask = full_mask & ~fixed_mask
        if rem_mask.bit_count() != len(unknown_cells):
            return None

        for cell in unknown_cells:
            m = domains[cell] & rem_mask
            if m == 0:
                return None
            unknown_masks.append(m)

        if unknown_masks:
            exists = make_exists_cache()
            if not exists(tuple(unknown_masks)):
                return None

            for i, cell in enumerate(unknown_cells):
                m = unknown_masks[i]
                if is_single(m):
                    if domains[cell] != m:
                        domains[cell] = m
                        changed = True
                    continue
                nm = 0
                mm = m
                while mm:
                    b = mm & -mm
                    trial = list(unknown_masks)
                    trial[i] = b
                    if exists(tuple(trial)):
                        nm |= b
                    mm ^= b
                if nm == 0:
                    return None
                if nm != domains[cell]:
                    domains[cell] = nm
                    changed = True

        return changed

    def propagate(domains, rels):
        while True:
            changed = False

            for less, greater in rels:
                ml = domains[less]
                mg = domains[greater]
                if ml == 0 or mg == 0:
                    return False

                max_g = max_val(mg)
                min_l = min_val(ml)

                nml = ml & lt_mask[max_g]
                nmg = mg & gt_mask[min_l]

                if nml == 0 or nmg == 0:
                    return False
                if nml != ml:
                    domains[less] = nml
                    changed = True
                if nmg != mg:
                    domains[greater] = nmg
                    changed = True

            for unit in units:
                res = propagate_unit(domains, unit)
                if res is None:
                    return False
                if res:
                    changed = True

            if not changed:
                return True

    def choose_cell(domains):
        best_cell = -1
        best_size = n + 1
        for i, m in enumerate(domains):
            bc = m.bit_count()
            if 1 < bc < best_size:
                best_size = bc
                best_cell = i
        return best_cell

    def candidate_order(domains, cell):
        m = domains[cell]
        r = cell // n
        c = cell % n
        row = rows[r]
        col = cols[c]
        vals = []
        mm = m
        while mm:
            b = mm & -mm
            score = 0
            for peer in row:
                if peer != cell and (domains[peer] & b):
                    score += 1
            for peer in col:
                if peer != cell and (domains[peer] & b):
                    score += 1
            vals.append((score, b))
            mm ^= b
        vals.sort()
        return [b for _, b in vals]

    dead = set()

    def search(domains, rels):
        key = tuple(domains)
        if key in dead:
            return None

        cell = choose_cell(domains)
        if cell == -1:
            return domains

        for b in candidate_order(domains, cell):
            nxt = domains.copy()
            nxt[cell] = b
            if propagate(nxt, rels):
                ans = search(nxt, rels)
                if ans is not None:
                    return ans

        dead.add(key)
        return None

    for vertical_mode in (0, 1):
        rels, edges, rev = build_inequalities(vertical_mode)
        domains = base_domains.copy()

        if not static_path_prune(domains, edges, rev):
            continue
        if not propagate(domains, rels):
            continue

        solved = search(domains, rels)
        if solved is not None:
            return str(masks_to_grid(solved))

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 9, None, None, None], [None, 5, None, None, None, None, 8], [None, None, None, 8, None, None, 10], [None, None, None, 9, None, None, None], [7, None, None, 9, None, None, None], [3, None, None, None, None, 3, None], [None, None, None, 4, None, None, None]]}

# Kuromasu solver:
# - clue cells are white
# - black cells cannot touch orthogonally
# - each clue equals visible white cells in 4 orthogonal directions including itself
# - all white cells must be one connected component

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0
    if n == 0 or n != m:
        return "No Solution"

    N = n
    ALL_MASK = (1 << (N * N)) - 1

    def idx(r, c):
        return r * N + c

    def bit(r, c):
        return 1 << idx(r, c)

    def bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_index(b):
        return b.bit_length() - 1

    def rc_from_bit(b):
        k = bit_index(b)
        return divmod(k, N)

    # Orthogonal neighbors
    neighbor_masks = [0] * (N * N)
    for r in range(N):
        for c in range(N):
            k = idx(r, c)
            nm = 0
            if r > 0:
                nm |= bit(r - 1, c)
            if r + 1 < N:
                nm |= bit(r + 1, c)
            if c > 0:
                nm |= bit(r, c - 1)
            if c + 1 < N:
                nm |= bit(r, c + 1)
            neighbor_masks[k] = nm

    def union_neighbors(mask):
        out = 0
        for b in bits(mask):
            out |= neighbor_masks[bit_index(b)]
        return out

    # Clues
    clue_cells = {}
    clue_mask = 0
    clues = []
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                clue_cells[(r, c)] = v
                clue_mask |= bit(r, c)

    if clue_mask == 0:
        return "No Solution"

    # Precompute rays and patterns for each clue.
    # Pattern = exact visibility extents in U/D/L/R, encoded as:
    #   whites bitmask forced by the clue
    #   blacks bitmask forced as blockers immediately after the visible run
    clue_patterns = []
    cell_scores = [0] * (N * N)

    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue

            up = [(rr, c) for rr in range(r - 1, -1, -1)]
            down = [(rr, c) for rr in range(r + 1, N)]
            left = [(r, cc) for cc in range(c - 1, -1, -1)]
            right = [(r, cc) for cc in range(c + 1, N)]

            max_u = len(up)
            max_d = len(down)
            max_l = len(left)
            max_r = len(right)

            pats = []
            need = v - 1
            if need < 0:
                return "No Solution"

            for u in range(max_u + 1):
                rem1 = need - u
                if rem1 < 0:
                    break
                for d in range(max_d + 1):
                    rem2 = rem1 - d
                    if rem2 < 0:
                        break
                    for l in range(max_l + 1):
                        rr = rem2 - l
                        if rr < 0:
                            break
                        if rr > max_r:
                            continue
                        rgt = rr

                        whites = bit(r, c)
                        blacks = 0
                        ok = True

                        for i in range(u):
                            rr2, cc2 = up[i]
                            whites |= bit(rr2, cc2)
                        if u < max_u:
                            br, bc = up[u]
                            if data[br][bc] is not None:
                                ok = False
                            else:
                                blacks |= bit(br, bc)

                        for i in range(d):
                            rr2, cc2 = down[i]
                            whites |= bit(rr2, cc2)
                        if d < max_d:
                            br, bc = down[d]
                            if data[br][bc] is not None:
                                ok = False
                            else:
                                blacks |= bit(br, bc)

                        for i in range(l):
                            rr2, cc2 = left[i]
                            whites |= bit(rr2, cc2)
                        if l < max_l:
                            br, bc = left[l]
                            if data[br][bc] is not None:
                                ok = False
                            else:
                                blacks |= bit(br, bc)

                        for i in range(rgt):
                            rr2, cc2 = right[i]
                            whites |= bit(rr2, cc2)
                        if rgt < max_r:
                            br, bc = right[rgt]
                            if data[br][bc] is not None:
                                ok = False
                            else:
                                blacks |= bit(br, bc)

                        if not ok:
                            continue
                        if whites & blacks:
                            continue
                        pats.append((whites, blacks))

            if not pats:
                return "No Solution"

            clue_idx = len(clues)
            clues.append((r, c, v))
            clue_patterns.append(pats)

            # Cell scoring for fallback branching
            union_w = 0
            union_b = 0
            for pw, pb in pats:
                union_w |= pw
                union_b |= pb
            affect = (union_w | union_b) & ~bit(r, c)
            for b in bits(affect):
                cell_scores[bit_index(b)] += 1

    clue_count = len(clues)
    initial_domains = tuple((1 << len(clue_patterns[i])) - 1 for i in range(clue_count))

    def flood(passable_mask, start_bit):
        comp = 0
        frontier = start_bit & passable_mask
        while frontier:
            comp |= frontier
            nxt = 0
            for b in bits(frontier):
                nxt |= neighbor_masks[bit_index(b)]
            frontier = nxt & passable_mask & ~comp
        return comp

    def has_adjacent_black(black_mask):
        for b in bits(black_mask):
            if neighbor_masks[bit_index(b)] & black_mask:
                return True
        return False

    def connectivity_deductions(black_mask, white_mask):
        # Necessary connectivity conditions:
        # 1) all currently-white cells must still be connectable through non-black cells
        # 2) all clues must be in one passable component
        # 3) cells outside the clue-containing passable component can never be white -> black
        # 4) articulation-style deduction: if removing an unknown cell disconnects current whites, that cell is white
        passable = ALL_MASK & ~black_mask

        # All currently white cells must be mutually connectable within passable
        start_req = white_mask & -white_mask
        req_comp = flood(passable, start_req)
        if white_mask & ~req_comp:
            return None

        # All clues must also be connectable
        start_clue = clue_mask & -clue_mask
        clue_comp = flood(passable, start_clue)
        if clue_mask & ~clue_comp:
            return None

        force_black = passable & ~clue_comp
        force_white = 0

        # If removing an undecided cell disconnects forced whites, that cell must be white.
        req = white_mask
        if req:
            start_req = req & -req
            for b in bits(clue_comp & ~white_mask):
                reduced = passable ^ b
                comp2 = flood(reduced, start_req)
                if req & ~comp2:
                    force_white |= b

        return force_white, force_black

    def propagate(black_mask, white_mask, domains):
        domains = list(domains)
        white_mask |= clue_mask

        while True:
            if black_mask & white_mask:
                return None
            if has_adjacent_black(black_mask):
                return None

            changed = False

            # Black cells force orthogonal neighbors white.
            forced_white = union_neighbors(black_mask) & ~white_mask
            if forced_white:
                if forced_white & black_mask:
                    return None
                white_mask |= forced_white
                changed = True

            # Filter clue domains and intersect common forced whites/blacks.
            aggregate_force_white = clue_mask
            aggregate_force_black = 0

            for i in range(clue_count):
                dom = domains[i]
                pats = clue_patterns[i]

                new_dom = 0
                inter_w = 0
                inter_b = 0
                first = True

                d = dom
                while d:
                    lsb = d & -d
                    pidx = lsb.bit_length() - 1
                    pw, pb = pats[pidx]
                    if (pw & black_mask) == 0 and (pb & white_mask) == 0:
                        new_dom |= lsb
                        if first:
                            inter_w = pw
                            inter_b = pb
                            first = False
                        else:
                            inter_w &= pw
                            inter_b &= pb
                    d ^= lsb

                if new_dom == 0:
                    return None
                if new_dom != dom:
                    domains[i] = new_dom
                    changed = True

                aggregate_force_white |= inter_w
                aggregate_force_black |= inter_b

            if aggregate_force_white & black_mask:
                return None
            if aggregate_force_black & white_mask:
                return None

            add_w = aggregate_force_white & ~white_mask
            add_b = aggregate_force_black & ~black_mask
            if add_w or add_b:
                white_mask |= add_w
                black_mask |= add_b
                changed = True
                continue

            conn = connectivity_deductions(black_mask, white_mask)
            if conn is None:
                return None
            add_w, add_b = conn
            if add_w & black_mask:
                return None
            if add_b & white_mask:
                return None
            if add_w or add_b:
                white_mask |= add_w
                black_mask |= add_b
                changed = True
                continue

            if not changed:
                break

        if has_adjacent_black(black_mask):
            return None
        if black_mask & white_mask:
            return None

        return black_mask, white_mask, tuple(domains)

    def count_visible(final_black, r, c):
        total = 1

        rr = r - 1
        while rr >= 0 and not (final_black & bit(rr, c)):
            total += 1
            rr -= 1

        rr = r + 1
        while rr < N and not (final_black & bit(rr, c)):
            total += 1
            rr += 1

        cc = c - 1
        while cc >= 0 and not (final_black & bit(r, cc)):
            total += 1
            cc -= 1

        cc = c + 1
        while cc < N and not (final_black & bit(r, cc)):
            total += 1
            cc += 1

        return total

    def verify_complete(black_mask):
        if black_mask & clue_mask:
            return False
        if has_adjacent_black(black_mask):
            return False

        white_final = ALL_MASK & ~black_mask
        start = white_final & -white_final
        comp = flood(white_final, start)
        if comp != white_final:
            return False

        for r, c, v in clues:
            if count_visible(black_mask, r, c) != v:
                return False
        return True

    failed = set()

    def dfs(black_mask, white_mask, domains):
        state = propagate(black_mask, white_mask, domains)
        if state is None:
            return None

        black_mask, white_mask, domains = state
        sig = (black_mask, white_mask, domains)
        if sig in failed:
            return None

        unknown = ALL_MASK & ~(black_mask | white_mask)
        if unknown == 0:
            if verify_complete(black_mask):
                return black_mask
            failed.add(sig)
            return None

        # Prefer branching on the most constrained clue domain.
        best_i = -1
        best_count = 10**9
        for i, dom in enumerate(domains):
            cnt = dom.bit_count()
            if 1 < cnt < best_count:
                best_count = cnt
                best_i = i

        if best_i != -1:
            opts = []
            pats = clue_patterns[best_i]
            d = domains[best_i]
            while d:
                lsb = d & -d
                pidx = lsb.bit_length() - 1
                pw, pb = pats[pidx]
                score = ((pw | pb) & unknown).bit_count()
                score += pb.bit_count()  # black placements are usually more constraining
                opts.append((score, pidx, pw, pb))
                d ^= lsb
            opts.sort(reverse=True)

            for _, pidx, pw, pb in opts:
                new_domains = list(domains)
                new_domains[best_i] = 1 << pidx
                ans = dfs(black_mask | pb, white_mask | pw, tuple(new_domains))
                if ans is not None:
                    return ans

            failed.add(sig)
            return None

        # Fallback: branch on an undecided cell.
        best_bit = None
        best_score = -1
        for b in bits(unknown):
            k = bit_index(b)
            score = cell_scores[k] * 4
            score += (neighbor_masks[k] & unknown).bit_count()
            score += (neighbor_masks[k] & black_mask).bit_count() * 3
            if score > best_score:
                best_score = score
                best_bit = b

        if best_bit is None:
            failed.add(sig)
            return None

        k = bit_index(best_bit)
        if neighbor_masks[k] & black_mask:
            order = ('W',)
        else:
            order = ('B', 'W')

        for choice in order:
            if choice == 'B':
                ans = dfs(black_mask | best_bit, white_mask, domains)
            else:
                ans = dfs(black_mask, white_mask | best_bit, domains)
            if ans is not None:
                return ans

        failed.add(sig)
        return None

    final_black = dfs(0, clue_mask, initial_domains)
    if final_black is None:
        return "No Solution"

    answer = []
    for r in range(N):
        row = []
        for c in range(N):
            v = data[r][c]
            if v is not None:
                row.append(v)
            elif final_black & bit(r, c):
                row.append('B')
            else:
                row.append(None)
        answer.append(row)

    return repr(answer)


