# Hitori solver with aggressive logical propagation plus bounded search.
# States: 0 = undecided, 1 = white, 2 = black.

def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n
    values = [data[r][c] for r in range(n) for c in range(n)]

    def idx(r, c):
        return r * n + c

    coords = [(i // n, i % n) for i in range(m)]

    neighbors = [[] for _ in range(m)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    # Same-value peers in row/column.
    row_map = {}
    col_map = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            row_map.setdefault((r, v), []).append(idx(r, c))
            col_map.setdefault((c, v), []).append(idx(r, c))

    dup_peers = [set() for _ in range(m)]
    for cells in row_map.values():
        if len(cells) > 1:
            for i in cells:
                dup_peers[i].update(j for j in cells if j != i)
    for cells in col_map.values():
        if len(cells) > 1:
            for i in cells:
                dup_peers[i].update(j for j in cells if j != i)
    dup_peers = [tuple(sorted(s)) for s in dup_peers]

    candidate_black = [bool(dup_peers[i]) for i in range(m)]

    def connectivity_forces(state, removed=-1):
        # Analyze graph of currently non-black cells, optionally with one cell removed.
        active = [False] * m
        active_count = 0
        for i in range(m):
            if i != removed and state[i] != 2:
                active[i] = True
                active_count += 1
        if active_count == 0:
            return False, []

        seen = [False] * m
        comps = []
        for start in range(m):
            if active[start] and not seen[start]:
                stack = [start]
                seen[start] = True
                comp = []
                has_white = False
                while stack:
                    u = stack.pop()
                    comp.append(u)
                    if state[u] == 1:
                        has_white = True
                    for v in neighbors[u]:
                        if active[v] and not seen[v]:
                            seen[v] = True
                            stack.append(v)
                comps.append((comp, has_white))

        def removable(comp, has_white):
            return (
                not has_white
                and len(comp) == 1
                and state[comp[0]] == 0
                and candidate_black[comp[0]]
            )

        white_comps = [k for k, (_, hw) in enumerate(comps) if hw]
        forced_black = []

        if white_comps:
            if len(white_comps) > 1:
                return False, []
            main = white_comps[0]
            for k, (comp, has_white) in enumerate(comps):
                if k == main:
                    continue
                if removable(comp, has_white):
                    forced_black.extend(comp)
                else:
                    return False, []
            return True, forced_black

        nonremovable = []
        removable_cells = []
        for comp, has_white in comps:
            if removable(comp, has_white):
                removable_cells.extend(comp)
            else:
                nonremovable.append(comp)

        if len(nonremovable) > 1:
            return False, []
        if len(nonremovable) == 1:
            return True, removable_cells
        return True, []

    def heuristic(state, i):
        dup_unknown = 0
        for p in dup_peers[i]:
            if state[p] == 0:
                dup_unknown += 1
        nonblack_deg = 0
        for nb in neighbors[i]:
            if state[nb] != 2:
                nonblack_deg += 1
        return dup_unknown * 6 + nonblack_deg * 2 + len(dup_peers[i])

    def propagate(state, initial_queue=None, allow_trials=True):
        queue = [] if initial_queue is None else list(initial_queue)

        def do_white(i):
            if state[i] == 1:
                return True
            if state[i] == 2:
                return False
            state[i] = 1
            queue.append((i, 1))
            return True

        def do_black(i):
            if not candidate_black[i]:
                return False
            if state[i] == 2:
                return True
            if state[i] == 1:
                return False
            state[i] = 2
            queue.append((i, 2))
            return True

        while True:
            while queue:
                i, color = queue.pop()
                if color == 1:
                    for p in dup_peers[i]:
                        if not do_black(p):
                            return None
                else:
                    for nb in neighbors[i]:
                        if not do_white(nb):
                            return None

            progress = False

            # Dynamic uniqueness: once all duplicate peers are black, blacking this cell is pointless.
            for i in range(m):
                if state[i] == 0:
                    all_black = True
                    for p in dup_peers[i]:
                        if state[p] != 2:
                            all_black = False
                            break
                    if all_black:
                        if not do_white(i):
                            return None
                        progress = True
            if queue:
                continue

            # Global connectivity pruning.
            ok, forced = connectivity_forces(state)
            if not ok:
                return None
            for i in forced:
                if not do_black(i):
                    return None
                progress = True
            if queue:
                continue

            # If blacking a cell alone breaks the future white connectivity, it must be white.
            unknowns = [i for i in range(m) if state[i] == 0]
            for i in unknowns:
                ok_removed, _ = connectivity_forces(state, removed=i)
                if not ok_removed:
                    if not do_white(i):
                        return None
                    progress = True
            if queue:
                continue

            # Small look-ahead on the most constrained cells.
            if allow_trials:
                unknowns = [i for i in range(m) if state[i] == 0]
                if unknowns:
                    unknowns.sort(key=lambda x: heuristic(state, x), reverse=True)
                    limit = min(8, len(unknowns))
                    for i in unknowns[:limit]:
                        trial = state.copy()
                        if propagate(trial, [(i, 2)], allow_trials=False) is None:
                            if not do_white(i):
                                return None
                            progress = True
                            break
                        trial = state.copy()
                        if propagate(trial, [(i, 1)], allow_trials=False) is None:
                            if not do_black(i):
                                return None
                            progress = True
                            break
                if queue:
                    continue

            if not progress:
                break

        return state

    def valid_complete(state):
        if any(s == 0 for s in state):
            return False
        if 1 not in state:
            return False

        for i in range(m):
            if state[i] == 2:
                for nb in neighbors[i]:
                    if state[nb] == 2:
                        return False

        for r in range(n):
            seen = {}
            for c in range(n):
                i = idx(r, c)
                if state[i] == 1:
                    v = data[r][c]
                    if v in seen:
                        return False
                    seen[v] = True

        for c in range(n):
            seen = {}
            for r in range(n):
                i = idx(r, c)
                if state[i] == 1:
                    v = data[r][c]
                    if v in seen:
                        return False
                    seen[v] = True

        whites = [i for i in range(m) if state[i] == 1]
        start = whites[0]
        stack = [start]
        seen = {start}
        while stack:
            u = stack.pop()
            for v in neighbors[u]:
                if state[v] == 1 and v not in seen:
                    seen.add(v)
                    stack.append(v)
        return len(seen) == len(whites)

    def search(state):
        state = propagate(state, allow_trials=True)
        if state is None:
            return None

        unknowns = [i for i in range(m) if state[i] == 0]
        if not unknowns:
            return state if valid_complete(state) else None

        unknowns.sort(key=lambda x: heuristic(state, x), reverse=True)
        i = unknowns[0]

        black_impact = sum(1 for nb in neighbors[i] if state[nb] == 0)
        white_impact = sum(1 for p in dup_peers[i] if state[p] == 0)
        order = [2, 1] if black_impact >= white_impact else [1, 2]

        branch_results = []
        for val in order:
            new_state = state.copy()
            new_state = propagate(new_state, [(i, val)], allow_trials=True)
            if new_state is not None:
                rem = sum(1 for s in new_state if s == 0)
                branch_results.append((rem, new_state))

        branch_results.sort(key=lambda t: t[0])
        for _, next_state in branch_results:
            res = search(next_state)
            if res is not None:
                return res
        return None

    init = [0] * m
    initial_queue = []
    for i in range(m):
        if not candidate_black[i]:
            init[i] = 1
            initial_queue.append((i, 1))

    solved = search(propagate(init, initial_queue, allow_trials=True))
    if solved is None:
        return "No Solution"

    answer = []
    for r in range(n):
        row = []
        for c in range(n):
            s = solved[idx(r, c)]
            row.append("B" if s == 2 else None)
        answer.append(row)
    return answer


