from functools import lru_cache


def solve(observation):
    data = observation["data"]
    n = len(data)
    full_mask = (1 << n) - 1
    less_than_mask = [0] * (n + 2)   # values < k
    greater_than_mask = [0] * (n + 2)  # values > k
    range_mask = [[0] * (n + 2) for _ in range(n + 2)]
    for k in range(1, n + 2):
        less_than_mask[k] = (1 << (k - 1)) - 1
    for k in range(0, n + 1):
        greater_than_mask[k] = full_mask & ~((1 << k) - 1)
    for lo in range(1, n + 1):
        acc = 0
        for hi in range(lo, n + 1):
            acc |= 1 << (hi - 1)
            range_mask[lo][hi] = acc

    def parse_key(key):
        if isinstance(key, tuple):
            return key
        s = key.strip()
        if s[0] == "(" and s[-1] == ")":
            s = s[1:-1]
        a, b = s.split(",")
        return float(a), float(b)

    def bit_to_value(bit):
        return bit.bit_length()

    def min_value(mask):
        return (mask & -mask).bit_length()

    def max_value(mask):
        return mask.bit_length()

    def iter_bits(mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask ^= bit

    def build_model(horizontal_standard=True, caret_means_top_less=True):
        cell_count = n * n
        row_units = [[r * n + c for c in range(n)] for r in range(n)]
        col_units = [[r * n + c for r in range(n)] for c in range(n)]
        units = row_units + col_units

        direct_adj = [set() for _ in range(cell_count)]
        succ = [[] for _ in range(cell_count)]
        indeg = [0] * cell_count

        def add_less(a, b):
            if a == b:
                return False
            succ[a].append(b)
            indeg[b] += 1
            direct_adj[a].add(b)
            direct_adj[b].add(a)
            return True

        for k, sym in observation.get("horizontal", {}).items():
            r, cc = parse_key(k)
            r = int(r)
            c = int(cc)
            left = r * n + c
            right = r * n + (c + 1)
            if horizontal_standard:
                left_less = (sym == "<")
            else:
                left_less = (sym == ">")
            if left_less:
                add_less(left, right)
            else:
                add_less(right, left)

        for k, sym in observation.get("vertical", {}).items():
            rr, c = parse_key(k)
            r = int(rr)
            c = int(c)
            top = r * n + c
            bottom = (r + 1) * n + c
            if caret_means_top_less:
                top_less = (sym == "^")
            else:
                top_less = (sym == "v")
            if top_less:
                add_less(top, bottom)
            else:
                add_less(bottom, top)

        # Kahn topo sort for cycle detection in inequality graph.
        q = [i for i in range(cell_count) if indeg[i] == 0]
        topo = []
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            topo.append(u)
            for v in succ[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        if len(topo) != cell_count:
            return None

        pred = [[] for _ in range(cell_count)]
        for u in range(cell_count):
            for v in succ[u]:
                pred[v].append(u)

        # Static chain bounds: longest predecessor/successor paths.
        longest_pred = [0] * cell_count
        for u in topo:
            base = longest_pred[u] + 1
            for v in succ[u]:
                if base > longest_pred[v]:
                    longest_pred[v] = base

        longest_succ = [0] * cell_count
        for u in reversed(topo):
            best = 0
            for v in succ[u]:
                cand = longest_succ[v] + 1
                if cand > best:
                    best = cand
            longest_succ[u] = best

        static_mask = [full_mask] * cell_count
        for i in range(cell_count):
            lo = 1 + longest_pred[i]
            hi = n - longest_succ[i]
            if lo > hi:
                return None
            static_mask[i] = range_mask[lo][hi]

        # Transitive closure for stronger inequality pruning.
        reach = [0] * cell_count
        for u in reversed(topo):
            mask = 0
            for v in succ[u]:
                mask |= (1 << v) | reach[v]
            reach[u] = mask

        closure_edges = []
        for u in range(cell_count):
            m = reach[u]
            while m:
                lb = m & -m
                v = lb.bit_length() - 1
                closure_edges.append((u, v))
                m ^= lb

        peer_sets = []
        for r in range(n):
            row = set(row_units[r])
            for c in range(n):
                idx = r * n + c
                peers = (row | set(col_units[c])) - {idx}
                peers |= direct_adj[idx]
                peer_sets.append(peers)

        degree = [len(peer_sets[i]) for i in range(cell_count)]

        return {
            "units": units,
            "closure_edges": closure_edges,
            "static_mask": static_mask,
            "peer_sets": peer_sets,
            "degree": degree,
        }

    def solve_with_model(model):
        units = model["units"]
        closure_edges = model["closure_edges"]
        static_mask = model["static_mask"]
        peer_sets = model["peer_sets"]
        degree = model["degree"]

        @lru_cache(maxsize=None)
        def unit_supported(state):
            # Exact-cover support per row/column:
            # every remaining candidate must appear in at least one full Latin assignment.
            size = len(state)
            subset_count = 1 << n

            fw_lists = [None] * (size + 1)
            fw_seen = [None] * (size + 1)
            seen0 = bytearray(subset_count)
            seen0[0] = 1
            fw_seen[0] = seen0
            fw_lists[0] = [0]

            for i in range(size):
                dom = state[i]
                prev = fw_lists[i]
                seen = bytearray(subset_count)
                new = []
                for used in prev:
                    avail = dom & (full_mask ^ used)
                    while avail:
                        bit = avail & -avail
                        nxt = used | bit
                        if not seen[nxt]:
                            seen[nxt] = 1
                            new.append(nxt)
                        avail ^= bit
                if not new:
                    return None
                fw_seen[i + 1] = seen
                fw_lists[i + 1] = new

            if not fw_seen[size][full_mask]:
                return None

            bw_lists = [None] * (size + 1)
            bw_seen = [None] * (size + 1)
            seen_end = bytearray(subset_count)
            seen_end[0] = 1
            bw_seen[size] = seen_end
            bw_lists[size] = [0]

            for i in range(size - 1, -1, -1):
                dom = state[i]
                prev = bw_lists[i + 1]
                seen = bytearray(subset_count)
                new = []
                for used in prev:
                    avail = dom & (full_mask ^ used)
                    while avail:
                        bit = avail & -avail
                        nxt = used | bit
                        if not seen[nxt]:
                            seen[nxt] = 1
                            new.append(nxt)
                        avail ^= bit
                if not new:
                    return None
                bw_seen[i] = seen
                bw_lists[i] = new

            supported = [0] * size
            for i in range(size):
                dom = state[i]
                sup = 0
                for pref in fw_lists[i]:
                    avail = dom & (full_mask ^ pref)
                    while avail:
                        bit = avail & -avail
                        need = full_mask ^ (pref | bit)
                        if bw_seen[i + 1][need]:
                            sup |= bit
                        avail ^= bit
                    if sup == dom:
                        break
                if not sup:
                    return None
                supported[i] = sup

            return tuple(supported)

        def propagate(domains):
            # Apply static masks immediately.
            for i in range(n * n):
                nd = domains[i] & static_mask[i]
                if nd != domains[i]:
                    if nd == 0:
                        return False
                    domains[i] = nd

            changed = True
            while changed:
                changed = False

                # Inequality arc pruning over transitive closure.
                for a, b in closure_edges:
                    ma = domains[a]
                    mb = domains[b]

                    new_a = ma & less_than_mask[max_value(mb)]
                    if new_a != ma:
                        if new_a == 0:
                            return False
                        domains[a] = new_a
                        ma = new_a
                        changed = True

                    new_b = mb & greater_than_mask[min_value(ma)]
                    if new_b != mb:
                        if new_b == 0:
                            return False
                        domains[b] = new_b
                        changed = True

                # Row/column exact-cover filtering.
                for unit in units:
                    state = tuple(domains[idx] for idx in unit)
                    supported = unit_supported(state)
                    if supported is None:
                        return False
                    for idx, sup in zip(unit, supported):
                        nd = domains[idx] & sup
                        if nd != domains[idx]:
                            if nd == 0:
                                return False
                            domains[idx] = nd
                            changed = True

            return True

        def solved(domains):
            return all(d and not (d & (d - 1)) for d in domains)

        def choose_cell(domains):
            best_idx = -1
            best_size = n + 1
            best_deg = -1
            for i, d in enumerate(domains):
                bc = d.bit_count()
                if 1 < bc < best_size:
                    best_size = bc
                    best_idx = i
                    best_deg = degree[i]
                elif bc == best_size and bc > 1 and degree[i] > best_deg:
                    best_idx = i
                    best_deg = degree[i]
            return best_idx

        def order_values(domains, idx):
            dom = domains[idx]
            peers = peer_sets[idx]
            scored = []
            for bit in iter_bits(dom):
                # Prefer values that are rarer among peers/units.
                score = 0
                for p in peers:
                    if domains[p] & bit:
                        score += 1
                scored.append((score, bit_to_value(bit), bit))
            scored.sort()
            return [bit for _, _, bit in scored]

        def dfs(domains):
            if not propagate(domains):
                return None
            if solved(domains):
                return domains

            idx = choose_cell(domains)
            if idx < 0:
                return None

            for bit in order_values(domains, idx):
                new_domains = domains[:]
                new_domains[idx] = bit
                result = dfs(new_domains)
                if result is not None:
                    return result
            return None

        domains = [full_mask] * (n * n)
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    domains[r * n + c] = 1 << (v - 1)

        result = dfs(domains)
        if result is None:
            return None

        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                row.append(bit_to_value(result[r * n + c]))
            grid.append(row)
        return grid

    # Try all plausible sign conventions; return the first valid solved grid.
    # This makes the solver robust to differing image/publisher conventions.
    tried = []
    for horizontal_standard in (True, False):
        for caret_means_top_less in (True, False):
            model = build_model(horizontal_standard, caret_means_top_less)
            if model is None:
                continue
            grid = solve_with_model(model)
            if grid is not None:
                s = str(grid)
                if s not in tried:
                    tried.append(s)
                    return s

    return "No Solution"


