def solve(observation):
    data = observation["data"]
    n = len(data)
    total = n * n
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def rc_to_i(r, c):
        return r * n + c

    def i_to_rc(i):
        return divmod(i, n)

    neighbors = [[] for _ in range(total)]
    for r in range(n):
        for c in range(n):
            i = rc_to_i(r, c)
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    neighbors[i].append(rc_to_i(rr, cc))

    is_clue = [False] * total
    clue_num = [None] * total
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if isinstance(v, int):
                i = rc_to_i(r, c)
                is_clue[i] = True
                clue_num[i] = v

    clues = []
    occurrences = [[] for _ in range(total)]
    participation = [0] * total
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if not isinstance(v, int):
                continue
            src = rc_to_i(r, c)
            rays = []
            clue_id = len(clues)
            for d, (dr, dc) in enumerate(dirs):
                ray = []
                rr, cc = r + dr, c + dc
                pos = 1
                while 0 <= rr < n and 0 <= cc < n:
                    j = rc_to_i(rr, cc)
                    ray.append(j)
                    occurrences[j].append((clue_id, d, pos))
                    participation[j] += 1
                    rr += dr
                    cc += dc
                    pos += 1
                rays.append(tuple(ray))
            clues.append({"id": clue_id, "idx": src, "value": v, "rays": tuple(rays)})

    initial = [UNKNOWN] * total
    for i in range(total):
        if is_clue[i]:
            initial[i] = WHITE

    def assign(state, i, val, queue):
        cur = state[i]
        if cur == val:
            return False
        if cur != UNKNOWN:
            raise Contradiction
        if val == BLACK:
            if is_clue[i]:
                raise Contradiction
            for nb in neighbors[i]:
                if state[nb] == BLACK:
                    raise Contradiction
        state[i] = val
        queue.append(i)
        return True

    def allowed_lengths(state, ray):
        # Human-style line reasoning:
        # choose how many cells are visible on one ray;
        # prefix cells must be white, next cell (if any) must be black.
        L = len(ray)
        res = []
        prefix_ok = True
        for k in range(L + 1):
            if not prefix_ok:
                break
            if k < L:
                blocker = ray[k]
                if state[blocker] != WHITE:
                    res.append(k)
            else:
                res.append(L)
            if k < L and state[ray[k]] == BLACK:
                prefix_ok = False
        return res

    def feasible_tuples(state, clue):
        allowed = [allowed_lengths(state, ray) for ray in clue["rays"]]
        if any(len(a) == 0 for a in allowed):
            return []

        target = clue["value"] - 1
        mins = [min(a) for a in allowed]
        maxs = [max(a) for a in allowed]
        if sum(mins) > target or sum(maxs) < target:
            return []

        suffix_min = [0] * 5
        suffix_max = [0] * 5
        for d in range(3, -1, -1):
            suffix_min[d] = suffix_min[d + 1] + mins[d]
            suffix_max[d] = suffix_max[d + 1] + maxs[d]

        out = []
        cur = [0, 0, 0, 0]

        def bt(d, rem):
            if d == 4:
                if rem == 0:
                    out.append(tuple(cur))
                return
            for k in allowed[d]:
                rem2 = rem - k
                if rem2 < suffix_min[d + 1] or rem2 > suffix_max[d + 1]:
                    continue
                cur[d] = k
                bt(d + 1, rem2)

        bt(0, target)
        return out

    def bfs_passable(state, start, banned=-1):
        seen = set()
        if start == banned or state[start] == BLACK:
            return seen
        dq = deque([start])
        seen.add(start)
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if v == banned or state[v] == BLACK or v in seen:
                    continue
                seen.add(v)
                dq.append(v)
        return seen

    def connectivity_rules(state, queue):
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return

        seen = bfs_passable(state, whites[0])
        for w in whites:
            if w not in seen:
                raise Contradiction

        # If an undecided cell is a mandatory bridge between known-white cells,
        # it must stay white.
        if len(whites) >= 2:
            comp_unknowns = [i for i in seen if state[i] == UNKNOWN]
            whites_tail = whites[1:]
            for u in comp_unknowns:
                deg = 0
                for nb in neighbors[u]:
                    if state[nb] != BLACK and nb in seen:
                        deg += 1
                if deg < 2:
                    continue
                seen2 = bfs_passable(state, whites[0], banned=u)
                for w in whites_tail:
                    if w not in seen2:
                        assign(state, u, WHITE, queue)
                        break

    def propagate(state, queue=None):
        if queue is None:
            queue = []
        while True:
            progress = False

            while queue:
                i = queue.pop()
                if state[i] == BLACK:
                    for nb in neighbors[i]:
                        if not is_clue[nb]:
                            if assign(state, nb, WHITE, queue):
                                progress = True

            tuples_by_clue = {}
            for clue in clues:
                tups = feasible_tuples(state, clue)
                if not tups:
                    raise Contradiction
                tuples_by_clue[clue["id"]] = tups

                for d, ray in enumerate(clue["rays"]):
                    if not ray:
                        continue
                    vals = [t[d] for t in tups]
                    mn = min(vals)
                    mx = max(vals)

                    for j in range(mn):
                        if assign(state, ray[j], WHITE, queue):
                            progress = True

                    if mn == mx and mn < len(ray):
                        if assign(state, ray[mn], BLACK, queue):
                            progress = True

            before_q = len(queue)
            connectivity_rules(state, queue)
            if len(queue) != before_q:
                progress = True

            if not progress and not queue:
                return tuples_by_clue

    def verify(state):
        if any(v == UNKNOWN for v in state):
            return False

        for i, v in enumerate(state):
            if v == BLACK:
                if is_clue[i]:
                    return False
                for nb in neighbors[i]:
                    if state[nb] == BLACK:
                        return False

        whites = [i for i, v in enumerate(state) if v != BLACK]
        if whites:
            seen = bfs_passable(state, whites[0])
            if len(seen) != len(whites):
                return False

        for clue in clues:
            cnt = 1
            for ray in clue["rays"]:
                for cell in ray:
                    if state[cell] == BLACK:
                        break
                    cnt += 1
            if cnt != clue["value"]:
                return False

        return True

    dead = set()

    def choose_cell(state, tuples_by_clue):
        best_i = None
        best_score = None
        best_order = (WHITE, BLACK)

        for i, v in enumerate(state):
            if v != UNKNOWN:
                continue

            support_white = 0
            support_black = 0
            for clue_id, d, pos in occurrences[i]:
                tups = tuples_by_clue[clue_id]
                for t in tups:
                    k = t[d]
                    if k >= pos:
                        support_white += 1
                    if k == pos - 1:
                        support_black += 1

            score = (
                10 * participation[i]
                + 3 * sum(state[nb] == WHITE for nb in neighbors[i])
                + 2 * sum(state[nb] == UNKNOWN for nb in neighbors[i])
                + support_white
                + support_black
            )

            if best_score is None or score > best_score:
                best_score = score
                best_i = i
                if support_black > support_white:
                    best_order = (BLACK, WHITE)
                else:
                    best_order = (WHITE, BLACK)

        return best_i, best_order

    def apply_tuple(state, clue, tup):
        new_state = state[:]
        q = []
        for d, ray in enumerate(clue["rays"]):
            k = tup[d]
            for j in range(k):
                assign(new_state, ray[j], WHITE, q)
            if k < len(ray):
                assign(new_state, ray[k], BLACK, q)
        return new_state, q

    def search(state, queue=None):
        try:
            tuples_by_clue = propagate(state, [] if queue is None else list(queue))
        except Contradiction:
            return None

        key = tuple(state)
        if key in dead:
            return None

        if UNKNOWN not in state:
            if verify(state):
                return state
            dead.add(key)
            return None

        best_clue = None
        best_tups = None
        for clue in clues:
            tups = tuples_by_clue[clue["id"]]
            if len(tups) > 1 and (best_tups is None or len(tups) < len(best_tups)):
                best_clue = clue
                best_tups = tups

        if best_tups is not None and len(best_tups) <= 4:
            def tuple_strength(t):
                score = 0
                for d, ray in enumerate(best_clue["rays"]):
                    if t[d] < len(ray):
                        score += 2
                    score += t[d]
                return -score

            for tup in sorted(best_tups, key=tuple_strength):
                try:
                    new_state, q = apply_tuple(state, best_clue, tup)
                except Contradiction:
                    continue
                res = search(new_state, q)
                if res is not None:
                    return res
        else:
            cell, order = choose_cell(state, tuples_by_clue)
            for val in order:
                new_state = state[:]
                q = []
                try:
                    assign(new_state, cell, val, q)
                except Contradiction:
                    continue
                res = search(new_state, q)
                if res is not None:
                    return res

        dead.add(key)
        return None

    result = search(initial[:], [])
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            i = rc_to_i(r, c)
            if is_clue[i]:
                row.append(clue_num[i])
            elif result[i] == BLACK:
                row.append('B')
            else:
                row.append(None)
        out.append(row)
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[5, 1, 2, 8, 7, 1, 4, 9, 8, 9], [8, 2, 10, 4, 9, 3, 6, 9, 1, 8], [1, 7, 7, 8, 4, 4, 9, 2, 9, 5], [4, 6, 9, 4, 8, 2, 9, 3, 6, 8], [6, 9, 1, 7, 9, 8, 2, 2, 5, 3], [1, 6, 3, 9, 1, 3, 8, 7, 8, 4], [9, 5, 7, 10, 5, 1, 4, 10, 4, 1], [8, 3, 1, 6, 2, 9, 5, 1, 5, 9], [9, 4, 5, 10, 8, 9, 10, 8, 3, 1], [3, 5, 10, 1, 4, 7, 10, 1, 9, 3]]}

from collections import deque

UNK = 0
WHITE = 1
BLACK = 2


def build_context(data):
    n = len(data)
    m = len(data[0]) if n else 0
    size = n * m

    def idx(r, c):
        return r * m + c

    neighbors = [[] for _ in range(size)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < m:
                neighbors[i].append(idx(r, c + 1))

    peers = [set() for _ in range(size)]

    for r in range(n):
        by_val = {}
        for c in range(m):
            by_val.setdefault(data[r][c], []).append(idx(r, c))
        for cells in by_val.values():
            if len(cells) > 1:
                for i in cells:
                    peers[i].update(j for j in cells if j != i)

    for c in range(m):
        by_val = {}
        for r in range(n):
            by_val.setdefault(data[r][c], []).append(idx(r, c))
        for cells in by_val.values():
            if len(cells) > 1:
                for i in cells:
                    peers[i].update(j for j in cells if j != i)

    peers = [tuple(sorted(s)) for s in peers]

    return {
        'data': data,
        'n': n,
        'm': m,
        'size': size,
        'neighbors': neighbors,
        'peers': peers,
    }


def connected_whites_possible(state, ctx):
    white_cells = [i for i, s in enumerate(state) if s == WHITE]
    if len(white_cells) <= 1:
        return True

    start = white_cells[0]
    seen = [False] * ctx['size']
    dq = deque([start])
    seen[start] = True

    while dq:
        u = dq.popleft()
        for v in ctx['neighbors'][u]:
            if not seen[v] and state[v] != BLACK:
                seen[v] = True
                dq.append(v)

    for w in white_cells:
        if not seen[w]:
            return False
    return True


def forced_whites_by_cut(state, ctx):
    white_cells = [i for i, s in enumerate(state) if s == WHITE]
    if len(white_cells) <= 1:
        return []

    size = ctx['size']
    neighbors = ctx['neighbors']
    start = white_cells[0]

    # Current reachable component containing all already-white cells.
    comp = [False] * size
    dq = deque([start])
    comp[start] = True
    while dq:
        u = dq.popleft()
        for v in neighbors[u]:
            if not comp[v] and state[v] != BLACK:
                comp[v] = True
                dq.append(v)

    forced = []

    for cut in range(size):
        if state[cut] != UNK or not comp[cut]:
            continue

        # A leaf in the current passable graph cannot disconnect multiple whites.
        deg = 0
        for v in neighbors[cut]:
            if comp[v] and state[v] != BLACK:
                deg += 1
        if deg < 2:
            continue

        # BFS among passable cells excluding 'cut'.
        start2 = None
        for w in white_cells:
            if w != cut:
                start2 = w
                break
        if start2 is None:
            continue

        seen = [False] * size
        dq = deque([start2])
        seen[start2] = True

        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if v == cut:
                    continue
                if not seen[v] and state[v] != BLACK:
                    seen[v] = True
                    dq.append(v)

        ok = True
        for w in white_cells:
            if w != cut and not seen[w]:
                ok = False
                break
        if not ok:
            forced.append(cut)

    return forced


def basic_closure(state, ctx):
    size = ctx['size']
    neighbors = ctx['neighbors']
    peers = ctx['peers']

    changed = True
    while changed:
        changed = False

        # Direct implications from decided cells.
        for i in range(size):
            s = state[i]
            if s == BLACK:
                for j in neighbors[i]:
                    if state[j] == BLACK:
                        return None
                    if state[j] == UNK:
                        state[j] = WHITE
                        changed = True
            elif s == WHITE:
                for j in peers[i]:
                    if state[j] == WHITE:
                        return None
                    if state[j] == UNK:
                        state[j] = BLACK
                        changed = True

        # Safe normalization:
        # if a cell has no remaining same-value peer that could stay white,
        # it can always be white.
        for i in range(size):
            if state[i] == WHITE:
                continue
            all_peer_black = True
            for j in peers[i]:
                if state[j] != BLACK:
                    all_peer_black = False
                    break
            if all_peer_black and state[i] == UNK:
                state[i] = WHITE
                changed = True

        # Quick consistency: existing whites must still be connectable.
        if not connected_whites_possible(state, ctx):
            return None

        # Connectivity forcing: cells that are mandatory bridges between whites.
        forced = forced_whites_by_cut(state, ctx)
        for i in forced:
            if state[i] == BLACK:
                return None
            if state[i] == UNK:
                state[i] = WHITE
                changed = True

    return state


def candidate_cells(state, ctx):
    peers = ctx['peers']
    neighbors = ctx['neighbors']
    cand = []
    for i, s in enumerate(state):
        if s != UNK:
            continue
        open_peers = 0
        for j in peers[i]:
            if state[j] != BLACK:
                open_peers += 1
        open_neighbors = 0
        black_neighbors = 0
        for j in neighbors[i]:
            if state[j] == UNK:
                open_neighbors += 1
            elif state[j] == BLACK:
                black_neighbors += 1
        cand.append((-(3 * open_peers + open_neighbors), -black_neighbors, i))
    cand.sort()
    return [i for _, _, i in cand]


def propagate(state, ctx, do_lookahead=True):
    state = basic_closure(state, ctx)
    if state is None or not do_lookahead:
        return state

    while True:
        progress = False
        for i in candidate_cells(state, ctx):
            if state[i] != UNK:
                continue

            bad_black = False
            bad_white = False

            t_black = state[:]
            t_black[i] = BLACK
            t_black = basic_closure(t_black, ctx)
            if t_black is None:
                bad_black = True

            t_white = state[:]
            t_white[i] = WHITE
            t_white = basic_closure(t_white, ctx)
            if t_white is None:
                bad_white = True

            if bad_black and bad_white:
                return None
            if bad_black:
                state[i] = WHITE
                state = basic_closure(state, ctx)
                if state is None:
                    return None
                progress = True
                break
            if bad_white:
                state[i] = BLACK
                state = basic_closure(state, ctx)
                if state is None:
                    return None
                progress = True
                break

        if not progress:
            return state


def choose_branch_cell(state, ctx):
    cands = candidate_cells(state, ctx)
    return cands[0] if cands else None


def verify_solution(state, ctx):
    n = ctx['n']
    m = ctx['m']
    data = ctx['data']
    neighbors = ctx['neighbors']

    if any(s == UNK for s in state):
        return False

    for i, s in enumerate(state):
        if s == BLACK:
            for j in neighbors[i]:
                if state[j] == BLACK:
                    return False

    for r in range(n):
        seen = set()
        for c in range(m):
            i = r * m + c
            if state[i] != BLACK:
                v = data[r][c]
                if v in seen:
                    return False
                seen.add(v)

    for c in range(m):
        seen = set()
        for r in range(n):
            i = r * m + c
            if state[i] != BLACK:
                v = data[r][c]
                if v in seen:
                    return False
                seen.add(v)

    whites = [i for i, s in enumerate(state) if s == WHITE]
    if not whites:
        return False

    seen = [False] * ctx['size']
    dq = deque([whites[0]])
    seen[whites[0]] = True
    while dq:
        u = dq.popleft()
        for v in neighbors[u]:
            if not seen[v] and state[v] == WHITE:
                seen[v] = True
                dq.append(v)

    return all(seen[w] for w in whites)


def state_to_mask(state, ctx):
    n = ctx['n']
    m = ctx['m']
    out = []
    for r in range(n):
        row = []
        for c in range(m):
            i = r * m + c
            row.append('B' if state[i] == BLACK else None)
        out.append(row)
    return out


def solve(observation):
    data = observation['data']
    ctx = build_context(data)
    failed = set()

    def dfs(state):
        state = propagate(state, ctx, do_lookahead=True)
        if state is None:
            return None

        key = tuple(state)
        if key in failed:
            return None

        if all(s != UNK for s in state):
            if verify_solution(state, ctx):
                return state
            failed.add(key)
            return None

        i = choose_branch_cell(state, ctx)
        if i is None:
            failed.add(key)
            return None

        branches = []

        for color in (BLACK, WHITE):
            trial = state[:]
            trial[i] = color
            trial = basic_closure(trial, ctx)
            if trial is not None:
                remaining = sum(1 for s in trial if s == UNK)
                branches.append((remaining, trial))

        branches.sort(key=lambda x: x[0])

        for _, trial in branches:
            res = dfs(trial)
            if res is not None:
                return res

        failed.add(key)
        return None

    initial = [UNK] * ctx['size']
    result = dfs(initial)
    if result is None:
        return "No Solution"
    return state_to_mask(result, ctx)


