    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, 2, None], [None, None, 4, None, None, None, None], [None, 1, None, None, None, 4, None], [None, None, None, None, 4, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, None, None, None]]}

from collections import deque

def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0

    clues = []
    clue_at = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                idx = len(clues)
                clues.append((r, c, data[r][c]))
                clue_at[(r, c)] = idx

    m = len(clues)
    BLACK = 1 << m
    ALL_CLUES = BLACK - 1
    bit_of = [1 << i for i in range(m)]
    idx_of_bit = {1 << i: i for i in range(m)}
    targets = [clues[i][2] for i in range(m)]

    nbrs = {}
    for r in range(h):
        for c in range(w):
            arr = []
            if r > 0:
                arr.append((r - 1, c))
            if r + 1 < h:
                arr.append((r + 1, c))
            if c > 0:
                arr.append((r, c - 1))
            if c + 1 < w:
                arr.append((r, c + 1))
            nbrs[(r, c)] = arr

    def popcount(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def clone(dom):
        return [row[:] for row in dom]

    def set_domain(dom, r, c, newmask):
        old = dom[r][c]
        if newmask == old:
            return False
        if newmask == 0:
            raise ValueError
        dom[r][c] = newmask
        return True

    def remove_bits(dom, r, c, rem):
        old = dom[r][c]
        new = old & ~rem
        if new == old:
            return False
        if new == 0:
            raise ValueError
        dom[r][c] = new
        return True

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def is_fixed_black(mask):
        return mask == BLACK

    def is_fixed_clue(mask):
        return mask != BLACK and is_single(mask)

    def white_bits(mask):
        return mask & ALL_CLUES

    def has_black(mask):
        return (mask & BLACK) != 0

    def initial_domains():
        dom = [[0] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if (r, c) in clue_at:
                    dom[r][c] = bit_of[clue_at[(r, c)]]
                else:
                    mask = BLACK
                    for i, (cr, cc, sz) in enumerate(clues):
                        if abs(r - cr) + abs(c - cc) < sz:
                            mask |= bit_of[i]
                    dom[r][c] = mask
        return dom

    def clue_reachable_cells(dom, i):
        bit = bit_of[i]
        sr, sc, _ = clues[i]
        if not (dom[sr][sc] & bit):
            return None
        q = deque([(sr, sc)])
        seen = {(sr, sc)}
        while q:
            r, c = q.popleft()
            for nr, nc in nbrs[(r, c)]:
                if (nr, nc) not in seen and (dom[nr][nc] & bit):
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return seen

    def fixed_clue_cells(dom, bit):
        out = []
        for r in range(h):
            for c in range(w):
                if dom[r][c] == bit:
                    out.append((r, c))
        return out

    def connected_count(cells, start):
        cells = set(cells)
        if start not in cells:
            return 0
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in nbrs[(r, c)]:
                if (nr, nc) in cells and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return len(seen)

    def black_component(dom):
        capable = {(r, c) for r in range(h) for c in range(w) if has_black(dom[r][c])}
        fixed = {(r, c) for r in range(h) for c in range(w) if is_fixed_black(dom[r][c])}
        return capable, fixed

    def black_reachable_from(dom, start, blocked=None):
        capable = {(r, c) for r in range(h) for c in range(w) if has_black(dom[r][c])}
        if blocked is not None:
            capable.discard(blocked)
        if start not in capable:
            return set()
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in nbrs[(r, c)]:
                if (nr, nc) in capable and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return seen

    def deterministic_propagate(dom):
        changed_any = False
        changed = True
        while changed:
            changed = False

            # Cells with no white option become black.
            for r in range(h):
                for c in range(w):
                    mask = dom[r][c]
                    if mask == 0:
                        return None, changed_any
                    if white_bits(mask) == 0:
                        if mask != BLACK:
                            try:
                                if set_domain(dom, r, c, BLACK):
                                    changed = True
                                    changed_any = True
                            except ValueError:
                                return None, changed_any

            # Adjacent definitely-white cells must share the same clue id.
            # If one side is definitely white, the other side can only be black or that same white-id set.
            for r in range(h):
                for c in range(w):
                    for nr, nc in nbrs[(r, c)]:
                        if (nr, nc) < (r, c):
                            continue
                        a = dom[r][c]
                        b = dom[nr][nc]
                        aw = white_bits(a)
                        bw = white_bits(b)
                        ab = has_black(a)
                        bb = has_black(b)

                        if not ab and not bb:
                            inter = aw & bw
                            if inter == 0:
                                return None, changed_any
                            if a != inter:
                                try:
                                    if set_domain(dom, r, c, inter):
                                        changed = True
                                        changed_any = True
                                except ValueError:
                                    return None, changed_any
                            if b != inter:
                                try:
                                    if set_domain(dom, nr, nc, inter):
                                        changed = True
                                        changed_any = True
                                except ValueError:
                                    return None, changed_any
                        elif not ab:
                            newb = (BLACK if bb else 0) | (bw & aw)
                            if newb == 0:
                                return None, changed_any
                            if newb != b:
                                try:
                                    if set_domain(dom, nr, nc, newb):
                                        changed = True
                                        changed_any = True
                                except ValueError:
                                    return None, changed_any
                        elif not bb:
                            newa = (BLACK if ab else 0) | (aw & bw)
                            if newa == 0:
                                return None, changed_any
                            if newa != a:
                                try:
                                    if set_domain(dom, r, c, newa):
                                        changed = True
                                        changed_any = True
                                except ValueError:
                                    return None, changed_any

            # Connected components of definitely-white cells must all share one clue id.
            seen = set()
            for r in range(h):
                for c in range(w):
                    if (r, c) in seen or has_black(dom[r][c]):
                        continue
                    q = deque([(r, c)])
                    comp = []
                    seen.add((r, c))
                    common = white_bits(dom[r][c])
                    while q:
                        x, y = q.popleft()
                        comp.append((x, y))
                        common &= white_bits(dom[x][y])
                        for nx, ny in nbrs[(x, y)]:
                            if (nx, ny) not in seen and not has_black(dom[nx][ny]):
                                seen.add((nx, ny))
                                q.append((nx, ny))
                    # A white component of size s can only belong to clues with target >= s.
                    size = len(comp)
                    valid_common = 0
                    for b in iter_bits(common):
                        if targets[idx_of_bit[b]] >= size:
                            valid_common |= b
                    common = valid_common
                    if common == 0:
                        return None, changed_any
                    for x, y in comp:
                        if dom[x][y] != common:
                            try:
                                if set_domain(dom, x, y, common):
                                    changed = True
                                    changed_any = True
                            except ValueError:
                                return None, changed_any
                    if is_single(common):
                        i = idx_of_bit[common]
                        if size > targets[i]:
                            return None, changed_any
                        if size == targets[i]:
                            comp_set = set(comp)
                            for x, y in comp:
                                for nx, ny in nbrs[(x, y)]:
                                    if (nx, ny) not in comp_set and (dom[nx][ny] & common):
                                        try:
                                            if remove_bits(dom, nx, ny, common):
                                                changed = True
                                                changed_any = True
                                        except ValueError:
                                            return None, changed_any

            # Clue-specific reachability and completion.
            for i, (cr, cc, target) in enumerate(clues):
                bit = bit_of[i]
                if dom[cr][cc] != bit:
                    return None, changed_any

                reached = clue_reachable_cells(dom, i)
                if reached is None:
                    return None, changed_any

                # Remove disconnected appearances of this clue id.
                for r in range(h):
                    for c in range(w):
                        if (dom[r][c] & bit) and (r, c) not in reached:
                            try:
                                if remove_bits(dom, r, c, bit):
                                    changed = True
                                    changed_any = True
                            except ValueError:
                                return None, changed_any

                if len(reached) < target:
                    return None, changed_any

                fixed = [(r, c) for r in range(h) for c in range(w) if dom[r][c] == bit]
                if len(fixed) > target:
                    return None, changed_any

                if len(fixed) == target:
                    if connected_count(fixed, (cr, cc)) != target:
                        return None, changed_any
                    for r in range(h):
                        for c in range(w):
                            if dom[r][c] != bit and (dom[r][c] & bit):
                                try:
                                    if remove_bits(dom, r, c, bit):
                                        changed = True
                                        changed_any = True
                                except ValueError:
                                    return None, changed_any

                if len(reached) == target:
                    for r, c in reached:
                        if dom[r][c] != bit:
                            try:
                                if set_domain(dom, r, c, bit):
                                    changed = True
                                    changed_any = True
                            except ValueError:
                                return None, changed_any

            # 2x2 black rule.
            for r in range(h - 1):
                for c in range(w - 1):
                    cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                    fixed_black = [(x, y) for (x, y) in cells if dom[x][y] == BLACK]
                    if len(fixed_black) == 4:
                        return None, changed_any
                    if len(fixed_black) == 3:
                        for x, y in cells:
                            if dom[x][y] != BLACK and has_black(dom[x][y]):
                                try:
                                    if remove_bits(dom, x, y, BLACK):
                                        changed = True
                                        changed_any = True
                                except ValueError:
                                    return None, changed_any

            # Black connectivity pruning.
            capable, fixed = black_component(dom)
            if fixed:
                start = next(iter(fixed))
                reach = black_reachable_from(dom, start)
                if not fixed.issubset(reach):
                    return None, changed_any
                for r, c in list(capable - reach):
                    try:
                        if remove_bits(dom, r, c, BLACK):
                            changed = True
                            changed_any = True
                    except ValueError:
                        return None, changed_any

                # If removing a candidate-black cell disconnects existing black cells, it is forced black.
                fixed_now = {(r, c) for r in range(h) for c in range(w) if dom[r][c] == BLACK}
                if len(fixed_now) >= 2:
                    reach = black_reachable_from(dom, next(iter(fixed_now)))
                    candidates = [p for p in reach if dom[p[0]][p[1]] != BLACK and has_black(dom[p[0]][p[1]])]
                    for x in candidates:
                        start2 = next(iter(fixed_now))
                        if x == start2:
                            continue
                        seen2 = black_reachable_from(dom, start2, blocked=x)
                        if not fixed_now.issubset(seen2):
                            try:
                                if set_domain(dom, x[0], x[1], BLACK):
                                    changed = True
                                    changed_any = True
                            except ValueError:
                                return None, changed_any

        return dom, changed_any

    def propagate(dom, allow_lookahead=True):
        while True:
            res = deterministic_propagate(dom)
            if res[0] is None:
                return None
            dom, changed = res
            if changed:
                continue

            if not allow_lookahead:
                return dom

            # Limited contradiction-based lookahead on binary domains.
            progress = False
            cells = []
            for r in range(h):
                for c in range(w):
                    if popcount(dom[r][c]) == 2:
                        cells.append((r, c))
            # Most constrained first is already binary; prefer cells with a clue assignment.
            cells.sort(key=lambda p: (0 if has_black(dom[p[0]][p[1]]) else 1, p[0], p[1]))

            for r, c in cells:
                mask = dom[r][c]
                bad = 0
                for b in iter_bits(mask):
                    trial = clone(dom)
                    trial[r][c] = b
                    if propagate(trial, allow_lookahead=False) is None:
                        bad |= b
                if bad:
                    try:
                        remove_bits(dom, r, c, bad)
                    except ValueError:
                        return None
                    progress = True
                    break
            if not progress:
                return dom

    def solved(dom):
        for r in range(h):
            for c in range(w):
                if not is_single(dom[r][c]):
                    return False
        return True

    def validate(dom):
        if not solved(dom):
            return False

        # No 2x2 all black.
        for r in range(h - 1):
            for c in range(w - 1):
                if dom[r][c] == BLACK and dom[r + 1][c] == BLACK and dom[r][c + 1] == BLACK and dom[r + 1][c + 1] == BLACK:
                    return False

        # Black connected.
        black_cells = [(r, c) for r in range(h) for c in range(w) if dom[r][c] == BLACK]
        if black_cells:
            if connected_count(black_cells, black_cells[0]) != len(black_cells):
                return False

        # White cells form clue-islands with correct sizes and one clue each.
        used = set()
        for i, (cr, cc, target) in enumerate(clues):
            bit = bit_of[i]
            cells = [(r, c) for r in range(h) for c in range(w) if dom[r][c] == bit]
            if len(cells) != target:
                return False
            if connected_count(cells, (cr, cc)) != target:
                return False
            clue_count = 0
            for r, c in cells:
                if (r, c) in clue_at:
                    clue_count += 1
            if clue_count != 1:
                return False
            used.update(cells)

        for r in range(h):
            for c in range(w):
                if dom[r][c] != BLACK and (r, c) not in used:
                    return False
        return True

    def choose_branch_cell(dom):
        best = None
        best_key = None
        for r in range(h):
            for c in range(w):
                mask = dom[r][c]
                cnt = popcount(mask)
                if cnt <= 1:
                    continue
                wcnt = popcount(white_bits(mask))
                key = (cnt, 0 if has_black(mask) else 1, wcnt, r, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def ordered_values(mask, r, c):
        vals = list(iter_bits(mask))
        # Prefer clue assignment if adjacent to same fixed clue or if only one white choice.
        scored = []
        for v in vals:
            score = 0
            if v == BLACK:
                # Slightly defer black unless strongly constrained by adjacency.
                adj_fixed_white = sum(1 for nr, nc in nbrs[(r, c)] if is_fixed_clue(dom0[nr][nc]))
                score = 10 - adj_fixed_white
            else:
                i = idx_of_bit[v]
                adj_same = sum(1 for nr, nc in nbrs[(r, c)] if dom0[nr][nc] == v)
                need = targets[i]
                score = -adj_same - (5 if need <= 2 else 0)
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def search(dom):
        dom2 = propagate(dom, allow_lookahead=True)
        if dom2 is None:
            return None
        if solved(dom2):
            return dom2 if validate(dom2) else None

        cell = choose_branch_cell(dom2)
        if cell is None:
            return dom2 if validate(dom2) else None
        r, c = cell
        mask = dom2[r][c]

        # Use current board in value ordering.
        nonlocal_dom0 = dom2

        def local_ordered_values(mask2, rr, cc):
            vals = list(iter_bits(mask2))
            scored = []
            for v in vals:
                if v == BLACK:
                    adj_fixed_white = sum(1 for nr, nc in nbrs[(rr, cc)] if is_fixed_clue(nonlocal_dom0[nr][nc]))
                    score = 10 - adj_fixed_white
                else:
                    i = idx_of_bit[v]
                    adj_same = sum(1 for nr, nc in nbrs[(rr, cc)] if nonlocal_dom0[nr][nc] == v)
                    rem = targets[i] - sum(1 for x in range(h) for y in range(w) if nonlocal_dom0[x][y] == v)
                    score = -adj_same - (3 if rem <= 2 else 0)
                scored.append((score, v))
            scored.sort()
            return [v for _, v in scored]

        for v in local_ordered_values(mask, r, c):
            trial = clone(dom2)
            trial[r][c] = v
            ans = search(trial)
            if ans is not None:
                return ans
        return None

    dom0 = initial_domains()
    ans = search(dom0)
    if ans is None:
        return "No Solution"

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if ans[r][c] == BLACK else None)
        out.append(row)
    return repr(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, 4, None, None]], 'horizontal': {'(0,1.5)': '>', '(0,3.5)': '>', '(0,5.5)': '>', '(1,0.5)': '>', '(1,2.5)': '>', '(1,3.5)': '>', '(2,3.5)': '>', '(3,3.5)': '>', '(3,5.5)': '>', '(4,0.5)': '>', '(4,1.5)': '<', '(4,3.5)': '>', '(4,4.5)': '>', '(5,2.5)': '>', '(6,1.5)': '<'}, 'vertical': {'(0.5,0)': 'v', '(0.5,1)': '^', '(0.5,4)': 'v', '(1.5,6)': 'v', '(2.5,1)': 'v', '(2.5,2)': 'v', '(3.5,0)': 'v', '(3.5,1)': 'v', '(4.5,1)': 'v', '(4.5,5)': 'v', '(5.5,5)': '^', '(5.5,6)': '^'}}

import ast
from functools import lru_cache


def solve(observation):
    n = len(observation["data"])
    full = (1 << n) - 1

    def idx(r, c):
        return r * n + c

    rows = [[idx(r, c) for c in range(n)] for r in range(n)]
    cols = [[idx(r, c) for r in range(n)] for c in range(n)]
    units = rows + cols

    peers = []
    for r in range(n):
        for c in range(n):
            s = set(rows[r])
            s.update(cols[c])
            s.remove(idx(r, c))
            peers.append(tuple(s))

    def build_edges(h_reversed=False, v_mode=0):
        # h_reversed=False: '<' means left<right, '>' means left>right
        # v_mode=0: '^' means top<bottom, 'v' means top>bottom
        # v_mode=1: reversed vertical convention
        edges = []
        ineq_degree = [0] * (n * n)

        for key, sym in observation["horizontal"].items():
            r, c_half = ast.literal_eval(key)
            r = int(r)
            c = int(c_half)
            a = idx(r, c)
            b = idx(r, c + 1)
            less = (sym == "<") ^ h_reversed
            rel = -1 if less else 1  # a<b or a>b
            edges.append((a, b, rel))
            ineq_degree[a] += 1
            ineq_degree[b] += 1

        for key, sym in observation["vertical"].items():
            r_half, c = ast.literal_eval(key)
            r = int(r_half)
            c = int(c)
            a = idx(r, c)
            b = idx(r + 1, c)
            if v_mode == 0:
                less = (sym == "^")
            else:
                less = (sym == "v")
            rel = -1 if less else 1  # top<bottom or top>bottom
            edges.append((a, b, rel))
            ineq_degree[a] += 1
            ineq_degree[b] += 1

        return edges, ineq_degree

    def solve_with_convention(h_reversed=False, v_mode=0):
        edges, ineq_degree = build_edges(h_reversed, v_mode)
        degrees = [len(peers[i]) + ineq_degree[i] for i in range(n * n)]

        @lru_cache(maxsize=None)
        def feasible_sorted(masks_sorted):
            if not masks_sorted:
                return True
            first = masks_sorted[0]
            rest = masks_sorted[1:]
            m = first
            while m:
                b = m & -m
                new_rest = []
                ok = True
                for rm in rest:
                    nr = rm & ~b
                    if nr == 0:
                        ok = False
                        break
                    new_rest.append(nr)
                if ok:
                    new_rest.sort(key=lambda x: (x.bit_count(), x))
                    if feasible_sorted(tuple(new_rest)):
                        return True
                m -= b
            return False

        def unit_feasible(masks):
            if any(m == 0 for m in masks):
                return False
            ordered = tuple(sorted(masks, key=lambda x: (x.bit_count(), x)))
            return feasible_sorted(ordered)

        def prune_pair(da, db, rel):
            # rel=-1 means a<b ; rel=1 means a>b
            if rel == -1:
                while True:
                    oa, ob = da, db
                    if da == 0 or db == 0:
                        return 0, 0
                    hb = db.bit_length() - 1
                    da &= (1 << hb) - 1
                    if da == 0:
                        return 0, 0
                    la = (da & -da).bit_length() - 1
                    db &= full ^ ((1 << (la + 1)) - 1)
                    if db == 0:
                        return 0, 0
                    if da == oa and db == ob:
                        return da, db
            else:
                while True:
                    oa, ob = da, db
                    if da == 0 or db == 0:
                        return 0, 0
                    lb = (db & -db).bit_length() - 1
                    da &= full ^ ((1 << (lb + 1)) - 1)
                    if da == 0:
                        return 0, 0
                    ha = da.bit_length() - 1
                    db &= (1 << ha) - 1
                    if db == 0:
                        return 0, 0
                    if da == oa and db == ob:
                        return da, db

        def propagate(domains):
            domains = domains[:]
            changed = True

            while changed:
                changed = False

                if any(d == 0 for d in domains):
                    return None

                # Direct Latin elimination from solved cells.
                for i, d in enumerate(domains):
                    if d & (d - 1) == 0:
                        for p in peers[i]:
                            pd = domains[p]
                            if pd != d and (pd & d):
                                nd = pd & ~d
                                if nd == 0:
                                    return None
                                if nd != pd:
                                    domains[p] = nd
                                    changed = True

                # Inequality arc-consistency.
                for a, b, rel in edges:
                    da, db = domains[a], domains[b]
                    nda, ndb = prune_pair(da, db, rel)
                    if nda == 0 or ndb == 0:
                        return None
                    if nda != da:
                        domains[a] = nda
                        changed = True
                    if ndb != db:
                        domains[b] = ndb
                        changed = True

                # Row/column all-different reasoning:
                # - feasibility check
                # - hidden singles
                # - support-based candidate pruning via perfect matching tests
                for unit in units:
                    masks = [domains[i] for i in unit]
                    if not unit_feasible(tuple(masks)):
                        return None

                    new_masks = masks[:]
                    local_changed = False

                    # Hidden singles by value within the unit.
                    for bit_pos in range(n):
                        bit = 1 << bit_pos
                        places = [k for k, m in enumerate(new_masks) if m & bit]
                        if not places:
                            return None
                        if len(places) == 1 and new_masks[places[0]] != bit:
                            new_masks[places[0]] = bit
                            local_changed = True

                    # Candidate support filtering:
                    # keep only values that participate in at least one unit-perfect-matching.
                    for k, mask in enumerate(new_masks):
                        if mask == 0:
                            return None
                        if mask & (mask - 1) == 0:
                            continue
                        supported = 0
                        mm = mask
                        while mm:
                            b = mm & -mm
                            test_masks = list(new_masks)
                            test_masks[k] = b
                            if unit_feasible(tuple(test_masks)):
                                supported |= b
                            mm -= b
                        if supported == 0:
                            return None
                        if supported != new_masks[k]:
                            new_masks[k] = supported
                            local_changed = True

                    if local_changed:
                        for pos, cell in enumerate(unit):
                            if domains[cell] != new_masks[pos]:
                                domains[cell] = new_masks[pos]
                                changed = True

            return domains

        def order_values(cell, mask, domains):
            options = []
            mm = mask
            while mm:
                b = mm & -mm
                score = 0
                for p in peers[cell]:
                    if domains[p] & b:
                        score += 1
                options.append((score, b))
                mm -= b
            options.sort()
            return [b for _, b in options]

        def to_grid(domains):
            grid = []
            for r in range(n):
                row = []
                for c in range(n):
                    m = domains[idx(r, c)]
                    row.append(m.bit_length())
                grid.append(row)
            return grid

        def dfs(domains):
            domains = propagate(domains)
            if domains is None:
                return None

            best = -1
            best_size = n + 1
            best_degree = -1

            for i, d in enumerate(domains):
                bc = d.bit_count()
                if 1 < bc < best_size or (bc == best_size and degrees[i] > best_degree):
                    best = i
                    best_size = bc
                    best_degree = degrees[i]

            if best == -1:
                return to_grid(domains)

            for b in order_values(best, domains[best], domains):
                new_domains = domains[:]
                new_domains[best] = b
                ans = dfs(new_domains)
                if ans is not None:
                    return ans
            return None

        initial = [full] * (n * n)
        for r in range(n):
            for c in range(n):
                v = observation["data"][r][c]
                if v is not None:
                    initial[idx(r, c)] = 1 << (v - 1)

        return dfs(initial)

    # Try likely conventions first, then fallbacks.
    convention_order = [
        (False, 0),
        (False, 1),
        (True, 0),
        (True, 1),
    ]

    for h_reversed, v_mode in convention_order:
        sol = solve_with_convention(h_reversed=h_reversed, v_mode=v_mode)
        if sol is not None:
            return str(sol)

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, 5, None], [None, None, None, None, 1], [None, None, None, None, None], [1, None, 3, None, None]]}

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0
    N = n * m

    def idx(r, c):
        return r * m + c

    def rc(i):
        return divmod(i, m)

    neighbors = [[] for _ in range(N)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < m:
                neighbors[i].append(idx(r, c + 1))

    blocks = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks.append((idx(r, c), idx(r, c + 1), idx(r + 1, c), idx(r + 1, c + 1)))

    clues = []
    clue_at = {}
    for r in range(n):
        for c in range(m):
            if data[r][c] is not None:
                clue_at[idx(r, c)] = len(clues)
                clues.append((idx(r, c), data[r][c]))

    k = len(clues)
    BLACK = 1
    BITS = [1 << (i + 1) for i in range(k)]
    ALL_ISLANDS = 0
    for b in BITS:
        ALL_ISLANDS |= b

    seed_of = [p for p, _ in clues]
    size_of = [s for _, s in clues]

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def is_single_island(mask):
        return is_single(mask) and mask != BLACK

    def bit_to_island(bit):
        return bit.bit_length() - 2

    # Initial domain pruning by clue reachability:
    # a cell can belong to an island only if it is reachable from the clue
    # without passing through other clues, within at most size-1 steps.
    initial = [BLACK for _ in range(N)]
    clue_cells = set(seed_of)

    for i, (seed, target) in enumerate(clues):
        bit = BITS[i]
        dist = [-1] * N
        q = deque([seed])
        dist[seed] = 0
        while q:
            v = q.popleft()
            for nb in neighbors[v]:
                if dist[nb] != -1:
                    continue
                if nb in clue_cells and nb != seed:
                    continue
                dist[nb] = dist[v] + 1
                q.append(nb)
        for cell in range(N):
            if dist[cell] != -1 and dist[cell] < target:
                initial[cell] |= bit

    for i, seed in enumerate(seed_of):
        initial[seed] = BITS[i]

    def bfs_component(start, allowed_mask_bit, dom, exclude=-1):
        seen = [False] * N
        if start == exclude or not (dom[start] & allowed_mask_bit):
            return seen, 0
        q = deque([start])
        seen[start] = True
        count = 1
        while q:
            v = q.popleft()
            for nb in neighbors[v]:
                if nb == exclude or seen[nb]:
                    continue
                if dom[nb] & allowed_mask_bit:
                    seen[nb] = True
                    count += 1
                    q.append(nb)
        return seen, count

    def propagate(dom):
        dom = dom[:]
        while True:
            changed = False

            for i in range(N):
                if dom[i] == 0:
                    return None

            # Numbered cells are fixed white in their own island.
            for i, seed in enumerate(seed_of):
                bit = BITS[i]
                if dom[seed] != bit:
                    if dom[seed] & bit:
                        dom[seed] = bit
                        changed = True
                    else:
                        return None

            # Adjacent white cells must belong to the same island.
            # If a cell is fixed to island i, neighbors can only be black or island i.
            for cell in range(N):
                mask = dom[cell]
                if is_single_island(mask):
                    allowed = BLACK | mask
                    for nb in neighbors[cell]:
                        new_mask = dom[nb] & allowed
                        if new_mask != dom[nb]:
                            if new_mask == 0:
                                return None
                            dom[nb] = new_mask
                            changed = True

            # No 2x2 all-black blocks.
            for a, b, c, d in blocks:
                vals = (dom[a], dom[b], dom[c], dom[d])
                black_fixed = sum(1 for x in vals if x == BLACK)
                if black_fixed == 4:
                    return None
                if black_fixed == 3:
                    for cell in (a, b, c, d):
                        if dom[cell] != BLACK and (dom[cell] & BLACK):
                            new_mask = dom[cell] & ~BLACK
                            if new_mask == 0:
                                return None
                            if new_mask != dom[cell]:
                                dom[cell] = new_mask
                                changed = True

            # Island connectivity and size propagation.
            for i in range(k):
                bit = BITS[i]
                seed = seed_of[i]
                target = size_of[i]

                seen, comp_size = bfs_component(seed, bit, dom)
                assigned = 0

                for cell in range(N):
                    if dom[cell] & bit:
                        if not seen[cell]:
                            new_mask = dom[cell] & ~bit
                            if new_mask == 0:
                                return None
                            if new_mask != dom[cell]:
                                dom[cell] = new_mask
                                changed = True
                        else:
                            if dom[cell] == bit:
                                assigned += 1

                if assigned > target:
                    return None

                # Recount potential after removals to the seed-connected region only.
                potential = 0
                for cell in range(N):
                    if seen[cell] and (dom[cell] & bit):
                        potential += 1

                if potential < target:
                    return None

                # All possible cells are needed.
                if potential == target:
                    for cell in range(N):
                        if seen[cell] and (dom[cell] & bit) and dom[cell] != bit:
                            dom[cell] = bit
                            changed = True

                # Island already full: remove this island from all other cells.
                if assigned == target:
                    for cell in range(N):
                        if dom[cell] != bit and (dom[cell] & bit):
                            new_mask = dom[cell] & ~bit
                            if new_mask == 0:
                                return None
                            if new_mask != dom[cell]:
                                dom[cell] = new_mask
                                changed = True

                # Human-like bridge/corridor rule for islands:
                # if removing a candidate cell leaves too few reachable cells,
                # that cell is mandatory for the island.
                if assigned < target:
                    candidates = [cell for cell in range(N) if cell != seed and seen[cell] and (dom[cell] & bit) and dom[cell] != bit]
                    for cell in candidates:
                        seen2, cnt2 = bfs_component(seed, bit, dom, exclude=cell)
                        if cnt2 < target:
                            if dom[cell] != bit:
                                dom[cell] = bit
                                changed = True

            # Black cells must stay connectable.
            black_fixed = [cell for cell in range(N) if dom[cell] == BLACK]
            if black_fixed:
                start = black_fixed[0]
                seen, _ = bfs_component(start, BLACK, dom)
                for cell in black_fixed:
                    if not seen[cell]:
                        return None
                for cell in range(N):
                    if (dom[cell] & BLACK) and not seen[cell]:
                        new_mask = dom[cell] & ~BLACK
                        if new_mask == 0:
                            return None
                        if new_mask != dom[cell]:
                            dom[cell] = new_mask
                            changed = True

                # Human-like black bridge rule:
                # if a candidate black cell is required to keep current black cells connected,
                # force it to black.
                current_black_fixed = [cell for cell in range(N) if dom[cell] == BLACK]
                for cell in range(N):
                    if dom[cell] != BLACK and (dom[cell] & BLACK) and seen[cell]:
                        seen2, _ = bfs_component(start, BLACK, dom, exclude=cell)
                        ok = True
                        for b in current_black_fixed:
                            if b != cell and not seen2[b]:
                                ok = False
                                break
                        if not ok:
                            dom[cell] = BLACK
                            changed = True

            # Any cell with no island option must be black.
            for cell in range(N):
                if dom[cell] & ALL_ISLANDS == 0:
                    if not (dom[cell] & BLACK):
                        return None
                    if dom[cell] != BLACK:
                        dom[cell] = BLACK
                        changed = True

            # Sanity: no adjacent fixed different islands.
            for cell in range(N):
                if is_single_island(dom[cell]):
                    for nb in neighbors[cell]:
                        if is_single_island(dom[nb]) and dom[nb] != dom[cell]:
                            return None

            if not changed:
                return dom

    def validate(dom):
        if any(not is_single(x) for x in dom):
            return False

        # 2x2 rule
        for a, b, c, d in blocks:
            if dom[a] == dom[b] == dom[c] == dom[d] == BLACK:
                return False

        # Black connectivity
        blacks = [i for i in range(N) if dom[i] == BLACK]
        if blacks:
            seen = set([blacks[0]])
            q = deque([blacks[0]])
            while q:
                v = q.popleft()
                for nb in neighbors[v]:
                    if dom[nb] == BLACK and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
            if len(seen) != len(blacks):
                return False

        # Islands
        for i in range(k):
            bit = BITS[i]
            cells = [cell for cell in range(N) if dom[cell] == bit]
            if len(cells) != size_of[i]:
                return False
            if seed_of[i] not in cells:
                return False
            seen = set([seed_of[i]])
            q = deque([seed_of[i]])
            while q:
                v = q.popleft()
                for nb in neighbors[v]:
                    if dom[nb] == bit and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
            if len(seen) != len(cells):
                return False

        # No adjacent different islands
        for cell in range(N):
            if dom[cell] != BLACK:
                for nb in neighbors[cell]:
                    if dom[nb] != BLACK and dom[nb] != dom[cell]:
                        return False

        return True

    def choose_cell(dom):
        best = None
        best_key = None
        for cell in range(N):
            mask = dom[cell]
            if is_single(mask):
                continue
            domain_size = mask.bit_count()
            island_count = (mask & ALL_ISLANDS).bit_count()
            adj_fixed_islands = sum(1 for nb in neighbors[cell] if is_single_island(dom[nb]))
            key = (domain_size, island_count, -adj_fixed_islands)
            if best is None or key < best_key:
                best = cell
                best_key = key
        return best

    def order_values(cell, dom):
        mask = dom[cell]
        island_bits = [b for b in BITS if mask & b]

        assigned_counts = [0] * k
        for x in dom:
            if is_single_island(x):
                assigned_counts[bit_to_island(x)] += 1

        def island_key(bit):
            i = bit_to_island(bit)
            remain = size_of[i] - assigned_counts[i]
            adj_same = sum(1 for nb in neighbors[cell] if dom[nb] == bit)
            return (remain, -adj_same)

        island_bits.sort(key=island_key)
        has_black = bool(mask & BLACK)

        if not has_black:
            return island_bits

        # If touching multiple fixed islands, black is highly likely.
        adj_islands = {dom[nb] for nb in neighbors[cell] if is_single_island(dom[nb])}
        if len(adj_islands) >= 2:
            return [BLACK] + island_bits

        # If exactly one island candidate and it already touches that island, try growing it first.
        if len(island_bits) == 1 and any(dom[nb] == island_bits[0] for nb in neighbors[cell]):
            return [island_bits[0], BLACK]

        return island_bits + [BLACK]

    def dfs(dom):
        dom = propagate(dom)
        if dom is None:
            return None
        if all(is_single(x) for x in dom):
            return dom if validate(dom) else None

        cell = choose_cell(dom)
        if cell is None:
            return dom if validate(dom) else None

        for val in order_values(cell, dom):
            new_dom = dom[:]
            new_dom[cell] = val
            ans = dfs(new_dom)
            if ans is not None:
                return ans
        return None

    result = dfs(initial)
    if result is None:
        return "No Solution"

    answer = []
    for r in range(n):
        row = []
        for c in range(m):
            cell = idx(r, c)
            row.append('B' if result[cell] == BLACK else None)
        answer.append(row)
    return repr(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [3, 3, 0, 0, 0], 'D': [0, 0, 0, 0, 0], 'L': [2, 0, 1, 0, 0], 'R': [0, 0, 2, 2, 0]}

from itertools import permutations
from functools import lru_cache


def solve(observation):
    U = list(observation.get('U', []))
    D = list(observation.get('D', []))
    L = list(observation.get('L', []))
    R = list(observation.get('R', []))

    if not U or not (len(U) == len(D) == len(L) == len(R)):
        return "No Solution"

    N = len(U)
    if any((not isinstance(c, int)) or c < 0 or c > N for c in U + D + L + R):
        return "No Solution"

    nums = tuple(range(1, N + 1))
    perms = list(permutations(nums))
    perm_count = len(perms)
    all_perm_mask = (1 << perm_count) - 1
    value_bit = [0] + [1 << (v - 1) for v in range(1, N + 1)]

    def visible(seq):
        seen = 0
        tallest = 0
        for x in seq:
            if x > tallest:
                tallest = x
                seen += 1
        return seen

    # Precompute clue masks and position/value masks over the permutation universe.
    left_masks = [0] * (N + 1)
    right_masks = [0] * (N + 1)
    pos_val_mask = [[0] * (N + 1) for _ in range(N)]

    for idx, p in enumerate(perms):
        bit = 1 << idx
        left_masks[visible(p)] |= bit
        right_masks[visible(reversed(p))] |= bit
        for pos, v in enumerate(p):
            pos_val_mask[pos][v] |= bit

    # For each position and each value-domain bitmask, precompute which permutations fit.
    subset_pos_mask = [[0] * (1 << N) for _ in range(N)]
    for pos in range(N):
        for domain_mask in range(1 << N):
            pm = 0
            for v in range(1, N + 1):
                if domain_mask & value_bit[v]:
                    pm |= pos_val_mask[pos][v]
            subset_pos_mask[pos][domain_mask] = pm

    def initial_line_mask(front_clue, back_clue):
        mask = all_perm_mask
        if front_clue:
            mask &= left_masks[front_clue]
        if back_clue:
            mask &= right_masks[back_clue]
        return mask

    initial_rows = tuple(initial_line_mask(L[i], R[i]) for i in range(N))
    initial_cols = tuple(initial_line_mask(U[j], D[j]) for j in range(N))

    if any(m == 0 for m in initial_rows + initial_cols):
        return "No Solution"

    def line_pos_domain(line_mask, pos):
        domain = 0
        pv = pos_val_mask[pos]
        for v in range(1, N + 1):
            if line_mask & pv[v]:
                domain |= value_bit[v]
        return domain

    def propagate(rows_t, cols_t):
        # Human-like deduction:
        # 1) keep candidate line permutations consistent with side clues,
        # 2) derive per-cell possible heights from row candidates and column candidates,
        # 3) intersect them,
        # 4) remove any row/column candidate that violates those cell domains,
        # 5) repeat to a fixed point.
        rows = list(rows_t)
        cols = list(cols_t)

        while True:
            for k in range(N):
                if rows[k] == 0 or cols[k] == 0:
                    return None

            changed = False
            row_domains = [[0] * N for _ in range(N)]
            col_domains = [[0] * N for _ in range(N)]

            for i in range(N):
                rm = rows[i]
                for j in range(N):
                    row_domains[i][j] = line_pos_domain(rm, j)

            for j in range(N):
                cm = cols[j]
                for i in range(N):
                    col_domains[j][i] = line_pos_domain(cm, i)

            for i in range(N):
                for j in range(N):
                    domain = row_domains[i][j] & col_domains[j][i]
                    if domain == 0:
                        return None

                    new_row_mask = rows[i] & subset_pos_mask[j][domain]
                    if new_row_mask != rows[i]:
                        if new_row_mask == 0:
                            return None
                        rows[i] = new_row_mask
                        changed = True

                    new_col_mask = cols[j] & subset_pos_mask[i][domain]
                    if new_col_mask != cols[j]:
                        if new_col_mask == 0:
                            return None
                        cols[j] = new_col_mask
                        changed = True

            if not changed:
                domains = tuple(
                    tuple(row_domains[i][j] & col_domains[j][i] for j in range(N))
                    for i in range(N)
                )
                return tuple(rows), tuple(cols), domains

    def extract_single_perm(mask):
        bit = mask & -mask
        return bit.bit_length() - 1

    def validate(grid):
        target = set(range(1, N + 1))

        for row in grid:
            if set(row) != target:
                return False

        for j in range(N):
            col = [grid[i][j] for i in range(N)]
            if set(col) != target:
                return False
            if U[j] and visible(col) != U[j]:
                return False
            if D[j] and visible(reversed(col)) != D[j]:
                return False

        for i in range(N):
            row = grid[i]
            if L[i] and visible(row) != L[i]:
                return False
            if R[i] and visible(reversed(row)) != R[i]:
                return False

        return True

    @lru_cache(maxsize=None)
    def dfs(rows_t, cols_t):
        propagated = propagate(rows_t, cols_t)
        if propagated is None:
            return None

        rows_t, cols_t, domains = propagated

        best_cell = None
        best_size = N + 1

        for i in range(N):
            for j in range(N):
                size = domains[i][j].bit_count()
                if size > 1 and size < best_size:
                    best_size = size
                    best_cell = (i, j, domains[i][j])

        if best_cell is None:
            grid = []
            for i in range(N):
                rm = rows_t[i]
                if rm == 0 or (rm & (rm - 1)) != 0:
                    return None
                grid.append(list(perms[extract_single_perm(rm)]))
            return tuple(tuple(r) for r in grid) if validate(grid) else None

        i, j, domain = best_cell

        # Branch only on the most constrained cell.
        remaining = domain
        while remaining:
            bit = remaining & -remaining
            v = bit.bit_length()

            new_rows = list(rows_t)
            new_cols = list(cols_t)

            new_rows[i] &= pos_val_mask[j][v]
            new_cols[j] &= pos_val_mask[i][v]

            if new_rows[i] and new_cols[j]:
                result = dfs(tuple(new_rows), tuple(new_cols))
                if result is not None:
                    return result

            remaining ^= bit

        return None

    solution = dfs(initial_rows, initial_cols)
    if solution is None:
        return "No Solution"
    return str([list(row) for row in solution])


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 1, None, None, None, None, None, None, None], [None, None, None, 5, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, 1, None, None, None, None, None], [None, None, None, None, None, 9, None, None, None, 5], [6, None, None, 3, None, None, None, 8, None, None], [None, None, None, None, None, None, None, None, 3, None], [None, None, None, None, None, None, None, None, None, None], [1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, 1, None, None]]}

import sys

WHITE = None
BLACK = 'B'


def solve(observation):
    data = observation['data']
    h = len(data)
    if h == 0:
        return repr([])
    w = len(data[0])

    n = h * w

    def idx(r, c):
        return r * w + c

    def rc(p):
        return divmod(p, w)

    neighbor_bits = [0] * n
    neighbors = [[] for _ in range(n)]
    for r in range(h):
        for c in range(w):
            p = idx(r, c)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    q = idx(rr, cc)
                    neighbors[p].append(q)
                    neighbor_bits[p] |= 1 << q

    all_cells = (1 << n) - 1

    clues = []
    clue_at = [-1] * n
    for r in range(h):
        for c in range(w):
            v = data[r][c]
            if v is not None:
                p = idx(r, c)
                clue_at[p] = len(clues)
                clues.append((p, v))

    k = len(clues)
    if k == 0:
        return "No Solution"

    clue_positions = [p for p, _ in clues]
    targets = [s for _, s in clues]

    for i, (p, _) in enumerate(clues):
        for q in neighbors[p]:
            if clue_at[q] != -1 and clue_at[q] != i:
                return "No Solution"

    def manhattan(p, q):
        r1, c1 = rc(p)
        r2, c2 = rc(q)
        return abs(r1 - r2) + abs(c1 - c2)

    def bit_iter(bits):
        while bits:
            b = bits & -bits
            yield b.bit_length() - 1
            bits ^= b

    def bfs_component(allowed_bits, seed_bit):
        if seed_bit == 0:
            return 0
        seen = seed_bit
        stack = [seed_bit.bit_length() - 1]
        while stack:
            p = stack.pop()
            nb = neighbor_bits[p] & allowed_bits & ~seen
            while nb:
                b = nb & -nb
                q = b.bit_length() - 1
                nb ^= b
                seen |= b
                stack.append(q)
        return seen

    def expand_bits(bits):
        e = bits
        x = bits
        while x:
            b = x & -x
            p = b.bit_length() - 1
            x ^= b
            e |= neighbor_bits[p]
        return e

    block_masks = []
    for r in range(h - 1):
        for c in range(w - 1):
            block_masks.append((1 << idx(r, c)) | (1 << idx(r + 1, c)) | (1 << idx(r, c + 1)) | (1 << idx(r + 1, c + 1)))

    def generate_shapes(root, target):
        if target == 1:
            return [1 << root]

        allowed = 0
        for p in range(n):
            if clue_at[p] != -1 and p != root:
                continue
            if manhattan(root, p) > target - 1:
                continue
            if p != root:
                bad = False
                for q in neighbors[p]:
                    if clue_at[q] != -1 and q != root:
                        bad = True
                        break
                if bad:
                    continue
            allowed |= 1 << p

        if not (allowed & (1 << root)):
            return []

        comp = bfs_component(allowed, 1 << root)
        if comp.bit_count() < target:
            return []

        seen = set()
        out = []

        def rec(bits, frontier):
            if bits in seen:
                return
            seen.add(bits)
            size = bits.bit_count()
            if size == target:
                out.append(bits)
                return

            # Simple necessary bound.
            if comp.bit_count() < target:
                return

            f = frontier
            while f:
                b = f & -f
                f ^= b
                p = b.bit_length() - 1
                new_bits = bits | b
                new_frontier = (frontier | neighbor_bits[p]) & comp & ~new_bits
                rec(new_bits, new_frontier)

        start = 1 << root
        rec(start, neighbor_bits[root] & comp & ~start)

        # Deduplicate and keep connected exact-size shapes only.
        uniq = []
        seen_final = set()
        for s in out:
            if s in seen_final:
                continue
            if s.bit_count() != target:
                continue
            if bfs_component(s, 1 << root) != s:
                continue
            seen_final.add(s)
            uniq.append(s)
        return uniq

    shapes = []
    shape_index = []
    expanded_shapes = []

    for i, (p, t) in enumerate(clues):
        s_list = generate_shapes(p, t)
        if not s_list:
            return "No Solution"
        s_map = {bits: j for j, bits in enumerate(s_list)}
        e_list = [expand_bits(bits) for bits in s_list]
        shapes.append(s_list)
        shape_index.append(s_map)
        expanded_shapes.append(e_list)

    domains0 = []
    for i in range(k):
        domains0.append((1 << len(shapes[i])) - 1)

    # Adaptive compatibility cache.
    compat = [[None] * k for _ in range(k)]
    compat_limit = 200000

    for i in range(k):
        for j in range(i + 1, k):
            mi = len(shapes[i])
            mj = len(shapes[j])
            if mi * mj <= compat_limit:
                ij = [0] * mi
                ji = [0] * mj
                for a, sa in enumerate(shapes[i]):
                    mask = 0
                    ea = expanded_shapes[i][a]
                    for b, sb in enumerate(shapes[j]):
                        if (sa & expanded_shapes[j][b]) == 0:
                            mask |= 1 << b
                            ji[b] |= 1 << a
                    ij[a] = mask
                compat[i][j] = ij
                compat[j][i] = ji

    def support_exists(i, a, j, domj):
        cm = compat[i][j]
        if cm is not None:
            return (cm[a] & domj) != 0
        sa = shapes[i][a]
        m = domj
        while m:
            b = m & -m
            idxb = b.bit_length() - 1
            m ^= b
            if (sa & expanded_shapes[j][idxb]) == 0:
                return True
        return False

    def domain_bits_to_union_inter(i, dom):
        union = 0
        inter = None
        m = dom
        while m:
            b = m & -m
            a = b.bit_length() - 1
            m ^= b
            s = shapes[i][a]
            union |= s
            inter = s if inter is None else (inter & s)
        return union, (0 if inter is None else inter)

    def prune_by_mandatory(domains, inters):
        changed = False
        for i in range(k):
            mand_exp = expand_bits(inters[i])
            for j in range(k):
                if i == j:
                    continue
                old = domains[j]
                new = 0
                m = old
                while m:
                    b = m & -m
                    a = b.bit_length() - 1
                    m ^= b
                    if (shapes[j][a] & mand_exp) == 0:
                        new |= b
                if new != old:
                    if new == 0:
                        return None, False
                    domains[j] = new
                    changed = True
        return domains, changed

    def prune_by_pair_support(domains):
        changed = False
        for i in range(k):
            for j in range(i + 1, k):
                di = domains[i]
                dj = domains[j]

                if di == 0 or dj == 0:
                    return None, False

                check_pair = compat[i][j] is not None or di.bit_count() <= 6 or dj.bit_count() <= 6
                if not check_pair:
                    continue

                new_di = 0
                m = di
                while m:
                    b = m & -m
                    a = b.bit_length() - 1
                    m ^= b
                    if support_exists(i, a, j, dj):
                        new_di |= b
                if new_di != di:
                    if new_di == 0:
                        return None, False
                    domains[i] = new_di
                    di = new_di
                    changed = True

                new_dj = 0
                m = dj
                while m:
                    b = m & -m
                    a = b.bit_length() - 1
                    m ^= b
                    if support_exists(j, a, i, di):
                        new_dj |= b
                if new_dj != dj:
                    if new_dj == 0:
                        return None, False
                    domains[j] = new_dj
                    changed = True

        return domains, changed

    def global_checks(domains, unions, inters):
        # Mandatory white cells of different islands may not touch.
        seen_exp = 0
        for i in range(k):
            if inters[i] & seen_exp:
                return False
            seen_exp |= expand_bits(inters[i])

        # Each island's mandatory cells must stay reachable from its clue through its union.
        for i, (root, target) in enumerate(clues):
            comp = bfs_component(unions[i], 1 << root)
            if (inters[i] & ~comp) != 0:
                return False
            if comp.bit_count() < target:
                return False

        possible_white = 0
        forced_white = 0
        for u in unions:
            possible_white |= u
        for t in inters:
            forced_white |= t

        forced_black = all_cells & ~possible_white
        black_possible = all_cells & ~forced_white

        for bm in block_masks:
            if (forced_black & bm) == bm:
                return False

        if forced_black:
            comp = bfs_component(black_possible, forced_black & -forced_black)
            if (forced_black & ~comp) != 0:
                return False

        return True

    def propagate(domains):
        domains = domains[:]
        while True:
            changed = False

            unions = [0] * k
            inters = [0] * k

            for i in range(k):
                if domains[i] == 0:
                    return None
                union, inter = domain_bits_to_union_inter(i, domains[i])
                unions[i] = union
                inters[i] = inter

                if union.bit_count() < targets[i]:
                    return None

                root = clues[i][0]
                comp = bfs_component(union, 1 << root)
                if comp.bit_count() < targets[i]:
                    return None

                if union.bit_count() == targets[i]:
                    idx0 = shape_index[i].get(union)
                    if idx0 is None or (domains[i] & (1 << idx0)) == 0:
                        return None
                    nd = 1 << idx0
                    if domains[i] != nd:
                        domains[i] = nd
                        changed = True

                elif comp.bit_count() == targets[i]:
                    idx0 = shape_index[i].get(comp)
                    if idx0 is None or (domains[i] & (1 << idx0)) == 0:
                        return None
                    nd = 1 << idx0
                    if domains[i] != nd:
                        domains[i] = nd
                        changed = True

            if changed:
                continue

            domains, local_changed = prune_by_mandatory(domains, inters)
            if domains is None:
                return None
            if local_changed:
                changed = True
                continue

            domains, local_changed = prune_by_pair_support(domains)
            if domains is None:
                return None
            if local_changed:
                changed = True
                continue

            unions = [0] * k
            inters = [0] * k
            for i in range(k):
                union, inter = domain_bits_to_union_inter(i, domains[i])
                unions[i] = union
                inters[i] = inter

            if not global_checks(domains, unions, inters):
                return None

            if not changed:
                return domains

    def final_check(domains):
        white = 0
        for i in range(k):
            if domains[i].bit_count() != 1:
                return None
            a = (domains[i] & -domains[i]).bit_length() - 1
            s = shapes[i][a]
            if white & expand_bits(s):
                return None
            white |= s

        black = all_cells & ~white

        for bm in block_masks:
            if (black & bm) == bm:
                return None

        if black:
            comp = bfs_component(black, black & -black)
            if comp != black:
                return None

        grid = [[None for _ in range(w)] for _ in range(h)]
        for p in range(n):
            r, c = rc(p)
            if black & (1 << p):
                grid[r][c] = 'B'
        return grid

    sys.setrecursionlimit(10000)
    visited = {}

    def choose_island(domains):
        best = None
        best_score = None
        for i in range(k):
            cnt = domains[i].bit_count()
            if cnt <= 1:
                continue
            union, inter = domain_bits_to_union_inter(i, domains[i])
            flexibility = union.bit_count() - inter.bit_count()
            score = (cnt, flexibility, targets[i])
            if best is None or score < best_score:
                best = i
                best_score = score
        return best

    def ordered_shape_choices(i, dom):
        arr = []
        m = dom
        while m:
            b = m & -m
            a = b.bit_length() - 1
            m ^= b
            conflict_score = 0
            s = shapes[i][a]
            es = expanded_shapes[i][a]
            for j in range(k):
                if j == i:
                    continue
                dj = domains_now[j]
                local = 0
                mm = dj
                while mm:
                    bb = mm & -mm
                    aa = bb.bit_length() - 1
                    mm ^= bb
                    if s & expanded_shapes[j][aa]:
                        local += 1
                conflict_score += local
            arr.append((conflict_score, a))
        arr.sort()
        return [a for _, a in arr]

    def backtrack(domains):
        key = tuple(domains)
        if key in visited:
            return None
        visited[key] = True

        domains = propagate(domains)
        if domains is None:
            return None

        done = True
        for d in domains:
            if d.bit_count() != 1:
                done = False
                break
        if done:
            return final_check(domains)

        i = choose_island(domains)
        if i is None:
            return None

        global domains_now
        domains_now = domains

        choices = ordered_shape_choices(i, domains[i])
        for a in choices:
            nd = domains[:]
            nd[i] = 1 << a
            res = backtrack(nd)
            if res is not None:
                return res

        return None

    domains_now = domains0[:]
    ans = backtrack(domains0)
    if ans is None:
        return "No Solution"
    return repr(ans)


