def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    k = 2
    cell_count = n * n
    full_mask = (1 << cell_count) - 1

    def idx(r, c):
        return r * n + c

    # Build regions from the observation grid.
    region_index = {}
    regions = []
    for r in range(n):
        for c in range(n):
            rid = data[r][c]
            if rid not in region_index:
                region_index[rid] = len(regions)
                regions.append([])
            regions[region_index[rid]].append(idx(r, c))

    # Necessary consistency for a 2-star N x N puzzle.
    if len(regions) != n:
        return "No Solution"

    # Precompute adjacency (stars cannot touch orthogonally or diagonally).
    adj_mask = [0] * cell_count
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            mask = 0
            for dr in (-1, 0, 1):
                rr = r + dr
                if not (0 <= rr < n):
                    continue
                for dc in (-1, 0, 1):
                    cc = c + dc
                    if not (0 <= cc < n):
                        continue
                    if dr == 0 and dc == 0:
                        continue
                    mask |= 1 << idx(rr, cc)
            adj_mask[i] = mask

    # Units: rows, columns, regions.
    units = []
    unit_masks = []

    for r in range(n):
        cells = [idx(r, c) for c in range(n)]
        units.append(cells)
        m = 0
        for i in cells:
            m |= 1 << i
        unit_masks.append(m)

    for c in range(n):
        cells = [idx(r, c) for r in range(n)]
        units.append(cells)
        m = 0
        for i in cells:
            m |= 1 << i
        unit_masks.append(m)

    for cells in regions:
        units.append(cells)
        m = 0
        for i in cells:
            m |= 1 << i
        unit_masks.append(m)

    unit_count = len(units)

    # Precompute all local non-touching star subsets of size 0/1/2 for each unit.
    # This mirrors human line/column/region candidate placement reasoning.
    unit_subsets = []
    for cells in units:
        subs0 = [0]
        subs1 = []
        subs2 = []
        for i_pos, i in enumerate(cells):
            bi = 1 << i
            subs1.append(bi)
            for j in cells[i_pos + 1:]:
                if not ((adj_mask[i] | bi) & (1 << j)):
                    subs2.append(bi | (1 << j))
        unit_subsets.append({0: subs0, 1: subs1, 2: subs2})

    def iter_bits(mask):
        while mask:
            bit = mask & -mask
            yield bit.bit_length() - 1
            mask ^= bit

    def apply_star(star_mask, empty_mask, i):
        bit = 1 << i
        if empty_mask & bit:
            return None
        if star_mask & bit:
            return star_mask, empty_mask, False
        if adj_mask[i] & star_mask:
            return None
        star_mask |= bit
        blocked = adj_mask[i]
        if blocked & star_mask:
            return None
        empty_mask |= blocked
        if empty_mask & star_mask:
            return None
        return star_mask, empty_mask, True

    def apply_empty(star_mask, empty_mask, i):
        bit = 1 << i
        if star_mask & bit:
            return None
        if empty_mask & bit:
            return star_mask, empty_mask, False
        empty_mask |= bit
        return star_mask, empty_mask, True

    def feasible_placements(unit_idx, star_mask, empty_mask):
        um = unit_masks[unit_idx]
        fixed = star_mask & um
        fixed_count = fixed.bit_count()
        if fixed_count > k:
            return None

        unknown = um & ~(star_mask | empty_mask)
        remaining = k - fixed_count
        if remaining < 0:
            return None
        if fixed_count + unknown.bit_count() < k:
            return None

        placements = []
        unavailable = star_mask | empty_mask
        for p in unit_subsets[unit_idx][remaining]:
            if p & unavailable:
                continue
            placements.append(p)
        return placements

    def propagate(star_mask, empty_mask):
        while True:
            changed = False
            placements_cache = [None] * unit_count

            # Basic global adjacency sanity.
            for i in iter_bits(star_mask):
                if adj_mask[i] & (star_mask ^ (1 << i)):
                    return None

            for u in range(unit_count):
                placements = feasible_placements(u, star_mask, empty_mask)
                if not placements:
                    return None
                placements_cache[u] = placements

                um = unit_masks[u]
                unknown = um & ~(star_mask | empty_mask)

                union_mask = 0
                inter_mask = None
                for p in placements:
                    union_mask |= p
                    inter_mask = p if inter_mask is None else (inter_mask & p)
                if inter_mask is None:
                    inter_mask = 0

                # Cells never used in any feasible placement for the unit cannot be stars.
                to_empty = unknown & ~union_mask
                if to_empty:
                    for i in iter_bits(to_empty):
                        res = apply_empty(star_mask, empty_mask, i)
                        if res is None:
                            return None
                        star_mask, empty_mask, did = res
                        changed = changed or did

                # Cells present in every feasible placement are forced stars.
                to_star = inter_mask
                if to_star:
                    for i in iter_bits(to_star):
                        res = apply_star(star_mask, empty_mask, i)
                        if res is None:
                            return None
                        star_mask, empty_mask, did = res
                        changed = changed or did

            # Fast quota checks after any deductions.
            for u in range(unit_count):
                um = unit_masks[u]
                s = (star_mask & um).bit_count()
                if s > k:
                    return None
                remaining_unknown = (um & ~(star_mask | empty_mask)).bit_count()
                if s + remaining_unknown < k:
                    return None

            if not changed:
                return star_mask, empty_mask, placements_cache

    dead = set()

    def solved(star_mask, empty_mask):
        if (star_mask | empty_mask) != full_mask:
            return False
        for um in unit_masks:
            if (star_mask & um).bit_count() != k:
                return False
        return True

    def dfs(star_mask, empty_mask):
        propagated = propagate(star_mask, empty_mask)
        if propagated is None:
            return None
        star_mask, empty_mask, placements_cache = propagated

        if solved(star_mask, empty_mask):
            return star_mask

        state_key = (star_mask, empty_mask)
        if state_key in dead:
            return None

        # Branch on the most constrained unit: fewest feasible placements > 1.
        best_u = None
        best_placements = None
        best_len = None

        for u, placements in enumerate(placements_cache):
            count = len(placements)
            if count <= 1:
                continue
            if best_len is None or count < best_len:
                best_len = count
                best_u = u
                best_placements = placements
                if count == 2:
                    break

        if best_u is None:
            dead.add(state_key)
            return None

        um = unit_masks[best_u]
        unknown = um & ~(star_mask | empty_mask)

        # Deterministic branch order.
        for placement in sorted(best_placements):
            ns, ne = star_mask, empty_mask

            ok = True
            for i in iter_bits(placement):
                res = apply_star(ns, ne, i)
                if res is None:
                    ok = False
                    break
                ns, ne, _ = res
            if not ok:
                continue

            for i in iter_bits(unknown & ~placement):
                res = apply_empty(ns, ne, i)
                if res is None:
                    ok = False
                    break
                ns, ne, _ = res
            if not ok:
                continue

            ans = dfs(ns, ne)
            if ans is not None:
                return ans

        dead.add(state_key)
        return None

    result = dfs(0, 0)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if result & (1 << idx(r, c)):
                answer[r][c] = 'S'
    return repr(answer)


