def solve(observation):
    data = observation['data']
    n = len(data)

    # Build initial row domains from non-black cells.
    initial_masks = []
    for r in range(n):
        mask = 0
        for c in range(n):
            if data[r][c] != 'B':
                mask |= 1 << c
        initial_masks.append(mask)

    # Two stars in adjacent rows cannot be in the same column or neighboring columns.
    compatible = [0] * n
    for c in range(n):
        mask = 0
        for d in range(n):
            if abs(c - d) > 1:
                mask |= 1 << d
        compatible[c] = mask

    reduce_cache = {}
    prop_cache = {}
    match_cache = {}

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_to_col(bit):
        return bit.bit_length() - 1

    def row_is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def chain_possible(masks):
        # Feasibility of the adjacency chain ignoring column uniqueness.
        reachable = masks[0]
        if reachable == 0:
            return False
        for r in range(1, n):
            next_reachable = 0
            for b in bit_iter(masks[r]):
                c = bit_to_col(b)
                if compatible[c] & reachable:
                    next_reachable |= b
            if next_reachable == 0:
                return False
            reachable = next_reachable
        return True

    def has_perfect_matching(state):
        # Bipartite feasibility for row->column uniqueness.
        if state in match_cache:
            return match_cache[state]

        masks = list(state)
        order = sorted(range(n), key=lambda r: masks[r].bit_count())
        ordered_masks = [masks[r] for r in order]
        memo = {}

        def dfs(i, used_cols):
            key = (i, used_cols)
            if key in memo:
                return memo[key]
            if i == n:
                memo[key] = True
                return True

            avail = ordered_masks[i] & ~used_cols
            while avail:
                b = avail & -avail
                avail ^= b
                if dfs(i + 1, used_cols | b):
                    memo[key] = True
                    return True

            memo[key] = False
            return False

        ans = dfs(0, 0)
        match_cache[state] = ans
        return ans

    def basic_reduce(state):
        # Deterministic deductions:
        # - fixed stars eliminate same column elsewhere
        # - hidden singles in columns
        # - adjacent-row non-touch arc consistency
        # - feasibility checks: adjacency chain + perfect matching
        if state in reduce_cache:
            return reduce_cache[state]

        masks = list(state)

        while True:
            changed = False

            for m in masks:
                if m == 0:
                    reduce_cache[state] = None
                    return None

            # Fixed columns cannot appear in other rows.
            fixed_cols = 0
            for m in masks:
                if row_is_single(m):
                    fixed_cols |= m

            for r in range(n):
                if not row_is_single(masks[r]):
                    nm = masks[r] & ~fixed_cols
                    if nm == 0:
                        reduce_cache[state] = None
                        return None
                    if nm != masks[r]:
                        masks[r] = nm
                        changed = True

            # Column coverage and hidden singles.
            col_count = [0] * n
            col_last_row = [-1] * n
            for r, m in enumerate(masks):
                for b in bit_iter(m):
                    c = bit_to_col(b)
                    col_count[c] += 1
                    col_last_row[c] = r

            for c in range(n):
                if col_count[c] == 0:
                    reduce_cache[state] = None
                    return None
                if col_count[c] == 1:
                    r = col_last_row[c]
                    nm = 1 << c
                    if masks[r] != nm:
                        masks[r] = nm
                        changed = True

            # Adjacent rows must be non-touching.
            for r in range(n - 1):
                m1 = masks[r]
                m2 = masks[r + 1]

                s1 = 0
                for b in bit_iter(m1):
                    c = bit_to_col(b)
                    if compatible[c] & m2:
                        s1 |= b

                s2 = 0
                for b in bit_iter(m2):
                    c = bit_to_col(b)
                    if compatible[c] & m1:
                        s2 |= b

                if s1 == 0 or s2 == 0:
                    reduce_cache[state] = None
                    return None

                if s1 != m1:
                    masks[r] = s1
                    changed = True
                if s2 != m2:
                    masks[r + 1] = s2
                    changed = True

            current = tuple(masks)
            if not chain_possible(masks):
                reduce_cache[state] = None
                return None
            if not has_perfect_matching(current):
                reduce_cache[state] = None
                return None

            if not changed:
                reduce_cache[state] = current
                return current

    def propagate(state):
        # Add limited contradiction-based pruning:
        # if assuming a candidate causes failure, remove that candidate.
        if state in prop_cache:
            return prop_cache[state]

        reduced = basic_reduce(state)
        if reduced is None:
            prop_cache[state] = None
            return None

        masks = list(reduced)

        while True:
            changed = False

            rows = sorted(
                [r for r in range(n) if masks[r].bit_count() > 1],
                key=lambda r: masks[r].bit_count()
            )

            for r in rows:
                original = masks[r]
                remove_bits = 0

                for b in bit_iter(original):
                    trial = list(masks)
                    trial[r] = b
                    if basic_reduce(tuple(trial)) is None:
                        remove_bits |= b

                if remove_bits:
                    masks[r] &= ~remove_bits
                    if masks[r] == 0:
                        prop_cache[state] = None
                        return None
                    new_reduced = basic_reduce(tuple(masks))
                    if new_reduced is None:
                        prop_cache[state] = None
                        return None
                    masks = list(new_reduced)
                    changed = True
                    break

            if not changed:
                result = tuple(masks)
                prop_cache[state] = result
                return result

    def solved(state):
        cols = []
        for r, m in enumerate(state):
            if not row_is_single(m):
                return False
            c = bit_to_col(m)
            if data[r][c] == 'B':
                return False
            cols.append(c)

        if len(set(cols)) != n:
            return False

        for r in range(n - 1):
            if abs(cols[r] - cols[r + 1]) <= 1:
                return False

        return True

    def search(state):
        state = propagate(state)
        if state is None:
            return None
        if solved(state):
            return state

        masks = list(state)

        # Most-constrained row first.
        row = min(
            (r for r in range(n) if masks[r].bit_count() > 1),
            key=lambda r: (masks[r].bit_count(), -r)
        )

        candidates = []
        for b in bit_iter(masks[row]):
            c = bit_to_col(b)

            # Prefer more forcing choices:
            # - columns supported by fewer rows
            # - choices that leave fewer options in adjacent rows
            col_support = 0
            for rr in range(n):
                if masks[rr] & b:
                    col_support += 1

            adj_freedom = 0
            for rr in (row - 1, row + 1):
                if 0 <= rr < n:
                    adj_freedom += (masks[rr] & compatible[c]).bit_count()

            candidates.append((col_support, adj_freedom, b))

        candidates.sort()

        for _, _, b in candidates:
            trial = list(masks)
            trial[row] = b
            ans = search(tuple(trial))
            if ans is not None:
                return ans

        return None

    result = search(tuple(initial_masks))
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, m in enumerate(result):
        c = bit_to_col(m)
        answer[r][c] = 'S'
    return repr(answer)


