from collections import deque
import sys

BLACK = 1
WHITE = 2
UNKNOWN = 0
CHARS = {BLACK: 'B', WHITE: 'W'}

class YinYangSolver:
    def __init__(self, observation):
        data = observation['data']
        self.n = len(data)
        self.N = self.n * self.n
        self.initial = [UNKNOWN] * self.N

        for r in range(self.n):
            for c in range(self.n):
                v = data[r][c]
                if v == 'B':
                    self.initial[self.idx(r, c)] = BLACK
                elif v == 'W':
                    self.initial[self.idx(r, c)] = WHITE

        self.nei = [[] for _ in range(self.N)]
        for r in range(self.n):
            for c in range(self.n):
                i = self.idx(r, c)
                if r > 0:
                    self.nei[i].append(self.idx(r - 1, c))
                if r + 1 < self.n:
                    self.nei[i].append(self.idx(r + 1, c))
                if c > 0:
                    self.nei[i].append(self.idx(r, c - 1))
                if c + 1 < self.n:
                    self.nei[i].append(self.idx(r, c + 1))

        self.blocks = []
        self.cell_to_blocks = [[] for _ in range(self.N)]
        for r in range(self.n - 1):
            for c in range(self.n - 1):
                block = (
                    self.idx(r, c),
                    self.idx(r, c + 1),
                    self.idx(r + 1, c),
                    self.idx(r + 1, c + 1),
                )
                bidx = len(self.blocks)
                self.blocks.append(block)
                for i in block:
                    self.cell_to_blocks[i].append(bidx)

        self.memo_unsat = set()

    def idx(self, r, c):
        return r * self.n + c

    def rc(self, i):
        return divmod(i, self.n)

    def bfs_allowed(self, board, start, forbidden_color, blocked=-1):
        vis = [False] * self.N
        if start == blocked or board[start] == forbidden_color:
            return vis
        dq = deque([start])
        vis[start] = True
        while dq:
            u = dq.popleft()
            for v in self.nei[u]:
                if v != blocked and not vis[v] and board[v] != forbidden_color:
                    vis[v] = True
                    dq.append(v)
        return vis

    def bfs_color(self, board, start, color):
        vis = [False] * self.N
        if board[start] != color:
            return vis
        dq = deque([start])
        vis[start] = True
        while dq:
            u = dq.popleft()
            for v in self.nei[u]:
                if not vis[v] and board[v] == color:
                    vis[v] = True
                    dq.append(v)
        return vis

    def assign(self, board, i, color):
        cur = board[i]
        if cur == color:
            return True
        if cur != UNKNOWN and cur != color:
            return False
        board[i] = color
        return True

    def apply_2x2_rules(self, board):
        changed = False
        for block in self.blocks:
            vals = [board[i] for i in block]
            b = vals.count(BLACK)
            w = vals.count(WHITE)
            u = vals.count(UNKNOWN)

            if b == 4 or w == 4:
                return False
            if u == 1:
                k = vals.index(UNKNOWN)
                i = block[k]
                if b == 3:
                    if not self.assign(board, i, WHITE):
                        return False
                    changed = True
                elif w == 3:
                    if not self.assign(board, i, BLACK):
                        return False
                    changed = True
        return changed

    def connectivity_step(self, board, color):
        opp = WHITE if color == BLACK else BLACK
        terminals = [i for i, v in enumerate(board) if v == color]
        if not terminals:
            return False

        vis = self.bfs_allowed(board, terminals[0], opp)

        for t in terminals:
            if not vis[t]:
                return None

        changed = False

        # Any unknown cell outside the reachable allowed area can never join this color.
        for i, v in enumerate(board):
            if v == UNKNOWN and not vis[i]:
                board[i] = opp
                changed = True

        if changed:
            return True

        # If removing an unknown cell disconnects already-known cells of this color,
        # that cell must be this color.
        if len(terminals) >= 2:
            for i, v in enumerate(board):
                if v == UNKNOWN and vis[i]:
                    vis2 = self.bfs_allowed(board, terminals[0], opp, blocked=i)
                    ok = True
                    for t in terminals:
                        if not vis2[t]:
                            ok = False
                            break
                    if not ok:
                        board[i] = color
                        changed = True

        return changed

    def one_step_lookahead(self, board):
        unknowns = [i for i, v in enumerate(board) if v == UNKNOWN]
        unknowns.sort(key=lambda i: -self.cell_score(board, i))

        for i in unknowns:
            viable = []
            for color in (BLACK, WHITE):
                b2 = board[:]
                b2[i] = color
                if self.propagate(b2, allow_lookahead=False):
                    viable.append(color)

            if not viable:
                return None
            if len(viable) == 1:
                board[i] = viable[0]
                return True
        return False

    def propagate(self, board, allow_lookahead=True):
        while True:
            changed = False

            step = self.apply_2x2_rules(board)
            if step is False:
                return False
            changed |= bool(step)

            for color in (BLACK, WHITE):
                step = self.connectivity_step(board, color)
                if step is None:
                    return False
                changed |= bool(step)

            if changed:
                continue

            if allow_lookahead:
                step = self.one_step_lookahead(board)
                if step is None:
                    return False
                if step:
                    continue

            break
        return True

    def cell_score(self, board, i):
        score = 0
        for v in self.nei[i]:
            if board[v] != UNKNOWN:
                score += 3
        for bidx in self.cell_to_blocks[i]:
            block = self.blocks[bidx]
            vals = [board[x] for x in block]
            u = vals.count(UNKNOWN)
            if u <= 2:
                score += 4 - u
            if BLACK in vals and WHITE in vals:
                score += 1
        r, c = self.rc(i)
        if r == 0 or r == self.n - 1:
            score += 1
        if c == 0 or c == self.n - 1:
            score += 1
        return score

    def choose_branch_cell(self, board):
        best_i = None
        best_options = None
        best_score = -1

        unknowns = [i for i, v in enumerate(board) if v == UNKNOWN]
        unknowns.sort(key=lambda i: -self.cell_score(board, i))

        for i in unknowns:
            options = []
            for color in (BLACK, WHITE):
                b2 = board[:]
                b2[i] = color
                if self.propagate(b2, allow_lookahead=False):
                    options.append(color)

            if not options:
                return i, []
            score = self.cell_score(board, i)
            if best_i is None or len(options) < len(best_options) or (len(options) == len(best_options) and score > best_score):
                best_i = i
                best_options = options
                best_score = score
                if len(options) == 1:
                    break

        return best_i, best_options

    def final_check(self, board):
        if any(v == UNKNOWN for v in board):
            return False

        if BLACK not in board or WHITE not in board:
            return False

        for block in self.blocks:
            vals = [board[i] for i in block]
            if vals.count(BLACK) == 4 or vals.count(WHITE) == 4:
                return False

        for color in (BLACK, WHITE):
            cells = [i for i, v in enumerate(board) if v == color]
            vis = self.bfs_color(board, cells[0], color)
            for i in cells:
                if not vis[i]:
                    return False

        return True

    def search(self, board):
        if not self.propagate(board, allow_lookahead=True):
            return None

        key = tuple(board)
        if key in self.memo_unsat:
            return None

        if UNKNOWN not in board:
            if self.final_check(board):
                return board
            self.memo_unsat.add(key)
            return None

        i, options = self.choose_branch_cell(board)
        if not options:
            self.memo_unsat.add(key)
            return None

        if len(options) == 1:
            board2 = board[:]
            board2[i] = options[0]
            ans = self.search(board2)
            if ans is not None:
                return ans
            self.memo_unsat.add(key)
            return None

        # Try the branch that tends to force more propagation first.
        branch_states = []
        for color in options:
            b2 = board[:]
            b2[i] = color
            if self.propagate(b2, allow_lookahead=True):
                branch_states.append((b2.count(UNKNOWN), b2))
        branch_states.sort(key=lambda x: x[0])

        for _, b2 in branch_states:
            ans = self.search(b2)
            if ans is not None:
                return ans

        self.memo_unsat.add(key)
        return None

    def solve(self):
        board = self.initial[:]
        ans = self.search(board)
        if ans is None:
            return "No Solution"
        out = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                row.append(CHARS[ans[self.idx(r, c)]])
            out.append(row)
        return out


def solve(observation):
    sys.setrecursionlimit(10000)
    return YinYangSolver(observation).solve()


