# Consecutive sudoku / Kropki-latin solver:
# - numbers 1..N
# - each row/col is a permutation of 1..N
# - dotted orthogonal neighbors are consecutive
# - undotted orthogonal neighbors are not consecutive

def solve(observation):
    data = observation.get("data")
    adjacent = observation.get("adjacent", [])
    if not data or not isinstance(data, list):
        return "No Solution"

    n = len(data)
    if any((not isinstance(row, list)) or len(row) != n for row in data):
        return "No Solution"

    full = (1 << n) - 1
    cell_count = n * n

    def idx(r, c):
        return r * n + c

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b
            mask -= b

    def mask_to_values(mask):
        out = []
        while mask:
            b = mask & -mask
            out.append(b.bit_length())
            mask -= b
        return out

    # Build positive-edge set from midpoint coordinates.
    pos_edges = set()
    for pt in adjacent:
        if not isinstance(pt, (list, tuple)) or len(pt) != 2:
            return "No Solution"
        a, b = float(pt[0]), float(pt[1])

        ra = round(a * 2)
        rb = round(b * 2)
        if abs(a * 2 - ra) > 1e-9 or abs(b * 2 - rb) > 1e-9:
            return "No Solution"

        # Horizontal gap: (row, col+0.5)
        if ra % 2 == 0 and rb % 2 == 1:
            r = ra // 2
            c = (rb - 1) // 2
            if not (0 <= r < n and 0 <= c < n - 1):
                return "No Solution"
            u = idx(r, c)
            v = idx(r, c + 1)
        # Vertical gap: (row+0.5, col)
        elif ra % 2 == 1 and rb % 2 == 0:
            r = (ra - 1) // 2
            c = rb // 2
            if not (0 <= r < n - 1 and 0 <= c < n):
                return "No Solution"
            u = idx(r, c)
            v = idx(r + 1, c)
        else:
            return "No Solution"

        if u > v:
            u, v = v, u
        pos_edges.add((u, v))

    # All orthogonal edges exist; those not in pos_edges are negative edges.
    edges = []
    edge_neighbors = [[] for _ in range(cell_count)]
    for r in range(n):
        for c in range(n):
            u = idx(r, c)
            if c + 1 < n:
                v = idx(r, c + 1)
                key = (u, v) if u < v else (v, u)
                is_pos = key in pos_edges
                edges.append((u, v, is_pos))
                edge_neighbors[u].append((v, is_pos))
                edge_neighbors[v].append((u, is_pos))
            if r + 1 < n:
                v = idx(r + 1, c)
                key = (u, v) if u < v else (v, u)
                is_pos = key in pos_edges
                edges.append((u, v, is_pos))
                edge_neighbors[u].append((v, is_pos))
                edge_neighbors[v].append((u, is_pos))

    rows = [[idx(r, c) for c in range(n)] for r in range(n)]
    cols = [[idx(r, c) for r in range(n)] for c in range(n)]

    peers = [set() for _ in range(cell_count)]
    for unit in rows + cols:
        for i in unit:
            peers[i].update(unit)
            peers[i].discard(i)
    peers = [tuple(sorted(p)) for p in peers]

    # Allowed values on dotted / undotted edge for a fixed value.
    # For undotted edges, we exclude equality too, because row/col all-different
    # means equal neighbors in same row/col can never be part of a valid solution.
    allow_pos = [0] * (n + 1)
    allow_neg = [0] * (n + 1)
    for v in range(1, n + 1):
        bit_v = 1 << (v - 1)
        cons = 0
        if v > 1:
            cons |= 1 << (v - 2)
        if v < n:
            cons |= 1 << v
        allow_pos[v] = cons
        allow_neg[v] = full & ~(cons | bit_v)

    # Initial domains.
    domains = [full] * cell_count
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is None:
                continue
            if not isinstance(val, int) or not (1 <= val <= n):
                return "No Solution"
            domains[idx(r, c)] = 1 << (val - 1)

    def filter_unit(domains_list, unit):
        # Exact feasibility filter for a row/column using subset DP.
        # Since a unit must contain every number 1..N exactly once, feasible
        # assignments correspond to permutations of the full value set.
        m = len(unit)
        local = [domains_list[p] for p in unit]

        fwd = [set() for _ in range(m + 1)]
        fwd[0].add(0)
        for i in range(m):
            nxt = fwd[i + 1]
            di = local[i]
            if di == 0:
                return None
            for used in fwd[i]:
                avail = di & (full ^ used)
                while avail:
                    b = avail & -avail
                    nxt.add(used | b)
                    avail -= b
            if not nxt:
                return None

        if full not in fwd[m]:
            return None

        suff = [set() for _ in range(m + 1)]
        suff[m].add(0)
        for i in range(m - 1, -1, -1):
            curr = suff[i]
            di = local[i]
            for used in suff[i + 1]:
                avail = di & (full ^ used)
                while avail:
                    b = avail & -avail
                    curr.add(used | b)
                    avail -= b
            if not curr:
                return None

        changed = False
        for i, p in enumerate(unit):
            supported = 0
            di = domains_list[p]
            for pre in fwd[i]:
                avail = di & (full ^ pre)
                while avail:
                    b = avail & -avail
                    if (full ^ (pre | b)) in suff[i + 1]:
                        supported |= b
                    avail -= b
            if supported == 0:
                return None
            if supported != domains_list[p]:
                domains_list[p] = supported
                changed = True

        return changed

    def filter_edge(domains_list, a, b, is_pos):
        da = domains_list[a]
        db = domains_list[b]
        if da == 0 or db == 0:
            return None

        nda = 0
        x = da
        while x:
            bit = x & -x
            v = bit.bit_length()
            allowed = allow_pos[v] if is_pos else allow_neg[v]
            if allowed & db:
                nda |= bit
            x -= bit

        ndb = 0
        x = db
        while x:
            bit = x & -x
            v = bit.bit_length()
            allowed = allow_pos[v] if is_pos else allow_neg[v]
            if allowed & da:
                ndb |= bit
            x -= bit

        if nda == 0 or ndb == 0:
            return None

        changed = False
        if nda != da:
            domains_list[a] = nda
            changed = True
        if ndb != db:
            domains_list[b] = ndb
            changed = True
        return changed

    def propagate(domains_list):
        # Repeatedly apply:
        # 1) exact row/col permutation feasibility,
        # 2) exact edge consistency for dotted/undotted neighbors.
        while True:
            changed = False

            for unit in rows:
                res = filter_unit(domains_list, unit)
                if res is None:
                    return None
                changed |= res

            for unit in cols:
                res = filter_unit(domains_list, unit)
                if res is None:
                    return None
                changed |= res

            for a, b, is_pos in edges:
                res = filter_edge(domains_list, a, b, is_pos)
                if res is None:
                    return None
                changed |= res

            if not changed:
                return domains_list

    def solved(domains_list):
        return all(d and (d & (d - 1) == 0) for d in domains_list)

    def choose_cell(domains_list):
        best = -1
        best_key = None
        for i, d in enumerate(domains_list):
            bc = d.bit_count()
            if bc <= 1:
                continue
            deg = len(peers[i]) + len(edge_neighbors[i])
            key = (bc, -deg)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def value_order(domains_list, p):
        # Least-constraining value heuristic.
        vals = []
        d = domains_list[p]
        for bit in bit_iter(d):
            v = bit.bit_length()
            score = 0

            # Row/column peers: prefer values that remove less.
            for q in peers[p]:
                dq = domains_list[q]
                if dq & bit:
                    score += dq.bit_count() - 1
                else:
                    score += dq.bit_count()

            # Edge neighbors: prefer values with more local support.
            for q, is_pos in edge_neighbors[p]:
                dq = domains_list[q]
                allowed = allow_pos[v] if is_pos else allow_neg[v]
                score += (dq & allowed).bit_count() * 2

            vals.append((score, bit))

        vals.sort(reverse=True)
        return [bit for _, bit in vals]

    dead = set()

    def search(domains_list):
        domains_list = propagate(domains_list[:])
        if domains_list is None:
            return None

        key = tuple(domains_list)
        if key in dead:
            return None

        if solved(domains_list):
            return domains_list

        p = choose_cell(domains_list)
        if p < 0:
            dead.add(key)
            return None

        for bit in value_order(domains_list, p):
            nxt = domains_list[:]
            nxt[p] = bit
            res = search(nxt)
            if res is not None:
                return res

        dead.add(key)
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            d = result[idx(r, c)]
            if d == 0 or (d & (d - 1)):
                return "No Solution"
            row.append(d.bit_length())
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

