# Shapeless Star Battle (1-star) solver:
# - exactly 1 star per row
# - exactly 1 star per column
# - no touching, including diagonally
# - black cells are blocked

def solve(observation):
    data = observation.get('data')
    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    n = len(data)
    all_mask = (1 << n) - 1

    # Allowed columns in each row.
    row_masks0 = []
    for r in range(n):
        mask = 0
        for c in range(n):
            if data[r][c] != 'B':
                mask |= 1 << c
        if mask == 0:
            return "No Solution"
        row_masks0.append(mask)

    # Precompute columns allowed in an adjacent row if current row uses column c.
    compat_adj = []
    for c in range(n):
        banned = (1 << c)
        if c > 0:
            banned |= 1 << (c - 1)
        if c + 1 < n:
            banned |= 1 << (c + 1)
        compat_adj.append(all_mask & ~banned)

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_to_col(bit):
        return bit.bit_length() - 1

    def popcount(x):
        return x.bit_count()

    def has_perfect_matching(row_masks):
        # Necessary condition for row/column uniqueness.
        order = sorted(range(n), key=lambda r: popcount(row_masks[r]))
        match_col_to_row = [-1] * n

        def dfs(r, seen):
            m = row_masks[r]
            while m:
                b = m & -m
                c = bit_to_col(b)
                m ^= b
                if seen[c]:
                    continue
                seen[c] = True
                rr = match_col_to_row[c]
                if rr == -1 or dfs(rr, seen):
                    match_col_to_row[c] = r
                    return True
            return False

        for r in order:
            seen = [False] * n
            if not dfs(r, seen):
                return False
        return True

    def propagate(row_masks):
        # Deterministic deductions:
        # 1) fail on empty row
        # 2) singleton row -> fix column, remove from other rows, ban touching in adjacent rows
        # 3) singleton column -> only one row can take that column
        # 4) adjacent-row arc consistency
        # 5) perfect-matching feasibility
        row_masks = row_masks[:]

        while True:
            # Fail fast on empty row.
            for m in row_masks:
                if m == 0:
                    return None

            changed = False

            # Rule 1: fixed rows propagate globally and to adjacent rows.
            singletons = [i for i, m in enumerate(row_masks) if m & (m - 1) == 0]
            for i in singletons:
                bit = row_masks[i]
                c = bit_to_col(bit)

                # Unique column: remove this column from every other row.
                for j in range(n):
                    if j != i and (row_masks[j] & bit):
                        row_masks[j] &= ~bit
                        if row_masks[j] == 0:
                            return None
                        changed = True

                # No touching with adjacent rows.
                banned = all_mask & ~compat_adj[c]
                if i > 0 and (row_masks[i - 1] & banned):
                    row_masks[i - 1] &= ~banned
                    if row_masks[i - 1] == 0:
                        return None
                    changed = True
                if i + 1 < n and (row_masks[i + 1] & banned):
                    row_masks[i + 1] &= ~banned
                    if row_masks[i + 1] == 0:
                        return None
                    changed = True

            if changed:
                continue

            # Rule 2: hidden singles in columns.
            col_support = [0] * n
            for r, m in enumerate(row_masks):
                mm = m
                while mm:
                    b = mm & -mm
                    c = bit_to_col(b)
                    col_support[c] |= 1 << r
                    mm ^= b

            for c, support in enumerate(col_support):
                if support == 0:
                    return None
                if support & (support - 1) == 0:
                    r = support.bit_length() - 1
                    bit = 1 << c
                    if row_masks[r] != bit:
                        row_masks[r] = bit
                        changed = True

            if changed:
                continue

            # Rule 3: adjacent-row arc consistency.
            for i in range(n - 1):
                a = row_masks[i]
                b = row_masks[i + 1]

                new_a = 0
                mm = a
                while mm:
                    bit = mm & -mm
                    c = bit_to_col(bit)
                    if b & compat_adj[c]:
                        new_a |= bit
                    mm ^= bit
                if new_a != a:
                    if new_a == 0:
                        return None
                    row_masks[i] = new_a
                    changed = True

                a = row_masks[i]
                b = row_masks[i + 1]
                new_b = 0
                mm = b
                while mm:
                    bit = mm & -mm
                    c = bit_to_col(bit)
                    if a & compat_adj[c]:
                        new_b |= bit
                    mm ^= bit
                if new_b != b:
                    if new_b == 0:
                        return None
                    row_masks[i + 1] = new_b
                    changed = True

            if changed:
                continue

            # Rule 4: global row/column feasibility.
            if not has_perfect_matching(row_masks):
                return None

            return row_masks

    memo = {}

    def solved_cols(row_masks):
        cols = []
        used = set()
        for r, m in enumerate(row_masks):
            if m == 0 or (m & (m - 1)) != 0:
                return None
            c = bit_to_col(m)
            if c in used:
                return None
            used.add(c)
            cols.append(c)

        for r in range(n - 1):
            if abs(cols[r] - cols[r + 1]) <= 1:
                return None

        for r, c in enumerate(cols):
            if data[r][c] == 'B':
                return None

        return cols

    def dfs(row_masks):
        row_masks = propagate(row_masks)
        if row_masks is None:
            return None

        key = tuple(row_masks)
        if key in memo:
            return memo[key]

        cols = solved_cols(row_masks)
        if cols is not None:
            memo[key] = cols
            return cols

        # Branch on the most constrained unresolved row.
        unresolved = [r for r in range(n) if popcount(row_masks[r]) > 1]
        if not unresolved:
            memo[key] = None
            return None

        # Column supports help choose rarer candidates first.
        col_count = [0] * n
        for m in row_masks:
            mm = m
            while mm:
                b = mm & -mm
                col_count[bit_to_col(b)] += 1
                mm ^= b

        def row_score(r):
            # Smaller domain first; tie-break by neighbor pressure.
            p = popcount(row_masks[r])
            neighbor_space = 0
            if r > 0:
                neighbor_space += popcount(row_masks[r - 1])
            if r + 1 < n:
                neighbor_space += popcount(row_masks[r + 1])
            return (p, neighbor_space)

        r = min(unresolved, key=row_score)

        cand_bits = list(bit_iter(row_masks[r]))

        def cand_score(bit):
            c = bit_to_col(bit)
            support = col_count[c]
            local_compat = 0
            if r > 0:
                local_compat += popcount(row_masks[r - 1] & compat_adj[c])
            if r + 1 < n:
                local_compat += popcount(row_masks[r + 1] & compat_adj[c])
            # Rarer columns first, then more restrictive local effect first.
            return (support, local_compat, c)

        cand_bits.sort(key=cand_score)

        for bit in cand_bits:
            trial = row_masks[:]
            trial[r] = bit
            res = dfs(trial)
            if res is not None:
                memo[key] = res
                return res

        memo[key] = None
        return None

    cols = dfs(row_masks0)
    if cols is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, c in enumerate(cols):
        answer[r][c] = 'S'
    return repr(answer)


