from collections import deque

B = 1
W = 2


class YinYangSolver:
    # General-purpose Yin-Yang solver with:
    # - local 2x2 propagation
    # - global partial-connectivity feasibility checks
    # - singleton consistency tests on undecided cells
    # - backtracking only after aggressive deduction

    def __init__(self, data):
        self.n = len(data)
        self.m = self.n * self.n
        self.nei = [[] for _ in range(self.m)]
        self.blocks = []
        self.blocks_of = [[] for _ in range(self.m)]

        for r in range(self.n):
            for c in range(self.n):
                i = self.idx(r, c)
                if r > 0:
                    self.nei[i].append(self.idx(r - 1, c))
                if r + 1 < self.n:
                    self.nei[i].append(self.idx(r + 1, c))
                if c > 0:
                    self.nei[i].append(self.idx(r, c - 1))
                if c + 1 < self.n:
                    self.nei[i].append(self.idx(r, c + 1))

        for r in range(self.n - 1):
            for c in range(self.n - 1):
                cells = (
                    self.idx(r, c),
                    self.idx(r, c + 1),
                    self.idx(r + 1, c),
                    self.idx(r + 1, c + 1),
                )
                bi = len(self.blocks)
                self.blocks.append(cells)
                for i in cells:
                    self.blocks_of[i].append(bi)

        self.initial = [0] * self.m
        for r in range(self.n):
            for c in range(self.n):
                v = data[r][c]
                if v == 'B':
                    self.initial[self.idx(r, c)] = B
                elif v == 'W':
                    self.initial[self.idx(r, c)] = W

    def idx(self, r, c):
        return r * self.n + c

    def rc(self, i):
        return divmod(i, self.n)

    def assign(self, grid, i, color, q):
        cur = grid[i]
        if cur == color:
            return True
        if cur != 0:
            return False
        grid[i] = color
        q.append(i)
        return True

    def propagate_block(self, grid, bi, q):
        a, b, c, d = self.blocks[bi]
        vals = (grid[a], grid[b], grid[c], grid[d])

        bc = 0
        wc = 0
        uc = 0
        ui = -1
        for k, v in enumerate(vals):
            if v == B:
                bc += 1
            elif v == W:
                wc += 1
            else:
                uc += 1
                ui = k

        if bc == 4 or wc == 4:
            return False

        if uc == 1:
            target = None
            if bc == 3:
                target = W
            elif wc == 3:
                target = B
            if target is not None:
                cell = (a, b, c, d)[ui]
                if not self.assign(grid, cell, target, q):
                    return False
        return True

    def propagate_basic(self, grid, q):
        # Local deductions from no-2x2 rule, then global feasibility checks.
        while q:
            i = q.popleft()
            for bi in self.blocks_of[i]:
                if not self.propagate_block(grid, bi, q):
                    return False
        return self.quick_feasible(grid)

    def quick_feasible(self, grid):
        # 2x2 rule
        for a, b, c, d in self.blocks:
            va = grid[a]
            if va != 0 and va == grid[b] == grid[c] == grid[d]:
                return False

        # Each color must remain globally connectable through non-opposite cells.
        if not self.color_connectable(grid, B):
            return False
        if not self.color_connectable(grid, W):
            return False

        return True

    def color_connectable(self, grid, color):
        opp = W if color == B else B

        first_assigned = -1
        any_possible = False
        for i, v in enumerate(grid):
            if v != opp:
                any_possible = True
            if v == color and first_assigned == -1:
                first_assigned = i

        if not any_possible:
            return False

        # No fixed cell of this color yet: still feasible if at least one possible cell exists.
        if first_assigned == -1:
            return True

        seen = [False] * self.m
        dq = deque([first_assigned])
        seen[first_assigned] = True

        while dq:
            x = dq.popleft()
            for y in self.nei[x]:
                if not seen[y] and grid[y] != opp:
                    seen[y] = True
                    dq.append(y)

        for i, v in enumerate(grid):
            if v == color and not seen[i]:
                return False

        return True

    def trial_basic(self, grid, i, color):
        cur = grid[i]
        if cur == color:
            return True
        if cur != 0:
            return False
        g = grid[:]
        q = deque()
        if not self.assign(g, i, color, q):
            return False
        return self.propagate_basic(g, q)

    def ordered_unknowns(self, grid):
        items = []
        for i, v in enumerate(grid):
            if v != 0:
                continue
            assigned_n = 0
            same_block_pressure = 0
            for nb in self.nei[i]:
                if grid[nb] != 0:
                    assigned_n += 1
            for bi in self.blocks_of[i]:
                cnt = 0
                for cell in self.blocks[bi]:
                    if grid[cell] != 0:
                        cnt += 1
                same_block_pressure += cnt
            score = assigned_n * 3 + same_block_pressure
            items.append((score, i))
        items.sort(reverse=True)
        return [i for _, i in items]

    def propagate(self, grid, initial_queue=None):
        q = deque(initial_queue) if initial_queue is not None else deque(i for i, v in enumerate(grid) if v != 0)

        if not self.propagate_basic(grid, q):
            return False

        while True:
            progress = False

            for i in self.ordered_unknowns(grid):
                b_ok = self.trial_basic(grid, i, B)
                w_ok = self.trial_basic(grid, i, W)

                if not b_ok and not w_ok:
                    return False

                if b_ok != w_ok:
                    forced = B if b_ok else W
                    if not self.assign(grid, i, forced, q):
                        return False
                    progress = True

            if not progress:
                break

            if not self.propagate_basic(grid, q):
                return False

        return self.quick_feasible(grid)

    def is_solved(self, grid):
        if any(v == 0 for v in grid):
            return False

        for a, b, c, d in self.blocks:
            if grid[a] == grid[b] == grid[c] == grid[d]:
                return False

        for color in (B, W):
            cells = [i for i, v in enumerate(grid) if v == color]
            if not cells:
                return False
            seen = set([cells[0]])
            dq = deque([cells[0]])
            while dq:
                x = dq.popleft()
                for y in self.nei[x]:
                    if grid[y] == color and y not in seen:
                        seen.add(y)
                        dq.append(y)
            if len(seen) != len(cells):
                return False

        return True

    def branch_order(self, grid, i, options):
        # Try the color that better matches current neighborhood first.
        scored = []
        for color in options:
            same = 0
            opp = 0
            for nb in self.nei[i]:
                if grid[nb] == color:
                    same += 1
                elif grid[nb] != 0:
                    opp += 1
            scored.append((same - opp, color))
        scored.sort(reverse=True)
        return [color for _, color in scored]

    def search(self, grid):
        if not self.propagate(grid):
            return None

        if self.is_solved(grid):
            return grid

        unknowns = self.ordered_unknowns(grid)
        if not unknowns:
            return None

        best_i = None
        best_opts = None
        best_score = None

        for i in unknowns:
            opts = []
            if self.trial_basic(grid, i, B):
                opts.append(B)
            if self.trial_basic(grid, i, W):
                opts.append(W)

            if not opts:
                return None

            if len(opts) == 1:
                g = grid[:]
                q = deque()
                if self.assign(g, i, opts[0], q) and self.propagate(g, q):
                    return self.search(g)
                return None

            score = 0
            for nb in self.nei[i]:
                if grid[nb] != 0:
                    score += 3
            for bi in self.blocks_of[i]:
                for cell in self.blocks[bi]:
                    if grid[cell] != 0:
                        score += 1

            if best_i is None or len(opts) < len(best_opts) or (len(opts) == len(best_opts) and score > best_score):
                best_i = i
                best_opts = opts
                best_score = score

        for color in self.branch_order(grid, best_i, best_opts):
            g = grid[:]
            q = deque()
            if not self.assign(g, best_i, color, q):
                continue
            if not self.propagate(g, q):
                continue
            ans = self.search(g)
            if ans is not None:
                return ans

        return None

    def solve_grid(self):
        grid = self.initial[:]
        ans = self.search(grid)
        return ans


def solve(observation):
    data = observation['data']
    solver = YinYangSolver(data)
    ans = solver.solve_grid()
    if ans is None:
        return "No Solution"
    n = len(data)
    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if ans[r * n + c] == B else 'W')
        out.append(row)
    return out


