from itertools import permutations


def visible_count(seq):
    highest = 0
    seen = 0
    for v in seq:
        if v > highest:
            highest = v
            seen += 1
    return seen


def solve(observation):
    try:
        U = list(observation["U"])
        D = list(observation["D"])
        L = list(observation["L"])
        R = list(observation["R"])
    except Exception:
        return "No Solution"

    n = len(U)
    if n == 0 or len(D) != n or len(L) != n or len(R) != n:
        return "No Solution"
    if any((not isinstance(x, int)) or x < 0 or x > n for x in U + D + L + R):
        return "No Solution"

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    by_left = {}
    by_right = {}
    by_pair = {}
    for p in all_perms:
        lv = visible_count(p)
        rv = visible_count(reversed(p))
        by_left.setdefault(lv, []).append(p)
        by_right.setdefault(rv, []).append(p)
        by_pair.setdefault((lv, rv), []).append(p)

    bits = [0] + [1 << (v - 1) for v in range(1, n + 1)]
    all_mask = (1 << n) - 1

    # Human-like edge deductions:
    # - clue 1 => first cell is n
    # - clue n => full ascending from that side
    # - general bound: position d from a clue cannot exceed n - clue + 1 + d
    cell_masks = [[all_mask for _ in range(n)] for _ in range(n)]

    def apply_side(indices, clue):
        if clue == 0:
            return
        if clue == 1:
            r, c = indices[0]
            cell_masks[r][c] &= bits[n]
            return
        if clue == n:
            for d, (r, c) in enumerate(indices):
                cell_masks[r][c] &= bits[d + 1]
            return
        for d, (r, c) in enumerate(indices):
            max_v = n - clue + 1 + d
            if max_v < n:
                cell_masks[r][c] &= (1 << max_v) - 1

    for r in range(n):
        row = [(r, c) for c in range(n)]
        apply_side(row, L[r])
        apply_side(row[::-1], R[r])

    for c in range(n):
        col = [(r, c) for r in range(n)]
        apply_side(col, U[c])
        apply_side(col[::-1], D[c])

    for r in range(n):
        for c in range(n):
            if cell_masks[r][c] == 0:
                return "No Solution"

    def initial_domain(clue_a, clue_b):
        if clue_a and clue_b:
            return list(by_pair.get((clue_a, clue_b), ()))
        if clue_a:
            return list(by_left.get(clue_a, ()))
        if clue_b:
            return list(by_right.get(clue_b, ()))
        return list(all_perms)

    row_domains = []
    for r in range(n):
        dom = initial_domain(L[r], R[r])
        dom = [p for p in dom if all(bits[p[c]] & cell_masks[r][c] for c in range(n))]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        dom = initial_domain(U[c], D[c])
        dom = [p for p in dom if all(bits[p[r]] & cell_masks[r][c] for r in range(n))]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    def propagate(rdoms, cdoms):
        while True:
            changed = False

            row_masks = [[0] * n for _ in range(n)]
            for r in range(n):
                dom = rdoms[r]
                if not dom:
                    return None
                masks = row_masks[r]
                for p in dom:
                    for c, v in enumerate(p):
                        masks[c] |= bits[v]

            col_masks = [[0] * n for _ in range(n)]
            for c in range(n):
                dom = cdoms[c]
                if not dom:
                    return None
                masks = col_masks[c]
                for p in dom:
                    for r, v in enumerate(p):
                        masks[r] |= bits[v]

            allowed = [[0] * n for _ in range(n)]
            for r in range(n):
                for c in range(n):
                    m = row_masks[r][c] & col_masks[c][r]
                    if m == 0:
                        return None
                    allowed[r][c] = m

            # Cell-wise cross-filtering.
            for r in range(n):
                dom = rdoms[r]
                new_dom = [p for p in dom if all(bits[p[c]] & allowed[r][c] for c in range(n))]
                if not new_dom:
                    return None
                if len(new_dom) != len(dom):
                    rdoms[r] = new_dom
                    changed = True

            for c in range(n):
                dom = cdoms[c]
                new_dom = [p for p in dom if all(bits[p[r]] & allowed[r][c] for r in range(n))]
                if not new_dom:
                    return None
                if len(new_dom) != len(dom):
                    cdoms[c] = new_dom
                    changed = True

            # Human-like "only place for a value in a line" deductions.
            for r in range(n):
                for v in range(1, n + 1):
                    b = bits[v]
                    positions = [c for c in range(n) if allowed[r][c] & b]
                    if not positions:
                        return None
                    if len(positions) == 1:
                        c = positions[0]
                        dom = rdoms[r]
                        new_dom = [p for p in dom if p[c] == v]
                        if not new_dom:
                            return None
                        if len(new_dom) != len(dom):
                            rdoms[r] = new_dom
                            changed = True

            for c in range(n):
                for v in range(1, n + 1):
                    b = bits[v]
                    positions = [r for r in range(n) if allowed[r][c] & b]
                    if not positions:
                        return None
                    if len(positions) == 1:
                        r = positions[0]
                        dom = cdoms[c]
                        new_dom = [p for p in dom if p[r] == v]
                        if not new_dom:
                            return None
                        if len(new_dom) != len(dom):
                            cdoms[c] = new_dom
                            changed = True

            if not changed:
                return rdoms, cdoms

    full_set = set(range(1, n + 1))

    def valid_final(grid):
        if len(grid) != n:
            return False
        for r in range(n):
            row = grid[r]
            if set(row) != full_set:
                return False
            if L[r] and visible_count(row) != L[r]:
                return False
            if R[r] and visible_count(row[::-1]) != R[r]:
                return False
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != full_set:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(col[::-1]) != D[c]:
                return False
        return True

    visited = set()

    def state_key(rdoms, cdoms):
        return (
            tuple(tuple(dom) for dom in rdoms),
            tuple(tuple(dom) for dom in cdoms),
        )

    def score_row_choice(rdoms, cdoms, r, p):
        total = 0
        for c, v in enumerate(p):
            cnt = 0
            for q in cdoms[c]:
                if q[r] == v:
                    cnt += 1
            if cnt == 0:
                return -1
            total += cnt
        return total

    def score_col_choice(rdoms, cdoms, c, p):
        total = 0
        for r, v in enumerate(p):
            cnt = 0
            for q in rdoms[r]:
                if q[c] == v:
                    cnt += 1
            if cnt == 0:
                return -1
            total += cnt
        return total

    def search(rdoms, cdoms):
        state = propagate(rdoms, cdoms)
        if state is None:
            return None
        rdoms, cdoms = state

        key = state_key(rdoms, cdoms)
        if key in visited:
            return None
        visited.add(key)

        if all(len(dom) == 1 for dom in rdoms):
            grid = [list(rdoms[r][0]) for r in range(n)]
            return grid if valid_final(grid) else None

        best_is_row = True
        best_idx = -1
        best_size = 10**9

        for r in range(n):
            size = len(rdoms[r])
            if 1 < size < best_size:
                best_size = size
                best_idx = r
                best_is_row = True

        for c in range(n):
            size = len(cdoms[c])
            if 1 < size < best_size:
                best_size = size
                best_idx = c
                best_is_row = False

        if best_idx == -1:
            return None

        if best_is_row:
            candidates = []
            for p in rdoms[best_idx]:
                s = score_row_choice(rdoms, cdoms, best_idx, p)
                if s >= 0:
                    candidates.append((s, p))
            candidates.sort(key=lambda x: x[0])

            for _, p in candidates:
                new_rdoms = rdoms.copy()
                new_cdoms = cdoms.copy()
                new_rdoms[best_idx] = [p]
                result = search(new_rdoms, new_cdoms)
                if result is not None:
                    return result
        else:
            candidates = []
            for p in cdoms[best_idx]:
                s = score_col_choice(rdoms, cdoms, best_idx, p)
                if s >= 0:
                    candidates.append((s, p))
            candidates.sort(key=lambda x: x[0])

            for _, p in candidates:
                new_rdoms = rdoms.copy()
                new_cdoms = cdoms.copy()
                new_cdoms[best_idx] = [p]
                result = search(new_rdoms, new_cdoms)
                if result is not None:
                    return result

        return None

    result = search(row_domains, col_domains)
    return str(result) if result is not None else "No Solution"


