    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 1, None, None, 3, None, None], [None, None, 1, None, 4, None, 2], [None, 3, 2, 2, None, None, None], [2, None, 1, None, None, None, None], [None, None, None, None, 1, None, 0], [None, None, None, 1, None, None, None], [2, None, 2, None, None, None, 1]]}

from collections import defaultdict, Counter


def solve(observation):
    data = observation['data']
    h = len(data)
    w = len(data[0]) if h else 0

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if nr < 0 or nr >= h:
                continue
            for dc in (-1, 0, 1):
                nc = c + dc
                if dc == 0 and dr == 0:
                    continue
                if 0 <= nc < w:
                    yield nr, nc

    # Map every non-numbered cell to a boolean variable.
    var_of = {}
    coord_of = []
    for r in range(h):
        for c in range(w):
            if data[r][c] is None:
                var_of[(r, c)] = len(coord_of)
                coord_of.append((r, c))

    def add_constraint(bank, cells, total):
        # bank maps frozenset(vars) -> exact mine count
        if total < 0 or total > len(cells):
            return False
        if not cells:
            return total == 0
        prev = bank.get(cells)
        if prev is not None and prev != total:
            return False
        bank[cells] = total
        return True

    # Build exact-sum constraints from visible clues.
    initial_bank = {}
    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            scope = frozenset(
                var_of[(nr, nc)]
                for nr, nc in neighbors(r, c)
                if data[nr][nc] is None
            )
            if not add_constraint(initial_bank, scope, clue):
                return "No Solution"

    def propagate_bank(bank, seed_assign):
        # Repeatedly:
        # 1) reduce constraints by current assignments
        # 2) apply direct fill rules
        # 3) apply subset/intersection deductions
        bank = dict(bank)
        assign = dict(seed_assign)

        while True:
            active = {}
            for scope, total in bank.items():
                rem = total
                undec = []
                for v in scope:
                    if v in assign:
                        rem -= assign[v]
                    else:
                        undec.append(v)
                if rem < 0 or rem > len(undec):
                    return None
                if undec:
                    u = frozenset(undec)
                    prev = active.get(u)
                    if prev is not None and prev != rem:
                        return None
                    active[u] = rem
                elif rem != 0:
                    return None
            bank = active

            changed = False

            # Basic exact-fill rules.
            for scope, total in list(bank.items()):
                if total == 0 or total == len(scope):
                    val = 1 if total else 0
                    for v in scope:
                        prev = assign.get(v)
                        if prev is not None and prev != val:
                            return None
                        if prev is None:
                            assign[v] = val
                            changed = True
            if changed:
                continue

            # Human-like pair deductions:
            # - subset subtraction
            # - overlap min/max bounds
            items = list(bank.items())
            for i in range(len(items)):
                s1, r1 = items[i]
                for j in range(i + 1, len(items)):
                    s2, r2 = items[j]

                    if s1 == s2:
                        if r1 != r2:
                            return None
                        continue

                    if s1.issubset(s2):
                        diff = s2 - s1
                        rr = r2 - r1
                        if not add_constraint(bank, frozenset(diff), rr):
                            return None
                        if diff:
                            changed = True
                        continue

                    if s2.issubset(s1):
                        diff = s1 - s2
                        rr = r1 - r2
                        if not add_constraint(bank, frozenset(diff), rr):
                            return None
                        if diff:
                            changed = True
                        continue

                    inter = s1 & s2
                    if not inter:
                        continue

                    a_only = s1 - inter
                    b_only = s2 - inter

                    # Bounds on intersection.
                    lo_i = max(0, r1 - len(a_only), r2 - len(b_only))
                    hi_i = min(len(inter), r1, r2)
                    if lo_i > hi_i:
                        return None

                    # Bounds on exclusive parts.
                    lo_a = max(0, r1 - hi_i)
                    hi_a = min(len(a_only), r1 - lo_i)
                    if lo_a > hi_a:
                        return None

                    lo_b = max(0, r2 - hi_i)
                    hi_b = min(len(b_only), r2 - lo_i)
                    if lo_b > hi_b:
                        return None

                    # Force intersection if fully determined.
                    if inter and (lo_i == len(inter) or hi_i == 0):
                        val = 1 if lo_i == len(inter) else 0
                        for v in inter:
                            prev = assign.get(v)
                            if prev is not None and prev != val:
                                return None
                            if prev is None:
                                assign[v] = val
                                changed = True

                    # Force A-only if fully determined.
                    if a_only and (lo_a == len(a_only) or hi_a == 0):
                        val = 1 if lo_a == len(a_only) else 0
                        for v in a_only:
                            prev = assign.get(v)
                            if prev is not None and prev != val:
                                return None
                            if prev is None:
                                assign[v] = val
                                changed = True

                    # Force B-only if fully determined.
                    if b_only and (lo_b == len(b_only) or hi_b == 0):
                        val = 1 if lo_b == len(b_only) else 0
                        for v in b_only:
                            prev = assign.get(v)
                            if prev is not None and prev != val:
                                return None
                            if prev is None:
                                assign[v] = val
                                changed = True

            if changed:
                continue

            return bank, assign

    def canonical_bank(bank):
        return tuple(sorted((tuple(sorted(scope)), total) for scope, total in bank.items()))

    def split_components(bank):
        parent = {}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra != rb:
                parent[rb] = ra

        for scope in bank:
            lst = list(scope)
            if not lst:
                continue
            for v in lst:
                if v not in parent:
                    parent[v] = v
            root = lst[0]
            for v in lst[1:]:
                union(root, v)

        groups = defaultdict(dict)
        for scope, total in bank.items():
            v = next(iter(scope))
            groups[find(v)][scope] = total

        comps = list(groups.values())
        comps.sort(key=lambda b: (len({x for s in b for x in s}), len(b)))
        return comps

    def choose_branch_var(bank):
        freq = Counter()
        best_scope = None
        best_metric = None

        for scope, total in bank.items():
            for v in scope:
                freq[v] += 1
            metric = (len(scope), min(total, len(scope) - total))
            if best_metric is None or metric < best_metric:
                best_metric = metric
                best_scope = scope

        if best_scope is None:
            return None

        def pressure(v):
            num = 0.0
            den = 0
            for scope, total in bank.items():
                if v in scope:
                    num += total / len(scope)
                    den += 1
            return num / den if den else 0.5

        candidates = list(best_scope)
        candidates.sort(key=lambda v: (-freq[v], -abs(pressure(v) - 0.5)))
        return candidates[0]

    def branch_order(bank, v):
        num = 0.0
        den = 0
        for scope, total in bank.items():
            if v in scope:
                num += total / len(scope)
                den += 1
        p = num / den if den else 0.5
        return (1, 0) if p > 0.5 else (0, 1)

    memo = {}

    def search(bank):
        # Always start by exhausting pure logic.
        propagated = propagate_bank(bank, {})
        if propagated is None:
            return None
        bank2, forced = propagated

        # If nothing remains constrained, we're done.
        if not bank2:
            return dict(forced)

        key = canonical_bank(bank2)
        if key in memo:
            cached = memo[key]
            if cached is None:
                return None
            out = dict(forced)
            out.update(cached)
            return out

        # Solve disconnected regions independently.
        comps = split_components(bank2)
        if len(comps) > 1:
            combined = {}
            for comp in comps:
                part = search(comp)
                if part is None:
                    memo[key] = None
                    return None
                combined.update(part)
            memo[key] = dict(combined)
            out = dict(forced)
            out.update(combined)
            return out

        # Logic stalled: branch on the most constrained variable.
        v = choose_branch_var(bank2)
        for val in branch_order(bank2, v):
            child = dict(bank2)
            if not add_constraint(child, frozenset([v]), val):
                continue
            sub = search(child)
            if sub is not None:
                memo[key] = dict(sub)
                out = dict(forced)
                out.update(sub)
                return out

        memo[key] = None
        return None

    solution = search(initial_bank)
    if solution is None:
        return "No Solution"

    # Any variable absent from the constrained solution is unconstrained -> choose safe.
    answer = [[None for _ in range(w)] for _ in range(h)]
    for idx, (r, c) in enumerate(coord_of):
        if solution.get(idx, 0) == 1:
            answer[r][c] = 'F'

    # Validate.
    mine_cells = {(r, c) for r in range(h) for c in range(w) if answer[r][c] == 'F'}
    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            cnt = 0
            for nr, nc in neighbors(r, c):
                if (nr, nc) in mine_cells:
                    cnt += 1
            if cnt != clue:
                return "No Solution"

    return repr(answer)


