from itertools import combinations


def solve(observation):
    region = observation.get("region")
    data = observation.get("data")
    if not region or not data or len(region) != len(data):
        return "No Solution"

    N = len(region)
    if any(len(row) != N for row in region) or any(len(row) != N for row in data):
        return "No Solution"

    # Normalize region ids to 0..R-1 while preserving encounter order.
    reg_map = {}
    reg_of = []
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            if rid not in reg_map:
                reg_map[rid] = len(reg_map)
            reg_of.append(reg_map[rid])
    R = len(reg_map)

    rows = [[r * N + c for c in range(N)] for r in range(N)]
    cols = [[r * N + c for r in range(N)] for c in range(N)]
    regs = [[] for _ in range(R)]
    for idx, rg in enumerate(reg_of):
        regs[rg].append(idx)

    # Standard jigsaw Latin square expects exactly N regions, each of size N.
    if R != N or any(len(unit) != N for unit in regs):
        return "No Solution"

    unitlist = rows + cols + regs
    units = [None] * (N * N)
    peers = [None] * (N * N)

    for idx in range(N * N):
        r = idx // N
        c = idx % N
        rg = reg_of[idx]
        units[idx] = (rows[r], cols[c], regs[rg])
        peer_set = set(rows[r])
        peer_set.update(cols[c])
        peer_set.update(regs[rg])
        peer_set.discard(idx)
        peers[idx] = tuple(peer_set)

    all_mask = (1 << N) - 1
    digit_bits = [1 << i for i in range(N)]

    def iter_bits(mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask ^= bit

    def bit_to_digit(bit):
        return bit.bit_length()

    def assign(cand, idx, bit):
        # Keep only 'bit' in this cell by eliminating every other candidate.
        other = cand[idx] & ~bit
        while other:
            b = other & -other
            other ^= b
            if not eliminate(cand, idx, b):
                return False
        return True

    def eliminate(cand, idx, bit):
        # Remove one candidate from one cell; propagate consequences.
        if not (cand[idx] & bit):
            return True

        cand[idx] ^= bit
        mask = cand[idx]

        if mask == 0:
            return False

        # Naked single: remove this value from all peers.
        if mask & (mask - 1) == 0:
            single = mask
            for p in peers[idx]:
                if not eliminate(cand, p, single):
                    return False

        # Hidden single in each of the three houses containing idx.
        for unit in units[idx]:
            places = []
            for j in unit:
                if cand[j] & bit:
                    places.append(j)
                    if len(places) > 1:
                        break
            if not places:
                return False
            if len(places) == 1:
                if not assign(cand, places[0], bit):
                    return False

        return True

    def locked_candidates(cand):
        changed = False

        # Region -> row/col pointing.
        for rg, unit in enumerate(regs):
            for bit in digit_bits:
                places = [j for j in unit if cand[j] & bit]
                if len(places) <= 1:
                    continue

                r0 = places[0] // N
                if all((j // N) == r0 for j in places[1:]):
                    for j in rows[r0]:
                        if reg_of[j] != rg and (cand[j] & bit):
                            if not eliminate(cand, j, bit):
                                return -1
                            changed = True

                c0 = places[0] % N
                if all((j % N) == c0 for j in places[1:]):
                    for j in cols[c0]:
                        if reg_of[j] != rg and (cand[j] & bit):
                            if not eliminate(cand, j, bit):
                                return -1
                            changed = True

        # Row/col -> region claiming.
        for r, unit in enumerate(rows):
            for bit in digit_bits:
                places = [j for j in unit if cand[j] & bit]
                if len(places) <= 1:
                    continue
                rg0 = reg_of[places[0]]
                if all(reg_of[j] == rg0 for j in places[1:]):
                    for j in regs[rg0]:
                        if (j // N) != r and (cand[j] & bit):
                            if not eliminate(cand, j, bit):
                                return -1
                            changed = True

        for c, unit in enumerate(cols):
            for bit in digit_bits:
                places = [j for j in unit if cand[j] & bit]
                if len(places) <= 1:
                    continue
                rg0 = reg_of[places[0]]
                if all(reg_of[j] == rg0 for j in places[1:]):
                    for j in regs[rg0]:
                        if (j % N) != c and (cand[j] & bit):
                            if not eliminate(cand, j, bit):
                                return -1
                            changed = True

        return 1 if changed else 0

    def naked_subsets(cand):
        changed = False
        max_k = min(4, N - 1)

        for unit in unitlist:
            unsolved = [j for j in unit if cand[j].bit_count() > 1]
            if len(unsolved) < 2:
                continue

            # Fast path: repeated identical masks, e.g. naked pairs/triples/quads.
            groups = {}
            for j in unsolved:
                m = cand[j]
                bc = m.bit_count()
                if 2 <= bc <= max_k:
                    groups.setdefault(m, []).append(j)

            for m, cells in groups.items():
                k = m.bit_count()
                if len(cells) == k:
                    cell_set = set(cells)
                    for j in unit:
                        if j not in cell_set and (cand[j] & m):
                            for bit in iter_bits(m):
                                if cand[j] & bit:
                                    if not eliminate(cand, j, bit):
                                        return -1
                                    changed = True

            # General mixed-mask subsets.
            small = [j for j in unsolved if 2 <= cand[j].bit_count() <= max_k]
            if len(small) < 2:
                continue

            for k in range(2, min(max_k, len(small)) + 1):
                for combo in combinations(small, k):
                    union = 0
                    for j in combo:
                        union |= cand[j]
                        if union.bit_count() > k:
                            break
                    if union.bit_count() != k:
                        continue

                    # Valid only if exactly these k cells are confined to the union.
                    subset_cells = [j for j in unsolved if (cand[j] | union) == union]
                    if len(subset_cells) != k:
                        continue

                    combo_set = set(subset_cells)
                    for j in unit:
                        if j not in combo_set and (cand[j] & union):
                            for bit in iter_bits(union):
                                if cand[j] & bit:
                                    if not eliminate(cand, j, bit):
                                        return -1
                                    changed = True

        return 1 if changed else 0

    def hidden_subsets(cand):
        # Human-style complement to naked subsets.
        changed = False
        max_k = min(4, N - 1)

        for unit in unitlist:
            # Skip if unit already solved.
            if all(cand[j].bit_count() == 1 for j in unit):
                continue

            for k in range(2, max_k + 1):
                for bits_combo in combinations(digit_bits, k):
                    bit_union = 0
                    for b in bits_combo:
                        bit_union |= b

                    places = [j for j in unit if cand[j] & bit_union]
                    if len(places) != k:
                        continue

                    # Each chosen digit must appear somewhere in those places.
                    ok = True
                    for b in bits_combo:
                        if not any(cand[j] & b for j in places):
                            ok = False
                            break
                    if not ok:
                        continue

                    for j in places:
                        extra = cand[j] & ~bit_union
                        if extra:
                            for b in iter_bits(extra):
                                if not eliminate(cand, j, b):
                                    return -1
                                changed = True

        return 1 if changed else 0

    def deduce(cand):
        # Repeatedly apply advanced logic until no more progress.
        while True:
            snapshot = cand[:]

            res = locked_candidates(cand)
            if res == -1:
                return False

            res = naked_subsets(cand)
            if res == -1:
                return False

            res = hidden_subsets(cand)
            if res == -1:
                return False

            if cand == snapshot:
                break

        return True

    def solved(cand):
        return all((m & (m - 1)) == 0 for m in cand)

    def choose_branch(cand):
        # Prefer the tightest house-digit placement, otherwise the tightest cell.
        best = None
        best_count = N + 1

        # Cell MRV.
        best_cell = None
        best_cell_count = N + 1
        for idx, m in enumerate(cand):
            bc = m.bit_count()
            if 1 < bc < best_cell_count:
                best_cell_count = bc
                best_cell = idx
                if bc == 2:
                    break

        # House-digit branching.
        for unit in unitlist:
            for bit in digit_bits:
                places = []
                for j in unit:
                    if cand[j] & bit:
                        places.append(j)
                        if len(places) >= best_count:
                            break
                cnt = len(places)
                if 1 < cnt < best_count:
                    best_count = cnt
                    best = ("unitdigit", places[:], bit)
                    if cnt == 2:
                        break
            if best_count == 2:
                break

        if best_cell is not None and best_cell_count <= best_count:
            return ("cell", best_cell, None)
        return best if best is not None else ("cell", best_cell, None)

    def search(cand):
        if not deduce(cand):
            return None

        if solved(cand):
            return cand

        kind, a, b = choose_branch(cand)

        if kind == "cell":
            idx = a
            if idx is None:
                return None
            options = list(iter_bits(cand[idx]))

            # More constraining values first.
            options.sort(
                key=lambda bit: sum(1 for p in peers[idx] if cand[p] & bit),
                reverse=True,
            )

            for bit in options:
                nxt = cand[:]
                if assign(nxt, idx, bit):
                    out = search(nxt)
                    if out is not None:
                        return out
            return None

        # Branch on which cell in a house takes a specific digit.
        places, bit = a, b
        places = sorted(
            places,
            key=lambda j: (cand[j].bit_count(), -sum(1 for p in peers[j] if cand[p] & bit)),
        )

        for idx in places:
            nxt = cand[:]
            if assign(nxt, idx, bit):
                out = search(nxt)
                if out is not None:
                    return out
        return None

    cand = [all_mask] * (N * N)

    # Seed givens.
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= N):
                return "No Solution"
            if not assign(cand, r * N + c, 1 << (v - 1)):
                return "No Solution"

    result = search(cand)
    if result is None:
        return "No Solution"

    grid = [[0] * N for _ in range(N)]
    for idx, m in enumerate(result):
        grid[idx // N][idx % N] = bit_to_digit(m)
    return str(grid)


