import ast
from functools import lru_cache

def solve(observation):
    n = len(observation['data'])
    full_mask = (1 << n) - 1
    target_set = set(range(1, n + 1))

    # Horizontal: '<' means left < right, '>' means left > right.
    hrels = [[None] * (n - 1) for _ in range(n)]
    for k, sym in observation.get('horizontal', {}).items():
        r, x = ast.literal_eval(k)
        r = int(r)
        c = int(round(float(x) - 0.5))
        hrels[r][c] = sym

    # Vertical symbols are interpreted by rotation:
    # '^' means upper < lower, 'v' means upper > lower.
    vrels = [[None] * n for _ in range(n - 1)]
    for k, sym in observation.get('vertical', {}).items():
        y, c = ast.literal_eval(k)
        r = int(round(float(y) - 0.5))
        c = int(c)
        vrels[r][c] = '<' if sym == '^' else '>'

    domains = [[full_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = observation['data'][r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[r][c] = 1 << (v - 1)

    line_cache = {}
    dead_states = set()

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_to_val(bit):
        return bit.bit_length()

    def popcount(x):
        return x.bit_count()

    def line_support(dom_tuple, rel_tuple):
        key = (dom_tuple, rel_tuple)
        if key in line_cache:
            return line_cache[key]

        @lru_cache(None)
        def feasible(pos, used_mask, prev_val):
            if pos == n:
                return True
            rel = rel_tuple[pos - 1] if pos else None
            avail = dom_tuple[pos] & (~used_mask & full_mask)
            while avail:
                bit = avail & -avail
                avail ^= bit
                v = bit_to_val(bit)
                if rel == '<' and not (prev_val < v):
                    continue
                if rel == '>' and not (prev_val > v):
                    continue
                if feasible(pos + 1, used_mask | bit, v):
                    return True
            return False

        if not feasible(0, 0, 0):
            line_cache[key] = None
            return None

        supports = [0] * n
        seen = set()

        def collect(pos, used_mask, prev_val):
            state = (pos, used_mask, prev_val)
            if state in seen:
                return
            seen.add(state)
            if pos == n:
                return
            rel = rel_tuple[pos - 1] if pos else None
            avail = dom_tuple[pos] & (~used_mask & full_mask)
            while avail:
                bit = avail & -avail
                avail ^= bit
                v = bit_to_val(bit)
                if rel == '<' and not (prev_val < v):
                    continue
                if rel == '>' and not (prev_val > v):
                    continue
                if feasible(pos + 1, used_mask | bit, v):
                    supports[pos] |= bit
                    collect(pos + 1, used_mask | bit, v)

        collect(0, 0, 0)
        result = tuple(supports)
        line_cache[key] = result
        return result

    def propagate(board):
        changed = True
        while changed:
            changed = False

            # Row-wise exact permutation filtering with horizontal inequalities.
            for r in range(n):
                row = tuple(board[r])
                supports = line_support(row, tuple(hrels[r]))
                if supports is None:
                    return False
                for c in range(n):
                    new_mask = board[r][c] & supports[c]
                    if new_mask == 0:
                        return False
                    if new_mask != board[r][c]:
                        board[r][c] = new_mask
                        changed = True

            # Column-wise exact permutation filtering with vertical inequalities.
            for c in range(n):
                col = tuple(board[r][c] for r in range(n))
                rels = tuple(vrels[r][c] for r in range(n - 1))
                supports = line_support(col, rels)
                if supports is None:
                    return False
                for r in range(n):
                    new_mask = board[r][c] & supports[r]
                    if new_mask == 0:
                        return False
                    if new_mask != board[r][c]:
                        board[r][c] = new_mask
                        changed = True

        return True

    deg = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n - 1):
            if hrels[r][c] is not None:
                deg[r][c] += 1
                deg[r][c + 1] += 1
    for r in range(n - 1):
        for c in range(n):
            if vrels[r][c] is not None:
                deg[r][c] += 1
                deg[r + 1][c] += 1

    def solved(board):
        for r in range(n):
            for c in range(n):
                if board[r][c] & (board[r][c] - 1):
                    return False
        return True

    def choose_cell(board):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                pc = popcount(board[r][c])
                if pc > 1:
                    key = (pc, -deg[r][c], r, c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def candidate_bits(board, r, c):
        mask = board[r][c]
        scored = []
        for bit in bit_iter(mask):
            freq = 0
            for j in range(n):
                if board[r][j] & bit:
                    freq += 1
            for i in range(n):
                if i != r and (board[i][c] & bit):
                    freq += 1
            scored.append((freq, bit_to_val(bit), bit))
        scored.sort()
        return [bit for _, _, bit in scored]

    def clone(board):
        return [row[:] for row in board]

    def extract_solution(board):
        return [[bit_to_val(board[r][c]) for c in range(n)] for r in range(n)]

    def validate(grid):
        for r in range(n):
            if set(grid[r]) != target_set:
                return False
        for c in range(n):
            if {grid[r][c] for r in range(n)} != target_set:
                return False
        for r in range(n):
            for c in range(n - 1):
                rel = hrels[r][c]
                if rel == '<' and not (grid[r][c] < grid[r][c + 1]):
                    return False
                if rel == '>' and not (grid[r][c] > grid[r][c + 1]):
                    return False
        for r in range(n - 1):
            for c in range(n):
                rel = vrels[r][c]
                if rel == '<' and not (grid[r][c] < grid[r + 1][c]):
                    return False
                if rel == '>' and not (grid[r][c] > grid[r + 1][c]):
                    return False
        return True

    def search(board):
        state = tuple(tuple(row) for row in board)
        if state in dead_states:
            return None

        if solved(board):
            grid = extract_solution(board)
            if validate(grid):
                return grid
            dead_states.add(state)
            return None

        cell = choose_cell(board)
        if cell is None:
            dead_states.add(state)
            return None
        r, c = cell

        for bit in candidate_bits(board, r, c):
            nxt = clone(board)
            nxt[r][c] = bit
            if propagate(nxt):
                ans = search(nxt)
                if ans is not None:
                    return ans

        dead_states.add(state)
        return None

    if not propagate(domains):
        return "No Solution"
    ans = search(domains)
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 5, None, None, None, 13, None, None, None], [None, None, None, None, None, None, None, None, None, 4], [None, 11, None, None, None, None, None, None, None, None], [None, None, 8, None, 11, None, 14, 6, None, None], [None, 11, None, None, None, None, None, None, 8, None], [None, 14, None, None, None, None, None, None, 17, None], [None, None, 8, 4, None, 12, None, 6, None, None], [None, None, None, None, None, None, None, None, 8, None], [11, None, None, None, None, None, None, None, None, None], [None, None, None, 2, None, None, None, 3, None, None]]}

def solve(observation):
    data = observation["data"]
    n = len(data)
    total = n * n
    all_mask = (1 << total) - 1

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    # Orthogonal neighbors as bitmasks.
    neigh = [0] * total
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            m = 0
            if r > 0:
                m |= 1 << idx(r - 1, c)
            if r + 1 < n:
                m |= 1 << idx(r + 1, c)
            if c > 0:
                m |= 1 << idx(r, c - 1)
            if c + 1 < n:
                m |= 1 << idx(r, c + 1)
            neigh[i] = m

    clues = []
    clue_mask = 0
    is_clue = [False] * total
    clue_value_at = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                i = idx(r, c)
                clues.append((r, c, v, i))
                clue_mask |= 1 << i
                is_clue[i] = True
                clue_value_at[i] = v

    if not clues:
        return "No Solution"

    # Precompute possible "cross shapes" for each clue:
    # a pattern is (white cells seen including clue itself, forced blocking black cells)
    p_white = []
    p_black = []
    mention_count = [0] * total

    for r0, c0, val, clue_i in clues:
        target = val - 1
        up_max = r0
        down_max = n - 1 - r0
        left_max = c0
        right_max = n - 1 - c0

        cur_w = []
        cur_b = []

        for up in range(up_max + 1):
            rem1 = target - up
            if rem1 < 0:
                break
            for down in range(down_max + 1):
                rem2 = rem1 - down
                if rem2 < 0:
                    break
                for left in range(left_max + 1):
                    right = rem2 - left
                    if right < 0:
                        break
                    if right > right_max:
                        continue

                    wmask = 1 << clue_i
                    bmask = 0
                    valid = True

                    # Up
                    for d in range(1, up + 1):
                        wmask |= 1 << idx(r0 - d, c0)
                    if up < up_max:
                        bi = idx(r0 - up - 1, c0)
                        if is_clue[bi]:
                            valid = False
                        else:
                            bmask |= 1 << bi

                    # Down
                    if valid:
                        for d in range(1, down + 1):
                            wmask |= 1 << idx(r0 + d, c0)
                        if down < down_max:
                            bi = idx(r0 + down + 1, c0)
                            if is_clue[bi]:
                                valid = False
                            else:
                                bmask |= 1 << bi

                    # Left
                    if valid:
                        for d in range(1, left + 1):
                            wmask |= 1 << idx(r0, c0 - d)
                        if left < left_max:
                            bi = idx(r0, c0 - left - 1)
                            if is_clue[bi]:
                                valid = False
                            else:
                                bmask |= 1 << bi

                    # Right
                    if valid:
                        for d in range(1, right + 1):
                            wmask |= 1 << idx(r0, c0 + d)
                        if right < right_max:
                            bi = idx(r0, c0 + right + 1)
                            if is_clue[bi]:
                                valid = False
                            else:
                                bmask |= 1 << bi

                    if valid:
                        cur_w.append(wmask)
                        cur_b.append(bmask)

        if not cur_w:
            return "No Solution"

        p_white.append(cur_w)
        p_black.append(cur_b)

        union_m = 0
        for wmask, bmask in zip(cur_w, cur_b):
            union_m |= (wmask | bmask)
        x = union_m
        while x:
            b = x & -x
            mention_count[b.bit_length() - 1] += 1
            x ^= b

    domains0 = [(1 << len(p_white[i])) - 1 for i in range(len(clues))]

    def bit_iter(x):
        while x:
            b = x & -x
            yield b.bit_length() - 1
            x ^= b

    def neighbor_union(mask):
        out = 0
        x = mask
        while x:
            b = x & -x
            out |= neigh[b.bit_length() - 1]
            x ^= b
        return out

    def reachable_component(start_bit, allowed_mask):
        seen = start_bit
        front = start_bit
        while front:
            nxt = 0
            x = front
            while x:
                b = x & -x
                nxt |= neigh[b.bit_length() - 1]
                x ^= b
            front = (nxt & allowed_mask) & ~seen
            seen |= front
        return seen

    def propagate(white, black, domains):
        white |= clue_mask

        while True:
            changed = False

            # Black cells force orthogonal neighbors white.
            nw = white | neighbor_union(black) | clue_mask
            if nw != white:
                white = nw
                changed = True
            if white & black:
                return None

            add_white = 0
            add_black = 0

            # Remove clue-patterns incompatible with current fixed cells.
            for ci in range(len(clues)):
                D = domains[ci]
                newD = 0
                first = True
                common_w = 0
                common_b = 0

                x = D
                while x:
                    bit = x & -x
                    pi = bit.bit_length() - 1
                    x ^= bit

                    wmask = p_white[ci][pi]
                    bmask = p_black[ci][pi]

                    if (wmask & black) or (bmask & white):
                        continue

                    newD |= bit
                    if first:
                        common_w = wmask
                        common_b = bmask
                        first = False
                    else:
                        common_w &= wmask
                        common_b &= bmask

                if newD == 0:
                    return None
                if newD != D:
                    domains[ci] = newD
                    changed = True

                add_white |= common_w
                add_black |= common_b

            nw = white | add_white
            nb = black | add_black
            if nw != white or nb != black:
                white, black = nw, nb
                changed = True
            if white & black:
                return None

            # All white cells must remain connectable through not-black cells.
            allowed = all_mask ^ black
            start = white & -white
            seen = reachable_component(start, allowed)
            if white & ~seen:
                return None

            # Any allowed component not connected to the existing white group
            # can never become white later, so it must be black.
            outside = allowed & ~seen
            if outside:
                black |= outside
                changed = True
                if white & black:
                    return None

            if not changed:
                return white, black, domains

    def validate(white, black):
        if white & black:
            return False
        if (white | black) != all_mask:
            return False
        if black & neighbor_union(black):
            return False

        # White connectivity on final board.
        start = white & -white
        seen = reachable_component(start, white)
        if seen != white:
            return False

        # Check every clue exactly.
        for r0, c0, val, _ in clues:
            cnt = 1
            r = r0 - 1
            while r >= 0:
                if (black >> idx(r, c0)) & 1:
                    break
                cnt += 1
                r -= 1
            r = r0 + 1
            while r < n:
                if (black >> idx(r, c0)) & 1:
                    break
                cnt += 1
                r += 1
            c = c0 - 1
            while c >= 0:
                if (black >> idx(r0, c)) & 1:
                    break
                cnt += 1
                c -= 1
            c = c0 + 1
            while c < n:
                if (black >> idx(r0, c)) & 1:
                    break
                cnt += 1
                c += 1
            if cnt != val:
                return False
        return True

    failed = set()

    def choose_unknown_cell(white, black):
        unknown = all_mask & ~(white | black)
        best = None
        best_key = None
        x = unknown
        while x:
            b = x & -x
            i = b.bit_length() - 1
            x ^= b
            # Prefer cells touched by many clue constraints and with more fixed neighbors.
            key = (mention_count[i], (neigh[i] & (white | black)).bit_count())
            if best is None or key > best_key:
                best = i
                best_key = key
        return best

    def dfs(white, black, domains):
        state = propagate(white, black, domains)
        if state is None:
            return None

        white, black, domains = state
        key = (white, black, tuple(domains))
        if key in failed:
            return None

        if (white | black) == all_mask:
            if validate(white, black):
                return white, black
            failed.add(key)
            return None

        # Branch first on the most constrained clue-pattern domain.
        best_ci = -1
        best_sz = 10**9
        for ci, D in enumerate(domains):
            sz = D.bit_count()
            if 1 < sz < best_sz:
                best_sz = sz
                best_ci = ci

        if best_ci != -1:
            options = []
            for pi in bit_iter(domains[best_ci]):
                force = ((p_white[best_ci][pi] | p_black[best_ci][pi]) & ~(white | black)).bit_count()
                options.append((-force, pi))
            options.sort()

            for _, pi in options:
                new_domains = domains[:]
                new_domains[best_ci] = 1 << pi
                res = dfs(
                    white | p_white[best_ci][pi],
                    black | p_black[best_ci][pi],
                    new_domains,
                )
                if res is not None:
                    return res

            failed.add(key)
            return None

        # If all clue domains are singletons but cells remain undecided,
        # branch on a cell.
        cell = choose_unknown_cell(white, black)
        if cell is None:
            if validate(white, black):
                return white, black
            failed.add(key)
            return None

        bit = 1 << cell

        # Try black first; it often propagates more.
        if not is_clue[cell]:
            res = dfs(white, black | bit, domains[:])
            if res is not None:
                return res

        res = dfs(white | bit, black, domains[:])
        if res is not None:
            return res

        failed.add(key)
        return None

    result = dfs(clue_mask, 0, domains0[:])
    if result is None:
        return "No Solution"

    white, black = result
    answer = []
    for r in range(n):
        row = []
        for c in range(n):
            i = idx(r, c)
            if data[r][c] is not None:
                row.append(data[r][c])
            elif (black >> i) & 1:
                row.append('B')
            else:
                row.append(None)
        answer.append(row)
    return repr(answer)


