OBSERVATION = {'U': [2, 0, 0, 1, 0, 6], 'D': [0, 0, 2, 2, 3, 0], 'L': [4, 0, 3, 0, 2, 0], 'R': [0, 0, 0, 0, 0, 0]}

from itertools import permutations
from functools import lru_cache


def solve(observation):
    obs = {
        'U': [int(x or 0) for x in observation.get('U', [])],
        'D': [int(x or 0) for x in observation.get('D', [])],
        'L': [int(x or 0) for x in observation.get('L', [])],
        'R': [int(x or 0) for x in observation.get('R', [])],
    }

    n = len(obs['U'])
    if not n or any(len(obs[k]) != n for k in ('U', 'D', 'L', 'R')):
        return "No Solution"

    bit_of = [0] + [1 << (v - 1) for v in range(1, n + 1)]
    full_mask = (1 << n) - 1

    @lru_cache(None)
    def visible_count(seq):
        mx = 0
        cnt = 0
        for h in seq:
            if h > mx:
                mx = h
                cnt += 1
        return cnt

    @lru_cache(None)
    def all_line_meta(size):
        vals = tuple(range(1, size + 1))
        meta = []
        for p in permutations(vals):
            l = visible_count(p)
            r = visible_count(p[::-1])
            meta.append((p, l, r))
        return tuple(meta)

    metas = all_line_meta(n)

    def line_candidates(left_clue, right_clue):
        out = []
        for p, l, r in metas:
            if (left_clue == 0 or l == left_clue) and (right_clue == 0 or r == right_clue):
                out.append(p)
        return out

    # Human-like edge deductions on domains.
    domains = [[full_mask for _ in range(n)] for _ in range(n)]

    def apply_mask(r, c, mask):
        domains[r][c] &= mask
        return domains[r][c] != 0

    def allowed_upto(max_h):
        if max_h >= n:
            return full_mask
        if max_h <= 0:
            return 0
        return (1 << max_h) - 1

    def apply_edge_rule_row(i, clue, from_left=True):
        if clue == 0:
            return True
        if clue == 1:
            j = 0 if from_left else n - 1
            return apply_mask(i, j, bit_of[n])
        if clue == n:
            for d in range(n):
                j = d if from_left else n - 1 - d
                if not apply_mask(i, j, bit_of[d + 1]):
                    return False
        base = n - clue + 1
        for d in range(n):
            j = d if from_left else n - 1 - d
            if not apply_mask(i, j, allowed_upto(base + d)):
                return False
        return True

    def apply_edge_rule_col(j, clue, from_top=True):
        if clue == 0:
            return True
        if clue == 1:
            i = 0 if from_top else n - 1
            return apply_mask(i, j, bit_of[n])
        if clue == n:
            for d in range(n):
                i = d if from_top else n - 1 - d
                if not apply_mask(i, j, bit_of[d + 1]):
                    return False
        base = n - clue + 1
        for d in range(n):
            i = d if from_top else n - 1 - d
            if not apply_mask(i, j, allowed_upto(base + d)):
                return False
        return True

    for i in range(n):
        if not apply_edge_rule_row(i, obs['L'][i], True):
            return "No Solution"
        if not apply_edge_rule_row(i, obs['R'][i], False):
            return "No Solution"
    for j in range(n):
        if not apply_edge_rule_col(j, obs['U'][j], True):
            return "No Solution"
        if not apply_edge_rule_col(j, obs['D'][j], False):
            return "No Solution"

    row_cands = [line_candidates(obs['L'][i], obs['R'][i]) for i in range(n)]
    col_cands = [line_candidates(obs['U'][j], obs['D'][j]) for j in range(n)]

    if any(not c for c in row_cands) or any(not c for c in col_cands):
        return "No Solution"

    def singleton_value(mask):
        return mask.bit_length() if mask and (mask & (mask - 1)) == 0 else 0

    def propagate(row_cands, col_cands, domains):
        while True:
            changed = False

            # Row-based pruning and deductions.
            for i in range(n):
                new_cands = []
                pos_masks = [0] * n

                for cand in row_cands[i]:
                    ok = True
                    for j, v in enumerate(cand):
                        if domains[i][j] & bit_of[v] == 0:
                            ok = False
                            break
                    if ok:
                        new_cands.append(cand)
                        for j, v in enumerate(cand):
                            pos_masks[j] |= bit_of[v]

                if not new_cands:
                    return False
                if len(new_cands) != len(row_cands[i]):
                    row_cands[i] = new_cands
                    changed = True
                else:
                    row_cands[i] = new_cands

                for j in range(n):
                    nd = domains[i][j] & pos_masks[j]
                    if nd == 0:
                        return False
                    if nd != domains[i][j]:
                        domains[i][j] = nd
                        changed = True

                # Hidden singles inside the row.
                places = [0] * (n + 1)
                for j, mask in enumerate(pos_masks):
                    m = mask
                    while m:
                        b = m & -m
                        v = b.bit_length()
                        places[v] |= 1 << j
                        m ^= b
                for v in range(1, n + 1):
                    pm = places[v]
                    if pm and (pm & (pm - 1)) == 0:
                        j = pm.bit_length() - 1
                        nd = domains[i][j] & bit_of[v]
                        if nd == 0:
                            return False
                        if nd != domains[i][j]:
                            domains[i][j] = nd
                            changed = True

            # Column-based pruning and deductions.
            for j in range(n):
                new_cands = []
                pos_masks = [0] * n

                for cand in col_cands[j]:
                    ok = True
                    for i, v in enumerate(cand):
                        if domains[i][j] & bit_of[v] == 0:
                            ok = False
                            break
                    if ok:
                        new_cands.append(cand)
                        for i, v in enumerate(cand):
                            pos_masks[i] |= bit_of[v]

                if not new_cands:
                    return False
                if len(new_cands) != len(col_cands[j]):
                    col_cands[j] = new_cands
                    changed = True
                else:
                    col_cands[j] = new_cands

                for i in range(n):
                    nd = domains[i][j] & pos_masks[i]
                    if nd == 0:
                        return False
                    if nd != domains[i][j]:
                        domains[i][j] = nd
                        changed = True

                # Hidden singles inside the column.
                places = [0] * (n + 1)
                for i, mask in enumerate(pos_masks):
                    m = mask
                    while m:
                        b = m & -m
                        v = b.bit_length()
                        places[v] |= 1 << i
                        m ^= b
                for v in range(1, n + 1):
                    pm = places[v]
                    if pm and (pm & (pm - 1)) == 0:
                        i = pm.bit_length() - 1
                        nd = domains[i][j] & bit_of[v]
                        if nd == 0:
                            return False
                        if nd != domains[i][j]:
                            domains[i][j] = nd
                            changed = True

            # Cell singles can force immediate support checks on both axes next loop.
            if not changed:
                return True

    def extract_grid(row_cands, domains):
        grid = []
        for i in range(n):
            if len(row_cands[i]) == 1:
                grid.append(list(row_cands[i][0]))
            else:
                row = []
                for j in range(n):
                    v = singleton_value(domains[i][j])
                    if not v:
                        return None
                    row.append(v)
                grid.append(row)
        return grid

    def valid_grid(grid):
        target = set(range(1, n + 1))
        for row in grid:
            if set(row) != target:
                return False
        for j in range(n):
            col = [grid[i][j] for i in range(n)]
            if set(col) != target:
                return False

        def vis(seq):
            mx = 0
            cnt = 0
            for h in seq:
                if h > mx:
                    mx = h
                    cnt += 1
            return cnt

        for i in range(n):
            if obs['L'][i] and vis(grid[i]) != obs['L'][i]:
                return False
            if obs['R'][i] and vis(grid[i][::-1]) != obs['R'][i]:
                return False
        for j in range(n):
            col = [grid[i][j] for i in range(n)]
            if obs['U'][j] and vis(col) != obs['U'][j]:
                return False
            if obs['D'][j] and vis(col[::-1]) != obs['D'][j]:
                return False
        return True

    if not propagate(row_cands, col_cands, domains):
        return "No Solution"

    def choose_branch(row_cands, col_cands):
        best = None

        for i in range(n):
            c = len(row_cands[i])
            if 1 < c and (best is None or c < best[2]):
                best = ('row', i, c)

        for j in range(n):
            c = len(col_cands[j])
            if 1 < c and (best is None or c < best[2]):
                best = ('col', j, c)

        return best

    def clone_state(row_cands, col_cands, domains):
        return [rc[:] for rc in row_cands], [cc[:] for cc in col_cands], [row[:] for row in domains]

    def dfs(row_cands, col_cands, domains):
        branch = choose_branch(row_cands, col_cands)
        if branch is None:
            grid = extract_grid(row_cands, domains)
            if grid is not None and valid_grid(grid):
                return grid
            return None

        kind, idx, _ = branch
        candidates = row_cands[idx] if kind == 'row' else col_cands[idx]

        # Branch on the most constrained line.
        for cand in candidates:
            nr, nc, nd = clone_state(row_cands, col_cands, domains)

            ok = True
            if kind == 'row':
                nr[idx] = [cand]
                for j, v in enumerate(cand):
                    nd[idx][j] &= bit_of[v]
                    if nd[idx][j] == 0:
                        ok = False
                        break
            else:
                nc[idx] = [cand]
                for i, v in enumerate(cand):
                    nd[i][idx] &= bit_of[v]
                    if nd[i][idx] == 0:
                        ok = False
                        break

            if not ok:
                continue
            if not propagate(nr, nc, nd):
                continue

            result = dfs(nr, nc, nd)
            if result is not None:
                return result

        return None

    result = dfs(row_cands, col_cands, domains)
    return str(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1, 1, 2], [0, 0, 3, 3, 3, 1, 1, 2], [0, 3, 3, 4, 3, 3, 2, 2], [0, 3, 4, 4, 3, 5, 5, 6], [0, 0, 4, 4, 3, 3, 3, 6], [0, 4, 4, 4, 7, 7, 7, 6], [0, 4, 4, 4, 7, 7, 7, 7], [0, 0, 0, 0, 0, 0, 7, 7]]}

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Normalize region ids to 0..R-1
    reg_map = {}
    next_id = 0
    regions = []
    for r in range(n):
        row = []
        for c in range(n):
            v = data[r][c]
            if v not in reg_map:
                reg_map[v] = next_id
                next_id += 1
            row.append(reg_map[v])
        regions.append(row)
    region_count = next_id

    full_cols = (1 << n) - 1

    def bit_iter(mask):
        while mask:
            lb = mask & -mask
            yield lb.bit_length() - 1
            mask ^= lb

    def singleton_col(mask):
        return mask.bit_length() - 1

    row_region_cols = [[0] * region_count for _ in range(n)]
    region_cells = [[] for _ in range(region_count)]
    for r in range(n):
        for c in range(n):
            g = regions[r][c]
            row_region_cols[r][g] |= 1 << c
            region_cells[g].append((r, c))

    adj_cols = [0] * n
    for c in range(n):
        m = 0
        for cc in range(max(0, c - 1), min(n - 1, c + 1) + 1):
            m |= 1 << cc
        adj_cols[c] = m

    def row_regions_mask(mask, r):
        out = 0
        for c in bit_iter(mask):
            out |= 1 << regions[r][c]
        return out

    def filter_used_regions(mask, r, used_regions):
        if not used_regions or mask == 0:
            return mask
        out = 0
        for c in bit_iter(mask):
            if ((used_regions >> regions[r][c]) & 1) == 0:
                out |= 1 << c
        return out

    def row_col_matching_feasible(masks, assigned):
        rows = [r for r in range(n) if assigned[r] == -1]
        if not rows:
            return True
        match_to_row = [-1] * n
        order = sorted(rows, key=lambda r: masks[r].bit_count())

        def dfs(r, seen):
            m = masks[r]
            while m:
                lb = m & -m
                c = lb.bit_length() - 1
                m ^= lb
                if seen[c]:
                    continue
                seen[c] = True
                if match_to_row[c] == -1 or dfs(match_to_row[c], seen):
                    match_to_row[c] = r
                    return True
            return False

        for r in order:
            seen = [False] * n
            if not dfs(r, seen):
                return False
        return True

    def row_region_matching_feasible(masks, assigned, used_regions):
        rows = [r for r in range(n) if assigned[r] == -1]
        unused_regions = [g for g in range(region_count) if ((used_regions >> g) & 1) == 0]
        if not rows:
            return True
        if len(unused_regions) < len(rows):
            return False

        region_index = {g: i for i, g in enumerate(unused_regions)}
        row_g_masks = []
        for r in rows:
            gm = 0
            seen = 0
            for c in bit_iter(masks[r]):
                g = regions[r][c]
                if ((seen >> g) & 1) == 0 and g in region_index:
                    seen |= 1 << g
                    gm |= 1 << region_index[g]
            if gm == 0:
                return False
            row_g_masks.append(gm)

        msize = len(unused_regions)
        match_to_row = [-1] * msize
        order = sorted(range(len(rows)), key=lambda i: row_g_masks[i].bit_count())

        def dfs(i, seen):
            m = row_g_masks[i]
            while m:
                lb = m & -m
                j = lb.bit_length() - 1
                m ^= lb
                if seen[j]:
                    continue
                seen[j] = True
                if match_to_row[j] == -1 or dfs(match_to_row[j], seen):
                    match_to_row[j] = i
                    return True
            return False

        for i in order:
            seen = [False] * msize
            if not dfs(i, seen):
                return False
        return True

    def propagate(masks, assigned, used_cols, used_regions):
        masks = masks[:]
        assigned = assigned[:]

        def force(r, c):
            nonlocal used_cols, used_regions
            bit = 1 << c
            g = regions[r][c]

            if assigned[r] != -1:
                return assigned[r] == c
            if (masks[r] & bit) == 0:
                return False
            if (used_cols & bit) or ((used_regions >> g) & 1):
                return False
            if r > 0 and assigned[r - 1] != -1 and abs(assigned[r - 1] - c) <= 1:
                return False
            if r + 1 < n and assigned[r + 1] != -1 and abs(assigned[r + 1] - c) <= 1:
                return False

            assigned[r] = c
            masks[r] = bit
            used_cols |= bit
            used_regions |= 1 << g

            for rr in range(n):
                if rr == r or assigned[rr] != -1:
                    continue
                m = masks[rr]
                m &= ~bit
                m &= ~row_region_cols[rr][g]
                if abs(rr - r) == 1:
                    m &= ~adj_cols[c]
                if m == 0:
                    return False
                masks[rr] = m
            return True

        changed = True
        while changed:
            changed = False

            # Apply global filters
            for r in range(n):
                if assigned[r] != -1:
                    masks[r] = 1 << assigned[r]
                    continue
                m = masks[r]
                m &= ~used_cols
                m = filter_used_regions(m, r, used_regions)
                if r > 0 and assigned[r - 1] != -1:
                    m &= ~adj_cols[assigned[r - 1]]
                if r + 1 < n and assigned[r + 1] != -1:
                    m &= ~adj_cols[assigned[r + 1]]
                if m == 0:
                    return None
                if m != masks[r]:
                    masks[r] = m
                    changed = True

            # Forced rows
            for r in range(n):
                if assigned[r] == -1 and masks[r].bit_count() == 1:
                    if not force(r, singleton_col(masks[r])):
                        return None
                    changed = True

            # Column candidates
            col_count = [0] * n
            col_last = [None] * n
            for r in range(n):
                if assigned[r] != -1:
                    c = assigned[r]
                    col_count[c] = 10**9
                    continue
                for c in bit_iter(masks[r]):
                    col_count[c] += 1
                    col_last[c] = (r, c)

            for c in range(n):
                if (used_cols >> c) & 1:
                    continue
                if col_count[c] == 0:
                    return None
                if col_count[c] == 1:
                    r0, c0 = col_last[c]
                    if assigned[r0] == -1:
                        if not force(r0, c0):
                            return None
                        changed = True

            # Region candidates
            region_cell_count = [0] * region_count
            region_last = [None] * region_count
            region_row_mask = [0] * region_count

            for g in range(region_count):
                if (used_regions >> g) & 1:
                    continue
                count = 0
                last = None
                rows_mask = 0
                for r in range(n):
                    if assigned[r] != -1:
                        continue
                    m = masks[r] & row_region_cols[r][g]
                    if m:
                        rows_mask |= 1 << r
                        bc = m.bit_count()
                        count += bc
                        if bc == 1:
                            last = (r, singleton_col(m))
                        else:
                            last = None
                region_cell_count[g] = count
                region_last[g] = last
                region_row_mask[g] = rows_mask

                if count == 0:
                    return None
                if count == 1:
                    r0, c0 = last
                    if assigned[r0] == -1:
                        if not force(r0, c0):
                            return None
                        changed = True

            # Row -> single region
            for r in range(n):
                if assigned[r] != -1:
                    continue
                gm = row_regions_mask(masks[r], r)
                if gm == 0:
                    return None
                if gm.bit_count() == 1:
                    g = singleton_col(gm)
                    nm = masks[r] & row_region_cols[r][g]
                    if nm == 0:
                        return None
                    if nm != masks[r]:
                        masks[r] = nm
                        changed = True
                    for rr in range(n):
                        if rr == r or assigned[rr] != -1:
                            continue
                        nm2 = masks[rr] & ~row_region_cols[rr][g]
                        if nm2 == 0:
                            return None
                        if nm2 != masks[rr]:
                            masks[rr] = nm2
                            changed = True

            # Region -> single row
            for g in range(region_count):
                if (used_regions >> g) & 1:
                    continue
                rows_mask = 0
                last_r = None
                for r in range(n):
                    if assigned[r] == -1 and (masks[r] & row_region_cols[r][g]):
                        rows_mask |= 1 << r
                        last_r = r
                if rows_mask == 0:
                    return None
                if rows_mask.bit_count() == 1:
                    r = last_r
                    nm = masks[r] & row_region_cols[r][g]
                    if nm == 0:
                        return None
                    if nm != masks[r]:
                        masks[r] = nm
                        changed = True

            # Adjacent row support pruning
            for r in range(n - 1):
                if assigned[r] == -1 and assigned[r + 1] == -1:
                    m1 = masks[r]
                    m2 = masks[r + 1]

                    keep1 = 0
                    for c in bit_iter(m1):
                        support = m2 & ~adj_cols[c] & ~row_region_cols[r + 1][regions[r][c]]
                        if support:
                            keep1 |= 1 << c
                    if keep1 == 0:
                        return None
                    if keep1 != m1:
                        masks[r] = keep1
                        changed = True

                    m1 = masks[r]
                    m2 = masks[r + 1]
                    keep2 = 0
                    for c in bit_iter(m2):
                        support = m1 & ~adj_cols[c] & ~row_region_cols[r][regions[r + 1][c]]
                        if support:
                            keep2 |= 1 << c
                    if keep2 == 0:
                        return None
                    if keep2 != m2:
                        masks[r + 1] = keep2
                        changed = True

            # Cheap global feasibility
            for r in range(n):
                if assigned[r] == -1 and masks[r] == 0:
                    return None

            for c in range(n):
                if (used_cols >> c) & 1:
                    continue
                possible = False
                for r in range(n):
                    if assigned[r] == -1 and ((masks[r] >> c) & 1):
                        possible = True
                        break
                if not possible:
                    return None

            for g in range(region_count):
                if (used_regions >> g) & 1:
                    continue
                possible = False
                for r in range(n):
                    if assigned[r] == -1 and (masks[r] & row_region_cols[r][g]):
                        possible = True
                        break
                if not possible:
                    return None

            if not row_col_matching_feasible(masks, assigned):
                return None
            if not row_region_matching_feasible(masks, assigned, used_regions):
                return None

        return masks, assigned, used_cols, used_regions

    def search(masks, assigned, used_cols, used_regions):
        state = propagate(masks, assigned, used_cols, used_regions)
        if state is None:
            return None
        masks, assigned, used_cols, used_regions = state

        if all(a != -1 for a in assigned):
            # Final exact validation
            cols_seen = set()
            regs_seen = set()
            for r, c in enumerate(assigned):
                g = regions[r][c]
                if c in cols_seen or g in regs_seen:
                    return None
                cols_seen.add(c)
                regs_seen.add(g)
                if r > 0 and abs(assigned[r] - assigned[r - 1]) <= 1:
                    return None
            return assigned

        # Candidate statistics for branching
        region_candidates = [[] for _ in range(region_count)]
        col_candidates = [[] for _ in range(n)]
        for r in range(n):
            if assigned[r] != -1:
                continue
            for c in bit_iter(masks[r]):
                g = regions[r][c]
                region_candidates[g].append((r, c))
                col_candidates[c].append((r, c))

        best_cells = None
        best_size = 10**9

        # Row branch
        for r in range(n):
            if assigned[r] == -1:
                k = masks[r].bit_count()
                if 1 < k < best_size:
                    best_size = k
                    best_cells = [(r, c) for c in bit_iter(masks[r])]

        # Region branch
        for g in range(region_count):
            if ((used_regions >> g) & 1) == 0:
                k = len(region_candidates[g])
                if 1 < k < best_size:
                    best_size = k
                    best_cells = region_candidates[g][:]

        # Column branch
        for c in range(n):
            if ((used_cols >> c) & 1) == 0:
                k = len(col_candidates[c])
                if 1 < k < best_size:
                    best_size = k
                    best_cells = col_candidates[c][:]

        if not best_cells:
            return None

        # Try most constraining cells first
        def cell_score(rc):
            r, c = rc
            g = regions[r][c]
            return (
                masks[r].bit_count(),
                len(col_candidates[c]),
                len(region_candidates[g]),
                abs((n - 1) / 2 - c),
            )

        best_cells.sort(key=cell_score)

        seen = set()
        for r, c in best_cells:
            if (r, c) in seen:
                continue
            seen.add((r, c))
            nmasks = masks[:]
            nassigned = assigned[:]
            bit = 1 << c
            nmasks[r] = bit
            res = search(nmasks, nassigned, used_cols, used_regions)
            if res is not None:
                return res

        return None

    initial_masks = [full_cols] * n
    initial_assigned = [-1] * n
    result = search(initial_masks, initial_assigned, 0, 0)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, c in enumerate(result):
        answer[r][c] = "S"
    return repr(answer)


