    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 2, None, 3, None, 1, None], [2, None, None, None, None, None, None], [None, None, None, None, 4, None, 4], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, 2, None, None], [3, None, None, 3, None, None, 3]]}

from collections import defaultdict, deque


def solve(observation):
    data = observation["data"]
    n = len(data)

    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            v = data[r][c]
            if v is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, v))

    m_islands = len(islands)
    if m_islands == 0:
        return repr({})

    edges = []
    incident = [[] for _ in range(m_islands)]

    # Build visibility edges: only right and down to avoid duplicates.
    for i, (r, c, v) in enumerate(islands):
        cc = c + 1
        while cc < n:
            if data[r][cc] is not None:
                j = pos_to_idx[(r, cc)]
                ub = min(2, islands[i][2], islands[j][2])
                eidx = len(edges)
                edges.append(
                    {
                        "u": i,
                        "v": j,
                        "p1": (r, c),
                        "p2": (r, cc),
                        "ori": "H",
                        "row": r,
                        "c1": c,
                        "c2": cc,
                        "ub0": ub,
                    }
                )
                incident[i].append(eidx)
                incident[j].append(eidx)
                break
            cc += 1

        rr = r + 1
        while rr < n:
            if data[rr][c] is not None:
                j = pos_to_idx[(rr, c)]
                ub = min(2, islands[i][2], islands[j][2])
                eidx = len(edges)
                edges.append(
                    {
                        "u": i,
                        "v": j,
                        "p1": (r, c),
                        "p2": (rr, c),
                        "ori": "V",
                        "col": c,
                        "r1": r,
                        "r2": rr,
                        "ub0": ub,
                    }
                )
                incident[i].append(eidx)
                incident[j].append(eidx)
                break
            rr += 1

    m_edges = len(edges)

    crossings = [[] for _ in range(m_edges)]
    for a in range(m_edges):
        ea = edges[a]
        if ea["ori"] != "H":
            continue
        for b in range(m_edges):
            eb = edges[b]
            if eb["ori"] != "V":
                continue
            if eb["r1"] < ea["row"] < eb["r2"] and ea["c1"] < eb["col"] < ea["c2"]:
                crossings[a].append(b)
                crossings[b].append(a)

    targets = [v for _, _, v in islands]
    base_lb = [0] * m_edges
    base_ub = [e["ub0"] for e in edges]

    def possible_graph_connected(ub):
        if m_islands <= 1:
            return True
        start = 0
        seen = [False] * m_islands
        dq = [start]
        seen[start] = True
        while dq:
            u = dq.pop()
            for eidx in incident[u]:
                if ub[eidx] <= 0:
                    continue
                e = edges[eidx]
                v = e["v"] if e["u"] == u else e["u"]
                if not seen[v]:
                    seen[v] = True
                    dq.append(v)
        return all(seen)

    def final_connected(sol):
        seen = [False] * m_islands
        dq = [0]
        seen[0] = True
        while dq:
            u = dq.pop()
            for eidx in incident[u]:
                if sol[eidx] <= 0:
                    continue
                e = edges[eidx]
                v = e["v"] if e["u"] == u else e["u"]
                if not seen[v]:
                    seen[v] = True
                    dq.append(v)
        return all(seen)

    def component_data(lb, ub):
        parent = list(range(m_islands))
        rank = [0] * m_islands

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        for eidx in range(m_edges):
            if lb[eidx] > 0:
                e = edges[eidx]
                union(e["u"], e["v"])

        comp_map = {}
        comp_id = 0
        comp_of = [0] * m_islands
        members = defaultdict(list)
        for i in range(m_islands):
            r = find(i)
            if r not in comp_map:
                comp_map[r] = comp_id
                comp_id += 1
            cid = comp_map[r]
            comp_of[i] = cid
            members[cid].append(i)

        return comp_of, members, comp_id

    def force_bridge_edges(lb, ub):
        comp_of, members, comp_cnt = component_data(lb, ub)
        if comp_cnt == 1:
            return True, False

        outgoing_by_comp = [set() for _ in range(comp_cnt)]
        multi_adj = [[] for _ in range(comp_cnt)]
        medge_id = 0

        for eidx in range(m_edges):
            if ub[eidx] <= 0:
                continue
            e = edges[eidx]
            a = comp_of[e["u"]]
            b = comp_of[e["v"]]
            if a == b:
                continue
            outgoing_by_comp[a].add(eidx)
            outgoing_by_comp[b].add(eidx)
            multi_adj[a].append((b, medge_id, eidx))
            multi_adj[b].append((a, medge_id, eidx))
            medge_id += 1

        changed = False

        for cid in range(comp_cnt):
            if len(outgoing_by_comp[cid]) == 0:
                return False, changed
            if len(outgoing_by_comp[cid]) == 1:
                only_e = next(iter(outgoing_by_comp[cid]))
                if lb[only_e] < 1:
                    lb[only_e] = 1
                    changed = True

        tin = [-1] * comp_cnt
        low = [0] * comp_cnt
        timer = 0
        bridge_orig_edges = set()

        def dfs(u, peid):
            nonlocal timer
            tin[u] = low[u] = timer
            timer += 1
            for v, eid, orig_eidx in multi_adj[u]:
                if eid == peid:
                    continue
                if tin[v] != -1:
                    low[u] = min(low[u], tin[v])
                else:
                    dfs(v, eid)
                    low[u] = min(low[u], low[v])
                    if low[v] > tin[u]:
                        bridge_orig_edges.add(orig_eidx)

        for cid in range(comp_cnt):
            if tin[cid] == -1:
                dfs(cid, -1)

        for eidx in bridge_orig_edges:
            if lb[eidx] < 1:
                lb[eidx] = 1
                changed = True

        return True, changed

    def propagate(lb, ub):
        while True:
            changed = False

            for eidx in range(m_edges):
                if lb[eidx] > ub[eidx]:
                    return False
                if lb[eidx] > 0:
                    for fidx in crossings[eidx]:
                        if ub[fidx] != 0:
                            ub[fidx] = 0
                            changed = True

            for i in range(m_islands):
                t = targets[i]
                inc = incident[i]
                s_lb = 0
                s_ub = 0
                for eidx in inc:
                    s_lb += lb[eidx]
                    s_ub += ub[eidx]
                if t < s_lb or t > s_ub:
                    return False

                for eidx in inc:
                    other_lb = s_lb - lb[eidx]
                    other_ub = s_ub - ub[eidx]
                    nl = max(lb[eidx], t - other_ub)
                    nu = min(ub[eidx], t - other_lb)
                    if nl > nu:
                        return False
                    if nl != lb[eidx]:
                        lb[eidx] = nl
                        changed = True
                    if nu != ub[eidx]:
                        ub[eidx] = nu
                        changed = True

            for eidx in range(m_edges):
                if lb[eidx] > ub[eidx]:
                    return False
                if lb[eidx] > 0:
                    for fidx in crossings[eidx]:
                        if ub[fidx] > 0:
                            ub[fidx] = 0
                            changed = True
                            if lb[fidx] > ub[fidx]:
                                return False

            if not possible_graph_connected(ub):
                return False

            ok, comp_changed = force_bridge_edges(lb, ub)
            if not ok:
                return False
            if comp_changed:
                changed = True

            if not changed:
                break

        return True

    def solved(lb, ub):
        for eidx in range(m_edges):
            if lb[eidx] != ub[eidx]:
                return False
        vals = lb
        for i in range(m_islands):
            s = 0
            for eidx in incident[i]:
                s += vals[eidx]
            if s != targets[i]:
                return False
        for eidx in range(m_edges):
            if vals[eidx] > 0:
                for fidx in crossings[eidx]:
                    if vals[fidx] > 0:
                        return False
        return final_connected(vals)

    def branch_order(eidx, lb, ub):
        vals = list(range(lb[eidx], ub[eidx] + 1))
        e = edges[eidx]
        u, v = e["u"], e["v"]

        def endpoint_pressure(i):
            cur_lb = 0
            extra = 0
            for x in incident[i]:
                cur_lb += lb[x]
                extra += ub[x] - lb[x]
            need = targets[i] - cur_lb
            if extra <= 0:
                return 0.0
            return need / extra

        p = endpoint_pressure(u) + endpoint_pressure(v)
        if p > 1.0:
            vals.sort(reverse=True)
        else:
            vals.sort()
        return vals

    def choose_edge(lb, ub):
        best = None
        best_key = None
        for eidx in range(m_edges):
            if lb[eidx] == ub[eidx]:
                continue
            domain = ub[eidx] - lb[eidx] + 1
            e = edges[eidx]
            impact = len(crossings[eidx]) + len(incident[e["u"]]) + len(incident[e["v"]])
            tight = 0
            for i in (e["u"], e["v"]):
                s_lb = sum(lb[x] for x in incident[i])
                s_ub = sum(ub[x] for x in incident[i])
                tight += (s_ub - s_lb)
            key = (domain, -impact, tight)
            if best_key is None or key < best_key:
                best_key = key
                best = eidx
        return best

    failed = set()

    def dfs(lb, ub):
        ok = propagate(lb, ub)
        if not ok:
            return None

        state_key = (tuple(lb), tuple(ub))
        if state_key in failed:
            return None

        if solved(lb, ub):
            return lb[:]

        eidx = choose_edge(lb, ub)
        if eidx is None:
            failed.add(state_key)
            return None

        for val in branch_order(eidx, lb, ub):
            nlb = lb[:]
            nub = ub[:]
            nlb[eidx] = val
            nub[eidx] = val
            res = dfs(nlb, nub)
            if res is not None:
                return res

        failed.add(state_key)
        return None

    solution = dfs(base_lb[:], base_ub[:])
    if solution is None:
        return "No Solution"

    answer = {}
    for eidx, cnt in enumerate(solution):
        if cnt > 0:
            a = edges[eidx]["p1"]
            b = edges[eidx]["p2"]
            if a > b:
                a, b = b, a
            answer[(a, b)] = cnt
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 0, 0, 0, 1, 1, 2, 2], [3, 3, 0, 0, 0, 0, 5, 1, 2, 2], [4, 3, 3, 0, 0, 5, 5, 1, 2, 2], [4, 4, 4, 0, 0, 0, 1, 1, 2, 2], [4, 7, 0, 0, 8, 8, 1, 2, 2, 2], [4, 7, 7, 7, 7, 1, 1, 2, 2, 2], [4, 4, 10, 10, 1, 1, 1, 1, 2, 2], [11, 11, 10, 10, 12, 12, 12, 1, 2, 2], [11, 10, 10, 13, 13, 13, 1, 1, 14, 2], [11, 11, 10, 10, 13, 13, 13, 14, 14, 2]], 'row_water_counts': [6, 7, 7, 8, 6, 6, 2, 6, 8, 8], 'col_water_counts': [9, 7, 6, 7, 9, 8, 8, 4, 3, 3]}

from collections import defaultdict


def solve(observation):
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']

    if not region_grid or not region_grid[0]:
        return "No Solution"

    R = len(region_grid)
    C = len(region_grid[0])

    if len(row_targets) != R or len(col_targets) != C:
        return "No Solution"

    if any(len(row) != C for row in region_grid):
        return "No Solution"

    total_target = sum(row_targets)
    if total_target != sum(col_targets):
        return "No Solution"

    # Collect regions.
    cells_by_region_id = defaultdict(list)
    for r in range(R):
        for c in range(C):
            cells_by_region_id[region_grid[r][c]].append((r, c))

    region_ids = sorted(cells_by_region_id)
    n_regions = len(region_ids)
    region_index_of_id = {rid: i for i, rid in enumerate(region_ids)}

    # For each region, states are waterlines:
    # choose a cutoff among the distinct occupied rows;
    # water = all cells in rows at or below that cutoff, or empty.
    region_data = []
    row_regions = [[] for _ in range(R)]
    col_regions = [[] for _ in range(C)]

    for rid in region_ids:
        cells = cells_by_region_id[rid]
        rows_present = sorted({r for r, _ in cells})
        row_to_cells = defaultdict(list)
        col_to_cells = defaultdict(list)
        for r, c in cells:
            row_to_cells[r].append((r, c))
            col_to_cells[c].append((r, c))

        states = []
        seen = set()

        # Full to empty, preserving monotone waterline choices.
        for k in range(len(rows_present) + 1):
            filled_rows = set(rows_present[k:])
            water_cells = tuple(sorted((r, c) for (r, c) in cells if r in filled_rows))
            if water_cells in seen:
                continue
            seen.add(water_cells)

            row_amt = [0] * R
            col_amt = [0] * C
            for r, c in water_cells:
                row_amt[r] += 1
                col_amt[c] += 1

            states.append({
                'water_cells': water_cells,
                'row_amt': tuple(row_amt),
                'col_amt': tuple(col_amt),
                'total': len(water_cells),
            })

        ri = len(region_data)
        touched_rows = sorted(row_to_cells)
        touched_cols = sorted(col_to_cells)
        for r in touched_rows:
            row_regions[r].append(ri)
        for c in touched_cols:
            col_regions[c].append(ri)

        region_data.append({
            'id': rid,
            'cells': tuple(sorted(cells)),
            'states': states,
            'touched_rows': touched_rows,
            'touched_cols': touched_cols,
        })

    # Precompute masks of states by contribution value, for rows / cols / total.
    for reg in region_data:
        states = reg['states']
        reg['row_value_masks'] = [defaultdict(int) for _ in range(R)]
        reg['col_value_masks'] = [defaultdict(int) for _ in range(C)]
        reg['total_value_masks'] = defaultdict(int)

        for si, st in enumerate(states):
            bit = 1 << si
            reg['total_value_masks'][st['total']] |= bit
            for r in reg['touched_rows']:
                reg['row_value_masks'][r][st['row_amt'][r]] |= bit
            for c in reg['touched_cols']:
                reg['col_value_masks'][c][st['col_amt'][c]] |= bit

    full_domains = tuple((1 << len(reg['states'])) - 1 for reg in region_data)

    # Quick helper.
    def singleton_index(mask):
        return mask.bit_length() - 1 if mask and (mask & (mask - 1)) == 0 else None

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def line_filter(domains, regs, target, getter):
        # getter(ri) -> dict[value] = mask_of_states_having_that_value
        # Human-like line reasoning: exact clue on a row/column/total is a subset-sum
        # over region contributions. We keep only contribution values that participate
        # in at least one exact construction of the clue.
        if not regs:
            return target == 0, False

        possible_values = []
        value_masks = []

        for ri in regs:
            d = domains[ri]
            vm = getter(ri)
            vals = []
            masks = {}
            for v, m in vm.items():
                active = d & m
                if active:
                    vals.append(v)
                    masks[v] = active
            if not vals:
                return False, False
            possible_values.append(vals)
            value_masks.append(masks)

        # Prefix/suffix feasible-sum bitsets.
        prefix = [0] * (len(regs) + 1)
        prefix[0] = 1
        limit_mask = (1 << (target + 1)) - 1 if target >= 0 else 0

        for i, vals in enumerate(possible_values):
            bits = 0
            prev = prefix[i]
            for v in vals:
                if v <= target:
                    bits |= (prev << v)
            prefix[i + 1] = bits & limit_mask

        if ((prefix[-1] >> target) & 1) == 0:
            return False, False

        suffix = [0] * (len(regs) + 1)
        suffix[-1] = 1
        for i in range(len(regs) - 1, -1, -1):
            bits = 0
            nxt = suffix[i + 1]
            for v in possible_values[i]:
                if v <= target:
                    bits |= (nxt << v)
            suffix[i] = bits & limit_mask

        changed = False

        for i, ri in enumerate(regs):
            allowed_mask = 0
            pref = prefix[i]
            suff = suffix[i + 1]

            for v in possible_values[i]:
                rem = target - v
                if rem < 0:
                    continue

                supported = False
                tmp = pref & ((1 << (rem + 1)) - 1)
                while tmp:
                    lsb = tmp & -tmp
                    s = lsb.bit_length() - 1
                    if (suff >> (rem - s)) & 1:
                        supported = True
                        break
                    tmp ^= lsb

                if supported:
                    allowed_mask |= value_masks[i][v]

            new_domain = domains[ri] & allowed_mask
            if new_domain == 0:
                return False, False
            if new_domain != domains[ri]:
                domains[ri] = new_domain
                changed = True

        return True, changed

    def propagate(domains):
        domains = list(domains)

        while True:
            any_change = False

            # Region sanity.
            for ri in range(n_regions):
                if domains[ri] == 0:
                    return None

            # Global total-water exact sum.
            ok, changed = line_filter(
                domains,
                list(range(n_regions)),
                total_target,
                lambda ri: region_data[ri]['total_value_masks'],
            )
            if not ok:
                return None
            any_change |= changed

            # Row exact sums.
            for r in range(R):
                ok, changed = line_filter(
                    domains,
                    row_regions[r],
                    row_targets[r],
                    lambda ri, rr=r: region_data[ri]['row_value_masks'][rr],
                )
                if not ok:
                    return None
                any_change |= changed

            # Column exact sums.
            for c in range(C):
                ok, changed = line_filter(
                    domains,
                    col_regions[c],
                    col_targets[c],
                    lambda ri, cc=c: region_data[ri]['col_value_masks'][cc],
                )
                if not ok:
                    return None
                any_change |= changed

            # Cheap bound check using current min/max on each line.
            for r in range(R):
                mn = 0
                mx = 0
                for ri in row_regions[r]:
                    d = domains[ri]
                    vals = [region_data[ri]['states'][si]['row_amt'][r] for si in iter_bits(d)]
                    mn += min(vals)
                    mx += max(vals)
                if not (mn <= row_targets[r] <= mx):
                    return None

            for c in range(C):
                mn = 0
                mx = 0
                for ri in col_regions[c]:
                    d = domains[ri]
                    vals = [region_data[ri]['states'][si]['col_amt'][c] for si in iter_bits(d)]
                    mn += min(vals)
                    mx += max(vals)
                if not (mn <= col_targets[c] <= mx):
                    return None

            if not any_change:
                return tuple(domains)

    fail_cache = set()

    def choose_region(domains):
        # Most constrained region first; tie-break by total impact on lines.
        best = None
        best_key = None
        for ri in range(n_regions):
            size = domains[ri].bit_count()
            if size <= 1:
                continue
            impact = len(region_data[ri]['touched_rows']) + len(region_data[ri]['touched_cols'])
            key = (size, -impact)
            if best is None or key < best_key:
                best = ri
                best_key = key
        return best

    def state_order(ri, domain_mask):
        # Prefer states closer to global average fill of the region.
        states = region_data[ri]['states']
        avg = total_target * len(region_data[ri]['cells']) / (R * C)
        order = list(iter_bits(domain_mask))
        order.sort(key=lambda si: (abs(states[si]['total'] - avg), states[si]['total']))
        return order

    def build_answer(domains):
        ans = [[None for _ in range(C)] for _ in range(R)]
        for ri in range(n_regions):
            si = singleton_index(domains[ri])
            if si is None:
                return None
            for r, c in region_data[ri]['states'][si]['water_cells']:
                ans[r][c] = 'W'

        # Final validation.
        if [sum(1 for c in range(C) if ans[r][c] == 'W') for r in range(R)] != row_targets:
            return None
        if [sum(1 for r in range(R) if ans[r][c] == 'W') for c in range(C)] != col_targets:
            return None

        return ans

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        if domains in fail_cache:
            return None

        if all((d & (d - 1)) == 0 for d in domains):
            return build_answer(domains)

        ri = choose_region(domains)
        if ri is None:
            return build_answer(domains)

        for si in state_order(ri, domains[ri]):
            new_domains = list(domains)
            new_domains[ri] = 1 << si
            res = search(tuple(new_domains))
            if res is not None:
                return res

        fail_cache.add(domains)
        return None

    result = search(full_domains)
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

