from collections import deque
from itertools import combinations
import math


def solve(observation):
    data = observation['data']
    h = len(data)
    w = len(data[0]) if h else 0

    def is_white(r, c):
        return 0 <= r < h and 0 <= c < w and data[r][c] is None

    white_cells = []
    white_id = {}
    clues = []
    clue_req = []
    clue_adj = []

    for r in range(h):
        for c in range(w):
            if data[r][c] is None:
                white_id[(r, c)] = len(white_cells)
                white_cells.append((r, c))

    for r in range(h):
        for c in range(w):
            if isinstance(data[r][c], int) and data[r][c] >= 0:
                clues.append((r, c))
                clue_req.append(data[r][c])

    W = len(white_cells)
    C = len(clues)

    white_to_clues = [[] for _ in range(W)]
    for ci, (r, c) in enumerate(clues):
        adj = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if is_white(nr, nc):
                wid = white_id[(nr, nc)]
                adj.append(wid)
                white_to_clues[wid].append(ci)
        clue_adj.append(tuple(adj))

    conflict = [[] for _ in range(W)]
    litset = [[] for _ in range(W)]

    for wid, (r, c) in enumerate(white_cells):
        seen = [wid]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            while 0 <= nr < h and 0 <= nc < w and data[nr][nc] is None:
                seen.append(white_id[(nr, nc)])
                nr += dr
                nc += dc
        litset[wid] = tuple(seen)
        conflict[wid] = tuple(x for x in seen if x != wid)

    candset = [[] for _ in range(W)]
    for wid in range(W):
        for t in litset[wid]:
            candset[t].append(wid)
    candset = [tuple(v) for v in candset]

    impact = [len(litset[wid]) * 4 + len(white_to_clues[wid]) * 7 for wid in range(W)]

    def clone_state(state):
        return {
            'assign': state['assign'][:],          # 0 unknown, 1 bulb, -1 empty
            'illum': state['illum'][:],            # number of bulbs lighting each white
            'clue_bulbs': state['clue_bulbs'][:],  # bulbs adjacent to each clue
            'clue_unknown': state['clue_unknown'][:],
        }

    def can_still_be_bulb(state, wid):
        a = state['assign'][wid]
        if a == 1:
            return True
        if a == -1:
            return False

        for other in conflict[wid]:
            if state['assign'][other] == 1:
                return False

        for ci in white_to_clues[wid]:
            b = state['clue_bulbs'][ci]
            u = state['clue_unknown'][ci]
            req = clue_req[ci]
            if b + 1 > req:
                return False
            if b + 1 + (u - 1) < req:
                return False

        return True

    def propagate(state, initial_moves=None, full_scan=False):
        assign = state['assign']
        illum = state['illum']
        clue_bulbs = state['clue_bulbs']
        clue_unknown = state['clue_unknown']

        clue_q = deque(range(C)) if full_scan else deque()
        cell_q = deque(range(W)) if full_scan else deque()
        target_q = deque(range(W)) if full_scan else deque()

        def assign_cell(wid, val):
            cur = assign[wid]
            if cur == val:
                return True
            if cur != 0:
                return False

            assign[wid] = val
            cell_q.append(wid)
            target_q.append(wid)

            if val == -1:
                for ci in white_to_clues[wid]:
                    clue_unknown[ci] -= 1
                    clue_q.append(ci)
                    for aw in clue_adj[ci]:
                        cell_q.append(aw)
                for t in litset[wid]:
                    target_q.append(t)
                return True

            for ci in white_to_clues[wid]:
                clue_bulbs[ci] += 1
                clue_unknown[ci] -= 1
                clue_q.append(ci)
                for aw in clue_adj[ci]:
                    cell_q.append(aw)

            for t in litset[wid]:
                illum[t] += 1
                target_q.append(t)

            for other in conflict[wid]:
                if assign[other] == 1:
                    return False
                if assign[other] == 0:
                    if not assign_cell(other, -1):
                        return False

            return True

        if initial_moves:
            for wid, val in initial_moves:
                if not assign_cell(wid, val):
                    return False

        while clue_q or cell_q or target_q:
            while clue_q:
                ci = clue_q.popleft()
                req = clue_req[ci]
                b = clue_bulbs[ci]
                if b > req:
                    return False

                unknowns = [wid for wid in clue_adj[ci] if assign[wid] == 0]
                u = len(unknowns)
                if b + u < req:
                    return False

                if b == req:
                    for wid in unknowns:
                        if not assign_cell(wid, -1):
                            return False
                elif b + u == req:
                    for wid in unknowns:
                        if not assign_cell(wid, 1):
                            return False

            while cell_q:
                wid = cell_q.popleft()
                if assign[wid] == 0 and not can_still_be_bulb(state, wid):
                    if not assign_cell(wid, -1):
                        return False

            while target_q:
                t = target_q.popleft()
                if illum[t] > 0:
                    continue

                feasible = []
                for wid in candset[t]:
                    a = assign[wid]
                    if a == 1:
                        feasible = [wid]
                        break
                    if a == 0 and can_still_be_bulb(state, wid):
                        feasible.append(wid)

                if not feasible:
                    return False

                if len(feasible) == 1:
                    if not assign_cell(feasible[0], 1):
                        return False

        return True

    def solved(state):
        for ci in range(C):
            if state['clue_bulbs'][ci] != clue_req[ci]:
                return False
        for wid in range(W):
            if state['illum'][wid] == 0:
                return False
        return True

    def choose_branch(state):
        best = None
        best_count = 10**9

        for ci in range(C):
            rem = clue_req[ci] - state['clue_bulbs'][ci]
            if rem <= 0:
                continue
            unknowns = [wid for wid in clue_adj[ci] if state['assign'][wid] == 0]
            u = len(unknowns)
            if rem >= u:
                continue
            cnt = math.comb(u, rem)
            if cnt < best_count:
                best_count = cnt
                best = ('clue', ci, tuple(unknowns), rem)
                if cnt == 2:
                    break

        if best is not None:
            return best

        best_target = None
        best_len = 10**9
        best_cell = None

        for t in range(W):
            if state['illum'][t] > 0:
                continue
            feasible = []
            for wid in candset[t]:
                a = state['assign'][wid]
                if a == 1:
                    feasible = [wid]
                    break
                if a == 0 and can_still_be_bulb(state, wid):
                    feasible.append(wid)

            lf = len(feasible)
            if lf == 0:
                return ('dead',)
            if lf == 1:
                return ('force', feasible[0])

            if lf < best_len:
                best_len = lf
                best_target = t
                best_cell = max(feasible, key=lambda x: (impact[x], len(white_to_clues[x])))

        if best_target is not None:
            return ('cell', best_cell)

        unknowns = [wid for wid in range(W) if state['assign'][wid] == 0]
        if unknowns:
            wid = max(unknowns, key=lambda x: (len(white_to_clues[x]), impact[x]))
            return ('cell', wid)

        return None

    def dfs(state):
        if solved(state):
            return state

        branch = choose_branch(state)
        if branch is None:
            return state if solved(state) else None

        kind = branch[0]

        if kind == 'dead':
            return None

        if kind == 'force':
            ns = clone_state(state)
            if propagate(ns, [(branch[1], 1)], False):
                return dfs(ns)
            return None

        if kind == 'clue':
            _, ci, unknowns, rem = branch

            feasible = [wid for wid in unknowns if can_still_be_bulb(state, wid)]
            if len(feasible) < rem:
                return None

            if len(feasible) != len(unknowns):
                ns = clone_state(state)
                moves = [(wid, -1) for wid in unknowns if wid not in feasible]
                if propagate(ns, moves, False):
                    return dfs(ns)
                return None

            combos = list(combinations(unknowns, rem))
            combos.sort(key=lambda combo: -sum(impact[wid] for wid in combo))

            unknown_set = tuple(unknowns)
            for combo in combos:
                chosen = set(combo)
                moves = [(wid, 1 if wid in chosen else -1) for wid in unknown_set]
                ns = clone_state(state)
                if propagate(ns, moves, False):
                    res = dfs(ns)
                    if res is not None:
                        return res
            return None

        if kind == 'cell':
            wid = branch[1]

            if can_still_be_bulb(state, wid):
                ns = clone_state(state)
                if propagate(ns, [(wid, 1)], False):
                    res = dfs(ns)
                    if res is not None:
                        return res

            ns = clone_state(state)
            if propagate(ns, [(wid, -1)], False):
                return dfs(ns)

            return None

        return None

    state = {
        'assign': [0] * W,
        'illum': [0] * W,
        'clue_bulbs': [0] * C,
        'clue_unknown': [len(adj) for adj in clue_adj],
    }

    if not propagate(state, full_scan=True):
        return "No Solution"

    result = dfs(state)
    if result is None:
        return "No Solution"

    ans = [[None for _ in range(w)] for _ in range(h)]
    for wid, (r, c) in enumerate(white_cells):
        if result['assign'][wid] == 1:
            ans[r][c] = 'B'
    return repr(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], ['B', None, None, 'W', None, 'B'], [None, None, None, None, None, None], [None, None, None, None, 'W', None], [None, 'W', 'W', None, None, 'B'], [None, 'W', None, 'B', None, None]]}

from functools import lru_cache


def solve(observation):
    grid = [row[:] for row in observation['data']]
    if not grid or not grid[0]:
        return "No Solution"

    n = len(grid)
    m = len(grid[0])

    if n % 2 != 0 or m % 2 != 0:
        return "No Solution"

    row_patterns = list(generate_patterns(m))
    col_patterns = list(generate_patterns(n))

    result = search(
        grid=grid,
        initial=observation['data'],
        row_domains=None,
        col_domains=None,
        row_patterns=row_patterns,
        col_patterns=col_patterns,
    )

    if result is None:
        return "No Solution"
    return result


def opposite(v):
    return 'B' if v == 'W' else 'W'


@lru_cache(maxsize=None)
def generate_patterns(length):
    half = length // 2
    out = []

    def bt(pos, b_count, w_count, a, b, prefix):
        remaining = length - pos

        if b_count > half or w_count > half:
            return
        if b_count + remaining < half or w_count + remaining < half:
            return

        if pos == length:
            if b_count == half and w_count == half:
                out.append(tuple(prefix))
            return

        for v in ('B', 'W'):
            if pos >= 2 and a == b == v:
                continue
            prefix.append(v)
            if v == 'B':
                bt(pos + 1, b_count + 1, w_count, b, v, prefix)
            else:
                bt(pos + 1, b_count, w_count + 1, b, v, prefix)
            prefix.pop()

    bt(0, 0, 0, None, None, [])
    return tuple(out)


def search(grid, initial, row_domains, col_domains, row_patterns, col_patterns):
    propagated = propagate(grid, row_domains, col_domains, row_patterns, col_patterns)
    if propagated is None:
        return None

    grid, row_domains, col_domains = propagated

    if all(all(cell is not None for cell in row) for row in grid):
        if verify(grid, initial):
            return [row[:] for row in grid]
        return None

    choice = choose_branch(row_domains, col_domains)
    if choice is None:
        if verify(grid, initial):
            return [row[:] for row in grid]
        return None

    kind, idx, domain = choice

    for pattern in domain:
        new_grid = [row[:] for row in grid]
        ok = True

        if kind == 'row':
            for c, v in enumerate(pattern):
                state = assign_cell(new_grid, idx, c, v)
                if state < 0:
                    ok = False
                    break
            if not ok:
                continue
            new_row_domains = [d[:] for d in row_domains]
            new_col_domains = [d[:] for d in col_domains]
            new_row_domains[idx] = [pattern]
        else:
            for r, v in enumerate(pattern):
                state = assign_cell(new_grid, r, idx, v)
                if state < 0:
                    ok = False
                    break
            if not ok:
                continue
            new_row_domains = [d[:] for d in row_domains]
            new_col_domains = [d[:] for d in col_domains]
            new_col_domains[idx] = [pattern]

        result = search(
            new_grid,
            initial,
            new_row_domains,
            new_col_domains,
            row_patterns,
            col_patterns,
        )
        if result is not None:
            return result

    return None


def choose_branch(row_domains, col_domains):
    best = None

    for i, d in enumerate(row_domains):
        if 1 < len(d) and (best is None or len(d) < best[2]):
            best = ('row', i, len(d), d)

    for i, d in enumerate(col_domains):
        if 1 < len(d) and (best is None or len(d) < best[2]):
            best = ('col', i, len(d), d)

    if best is None:
        return None
    return best[0], best[1], best[3]


def propagate(grid, row_domains, col_domains, row_patterns, col_patterns):
    n = len(grid)
    m = len(grid[0])

    if row_domains is None:
        row_domains = [filter_line_patterns(row_patterns, grid[r]) for r in range(n)]
    else:
        row_domains = [d[:] for d in row_domains]

    if col_domains is None:
        cols = get_cols(grid)
        col_domains = [filter_line_patterns(col_patterns, cols[c]) for c in range(m)]
    else:
        col_domains = [d[:] for d in col_domains]

    while True:
        changed = False

        # Human-style local deductions first: balance and no-three-in-a-row.
        for r in range(n):
            forced = deduce_line(grid[r])
            if forced is None:
                return None
            for c, v in forced.items():
                state = assign_cell(grid, r, c, v)
                if state < 0:
                    return None
                if state > 0:
                    changed = True

        cols = get_cols(grid)
        for c in range(m):
            forced = deduce_line(cols[c])
            if forced is None:
                return None
            for r, v in forced.items():
                state = assign_cell(grid, r, c, v)
                if state < 0:
                    return None
                if state > 0:
                    changed = True

        # Domains must match the current grid.
        for r in range(n):
            new_domain = [p for p in row_domains[r] if pattern_matches_line(p, grid[r])]
            if not new_domain:
                return None
            if len(new_domain) != len(row_domains[r]):
                row_domains[r] = new_domain
                changed = True

        cols = get_cols(grid)
        for c in range(m):
            new_domain = [p for p in col_domains[c] if pattern_matches_line(p, cols[c])]
            if not new_domain:
                return None
            if len(new_domain) != len(col_domains[c]):
                col_domains[c] = new_domain
                changed = True

        # Uniqueness of completed rows/columns.
        if not enforce_uniqueness(row_domains):
            return None
        if not enforce_uniqueness(col_domains):
            return None

        # Cell-wise support from row and column domains.
        row_support = [[set() for _ in range(m)] for _ in range(n)]
        for r in range(n):
            for p in row_domains[r]:
                for c, v in enumerate(p):
                    row_support[r][c].add(v)

        col_support = [[set() for _ in range(n)] for _ in range(m)]
        for c in range(m):
            for p in col_domains[c]:
                for r, v in enumerate(p):
                    col_support[c][r].add(v)

        for r in range(n):
            for c in range(m):
                allowed = row_support[r][c] & col_support[c][r]
                if not allowed:
                    return None
                if len(allowed) == 1:
                    v = next(iter(allowed))
                    state = assign_cell(grid, r, c, v)
                    if state < 0:
                        return None
                    if state > 0:
                        changed = True

        # Cross-filter row domains by column supports.
        for r in range(n):
            new_domain = [
                p for p in row_domains[r]
                if all(p[c] in col_support[c][r] for c in range(m))
            ]
            if not new_domain:
                return None
            if len(new_domain) != len(row_domains[r]):
                row_domains[r] = new_domain
                changed = True

        # Cross-filter column domains by row supports.
        for c in range(m):
            new_domain = [
                p for p in col_domains[c]
                if all(p[r] in row_support[r][c] for r in range(n))
            ]
            if not new_domain:
                return None
            if len(new_domain) != len(col_domains[c]):
                col_domains[c] = new_domain
                changed = True

        # If a line is fully determined by its domain, write it into the grid.
        for r in range(n):
            if len(row_domains[r]) == 1:
                p = row_domains[r][0]
                for c, v in enumerate(p):
                    state = assign_cell(grid, r, c, v)
                    if state < 0:
                        return None
                    if state > 0:
                        changed = True

        for c in range(m):
            if len(col_domains[c]) == 1:
                p = col_domains[c][0]
                for r, v in enumerate(p):
                    state = assign_cell(grid, r, c, v)
                    if state < 0:
                        return None
                    if state > 0:
                        changed = True

        if not changed:
            break

    if not partial_valid(grid):
        return None

    return grid, row_domains, col_domains


def enforce_uniqueness(domains):
    fixed = {}
    for i, d in enumerate(domains):
        if len(d) == 1:
            p = d[0]
            if p in fixed:
                return False
            fixed[p] = i

    fixed_patterns = set(fixed.keys())
    for i, d in enumerate(domains):
        if len(d) > 1:
            new_domain = [p for p in d if p not in fixed_patterns]
            if not new_domain:
                return False
            if len(new_domain) != len(d):
                domains[i] = new_domain
    return True


def filter_line_patterns(all_patterns, line):
    return [p for p in all_patterns if pattern_matches_line(p, line)]


def pattern_matches_line(pattern, line):
    return all(cell is None or cell == pattern[i] for i, cell in enumerate(line))


def get_cols(grid):
    return [list(col) for col in zip(*grid)]


def assign_cell(grid, r, c, v):
    cur = grid[r][c]
    if cur is None:
        grid[r][c] = v
        return 1
    if cur == v:
        return 0
    return -1


def deduce_line(line):
    length = len(line)
    half = length // 2
    forced = {}

    def add(pos, val):
        cur = line[pos]
        if cur is not None and cur != val:
            return False
        if pos in forced and forced[pos] != val:
            return False
        forced[pos] = val
        return True

    b_count = sum(1 for x in line if x == 'B')
    w_count = sum(1 for x in line if x == 'W')

    if b_count > half or w_count > half:
        return None

    for i in range(length - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and a == b == c:
            return None

    if b_count == half:
        for i, x in enumerate(line):
            if x is None and not add(i, 'W'):
                return None

    if w_count == half:
        for i, x in enumerate(line):
            if x is None and not add(i, 'B'):
                return None

    for i in range(length - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]

        if a == b and a is not None and c is None:
            if not add(i + 2, opposite(a)):
                return None
        if b == c and b is not None and a is None:
            if not add(i, opposite(b)):
                return None
        if a == c and a is not None and b is None:
            if not add(i + 1, opposite(a)):
                return None

    return forced


def partial_valid(grid):
    n = len(grid)
    m = len(grid[0])

    for r in range(n):
        if not partial_line_valid(grid[r]):
            return False

    for c in range(m):
        col = [grid[r][c] for r in range(n)]
        if not partial_line_valid(col):
            return False

    # Completed rows must already be unique.
    seen = set()
    for r in range(n):
        if all(x is not None for x in grid[r]):
            t = tuple(grid[r])
            if t in seen:
                return False
            seen.add(t)

    # Completed columns must already be unique.
    seen = set()
    for c in range(m):
        col = tuple(grid[r][c] for r in range(n))
        if all(x is not None for x in col):
            if col in seen:
                return False
            seen.add(col)

    return True


def partial_line_valid(line):
    length = len(line)
    half = length // 2

    if sum(1 for x in line if x == 'B') > half:
        return False
    if sum(1 for x in line if x == 'W') > half:
        return False

    for i in range(length - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and a == b == c:
            return False

    return True


def verify(grid, initial):
    n = len(grid)
    m = len(grid[0])

    for r in range(n):
        for c in range(m):
            if grid[r][c] not in ('B', 'W'):
                return False
            if initial[r][c] is not None and grid[r][c] != initial[r][c]:
                return False

    for r in range(n):
        row = grid[r]
        if row.count('B') != m // 2 or row.count('W') != m // 2:
            return False
        for i in range(m - 2):
            if row[i] == row[i + 1] == row[i + 2]:
                return False

    for c in range(m):
        col = [grid[r][c] for r in range(n)]
        if col.count('B') != n // 2 or col.count('W') != n // 2:
            return False
        for i in range(n - 2):
            if col[i] == col[i + 1] == col[i + 2]:
                return False

    rows = [tuple(row) for row in grid]
    if len(set(rows)) != len(rows):
        return False

    cols = [tuple(grid[r][c] for r in range(n)) for c in range(m)]
    if len(set(cols)) != len(cols):
        return False

    return True


