from collections import deque


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n
    full = (1 << n) - 1

    # Precompute row/col units and peers.
    row_units = [[r * n + c for c in range(n)] for r in range(n)]
    col_units = [[r * n + c for r in range(n)] for c in range(n)]
    peers = []
    for r in range(n):
        for c in range(n):
            s = set(row_units[r] + col_units[c])
            s.remove(r * n + c)
            peers.append(tuple(s))

    # Bit helpers.
    popcount = [0] * (full + 1)
    lowest_val = [0] * (full + 1)
    highest_val = [0] * (full + 1)
    prefix = [0] * (n + 1)
    acc = 0
    for v in range(1, n + 1):
        acc |= 1 << (v - 1)
        prefix[v] = acc
    for mask in range(1, full + 1):
        popcount[mask] = mask.bit_count()
        lb = mask & -mask
        lowest_val[mask] = lb.bit_length()
        highest_val[mask] = mask.bit_length()

    # less_mask[v] = values strictly less than v
    # greater_mask[v] = values strictly greater than v
    less_mask = [0] * (n + 1)
    greater_mask = [0] * (n + 1)
    for v in range(1, n + 1):
        less_mask[v] = prefix[v - 1]
        greater_mask[v] = full ^ prefix[v]

    subset_masks = [mask for mask in range(1, full + 1) if 2 <= popcount[mask] <= n - 1]

    def range_mask(lo, hi):
        if lo > hi:
            return 0
        return prefix[hi] & ~prefix[lo - 1]

    def parse_coord(key):
        if isinstance(key, tuple):
            return float(key[0]), float(key[1])
        s = str(key).strip()
        if s.startswith("(") and s.endswith(")"):
            s = s[1:-1]
        a, b = s.split(",")
        return float(a), float(b)

    def build_edges(h_reverse=False, v_reverse=False):
        edges = []

        # Horizontal: symbol sits between (r,c) and (r,c+1)
        for key, sym in observation.get("horizontal", {}).items():
            rr, cc = parse_coord(key)
            r = int(round(rr))
            c = int(round(cc - 0.5))
            left = r * n + c
            right = r * n + (c + 1)
            less = (sym == "<")
            if h_reverse:
                less = not less
            edges.append((left, right) if less else (right, left))

        # Vertical: symbol sits between (r,c) and (r+1,c)
        for key, sym in observation.get("vertical", {}).items():
            rr, cc = parse_coord(key)
            r = int(round(rr - 0.5))
            c = int(round(cc))
            top = r * n + c
            bottom = (r + 1) * n + c
            less = (sym == "^")
            if v_reverse:
                less = not less
            edges.append((top, bottom) if less else (bottom, top))

        return edges

    def solve_with_edges(edges):
        out_edges = [[] for _ in range(m)]
        in_edges = [[] for _ in range(m)]
        indeg = [0] * m
        for a, b in edges:
            out_edges[a].append(b)
            in_edges[b].append(a)
            indeg[b] += 1

        # Topological check and inequality-chain bounds.
        dq = deque(i for i in range(m) if indeg[i] == 0)
        topo = []
        while dq:
            u = dq.popleft()
            topo.append(u)
            for v in out_edges[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    dq.append(v)
        if len(topo) != m:
            return None

        low_bound = [1] * m
        for u in topo:
            nxt = low_bound[u] + 1
            for v in out_edges[u]:
                if nxt > low_bound[v]:
                    low_bound[v] = nxt

        desc_len = [0] * m
        for u in reversed(topo):
            best = 0
            for v in out_edges[u]:
                cand = desc_len[v] + 1
                if cand > best:
                    best = cand
            desc_len[u] = best
        high_bound = [n - desc_len[i] for i in range(m)]

        # Initialize domains from givens + inequality-chain bounds.
        domains = [full] * m
        for r in range(n):
            for c in range(n):
                idx = r * n + c
                lo = low_bound[idx]
                hi = high_bound[idx]
                if lo > hi:
                    return None
                mask = range_mask(lo, hi)
                val = data[r][c]
                if val is not None:
                    bit = 1 << (val - 1)
                    if not (mask & bit):
                        return None
                    mask = bit
                if mask == 0:
                    return None
                domains[idx] = mask

        def propagate(curr):
            assigned_done = [0] * m
            q = deque(range(m))
            in_q = [True] * m
            dirty_rows = set(range(n))
            dirty_cols = set(range(n))

            def enqueue(idx):
                if not in_q[idx]:
                    in_q[idx] = True
                    q.append(idx)

            def set_domain(idx, new_mask):
                if new_mask == 0:
                    return False
                if new_mask == curr[idx]:
                    return True
                curr[idx] = new_mask
                enqueue(idx)
                dirty_rows.add(idx // n)
                dirty_cols.add(idx % n)
                return True

            def check_unit(unit):
                # Fixed-value duplicates and value coverage.
                seen_fixed = 0
                occ = [0] * n
                last = [-1] * n

                for idx in unit:
                    d = curr[idx]
                    if d == 0:
                        return False
                    if d & (d - 1) == 0:
                        if seen_fixed & d:
                            return False
                        seen_fixed |= d
                    x = d
                    while x:
                        b = x & -x
                        v = b.bit_length() - 1
                        occ[v] += 1
                        last[v] = idx
                        x -= b

                # Hidden singles and missing values.
                for v in range(n):
                    if occ[v] == 0:
                        return False
                    if occ[v] == 1:
                        if not set_domain(last[v], 1 << v):
                            return False

                # Hall-style subset checks:
                # 1) Naked subsets: if k cells are confined to k values, remove those values elsewhere.
                # 2) Hidden subsets: if k values can only appear in k cells, restrict those cells.
                for mask in subset_masks:
                    k = popcount[mask]
                    subset_cells = []
                    any_cells = []

                    for idx in unit:
                        d = curr[idx]
                        if d & mask:
                            any_cells.append(idx)
                        if d & ~mask == 0:
                            subset_cells.append(idx)

                    cs = len(subset_cells)
                    if cs > k:
                        return False
                    if cs == k and cs:
                        subset_set = set(subset_cells)
                        for idx in unit:
                            if idx not in subset_set:
                                d = curr[idx]
                                if d & mask:
                                    if not set_domain(idx, d & ~mask):
                                        return False

                    ca = len(any_cells)
                    if ca < k:
                        return False
                    if ca == k:
                        for idx in any_cells:
                            d = curr[idx]
                            nd = d & mask
                            if nd != d:
                                if not set_domain(idx, nd):
                                    return False
                return True

            while q or dirty_rows or dirty_cols:
                while q:
                    idx = q.popleft()
                    in_q[idx] = False
                    d = curr[idx]
                    if d == 0:
                        return False

                    # Revise this cell against all inequality neighbors.
                    nd = d
                    for j in out_edges[idx]:
                        nd &= less_mask[highest_val[curr[j]]]
                        if nd == 0:
                            return False
                    for j in in_edges[idx]:
                        nd &= greater_mask[lowest_val[curr[j]]]
                        if nd == 0:
                            return False
                    if nd != d:
                        if not set_domain(idx, nd):
                            return False
                        continue

                    # Singleton propagation through row/column all-different.
                    if d & (d - 1) == 0 and assigned_done[idx] != d:
                        assigned_done[idx] = d
                        for j in peers[idx]:
                            if curr[j] & d:
                                if not set_domain(j, curr[j] & ~d):
                                    return False

                    # Push inequality effects onto neighbors.
                    lo = lowest_val[d]
                    hi = highest_val[d]

                    for j in out_edges[idx]:
                        ndj = curr[j] & greater_mask[lo]
                        if ndj != curr[j]:
                            if not set_domain(j, ndj):
                                return False

                    for j in in_edges[idx]:
                        ndj = curr[j] & less_mask[hi]
                        if ndj != curr[j]:
                            if not set_domain(j, ndj):
                                return False

                if dirty_rows or dirty_cols:
                    rows = list(dirty_rows)
                    cols = list(dirty_cols)
                    dirty_rows.clear()
                    dirty_cols.clear()

                    for r in rows:
                        if not check_unit(row_units[r]):
                            return False
                    for c in cols:
                        if not check_unit(col_units[c]):
                            return False

            return True

        def choose_cell(curr):
            best_idx = -1
            best_size = n + 1
            best_degree = -1
            for idx, d in enumerate(curr):
                sz = popcount[d]
                if 1 < sz < best_size:
                    best_idx = idx
                    best_size = sz
                    best_degree = len(out_edges[idx]) + len(in_edges[idx])
                elif sz == best_size:
                    deg = len(out_edges[idx]) + len(in_edges[idx])
                    if deg > best_degree:
                        best_idx = idx
                        best_degree = deg
            return best_idx

        def ordered_bits(mask, idx):
            bits = []
            x = mask
            while x:
                b = x & -x
                bits.append(b)
                x -= b
            # If the cell must be smaller than many neighbors, prefer small values first.
            # If it must be larger than many neighbors, prefer large values first.
            if len(in_edges[idx]) > len(out_edges[idx]):
                bits.reverse()
            return bits

        def dfs(curr):
            if not propagate(curr):
                return None

            done = True
            for d in curr:
                if d & (d - 1):
                    done = False
                    break
            if done:
                return curr

            idx = choose_cell(curr)
            if idx < 0:
                return None

            for bit in ordered_bits(curr[idx], idx):
                nxt = curr.copy()
                nxt[idx] = bit
                ans = dfs(nxt)
                if ans is not None:
                    return ans
            return None

        solved = dfs(domains)
        if solved is None:
            return None

        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                bit = solved[r * n + c]
                if bit == 0 or (bit & (bit - 1)) != 0:
                    return None
                row.append(bit.bit_length())
            grid.append(row)
        return grid

    # Try standard interpretation first.
    convention_order = [
        (False, False),  # horizontal direct, vertical direct
        (False, True),   # horizontal direct, vertical reversed
        (True, False),   # horizontal reversed, vertical direct
        (True, True),    # horizontal reversed, vertical reversed
    ]

    for h_rev, v_rev in convention_order:
        edges = build_edges(h_reverse=h_rev, v_reverse=v_rev)
        ans = solve_with_edges(edges)
        if ans is not None:
            return ans

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, None, None], [None, None, None, 2, 4], [None, None, None, None, None], [None, None, None, None, None]], 'adjacent': [[0.0, 0.5], [0.0, 2.5], [0.5, 1.0], [0.5, 4.0], [1.0, 1.5], [1.0, 2.5], [1.5, 2.0], [2.5, 0.0], [3.0, 2.5], [3.5, 3.0], [4.0, 1.5]]}

import itertools


def solve(observation):
    data = observation["data"]
    N = len(data)
    if N == 0 or any(len(row) != N for row in data):
        return "No Solution"

    def is_int(x):
        return abs(x - round(x)) < 1e-9

    def is_half(x):
        return abs((x - int(x)) - 0.5) < 1e-9 or abs((x - int(x)) + 0.5) < 1e-9

    row_dot = [[False] * (N - 1) for _ in range(N)]
    col_dot = [[False] * N for _ in range(N - 1)]

    for a, b in observation["adjacent"]:
        a = float(a)
        b = float(b)
        if is_int(a) and not is_int(b):
            r = int(round(a))
            c = int(round(b - 0.5))
            if 0 <= r < N and 0 <= c < N - 1:
                row_dot[r][c] = True
        elif not is_int(a) and is_int(b):
            r = int(round(a - 0.5))
            c = int(round(b))
            if 0 <= r < N - 1 and 0 <= c < N:
                col_dot[r][c] = True

    full_mask = (1 << N) - 1

    def bit(v):
        return 1 << (v - 1)

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def single_value(mask):
        return mask.bit_length()

    domains = [[full_mask for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                v = data[r][c]
                if not (1 <= v <= N):
                    return "No Solution"
                domains[r][c] = bit(v)

    perms = list(itertools.permutations(range(1, N + 1)))
    pattern_cache = {}

    def candidates_for_pattern(pattern):
        key = tuple(pattern)
        if key not in pattern_cache:
            out = []
            for p in perms:
                ok = True
                for i, want_consecutive in enumerate(key):
                    if ((abs(p[i] - p[i + 1]) == 1) != want_consecutive):
                        ok = False
                        break
                if ok:
                    out.append(p)
            pattern_cache[key] = out
        return pattern_cache[key]

    row_base = []
    for r in range(N):
        fixed = data[r]
        cands = []
        for p in candidates_for_pattern(row_dot[r]):
            ok = True
            for c in range(N):
                if fixed[c] is not None and p[c] != fixed[c]:
                    ok = False
                    break
            if ok:
                cands.append(p)
        if not cands:
            return "No Solution"
        row_base.append(cands)

    col_base = []
    for c in range(N):
        fixed = [data[r][c] for r in range(N)]
        pattern = [col_dot[r][c] for r in range(N - 1)]
        cands = []
        for p in candidates_for_pattern(pattern):
            ok = True
            for r in range(N):
                if fixed[r] is not None and p[r] != fixed[r]:
                    ok = False
                    break
            if ok:
                cands.append(p)
        if not cands:
            return "No Solution"
        col_base.append(cands)

    consec_masks = [0] * (N + 1)
    nonconsec_masks = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < N:
            m |= bit(v + 1)
        consec_masks[v] = m
        nonconsec_masks[v] = full_mask & ~m

    support_from = [[0] * (1 << N) for _ in range(2)]
    for other_mask in range(1 << N):
        good_non = 0
        good_con = 0
        for v in range(1, N + 1):
            b = bit(v)
            if nonconsec_masks[v] & other_mask:
                good_non |= b
            if consec_masks[v] & other_mask:
                good_con |= b
        support_from[0][other_mask] = good_non
        support_from[1][other_mask] = good_con

    edges = []
    for r in range(N):
        for c in range(N - 1):
            edges.append((r, c, r, c + 1, 1 if row_dot[r][c] else 0))
    for r in range(N - 1):
        for c in range(N):
            edges.append((r, c, r + 1, c, 1 if col_dot[r][c] else 0))

    def propagate(domains, row_cands, col_cands):
        while True:
            changed = False

            # Latin singleton elimination in rows.
            for r in range(N):
                assigned = 0
                for c in range(N):
                    m = domains[r][c]
                    if m == 0:
                        return False
                    if is_single(m):
                        if assigned & m:
                            return False
                        assigned |= m
                if assigned:
                    for c in range(N):
                        m = domains[r][c]
                        if not is_single(m):
                            nm = m & ~assigned
                            if nm == 0:
                                return False
                            if nm != m:
                                domains[r][c] = nm
                                changed = True

            # Latin singleton elimination in columns.
            for c in range(N):
                assigned = 0
                for r in range(N):
                    m = domains[r][c]
                    if m == 0:
                        return False
                    if is_single(m):
                        if assigned & m:
                            return False
                        assigned |= m
                if assigned:
                    for r in range(N):
                        m = domains[r][c]
                        if not is_single(m):
                            nm = m & ~assigned
                            if nm == 0:
                                return False
                            if nm != m:
                                domains[r][c] = nm
                                changed = True

            # Binary adjacency arc consistency.
            for r1, c1, r2, c2, rel in edges:
                da = domains[r1][c1]
                db = domains[r2][c2]

                nda = da & support_from[rel][db]
                if nda == 0:
                    return False
                if nda != da:
                    domains[r1][c1] = nda
                    da = nda
                    changed = True

                ndb = db & support_from[rel][da]
                if ndb == 0:
                    return False
                if ndb != db:
                    domains[r2][c2] = ndb
                    changed = True

            # Row permutation filtering + hidden singles.
            for r in range(N):
                old = row_cands[r]
                new = []
                pos_union = [0] * N
                value_posmask = [0] * (N + 1)

                for p in old:
                    ok = True
                    for c, v in enumerate(p):
                        if not (domains[r][c] & bit(v)):
                            ok = False
                            break
                    if ok:
                        new.append(p)
                        for c, v in enumerate(p):
                            b = bit(v)
                            pos_union[c] |= b
                            value_posmask[v] |= 1 << c

                if not new:
                    return False
                if len(new) != len(old):
                    row_cands[r] = new
                    changed = True

                for c in range(N):
                    nm = domains[r][c] & pos_union[c]
                    if nm == 0:
                        return False
                    if nm != domains[r][c]:
                        domains[r][c] = nm
                        changed = True

                for v in range(1, N + 1):
                    pm = value_posmask[v]
                    if pm and (pm & (pm - 1)) == 0:
                        c = pm.bit_length() - 1
                        nm = domains[r][c] & bit(v)
                        if nm == 0:
                            return False
                        if nm != domains[r][c]:
                            domains[r][c] = nm
                            changed = True

            # Column permutation filtering + hidden singles.
            for c in range(N):
                old = col_cands[c]
                new = []
                pos_union = [0] * N
                value_posmask = [0] * (N + 1)

                for p in old:
                    ok = True
                    for r, v in enumerate(p):
                        if not (domains[r][c] & bit(v)):
                            ok = False
                            break
                    if ok:
                        new.append(p)
                        for r, v in enumerate(p):
                            b = bit(v)
                            pos_union[r] |= b
                            value_posmask[v] |= 1 << r

                if not new:
                    return False
                if len(new) != len(old):
                    col_cands[c] = new
                    changed = True

                for r in range(N):
                    nm = domains[r][c] & pos_union[r]
                    if nm == 0:
                        return False
                    if nm != domains[r][c]:
                        domains[r][c] = nm
                        changed = True

                for v in range(1, N + 1):
                    pm = value_posmask[v]
                    if pm and (pm & (pm - 1)) == 0:
                        r = pm.bit_length() - 1
                        nm = domains[r][c] & bit(v)
                        if nm == 0:
                            return False
                        if nm != domains[r][c]:
                            domains[r][c] = nm
                            changed = True

            if not changed:
                return True

    def solved(domains):
        for r in range(N):
            for c in range(N):
                if not is_single(domains[r][c]):
                    return False
        return True

    def extract_grid(domains):
        return [[single_value(domains[r][c]) for c in range(N)] for r in range(N)]

    def copy_domains(domains):
        return [row[:] for row in domains]

    def order_row_candidates(r, cands, col_cands):
        scored = []
        for p in cands:
            s = 0
            for c, v in enumerate(p):
                cnt = 0
                for q in col_cands[c]:
                    if q[r] == v:
                        cnt += 1
                s += cnt
            scored.append((s, p))
        scored.sort(key=lambda x: x[0])
        return [p for _, p in scored]

    def order_col_candidates(c, cands, row_cands):
        scored = []
        for p in cands:
            s = 0
            for r, v in enumerate(p):
                cnt = 0
                for q in row_cands[r]:
                    if q[c] == v:
                        cnt += 1
                s += cnt
            scored.append((s, p))
        scored.sort(key=lambda x: x[0])
        return [p for _, p in scored]

    def order_cell_values(r, c, mask, row_cands, col_cands):
        vals = []
        m = mask
        while m:
            b = m & -m
            v = b.bit_length()
            s = 0
            for p in row_cands[r]:
                if p[c] == v:
                    s += 1
            for p in col_cands[c]:
                if p[r] == v:
                    s += 1
            vals.append((s, v))
            m -= b
        vals.sort()
        return [v for _, v in vals]

    dead = set()

    def state_key(domains):
        return tuple(tuple(row) for row in domains)

    def search(domains, row_cands, col_cands):
        if not propagate(domains, row_cands, col_cands):
            return None

        key = state_key(domains)
        if key in dead:
            return None

        if solved(domains):
            return extract_grid(domains)

        best_kind = None
        best_idx = None
        best_size = 10**9

        for r in range(N):
            k = len(row_cands[r])
            if 1 < k < best_size:
                best_kind = "row"
                best_idx = r
                best_size = k

        for c in range(N):
            k = len(col_cands[c])
            if 1 < k < best_size:
                best_kind = "col"
                best_idx = c
                best_size = k

        best_cell = None
        best_cell_size = 10**9
        for r in range(N):
            for c in range(N):
                k = domains[r][c].bit_count()
                if 1 < k < best_cell_size:
                    best_cell = (r, c)
                    best_cell_size = k

        if best_cell is not None and best_cell_size < best_size:
            r, c = best_cell
            for v in order_cell_values(r, c, domains[r][c], row_cands, col_cands):
                d2 = copy_domains(domains)
                rc2 = row_cands[:]
                cc2 = col_cands[:]
                d2[r][c] = bit(v)
                ans = search(d2, rc2, cc2)
                if ans is not None:
                    return ans
        elif best_kind == "row":
            r = best_idx
            for p in order_row_candidates(r, row_cands[r], col_cands):
                d2 = copy_domains(domains)
                rc2 = row_cands[:]
                cc2 = col_cands[:]
                for c, v in enumerate(p):
                    d2[r][c] = bit(v)
                rc2[r] = [p]
                ans = search(d2, rc2, cc2)
                if ans is not None:
                    return ans
        elif best_kind == "col":
            c = best_idx
            for p in order_col_candidates(c, col_cands[c], row_cands):
                d2 = copy_domains(domains)
                rc2 = row_cands[:]
                cc2 = col_cands[:]
                for r, v in enumerate(p):
                    d2[r][c] = bit(v)
                cc2[c] = [p]
                ans = search(d2, rc2, cc2)
                if ans is not None:
                    return ans
        else:
            dead.add(key)
            return None

        dead.add(key)
        return None

    row_cands = [lst[:] for lst in row_base]
    col_cands = [lst[:] for lst in col_base]
    ans = search(domains, row_cands, col_cands)
    return repr(ans) if ans is not None else "No Solution"


