# General Minesweeper solver:
# - strong propagation from direct clue saturation
# - subset deductions
# - overlap bounds deductions
# - connected-component decomposition
# - memoized depth-first search only on unresolved components

def solve(observation):
    data = observation["data"]
    rows = len(data)
    cols = len(data[0]) if rows else 0

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if 0 <= nr < rows:
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nc = c + dc
                    if 0 <= nc < cols:
                        yield nr, nc

    # Frontier variables are unrevealed cells adjacent to at least one clue.
    frontier_set = set()
    clues = []
    for r in range(rows):
        for c in range(cols):
            v = data[r][c]
            if v is not None:
                adj_unknown = []
                for nr, nc in neighbors(r, c):
                    if data[nr][nc] is None:
                        adj_unknown.append((nr, nc))
                        frontier_set.add((nr, nc))
                clues.append((r, c, v, adj_unknown))

    frontier = sorted(frontier_set)
    var_index = {cell: i for i, cell in enumerate(frontier)}
    nvars = len(frontier)

    # Build exact-sum constraints over frontier vars.
    constraints = []
    for _, _, clue, adj_unknown in clues:
        mask = 0
        for cell in adj_unknown:
            idx = var_index.get(cell)
            if idx is not None:
                mask |= 1 << idx
        constraints.append((mask, clue))

    def propagate(constraints_list, known_mask, mine_mask):
        # known_mask marks assigned vars; mine_mask is subset of known_mask.
        while True:
            progress = False
            reduced = {}

            # Basic saturation / emptiness rules
            for mask, target in constraints_list:
                assigned_mines = (mask & mine_mask).bit_count()
                undec_mask = mask & ~known_mask
                rem = target - assigned_mines
                free = undec_mask.bit_count()

                if rem < 0 or rem > free:
                    return None

                if free == 0:
                    if rem != 0:
                        return None
                    continue

                if rem == 0:
                    # all undecided safe
                    if undec_mask & mine_mask:
                        return None
                    if undec_mask:
                        known_mask |= undec_mask
                        progress = True
                    continue

                if rem == free:
                    # all undecided mines
                    safe_known = known_mask & ~mine_mask
                    if undec_mask & safe_known:
                        return None
                    if undec_mask:
                        known_mask |= undec_mask
                        mine_mask |= undec_mask
                        progress = True
                    continue

                prev = reduced.get(undec_mask)
                if prev is not None and prev != rem:
                    return None
                reduced[undec_mask] = rem

            if progress:
                continue

            items = sorted(reduced.items(), key=lambda x: x[0].bit_count())
            force_safe = 0
            force_mine = 0

            # Human-like set relations:
            # 1) subset rule
            # 2) overlap bound rule
            m = len(items)
            for i in range(m):
                A, a = items[i]
                for j in range(i + 1, m):
                    B, b = items[j]

                    # Subset rule: if A subset B, then B\A contains exactly b-a mines.
                    if A & B == A:
                        D = B ^ A
                        k = b - a
                        dsz = D.bit_count()
                        if k < 0 or k > dsz:
                            return None
                        if k == 0:
                            force_safe |= D
                        elif k == dsz:
                            force_mine |= D
                        continue

                    I = A & B
                    if not I:
                        continue

                    only_A = A ^ I
                    only_B = B ^ I
                    size_I = I.bit_count()
                    size_only_A = only_A.bit_count()
                    size_only_B = only_B.bit_count()

                    # Let x be mines in intersection I.
                    x_low = max(0, a - size_only_A, b - size_only_B)
                    x_high = min(size_I, a, b)
                    if x_low > x_high:
                        return None

                    # Intersection forced?
                    if x_high == 0:
                        force_safe |= I
                    elif x_low == size_I:
                        force_mine |= I

                    # only_A mines = a - x
                    y_low = a - x_high
                    y_high = a - x_low
                    if y_low > size_only_A or y_high < 0:
                        return None
                    if y_high == 0:
                        force_safe |= only_A
                    elif y_low == size_only_A:
                        force_mine |= only_A

                    # only_B mines = b - x
                    z_low = b - x_high
                    z_high = b - x_low
                    if z_low > size_only_B or z_high < 0:
                        return None
                    if z_high == 0:
                        force_safe |= only_B
                    elif z_low == size_only_B:
                        force_mine |= only_B

            if force_safe & force_mine:
                return None
            if force_safe & mine_mask:
                return None
            if force_mine & (known_mask & ~mine_mask):
                return None

            new_safe = force_safe & ~known_mask
            new_mine = force_mine & ~known_mask
            if new_safe or new_mine:
                known_mask |= new_safe | new_mine
                mine_mask |= new_mine
                progress = True

            if not progress:
                return known_mask, mine_mask

    def get_reduced_constraints(constraints_list, known_mask, mine_mask):
        reduced = {}
        for mask, target in constraints_list:
            assigned_mines = (mask & mine_mask).bit_count()
            undec_mask = mask & ~known_mask
            rem = target - assigned_mines
            free = undec_mask.bit_count()
            if rem < 0 or rem > free:
                return None
            if free == 0:
                if rem != 0:
                    return None
                continue
            prev = reduced.get(undec_mask)
            if prev is not None and prev != rem:
                return None
            reduced[undec_mask] = rem
        return list(reduced.items())

    def build_components(reduced_items):
        remaining = 0
        for mask, _ in reduced_items:
            remaining |= mask
        components = []
        while remaining:
            seed = remaining & -remaining
            comp = 0
            frontier_bits = seed
            while frontier_bits:
                comp |= frontier_bits
                added = 0
                for mask, _ in reduced_items:
                    if mask & frontier_bits:
                        added |= mask
                frontier_bits = added & ~comp
            components.append(comp)
            remaining &= ~comp
        return components

    def solve_component(component_mask, component_constraints):
        # Remap this component to a compact local bitspace.
        global_positions = []
        temp = component_mask
        while temp:
            b = temp & -temp
            global_positions.append(b.bit_length() - 1)
            temp ^= b

        g2l = {g: i for i, g in enumerate(global_positions)}
        local_constraints = []
        for gmask, rem in component_constraints:
            t = gmask & component_mask
            lmask = 0
            while t:
                b = t & -t
                gi = b.bit_length() - 1
                lmask |= 1 << g2l[gi]
                t ^= b
            local_constraints.append((lmask, rem))

        k = len(global_positions)
        all_local = (1 << k) - 1
        cache = {}

        def choose_var(known_mask, mine_mask):
            # Choose a variable from the tightest active constraint, then the highest-degree one.
            freq = [0] * k
            best_mask = 0
            best_free = 10**9
            best_bias = -1

            for mask, target in local_constraints:
                assigned_mines = (mask & mine_mask).bit_count()
                undec_mask = mask & ~known_mask
                rem = target - assigned_mines
                free = undec_mask.bit_count()
                if free <= 1:
                    continue

                t = undec_mask
                while t:
                    b = t & -t
                    freq[b.bit_length() - 1] += 1
                    t ^= b

                bias = abs(free - 2 * rem)
                if free < best_free or (free == best_free and bias > best_bias):
                    best_free = free
                    best_bias = bias
                    best_mask = undec_mask
                    best_rem = rem

            if not best_mask:
                t = all_local & ~known_mask
                b = t & -t
                return b.bit_length() - 1, False

            best_var = None
            best_score = -1
            t = best_mask
            while t:
                b = t & -t
                v = b.bit_length() - 1
                if freq[v] > best_score:
                    best_score = freq[v]
                    best_var = v
                t ^= b

            prefer_mine = (2 * best_rem > best_free)
            return best_var, prefer_mine

        def dfs(known_mask, mine_mask):
            key = (known_mask, mine_mask)
            if key in cache:
                return cache[key]

            state = propagate(local_constraints, known_mask, mine_mask)
            if state is None:
                cache[key] = None
                return None

            known_mask, mine_mask = state
            key2 = (known_mask, mine_mask)
            if key2 in cache:
                return cache[key2]

            if known_mask == all_local:
                cache[key2] = mine_mask
                return mine_mask

            # If some vars became unconstrained, they may safely default to non-mine.
            reduced = get_reduced_constraints(local_constraints, known_mask, mine_mask)
            if reduced is None:
                cache[key2] = None
                return None
            constrained_mask = 0
            for mask, _ in reduced:
                constrained_mask |= mask
            dangling = (all_local & ~known_mask) & ~constrained_mask
            if dangling:
                known_mask |= dangling
                key3 = (known_mask, mine_mask)
                if key3 in cache:
                    return cache[key3]
                if known_mask == all_local:
                    cache[key3] = mine_mask
                    return mine_mask

            var, prefer_mine = choose_var(known_mask, mine_mask)
            bit = 1 << var
            order = (1, 0) if prefer_mine else (0, 1)

            for val in order:
                res = dfs(known_mask | bit, mine_mask | (bit if val else 0))
                if res is not None:
                    cache[key2] = res
                    return res

            cache[key2] = None
            return None

        local_solution = dfs(0, 0)
        if local_solution is None:
            return None

        global_mines = 0
        for li, gi in enumerate(global_positions):
            if (local_solution >> li) & 1:
                global_mines |= 1 << gi
        return global_mines

    # Global deterministic phase.
    state = propagate(constraints, 0, 0)
    if state is None:
        return "No Solution"
    known_mask, mine_mask = state

    reduced = get_reduced_constraints(constraints, known_mask, mine_mask)
    if reduced is None:
        return "No Solution"

    total_mines = mine_mask

    # Independent components can be solved separately.
    if reduced:
        for comp in build_components(reduced):
            comp_constraints = [(mask, rem) for mask, rem in reduced if mask & comp]
            comp_solution = solve_component(comp, comp_constraints)
            if comp_solution is None:
                return "No Solution"
            total_mines |= comp_solution

    # Build answer grid: 'F' for mines, None otherwise.
    answer = [[None for _ in range(cols)] for _ in range(rows)]
    for cell, idx in var_index.items():
        if (total_mines >> idx) & 1:
            r, c = cell
            answer[r][c] = 'F'

    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

