from functools import lru_cache


def solve(observation):
    data = observation.get("data")
    if not data or not isinstance(data, list) or not all(isinstance(row, list) for row in data):
        return "No Solution"

    n = len(data)
    if any(len(row) != n for row in data):
        return "No Solution"

    region_values = sorted({v for row in data for v in row})
    region_index = {v: i for i, v in enumerate(region_values)}
    regions = [[region_index[v] for v in row] for row in data]
    rcount = len(region_values)

    # A valid 2-star NxN Star Battle must have exactly N regions.
    if rcount != n:
        return "No Solution"

    # Generate all legal 2-star row patterns.
    patterns = []
    pattern_cols = []
    for c1 in range(n):
        for c2 in range(c1 + 2, n):  # same-row stars cannot touch horizontally
            mask = (1 << c1) | (1 << c2)
            patterns.append(mask)
            pattern_cols.append((c1, c2))

    m = len(patterns)
    all_patterns_mask = (1 << m) - 1

    # Compatibility between adjacent rows: no vertical or diagonal touching.
    compat = [0] * m
    for i, a in enumerate(patterns):
        attack = a | ((a << 1) & ((1 << n) - 1)) | (a >> 1)
        cm = 0
        for j, b in enumerate(patterns):
            if (attack & b) == 0:
                cm |= 1 << j
        compat[i] = cm

    # Column usage masks over the pattern index space.
    col_use = [0] * n
    for p_idx, (c1, c2) in enumerate(pattern_cols):
        col_use[c1] |= 1 << p_idx
        col_use[c2] |= 1 << p_idx

    # Region contribution per row/pattern, plus masks for 0/1/2 contributions.
    row_region_counts = [[[0] * rcount for _ in range(m)] for _ in range(n)]
    row_region_masks = [[[0, 0, 0] for _ in range(rcount)] for _ in range(n)]
    for r in range(n):
        for p_idx, (c1, c2) in enumerate(pattern_cols):
            cnts = [0] * rcount
            cnts[regions[r][c1]] += 1
            cnts[regions[r][c2]] += 1
            row_region_counts[r][p_idx] = cnts
        for k in range(rcount):
            mask0 = mask1 = mask2 = 0
            for p_idx in range(m):
                q = row_region_counts[r][p_idx][k]
                if q == 0:
                    mask0 |= 1 << p_idx
                elif q == 1:
                    mask1 |= 1 << p_idx
                else:
                    mask2 |= 1 << p_idx
            row_region_masks[r][k][0] = mask0
            row_region_masks[r][k][1] = mask1
            row_region_masks[r][k][2] = mask2

    # Useful iteration helpers.
    def iter_bits(bitset):
        while bitset:
            b = bitset & -bitset
            yield b.bit_length() - 1
            bitset ^= b

    def support_union(domain_mask):
        u = 0
        for p in iter_bits(domain_mask):
            u |= compat[p]
        return u

    def contrib_region(row, p_idx, region_id):
        return row_region_counts[row][p_idx][region_id]

    # Human-like propagation:
    # - neighbor row compatibility (local no-touch reasoning)
    # - exact quota pruning on columns
    # - exact quota pruning on regions
    def propagate(domains):
        domains = list(domains)

        while True:
            changed = False

            # 1) Arc consistency on adjacent rows.
            for r in range(n - 1):
                dr = domains[r]
                dn = domains[r + 1]
                allow_r = support_union(dn)
                new_dr = dr & allow_r
                if new_dr == 0:
                    return None
                if new_dr != dr:
                    domains[r] = new_dr
                    dr = new_dr
                    changed = True

                allow_n = support_union(dr)
                new_dn = dn & allow_n
                if new_dn == 0:
                    return None
                if new_dn != dn:
                    domains[r + 1] = new_dn
                    changed = True

            # 2) Exact-2 in every column.
            for c in range(n):
                use = col_use[c]
                not_use = all_patterns_mask ^ use

                row_min = [0] * n
                row_max = [0] * n
                total_min = 0
                total_max = 0

                for r in range(n):
                    d = domains[r]
                    mx = 1 if (d & use) else 0
                    mn = 1 if (d & not_use) == 0 else 0
                    row_min[r] = mn
                    row_max[r] = mx
                    total_min += mn
                    total_max += mx

                if total_min > 2 or total_max < 2:
                    return None

                for r in range(n):
                    d = domains[r]
                    other_min = total_min - row_min[r]
                    other_max = total_max - row_max[r]
                    new_d = 0

                    for p_idx in iter_bits(d):
                        q = 1 if (patterns[p_idx] >> c) & 1 else 0
                        if other_min + q <= 2 <= other_max + q:
                            new_d |= 1 << p_idx

                    if new_d == 0:
                        return None
                    if new_d != d:
                        domains[r] = new_d
                        changed = True

            # 3) Exact-2 in every region.
            for k in range(rcount):
                row_min = [0] * n
                row_max = [0] * n
                total_min = 0
                total_max = 0

                for r in range(n):
                    d = domains[r]
                    masks = row_region_masks[r][k]

                    mn = 0
                    if d & masks[0]:
                        mn = 0
                    elif d & masks[1]:
                        mn = 1
                    else:
                        mn = 2

                    mx = 2
                    if d & masks[2]:
                        mx = 2
                    elif d & masks[1]:
                        mx = 1
                    else:
                        mx = 0

                    row_min[r] = mn
                    row_max[r] = mx
                    total_min += mn
                    total_max += mx

                if total_min > 2 or total_max < 2:
                    return None

                for r in range(n):
                    d = domains[r]
                    other_min = total_min - row_min[r]
                    other_max = total_max - row_max[r]
                    new_d = 0

                    for p_idx in iter_bits(d):
                        q = contrib_region(r, p_idx, k)
                        if other_min + q <= 2 <= other_max + q:
                            new_d |= 1 << p_idx

                    if new_d == 0:
                        return None
                    if new_d != d:
                        domains[r] = new_d
                        changed = True

            if not changed:
                return tuple(domains)

    # Heuristic ordering: fail-first by smallest compatible support footprint.
    def ordered_patterns(domains, r):
        candidates = list(iter_bits(domains[r]))

        def score(p_idx):
            s = 0
            if r > 0:
                s += (domains[r - 1] & compat[p_idx]).bit_count()
            if r + 1 < n:
                s += (domains[r + 1] & compat[p_idx]).bit_count()
            # Prefer patterns using columns/regions that look tighter.
            c1, c2 = pattern_cols[p_idx]
            s += (domains[r] & col_use[c1]).bit_count()
            s += (domains[r] & col_use[c2]).bit_count()
            return s

        candidates.sort(key=score)
        return candidates

    def is_solved(domains):
        return all(d.bit_count() == 1 for d in domains)

    failed = set()

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        if domains in failed:
            return None

        if is_solved(domains):
            return domains

        # Minimum remaining values row choice.
        r = min((i for i in range(n) if domains[i].bit_count() > 1), key=lambda i: domains[i].bit_count())

        for p_idx in ordered_patterns(domains, r):
            new_domains = list(domains)
            new_domains[r] = 1 << p_idx
            result = search(tuple(new_domains))
            if result is not None:
                return result

        failed.add(domains)
        return None

    initial_domains = tuple(all_patterns_mask for _ in range(n))
    solved = search(initial_domains)
    if solved is None:
        return "No Solution"

    # Build answer grid.
    answer = [[None for _ in range(n)] for _ in range(n)]
    col_counts = [0] * n
    region_counts = [0] * rcount
    star_cells = []

    for r in range(n):
        p_idx = next(iter_bits(solved[r]))
        c1, c2 = pattern_cols[p_idx]
        answer[r][c1] = 'S'
        answer[r][c2] = 'S'
        col_counts[c1] += 1
        col_counts[c2] += 1
        region_counts[regions[r][c1]] += 1
        region_counts[regions[r][c2]] += 1
        star_cells.append((r, c1))
        star_cells.append((r, c2))

    # Final verification.
    if any(v != 2 for v in col_counts):
        return "No Solution"
    if any(v != 2 for v in region_counts):
        return "No Solution"

    star_set = set(star_cells)
    for r, c in star_cells:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n and (rr, cc) in star_set:
                    return "No Solution"

    return repr(answer)


