from collections import defaultdict

def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return "No Solution"

    rows = len(data)
    cols = len(data[0])
    n = rows * cols

    def idx(r, c):
        return r * cols + c

    def rc(i):
        return divmod(i, cols)

    # Build exact-sum constraints from numbered cells.
    clues = []
    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(rows, r + 2)):
                for cc in range(max(0, c - 1), min(cols, c + 2)):
                    cells.append(idx(rr, cc))
            clues.append((tuple(cells), val))

    # Map each variable to the clues that mention it.
    var_to_clues = [[] for _ in range(n)]
    constrained = set()
    for cid, (cells, target) in enumerate(clues):
        if target < 0 or target > len(cells):
            return "No Solution"
        for v in cells:
            var_to_clues[v].append(cid)
            constrained.add(v)

    # Unconstrained cells can be arbitrarily colored; choose white canonically.
    initial = [-1] * n
    for v in range(n):
        if v not in constrained:
            initial[v] = 0

    def merge_constraint(cons, S, t):
        if t < 0 or t > len(S):
            return False, False
        old = cons.get(S)
        if old is None:
            cons[S] = t
            return True, True
        return (old == t), False

    # Derive additional exact constraints using subset-difference and exact intersection logic.
    def build_exact_constraints(base_items):
        cons = {}
        for S, t in base_items:
            ok, _ = merge_constraint(cons, S, t)
            if not ok:
                return None

        while True:
            items = list(cons.items())
            changed = False

            for i in range(len(items)):
                Si, ti = items[i]
                if ti < 0 or ti > len(Si):
                    return None

                for j in range(i + 1, len(items)):
                    Sj, tj = items[j]
                    if tj < 0 or tj > len(Sj):
                        return None

                    if Si == Sj:
                        if ti != tj:
                            return None
                        continue

                    # Human-like "subtract the smaller clue from the larger one".
                    if Si.issubset(Sj):
                        D = frozenset(Sj - Si)
                        td = tj - ti
                        ok, added = merge_constraint(cons, D, td)
                        if not ok:
                            return None
                        changed |= added
                    elif Sj.issubset(Si):
                        D = frozenset(Si - Sj)
                        td = ti - tj
                        ok, added = merge_constraint(cons, D, td)
                        if not ok:
                            return None
                        changed |= added

                    # If overlap count is forced exactly, split both constraints.
                    I = Si & Sj
                    if I and I != Si and I != Sj:
                        oa = len(Si) - len(I)
                        ob = len(Sj) - len(I)
                        low_i = max(0, ti - oa, tj - ob)
                        high_i = min(len(I), ti, tj)
                        if low_i > high_i:
                            return None
                        if low_i == high_i:
                            k = low_i
                            for Sx, tx in (
                                (frozenset(I), k),
                                (frozenset(Si - I), ti - k),
                                (frozenset(Sj - I), tj - k),
                            ):
                                ok, added = merge_constraint(cons, Sx, tx)
                                if not ok:
                                    return None
                                changed |= added

            if not changed:
                return cons

    def propagate(vals):
        # vals: -1 undecided, 0 white, 1 black
        def assign(v, color):
            cur = vals[v]
            if cur == color:
                return True, False
            if cur != -1 and cur != color:
                return False, False
            vals[v] = color
            return True, True

        while True:
            any_change = False
            residuals = []

            # Basic clue bounds and forced fill/clear.
            for cells, target in clues:
                black = 0
                undec = []
                for v in cells:
                    cur = vals[v]
                    if cur == 1:
                        black += 1
                    elif cur == -1:
                        undec.append(v)

                rem = target - black
                if rem < 0 or rem > len(undec):
                    return None

                if rem == 0:
                    for v in undec:
                        ok, ch = assign(v, 0)
                        if not ok:
                            return None
                        any_change |= ch
                elif rem == len(undec):
                    for v in undec:
                        ok, ch = assign(v, 1)
                        if not ok:
                            return None
                        any_change |= ch

                if undec:
                    residuals.append((frozenset(undec), rem))
                elif rem != 0:
                    return None

            if any_change:
                continue

            cons = build_exact_constraints(residuals)
            if cons is None:
                return None

            # Apply exact residual constraints that force all-or-nothing.
            for S, t in cons.items():
                if t == 0:
                    for v in S:
                        ok, ch = assign(v, 0)
                        if not ok:
                            return None
                        any_change |= ch
                elif t == len(S):
                    for v in S:
                        ok, ch = assign(v, 1)
                        if not ok:
                            return None
                        any_change |= ch

            if any_change:
                continue

            # Overlap bounds can force parts of regions even when not fully exact.
            items = list(cons.items())
            for i in range(len(items)):
                Si, ti = items[i]
                for j in range(i + 1, len(items)):
                    Sj, tj = items[j]
                    I = Si & Sj
                    if not I:
                        continue

                    OA = Si - I
                    OB = Sj - I

                    low_i = max(0, ti - len(OA), tj - len(OB))
                    high_i = min(len(I), ti, tj)
                    if low_i > high_i:
                        return None

                    if high_i == 0:
                        for v in I:
                            ok, ch = assign(v, 0)
                            if not ok:
                                return None
                            any_change |= ch
                    elif low_i == len(I):
                        for v in I:
                            ok, ch = assign(v, 1)
                            if not ok:
                                return None
                            any_change |= ch

                    low_oa = ti - high_i
                    high_oa = ti - low_i
                    if high_oa == 0:
                        for v in OA:
                            ok, ch = assign(v, 0)
                            if not ok:
                                return None
                            any_change |= ch
                    elif low_oa == len(OA):
                        for v in OA:
                            ok, ch = assign(v, 1)
                            if not ok:
                                return None
                            any_change |= ch

                    low_ob = tj - high_i
                    high_ob = tj - low_i
                    if high_ob == 0:
                        for v in OB:
                            ok, ch = assign(v, 0)
                            if not ok:
                                return None
                            any_change |= ch
                    elif low_ob == len(OB):
                        for v in OB:
                            ok, ch = assign(v, 1)
                            if not ok:
                                return None
                            any_change |= ch

            if not any_change:
                return vals

    def choose_var(vals):
        best_v = None
        best_score = None

        for v in range(n):
            if vals[v] != -1:
                continue

            degree = len(var_to_clues[v])
            if degree == 0:
                # Should already be fixed white, but keep safe.
                return v, (0, 1)

            pressure = 0
            total_u = 0
            bias_num = 0
            bias_den = 0

            for cid in var_to_clues[v]:
                cells, target = clues[cid]
                black = 0
                undec = 0
                for x in cells:
                    cur = vals[x]
                    if cur == 1:
                        black += 1
                    elif cur == -1:
                        undec += 1
                rem = target - black
                total_u += undec
                if undec > 0:
                    bias_num += rem
                    bias_den += undec
                    if rem in (0, undec, 1, undec - 1):
                        pressure += 2
                    pressure += max(rem, undec - rem)

            score = (degree, pressure, -total_u)
            if best_score is None or score > best_score:
                best_score = score
                p_black = (bias_num / bias_den) if bias_den else 0.5
                order = (1, 0) if p_black >= 0.5 else (0, 1)
                best_v = (v, order)

        return best_v

    fail_cache = set()

    def dfs(vals):
        vals = propagate(vals[:])
        if vals is None:
            return None

        key = tuple(vals)
        if key in fail_cache:
            return None

        undecided_exists = False
        for v in range(n):
            if vals[v] == -1:
                undecided_exists = True
                break

        if not undecided_exists:
            return vals

        pick = choose_var(vals)
        if pick is None:
            return vals
        v, order = pick

        for color in order:
            nxt = vals[:]
            nxt[v] = color
            res = dfs(nxt)
            if res is not None:
                return res

        fail_cache.add(key)
        return None

    solution = dfs(initial)
    if solution is None:
        return "No Solution"

    # Final verification.
    for cells, target in clues:
        s = sum(solution[v] == 1 for v in cells)
        if s != target:
            return "No Solution"

    out = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('B' if solution[idx(r, c)] == 1 else None)
        out.append(row)
    return repr(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[-1, None, -1, None, None, None, 1], [None, None, 2, None, None, None, None], [None, None, None, None, None, 1, 1], [None, None, None, 1, None, None, None], [1, -1, None, None, None, None, None], [None, None, None, None, -1, None, None], [0, None, None, None, 1, None, -1]]}

from itertools import combinations
from math import comb


def _bit_iter(mask):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length() - 1
        mask ^= lsb


class AkariSolver:
    def __init__(self, observation):
        self.data = observation["data"]
        self.n = len(self.data)

        self.white_cells = []
        self.white_index = {}
        self.black = set()
        self.clue_cells = {}

        for r in range(self.n):
            for c in range(self.n):
                v = self.data[r][c]
                if v is None:
                    idx = len(self.white_cells)
                    self.white_cells.append((r, c))
                    self.white_index[(r, c)] = idx
                else:
                    self.black.add((r, c))
                    if v != -1:
                        self.clue_cells[(r, c)] = v

        self.w = len(self.white_cells)
        self.all_mask = (1 << self.w) - 1

        self.hseg_of = [-1] * self.w
        self.vseg_of = [-1] * self.w
        self.h_segments = []
        self.v_segments = []

        self._build_segments()
        self.segments = self.h_segments + self.v_segments

        self.cover_masks = [0] * self.w
        for i in range(self.w):
            self.cover_masks[i] = self.h_segments[self.hseg_of[i]] | self.v_segments[self.vseg_of[i]]

        self.conflict_masks = [self.cover_masks[i] & ~(1 << i) for i in range(self.w)]

        self.clues = []
        self.var_to_clues = [[] for _ in range(self.w)]
        self._build_clues()

        # Static branching score: cover breadth + clue involvement.
        self.scores = [self.cover_masks[i].bit_count() + 3 * len(self.var_to_clues[i]) for i in range(self.w)]

        self.failed = set()

    def _build_segments(self):
        # Horizontal segments
        for r in range(self.n):
            c = 0
            while c < self.n:
                if self.data[r][c] is not None:
                    c += 1
                    continue
                mask = 0
                start = c
                while c < self.n and self.data[r][c] is None:
                    idx = self.white_index[(r, c)]
                    mask |= 1 << idx
                    c += 1
                seg_id = len(self.h_segments)
                self.h_segments.append(mask)
                for cc in range(start, c):
                    idx = self.white_index[(r, cc)]
                    self.hseg_of[idx] = seg_id

        # Vertical segments
        for c in range(self.n):
            r = 0
            while r < self.n:
                if self.data[r][c] is not None:
                    r += 1
                    continue
                mask = 0
                start = r
                while r < self.n and self.data[r][c] is None:
                    idx = self.white_index[(r, c)]
                    mask |= 1 << idx
                    r += 1
                seg_id = len(self.v_segments)
                self.v_segments.append(mask)
                for rr in range(start, r):
                    idx = self.white_index[(rr, c)]
                    self.vseg_of[idx] = seg_id

    def _build_clues(self):
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for (r, c), k in self.clue_cells.items():
            adj_mask = 0
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if (nr, nc) in self.white_index:
                    idx = self.white_index[(nr, nc)]
                    adj_mask |= 1 << idx

            clue_id = len(self.clues)
            self.clues.append((adj_mask, k))
            for i in _bit_iter(adj_mask):
                self.var_to_clues[i].append(clue_id)

    def propagate(self, bulb_mask, empty_mask):
        while True:
            if bulb_mask & empty_mask:
                return None

            unknown = self.all_mask & ~(bulb_mask | empty_mask)
            new_bulbs = 0
            new_empty = 0

            # Numbered black cell deductions.
            for adj_mask, k in self.clues:
                b = (bulb_mask & adj_mask).bit_count()
                u_mask = unknown & adj_mask
                u = u_mask.bit_count()

                if b > k or b + u < k:
                    return None

                if u_mask:
                    if b == k:
                        new_empty |= u_mask
                    elif b + u == k:
                        new_bulbs |= u_mask

            # Bulb visibility deductions: one bulb per segment.
            for seg_mask in self.segments:
                b = (bulb_mask & seg_mask).bit_count()
                if b > 1:
                    return None
                if b == 1:
                    new_empty |= unknown & seg_mask

            # Illumination deductions: every white cell needs at least one source.
            for cov_mask in self.cover_masks:
                if bulb_mask & cov_mask:
                    continue
                u_mask = unknown & cov_mask
                if not u_mask:
                    return None
                if u_mask & (u_mask - 1) == 0:
                    new_bulbs |= u_mask

            # Remove already-fixed cells from the new assignments.
            new_bulbs &= unknown
            new_empty &= unknown

            if (new_bulbs & new_empty) or (new_bulbs & empty_mask) or (new_empty & bulb_mask):
                return None

            if not new_bulbs and not new_empty:
                return bulb_mask, empty_mask

            bulb_mask |= new_bulbs
            empty_mask |= new_empty

    def is_solved(self, bulb_mask):
        for cov_mask in self.cover_masks:
            if not (bulb_mask & cov_mask):
                return False
        for adj_mask, k in self.clues:
            if (bulb_mask & adj_mask).bit_count() != k:
                return False
        return True

    def choose_branch(self, bulb_mask, empty_mask):
        unknown = self.all_mask & ~(bulb_mask | empty_mask)

        # Prefer branching on a still-undecided clue.
        best = None
        best_cost = None

        for adj_mask, k in self.clues:
            b = (bulb_mask & adj_mask).bit_count()
            u_mask = unknown & adj_mask
            u = u_mask.bit_count()
            rem = k - b

            if rem < 0 or rem > u:
                return ("contradiction", None)

            if 0 < rem < u:
                cost = comb(u, rem)
                if best is None or cost < best_cost:
                    best = (u_mask, rem)
                    best_cost = cost
                    if cost == 2:
                        break

        if best is not None:
            u_mask, rem = best
            cells = list(_bit_iter(u_mask))
            cells.sort(key=lambda i: self.scores[i], reverse=True)

            branches = []
            for subset in combinations(cells, rem):
                bulb_add = 0
                ok = True
                for i in subset:
                    if bulb_mask & self.conflict_masks[i]:
                        ok = False
                        break
                    bulb_add |= 1 << i
                if not ok:
                    continue
                # Pairwise conflict check inside subset.
                temp = bulb_add
                while temp:
                    lsb = temp & -temp
                    i = lsb.bit_length() - 1
                    temp ^= lsb
                    if temp & self.conflict_masks[i]:
                        ok = False
                        break
                if not ok:
                    continue

                empty_add = u_mask & ~bulb_add
                score = sum(self.scores[i] for i in subset)
                branches.append((score, bulb_add, empty_add))

            branches.sort(reverse=True)
            return ("clue", [(b, e) for _, b, e in branches])

        # Otherwise branch on an unlit white cell with the fewest possible lighting positions.
        best_cell = None
        best_cand_mask = 0
        best_count = None

        for i, cov_mask in enumerate(self.cover_masks):
            if bulb_mask & cov_mask:
                continue
            cand_mask = unknown & cov_mask
            cnt = cand_mask.bit_count()
            if cnt == 0:
                return ("contradiction", None)
            if best_cell is None or cnt < best_count:
                best_cell = i
                best_cand_mask = cand_mask
                best_count = cnt
                if cnt == 1:
                    break

        if best_cell is not None:
            cells = list(_bit_iter(best_cand_mask))
            cells.sort(key=lambda i: self.scores[i], reverse=True)

            # Sequential OR branching:
            # first true candidate in the ordered list becomes the bulb.
            branches = []
            prefix_empty = 0
            for i in cells:
                branches.append((1 << i, prefix_empty))
                prefix_empty |= 1 << i
            return ("cover", branches)

        return ("done", None)

    def search(self, bulb_mask=0, empty_mask=0):
        state = self.propagate(bulb_mask, empty_mask)
        if state is None:
            return None

        bulb_mask, empty_mask = state
        key = (bulb_mask, empty_mask)
        if key in self.failed:
            return None

        if self.is_solved(bulb_mask):
            return bulb_mask

        mode, branches = self.choose_branch(bulb_mask, empty_mask)
        if mode == "contradiction":
            self.failed.add(key)
            return None
        if mode == "done":
            if self.is_solved(bulb_mask):
                return bulb_mask
            self.failed.add(key)
            return None

        for add_bulb, add_empty in branches:
            res = self.search(bulb_mask | add_bulb, empty_mask | add_empty)
            if res is not None:
                return res

        self.failed.add(key)
        return None

    def solve_grid(self):
        bulb_mask = self.search()
        if bulb_mask is None:
            return None

        grid = [[None for _ in range(self.n)] for _ in range(self.n)]
        for i, (r, c) in enumerate(self.white_cells):
            if (bulb_mask >> i) & 1:
                grid[r][c] = "B"
        return grid


def solve(observation):
    solver = AkariSolver(observation)
    grid = solver.solve_grid()
    if grid is None:
        return "No Solution"
    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [2, 0, 4, 0, 0, 2], 'D': [0, 4, 3, 0, 1, 0], 'L': [0, 0, 4, 0, 2, 3], 'R': [3, 4, 0, 3, 0, 0]}

from itertools import permutations
import sys

sys.setrecursionlimit(10000)


def solve(observation):
    U = [0 if x in (None, "", ".") else int(x) for x in observation["U"]]
    D = [0 if x in (None, "", ".") else int(x) for x in observation["D"]]
    L = [0 if x in (None, "", ".") else int(x) for x in observation["L"]]
    R = [0 if x in (None, "", ".") else int(x) for x in observation["R"]]

    n = len(U)
    if not (len(D) == len(L) == len(R) == n):
        return "No Solution"

    values = tuple(range(1, n + 1))
    full_set = set(values)

    def visible_count(seq):
        seen = 0
        tallest = 0
        for x in seq:
            if x > tallest:
                tallest = x
                seen += 1
        return seen

    # Precompute all legal line permutations and their clue signatures.
    perms = list(permutations(values))
    perm_bits = [tuple(1 << (v - 1) for v in p) for p in perms]
    left_vis = [visible_count(p) for p in perms]
    right_vis = [visible_count(p[::-1]) for p in perms]

    clue_cache = {}

    def line_candidates(front_clue, back_clue):
        key = (front_clue, back_clue)
        if key not in clue_cache:
            clue_cache[key] = [
                i
                for i in range(len(perms))
                if (front_clue == 0 or left_vis[i] == front_clue)
                and (back_clue == 0 or right_vis[i] == back_clue)
            ]
        return list(clue_cache[key])

    row_cands0 = [line_candidates(L[r], R[r]) for r in range(n)]
    col_cands0 = [line_candidates(U[c], D[c]) for c in range(n)]

    if any(not c for c in row_cands0) or any(not c for c in col_cands0):
        return "No Solution"

    def validate(grid):
        if len(grid) != n or any(len(row) != n for row in grid):
            return False

        for r in range(n):
            row = grid[r]
            if set(row) != full_set:
                return False
            if L[r] and visible_count(row) != L[r]:
                return False
            if R[r] and visible_count(row[::-1]) != R[r]:
                return False

        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != full_set:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(col[::-1]) != D[c]:
                return False

        return True

    def propagate(row_cands, col_cands):
        # Human-like loop:
        # 1) restrict each row/column by its clue-compatible permutations
        # 2) intersect row possibilities with column possibilities cell-by-cell
        # 3) apply hidden singles in rows/columns
        while True:
            changed = False

            row_masks = [[0] * n for _ in range(n)]
            for r in range(n):
                cands = row_cands[r]
                if not cands:
                    return None
                masks = [0] * n
                for idx in cands:
                    bits = perm_bits[idx]
                    for c in range(n):
                        masks[c] |= bits[c]
                row_masks[r] = masks

            col_masks = [[0] * n for _ in range(n)]
            for c in range(n):
                cands = col_cands[c]
                if not cands:
                    return None
                masks = [0] * n
                for idx in cands:
                    bits = perm_bits[idx]
                    for r in range(n):
                        masks[r] |= bits[r]
                col_masks[c] = masks

            domain = [[0] * n for _ in range(n)]
            for r in range(n):
                for c in range(n):
                    m = row_masks[r][c] & col_masks[c][r]
                    if m == 0:
                        return None
                    domain[r][c] = m

            # Filter row candidates against current cell domains.
            for r in range(n):
                old = row_cands[r]
                new = []
                for idx in old:
                    bits = perm_bits[idx]
                    ok = True
                    for c in range(n):
                        if not (bits[c] & domain[r][c]):
                            ok = False
                            break
                    if ok:
                        new.append(idx)
                if not new:
                    return None
                if len(new) != len(old):
                    row_cands[r] = new
                    changed = True

            # Filter column candidates against current cell domains.
            for c in range(n):
                old = col_cands[c]
                new = []
                for idx in old:
                    bits = perm_bits[idx]
                    ok = True
                    for r in range(n):
                        if not (bits[r] & domain[r][c]):
                            ok = False
                            break
                    if ok:
                        new.append(idx)
                if not new:
                    return None
                if len(new) != len(old):
                    col_cands[c] = new
                    changed = True

            # Hidden singles in each row: a value can go in only one column.
            for r in range(n):
                for v in range(1, n + 1):
                    bit = 1 << (v - 1)
                    positions = [c for c in range(n) if domain[r][c] & bit]
                    if not positions:
                        return None
                    if len(positions) == 1:
                        c = positions[0]
                        old = row_cands[r]
                        new = [idx for idx in old if perm_bits[idx][c] == bit]
                        if not new:
                            return None
                        if len(new) != len(old):
                            row_cands[r] = new
                            changed = True

            # Hidden singles in each column: a value can go in only one row.
            for c in range(n):
                for v in range(1, n + 1):
                    bit = 1 << (v - 1)
                    positions = [r for r in range(n) if domain[r][c] & bit]
                    if not positions:
                        return None
                    if len(positions) == 1:
                        r = positions[0]
                        old = col_cands[c]
                        new = [idx for idx in old if perm_bits[idx][r] == bit]
                        if not new:
                            return None
                        if len(new) != len(old):
                            col_cands[c] = new
                            changed = True

            if not changed:
                return row_cands, col_cands

    def build_grid_from_rows(row_cands):
        return [list(perms[cands[0]]) for cands in row_cands]

    def build_grid_from_cols(col_cands):
        return [[perms[col_cands[c][0]][r] for c in range(n)] for r in range(n)]

    def dfs(row_cands, col_cands):
        state = propagate(row_cands, col_cands)
        if state is None:
            return None
        row_cands, col_cands = state

        rows_single = all(len(c) == 1 for c in row_cands)
        cols_single = all(len(c) == 1 for c in col_cands)

        if rows_single:
            grid = build_grid_from_rows(row_cands)
            if validate(grid):
                return grid

        if cols_single:
            grid = build_grid_from_cols(col_cands)
            if validate(grid):
                return grid

        # Branch on the most constrained unresolved line.
        best_is_row = True
        best_idx = -1
        best_len = 10**9

        for r in range(n):
            m = len(row_cands[r])
            if 1 < m < best_len:
                best_len = m
                best_idx = r
                best_is_row = True

        for c in range(n):
            m = len(col_cands[c])
            if 1 < m < best_len:
                best_len = m
                best_idx = c
                best_is_row = False

        if best_idx == -1:
            return None

        if best_is_row:
            options = row_cands[best_idx]
            for cand in options:
                new_rows = [lst[:] for lst in row_cands]
                new_cols = [lst[:] for lst in col_cands]
                new_rows[best_idx] = [cand]
                result = dfs(new_rows, new_cols)
                if result is not None:
                    return result
        else:
            options = col_cands[best_idx]
            for cand in options:
                new_rows = [lst[:] for lst in row_cands]
                new_cols = [lst[:] for lst in col_cands]
                new_cols[best_idx] = [cand]
                result = dfs(new_rows, new_cols)
                if result is not None:
                    return result

        return None

    solution = dfs([c[:] for c in row_cands0], [c[:] for c in col_cands0])
    return str(solution) if solution is not None else "No Solution"


