from collections import deque
import sys

sys.setrecursionlimit(10000)


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n

    U = -1
    B = 0
    W = 1

    enc = {None: U, "B": B, "W": W}
    dec = {B: "B", W: "W"}

    grid0 = [enc[data[r][c]] for r in range(n) for c in range(n)]

    neighbors = [[] for _ in range(m)]
    for r in range(n):
        for c in range(n):
            i = r * n + c
            if r > 0:
                neighbors[i].append((r - 1) * n + c)
            if r + 1 < n:
                neighbors[i].append((r + 1) * n + c)
            if c > 0:
                neighbors[i].append(r * n + (c - 1))
            if c + 1 < n:
                neighbors[i].append(r * n + (c + 1))

    blocks = []
    cell_blocks = [[] for _ in range(m)]
    for r in range(n - 1):
        for c in range(n - 1):
            blk = (r * n + c, r * n + c + 1, (r + 1) * n + c, (r + 1) * n + c + 1)
            bi = len(blocks)
            blocks.append(blk)
            for x in blk:
                cell_blocks[x].append(bi)

    def avail_component(grid, color, start, banned=-1):
        opp = 1 - color
        seen = [False] * m
        if start == banned or grid[start] == opp:
            return seen
        stack = [start]
        seen[start] = True
        while stack:
            v = stack.pop()
            for nb in neighbors[v]:
                if nb != banned and not seen[nb] and grid[nb] != opp:
                    seen[nb] = True
                    stack.append(nb)
        return seen

    def monochrome_2x2_exists(grid):
        for a, b, c, d in blocks:
            va = grid[a]
            if va != U and va == grid[b] == grid[c] == grid[d]:
                return True
        return False

    def is_consistent(grid):
        if monochrome_2x2_exists(grid):
            return False
        for color in (B, W):
            req = [i for i, v in enumerate(grid) if v == color]
            if req:
                seen = avail_component(grid, color, req[0])
                for i in req[1:]:
                    if not seen[i]:
                        return False
        return True

    def quick_feasible(grid, idx, val):
        cur = grid[idx]
        if cur != U:
            return cur == val
        grid[idx] = val
        ok = is_consistent(grid)
        grid[idx] = U
        return ok

    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # Rule 1: 2x2 completion / contradiction.
            for a, b, c, d in blocks:
                vals = [grid[a], grid[b], grid[c], grid[d]]
                ua = vals.count(U)
                if ua == 0:
                    if vals[0] == vals[1] == vals[2] == vals[3]:
                        return None
                    continue
                if vals.count(B) == 3 and ua == 1:
                    pos = (a, b, c, d)[vals.index(U)]
                    if grid[pos] == U:
                        grid[pos] = W
                        changed = True
                    elif grid[pos] != W:
                        return None
                if vals.count(W) == 3 and ua == 1:
                    pos = (a, b, c, d)[vals.index(U)]
                    if grid[pos] == U:
                        grid[pos] = B
                        changed = True
                    elif grid[pos] != B:
                        return None

            # Rule 2: each color's existing cells must stay in one available component.
            for color in (B, W):
                req = [i for i, v in enumerate(grid) if v == color]
                if not req:
                    continue

                seen = avail_component(grid, color, req[0])
                for i in req[1:]:
                    if not seen[i]:
                        return None

                # Any unknown outside that component can never join this color.
                opp = 1 - color
                for i, v in enumerate(grid):
                    if v == U and not seen[i]:
                        grid[i] = opp
                        changed = True

                # Any unknown whose removal disconnects the color terminals is forced.
                if len(req) >= 2:
                    for i, v in enumerate(grid):
                        if v == U and seen[i]:
                            seen2 = avail_component(grid, color, req[0], banned=i)
                            forced = False
                            for r in req[1:]:
                                if not seen2[r]:
                                    forced = True
                                    break
                            if forced:
                                grid[i] = color
                                changed = True

            # Rule 3: contradiction-based singles.
            for i, v in enumerate(grid):
                if v != U:
                    continue
                can_b = quick_feasible(grid, i, B)
                can_w = quick_feasible(grid, i, W)
                if not can_b and not can_w:
                    return None
                if can_b and not can_w:
                    grid[i] = B
                    changed = True
                elif can_w and not can_b:
                    grid[i] = W
                    changed = True

            if not is_consistent(grid):
                return None

        return grid

    def final_check(grid):
        if U in grid:
            return False
        if B not in grid or W not in grid:
            return False
        if monochrome_2x2_exists(grid):
            return False
        for color in (B, W):
            req = [i for i, v in enumerate(grid) if v == color]
            seen = avail_component(grid, color, req[0])
            for i in req:
                if not seen[i]:
                    return False
        return True

    def cell_pressure(grid, idx):
        score = 0
        score += sum(1 for nb in neighbors[idx] if grid[nb] != U) * 3
        for bi in cell_blocks[idx]:
            score += sum(1 for j in blocks[bi] if grid[j] != U)
        return score

    def choose_branch(grid):
        best_idx = None
        best_opts = None
        best_key = None

        for i, v in enumerate(grid):
            if v != U:
                continue
            opts = []
            if quick_feasible(grid, i, B):
                opts.append(B)
            if quick_feasible(grid, i, W):
                opts.append(W)

            if not opts:
                return i, []

            key = (len(opts), -cell_pressure(grid, i))
            if best_key is None or key < best_key:
                best_key = key
                best_idx = i
                best_opts = opts
                if len(opts) == 1:
                    break

        ranked = []
        for val in best_opts:
            g2 = grid.copy()
            g2[best_idx] = val
            g2 = propagate(g2)
            if g2 is not None:
                ranked.append((g2.count(U), -cell_pressure(g2, best_idx), val))
        ranked.sort()
        return best_idx, [val for _, __, val in ranked]

    failed = set()

    def dfs(grid):
        grid = propagate(grid.copy())
        if grid is None:
            return None

        key = tuple(grid)
        if key in failed:
            return None

        if U not in grid:
            if final_check(grid):
                return grid
            failed.add(key)
            return None

        idx, opts = choose_branch(grid)
        if not opts:
            failed.add(key)
            return None

        for val in opts:
            g2 = grid.copy()
            g2[idx] = val
            sol = dfs(g2)
            if sol is not None:
                return sol

        failed.add(key)
        return None

    if not is_consistent(grid0):
        return "No Solution"

    sol = dfs(grid0)
    if sol is None:
        return "No Solution"

    return [[dec[sol[r * n + c]] for c in range(n)] for r in range(n)]


if __name__ == "__main__":
    print(solve(OBSERVATION))

