from collections import defaultdict, deque


def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0
    nvars = rows * cols

    def vid(r, c):
        return r * cols + c

    # Build exact-sum constraints from every numbered clue.
    base_constraints = {}
    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(rows, r + 2)):
                for cc in range(max(0, c - 1), min(cols, c + 2)):
                    cells.append(vid(rr, cc))
            fs = frozenset(cells)
            old = base_constraints.get(fs)
            if old is not None and old != val:
                return "No Solution"
            base_constraints[fs] = val

    # -1 unknown, 0 white, 1 black
    initial_assign = [-1] * nvars

    # Human-style propagation:
    # 1) simplify each clue against current assignments
    # 2) force all-0 / all-1 residuals
    # 3) use subset differences exactly
    # 4) use overlap saturation:
    #    if sum(A)-sum(B) reaches the maximum possible contribution of A\B,
    #    then A\B must be black and B\A must be white (or vice versa)
    def propagate(assign, constraints):
        assign = assign[:]
        constraints = dict(constraints)

        while True:
            changed = False

            # Simplify constraints by removing assigned cells.
            simplified = {}
            for cells, target in constraints.items():
                rem_target = target
                unknown = []
                for v in cells:
                    av = assign[v]
                    if av == 1:
                        rem_target -= 1
                    elif av == -1:
                        unknown.append(v)
                if rem_target < 0 or rem_target > len(unknown):
                    return None
                if not unknown:
                    if rem_target != 0:
                        return None
                    continue
                fs = frozenset(unknown)
                prev = simplified.get(fs)
                if prev is not None and prev != rem_target:
                    return None
                simplified[fs] = rem_target
            constraints = simplified

            # Direct forcing.
            forced = []
            for cells, target in constraints.items():
                k = len(cells)
                if target == 0:
                    for v in cells:
                        forced.append((v, 0))
                elif target == k:
                    for v in cells:
                        forced.append((v, 1))
                elif k == 1:
                    v = next(iter(cells))
                    forced.append((v, target))

            if forced:
                for v, val in forced:
                    cur = assign[v]
                    if cur != -1 and cur != val:
                        return None
                    if cur == -1:
                        assign[v] = val
                        changed = True
                if changed:
                    continue

            # Pairwise deductions.
            items = list(constraints.items())
            items.sort(key=lambda kv: (len(kv[0]), kv[1]))

            derived = {}
            pair_forced = []

            m = len(items)
            for i in range(m):
                A, a = items[i]
                for j in range(i + 1, m):
                    B, b = items[j]

                    # Exact subset difference: if A ⊆ B then sum(B\A)=b-a.
                    if len(A) <= len(B) and A.issubset(B) and A != B:
                        D = B - A
                        d = b - a
                        if d < 0 or d > len(D):
                            return None
                        if D:
                            old = constraints.get(D)
                            if old is not None and old != d:
                                return None
                            old = derived.get(D)
                            if old is not None and old != d:
                                return None
                            if old is None and constraints.get(D) != d:
                                derived[D] = d
                        elif d != 0:
                            return None

                    # Overlap saturation:
                    # a-b = sum(A\B) - sum(B\A), so it must lie in [-|B\A|, |A\B|].
                    X = A - B
                    Y = B - A
                    diff = a - b
                    if diff > len(X) or -diff > len(Y):
                        return None

                    if diff == len(X) and len(X) > 0:
                        for v in X:
                            pair_forced.append((v, 1))
                        for v in Y:
                            pair_forced.append((v, 0))
                    elif -diff == len(Y) and len(Y) > 0:
                        for v in X:
                            pair_forced.append((v, 0))
                        for v in Y:
                            pair_forced.append((v, 1))

            if derived:
                constraints.update(derived)
                changed = True
                continue

            if pair_forced:
                for v, val in pair_forced:
                    cur = assign[v]
                    if cur != -1 and cur != val:
                        return None
                    if cur == -1:
                        assign[v] = val
                        changed = True
                if changed:
                    continue

            if not changed:
                break

        return assign, constraints

    def frontier_vars(constraints, assign):
        counts = defaultdict(int)
        min_size = {}
        bias_num = defaultdict(float)
        bias_den = defaultdict(float)
        for cells, target in constraints.items():
            size = len(cells)
            ratio = target / size
            tight = abs(ratio - 0.5)
            for v in cells:
                if assign[v] != -1:
                    continue
                counts[v] += 1
                if v not in min_size or size < min_size[v]:
                    min_size[v] = size
                bias_num[v] += ratio * (1.0 + tight)
                bias_den[v] += (1.0 + tight)
        vars_list = list(counts)
        vars_list.sort(key=lambda v: (min_size[v], -counts[v], v))
        return vars_list, counts, min_size, bias_num, bias_den

    def choose_var(assign, constraints):
        vars_list, counts, min_size, bias_num, bias_den = frontier_vars(constraints, assign)
        if not vars_list:
            return None
        # Most constrained first: smallest residual clue, then most appearances.
        vars_list.sort(key=lambda v: (min_size[v], -counts[v], v))
        return vars_list[0]

    def value_order(v, assign, constraints):
        # Estimate black likelihood from local residual clue ratios.
        num = 0.0
        den = 0.0
        for cells, target in constraints.items():
            if v in cells:
                size = len(cells)
                ratio = target / size
                weight = 1.0 + abs(ratio - 0.5)
                num += ratio * weight
                den += weight
        p_black = num / den if den else 0.5
        return (1, 0) if p_black >= 0.5 else (0, 1)

    def failed_literal(assign, constraints):
        # Limited contradiction probing, imitating human "try one color and see if it breaks".
        while True:
            vars_list, counts, min_size, _, _ = frontier_vars(constraints, assign)
            if not vars_list:
                return assign, constraints
            # Probe only the most constrained few cells.
            probe = vars_list[: min(10, len(vars_list))]
            progress = False
            for v in probe:
                bad = []
                for val in (0, 1):
                    test_assign = assign[:]
                    if test_assign[v] != -1 and test_assign[v] != val:
                        bad.append(val)
                        continue
                    test_assign[v] = val
                    if propagate(test_assign, constraints) is None:
                        bad.append(val)
                if len(bad) == 2:
                    return None
                if len(bad) == 1:
                    forced_val = 1 - bad[0]
                    cur = assign[v]
                    if cur != -1 and cur != forced_val:
                        return None
                    if cur == -1:
                        assign[v] = forced_val
                        res = propagate(assign, constraints)
                        if res is None:
                            return None
                        assign, constraints = res
                        progress = True
                        break
            if not progress:
                return assign, constraints

    def all_constraints_satisfied(assign, constraints):
        if constraints:
            return False
        return True

    def dfs(assign, constraints):
        res = propagate(assign, constraints)
        if res is None:
            return None
        assign, constraints = res

        res = failed_literal(assign, constraints)
        if res is None:
            return None
        assign, constraints = res

        if all_constraints_satisfied(assign, constraints):
            # Unconstrained leftovers can be white.
            final_assign = [0 if v == -1 else v for v in assign]
            return final_assign

        v = choose_var(assign, constraints)
        if v is None:
            final_assign = [0 if x == -1 else x for x in assign]
            return final_assign

        for val in value_order(v, assign, constraints):
            new_assign = assign[:]
            cur = new_assign[v]
            if cur != -1 and cur != val:
                continue
            new_assign[v] = val
            sol = dfs(new_assign, constraints)
            if sol is not None:
                return sol
        return None

    solution = dfs(initial_assign, base_constraints)
    if solution is None:
        return "No Solution"

    answer = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('B' if solution[vid(r, c)] == 1 else None)
        answer.append(row)
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

