from collections import deque
from functools import lru_cache


def solve(observation):
    data = observation.get("data")
    adjacent = observation.get("adjacent", [])
    if not data or not isinstance(data, list) or any(len(row) != len(data) for row in data):
        return "No Solution"

    N = len(data)
    FULL_MASK = (1 << N) - 1
    ALL_BITS = [1 << i for i in range(N)]

    def iter_bits(mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask -= bit

    def bit_value(bit):
        return bit.bit_length()

    # Consecutive / non-consecutive support masks per single value-bit.
    support_pos = {}
    support_neg = {}
    for i in range(N):
        bit = 1 << i
        v = i + 1
        m = 0
        if v > 1:
            m |= 1 << (v - 2)
        if v < N:
            m |= 1 << v
        support_pos[bit] = m
        support_neg[bit] = FULL_MASK & ~m

    # Build positive adjacency set from midpoint coordinates.
    positive_pairs = set()
    try:
        for coord in adjacent:
            r, c = coord
            r2 = int(round(r * 2))
            c2 = int(round(c * 2))
            if r2 % 2 == 0 and c2 % 2 == 1:
                rr = r2 // 2
                cc = c2 // 2
                if not (0 <= rr < N and 0 <= cc < N - 1):
                    return "No Solution"
                a = rr * N + cc
                b = rr * N + (cc + 1)
            elif r2 % 2 == 1 and c2 % 2 == 0:
                rr = r2 // 2
                cc = c2 // 2
                if not (0 <= rr < N - 1 and 0 <= cc < N):
                    return "No Solution"
                a = rr * N + cc
                b = (rr + 1) * N + cc
            else:
                return "No Solution"
            if a > b:
                a, b = b, a
            positive_pairs.add((a, b))
    except Exception:
        return "No Solution"

    # All orthogonal neighbor pairs; absence of dot means non-consecutive.
    edges = []
    edge_index = {}
    for r in range(N):
        for c in range(N):
            a = r * N + c
            if c + 1 < N:
                b = r * N + (c + 1)
                pair = (a, b) if a < b else (b, a)
                edge_index[pair] = len(edges)
                edges.append((pair[0], pair[1], pair in positive_pairs))
            if r + 1 < N:
                b = (r + 1) * N + c
                pair = (a, b) if a < b else (b, a)
                edge_index[pair] = len(edges)
                edges.append((pair[0], pair[1], pair in positive_pairs))

    # Row and column units.
    units = []
    for r in range(N):
        units.append([r * N + c for c in range(N)])
    for c in range(N):
        units.append([r * N + c for r in range(N)])

    cell_to_units = [[] for _ in range(N * N)]
    for ui, unit in enumerate(units):
        for idx in unit:
            cell_to_units[idx].append(ui)

    cell_edges = [[] for _ in range(N * N)]
    for ei, (a, b, _) in enumerate(edges):
        cell_edges[a].append(ei)
        cell_edges[b].append(ei)

    cell_priority = [0] * (N * N)
    for idx in range(N * N):
        score = 0
        for ei in cell_edges[idx]:
            score += 2 if edges[ei][2] else 1
        cell_priority[idx] = score

    # Initial domains.
    domains = [FULL_MASK] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            idx = r * N + c
            if v is None:
                domains[idx] = FULL_MASK
            else:
                if not isinstance(v, int) or not (1 <= v <= N):
                    return "No Solution"
                domains[idx] = 1 << (v - 1)

    def canonical(masks):
        return tuple(sorted(masks, key=lambda x: (x.bit_count(), x)))

    # Human-like Hall reasoning via exact unit feasibility.
    @lru_cache(maxsize=None)
    def unit_feasible(state):
        if not state:
            return True
        if state[0] == 0:
            return False
        union = 0
        for m in state:
            if m == 0:
                return False
            union |= m
        if union.bit_count() < len(state):
            return False

        m = state[0]
        rest = list(state[1:])
        for bit in iter_bits(m):
            nxt = []
            ok = True
            for x in rest:
                y = x & ~bit
                if y == 0:
                    ok = False
                    break
                nxt.append(y)
            if ok:
                nxt.sort(key=lambda z: (z.bit_count(), z))
                if unit_feasible(tuple(nxt)):
                    return True
        return False

    def revise_edge(cur_domains, ei):
        a, b, is_pos = edges[ei]
        da = cur_domains[a]
        db = cur_domains[b]
        keep_a = 0
        keep_b = 0
        support = support_pos if is_pos else support_neg

        for bit in iter_bits(da):
            if support[bit] & db:
                keep_a |= bit
        if keep_a == 0:
            return None

        for bit in iter_bits(db):
            if support[bit] & da:
                keep_b |= bit
        if keep_b == 0:
            return None

        changed = []
        if keep_a != da:
            cur_domains[a] = keep_a
            changed.append(a)
        if keep_b != db:
            cur_domains[b] = keep_b
            changed.append(b)
        return changed

    def filter_unit(cur_domains, ui):
        unit = units[ui]
        changed = []

        # 1) Direct Latin elimination from fixed values.
        fixed = 0
        for idx in unit:
            m = cur_domains[idx]
            if m == 0:
                return None
            if m.bit_count() == 1:
                if fixed & m:
                    return None
                fixed |= m

        for idx in unit:
            m = cur_domains[idx]
            if m.bit_count() > 1:
                nm = m & ~fixed
                if nm == 0:
                    return None
                if nm != m:
                    cur_domains[idx] = nm
                    changed.append(idx)

        # 2) Hidden singles: each value must appear somewhere in the unit.
        masks = [cur_domains[idx] for idx in unit]
        union = 0
        for m in masks:
            union |= m
        if union != FULL_MASK:
            return None

        for bit in ALL_BITS:
            pos = -1
            count = 0
            for i, m in enumerate(masks):
                if m & bit:
                    pos = i
                    count += 1
                    if count > 1:
                        break
            if count == 0:
                return None
            if count == 1:
                idx = unit[pos]
                if cur_domains[idx] != bit:
                    cur_domains[idx] = bit
                    changed.append(idx)

        # 3) Hall / all-different support pruning.
        masks = [cur_domains[idx] for idx in unit]
        if not unit_feasible(canonical(masks)):
            return None

        for i, idx in enumerate(unit):
            m = cur_domains[idx]
            if m.bit_count() <= 1:
                continue
            nm = 0
            for bit in iter_bits(m):
                trial = list(masks)
                trial[i] = bit
                if unit_feasible(canonical(trial)):
                    nm |= bit
            if nm == 0:
                return None
            if nm != m:
                cur_domains[idx] = nm
                changed.append(idx)

        if changed:
            # Preserve order, remove duplicates.
            seen = set()
            dedup = []
            for idx in changed:
                if idx not in seen:
                    seen.add(idx)
                    dedup.append(idx)
            return dedup
        return []

    def propagate(start_domains):
        cur_domains = start_domains
        total_tasks = len(edges) + len(units)
        q = deque(range(total_tasks))
        in_q = [True] * total_tasks

        def enqueue_cell(idx):
            for ei in cell_edges[idx]:
                if not in_q[ei]:
                    in_q[ei] = True
                    q.append(ei)
            for ui in cell_to_units[idx]:
                tid = len(edges) + ui
                if not in_q[tid]:
                    in_q[tid] = True
                    q.append(tid)

        while q:
            tid = q.popleft()
            in_q[tid] = False
            if tid < len(edges):
                changed = revise_edge(cur_domains, tid)
            else:
                changed = filter_unit(cur_domains, tid - len(edges))

            if changed is None:
                return None

            for idx in changed:
                if cur_domains[idx] == 0:
                    return None
                enqueue_cell(idx)

        return cur_domains

    dead_states = set()

    def choose_cell(cur_domains):
        best_idx = None
        best_key = None
        for idx, m in enumerate(cur_domains):
            bc = m.bit_count()
            if bc <= 1:
                continue
            row_ui, col_ui = cell_to_units[idx]
            scarcity = 0
            for bit in iter_bits(m):
                row_count = sum(1 for j in units[row_ui] if cur_domains[j] & bit)
                col_count = sum(1 for j in units[col_ui] if cur_domains[j] & bit)
                scarcity += row_count + col_count
            key = (bc, scarcity, -cell_priority[idx], idx)
            if best_key is None or key < best_key:
                best_key = key
                best_idx = idx
        return best_idx

    def ordered_values(cur_domains, idx):
        row_ui, col_ui = cell_to_units[idx]
        options = []
        for bit in iter_bits(cur_domains[idx]):
            scarcity = sum(1 for j in units[row_ui] if cur_domains[j] & bit)
            scarcity += sum(1 for j in units[col_ui] if cur_domains[j] & bit)
            support_score = 0
            for ei in cell_edges[idx]:
                a, b, is_pos = edges[ei]
                other = b if a == idx else a
                sup = support_pos[bit] if is_pos else support_neg[bit]
                support_score += (sup & cur_domains[other]).bit_count()
            options.append((scarcity, -support_score, bit_value(bit), bit))
        options.sort()
        return [bit for _, _, _, bit in options]

    def search(cur_domains):
        cur_domains = propagate(cur_domains)
        if cur_domains is None:
            return None

        key = tuple(cur_domains)
        if key in dead_states:
            return None

        if all(m.bit_count() == 1 for m in cur_domains):
            return cur_domains

        idx = choose_cell(cur_domains)
        if idx is None:
            return cur_domains

        for bit in ordered_values(cur_domains, idx):
            nxt = cur_domains.copy()
            nxt[idx] = bit
            res = search(nxt)
            if res is not None:
                return res

        dead_states.add(key)
        return None

    solved = search(domains)
    if solved is None:
        return "No Solution"

    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            m = solved[r * N + c]
            if m == 0 or m.bit_count() != 1:
                return "No Solution"
            row.append(bit_value(m))
        grid.append(row)

    # Final validation.
    target = set(range(1, N + 1))
    for r in range(N):
        if set(grid[r]) != target:
            return "No Solution"
    for c in range(N):
        if {grid[r][c] for r in range(N)} != target:
            return "No Solution"

    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                a = r * N + c
                b = r * N + (c + 1)
                pair = (a, b) if a < b else (b, a)
                is_pos = pair in positive_pairs
                is_cons = abs(grid[r][c] - grid[r][c + 1]) == 1
                if is_pos != is_cons:
                    return "No Solution"
            if r + 1 < N:
                a = r * N + c
                b = (r + 1) * N + c
                pair = (a, b) if a < b else (b, a)
                is_pos = pair in positive_pairs
                is_cons = abs(grid[r][c] - grid[r + 1][c]) == 1
                if is_pos != is_cons:
                    return "No Solution"

    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 1, None, None, None, None, 3], [2, None, None, 1, None, 2, None], [None, None, None, None, None, None, 3], [5, None, None, None, None, 3, None], [None, None, None, None, None, None, 2], [None, None, 1, None, None, 2, None], [4, None, None, 3, None, None, 2]]}

from collections import deque

def solve(observation):
    data = observation.get("data")
    if not data or not isinstance(data, list):
        return "No Solution"

    n = len(data)
    islands = []
    island_at = {}
    for r in range(n):
        if len(data[r]) != n:
            return "No Solution"
        for c in range(n):
            v = data[r][c]
            if isinstance(v, int):
                idx = len(islands)
                islands.append((r, c, v))
                island_at[(r, c)] = idx

    m = len(islands)
    if m == 0:
        return {}

    edges = []
    incident = [[] for _ in range(m)]

    def add_edge(u, v):
        e = len(edges)
        edges.append((u, v))
        incident[u].append(e)
        incident[v].append(e)

    for u, (r, c, _) in enumerate(islands):
        cc = c + 1
        while cc < n and data[r][cc] is None:
            cc += 1
        if cc < n and isinstance(data[r][cc], int):
            add_edge(u, island_at[(r, cc)])

        rr = r + 1
        while rr < n and data[rr][c] is None:
            rr += 1
        if rr < n and isinstance(data[rr][c], int):
            add_edge(u, island_at[(rr, c)])

    ecount = len(edges)
    if ecount == 0:
        return {} if m == 1 and islands[0][2] == 0 else "No Solution"

    eu = [u for u, _ in edges]
    ev = [v for _, v in edges]
    target = [v for _, _, v in islands]

    high0 = [0] * ecount
    for e in range(ecount):
        u, v = eu[e], ev[e]
        high0[e] = min(2, target[u], target[v])

    cross = [[] for _ in range(ecount)]
    horiz = []
    vert = []

    for e in range(ecount):
        u, v = eu[e], ev[e]
        r1, c1, _ = islands[u]
        r2, c2, _ = islands[v]
        if r1 == r2:
            if c1 > c2:
                c1, c2 = c2, c1
            horiz.append((e, r1, c1, c2))
        else:
            if r1 > r2:
                r1, r2 = r2, r1
            vert.append((e, c1, r1, r2))

    for eh, r, c1, c2 in horiz:
        for evv, c, r1, r2 in vert:
            if r1 < r < r2 and c1 < c < c2:
                cross[eh].append(evv)
                cross[evv].append(eh)

    def other(e, u):
        return ev[e] if eu[e] == u else eu[e]

    def possible_connected(high):
        seen = [False] * m
        dq = deque([0])
        seen[0] = True
        count = 1
        while dq:
            u = dq.popleft()
            for e in incident[u]:
                if high[e] == 0:
                    continue
                v = other(e, u)
                if not seen[v]:
                    seen[v] = True
                    count += 1
                    dq.append(v)
        return count == m

    def positive_components(low):
        comp_id = [-1] * m
        comps = []
        for s in range(m):
            if comp_id[s] != -1:
                continue
            cid = len(comps)
            stack = [s]
            comp_id[s] = cid
            comp = [s]
            while stack:
                u = stack.pop()
                for e in incident[u]:
                    if low[e] == 0:
                        continue
                    v = other(e, u)
                    if comp_id[v] == -1:
                        comp_id[v] = cid
                        comp.append(v)
                        stack.append(v)
            comps.append(comp)
        return comps, comp_id

    def propagate(low, high):
        while True:
            changed = False

            for e in range(ecount):
                if low[e] > high[e]:
                    return False
                if low[e] > 0:
                    for f in cross[e]:
                        if high[f] != 0:
                            high[f] = 0
                            changed = True
                            if low[f] > 0:
                                return False

            for u in range(m):
                ids = incident[u]
                s_low = 0
                s_high = 0
                for e in ids:
                    s_low += low[e]
                    s_high += high[e]

                t = target[u]
                if t < s_low or t > s_high:
                    return False

                for e in ids:
                    other_low = s_low - low[e]
                    other_high = s_high - high[e]
                    nl = max(low[e], t - other_high, 0)
                    nh = min(high[e], t - other_low, 2)
                    if nl > nh:
                        return False
                    if nl != low[e] or nh != high[e]:
                        low[e] = nl
                        high[e] = nh
                        changed = True

            if not possible_connected(high):
                return False

            comps, comp_id = positive_components(low)
            if len(comps) > 1:
                out_edges = [[] for _ in range(len(comps))]
                for e in range(ecount):
                    if high[e] == 0:
                        continue
                    cu = comp_id[eu[e]]
                    cv = comp_id[ev[e]]
                    if cu != cv:
                        out_edges[cu].append(e)
                        out_edges[cv].append(e)

                for cid, comp in enumerate(comps):
                    if len(comp) == m:
                        continue
                    uniq = set(out_edges[cid])
                    if not uniq:
                        return False
                    if len(uniq) == 1:
                        e = next(iter(uniq))
                        if low[e] == 0:
                            low[e] = 1
                            changed = True
                            if low[e] > high[e]:
                                return False

            if not changed:
                return True

    def solved(low, high):
        for e in range(ecount):
            if low[e] != high[e]:
                return False
        comps, _ = positive_components(low)
        return len(comps) == 1

    def state_key(low, high):
        return tuple((low[e] << 2) | high[e] for e in range(ecount))

    failed = set()

    def select_edge(low, high):
        sum_low = [0] * m
        sum_high = [0] * m
        for u in range(m):
            for e in incident[u]:
                sum_low[u] += low[e]
                sum_high[u] += high[e]

        best = None
        best_score = None
        for e in range(ecount):
            if low[e] == high[e]:
                continue
            u, v = eu[e], ev[e]
            width = high[e] - low[e]
            tight_u = sum_high[u] - sum_low[u]
            tight_v = sum_high[v] - sum_low[v]
            score = (
                width,
                -(len(cross[e])),
                -(len(incident[u]) + len(incident[v])),
                tight_u + tight_v,
            )
            if best_score is None or score < best_score:
                best_score = score
                best = e
        return best

    def value_order(e, low, high):
        return list(range(high[e], low[e] - 1, -1))

    def dfs(low, high):
        if not propagate(low, high):
            return None

        key = state_key(low, high)
        if key in failed:
            return None

        if solved(low, high):
            return low

        e = select_edge(low, high)
        if e is None:
            failed.add(key)
            return None

        for val in value_order(e, low, high):
            low2 = low[:]
            high2 = high[:]
            low2[e] = val
            high2[e] = val
            ans = dfs(low2, high2)
            if ans is not None:
                return ans

        failed.add(key)
        return None

    low_init = [0] * ecount
    high_init = high0[:]

    solution = dfs(low_init, high_init)
    if solution is None:
        return "No Solution"

    result = {}
    for e in range(ecount):
        cnt = solution[e]
        if cnt > 0:
            a = islands[eu[e]][:2]
            b = islands[ev[e]][:2]
            if a > b:
                a, b = b, a
            result[(a, b)] = cnt
    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 'W', None, None, None, 'W'], [None, None, 'B', None, None, None], [None, 'W', None, 'W', None, 'W'], [None, None, None, None, None, None], ['B', None, None, 'W', None, 'B']]}

from functools import lru_cache


# Internal encoding: W -> 0, B -> 1
CHAR_TO_BIT = {'W': 0, 'B': 1}
BIT_TO_CHAR = {0: 'W', 1: 'B'}


@lru_cache(maxsize=None)
def generate_patterns(length):
    # All valid line patterns of given length:
    # - equal number of 0/1
    # - no three consecutive equal
    if length % 2 != 0:
        return ()
    target_ones = length // 2
    result = []

    def rec(pos, ones, pattern):
        if ones > target_ones:
            return
        remaining = length - pos
        if ones + remaining < target_ones:
            return
        if pos >= 2 and pattern[-1] == pattern[-2]:
            forced = 1 - pattern[-1]
            if ones + forced > target_ones:
                return
            pattern.append(forced)
            rec(pos + 1, ones + forced, pattern)
            pattern.pop()
            return
        if pos == length:
            if ones == target_ones:
                result.append(tuple(pattern))
            return
        pattern.append(0)
        rec(pos + 1, ones, pattern)
        pattern.pop()
        pattern.append(1)
        rec(pos + 1, ones + 1, pattern)
        pattern.pop()

    rec(0, 0, [])
    return tuple(result)


def line_respects_givens(pattern, givens):
    for a, b in zip(pattern, givens):
        if b is not None and a != b:
            return False
    return True


def has_distinct_assignment(domains):
    # Bipartite matching feasibility for all-different constraint on lines.
    order = sorted(range(len(domains)), key=lambda i: len(domains[i]))
    match_value_to_var = {}

    def dfs(var, seen):
        for value in domains[var]:
            if value in seen:
                continue
            seen.add(value)
            if value not in match_value_to_var or dfs(match_value_to_var[value], seen):
                match_value_to_var[value] = var
                return True
        return False

    for var in order:
        if not dfs(var, set()):
            return False
    return True


def prune_all_diff(domains, aggressive_limit=160):
    # Enforce:
    # 1) no two fixed lines may be equal
    # 2) incomplete lines cannot use a pattern already fixed elsewhere
    # 3) matching feasibility
    # 4) optional candidate-by-candidate pruning when domains are small enough
    changed = False

    fixed = {}
    for i, d in enumerate(domains):
        if not d:
            return None, False
        if len(d) == 1:
            v = d[0]
            if v in fixed and fixed[v] != i:
                return None, False
            fixed[v] = i

    new_domains = [d[:] for d in domains]
    for i, d in enumerate(new_domains):
        if len(d) > 1:
            nd = [v for v in d if v not in fixed]
            if not nd:
                return None, False
            if len(nd) != len(d):
                new_domains[i] = nd
                changed = True

    if not has_distinct_assignment(new_domains):
        return None, False

    total = sum(len(d) for d in new_domains)
    if total <= aggressive_limit:
        for i, d in enumerate(new_domains):
            if len(d) <= 1:
                continue
            kept = []
            for v in d:
                test = [x[:] for x in new_domains]
                test[i] = [v]
                if has_distinct_assignment(test):
                    kept.append(v)
            if not kept:
                return None, False
            if len(kept) != len(d):
                new_domains[i] = kept
                changed = True

    return new_domains, changed


def compute_row_cell_masks(row_domains, row_patterns, n_rows, n_cols):
    masks = [[0] * n_cols for _ in range(n_rows)]
    for i in range(n_rows):
        for rid in row_domains[i]:
            pat = row_patterns[rid]
            for j, v in enumerate(pat):
                masks[i][j] |= (1 << v)
    return masks


def compute_col_cell_masks(col_domains, col_patterns, n_rows, n_cols):
    masks = [[0] * n_cols for _ in range(n_rows)]
    for j in range(n_cols):
        for cid in col_domains[j]:
            pat = col_patterns[cid]
            for i, v in enumerate(pat):
                masks[i][j] |= (1 << v)
    return masks


def propagate(row_domains, col_domains, row_patterns, col_patterns, givens):
    n_rows = len(row_domains)
    n_cols = len(col_domains)

    row_domains = [d[:] for d in row_domains]
    col_domains = [d[:] for d in col_domains]

    while True:
        changed = False

        for d in row_domains:
            if not d:
                return None, None
        for d in col_domains:
            if not d:
                return None, None

        row_domains, row_changed = prune_all_diff(row_domains)
        if row_domains is None:
            return None, None
        if row_changed:
            changed = True

        col_domains, col_changed = prune_all_diff(col_domains)
        if col_domains is None:
            return None, None
        if col_changed:
            changed = True

        row_masks = compute_row_cell_masks(row_domains, row_patterns, n_rows, n_cols)
        col_masks = compute_col_cell_masks(col_domains, col_patterns, n_rows, n_cols)

        for i in range(n_rows):
            for j in range(n_cols):
                allowed = row_masks[i][j] & col_masks[i][j]
                if givens[i][j] is not None:
                    allowed &= (1 << givens[i][j])
                if allowed == 0:
                    return None, None

        new_row_domains = []
        for i, d in enumerate(row_domains):
            nd = []
            for rid in d:
                pat = row_patterns[rid]
                ok = True
                for j, v in enumerate(pat):
                    allowed = col_masks[i][j]
                    if givens[i][j] is not None:
                        allowed &= (1 << givens[i][j])
                    if ((allowed >> v) & 1) == 0:
                        ok = False
                        break
                if ok:
                    nd.append(rid)
            if not nd:
                return None, None
            if len(nd) != len(d):
                changed = True
            new_row_domains.append(nd)
        row_domains = new_row_domains

        row_masks = compute_row_cell_masks(row_domains, row_patterns, n_rows, n_cols)

        new_col_domains = []
        for j, d in enumerate(col_domains):
            nd = []
            for cid in d:
                pat = col_patterns[cid]
                ok = True
                for i, v in enumerate(pat):
                    allowed = row_masks[i][j]
                    if givens[i][j] is not None:
                        allowed &= (1 << givens[i][j])
                    if ((allowed >> v) & 1) == 0:
                        ok = False
                        break
                if ok:
                    nd.append(cid)
            if not nd:
                return None, None
            if len(nd) != len(d):
                changed = True
            new_col_domains.append(nd)
        col_domains = new_col_domains

        if not changed:
            break

    return row_domains, col_domains


def verify_grid(grid, givens):
    n_rows = len(grid)
    n_cols = len(grid[0]) if n_rows else 0

    if n_rows % 2 != 0 or n_cols % 2 != 0:
        return False

    for i in range(n_rows):
        row = grid[i]
        if sum(row) != n_cols // 2:
            return False
        for j in range(n_cols):
            if givens[i][j] is not None and row[j] != givens[i][j]:
                return False
        for j in range(n_cols - 2):
            if row[j] == row[j + 1] == row[j + 2]:
                return False

    rows_seen = set()
    for row in grid:
        t = tuple(row)
        if t in rows_seen:
            return False
        rows_seen.add(t)

    cols_seen = set()
    for j in range(n_cols):
        col = tuple(grid[i][j] for i in range(n_rows))
        if sum(col) != n_rows // 2:
            return False
        for i in range(n_rows - 2):
            if col[i] == col[i + 1] == col[i + 2]:
                return False
        if col in cols_seen:
            return False
        cols_seen.add(col)

    return True


def extract_grid_if_complete(row_domains, col_domains, row_patterns, col_patterns, givens):
    if all(len(d) == 1 for d in row_domains):
        grid = [list(row_patterns[d[0]]) for d in row_domains]
        if verify_grid(grid, givens):
            return grid
    if all(len(d) == 1 for d in col_domains):
        n_rows = len(row_domains)
        n_cols = len(col_domains)
        grid = [[0] * n_cols for _ in range(n_rows)]
        for j, d in enumerate(col_domains):
            pat = col_patterns[d[0]]
            for i, v in enumerate(pat):
                grid[i][j] = v
        if verify_grid(grid, givens):
            return grid
    return None


def order_row_candidates(i, row_domains, col_domains, row_patterns, col_patterns):
    scores = []
    for rid in row_domains[i]:
        pat = row_patterns[rid]
        score = 0
        for j, v in enumerate(pat):
            compatible = 0
            for cid in col_domains[j]:
                if col_patterns[cid][i] == v:
                    compatible += 1
            score += compatible
        scores.append((score, rid))
    scores.sort()
    return [rid for _, rid in scores]


def order_col_candidates(j, row_domains, col_domains, row_patterns, col_patterns):
    scores = []
    for cid in col_domains[j]:
        pat = col_patterns[cid]
        score = 0
        for i, v in enumerate(pat):
            compatible = 0
            for rid in row_domains[i]:
                if row_patterns[rid][j] == v:
                    compatible += 1
            score += compatible
        scores.append((score, cid))
    scores.sort()
    return [cid for _, cid in scores]


def search(row_domains, col_domains, row_patterns, col_patterns, givens):
    row_domains, col_domains = propagate(row_domains, col_domains, row_patterns, col_patterns, givens)
    if row_domains is None:
        return None

    done = extract_grid_if_complete(row_domains, col_domains, row_patterns, col_patterns, givens)
    if done is not None:
        return done

    best_kind = None
    best_idx = None
    best_size = 10**9

    for i, d in enumerate(row_domains):
        if 1 < len(d) < best_size:
            best_size = len(d)
            best_kind = 'row'
            best_idx = i

    for j, d in enumerate(col_domains):
        if 1 < len(d) < best_size:
            best_size = len(d)
            best_kind = 'col'
            best_idx = j

    if best_kind is None:
        return None

    if best_kind == 'row':
        for rid in order_row_candidates(best_idx, row_domains, col_domains, row_patterns, col_patterns):
            new_row_domains = [d[:] for d in row_domains]
            new_col_domains = [d[:] for d in col_domains]
            new_row_domains[best_idx] = [rid]
            result = search(new_row_domains, new_col_domains, row_patterns, col_patterns, givens)
            if result is not None:
                return result
    else:
        for cid in order_col_candidates(best_idx, row_domains, col_domains, row_patterns, col_patterns):
            new_row_domains = [d[:] for d in row_domains]
            new_col_domains = [d[:] for d in col_domains]
            new_col_domains[best_idx] = [cid]
            result = search(new_row_domains, new_col_domains, row_patterns, col_patterns, givens)
            if result is not None:
                return result

    return None


def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return "No Solution"

    n_rows = len(data)
    n_cols = len(data[0])

    if n_rows % 2 != 0 or n_cols % 2 != 0:
        return "No Solution"

    givens = []
    for row in data:
        if len(row) != n_cols:
            return "No Solution"
        converted = []
        for cell in row:
            if cell is None:
                converted.append(None)
            elif cell in CHAR_TO_BIT:
                converted.append(CHAR_TO_BIT[cell])
            else:
                return "No Solution"
        givens.append(converted)

    row_patterns = generate_patterns(n_cols)
    col_patterns = generate_patterns(n_rows)

    if not row_patterns or not col_patterns:
        return "No Solution"

    row_domains = []
    for i in range(n_rows):
        domain = []
        for rid, pat in enumerate(row_patterns):
            if line_respects_givens(pat, givens[i]):
                domain.append(rid)
        if not domain:
            return "No Solution"
        row_domains.append(domain)

    col_domains = []
    for j in range(n_cols):
        col_givens = [givens[i][j] for i in range(n_rows)]
        domain = []
        for cid, pat in enumerate(col_patterns):
            if line_respects_givens(pat, col_givens):
                domain.append(cid)
        if not domain:
            return "No Solution"
        col_domains.append(domain)

    grid = search(row_domains, col_domains, row_patterns, col_patterns, givens)
    if grid is None:
        return "No Solution"

    return [[BIT_TO_CHAR[v] for v in row] for row in grid]


