# Aquarium solver:
# - Each region chooses one water level.
# - Region candidates are generated as "all cells at rows >= threshold row".
# - Logical deduction is done by repeated exact row/column sum filtering using DP.
# - Search branches only on region-level candidates after propagation stalls.

from collections import defaultdict

def solve(observation):
    region_grid = observation["region"]
    row_target = observation["row_water_counts"]
    col_target = observation["col_water_counts"]

    R = len(region_grid)
    C = len(region_grid[0]) if R else 0

    if sum(row_target) != sum(col_target):
        return "No Solution"

    # Remap arbitrary region ids to dense 0..n-1
    ids = sorted({x for row in region_grid for x in row})
    rid_map = {rid: i for i, rid in enumerate(ids)}
    dense_grid = [[rid_map[x] for x in row] for row in region_grid]
    N = len(ids)

    # Collect cells per region
    regions = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            regions[dense_grid[r][c]].append((r, c))

    # Build candidate states for each region:
    # state = choose a water level, producing all cells in rows >= chosen threshold.
    region_states = []
    region_row_masks = []   # region_row_masks[rid][row][count] -> bitmask of states
    region_col_masks = []   # region_col_masks[rid][col][count] -> bitmask of states
    region_touch_rows = []
    region_touch_cols = []
    region_impact = []

    for cells in regions:
        rows_present = sorted({r for r, _ in cells})
        row_to_cells = defaultdict(list)
        col_to_cells = defaultdict(list)
        for r, c in cells:
            row_to_cells[r].append((r, c))
            col_to_cells[c].append((r, c))

        states = []
        # k = 0 => full, k = len(rows_present) => empty
        for k in range(len(rows_present) + 1):
            if k == len(rows_present):
                water = []
            else:
                cutoff = rows_present[k]
                water = [(r, c) for (r, c) in cells if r >= cutoff]

            row_counts = [0] * R
            col_counts = [0] * C
            cell_mask = 0
            for r, c in water:
                row_counts[r] += 1
                col_counts[c] += 1
                cell_mask |= 1 << (r * C + c)

            states.append({
                "rows": tuple(row_counts),
                "cols": tuple(col_counts),
                "cells_mask": cell_mask,
                "water_count": len(water),
            })

        region_states.append(states)

        rm = [defaultdict(int) for _ in range(R)]
        cm = [defaultdict(int) for _ in range(C)]
        for s_idx, st in enumerate(states):
            bit = 1 << s_idx
            for r in range(R):
                rm[r][st["rows"][r]] |= bit
            for c in range(C):
                cm[c][st["cols"][c]] |= bit
        region_row_masks.append(rm)
        region_col_masks.append(cm)

        touch_rows = sorted(row_to_cells.keys())
        touch_cols = sorted(col_to_cells.keys())
        region_touch_rows.append(touch_rows)
        region_touch_cols.append(touch_cols)
        region_impact.append(len(touch_rows) + len(touch_cols))

    # Which regions matter for each row/column
    row_regions = [[] for _ in range(R)]
    col_regions = [[] for _ in range(C)]
    for rid in range(N):
        for r in region_touch_rows[rid]:
            row_regions[r].append(rid)
        for c in region_touch_cols[rid]:
            col_regions[c].append(rid)

    full_domains = tuple((1 << len(region_states[rid])) - 1 for rid in range(N))
    dead = set()

    def bit_count(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def supported_mask_for_line(participants, target, domains, axis_masks):
        # axis_masks[rid][line][count] -> state bitmask
        n = len(participants)
        limit_mask = (1 << (target + 1)) - 1

        values_per = []
        prefix = [1]  # bitset of reachable sums
        for i in range(n):
            rid = participants[i]
            dom = domains[rid]
            vals = []
            for val, m in axis_masks[rid].items():
                if dom & m:
                    vals.append(val)
            vals = sorted(set(vals))
            if not vals:
                return None
            values_per.append(vals)

            nxt = 0
            cur = prefix[-1]
            for v in vals:
                if v <= target:
                    nxt |= (cur << v)
            nxt &= limit_mask
            prefix.append(nxt)

        if ((prefix[-1] >> target) & 1) == 0:
            return None

        suffix = [0] * (n + 1)
        suffix[n] = 1
        for i in range(n - 1, -1, -1):
            nxt = 0
            cur = suffix[i + 1]
            for v in values_per[i]:
                if v <= target:
                    nxt |= (cur << v)
            suffix[i] = nxt & limit_mask

        keep = {}
        for i in range(n):
            rid = participants[i]
            pre = prefix[i]
            suf = suffix[i + 1]
            keep_mask = 0

            for v in values_per[i]:
                need = target - v
                if need < 0:
                    continue
                ok = False
                for p in range(need + 1):
                    if ((pre >> p) & 1) and ((suf >> (need - p)) & 1):
                        ok = True
                        break
                if ok:
                    keep_mask |= domains[rid] & axis_masks[rid][v]

            if keep_mask == 0:
                return None
            keep[rid] = keep_mask

        return keep

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # Row deductions
            for r in range(R):
                participants = row_regions[r]
                axis = {rid: region_row_masks[rid][r] for rid in participants}
                keep = supported_mask_for_line(participants, row_target[r], domains, axis)
                if keep is None:
                    return False
                for rid, km in keep.items():
                    nd = domains[rid] & km
                    if nd == 0:
                        return False
                    if nd != domains[rid]:
                        domains[rid] = nd
                        changed = True

            # Column deductions
            for c in range(C):
                participants = col_regions[c]
                axis = {rid: region_col_masks[rid][c] for rid in participants}
                keep = supported_mask_for_line(participants, col_target[c], domains, axis)
                if keep is None:
                    return False
                for rid, km in keep.items():
                    nd = domains[rid] & km
                    if nd == 0:
                        return False
                    if nd != domains[rid]:
                        domains[rid] = nd
                        changed = True

        return True

    def build_answer(domains):
        grid = [[None for _ in range(C)] for _ in range(R)]
        for rid in range(N):
            dom = domains[rid]
            if dom == 0 or (dom & (dom - 1)):
                return None
            s_idx = dom.bit_length() - 1
            mask = region_states[rid][s_idx]["cells_mask"]
            while mask:
                b = mask & -mask
                idx = b.bit_length() - 1
                rr, cc = divmod(idx, C)
                grid[rr][cc] = 'W'
                mask ^= b

        if [sum(1 for x in row if x == 'W') for row in grid] != row_target:
            return None
        if [sum(1 for r in range(R) if grid[r][c] == 'W') for c in range(C)] != col_target:
            return None
        return grid

    def choose_region(domains):
        best = None
        best_key = None
        for rid in range(N):
            bc = bit_count(domains[rid])
            if bc > 1:
                key = (bc, -region_impact[rid])
                if best is None or key < best_key:
                    best = rid
                    best_key = key
        return best

    def order_states(rid, dom):
        # Mildly human-like: try extremes last, middle-ish water counts first.
        items = []
        for s in iter_bits(dom):
            items.append((region_states[rid][s]["water_count"], s))
        if not items:
            return []
        counts = [x for x, _ in items]
        mid = (min(counts) + max(counts)) / 2.0
        items.sort(key=lambda t: (abs(t[0] - mid), t[0]))
        return [s for _, s in items]

    def dfs(domains_tuple):
        if domains_tuple in dead:
            return None

        domains = list(domains_tuple)
        if not propagate(domains):
            dead.add(domains_tuple)
            return None

        state = tuple(domains)
        if state in dead:
            return None

        if all((d & (d - 1)) == 0 for d in domains):
            ans = build_answer(domains)
            if ans is not None:
                return ans
            dead.add(state)
            return None

        rid = choose_region(domains)
        if rid is None:
            dead.add(state)
            return None

        for s in order_states(rid, domains[rid]):
            new_domains = list(domains)
            new_domains[rid] = 1 << s
            res = dfs(tuple(new_domains))
            if res is not None:
                return res

        dead.add(state)
        return None

    result = dfs(full_domains)
    return repr(result) if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

