from itertools import combinations


def solve(observation):
    region_grid = observation["region"]
    data_grid = observation["data"]
    n = len(data_grid)
    if n == 0 or any(len(row) != n for row in data_grid) or any(len(row) != n for row in region_grid):
        return "No Solution"

    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def is_singleton(m):
        return m and (m & (m - 1)) == 0

    def mask_to_val(m):
        return m.bit_length()

    def iter_bits(m):
        while m:
            b = m & -m
            yield b
            m ^= b

    # Compress arbitrary region IDs to 0..R-1 in first-seen order.
    reg_map = {}
    reg_ids = []
    for r in range(n):
        for c in range(n):
            rid = region_grid[r][c]
            if rid not in reg_map:
                reg_map[rid] = len(reg_map)
            reg_ids.append(reg_map[rid])

    rcount = len(reg_map)
    if rcount != n:
        return "No Solution"

    cells = list(range(n * n))
    row_of = [i // n for i in cells]
    col_of = [i % n for i in cells]
    reg_of = reg_ids[:]

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    regs = [[] for _ in range(n)]
    for i in cells:
        regs[reg_of[i]].append(i)

    # Each region must contain exactly n cells.
    if any(len(reg) != n for reg in regs):
        return "No Solution"

    all_units = rows + cols + regs

    peers = []
    for i in cells:
        s = set(rows[row_of[i]]) | set(cols[col_of[i]]) | set(regs[reg_of[i]])
        s.discard(i)
        peers.append(tuple(s))

    # Initialize domains.
    domains = [full] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data_grid[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[r * n + c] = bit(v)

    def apply_basic(dom):
        # Intersect with row/col/region missing digits.
        row_missing = [full] * n
        col_missing = [full] * n
        reg_missing = [full] * n

        for units, missing_arr in ((rows, row_missing), (cols, col_missing), (regs, reg_missing)):
            for u_idx, unit in enumerate(units):
                used = 0
                for i in unit:
                    m = dom[i]
                    if m == 0:
                        return None, None, None
                    if is_singleton(m):
                        if used & m:
                            return None, None, None
                        used |= m
                missing_arr[u_idx] = full ^ used

        changed = False
        for i in cells:
            if not is_singleton(dom[i]):
                newm = dom[i] & row_missing[row_of[i]] & col_missing[col_of[i]] & reg_missing[reg_of[i]]
                if newm == 0:
                    return None, None, None
                if newm != dom[i]:
                    dom[i] = newm
                    changed = True
        return changed, row_missing, col_missing, reg_missing

    def hidden_singles(dom, units, unit_missing):
        changed = False
        for u_idx, unit in enumerate(units):
            miss = unit_missing[u_idx]
            if miss == 0:
                continue
            counts = {}
            last = {}
            union = 0
            for i in unit:
                m = dom[i] & miss
                union |= m
                for b in iter_bits(m):
                    counts[b] = counts.get(b, 0) + 1
                    last[b] = i
            if (union & miss) != miss:
                return None
            for b in iter_bits(miss):
                if counts.get(b, 0) == 1:
                    i = last[b]
                    if dom[i] != b:
                        dom[i] = b
                        changed = True
        return changed

    def naked_subsets(dom, unit):
        # Human-like naked pairs/triples/quads.
        changed = False
        unsolved = [i for i in unit if not is_singleton(dom[i])]
        m = len(unsolved)
        if m < 2:
            return changed
        max_k = min(4, m - 1)
        seen = set()
        for k in range(2, max_k + 1):
            for combo in combinations(unsolved, k):
                union = 0
                for i in combo:
                    union |= dom[i]
                if union.bit_count() != k:
                    continue
                key = (k, union, combo)
                if key in seen:
                    continue
                seen.add(key)
                for j in unsolved:
                    if j not in combo and (dom[j] & union):
                        newm = dom[j] & ~union
                        if newm == 0:
                            return None
                        if newm != dom[j]:
                            dom[j] = newm
                            changed = True
        return changed

    def locked_candidates(dom, row_missing, col_missing, reg_missing):
        changed = False

        # Region -> row / column
        for g, unit in enumerate(regs):
            miss = reg_missing[g]
            for b in iter_bits(miss):
                pos = [i for i in unit if dom[i] & b]
                if not pos:
                    return None
                rs = {row_of[i] for i in pos}
                if len(rs) == 1:
                    r = next(iter(rs))
                    for j in rows[r]:
                        if reg_of[j] != g and (dom[j] & b):
                            newm = dom[j] & ~b
                            if newm == 0:
                                return None
                            if newm != dom[j]:
                                dom[j] = newm
                                changed = True
                cs = {col_of[i] for i in pos}
                if len(cs) == 1:
                    c = next(iter(cs))
                    for j in cols[c]:
                        if reg_of[j] != g and (dom[j] & b):
                            newm = dom[j] & ~b
                            if newm == 0:
                                return None
                            if newm != dom[j]:
                                dom[j] = newm
                                changed = True

        # Row -> region
        for r, unit in enumerate(rows):
            miss = row_missing[r]
            for b in iter_bits(miss):
                pos = [i for i in unit if dom[i] & b]
                if not pos:
                    return None
                gs = {reg_of[i] for i in pos}
                if len(gs) == 1:
                    g = next(iter(gs))
                    for j in regs[g]:
                        if row_of[j] != r and (dom[j] & b):
                            newm = dom[j] & ~b
                            if newm == 0:
                                return None
                            if newm != dom[j]:
                                dom[j] = newm
                                changed = True

        # Column -> region
        for c, unit in enumerate(cols):
            miss = col_missing[c]
            for b in iter_bits(miss):
                pos = [i for i in unit if dom[i] & b]
                if not pos:
                    return None
                gs = {reg_of[i] for i in pos}
                if len(gs) == 1:
                    g = next(iter(gs))
                    for j in regs[g]:
                        if col_of[j] != c and (dom[j] & b):
                            newm = dom[j] & ~b
                            if newm == 0:
                                return None
                            if newm != dom[j]:
                                dom[j] = newm
                                changed = True

        return changed

    def propagate(dom):
        dom = dom[:]
        while True:
            progress = False

            basic = apply_basic(dom)
            if basic[0] is None:
                return None
            changed, row_missing, col_missing, reg_missing = basic
            progress |= changed

            res = hidden_singles(dom, rows, row_missing)
            if res is None:
                return None
            progress |= res

            res = hidden_singles(dom, cols, col_missing)
            if res is None:
                return None
            progress |= res

            res = hidden_singles(dom, regs, reg_missing)
            if res is None:
                return None
            progress |= res

            # Recompute before structural eliminations.
            basic = apply_basic(dom)
            if basic[0] is None:
                return None
            changed, row_missing, col_missing, reg_missing = basic
            progress |= changed

            res = locked_candidates(dom, row_missing, col_missing, reg_missing)
            if res is None:
                return None
            progress |= res

            for unit in all_units:
                res = naked_subsets(dom, unit)
                if res is None:
                    return None
                progress |= res

            if not progress:
                break

        # Final consistency check.
        for unit in all_units:
            used = 0
            for i in unit:
                m = dom[i]
                if m == 0:
                    return None
                if is_singleton(m):
                    if used & m:
                        return None
                    used |= m
            # Every missing digit must appear somewhere.
            miss = full ^ used
            for b in iter_bits(miss):
                if not any(dom[i] & b for i in unit):
                    return None

        return dom

    def solved(dom):
        return all(is_singleton(m) for m in dom)

    def choose_cell(dom):
        best = None
        best_key = None
        for i in cells:
            bc = dom[i].bit_count()
            if bc <= 1:
                continue
            # MRV, then most constrained by peer ambiguity.
            peer_weight = sum(1 for j in peers[i] if not is_singleton(dom[j]))
            key = (bc, -peer_weight)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def candidate_order(dom, i):
        vals = list(iter_bits(dom[i]))

        def score(b):
            s = 0
            # Prefer digits that are more forced in related units.
            for unit in (rows[row_of[i]], cols[col_of[i]], regs[reg_of[i]]):
                s += sum(1 for j in unit if dom[j] & b)
            return s

        vals.sort(key=score)
        return vals

    def search(dom):
        dom = propagate(dom)
        if dom is None:
            return None
        if solved(dom):
            return dom

        i = choose_cell(dom)
        if i is None:
            return None

        for b in candidate_order(dom, i):
            new_dom = dom[:]
            new_dom[i] = b
            res = search(new_dom)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = [[mask_to_val(result[r * n + c]) for c in range(n)] for r in range(n)]
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

