# Bitmask domain encoding for bridge counts {0,1,2}
VAL_MASK = [1 << 0, 1 << 1, 1 << 2]
FULL_MASK = VAL_MASK[0] | VAL_MASK[1] | VAL_MASK[2]
POS_MASK = VAL_MASK[1] | VAL_MASK[2]

MASK_VALUES = {
    0: (),
    1: (0,),
    2: (1,),
    3: (0, 1),
    4: (2,),
    5: (0, 2),
    6: (1, 2),
    7: (0, 1, 2),
}
MASK_MIN = [0] * 8
MASK_MAX = [0] * 8
MASK_SIZE = [0] * 8
for m in range(8):
    vals = MASK_VALUES[m]
    MASK_SIZE[m] = len(vals)
    if vals:
        MASK_MIN[m] = vals[0]
        MASK_MAX[m] = vals[-1]

RANGE_MASK = [[0] * 3 for _ in range(3)]
for a in range(3):
    for b in range(3):
        m = 0
        if a <= b:
            for v in range(a, b + 1):
                m |= VAL_MASK[v]
        RANGE_MASK[a][b] = m

SINGLETON_VALUE = {1: 0, 2: 1, 4: 2}


def solve(observation):
    data = observation.get("data")
    if not data or not isinstance(data, list):
        return "No Solution"
    n = len(data)

    # Collect islands
    islands = []
    coord_to_id = {}
    for r in range(n):
        if len(data[r]) != n:
            return "No Solution"
        for c in range(n):
            if data[r][c] is not None:
                if not isinstance(data[r][c], int) or data[r][c] < 0:
                    return "No Solution"
                idx = len(islands)
                islands.append(((r, c), data[r][c]))
                coord_to_id[(r, c)] = idx

    m_islands = len(islands)
    if m_islands == 0:
        return "{}"

    coords = [p for p, _ in islands]
    reqs = [v for _, v in islands]

    # Build candidate edges between nearest visible islands
    edges = []
    incidences = [[] for _ in range(m_islands)]
    horizontal_edges = []
    vertical_edges = []

    def add_edge(i, j, orient):
        e = len(edges)
        (r1, c1) = coords[i]
        (r2, c2) = coords[j]
        if orient == "H":
            left_c, right_c = sorted((c1, c2))
            span = (r1, left_c, right_c)
            horizontal_edges.append(e)
        else:
            top_r, bot_r = sorted((r1, r2))
            span = (c1, top_r, bot_r)
            vertical_edges.append(e)
        edges.append((i, j, orient, span))
        incidences[i].append(e)
        incidences[j].append(e)

    for i, (r, c) in enumerate(coords):
        cc = c + 1
        while cc < n and data[r][cc] is None:
            cc += 1
        if cc < n and data[r][cc] is not None:
            add_edge(i, coord_to_id[(r, cc)], "H")

        rr = r + 1
        while rr < n and data[rr][c] is None:
            rr += 1
        if rr < n and data[rr][c] is not None:
            add_edge(i, coord_to_id[(rr, c)], "V")

    m_edges = len(edges)

    # Immediate structural impossibility
    for i in range(m_islands):
        if reqs[i] > 2 * len(incidences[i]):
            return "No Solution"

    # Crossing relationships
    crossings = [[] for _ in range(m_edges)]
    for eh in horizontal_edges:
        i1, j1, _, (r, c1, c2) = edges[eh]
        for ev in vertical_edges:
            i2, j2, _, (c, r1, r2) = edges[ev]
            if c1 < c < c2 and r1 < r < r2:
                crossings[eh].append(ev)
                crossings[ev].append(eh)

    incident_degrees = [len(incidences[i]) for i in range(m_islands)]

    def is_singleton(mask):
        return mask in SINGLETON_VALUE

    def possible_positive(mask):
        return (mask & POS_MASK) != 0

    def forced_positive(mask):
        return (mask & VAL_MASK[0]) == 0

    def connectivity_prune(domains):
        # 1) All islands must still be connectable through edges that may be positive
        seen = [False] * m_islands
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for e in incidences[u]:
                if not possible_positive(domains[e]):
                    continue
                a, b = edges[e][0], edges[e][1]
                v = b if a == u else a
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        if not all(seen):
            return False

        # 2) Forced-positive components cannot become sealed off from the rest
        parent = list(range(m_islands))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        for e in range(m_edges):
            if forced_positive(domains[e]):
                a, b = edges[e][0], edges[e][1]
                union(a, b)

        comp_members = {}
        for i in range(m_islands):
            ri = find(i)
            comp_members.setdefault(ri, []).append(i)

        if len(comp_members) > 1:
            has_exit = {ri: False for ri in comp_members}
            for e in range(m_edges):
                if not possible_positive(domains[e]):
                    continue
                a, b = edges[e][0], edges[e][1]
                ra, rb = find(a), find(b)
                if ra != rb:
                    has_exit[ra] = True
                    has_exit[rb] = True
            for ri in comp_members:
                if not has_exit[ri]:
                    return False

        return True

    def final_connected(domains):
        seen = [False] * m_islands
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for e in incidences[u]:
                if SINGLETON_VALUE.get(domains[e], 0) <= 0:
                    continue
                a, b = edges[e][0], edges[e][1]
                v = b if a == u else a
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        return all(seen)

    def final_valid(domains):
        # exact island counts
        for i in range(m_islands):
            s = 0
            for e in incidences[i]:
                if domains[e] not in SINGLETON_VALUE:
                    return False
                s += SINGLETON_VALUE[domains[e]]
            if s != reqs[i]:
                return False
        # crossing check
        for e in range(m_edges):
            v = SINGLETON_VALUE.get(domains[e])
            if v is None or v == 0:
                continue
            for ce in crossings[e]:
                cv = SINGLETON_VALUE.get(domains[ce])
                if cv is not None and cv > 0:
                    return False
        return final_connected(domains)

    def propagate(domains):
        iq = deque(range(m_islands))
        eq = deque(range(m_edges))
        in_iq = [True] * m_islands
        in_eq = [True] * m_edges

        def enqueue_island(i):
            if not in_iq[i]:
                in_iq[i] = True
                iq.append(i)

        def enqueue_edge(e):
            if not in_eq[e]:
                in_eq[e] = True
                eq.append(e)

        def restrict_edge(e, newmask):
            cur = domains[e]
            nm = cur & newmask
            if nm == cur:
                return True
            if nm == 0:
                return False
            domains[e] = nm
            a, b = edges[e][0], edges[e][1]
            enqueue_island(a)
            enqueue_island(b)
            enqueue_edge(e)
            return True

        while iq or eq:
            while eq:
                e = eq.popleft()
                in_eq[e] = False
                m = domains[e]

                # If this edge must be positive, every crossing edge must be zero
                if forced_positive(m):
                    for ce in crossings[e]:
                        if not restrict_edge(ce, VAL_MASK[0]):
                            return False

            while iq:
                i = iq.popleft()
                in_iq[i] = False

                inc = incidences[i]
                req = reqs[i]

                smin = 0
                smax = 0
                possible_neighbors = 0
                for e in inc:
                    dm = domains[e]
                    smin += MASK_MIN[dm]
                    smax += MASK_MAX[dm]
                    if possible_positive(dm):
                        possible_neighbors += 1

                if req < smin or req > smax:
                    return False

                # Basic degree viability
                if req > 0 and possible_neighbors == 0:
                    return False

                # Human-like interval tightening per incident edge
                for e in inc:
                    dm = domains[e]
                    omin = smin - MASK_MIN[dm]
                    omax = smax - MASK_MAX[dm]
                    lo = max(MASK_MIN[dm], req - omax)
                    hi = min(MASK_MAX[dm], req - omin)
                    if lo > hi:
                        return False
                    allowed = RANGE_MASK[lo][hi]
                    if not restrict_edge(e, allowed):
                        return False

                # Recompute for stronger local deductions
                smin = sum(MASK_MIN[domains[e]] for e in inc)
                smax = sum(MASK_MAX[domains[e]] for e in inc)
                if req < smin or req > smax:
                    return False

                # If minimum sum already matches requirement, all undecided extras collapse to minima
                if req == smin:
                    for e in inc:
                        dm = domains[e]
                        if MASK_MIN[dm] != MASK_MAX[dm]:
                            if not restrict_edge(e, VAL_MASK[MASK_MIN[dm]]):
                                return False

                # If maximum sum already matches requirement, all undecided collapse to maxima
                if req == smax:
                    for e in inc:
                        dm = domains[e]
                        if MASK_MIN[dm] != MASK_MAX[dm]:
                            if not restrict_edge(e, VAL_MASK[MASK_MAX[dm]]):
                                return False

            if not connectivity_prune(domains):
                return False

        return True

    dead = set()

    def choose_edge(domains):
        best = None
        best_key = None

        island_min_sum = [0] * m_islands
        island_room = [0] * m_islands
        for i in range(m_islands):
            for e in incidences[i]:
                dm = domains[e]
                island_min_sum[i] += MASK_MIN[dm]
                island_room[i] += MASK_MAX[dm] - MASK_MIN[dm]

        for e in range(m_edges):
            dm = domains[e]
            if MASK_SIZE[dm] <= 1:
                continue
            a, b = edges[e][0], edges[e][1]
            size = MASK_SIZE[dm]
            impact = len(crossings[e]) * 3 + incident_degrees[a] + incident_degrees[b]
            tight_a = reqs[a] - island_min_sum[a]
            tight_b = reqs[b] - island_min_sum[b]
            room_a = island_room[a]
            room_b = island_room[b]
            urgency = 0
            if room_a > 0:
                urgency += (tight_a * 10) // room_a
            if room_b > 0:
                urgency += (tight_b * 10) // room_b
            key = (size, -urgency, -impact, -(reqs[a] + reqs[b]))
            if best is None or key < best_key:
                best = e
                best_key = key
        return best

    def branch_values(e, domains):
        dm = domains[e]
        vals = list(MASK_VALUES[dm])
        a, b = edges[e][0], edges[e][1]

        def endpoint_pressure(i):
            min_sum = sum(MASK_MIN[domains[x]] for x in incidences[i])
            room = sum(MASK_MAX[domains[x]] - MASK_MIN[domains[x]] for x in incidences[i])
            need = reqs[i] - min_sum
            return need, room

        need_a, room_a = endpoint_pressure(a)
        need_b, room_b = endpoint_pressure(b)
        crossing_heavy = len(crossings[e]) > 0

        prefer_high = False
        if room_a > 0 and need_a * 2 >= room_a:
            prefer_high = True
        if room_b > 0 and need_b * 2 >= room_b:
            prefer_high = True

        if prefer_high:
            order = sorted(vals, reverse=True)
        elif crossing_heavy:
            order = sorted(vals)
        else:
            order = sorted(vals, key=lambda v: (abs(v - 1), v), reverse=True)

        return order

    def search(domains):
        if not propagate(domains):
            return None

        state = tuple(domains)
        if state in dead:
            return None

        if all(is_singleton(dm) for dm in domains):
            if final_valid(domains):
                return domains
            dead.add(state)
            return None

        e = choose_edge(domains)
        if e is None:
            dead.add(state)
            return None

        for v in branch_values(e, domains):
            nd = list(domains)
            nd[e] = VAL_MASK[v]
            sol = search(nd)
            if sol is not None:
                return sol

        dead.add(state)
        return None

    initial_domains = [FULL_MASK] * m_edges
    solution = search(initial_domains)
    if solution is None:
        return "No Solution"

    answer = {}
    for e in range(m_edges):
        v = SINGLETON_VALUE[solution[e]]
        if v > 0:
            a, b = edges[e][0], edges[e][1]
            p1, p2 = coords[a], coords[b]
            if p2 < p1:
                p1, p2 = p2, p1
            answer[(p1, p2)] = v
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 0, None, 0, None], [2, None, None, None, None, None], [None, None, 2, None, None, 2], [2, 2, None, 2, 1, None], [0, None, None, None, None, 0], [None, None, 0, None, 1, None]]}

SLASH = 1
BACKSLASH = 2


class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        parent = self.parent
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        rank = self.rank
        parent = self.parent
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True


def solve(observation):
    data = observation["data"]
    h = len(data)
    if h == 0 or any(len(row) != h for row in data):
        return "No Solution"
    n = h - 1
    if n <= 0:
        return repr([])

    cell_count = n * n
    dot_count = (n + 1) * (n + 1)

    def cell_id(r, c):
        return r * n + c

    def dot_id(r, c):
        return r * (n + 1) + c

    # endpoints[cell][orientation_bit] = (u, v)
    endpoints = [{} for _ in range(cell_count)]
    cell_pos = [None] * cell_count
    for r in range(n):
        for c in range(n):
            cid = cell_id(r, c)
            cell_pos[cid] = (r, c)
            endpoints[cid][SLASH] = (dot_id(r, c + 1), dot_id(r + 1, c))
            endpoints[cid][BACKSLASH] = (dot_id(r, c), dot_id(r + 1, c + 1))

    # For each dot, record which cell/orientation contributes an incident segment to it.
    dot_incident = [[] for _ in range(dot_count)]
    for cid in range(cell_count):
        for bit in (SLASH, BACKSLASH):
            u, v = endpoints[cid][bit]
            dot_incident[u].append((cid, bit))
            dot_incident[v].append((cid, bit))

    # Clue structures:
    # each is (clue_value, cells_tuple, contrib_bits_tuple)
    clues = []
    cell_adj_clues = [[] for _ in range(cell_count)]
    for r in range(n + 1):
        for c in range(n + 1):
            clue = data[r][c]
            if clue is None:
                continue
            did = dot_id(r, c)
            inc = dot_incident[did]
            cells = tuple(x[0] for x in inc)
            bits = tuple(x[1] for x in inc)
            idx = len(clues)
            clues.append((clue, cells, bits))
            for cid in cells:
                cell_adj_clues[cid].append(idx)

    # Fast sanity check: impossible clues by local degree.
    for clue, cells, _bits in clues:
        if clue < 0 or clue > len(cells):
            return "No Solution"

    def propagate(domains):
        # Human-like deduction loop:
        # 1) forbid immediate loop-closing diagonals
        # 2) apply exact-count projection at every clue dot
        while True:
            changed = False

            dsu = DSU(dot_count)

            # Fixed edges must already be acyclic.
            for cid, dom in enumerate(domains):
                if dom == 0:
                    return None
                if dom == SLASH or dom == BACKSLASH:
                    u, v = endpoints[cid][dom]
                    if not dsu.union(u, v):
                        return None

            # Rule: an undecided diagonal cannot be chosen if it would instantly close a loop.
            for cid, dom in enumerate(domains):
                if dom == (SLASH | BACKSLASH):
                    new_dom = dom
                    if new_dom & SLASH:
                        u, v = endpoints[cid][SLASH]
                        if dsu.find(u) == dsu.find(v):
                            new_dom &= ~SLASH
                    if new_dom & BACKSLASH:
                        u, v = endpoints[cid][BACKSLASH]
                        if dsu.find(u) == dsu.find(v):
                            new_dom &= ~BACKSLASH
                    if new_dom == 0:
                        return None
                    if new_dom != dom:
                        domains[cid] = new_dom
                        changed = True

            # Rule: exact local pattern filtering at each clue dot.
            # This subsumes common human deductions for 0/degree, corner/edge effects,
            # saturation, and mixed-domain counting.
            for clue, cells, contrib_bits in clues:
                k = len(cells)
                allowed = [0] * k
                found = False

                # Tiny recursive enumeration: each clue sees at most 4 cells.
                def rec(i, count):
                    nonlocal found
                    if count > clue:
                        return
                    if count + (k - i) < clue:
                        return
                    if i == k:
                        if count == clue:
                            found = True
                        return

                    cid = cells[i]
                    contrib = contrib_bits[i]
                    dom = domains[cid]

                    if dom & SLASH:
                        add = 1 if contrib == SLASH else 0
                        rec(i + 1, count + add)
                        if found:
                            allowed[i] |= SLASH

                    if dom & BACKSLASH:
                        add = 1 if contrib == BACKSLASH else 0
                        before = found
                        rec(i + 1, count + add)
                        if found and not before:
                            pass
                        if found:
                            allowed[i] |= BACKSLASH

                # The above "allowed if found" needs to only mark bits that occur in at least
                # one satisfying completion, so use a proper second recursion.
                found = False
                allowed = [0] * k

                def rec2(i, count, chosen):
                    nonlocal found
                    if count > clue:
                        return
                    if count + (k - i) < clue:
                        return
                    if i == k:
                        if count == clue:
                            found = True
                            for j, bit in enumerate(chosen):
                                allowed[j] |= bit
                        return

                    cid = cells[i]
                    contrib = contrib_bits[i]
                    dom = domains[cid]

                    if dom & SLASH:
                        chosen.append(SLASH)
                        rec2(i + 1, count + (1 if contrib == SLASH else 0), chosen)
                        chosen.pop()

                    if dom & BACKSLASH:
                        chosen.append(BACKSLASH)
                        rec2(i + 1, count + (1 if contrib == BACKSLASH else 0), chosen)
                        chosen.pop()

                rec2(0, 0, [])

                if not found:
                    return None

                for i, cid in enumerate(cells):
                    new_dom = domains[cid] & allowed[i]
                    if new_dom == 0:
                        return None
                    if new_dom != domains[cid]:
                        domains[cid] = new_dom
                        changed = True

            if not changed:
                return domains

    def local_combo_count(clue_idx, domains, forced_cid=None, forced_bit=None):
        clue, cells, contrib_bits = clues[clue_idx]
        k = len(cells)
        total = 0

        def rec(i, count):
            nonlocal total
            if count > clue:
                return
            if count + (k - i) < clue:
                return
            if i == k:
                if count == clue:
                    total += 1
                return

            cid = cells[i]
            contrib = contrib_bits[i]

            if cid == forced_cid:
                bits = forced_bit
            else:
                bits = domains[cid]

            if bits & SLASH:
                rec(i + 1, count + (1 if contrib == SLASH else 0))
            if bits & BACKSLASH:
                rec(i + 1, count + (1 if contrib == BACKSLASH else 0))

        rec(0, 0)
        return total

    def choose_cell(domains):
        # Most constrained by nearby clues first.
        best_cid = None
        best_key = None
        for cid, dom in enumerate(domains):
            if dom == SLASH or dom == BACKSLASH:
                continue
            strength = 0
            for clue_idx in cell_adj_clues[cid]:
                clue, cells, _bits = clues[clue_idx]
                deg = len(cells)
                strength += (4 - deg) + abs(2 * clue - deg) + 1
            r, c = cell_pos[cid]
            key = (-strength, -(len(cell_adj_clues[cid])), abs(r - (n - 1) / 2) + abs(c - (n - 1) / 2), cid)
            if best_key is None or key < best_key:
                best_key = key
                best_cid = cid
        return best_cid

    def branch_order(cid, domains):
        bits = []
        if domains[cid] & SLASH:
            bits.append(SLASH)
        if domains[cid] & BACKSLASH:
            bits.append(BACKSLASH)

        scored = []
        for bit in bits:
            support = 0
            impossible = False
            for clue_idx in cell_adj_clues[cid]:
                cnt = local_combo_count(clue_idx, domains, cid, bit)
                if cnt == 0:
                    impossible = True
                    support = -1
                    break
                support += cnt
            scored.append((support, bit, impossible))

        scored.sort(key=lambda x: (x[2], x[0]))
        return [bit for _support, bit, _impossible in scored]

    def complete_and_valid(domains):
        for dom in domains:
            if dom != SLASH and dom != BACKSLASH:
                return False

        dsu = DSU(dot_count)
        for cid, dom in enumerate(domains):
            u, v = endpoints[cid][dom]
            if not dsu.union(u, v):
                return False

        for clue, cells, contrib_bits in clues:
            cnt = 0
            for cid, bit in zip(cells, contrib_bits):
                if domains[cid] == bit:
                    cnt += 1
            if cnt != clue:
                return False

        return True

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        cid = choose_cell(domains)
        if cid is None:
            if complete_and_valid(domains):
                return domains
            return None

        for bit in branch_order(cid, domains):
            new_domains = domains[:]
            new_domains[cid] = bit
            result = search(new_domains)
            if result is not None:
                return result
        return None

    initial_domains = [SLASH | BACKSLASH] * cell_count
    result = search(initial_domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            cid = cell_id(r, c)
            row.append("/" if result[cid] == SLASH else "\\")
        grid.append(row)
    return repr(grid)


