# General Takuzu / Binairo solver using aggressive deduction plus constrained search.

def solve(observation):
    data = observation.get('data')
    if not data or not isinstance(data, list):
        return "No Solution"

    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or n % 2 != 0:
        return "No Solution"

    enc = {'W': 0, 'B': 1, None: None}
    dec = {0: 'W', 1: 'B'}

    try:
        grid = [[enc[cell] for cell in row] for row in data]
    except Exception:
        return "No Solution"

    patterns = generate_valid_patterns(n)
    if not patterns:
        return "No Solution"

    failed = set()
    result = search(grid, patterns, failed)

    if result is None:
        return "No Solution"
    return [[dec[v] for v in row] for row in result]


def generate_valid_patterns(n):
    half = n // 2
    out = []

    def dfs(pos, ones, seq):
        zeros = pos - ones
        rem = n - pos
        need_ones = half - ones
        need_zeros = half - zeros

        if need_ones < 0 or need_zeros < 0 or need_ones > rem or need_zeros > rem:
            return

        if pos == n:
            if ones == half:
                out.append(tuple(seq))
            return

        for v in (0, 1):
            if v == 1 and ones == half:
                continue
            if v == 0 and zeros == half:
                continue
            if pos >= 2 and seq[-1] == v and seq[-2] == v:
                continue
            seq.append(v)
            dfs(pos + 1, ones + (1 if v == 1 else 0), seq)
            seq.pop()

    dfs(0, 0, [])
    return out


def to_key(grid):
    return tuple(tuple(row) for row in grid)


def get_col(grid, j):
    return [grid[i][j] for i in range(len(grid))]


def set_cell(grid, r, c, v):
    cur = grid[r][c]
    if cur is None:
        grid[r][c] = v
        return True
    if cur != v:
        raise ValueError("Contradiction")
    return False


def deduce_line(line):
    n = len(line)
    half = n // 2
    updates = {}

    def force(idx, val):
        cur = line[idx]
        if cur is not None:
            if cur != val:
                raise ValueError("Contradiction")
            return
        prev = updates.get(idx)
        if prev is not None and prev != val:
            raise ValueError("Contradiction")
        updates[idx] = val

    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]

        if a is not None and b is not None and a == b:
            if c is None:
                force(i + 2, 1 - a)
            elif c == a:
                raise ValueError("Contradiction")

        if b is not None and c is not None and b == c:
            if a is None:
                force(i, 1 - b)
            elif a == b:
                raise ValueError("Contradiction")

        if a is not None and c is not None and a == c:
            if b is None:
                force(i + 1, 1 - a)
            elif b == a:
                raise ValueError("Contradiction")

    ones = sum(v == 1 for v in line)
    zeros = sum(v == 0 for v in line)
    unknowns = line.count(None)

    if ones > half or zeros > half:
        raise ValueError("Contradiction")

    if unknowns:
        if ones == half:
            for i, v in enumerate(line):
                if v is None:
                    force(i, 0)
        elif zeros == half:
            for i, v in enumerate(line):
                if v is None:
                    force(i, 1)

    return updates


def line_matches(pattern, line):
    for a, b in zip(pattern, line):
        if b is not None and a != b:
            return False
    return True


def reduce_unique_candidate_sets(cands_list):
    changed = False
    while True:
        owner = {}
        for idx, cands in enumerate(cands_list):
            if len(cands) == 1:
                p = cands[0]
                if p in owner and owner[p] != idx:
                    raise ValueError("Contradiction")
                owner[p] = idx

        single_patterns = set(owner)
        local_change = False
        if single_patterns:
            for idx, cands in enumerate(cands_list):
                if len(cands) > 1:
                    new_cands = [p for p in cands if p not in single_patterns]
                    if not new_cands:
                        raise ValueError("Contradiction")
                    if len(new_cands) != len(cands):
                        cands_list[idx] = new_cands
                        changed = True
                        local_change = True
        if not local_change:
            break
    return changed


def propagate(grid, patterns):
    n = len(grid)

    while True:
        progress = False

        try:
            # Human-like local deductions on rows.
            for i in range(n):
                upd = deduce_line(grid[i])
                for j, v in upd.items():
                    if set_cell(grid, i, j, v):
                        progress = True

            # Human-like local deductions on columns.
            for j in range(n):
                col = get_col(grid, j)
                upd = deduce_line(col)
                for i, v in upd.items():
                    if set_cell(grid, i, j, v):
                        progress = True
        except ValueError:
            return None

        # Candidate lines consistent with current partial grid.
        row_cands = []
        col_cands = []

        for i in range(n):
            cands = [p for p in patterns if line_matches(p, grid[i])]
            if not cands:
                return None
            row_cands.append(cands)

        for j in range(n):
            col = get_col(grid, j)
            cands = [p for p in patterns if line_matches(p, col)]
            if not cands:
                return None
            col_cands.append(cands)

        # Uniqueness propagation: once a line is forced to one full pattern,
        # no other line may use the same full pattern.
        try:
            if reduce_unique_candidate_sets(row_cands):
                progress = True
            if reduce_unique_candidate_sets(col_cands):
                progress = True
        except ValueError:
            return None

        # Candidate intersection on rows.
        try:
            for i, cands in enumerate(row_cands):
                if len(cands) == 1:
                    pat = cands[0]
                    for j, v in enumerate(pat):
                        if set_cell(grid, i, j, v):
                            progress = True
                else:
                    for j in range(n):
                        first = cands[0][j]
                        if all(p[j] == first for p in cands[1:]):
                            if set_cell(grid, i, j, first):
                                progress = True

            # Candidate intersection on columns.
            for j, cands in enumerate(col_cands):
                if len(cands) == 1:
                    pat = cands[0]
                    for i, v in enumerate(pat):
                        if set_cell(grid, i, j, v):
                            progress = True
                else:
                    for i in range(n):
                        first = cands[0][i]
                        if all(p[i] == first for p in cands[1:]):
                            if set_cell(grid, i, j, first):
                                progress = True
        except ValueError:
            return None

        # Safety checks on fully known duplicated rows/cols.
        if not check_partial_validity(grid):
            return None

        if not progress:
            return grid, row_cands, col_cands


def check_partial_validity(grid):
    n = len(grid)
    half = n // 2

    # Rows
    complete_rows = set()
    for row in grid:
        ones = sum(v == 1 for v in row)
        zeros = sum(v == 0 for v in row)
        if ones > half or zeros > half:
            return False
        for i in range(n - 2):
            a, b, c = row[i], row[i + 1], row[i + 2]
            if a is not None and b is not None and c is not None and a == b == c:
                return False
        if None not in row:
            t = tuple(row)
            if t in complete_rows:
                return False
            complete_rows.add(t)

    # Columns
    complete_cols = set()
    for j in range(n):
        col = get_col(grid, j)
        ones = sum(v == 1 for v in col)
        zeros = sum(v == 0 for v in col)
        if ones > half or zeros > half:
            return False
        for i in range(n - 2):
            a, b, c = col[i], col[i + 1], col[i + 2]
            if a is not None and b is not None and c is not None and a == b == c:
                return False
        if None not in col:
            t = tuple(col)
            if t in complete_cols:
                return False
            complete_cols.add(t)

    return True


def is_complete(grid):
    return all(v is not None for row in grid for v in row)


def validate_full(grid):
    n = len(grid)
    half = n // 2

    rows = set()
    cols = set()

    for row in grid:
        if row.count(1) != half or row.count(0) != half:
            return False
        for i in range(n - 2):
            if row[i] == row[i + 1] == row[i + 2]:
                return False
        t = tuple(row)
        if t in rows:
            return False
        rows.add(t)

    for j in range(n):
        col = tuple(grid[i][j] for i in range(n))
        if col.count(1) != half or col.count(0) != half:
            return False
        for i in range(n - 2):
            if col[i] == col[i + 1] == col[i + 2]:
                return False
        if col in cols:
            return False
        cols.add(col)

    return True


def choose_branch(grid, row_cands, col_cands):
    n = len(grid)
    best = None

    for i, cands in enumerate(row_cands):
        if len(cands) > 1:
            unknowns = sum(v is None for v in grid[i])
            score = (len(cands), unknowns, 0, i)
            if best is None or score < best[0]:
                best = (score, 'row', i, cands)

    for j, cands in enumerate(col_cands):
        if len(cands) > 1:
            col = get_col(grid, j)
            unknowns = sum(v is None for v in col)
            score = (len(cands), unknowns, 1, j)
            if best is None or score < best[0]:
                best = (score, 'col', j, cands)

    return None if best is None else (best[1], best[2], best[3])


def assign_line(grid, kind, idx, pattern):
    n = len(grid)
    new_grid = [row[:] for row in grid]
    if kind == 'row':
        for j in range(n):
            set_cell(new_grid, idx, j, pattern[j])
    else:
        for i in range(n):
            set_cell(new_grid, i, idx, pattern[i])
    return new_grid


def search(grid, patterns, failed):
    key0 = to_key(grid)
    if key0 in failed:
        return None

    propagated = propagate([row[:] for row in grid], patterns)
    if propagated is None:
        failed.add(key0)
        return None

    grid, row_cands, col_cands = propagated
    key = to_key(grid)
    if key in failed:
        return None

    if is_complete(grid):
        if validate_full(grid):
            return grid
        failed.add(key)
        return None

    branch = choose_branch(grid, row_cands, col_cands)
    if branch is None:
        failed.add(key)
        return None

    kind, idx, cands = branch

    for pat in cands:
        try:
            new_grid = assign_line(grid, kind, idx, pat)
        except ValueError:
            continue
        result = search(new_grid, patterns, failed)
        if result is not None:
            return result

    failed.add(key)
    return None


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 4, 4, None, None, 1, None], [None, None, None, None, 3, None, None], [None, 9, 7, 4, 3, 5, None], [None, 6, None, 2, None, None, 5], [3, None, 5, None, None, 4, None], [None, None, None, None, 1, None, None], [3, None, None, 2, None, None, 1]]}

from collections import defaultdict

UNKNOWN = -1
WHITE = 0
BLACK = 1


class Solver:
    def __init__(self, observation):
        self.data = observation['data']
        self.n = len(self.data)
        self.m = len(self.data[0]) if self.n else 0
        self.var_count = self.n * self.m

        self.constraints = []
        self.var_to_constraints = [[] for _ in range(self.var_count)]
        self.involved = set()

        for r in range(self.n):
            for c in range(self.m):
                val = self.data[r][c]
                if val is None:
                    continue
                cells = []
                for rr in range(max(0, r - 1), min(self.n, r + 2)):
                    for cc in range(max(0, c - 1), min(self.m, c + 2)):
                        v = self.idx(rr, cc)
                        cells.append(v)
                        self.involved.add(v)
                cid = len(self.constraints)
                self.constraints.append((tuple(cells), int(val)))
                for v in cells:
                    self.var_to_constraints[v].append(cid)

        self.active_vars = sorted(self.involved)
        self.unconstrained_vars = [v for v in range(self.var_count) if v not in self.involved]
        self.memo_unsat = set()

    def idx(self, r, c):
        return r * self.m + c

    def rc(self, v):
        return divmod(v, self.m)

    def build_residual_map(self, assn):
        residual_map = {}
        for vars_, target in self.constraints:
            black_count = 0
            unknowns = []
            for v in vars_:
                a = assn[v]
                if a == BLACK:
                    black_count += 1
                elif a == UNKNOWN:
                    unknowns.append(v)
            remain = target - black_count
            size = len(unknowns)
            if remain < 0 or remain > size:
                return None
            if size == 0:
                continue
            key = frozenset(unknowns)
            prev = residual_map.get(key)
            if prev is None:
                residual_map[key] = remain
            elif prev != remain:
                return None
        return residual_map

    def assign(self, assn, v, val):
        cur = assn[v]
        if cur == UNKNOWN:
            assn[v] = val
            return True
        return cur == val

    def basic_propagate(self, assn):
        while True:
            changed = False
            residual_map = self.build_residual_map(assn)
            if residual_map is None:
                return None

            all_map = dict(residual_map)

            # Pairwise subset-difference closure:
            # if sum(A)=a and sum(B)=b with A subset B, then sum(B-A)=b-a.
            made_new = True
            while made_new:
                made_new = False
                items = sorted(all_map.items(), key=lambda kv: (len(kv[0]), tuple(sorted(kv[0]))))
                L = len(items)
                for i in range(L):
                    A, a = items[i]
                    lenA = len(A)
                    for j in range(i + 1, L):
                        B, b = items[j]
                        if lenA > len(B):
                            continue
                        if not A.issubset(B):
                            continue
                        D = B - A
                        need = b - a
                        if need < 0 or need > len(D):
                            return None
                        if not D:
                            if need != 0:
                                return None
                            continue
                        prev = all_map.get(D)
                        if prev is None:
                            all_map[D] = need
                            made_new = True
                        elif prev != need:
                            return None

            # Direct assignments from exact-sum constraints.
            for cells, need in all_map.items():
                size = len(cells)
                if need < 0 or need > size:
                    return None
                if size == 0:
                    if need != 0:
                        return None
                    continue
                if need == 0:
                    for v in cells:
                        if assn[v] == UNKNOWN:
                            assn[v] = WHITE
                            changed = True
                        elif assn[v] != WHITE:
                            return None
                elif need == size:
                    for v in cells:
                        if assn[v] == UNKNOWN:
                            assn[v] = BLACK
                            changed = True
                        elif assn[v] != BLACK:
                            return None
                elif size == 1:
                    v = next(iter(cells))
                    val = BLACK if need == 1 else WHITE
                    if assn[v] == UNKNOWN:
                        assn[v] = val
                        changed = True
                    elif assn[v] != val:
                        return None

            if not changed:
                return assn

    def candidate_vars_for_probe(self, assn):
        unknowns = [v for v in self.active_vars if assn[v] == UNKNOWN]
        if not unknowns:
            return []
        scored = []
        for v in unknowns:
            degree = len(self.var_to_constraints[v])
            min_scope = 10**9
            pressure = 0
            for cid in self.var_to_constraints[v]:
                vars_, target = self.constraints[cid]
                black_count = 0
                size = 0
                for u in vars_:
                    a = assn[u]
                    if a == BLACK:
                        black_count += 1
                    elif a == UNKNOWN:
                        size += 1
                remain = target - black_count
                if size > 0:
                    min_scope = min(min_scope, size)
                    pressure += abs(2 * remain - size)
            scored.append((min_scope, -degree, -pressure, v))
        scored.sort()
        if len(scored) <= 24:
            return [v for _, _, _, v in scored]
        return [v for _, _, _, v in scored[:8]]

    def probe_forced(self, assn):
        progress = False
        for v in self.candidate_vars_for_probe(assn):
            if assn[v] != UNKNOWN:
                continue

            ok0 = False
            ok1 = False

            test0 = assn[:]
            test0[v] = WHITE
            if self.basic_propagate(test0) is not None:
                ok0 = True

            test1 = assn[:]
            test1[v] = BLACK
            if self.basic_propagate(test1) is not None:
                ok1 = True

            if not ok0 and not ok1:
                return None
            if ok0 and ok1:
                continue

            forced_val = WHITE if ok0 else BLACK
            if assn[v] == UNKNOWN:
                assn[v] = forced_val
                progress = True
            elif assn[v] != forced_val:
                return None

        return progress

    def propagate(self, assn):
        while True:
            assn = self.basic_propagate(assn)
            if assn is None:
                return None
            forced = self.probe_forced(assn)
            if forced is None:
                return None
            if not forced:
                return assn

    def select_var(self, assn):
        best = None
        best_key = None
        best_ratio = 0.5

        for v in self.active_vars:
            if assn[v] != UNKNOWN:
                continue

            degree = 0
            min_scope = 10**9
            pressure = 0
            ratio_sum = 0.0
            ratio_w = 0

            for cid in self.var_to_constraints[v]:
                vars_, target = self.constraints[cid]
                black_count = 0
                size = 0
                for u in vars_:
                    a = assn[u]
                    if a == BLACK:
                        black_count += 1
                    elif a == UNKNOWN:
                        size += 1
                remain = target - black_count
                if size == 0:
                    continue
                degree += 1
                min_scope = min(min_scope, size)
                pressure += abs(2 * remain - size)
                ratio_sum += remain / size
                ratio_w += 1

            avg_ratio = ratio_sum / ratio_w if ratio_w else 0.5
            key = (min_scope, -degree, -pressure)

            if best_key is None or key < best_key:
                best_key = key
                best = v
                best_ratio = avg_ratio

        return best, best_ratio

    def search(self, assn):
        assn = self.propagate(assn)
        if assn is None:
            return None

        key = tuple(assn[v] for v in self.active_vars)
        if key in self.memo_unsat:
            return None

        unresolved = False
        for v in self.active_vars:
            if assn[v] == UNKNOWN:
                unresolved = True
                break

        if not unresolved:
            final_assn = assn[:]
            for v in range(self.var_count):
                if final_assn[v] == UNKNOWN:
                    final_assn[v] = WHITE
            if self.verify(final_assn):
                return final_assn
            self.memo_unsat.add(key)
            return None

        v, ratio = self.select_var(assn)
        if v is None:
            self.memo_unsat.add(key)
            return None

        order = (BLACK, WHITE) if ratio >= 0.5 else (WHITE, BLACK)
        for val in order:
            nxt = assn[:]
            nxt[v] = val
            res = self.search(nxt)
            if res is not None:
                return res

        self.memo_unsat.add(key)
        return None

    def verify(self, assn):
        for vars_, target in self.constraints:
            s = 0
            for v in vars_:
                if assn[v] == BLACK:
                    s += 1
            if s != target:
                return False
        return True

    def format_answer(self, assn):
        grid = []
        for r in range(self.n):
            row = []
            for c in range(self.m):
                v = self.idx(r, c)
                row.append('B' if assn[v] == BLACK else None)
            grid.append(row)
        return grid


def solve(observation):
    solver = Solver(observation)
    start = [UNKNOWN] * solver.var_count
    result = solver.search(start)
    if result is None:
        return "No Solution"
    return repr(solver.format_answer(result))


