OBSERVATION = {'U': [0, 0, 0, 0], 'D': [0, 0, 0, 0], 'L': [0, 0, 2, 0], 'R': [0, 1, 0, 3]}

from itertools import permutations


def solve(observation):
    # General skyscraper solver using:
    # 1) permutation filtering by clues,
    # 2) cross-propagation between row/column candidates,
    # 3) Latin-square deductions on cell domains,
    # 4) small, highly-pruned search only when deduction stalls.

    def norm_side(side):
        return [0 if x in (None, 0) else int(x) for x in side]

    try:
        U = norm_side(observation['U'])
        D = norm_side(observation['D'])
        L = norm_side(observation['L'])
        R = norm_side(observation['R'])
    except Exception:
        return "No Solution"

    N = len(U)
    if not (len(D) == len(L) == len(R) == N and N > 0):
        return "No Solution"

    for side in (U, D, L, R):
        for x in side:
            if x < 0 or x > N:
                return "No Solution"

    ALL = (1 << N) - 1
    VALUE_BITS = [1 << i for i in range(N)]

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def mask_to_value(mask):
        return mask.bit_length()

    def visible_count(seq):
        seen = 0
        best = 0
        for v in seq:
            if v > best:
                best = v
                seen += 1
        return seen

    def clue_ok(clue, count):
        return clue == 0 or clue == count

    # Precompute all line permutations and their visibility signatures.
    perms = list(permutations(range(1, N + 1)))
    P = len(perms)
    all_perm_ids = list(range(P))

    left_vis = [0] * P
    right_vis = [0] * P
    pos_bits = [None] * P

    by_left = {}
    by_right = {}
    by_pair = {}

    for idx, p in enumerate(perms):
        lv = visible_count(p)
        rv = visible_count(reversed(p))
        left_vis[idx] = lv
        right_vis[idx] = rv
        bits = tuple(1 << (v - 1) for v in p)
        pos_bits[idx] = bits

        by_left.setdefault(lv, []).append(idx)
        by_right.setdefault(rv, []).append(idx)
        by_pair.setdefault((lv, rv), []).append(idx)

    def initial_line_candidates(front_clue, back_clue):
        if front_clue and back_clue:
            return by_pair.get((front_clue, back_clue), []).copy()
        if front_clue:
            return by_left.get(front_clue, []).copy()
        if back_clue:
            return by_right.get(back_clue, []).copy()
        return all_perm_ids.copy()

    row_cands = [initial_line_candidates(L[r], R[r]) for r in range(N)]
    col_cands = [initial_line_candidates(U[c], D[c]) for c in range(N)]

    if any(not c for c in row_cands) or any(not c for c in col_cands):
        return "No Solution"

    cell_masks = [[ALL for _ in range(N)] for _ in range(N)]

    def reduce_latin_masks(cell_masks):
        changed = False

        # Row-wise Latin deductions.
        for r in range(N):
            fixed = 0
            for c in range(N):
                m = cell_masks[r][c]
                if is_single(m):
                    if fixed & m:
                        return False, changed
                    fixed |= m

            for c in range(N):
                m = cell_masks[r][c]
                if not is_single(m):
                    nm = m & ~fixed
                    if nm == 0:
                        return False, changed
                    if nm != m:
                        cell_masks[r][c] = nm
                        changed = True

            for bit in VALUE_BITS:
                pos = -1
                count = 0
                for c in range(N):
                    if cell_masks[r][c] & bit:
                        pos = c
                        count += 1
                if count == 0:
                    return False, changed
                if count == 1 and cell_masks[r][pos] != bit:
                    cell_masks[r][pos] = bit
                    changed = True

        # Column-wise Latin deductions.
        for c in range(N):
            fixed = 0
            for r in range(N):
                m = cell_masks[r][c]
                if is_single(m):
                    if fixed & m:
                        return False, changed
                    fixed |= m

            for r in range(N):
                m = cell_masks[r][c]
                if not is_single(m):
                    nm = m & ~fixed
                    if nm == 0:
                        return False, changed
                    if nm != m:
                        cell_masks[r][c] = nm
                        changed = True

            for bit in VALUE_BITS:
                pos = -1
                count = 0
                for r in range(N):
                    if cell_masks[r][c] & bit:
                        pos = r
                        count += 1
                if count == 0:
                    return False, changed
                if count == 1 and cell_masks[pos][c] != bit:
                    cell_masks[pos][c] = bit
                    changed = True

        return True, changed

    def propagate(row_cands, col_cands, cell_masks):
        while True:
            changed = False

            # Prune row candidates against current cell masks.
            for r in range(N):
                current = row_cands[r]
                new = []
                for idx in current:
                    bits = pos_bits[idx]
                    ok = True
                    for c in range(N):
                        if not (bits[c] & cell_masks[r][c]):
                            ok = False
                            break
                    if ok:
                        new.append(idx)
                if not new:
                    return False
                if len(new) != len(current):
                    row_cands[r] = new
                    changed = True

            # Prune column candidates against current cell masks.
            for c in range(N):
                current = col_cands[c]
                new = []
                for idx in current:
                    bits = pos_bits[idx]
                    ok = True
                    for r in range(N):
                        if not (bits[r] & cell_masks[r][c]):
                            ok = False
                            break
                    if ok:
                        new.append(idx)
                if not new:
                    return False
                if len(new) != len(current):
                    col_cands[c] = new
                    changed = True

            # Derive per-cell allowances from row candidates.
            row_allow = [[0] * N for _ in range(N)]
            for r in range(N):
                unions = [0] * N
                for idx in row_cands[r]:
                    bits = pos_bits[idx]
                    for c in range(N):
                        unions[c] |= bits[c]
                for c in range(N):
                    if unions[c] == 0:
                        return False
                    row_allow[r][c] = unions[c]

            # Derive per-cell allowances from column candidates.
            col_allow = [[0] * N for _ in range(N)]
            for c in range(N):
                unions = [0] * N
                for idx in col_cands[c]:
                    bits = pos_bits[idx]
                    for r in range(N):
                        unions[r] |= bits[r]
                for r in range(N):
                    if unions[r] == 0:
                        return False
                    col_allow[c][r] = unions[r]

            # Intersect current domains with line-derived allowances.
            for r in range(N):
                for c in range(N):
                    nm = cell_masks[r][c] & row_allow[r][c] & col_allow[c][r]
                    if nm == 0:
                        return False
                    if nm != cell_masks[r][c]:
                        cell_masks[r][c] = nm
                        changed = True

            ok, latin_changed = reduce_latin_masks(cell_masks)
            if not ok:
                return False
            if latin_changed:
                changed = True

            if not changed:
                return True

    def grid_from_rows(row_cands):
        return [list(perms[cands[0]]) for cands in row_cands]

    def grid_from_masks(cell_masks):
        return [[mask_to_value(cell_masks[r][c]) for c in range(N)] for r in range(N)]

    def verify(grid):
        target = tuple(range(1, N + 1))

        for r in range(N):
            if tuple(sorted(grid[r])) != target:
                return False
            if not clue_ok(L[r], visible_count(grid[r])):
                return False
            if not clue_ok(R[r], visible_count(reversed(grid[r]))):
                return False

        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if tuple(sorted(col)) != target:
                return False
            if not clue_ok(U[c], visible_count(col)):
                return False
            if not clue_ok(D[c], visible_count(reversed(col))):
                return False

        return True

    def state_solved(row_cands, col_cands, cell_masks):
        if all(len(c) == 1 for c in row_cands):
            grid = grid_from_rows(row_cands)
            if verify(grid):
                return grid
        if all(is_single(cell_masks[r][c]) for r in range(N) for c in range(N)):
            grid = grid_from_masks(cell_masks)
            if verify(grid):
                return grid
        return None

    def choose_branch_line(row_cands, col_cands):
        best_kind = None
        best_idx = -1
        best_len = 10**9

        for r in range(N):
            k = len(row_cands[r])
            if 1 < k < best_len:
                best_kind = 'row'
                best_idx = r
                best_len = k

        for c in range(N):
            k = len(col_cands[c])
            if 1 < k < best_len:
                best_kind = 'col'
                best_idx = c
                best_len = k

        return best_kind, best_idx

    def candidate_order(kind, idx, row_cands, col_cands):
        # Try more constraining candidates first.
        if kind == 'row':
            items = row_cands[idx]
            scored = []
            for pid in items:
                p = perms[pid]
                score = 0
                for c, v in enumerate(p):
                    bit = 1 << (v - 1)
                    compat = 0
                    for qid in col_cands[c]:
                        if pos_bits[qid][idx] & bit:
                            compat += 1
                    score += compat
                scored.append((score, pid))
            scored.sort()
            return [pid for _, pid in scored]

        items = col_cands[idx]
        scored = []
        for pid in items:
            p = perms[pid]
            score = 0
            for r, v in enumerate(p):
                bit = 1 << (v - 1)
                compat = 0
                for qid in row_cands[r]:
                    if pos_bits[qid][idx] & bit:
                        compat += 1
                score += compat
            scored.append((score, pid))
        scored.sort()
        return [pid for _, pid in scored]

    def search(row_cands, col_cands, cell_masks):
        if not propagate(row_cands, col_cands, cell_masks):
            return None

        solved = state_solved(row_cands, col_cands, cell_masks)
        if solved is not None:
            return solved

        kind, idx = choose_branch_line(row_cands, col_cands)
        if kind is None:
            return None

        for pid in candidate_order(kind, idx, row_cands, col_cands):
            new_rows = [lst[:] for lst in row_cands]
            new_cols = [lst[:] for lst in col_cands]
            new_masks = [row[:] for row in cell_masks]

            if kind == 'row':
                new_rows[idx] = [pid]
                bits = pos_bits[pid]
                for c in range(N):
                    nm = new_masks[idx][c] & bits[c]
                    if nm == 0:
                        break
                    new_masks[idx][c] = nm
                else:
                    ans = search(new_rows, new_cols, new_masks)
                    if ans is not None:
                        return ans
            else:
                new_cols[idx] = [pid]
                bits = pos_bits[pid]
                for r in range(N):
                    nm = new_masks[r][idx] & bits[r]
                    if nm == 0:
                        break
                    new_masks[r][idx] = nm
                else:
                    ans = search(new_rows, new_cols, new_masks)
                    if ans is not None:
                        return ans

        return None

    result = search(row_cands, col_cands, cell_masks)
    return str(result) if result is not None else "No Solution"


