from collections import deque
from itertools import combinations
from math import comb


class State:
    __slots__ = ("cell", "lit", "supp", "hbulb", "vbulb", "cbulb", "cundec")

    def __init__(self, W, H, V, C, initial_supp, initial_cundec):
        self.cell = [-1] * W          # -1 undecided, 0 no bulb, 1 bulb
        self.lit = [0] * W            # number of fixed bulbs illuminating each white cell
        self.supp = initial_supp[:]   # number of remaining possible bulb positions that can light each cell
        self.hbulb = [0] * H          # whether a horizontal segment already contains a bulb
        self.vbulb = [0] * V          # whether a vertical segment already contains a bulb
        self.cbulb = [0] * C          # fixed bulbs adjacent to numbered black cell
        self.cundec = initial_cundec[:]  # undecided adjacent cells for numbered black cell

    def clone(self):
        other = object.__new__(State)
        other.cell = self.cell[:]
        other.lit = self.lit[:]
        other.supp = self.supp[:]
        other.hbulb = self.hbulb[:]
        other.vbulb = self.vbulb[:]
        other.cbulb = self.cbulb[:]
        other.cundec = self.cundec[:]
        return other


class AkariSolver:
    def __init__(self, data):
        self.data = data
        self.N = len(data)
        self.white_coords = []
        self.idx_of = {}
        self.black_number = {}

        for r in range(self.N):
            if len(data[r]) != self.N:
                raise ValueError("Board must be square")
            for c in range(self.N):
                val = data[r][c]
                if val is None:
                    idx = len(self.white_coords)
                    self.white_coords.append((r, c))
                    self.idx_of[(r, c)] = idx
                else:
                    if val != -1:
                        self.black_number[(r, c)] = val

        self.W = len(self.white_coords)
        self._build_segments()
        self._build_visibility()
        self._build_number_constraints()

        self.initial_supp = [len(self.supporters[i]) for i in range(self.W)]
        self.initial_cundec = [len(adj) for adj in self.cadj]

    def _is_black(self, r, c):
        return self.data[r][c] is not None

    def _build_segments(self):
        self.hsegs = []
        self.vsegs = []
        self.hseg_of = [-1] * self.W
        self.vseg_of = [-1] * self.W

        for r in range(self.N):
            c = 0
            while c < self.N:
                if self._is_black(r, c):
                    c += 1
                    continue
                seg = []
                while c < self.N and not self._is_black(r, c):
                    seg.append(self.idx_of[(r, c)])
                    c += 1
                seg_id = len(self.hsegs)
                self.hsegs.append(tuple(seg))
                for idx in seg:
                    self.hseg_of[idx] = seg_id

        for c in range(self.N):
            r = 0
            while r < self.N:
                if self._is_black(r, c):
                    r += 1
                    continue
                seg = []
                while r < self.N and not self._is_black(r, c):
                    seg.append(self.idx_of[(r, c)])
                    r += 1
                seg_id = len(self.vsegs)
                self.vsegs.append(tuple(seg))
                for idx in seg:
                    self.vseg_of[idx] = seg_id

        self.H = len(self.hsegs)
        self.V = len(self.vsegs)

    def _build_visibility(self):
        self.visible = [None] * self.W
        self.supporters = [None] * self.W

        for idx in range(self.W):
            seen = set(self.hsegs[self.hseg_of[idx]])
            seen.update(self.vsegs[self.vseg_of[idx]])
            vis = tuple(sorted(seen))
            self.visible[idx] = vis
            self.supporters[idx] = vis

    def _build_number_constraints(self):
        self.cneed = []
        self.cadj = []
        self.cell_constraints = [[] for _ in range(self.W)]

        for (r, c), need in sorted(self.black_number.items()):
            adj = []
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < self.N and 0 <= cc < self.N and self.data[rr][cc] is None:
                    adj.append(self.idx_of[(rr, cc)])
            cid = len(self.cneed)
            self.cneed.append(need)
            self.cadj.append(tuple(adj))
            for idx in adj:
                self.cell_constraints[idx].append(cid)

        self.C = len(self.cneed)
        self.cell_constraints = [tuple(x) for x in self.cell_constraints]

    def initial_state(self):
        st = State(self.W, self.H, self.V, self.C, self.initial_supp, self.initial_cundec)
        if self.propagate(st, []):
            return st
        return None

    def _remaining_supporter(self, st, target):
        for idx in self.supporters[target]:
            if st.cell[idx] != 0:
                return idx
        return None

    def propagate(self, st, actions):
        q = deque()
        pending = [2] * self.W

        def enqueue(idx, val):
            cur = st.cell[idx]
            if cur == val:
                return True
            if cur != -1 and cur != val:
                return False
            pv = pending[idx]
            if pv == 2:
                pending[idx] = val
                q.append(idx)
            elif pv != val:
                return False
            return True

        def apply_constraint(cid):
            need = self.cneed[cid]
            bulbs = st.cbulb[cid]
            undec = st.cundec[cid]

            if bulbs > need or bulbs + undec < need:
                return False

            if undec:
                if bulbs == need:
                    for idx in self.cadj[cid]:
                        if st.cell[idx] == -1 and not enqueue(idx, 0):
                            return False
                elif bulbs + undec == need:
                    for idx in self.cadj[cid]:
                        if st.cell[idx] == -1 and not enqueue(idx, 1):
                            return False
            return True

        for idx, val in actions:
            if not enqueue(idx, val):
                return False

        for cid in range(self.C):
            if not apply_constraint(cid):
                return False

        for target in range(self.W):
            if st.supp[target] == 0:
                return False
            if st.lit[target] == 0 and st.supp[target] == 1:
                rem = self._remaining_supporter(st, target)
                if rem is None or not enqueue(rem, 1):
                    return False

        while q:
            idx = q.popleft()
            val = pending[idx]
            pending[idx] = 2

            if st.cell[idx] == val:
                continue
            if st.cell[idx] != -1:
                return False

            if val == 0:
                st.cell[idx] = 0

                for cid in self.cell_constraints[idx]:
                    st.cundec[cid] -= 1
                    if not apply_constraint(cid):
                        return False

                for target in self.visible[idx]:
                    st.supp[target] -= 1
                    if st.supp[target] <= 0:
                        return False
                    if st.lit[target] == 0 and st.supp[target] == 1:
                        rem = self._remaining_supporter(st, target)
                        if rem is None or not enqueue(rem, 1):
                            return False

            else:
                st.cell[idx] = 1

                for cid in self.cell_constraints[idx]:
                    st.cbulb[cid] += 1
                    st.cundec[cid] -= 1
                    if not apply_constraint(cid):
                        return False

                h = self.hseg_of[idx]
                if st.hbulb[h]:
                    return False
                st.hbulb[h] = 1
                for j in self.hsegs[h]:
                    if j != idx and not enqueue(j, 0):
                        return False

                v = self.vseg_of[idx]
                if st.vbulb[v]:
                    return False
                st.vbulb[v] = 1
                for j in self.vsegs[v]:
                    if j != idx and not enqueue(j, 0):
                        return False

                for target in self.visible[idx]:
                    st.lit[target] += 1

        for cid in range(self.C):
            need = self.cneed[cid]
            if st.cbulb[cid] > need or st.cbulb[cid] + st.cundec[cid] < need:
                return False

        for target in range(self.W):
            if st.lit[target] == 0 and st.supp[target] == 0:
                return False

        return True

    def is_solved(self, st):
        for cid in range(self.C):
            if st.cbulb[cid] != self.cneed[cid]:
                return False
        for target in range(self.W):
            if st.lit[target] == 0:
                return False
        return True

    def cell_branch_score(self, st, idx):
        benefit = 0
        for t in self.visible[idx]:
            if st.lit[t] == 0:
                benefit += 1
        pressure = 0
        for cid in self.cell_constraints[idx]:
            rem = self.cneed[cid] - st.cbulb[cid]
            if rem > 0:
                pressure += rem
        return benefit * 4 + pressure * 7

    def choose_branches(self, st):
        best_kind = None
        best_key = None
        best_payload = None

        for cid in range(self.C):
            rem = self.cneed[cid] - st.cbulb[cid]
            if rem <= 0:
                continue
            undec = [idx for idx in self.cadj[cid] if st.cell[idx] == -1]
            if not undec:
                continue
            if rem == len(undec):
                continue
            count = comb(len(undec), rem)
            key = (count, len(undec), 0)
            if best_key is None or key < best_key:
                best_key = key
                best_kind = "constraint"
                best_payload = (cid, rem, undec)

        for target in range(self.W):
            if st.lit[target] != 0:
                continue
            poss = st.supp[target]
            if poss <= 1:
                continue
            key = (poss, poss, 1)
            if best_key is None or key < best_key:
                best_key = key
                best_kind = "light"
                best_payload = target

        if best_kind == "constraint":
            cid, rem, undec = best_payload
            combos = list(combinations(undec, rem))
            combos.sort(
                key=lambda combo: -sum(self.cell_branch_score(st, idx) for idx in combo)
            )
            branches = []
            for combo in combos:
                chosen = set(combo)
                actions = []
                for idx in undec:
                    actions.append((idx, 1 if idx in chosen else 0))
                actions.sort(key=lambda x: -x[1])
                branches.append(actions)
            return branches

        if best_kind == "light":
            target = best_payload
            supporters = [idx for idx in self.supporters[target] if st.cell[idx] != 0]
            supporters.sort(key=lambda idx: self.cell_branch_score(st, idx), reverse=True)
            return [[(idx, 1)] for idx in supporters]

        undec = [idx for idx in range(self.W) if st.cell[idx] == -1]
        if not undec:
            return []
        undec.sort(key=lambda idx: self.cell_branch_score(st, idx), reverse=True)
        idx = undec[0]
        return [[(idx, 1)], [(idx, 0)]]

    def dfs(self, st):
        if self.is_solved(st):
            return st

        branches = self.choose_branches(st)
        for actions in branches:
            nxt = st.clone()
            if self.propagate(nxt, actions):
                res = self.dfs(nxt)
                if res is not None:
                    return res
        return None

    def format_solution(self, st):
        grid = [[None for _ in range(self.N)] for _ in range(self.N)]
        for idx, (r, c) in enumerate(self.white_coords):
            if st.cell[idx] == 1:
                grid[r][c] = 'B'
        return str(grid)


def solve(observation):
    try:
        data = observation["data"]
        solver = AkariSolver(data)
        st = solver.initial_state()
        if st is None:
            return "No Solution"
        res = solver.dfs(st)
        if res is None:
            return "No Solution"
        return solver.format_solution(res)
    except Exception:
        return "No Solution"


