def solve(observation):
    data = observation.get("data", [])
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    all_mask = (1 << n) - 1

    def is_singleton(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def bit_to_value(bit):
        return bit.bit_length()

    cons_by_bit = {}
    noncons_by_bit = {}
    for v in range(1, n + 1):
        bit = 1 << (v - 1)
        m = 0
        if v > 1:
            m |= 1 << (v - 2)
        if v < n:
            m |= 1 << v
        cons_by_bit[bit] = m
        noncons_by_bit[bit] = all_mask ^ m

    # True means a dot exists, so adjacent cells must be consecutive.
    row_rels = [[False] * (n - 1) for _ in range(n)]
    col_rels = [[False] * (n - 1) for _ in range(n)]

    for item in observation.get("adjacent", []):
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            continue
        r, c = item
        if abs(r - round(r)) < 1e-9:
            rr = int(round(r))
            cc = int(round(c - 0.5))
            if 0 <= rr < n and 0 <= cc < n - 1:
                row_rels[rr][cc] = True
        else:
            rr = int(round(r - 0.5))
            cc = int(round(c))
            if 0 <= rr < n - 1 and 0 <= cc < n:
                col_rels[cc][rr] = True

    domains = [[all_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            try:
                v = int(v)
            except Exception:
                return "No Solution"
            if not (1 <= v <= n):
                return "No Solution"
            domains[r][c] = 1 << (v - 1)

    # Cache full-line analyses. Each line analysis mirrors human reasoning:
    # "What complete permutations can this row/column still be?"
    line_cache = {}

    def analyze_line(domains_tuple, rels_tuple):
        key = (domains_tuple, rels_tuple)
        if key in line_cache:
            return line_cache[key]

        state_cache = {}

        def rec(pos, remaining, prev_bit):
            state_key = (pos, remaining, prev_bit)
            if state_key in state_cache:
                return state_cache[state_key]

            if pos == n:
                result = (1, (), (0,) * n)
                state_cache[state_key] = result
                return result

            union_future = 0
            for i in range(pos, n):
                m = domains_tuple[i] & remaining
                if m == 0:
                    zero = (0, (0,) * (n - pos), (0,) * n)
                    state_cache[state_key] = zero
                    return zero
                union_future |= m
            if union_future.bit_count() < (n - pos):
                zero = (0, (0,) * (n - pos), (0,) * n)
                state_cache[state_key] = zero
                return zero

            avail = domains_tuple[pos] & remaining
            if pos > 0:
                if rels_tuple[pos - 1]:
                    avail &= cons_by_bit[prev_bit]
                else:
                    avail &= noncons_by_bit[prev_bit]

            count = 0
            pos_support = [0] * (n - pos)
            val_pos = [0] * n

            m = avail
            while m:
                bit = m & -m
                m -= bit
                rem2 = remaining ^ bit

                if pos + 1 < n:
                    next_avail = domains_tuple[pos + 1] & rem2
                    if rels_tuple[pos]:
                        if (next_avail & cons_by_bit[bit]) == 0:
                            continue
                    else:
                        if (next_avail & noncons_by_bit[bit]) == 0:
                            continue

                child_count, child_pos_support, child_val_pos = rec(pos + 1, rem2, bit)
                if child_count == 0:
                    continue

                count += child_count
                pos_support[0] |= bit
                for i, bm in enumerate(child_pos_support, 1):
                    pos_support[i] |= bm

                v_idx = bit.bit_length() - 1
                val_pos[v_idx] |= 1 << pos
                for i in range(n):
                    val_pos[i] |= child_val_pos[i]

            result = (count, tuple(pos_support), tuple(val_pos))
            state_cache[state_key] = result
            return result

        result = rec(0, all_mask, 0)
        line_cache[key] = result
        return result

    def propagate(board):
        changed = True
        while changed:
            changed = False

            # Row-wise permutation filtering.
            for r in range(n):
                count, pos_support, val_pos = analyze_line(tuple(board[r]), tuple(row_rels[r]))
                if count == 0:
                    return None

                for c in range(n):
                    new_mask = board[r][c] & pos_support[c]
                    if new_mask == 0:
                        return None
                    if new_mask != board[r][c]:
                        board[r][c] = new_mask
                        changed = True

                for v_idx, pos_mask in enumerate(val_pos):
                    if pos_mask == 0:
                        return None
                    if (pos_mask & (pos_mask - 1)) == 0:
                        c = pos_mask.bit_length() - 1
                        forced = 1 << v_idx
                        new_mask = board[r][c] & forced
                        if new_mask == 0:
                            return None
                        if new_mask != board[r][c]:
                            board[r][c] = new_mask
                            changed = True

            # Column-wise permutation filtering.
            for c in range(n):
                col_domains = tuple(board[r][c] for r in range(n))
                count, pos_support, val_pos = analyze_line(col_domains, tuple(col_rels[c]))
                if count == 0:
                    return None

                for r in range(n):
                    new_mask = board[r][c] & pos_support[r]
                    if new_mask == 0:
                        return None
                    if new_mask != board[r][c]:
                        board[r][c] = new_mask
                        changed = True

                for v_idx, pos_mask in enumerate(val_pos):
                    if pos_mask == 0:
                        return None
                    if (pos_mask & (pos_mask - 1)) == 0:
                        r = pos_mask.bit_length() - 1
                        forced = 1 << v_idx
                        new_mask = board[r][c] & forced
                        if new_mask == 0:
                            return None
                        if new_mask != board[r][c]:
                            board[r][c] = new_mask
                            changed = True

        return board

    def solved(board):
        for r in range(n):
            for c in range(n):
                if not is_singleton(board[r][c]):
                    return False
        return True

    def select_cell(board):
        best = None
        best_key = None
        for r in range(n):
            row_unfixed = sum(1 for c in range(n) if not is_singleton(board[r][c]))
            for c in range(n):
                mask = board[r][c]
                if is_singleton(mask):
                    continue
                col_unfixed = sum(1 for rr in range(n) if not is_singleton(board[rr][c]))
                degree = (row_unfixed - 1) + (col_unfixed - 1)
                key = (mask.bit_count(), -degree, r, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def ordered_bits(board, r, c):
        mask = board[r][c]
        bits = []
        m = mask
        while m:
            bit = m & -m
            m -= bit
            row_places = sum(1 for cc in range(n) if cc != c and (board[r][cc] & bit))
            col_places = sum(1 for rr in range(n) if rr != r and (board[rr][c] & bit))
            score = row_places + col_places
            bits.append((score, bit_to_value(bit), bit))
        bits.sort()
        return [bit for _, _, bit in bits]

    failed = set()

    def board_key(board):
        return tuple(tuple(row) for row in board)

    def search(board):
        board = propagate(board)
        if board is None:
            return None

        key = board_key(board)
        if key in failed:
            return None

        if solved(board):
            return board

        cell = select_cell(board)
        if cell is None:
            return None

        r, c = cell
        for bit in ordered_bits(board, r, c):
            new_board = [row[:] for row in board]
            new_board[r][c] = bit
            result = search(new_board)
            if result is not None:
                return result

        failed.add(key)
        return None

    result = search([row[:] for row in domains])
    if result is None:
        return "No Solution"

    solved_grid = [[bit_to_value(result[r][c]) for c in range(n)] for r in range(n)]
    return repr(solved_grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

