from functools import lru_cache

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    fullmask = (1 << n) - 1
    bit_list = [1 << i for i in range(n)]

    def idx(r, c):
        return r * n + c

    def bit_to_val(bit):
        return bit.bit_length()

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    dots = {tuple(x) for x in observation["adjacent"]}

    edges = []
    adj_relation = [dict() for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            a = idx(r, c)
            if c + 1 < n:
                b = idx(r, c + 1)
                has_dot = (float(r), c + 0.5) in dots
                edges.append((a, b, has_dot))
                adj_relation[a][b] = has_dot
                adj_relation[b][a] = has_dot
            if r + 1 < n:
                b = idx(r + 1, c)
                has_dot = (r + 0.5, float(c)) in dots
                edges.append((a, b, has_dot))
                adj_relation[a][b] = has_dot
                adj_relation[b][a] = has_dot

    units = []
    for r in range(n):
        units.append(tuple(idx(r, c) for c in range(n)))
    for c in range(n):
        units.append(tuple(idx(r, c) for r in range(n)))

    peers = []
    degree = [0] * (n * n)
    for r in range(n):
        for c in range(n):
            s = set(idx(r, x) for x in range(n) if x != c)
            s.update(idx(x, c) for x in range(n) if x != r)
            p = tuple(sorted(s))
            peers.append(p)
            degree[idx(r, c)] = len(p) + len(adj_relation[idx(r, c)])

    cons_by_bit = {}
    noncon_by_bit = {}
    for v in range(1, n + 1):
        b = 1 << (v - 1)
        m = 0
        if v > 1:
            m |= 1 << (v - 2)
        if v < n:
            m |= 1 << v
        cons_by_bit[b] = m
        noncon_by_bit[b] = fullmask & ~m

    sup_con = [0] * (1 << n)
    sup_non = [0] * (1 << n)
    for mask in range(1 << n):
        sc = 0
        x = mask
        while x:
            b = x & -x
            x -= b
            sc |= cons_by_bit[b]
        sup_con[mask] = sc
        sn = 0
        for b in bit_list:
            if mask & noncon_by_bit[b]:
                sn |= b
        sup_non[mask] = sn

    @lru_cache(None)
    def reduce_unit(masks_tuple):
        masks = list(masks_tuple)
        while True:
            front = [None] * (n + 1)
            front[0] = {0}
            for i, m in enumerate(masks):
                new = set()
                for used in front[i]:
                    x = m & ~used
                    while x:
                        b = x & -x
                        x -= b
                        new.add(used | b)
                if not new:
                    return None
                front[i + 1] = new

            if fullmask not in front[n]:
                return None

            back = [None] * (n + 1)
            back[n] = {0}
            for i in range(n - 1, -1, -1):
                new = set()
                m = masks[i]
                for tail in back[i + 1]:
                    x = m & ~tail
                    while x:
                        b = x & -x
                        x -= b
                        new.add(tail | b)
                if not new:
                    return None
                back[i] = new

            changed = False
            supported = [0] * n
            for i, m in enumerate(masks):
                sup = 0
                suffix = back[i + 1]
                for p in front[i]:
                    x = m & ~p
                    while x:
                        b = x & -x
                        x -= b
                        if (fullmask ^ (p | b)) in suffix:
                            sup |= b
                    if sup == m:
                        break
                if sup == 0:
                    return None
                supported[i] = sup
                if sup != m:
                    changed = True

            masks = supported

            for b in bit_list:
                pos = -1
                cnt = 0
                for i, m in enumerate(masks):
                    if m & b:
                        cnt += 1
                        pos = i
                if cnt == 0:
                    return None
                if cnt == 1 and masks[pos] != b:
                    masks[pos] = b
                    changed = True

            if not changed:
                return tuple(masks)

    domains0 = [fullmask] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains0[idx(r, c)] = 1 << (v - 1)

    def propagate(domains):
        domains = domains[:]
        while True:
            changed = False

            for d in domains:
                if d == 0:
                    return None

            for i, d in enumerate(domains):
                if is_single(d):
                    bit = d
                    for p in peers[i]:
                        nd = domains[p] & ~bit
                        if nd != domains[p]:
                            if nd == 0:
                                return None
                            domains[p] = nd
                            changed = True

            for a, b, has_dot in edges:
                table = sup_con if has_dot else sup_non
                ma = domains[a]
                mb = domains[b]

                na = ma & table[mb]
                if na != ma:
                    if na == 0:
                        return None
                    domains[a] = na
                    ma = na
                    changed = True

                nb = mb & table[ma]
                if nb != mb:
                    if nb == 0:
                        return None
                    domains[b] = nb
                    changed = True

            for unit in units:
                reduced = reduce_unit(tuple(domains[i] for i in unit))
                if reduced is None:
                    return None
                for k, i in enumerate(unit):
                    nd = reduced[k]
                    if nd != domains[i]:
                        if nd == 0:
                            return None
                        domains[i] = nd
                        changed = True

            if not changed:
                return domains

    def candidate_order(domains, i):
        m = domains[i]
        scored = []
        x = m
        while x:
            b = x & -x
            x -= b
            total = 0
            ok = True
            for j in peers[i]:
                allowed = domains[j] & ~b
                rel = adj_relation[i].get(j)
                if rel is not None:
                    allowed &= cons_by_bit[b] if rel else noncon_by_bit[b]
                if allowed == 0:
                    ok = False
                    break
                total += allowed.bit_count()
            if ok:
                scored.append((-total, bit_to_val(b), b))
        scored.sort()
        return [b for _, _, b in scored]

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        unsolved = [i for i, d in enumerate(domains) if not is_single(d)]
        if not unsolved:
            return domains

        i = min(unsolved, key=lambda k: (domains[k].bit_count(), -degree[k]))
        for b in candidate_order(domains, i):
            new_domains = domains[:]
            new_domains[i] = b
            res = search(new_domains)
            if res is not None:
                return res
        return None

    def build_grid(domains):
        return [[bit_to_val(domains[idx(r, c)]) for c in range(n)] for r in range(n)]

    def validate(grid):
        target = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != target:
                return False
        for c in range(n):
            if {grid[r][c] for r in range(n)} != target:
                return False
        for r in range(n):
            for c in range(n):
                v = grid[r][c]
                if c + 1 < n:
                    w = grid[r][c + 1]
                    has_dot = (float(r), c + 0.5) in dots
                    if has_dot != (abs(v - w) == 1):
                        return False
                if r + 1 < n:
                    w = grid[r + 1][c]
                    has_dot = (r + 0.5, float(c)) in dots
                    if has_dot != (abs(v - w) == 1):
                        return False
        return True

    solved = search(domains0)
    if solved is None:
        return "No Solution"

    grid = build_grid(solved)
    return str(grid) if validate(grid) else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

