from itertools import combinations

# Generalized Kropki Latin-square solver with:
# - row/column all-different propagation
# - consecutive / non-consecutive arc consistency on every orthogonal edge
# - hidden singles
# - small Hall-set / naked-subset elimination
# - informed depth-first search with memoized dead states

def solve(observation):
    model = _build_model(observation)
    if model is None:
        return "No Solution"

    N = model["N"]
    FULL = model["FULL"]
    data = observation["data"]

    domains = [FULL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                domains[r * N + c] = 1 << (v - 1)

    dead = set()

    def dfs(domains):
        domains = _propagate(domains, model)
        if domains is None:
            return None

        state = tuple(domains)
        if state in dead:
            return None

        if all((m & (m - 1)) == 0 for m in domains):
            if _is_valid_solution(domains, model):
                return domains
            dead.add(state)
            return None

        idx = _choose_cell(domains, model)
        for bit in _ordered_values(idx, domains, model):
            nxt = domains.copy()
            nxt[idx] = bit
            res = dfs(nxt)
            if res is not None:
                return res

        dead.add(state)
        return None

    solved = dfs(domains)
    if solved is None:
        return "No Solution"

    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(_single_value(solved[r * N + c]))
        grid.append(row)
    return str(grid)


def _build_model(observation):
    data = observation["data"]
    N = len(data)
    if N == 0 or any(len(row) != N for row in data):
        return None

    FULL = (1 << N) - 1
    rows = [[r * N + c for c in range(N)] for r in range(N)]
    cols = [[r * N + c for r in range(N)] for c in range(N)]
    units = rows + cols

    dot_pairs = set()
    for rc in observation["adjacent"]:
        if len(rc) != 2:
            return None
        r, c = rc
        r_int = abs(r - round(r)) < 1e-9
        c_int = abs(c - round(c)) < 1e-9

        if r_int and not c_int:
            rr = int(round(r))
            cc = int(c - 0.5)
            if not (0 <= rr < N and 0 <= cc < N - 1):
                return None
            a = rr * N + cc
            b = rr * N + (cc + 1)
        elif c_int and not r_int:
            rr = int(r - 0.5)
            cc = int(round(c))
            if not (0 <= rr < N - 1 and 0 <= cc < N):
                return None
            a = rr * N + cc
            b = (rr + 1) * N + cc
        else:
            return None

        if a > b:
            a, b = b, a
        dot_pairs.add((a, b))

    edges = []
    adj_list = [[] for _ in range(N * N)]
    degrees = [0] * (N * N)

    for r in range(N):
        for c in range(N):
            i = r * N + c
            if c + 1 < N:
                j = i + 1
                p = (i, j) if i < j else (j, i)
                is_dot = p in dot_pairs
                edges.append((i, j, is_dot))
                adj_list[i].append((j, is_dot))
                adj_list[j].append((i, is_dot))
                degrees[i] += 1
                degrees[j] += 1
            if r + 1 < N:
                j = i + N
                p = (i, j) if i < j else (j, i)
                is_dot = p in dot_pairs
                edges.append((i, j, is_dot))
                adj_list[i].append((j, is_dot))
                adj_list[j].append((i, is_dot))
                degrees[i] += 1
                degrees[j] += 1

    cons_support = []
    noncons_support = []
    for v in range(1, N + 1):
        cons = 0
        if v > 1:
            cons |= 1 << (v - 2)
        if v < N:
            cons |= 1 << v
        cons_support.append(cons)
        noncons_support.append(FULL & ~cons & ~(1 << (v - 1)))

    return {
        "N": N,
        "FULL": FULL,
        "rows": rows,
        "cols": cols,
        "units": units,
        "edges": edges,
        "adj_list": adj_list,
        "degrees": degrees,
        "cons_support": cons_support,
        "noncons_support": noncons_support,
    }


def _single_value(mask):
    return mask.bit_length()


def _filter_by_neighbor(mask, neighbor_mask, support_table):
    out = 0
    m = mask
    while m:
        bit = m & -m
        m -= bit
        if support_table[bit.bit_length() - 1] & neighbor_mask:
            out |= bit
    return out


def _apply_unit_logic(unit, domains, N):
    changed = False

    fixed = 0
    for idx in unit:
        m = domains[idx]
        if m == 0:
            return None, False
        if (m & (m - 1)) == 0:
            if fixed & m:
                return None, False
            fixed |= m

    for idx in unit:
        m = domains[idx]
        if m & (m - 1):
            nm = m & ~fixed
            if nm == 0:
                return None, False
            if nm != m:
                domains[idx] = nm
                changed = True

    bit = 1
    for _ in range(N):
        count = 0
        last = -1
        for idx in unit:
            if domains[idx] & bit:
                count += 1
                last = idx
        if count == 0:
            return None, False
        if count == 1 and domains[last] != bit:
            domains[last] = bit
            changed = True
        bit <<= 1

    return domains, changed


def _apply_subset_logic(unit, domains):
    changed = False
    unsolved = [idx for idx in unit if domains[idx].bit_count() > 1]

    # Fast exact-mask elimination
    groups = {}
    for idx in unsolved:
        m = domains[idx]
        bc = m.bit_count()
        if 2 <= bc <= 3:
            groups.setdefault(m, []).append(idx)

    for m, cells in groups.items():
        k = len(cells)
        if k == m.bit_count() and k >= 2:
            cellset = set(cells)
            for idx in unit:
                if idx not in cellset:
                    nm = domains[idx] & ~m
                    if nm == 0:
                        return None, False
                    if nm != domains[idx]:
                        domains[idx] = nm
                        changed = True

    # Small Hall sets / naked subsets of size 2 and 3
    for k in (2, 3):
        cands = [idx for idx in unsolved if 2 <= domains[idx].bit_count() <= k]
        if len(cands) < k:
            continue
        seen = set()
        for combo in combinations(cands, k):
            union = 0
            for idx in combo:
                union |= domains[idx]
            if union.bit_count() != k:
                continue
            key = (combo, union)
            if key in seen:
                continue
            seen.add(key)
            combset = set(combo)
            for idx in unit:
                if idx not in combset:
                    nm = domains[idx] & ~union
                    if nm == 0:
                        return None, False
                    if nm != domains[idx]:
                        domains[idx] = nm
                        changed = True

    return domains, changed


def _propagate(domains, model):
    domains = domains.copy()
    N = model["N"]
    edges = model["edges"]
    units = model["units"]
    cons_support = model["cons_support"]
    noncons_support = model["noncons_support"]

    while True:
        changed = False

        # Binary edge consistency on every orthogonal adjacency.
        for a, b, is_dot in edges:
            support = cons_support if is_dot else noncons_support

            da = domains[a]
            db = domains[b]

            na = _filter_by_neighbor(da, db, support)
            if na == 0:
                return None
            if na != da:
                domains[a] = na
                changed = True

            da = domains[a]
            nb = _filter_by_neighbor(db, da, support)
            if nb == 0:
                return None
            if nb != db:
                domains[b] = nb
                changed = True

        # Latin-square row/column deductions.
        for unit in units:
            res, ch = _apply_unit_logic(unit, domains, N)
            if res is None:
                return None
            changed |= ch

        # Small subset reasoning.
        for unit in units:
            res, ch = _apply_subset_logic(unit, domains)
            if res is None:
                return None
            changed |= ch

        if not changed:
            break

    return domains


def _choose_cell(domains, model):
    N = model["N"]
    rows = model["rows"]
    cols = model["cols"]
    degrees = model["degrees"]

    best = None
    best_key = None
    for idx, m in enumerate(domains):
        bc = m.bit_count()
        if bc <= 1:
            continue
        r, c = divmod(idx, N)
        unresolved = 0
        for j in rows[r]:
            if domains[j].bit_count() > 1:
                unresolved += 1
        for j in cols[c]:
            if domains[j].bit_count() > 1:
                unresolved += 1
        key = (bc, -degrees[idx], -unresolved, idx)
        if best_key is None or key < best_key:
            best_key = key
            best = idx
    return best


def _ordered_values(idx, domains, model):
    N = model["N"]
    rows = model["rows"]
    cols = model["cols"]
    adj_list = model["adj_list"]
    cons_support = model["cons_support"]
    noncons_support = model["noncons_support"]

    r, c = divmod(idx, N)
    m = domains[idx]
    scored = []

    mm = m
    while mm:
        bit = mm & -mm
        mm -= bit
        value_index = bit.bit_length() - 1

        # Higher score = less constraining.
        score = 0

        # Preserve options in row/col peers.
        for j in rows[r]:
            if j != idx and domains[j] & bit:
                score += 1
        for j in cols[c]:
            if j != idx and domains[j] & bit:
                score += 1

        # Preserve options across adjacent Kropki edges.
        for j, is_dot in adj_list[idx]:
            support = cons_support if is_dot else noncons_support
            score += (domains[j] & support[value_index]).bit_count()

        scored.append((-score, value_index + 1, bit))

    scored.sort()
    return [bit for _, _, bit in scored]


def _is_valid_solution(domains, model):
    N = model["N"]
    rows = model["rows"]
    cols = model["cols"]
    edges = model["edges"]

    vals = [_single_value(m) for m in domains]

    target = set(range(1, N + 1))
    for unit in rows:
        if {vals[i] for i in unit} != target:
            return False
    for unit in cols:
        if {vals[i] for i in unit} != target:
            return False

    for a, b, is_dot in edges:
        diff = abs(vals[a] - vals[b])
        if is_dot:
            if diff != 1:
                return False
        else:
            if diff == 1:
                return False

    return True


