# Takuzu / Binairo solver with strong propagation plus guided backtracking.
# Uses human-like logic:
# - no three consecutive equal cells
# - row/column balance
# - rows/columns must be unique
# - candidate pattern pruning and row/column cross-consistency

import sys

sys.setrecursionlimit(10000)


def solve(observation):
    data = observation.get("data")
    if not data or not data[0]:
        return "No Solution"

    r = len(data)
    c = len(data[0])

    if any(len(row) != c for row in data):
        return "No Solution"
    if r % 2 != 0 or c % 2 != 0:
        return "No Solution"

    char_to_val = {"W": 0, "B": 1, None: None}
    val_to_char = {0: "W", 1: "B"}

    try:
        grid = [[char_to_val[x] for x in row] for row in data]
    except KeyError:
        return "No Solution"

    original = [row[:] for row in grid]

    row_patterns = generate_valid_patterns(c)
    col_patterns = generate_valid_patterns(r)
    if not row_patterns or not col_patterns:
        return "No Solution"

    row_cands = [row_patterns[:] for _ in range(r)]
    col_cands = [col_patterns[:] for _ in range(c)]

    result = dfs(grid, row_cands, col_cands, original)
    if result is None:
        return "No Solution"
    return [[val_to_char[v] for v in row] for row in result]


def generate_valid_patterns(n):
    half = n // 2
    out = []

    def rec(pos, seq, blacks, whites):
        rem = n - pos
        if blacks > half or whites > half:
            return
        if blacks + rem < half or whites + rem < half:
            return
        if pos == n:
            out.append(tuple(seq))
            return

        for v in (0, 1):
            if v == 1 and blacks >= half:
                continue
            if v == 0 and whites >= half:
                continue
            if pos >= 2 and seq[-1] == seq[-2] == v:
                continue
            seq.append(v)
            rec(pos + 1, seq, blacks + (v == 1), whites + (v == 0))
            seq.pop()

    rec(0, [], 0, 0)
    return out


def bit(v):
    return 1 if v == 0 else 2


def compatible_pattern_line(pattern, line):
    return all(cell is None or cell == val for cell, val in zip(line, pattern))


def apply_local_rules_line(line):
    n = len(line)
    changed = False

    # Triple-avoidance rules.
    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and b is not None and a == b and c is None:
            line[i + 2] = 1 - a
            changed = True
        elif b is not None and c is not None and b == c and a is None:
            line[i] = 1 - b
            changed = True
        elif a is not None and c is not None and a == c and b is None:
            line[i + 1] = 1 - a
            changed = True

    # Balance rule.
    half = n // 2
    blacks = sum(1 for x in line if x == 1)
    whites = sum(1 for x in line if x == 0)

    if blacks > half or whites > half:
        return None

    if blacks == half:
        for i, x in enumerate(line):
            if x is None:
                line[i] = 0
                changed = True
    elif whites == half:
        for i, x in enumerate(line):
            if x is None:
                line[i] = 1
                changed = True

    # Immediate validity checks.
    blacks = sum(1 for x in line if x == 1)
    whites = sum(1 for x in line if x == 0)
    if blacks > half or whites > half:
        return None

    for i in range(n - 2):
        if line[i] is not None and line[i] == line[i + 1] == line[i + 2]:
            return None

    return changed


def apply_local_rules(grid):
    r, c = len(grid), len(grid[0])
    progress = False

    for i in range(r):
        res = apply_local_rules_line(grid[i])
        if res is None:
            return None
        progress |= res

    for j in range(c):
        col = [grid[i][j] for i in range(r)]
        res = apply_local_rules_line(col)
        if res is None:
            return None
        if res:
            for i in range(r):
                if grid[i][j] != col[i]:
                    grid[i][j] = col[i]
                    progress = True

    return progress


def propagate(grid, row_cands, col_cands):
    r, c = len(grid), len(grid[0])

    while True:
        progress = False

        # Human-style direct deductions.
        res = apply_local_rules(grid)
        if res is None:
            return None
        progress |= res

        # Filter row candidates by current grid.
        for i in range(r):
            old = row_cands[i]
            new = [p for p in old if compatible_pattern_line(p, grid[i])]
            if not new:
                return None
            if len(new) != len(old):
                row_cands[i] = new
                progress = True

        # Filter column candidates by current grid.
        for j in range(c):
            col = [grid[i][j] for i in range(r)]
            old = col_cands[j]
            new = [p for p in old if compatible_pattern_line(p, col)]
            if not new:
                return None
            if len(new) != len(old):
                col_cands[j] = new
                progress = True

        # Enforce uniqueness against fixed/singleton lines.
        seen = {}
        for i in range(r):
            if len(row_cands[i]) == 1:
                p = row_cands[i][0]
                if p in seen and seen[p] != i:
                    return None
                seen[p] = i
        if seen:
            forbidden = set(seen)
            for i in range(r):
                if len(row_cands[i]) > 1:
                    old = row_cands[i]
                    new = [p for p in old if p not in forbidden]
                    if not new:
                        return None
                    if len(new) != len(old):
                        row_cands[i] = new
                        progress = True

        seen = {}
        for j in range(c):
            if len(col_cands[j]) == 1:
                p = col_cands[j][0]
                if p in seen and seen[p] != j:
                    return None
                seen[p] = j
        if seen:
            forbidden = set(seen)
            for j in range(c):
                if len(col_cands[j]) > 1:
                    old = col_cands[j]
                    new = [p for p in old if p not in forbidden]
                    if not new:
                        return None
                    if len(new) != len(old):
                        col_cands[j] = new
                        progress = True

        # Build allowed-value masks from row and column candidates.
        row_masks = [[0] * c for _ in range(r)]
        for i in range(r):
            for p in row_cands[i]:
                for j, v in enumerate(p):
                    row_masks[i][j] |= bit(v)

        col_masks = [[0] * r for _ in range(c)]
        for j in range(c):
            for p in col_cands[j]:
                for i, v in enumerate(p):
                    col_masks[j][i] |= bit(v)

        # Cell-wise intersection of row/column possibilities.
        for i in range(r):
            for j in range(c):
                allowed = row_masks[i][j] & col_masks[j][i]
                if allowed == 0:
                    return None
                if grid[i][j] is None:
                    if allowed == 1:
                        grid[i][j] = 0
                        progress = True
                    elif allowed == 2:
                        grid[i][j] = 1
                        progress = True
                else:
                    if not (allowed & bit(grid[i][j])):
                        return None

        # Remove unsupported row candidates using column possibility masks.
        for i in range(r):
            old = row_cands[i]
            new = []
            for p in old:
                ok = True
                for j, v in enumerate(p):
                    if not (col_masks[j][i] & bit(v)):
                        ok = False
                        break
                if ok:
                    new.append(p)
            if not new:
                return None
            if len(new) != len(old):
                row_cands[i] = new
                progress = True

        # Remove unsupported column candidates using row possibility masks.
        for j in range(c):
            old = col_cands[j]
            new = []
            for p in old:
                ok = True
                for i, v in enumerate(p):
                    if not (row_masks[i][j] & bit(v)):
                        ok = False
                        break
                if ok:
                    new.append(p)
            if not new:
                return None
            if len(new) != len(old):
                col_cands[j] = new
                progress = True

        # Write singleton line candidates into the grid.
        for i in range(r):
            if len(row_cands[i]) == 1:
                p = row_cands[i][0]
                for j, v in enumerate(p):
                    if grid[i][j] is None:
                        grid[i][j] = v
                        progress = True
                    elif grid[i][j] != v:
                        return None

        for j in range(c):
            if len(col_cands[j]) == 1:
                p = col_cands[j][0]
                for i, v in enumerate(p):
                    if grid[i][j] is None:
                        grid[i][j] = v
                        progress = True
                    elif grid[i][j] != v:
                        return None

        if not progress:
            return grid, row_cands, col_cands


def is_complete(grid):
    return all(all(cell is not None for cell in row) for row in grid)


def validate_complete(grid, original):
    r, c = len(grid), len(grid[0])

    # Given cells fixed.
    for i in range(r):
        for j in range(c):
            if original[i][j] is not None and grid[i][j] != original[i][j]:
                return False

    # Row rules.
    half_c = c // 2
    row_tuples = []
    for row in grid:
        if any(x is None for x in row):
            return False
        if sum(1 for x in row if x == 1) != half_c:
            return False
        for k in range(c - 2):
            if row[k] == row[k + 1] == row[k + 2]:
                return False
        row_tuples.append(tuple(row))
    if len(set(row_tuples)) != r:
        return False

    # Column rules.
    half_r = r // 2
    col_tuples = []
    for j in range(c):
        col = tuple(grid[i][j] for i in range(r))
        if sum(1 for x in col if x == 1) != half_r:
            return False
        for k in range(r - 2):
            if col[k] == col[k + 1] == col[k + 2]:
                return False
        col_tuples.append(col)
    if len(set(col_tuples)) != c:
        return False

    return True


def clone_state(grid, row_cands, col_cands):
    return [row[:] for row in grid], [cand[:] for cand in row_cands], [cand[:] for cand in col_cands]


def choose_branch(row_cands, col_cands):
    best = None

    for i, cands in enumerate(row_cands):
        k = len(cands)
        if k > 1:
            key = (k, 0, i)
            if best is None or key < best[:3]:
                best = (k, 0, i, cands)

    for j, cands in enumerate(col_cands):
        k = len(cands)
        if k > 1:
            key = (k, 1, j)
            if best is None or key < best[:3]:
                best = (k, 1, j, cands)

    return best


def dfs(grid, row_cands, col_cands, original):
    state = propagate(grid, row_cands, col_cands)
    if state is None:
        return None

    grid, row_cands, col_cands = state

    if is_complete(grid):
        return grid if validate_complete(grid, original) else None

    branch = choose_branch(row_cands, col_cands)
    if branch is None:
        return None

    _, kind, idx, candidates = branch

    # Least-disruptive ordering: candidates already strongly constrained.
    for pattern in candidates:
        ng, nr, nc = clone_state(grid, row_cands, col_cands)

        if kind == 0:
            nr[idx] = [pattern]
            ok = True
            for j, v in enumerate(pattern):
                if ng[idx][j] is not None and ng[idx][j] != v:
                    ok = False
                    break
                ng[idx][j] = v
            if not ok:
                continue
        else:
            nc[idx] = [pattern]
            ok = True
            for i, v in enumerate(pattern):
                if ng[i][idx] is not None and ng[i][idx] != v:
                    ok = False
                    break
                ng[i][idx] = v
            if not ok:
                continue

        res = dfs(ng, nr, nc, original)
        if res is not None:
            return res

    return None


