# Slant / Gokigen Naname solver:
# - exactly one diagonal per cell
# - numbered dots count incident diagonals
# - no closed loops

BIT_BS = 1   # '\'
BIT_FS = 2   # '/'

def solve(observation):
    data = observation['data']
    n = len(data) - 1
    if n <= 0:
        return repr([])

    m = n * n
    vcount = (n + 1) * (n + 1)

    def vid(r, c):
        return r * (n + 1) + c

    # Per cell:
    # bit '\' => (tl, br)
    # bit '/' => (tr, bl)
    endpoints = [{} for _ in range(m)]
    cell_clue_adj = [[] for _ in range(m)]  # list of (vertex_id, yes_bit) for numbered vertices

    # Per numbered vertex:
    clue_items = []          # list of (vertex_id, clue)
    clue_inc = {}            # vertex_id -> list of (cell_idx, yes_bit)

    for r in range(n + 1):
        for c in range(n + 1):
            clue = data[r][c]
            if clue is not None:
                v = vid(r, c)
                clue_items.append((v, clue))
                clue_inc[v] = []

    for r in range(n):
        for c in range(n):
            i = r * n + c
            tl = vid(r, c)
            tr = vid(r, c + 1)
            bl = vid(r + 1, c)
            br = vid(r + 1, c + 1)

            endpoints[i][BIT_BS] = (tl, br)
            endpoints[i][BIT_FS] = (tr, bl)

            corners = [
                (r, c, tl, BIT_BS),         # tl touched by '\'
                (r, c + 1, tr, BIT_FS),     # tr touched by '/'
                (r + 1, c, bl, BIT_FS),     # bl touched by '/'
                (r + 1, c + 1, br, BIT_BS)  # br touched by '\'
            ]
            for vr, vc, v, yes_bit in corners:
                if data[vr][vc] is not None:
                    clue_inc[v].append((i, yes_bit))
                    cell_clue_adj[i].append((v, yes_bit))

    def find(parent, x):
        while parent[x] != x:
            x = parent[x]
        return x

    def connected(parent, a, b):
        return find(parent, a) == find(parent, b)

    def union(parent, size, a, b):
        ra = find(parent, a)
        rb = find(parent, b)
        if ra == rb:
            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    def propagate(domains, chosen, parent, size):
        # domains[i] in {1,2,3}; chosen[i] in {0,1,2}
        while True:
            changed = False

            # Repeatedly:
            # 1) remove any option that would instantly create a loop
            # 2) commit singletons and union their endpoints
            while True:
                inner_changed = False
                for i in range(m):
                    if chosen[i]:
                        continue

                    mask = domains[i]
                    newmask = mask

                    if newmask & BIT_BS:
                        a, b = endpoints[i][BIT_BS]
                        if connected(parent, a, b):
                            newmask &= ~BIT_BS

                    if newmask & BIT_FS:
                        a, b = endpoints[i][BIT_FS]
                        if connected(parent, a, b):
                            newmask &= ~BIT_FS

                    if newmask == 0:
                        return False

                    if newmask != mask:
                        domains[i] = newmask
                        mask = newmask
                        changed = True
                        inner_changed = True

                    if mask in (BIT_BS, BIT_FS):
                        bit = mask
                        a, b = endpoints[i][bit]
                        if connected(parent, a, b):
                            return False
                        chosen[i] = bit
                        if not union(parent, size, a, b):
                            return False
                        changed = True
                        inner_changed = True

                if not inner_changed:
                    break

            # Numbered-dot propagation
            for v, clue in clue_items:
                yes_fixed = 0
                undecided = []

                for cell, yes_bit in clue_inc[v]:
                    mask = domains[cell]
                    if mask == yes_bit:
                        yes_fixed += 1
                    elif mask == 3:
                        undecided.append((cell, yes_bit))
                    else:
                        # fixed "no" for this vertex
                        pass

                if clue < yes_fixed or clue > yes_fixed + len(undecided):
                    return False

                if clue == yes_fixed:
                    # all remaining incident undecided cells must avoid this vertex
                    for cell, yes_bit in undecided:
                        target = 3 ^ yes_bit
                        newmask = domains[cell] & target
                        if newmask == 0:
                            return False
                        if newmask != domains[cell]:
                            domains[cell] = newmask
                            changed = True

                elif clue == yes_fixed + len(undecided):
                    # all remaining incident undecided cells must touch this vertex
                    for cell, yes_bit in undecided:
                        newmask = domains[cell] & yes_bit
                        if newmask == 0:
                            return False
                        if newmask != domains[cell]:
                            domains[cell] = newmask
                            changed = True

            if not changed:
                return True

    def compute_clue_stats(domains):
        # For branching heuristics
        stats = {}
        for v, clue in clue_items:
            yes_fixed = 0
            undecided = 0
            for cell, yes_bit in clue_inc[v]:
                mask = domains[cell]
                if mask == yes_bit:
                    yes_fixed += 1
                elif mask == 3:
                    undecided += 1
            stats[v] = (clue, clue - yes_fixed, undecided)
        return stats

    def select_cell(domains, chosen):
        stats = compute_clue_stats(domains)
        best_cell = -1
        best_score = None

        for i in range(m):
            if chosen[i] == 0 and domains[i] == 3:
                # Prefer cells around tight numbered vertices
                score = 0
                for v, _ in cell_clue_adj[i]:
                    clue, need, undec = stats[v]
                    score += 10 - undec
                    if need == 0 or need == undec:
                        score += 6
                    if clue in (0, 4):
                        score += 4
                    if clue in (1, 3):
                        score += 2

                # Small positional tie-breaker toward center-ish cells
                r, c = divmod(i, n)
                score = (score, -abs(r - (n - 1) / 2.0) - abs(c - (n - 1) / 2.0))

                if best_score is None or score > best_score:
                    best_score = score
                    best_cell = i

        return best_cell, stats

    def order_bits(cell, stats):
        options = []
        for bit in (BIT_BS, BIT_FS):
            score = 0
            for v, yes_bit in cell_clue_adj[cell]:
                clue, need, undec = stats[v]
                if undec <= 0:
                    continue
                wants_yes = need
                wants_no = undec - need
                if bit == yes_bit:
                    score += wants_yes - wants_no
                    if need == undec:
                        score += 3
                    if need == 0:
                        score -= 3
                else:
                    score += wants_no - wants_yes
                    if need == 0:
                        score += 3
                    if need == undec:
                        score -= 3
            options.append((score, bit))
        options.sort(reverse=True)
        return [bit for _, bit in options]

    def search(domains, chosen, parent, size):
        if not propagate(domains, chosen, parent, size):
            return None

        if all(chosen[i] != 0 for i in range(m)):
            return chosen

        cell, stats = select_cell(domains, chosen)
        if cell < 0:
            return None

        for bit in order_bits(cell, stats):
            if not (domains[cell] & bit):
                continue

            ndom = domains[:]
            ncho = chosen[:]
            npar = parent[:]
            nsiz = size[:]

            ndom[cell] &= bit
            if ndom[cell] == 0:
                continue

            result = search(ndom, ncho, npar, nsiz)
            if result is not None:
                return result

        return None

    domains = [3] * m
    chosen = [0] * m
    parent = list(range(vcount))
    size = [1] * vcount

    result = search(domains, chosen, parent, size)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            bit = result[r * n + c]
            row.append("\\" if bit == BIT_BS else "/")
        grid.append(row)
    return repr(grid)

