from itertools import combinations
from math import comb


class State:
    __slots__ = ("status", "row_bulb", "col_bulb")

    def __init__(self, status, row_bulb, col_bulb):
        self.status = status
        self.row_bulb = row_bulb
        self.col_bulb = col_bulb

    def copy(self):
        s = State.__new__(State)
        s.status = self.status.copy()
        s.row_bulb = self.row_bulb.copy()
        s.col_bulb = self.col_bulb.copy()
        return s


def solve(observation):
    data = observation["data"]
    n = len(data)

    white_cells = []
    index_of = {}
    for r in range(n):
        for c in range(n):
            if data[r][c] is None:
                index_of[(r, c)] = len(white_cells)
                white_cells.append((r, c))

    wcount = len(white_cells)
    row_seg_of = [-1] * wcount
    col_seg_of = [-1] * wcount
    row_segments = []
    col_segments = []

    # Row segments
    for r in range(n):
        c = 0
        while c < n:
            while c < n and data[r][c] is not None:
                c += 1
            if c >= n:
                break
            cells = []
            while c < n and data[r][c] is None:
                idx = index_of[(r, c)]
                cells.append(idx)
                c += 1
            sid = len(row_segments)
            row_segments.append(tuple(cells))
            for idx in cells:
                row_seg_of[idx] = sid

    # Column segments
    for c in range(n):
        r = 0
        while r < n:
            while r < n and data[r][c] is not None:
                r += 1
            if r >= n:
                break
            cells = []
            while r < n and data[r][c] is None:
                idx = index_of[(r, c)]
                cells.append(idx)
                r += 1
            sid = len(col_segments)
            col_segments.append(tuple(cells))
            for idx in cells:
                col_seg_of[idx] = sid

    vis_sets = []
    for i in range(wcount):
        seen = set()
        cells = []
        for j in row_segments[row_seg_of[i]]:
            if j not in seen:
                seen.add(j)
                cells.append(j)
        for j in col_segments[col_seg_of[i]]:
            if j not in seen:
                seen.add(j)
                cells.append(j)
        vis_sets.append(tuple(cells))

    clues = []
    cell_clues = [[] for _ in range(wcount)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if isinstance(v, int) and v >= 0:
                adj = []
                for dr, dc in dirs:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n and data[rr][cc] is None:
                        adj.append(index_of[(rr, cc)])
                cid = len(clues)
                clues.append((v, tuple(adj), (r, c)))
                for idx in adj:
                    cell_clues[idx].append(cid)

    def is_lit(state, idx):
        return state.row_bulb[row_seg_of[idx]] != -1 or state.col_bulb[col_seg_of[idx]] != -1

    def can_place_bulb(state, idx):
        s = state.status[idx]
        if s == 0:
            return False
        if s == 1:
            return True
        if state.row_bulb[row_seg_of[idx]] != -1:
            return False
        if state.col_bulb[col_seg_of[idx]] != -1:
            return False
        for cid in cell_clues[idx]:
            target, adj, _ = clues[cid]
            bulbs = 0
            other_undec = 0
            for j in adj:
                sj = state.status[j]
                if sj == 1:
                    bulbs += 1
                elif sj == -1 and j != idx:
                    other_undec += 1
            if bulbs + 1 > target:
                return False
            if bulbs + 1 + other_undec < target:
                return False
        return True

    def set_empty(state, idx):
        s = state.status[idx]
        if s == 0:
            return True, False
        if s == 1:
            return False, False
        state.status[idx] = 0
        return True, True

    def set_bulb(state, idx):
        s = state.status[idx]
        if s == 1:
            return True, False
        if s == 0:
            return False, False
        if not can_place_bulb(state, idx):
            return False, False

        state.status[idx] = 1
        rs = row_seg_of[idx]
        cs = col_seg_of[idx]
        state.row_bulb[rs] = idx
        state.col_bulb[cs] = idx

        # A human-like immediate deduction: a bulb forbids every other cell it sees.
        for j in row_segments[rs]:
            if j == idx:
                continue
            sj = state.status[j]
            if sj == 1:
                return False, False
            state.status[j] = 0

        for j in col_segments[cs]:
            if j == idx:
                continue
            sj = state.status[j]
            if sj == 1:
                return False, False
            state.status[j] = 0

        return True, True

    def propagate(state):
        while True:
            changed = False

            # Remove impossible bulb candidates.
            for i in range(wcount):
                if state.status[i] == -1 and not can_place_bulb(state, i):
                    ok, ch = set_empty(state, i)
                    if not ok:
                        return None
                    changed |= ch

            # Numbered black cell deductions.
            for target, adj, _ in clues:
                bulbs = 0
                undec = []
                for j in adj:
                    sj = state.status[j]
                    if sj == 1:
                        bulbs += 1
                    elif sj == -1:
                        undec.append(j)

                if bulbs > target:
                    return None
                if bulbs + len(undec) < target:
                    return None

                need = target - bulbs
                if need == 0:
                    for j in undec:
                        ok, ch = set_empty(state, j)
                        if not ok:
                            return None
                        changed |= ch
                elif need == len(undec):
                    for j in undec:
                        ok, ch = set_bulb(state, j)
                        if not ok:
                            return None
                        changed |= ch

            # Illumination necessity: if an unlit cell has one possible source, force it.
            for i in range(wcount):
                if is_lit(state, i):
                    continue
                cands = []
                for j in vis_sets[i]:
                    sj = state.status[j]
                    if sj == 1:
                        cands = [j]
                        break
                    if sj == -1 and can_place_bulb(state, j):
                        cands.append(j)
                if not cands:
                    return None
                if len(cands) == 1 and state.status[cands[0]] != 1:
                    ok, ch = set_bulb(state, cands[0])
                    if not ok:
                        return None
                    changed |= ch

            if not changed:
                break

        # Final consistency checks after fixed-point.
        for target, adj, _ in clues:
            bulbs = 0
            undec = 0
            for j in adj:
                sj = state.status[j]
                if sj == 1:
                    bulbs += 1
                elif sj == -1:
                    undec += 1
            if bulbs > target or bulbs + undec < target:
                return None

        for i in range(wcount):
            if is_lit(state, i):
                continue
            possible = False
            for j in vis_sets[i]:
                sj = state.status[j]
                if sj == 1 or (sj == -1 and can_place_bulb(state, j)):
                    possible = True
                    break
            if not possible:
                return None

        return state

    def is_solved(state):
        for target, adj, _ in clues:
            bulbs = 0
            for j in adj:
                if state.status[j] == 1:
                    bulbs += 1
            if bulbs != target:
                return False
        for i in range(wcount):
            if not is_lit(state, i):
                return False
        return True

    def search(state):
        state = propagate(state)
        if state is None:
            return None
        if is_solved(state):
            return state

        # Strong branch: choose a clue with few valid combinations.
        best = None
        for cid, (target, adj, _) in enumerate(clues):
            bulbs = 0
            undec = []
            for j in adj:
                sj = state.status[j]
                if sj == 1:
                    bulbs += 1
                elif sj == -1 and can_place_bulb(state, j):
                    undec.append(j)
            need = target - bulbs
            u = len(undec)
            if 0 < need < u:
                ways = comb(u, need)
                score = (ways, u, cid)
                if best is None or score < best[:3]:
                    best = (ways, u, cid, tuple(undec), need)

        if best is not None:
            _, _, _, undec, need = best
            undec = list(undec)
            for chosen in combinations(undec, need):
                chosen = set(chosen)
                ns = state.copy()
                ok = True
                for j in undec:
                    if j in chosen:
                        ok, _ = set_bulb(ns, j)
                    else:
                        ok, _ = set_empty(ns, j)
                    if not ok:
                        break
                if ok:
                    res = search(ns)
                    if res is not None:
                        return res
            return None

        # Next branch: pick an unlit cell with fewest ways to illuminate it.
        best_cands = None
        for i in range(wcount):
            if is_lit(state, i):
                continue
            cands = []
            for j in vis_sets[i]:
                sj = state.status[j]
                if sj == 1:
                    cands = [j]
                    break
                if sj == -1 and can_place_bulb(state, j):
                    cands.append(j)
            if 1 < len(cands) and (best_cands is None or len(cands) < len(best_cands)):
                best_cands = cands
                if len(cands) == 2:
                    break

        if best_cands is not None:
            # Prefer more constrained / more informative bulb placements first.
            best_cands = sorted(best_cands, key=lambda j: (-len(cell_clues[j]), -len(vis_sets[j])))
            for j in best_cands:
                ns = state.copy()
                ok, _ = set_bulb(ns, j)
                if ok:
                    res = search(ns)
                    if res is not None:
                        return res
            return None

        # Fallback: branch on a high-impact undecided cell.
        undec = [i for i in range(wcount) if state.status[i] == -1]
        if not undec:
            return None

        i = max(undec, key=lambda j: (len(cell_clues[j]), len(vis_sets[j])))

        if can_place_bulb(state, i):
            ns = state.copy()
            ok, _ = set_bulb(ns, i)
            if ok:
                res = search(ns)
                if res is not None:
                    return res

        ns = state.copy()
        ok, _ = set_empty(ns, i)
        if ok:
            return search(ns)
        return None

    init = State(
        status=[-1] * wcount,
        row_bulb=[-1] * len(row_segments),
        col_bulb=[-1] * len(col_segments),
    )

    result = search(init)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for idx, (r, c) in enumerate(white_cells):
        if result.status[idx] == 1:
            answer[r][c] = "B"
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'W', None, None, 'W', 'W', None, None, None, 'B'], [None, None, None, None, None, None, None, None, None, None], ['B', None, None, 'W', None, None, None, 'W', None, None], [None, 'W', None, None, 'W', 'W', None, None, None, 'W'], [None, None, None, 'W', None, None, None, None, None, None], [None, None, None, None, 'W', None, 'W', None, None, None], [None, 'W', None, None, None, None, 'W', None, 'W', None], [None, 'W', None, None, 'B', None, None, None, None, None], ['W', None, None, None, None, 'B', None, None, None, None], [None, None, None, None, None, None, None, 'B', None, 'B']]}
from collections import deque

# State encoding over the 4 directions U,R,D,L.
U, R, D, L = 0, 1, 2, 3
DIRS = (U, R, D, L)
OPP = (D, L, U, R)

OFF = 0
UD = 1
LR = 2
UR = 3
UL = 4
DR = 5
DL = 6

STATE_EDGES = [
    0,                  # OFF
    (1 << U) | (1 << D),  # UD
    (1 << L) | (1 << R),  # LR
    (1 << U) | (1 << R),  # UR
    (1 << U) | (1 << L),  # UL
    (1 << D) | (1 << R),  # DR
    (1 << D) | (1 << L),  # DL
]
STATE_BITS = [1 << i for i in range(len(STATE_EDGES))]
ALL_STATES_MASK = (1 << len(STATE_EDGES)) - 1
TURN_MASK = STATE_BITS[UR] | STATE_BITS[UL] | STATE_BITS[DR] | STATE_BITS[DL]
STRAIGHT_MASK = STATE_BITS[UD] | STATE_BITS[LR]
ACTIVE_MASK = ALL_STATES_MASK ^ STATE_BITS[OFF]
STATE_IS_TURN = [False, False, False, True, True, True, True]
STRAIGHT_STATE_FOR_DIR = [UD, LR, UD, LR]

CONNECT_MASK = [0, 0, 0, 0]
TURN_CONNECT_MASK = [0, 0, 0, 0]
BLACK_STATES_INCLUDE = [0, 0, 0, 0]
EDGE_SUPPORT_MASK = [[0] * len(STATE_EDGES) for _ in DIRS]

for s, em in enumerate(STATE_EDGES):
    for d in DIRS:
        if (em >> d) & 1:
            CONNECT_MASK[d] |= STATE_BITS[s]
            if STATE_IS_TURN[s]:
                TURN_CONNECT_MASK[d] |= STATE_BITS[s]

for d in DIRS:
    for s, em in enumerate(STATE_EDGES):
        need = (em >> d) & 1
        mask = 0
        for t, tem in enumerate(STATE_EDGES):
            if ((tem >> OPP[d]) & 1) == need:
                mask |= STATE_BITS[t]
        EDGE_SUPPORT_MASK[d][s] = mask

for s in (UR, UL, DR, DL):
    em = STATE_EDGES[s]
    for d in DIRS:
        if (em >> d) & 1:
            BLACK_STATES_INCLUDE[d] |= STATE_BITS[s]


def solve(observation):
    data = observation['data']
    n = len(data)
    m = n * n

    clues = [None] * m
    neighbors = [[-1, -1, -1, -1] for _ in range(m)]
    clue_indices = []

    def idx_of(r, c):
        return r * n + c

    def rc_of(idx):
        return divmod(idx, n)

    for r in range(n):
        for c in range(n):
            idx = idx_of(r, c)
            if r > 0:
                neighbors[idx][U] = idx_of(r - 1, c)
            if c + 1 < n:
                neighbors[idx][R] = idx_of(r, c + 1)
            if r + 1 < n:
                neighbors[idx][D] = idx_of(r + 1, c)
            if c > 0:
                neighbors[idx][L] = idx_of(r, c - 1)
            clues[idx] = data[r][c]
            if clues[idx] is not None:
                clue_indices.append(idx)

    # Precompute initial feasible domain by bounds and clue type.
    initial_domains = [0] * m
    weight = [0] * m

    for idx in range(m):
        clue = clues[idx]
        dom = 0
        for s, em in enumerate(STATE_EDGES):
            if clue == 'W' and s not in (UD, LR):
                continue
            if clue == 'B' and not STATE_IS_TURN[s]:
                continue
            if clue is None and s == OFF:
                dom |= STATE_BITS[s]
                continue
            ok = True
            for d in DIRS:
                if ((em >> d) & 1) and neighbors[idx][d] == -1:
                    ok = False
                    break
            if ok:
                dom |= STATE_BITS[s]
        initial_domains[idx] = dom

        r, c = rc_of(idx)
        w = 0
        if clue == 'W':
            w += 10
        elif clue == 'B':
            w += 12
        for nb in neighbors[idx]:
            if nb != -1 and clues[nb] is not None:
                w += 2
        if r == 0 or r == n - 1 or c == 0 or c == n - 1:
            w += 1
        weight[idx] = w

    def iter_states(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def state_supported(idx, s, domains):
        em = STATE_EDGES[s]

        # Generic edge-consistency.
        for d in DIRS:
            nb = neighbors[idx][d]
            inc = (em >> d) & 1
            if nb == -1:
                if inc:
                    return False
            else:
                if domains[nb] & EDGE_SUPPORT_MASK[d][s] == 0:
                    return False

        clue = clues[idx]

        # Own clue semantics.
        if clue == 'W':
            if s not in (UD, LR):
                return False
            if s == LR:
                lnb = neighbors[idx][L]
                rnb = neighbors[idx][R]
                if lnb == -1 or rnb == -1:
                    return False
                if domains[lnb] & CONNECT_MASK[R] == 0:
                    return False
                if domains[rnb] & CONNECT_MASK[L] == 0:
                    return False
                if (domains[lnb] & TURN_CONNECT_MASK[R]) == 0 and (domains[rnb] & TURN_CONNECT_MASK[L]) == 0:
                    return False
            else:
                unb = neighbors[idx][U]
                dnb = neighbors[idx][D]
                if unb == -1 or dnb == -1:
                    return False
                if domains[unb] & CONNECT_MASK[D] == 0:
                    return False
                if domains[dnb] & CONNECT_MASK[U] == 0:
                    return False
                if (domains[unb] & TURN_CONNECT_MASK[D]) == 0 and (domains[dnb] & TURN_CONNECT_MASK[U]) == 0:
                    return False

        elif clue == 'B':
            if not STATE_IS_TURN[s]:
                return False
            for d in DIRS:
                if (em >> d) & 1:
                    nb = neighbors[idx][d]
                    if nb == -1:
                        return False
                    req = STATE_BITS[STRAIGHT_STATE_FOR_DIR[d]]
                    if domains[nb] & req == 0:
                        return False

        # Constraints coming from adjacent clue vertices.
        for d in DIRS:
            if not ((em >> d) & 1):
                continue
            nb = neighbors[idx][d]
            if nb == -1:
                return False

            nclue = clues[nb]
            if nclue == 'B':
                # A vertex adjacent to a black clue and connected to it must be straight.
                if s != STRAIGHT_STATE_FOR_DIR[d]:
                    return False

                need_at_black = OPP[d]
                bdom = domains[nb] & BLACK_STATES_INCLUDE[need_at_black]
                ok = False
                for bs in iter_states(bdom):
                    bem = STATE_EDGES[bs]
                    for bd in DIRS:
                        if bd != need_at_black and ((bem >> bd) & 1):
                            other_nb = neighbors[nb][bd]
                            if other_nb != -1 and (domains[other_nb] & STATE_BITS[STRAIGHT_STATE_FOR_DIR[bd]]) != 0:
                                ok = True
                                break
                    if ok:
                        break
                if not ok:
                    return False

            elif nclue == 'W':
                axis_state = LR if d in (L, R) else UD
                if domains[nb] & STATE_BITS[axis_state] == 0:
                    return False

                # The other side of the white clue lies in the same absolute direction d.
                other_nb = neighbors[nb][d]
                if other_nb == -1:
                    return False

                # If current vertex is not a turn, the other side must be.
                req_mask = CONNECT_MASK[OPP[d]] if STATE_IS_TURN[s] else TURN_CONNECT_MASK[OPP[d]]
                if domains[other_nb] & req_mask == 0:
                    return False

        return True

    def all_clues_connected_in_possible_graph(domains):
        if not clue_indices:
            return True

        # BFS over edges still possibly used.
        start = clue_indices[0]
        q = deque([start])
        seen = {start}

        while q:
            cur = q.popleft()
            for d in DIRS:
                nb = neighbors[cur][d]
                if nb == -1:
                    continue
                if domains[cur] & CONNECT_MASK[d] and domains[nb] & CONNECT_MASK[OPP[d]]:
                    if nb not in seen and (domains[nb] & ACTIVE_MASK):
                        seen.add(nb)
                        q.append(nb)

        for ci in clue_indices:
            if ci not in seen:
                return False
        return True

    def has_premature_closed_cycle(domains):
        forced_adj = [[] for _ in range(m)]
        forced_degree = [0] * m

        for idx in range(m):
            for d in (R, D):
                nb = neighbors[idx][d]
                if nb == -1:
                    continue
                all_inc_here = True
                all_inc_there = True
                for s in iter_states(domains[idx]):
                    if ((STATE_EDGES[s] >> d) & 1) == 0:
                        all_inc_here = False
                        break
                for s in iter_states(domains[nb]):
                    if ((STATE_EDGES[s] >> OPP[d]) & 1) == 0:
                        all_inc_there = False
                        break
                if all_inc_here and all_inc_there:
                    forced_adj[idx].append(nb)
                    forced_adj[nb].append(idx)
                    forced_degree[idx] += 1
                    forced_degree[nb] += 1

        seen = [False] * m
        clue_set = set(clue_indices)

        for i in range(m):
            if seen[i] or not forced_adj[i]:
                continue
            comp = []
            stack = [i]
            seen[i] = True
            while stack:
                v = stack.pop()
                comp.append(v)
                for w in forced_adj[v]:
                    if not seen[w]:
                        seen[w] = True
                        stack.append(w)

            if all(forced_degree[v] == 2 for v in comp):
                comp_set = set(comp)
                if clue_set - comp_set:
                    return True

        return False

    def propagate(domains):
        changed = True
        order = sorted(range(m), key=lambda i: (-weight[i], i))
        while changed:
            changed = False

            for idx in order:
                dom = domains[idx]
                new_dom = 0
                for s in iter_states(dom):
                    if state_supported(idx, s, domains):
                        new_dom |= STATE_BITS[s]
                if new_dom == 0:
                    return None
                if new_dom != dom:
                    domains[idx] = new_dom
                    changed = True

            if not all_clues_connected_in_possible_graph(domains):
                return None
            if has_premature_closed_cycle(domains):
                return None

        return domains

    def is_solved(domains):
        return all((d & (d - 1)) == 0 for d in domains)

    def choose_var(domains):
        best = None
        best_key = None
        for idx, dom in enumerate(domains):
            bc = dom.bit_count()
            if bc <= 1:
                continue
            key = (bc, -weight[idx], idx)
            if best_key is None or key < best_key:
                best_key = key
                best = idx
        return best

    def ordered_states(idx, dom):
        clue = clues[idx]
        states = list(iter_states(dom))

        def key(s):
            # Active before OFF; clue variables prefer straights before turns only where it matters.
            off_penalty = 1 if s == OFF else 0
            turn_penalty = 0
            if clue == 'W':
                turn_penalty = 0
            elif clue == 'B':
                turn_penalty = 0
            else:
                turn_penalty = 0 if STATE_IS_TURN[s] else 1
            return (off_penalty, turn_penalty, s)

        states.sort(key=key)
        return states

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if is_solved(domains):
            if validate_solution(domains):
                return domains
            return None

        idx = choose_var(domains)
        if idx is None:
            return None

        for s in ordered_states(idx, domains[idx]):
            nd = domains[:]
            nd[idx] = STATE_BITS[s]
            ans = search(nd)
            if ans is not None:
                return ans
        return None

    def validate_solution(domains):
        used_adj = [[] for _ in range(m)]
        used_vertices = set()

        for idx in range(m):
            s = (domains[idx].bit_length() - 1)
            em = STATE_EDGES[s]
            deg = 0
            for d in DIRS:
                if (em >> d) & 1:
                    nb = neighbors[idx][d]
                    if nb == -1:
                        return False
                    ns = (domains[nb].bit_length() - 1)
                    if ((STATE_EDGES[ns] >> OPP[d]) & 1) == 0:
                        return False
                    deg += 1
                    if nb not in used_adj[idx]:
                        used_adj[idx].append(nb)
            if clues[idx] is not None and s == OFF:
                return False
            if s == OFF:
                if deg != 0:
                    return False
            else:
                if deg != 2:
                    return False
                used_vertices.add(idx)

        if not clue_indices:
            return False
        if not all(ci in used_vertices for ci in clue_indices):
            return False
        if not used_vertices:
            return False

        start = min(used_vertices)
        seen = set([start])
        q = deque([start])
        while q:
            v = q.popleft()
            for w in used_adj[v]:
                if w not in seen:
                    seen.add(w)
                    q.append(w)

        return seen == used_vertices

    def extract_path(domains):
        used_adj = [[] for _ in range(m)]
        used_vertices = []

        for idx in range(m):
            s = (domains[idx].bit_length() - 1)
            em = STATE_EDGES[s]
            if s != OFF:
                used_vertices.append(idx)
            for d in DIRS:
                if (em >> d) & 1:
                    nb = neighbors[idx][d]
                    if nb != -1 and nb not in used_adj[idx]:
                        used_adj[idx].append(nb)

        start = min(used_vertices)
        path = [rc_of(start)]
        prev = -1
        cur = start

        while True:
            nxts = used_adj[cur]
            if len(nxts) != 2:
                return None
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append(rc_of(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break

        return path

    ans_domains = search(initial_domains[:])
    if ans_domains is None:
        return "No Solution"

    path = extract_path(ans_domains)
    return path if path is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

