from itertools import product
import sys

# Akari / Light Up solver with strong propagation and guided search.
# Board encoding:
#   None -> white cell
#   -1   -> unnumbered black cell
#   0..4 -> numbered black cell

class Puzzle:
    def __init__(self, data):
        self.data = data
        self.n = len(data)

        self.whites = []
        self.white_index = {}
        for r in range(self.n):
            for c in range(self.n):
                if data[r][c] is None:
                    idx = len(self.whites)
                    self.whites.append((r, c))
                    self.white_index[(r, c)] = idx
        self.wcount = len(self.whites)

        self.row_segments = []
        self.col_segments = []
        self.row_seg_id = [-1] * self.wcount
        self.col_seg_id = [-1] * self.wcount

        self._build_segments()
        self.black_constraints = []
        self.adjacent_black_of_cell = [[] for _ in range(self.wcount)]
        self._build_black_constraints()

        # Impact heuristic: how much a bulb here influences the board.
        self.impact = [0] * self.wcount
        for i in range(self.wcount):
            rs = self.row_segments[self.row_seg_id[i]]
            cs = self.col_segments[self.col_seg_id[i]]
            self.impact[i] = (len(rs) + len(cs) - 1) + 2 * len(self.adjacent_black_of_cell[i])

    def _build_segments(self):
        # Row segments
        for r in range(self.n):
            current = []
            for c in range(self.n):
                if self.data[r][c] is None:
                    current.append(self.white_index[(r, c)])
                else:
                    if current:
                        sid = len(self.row_segments)
                        self.row_segments.append(current)
                        for i in current:
                            self.row_seg_id[i] = sid
                        current = []
            if current:
                sid = len(self.row_segments)
                self.row_segments.append(current)
                for i in current:
                    self.row_seg_id[i] = sid

        # Column segments
        for c in range(self.n):
            current = []
            for r in range(self.n):
                if self.data[r][c] is None:
                    current.append(self.white_index[(r, c)])
                else:
                    if current:
                        sid = len(self.col_segments)
                        self.col_segments.append(current)
                        for i in current:
                            self.col_seg_id[i] = sid
                        current = []
            if current:
                sid = len(self.col_segments)
                self.col_segments.append(current)
                for i in current:
                    self.col_seg_id[i] = sid

    def _build_black_constraints(self):
        for r in range(self.n):
            for c in range(self.n):
                v = self.data[r][c]
                if isinstance(v, int) and v >= 0:
                    neigh = []
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < self.n and 0 <= cc < self.n and self.data[rr][cc] is None:
                            neigh.append(self.white_index[(rr, cc)])
                    bidx = len(self.black_constraints)
                    self.black_constraints.append((v, tuple(neigh)))
                    for i in neigh:
                        self.adjacent_black_of_cell[i].append(bidx)


class State:
    __slots__ = ("status", "row_bulbs", "col_bulbs", "black_bulbs", "black_unknown")

    def __init__(self, puzzle):
        self.status = [-1] * puzzle.wcount   # -1 unknown, 0 empty, 1 bulb
        self.row_bulbs = [0] * len(puzzle.row_segments)
        self.col_bulbs = [0] * len(puzzle.col_segments)
        self.black_bulbs = [0] * len(puzzle.black_constraints)
        self.black_unknown = [len(neigh) for _, neigh in puzzle.black_constraints]

    def clone(self):
        s = State.__new__(State)
        s.status = self.status.copy()
        s.row_bulbs = self.row_bulbs.copy()
        s.col_bulbs = self.col_bulbs.copy()
        s.black_bulbs = self.black_bulbs.copy()
        s.black_unknown = self.black_unknown.copy()
        return s


def assign(puzzle, state, i, val):
    cur = state.status[i]
    if cur == val:
        return False
    if cur != -1:
        return None

    if val == 1:
        rs = puzzle.row_seg_id[i]
        cs = puzzle.col_seg_id[i]
        if state.row_bulbs[rs] > 0 or state.col_bulbs[cs] > 0:
            return None
        state.status[i] = 1
        state.row_bulbs[rs] += 1
        state.col_bulbs[cs] += 1
        for b in puzzle.adjacent_black_of_cell[i]:
            state.black_unknown[b] -= 1
            state.black_bulbs[b] += 1
    else:
        state.status[i] = 0
        for b in puzzle.adjacent_black_of_cell[i]:
            state.black_unknown[b] -= 1
    return True


def can_be_bulb(puzzle, state, i):
    st = state.status[i]
    if st == 0:
        return False
    if st == 1:
        return True

    if state.row_bulbs[puzzle.row_seg_id[i]] > 0:
        return False
    if state.col_bulbs[puzzle.col_seg_id[i]] > 0:
        return False

    for b in puzzle.adjacent_black_of_cell[i]:
        req, _ = puzzle.black_constraints[b]
        bulbs = state.black_bulbs[b]
        unk = state.black_unknown[b]
        # i is currently unknown and adjacent to b
        if bulbs + 1 > req:
            return False
        if bulbs + 1 + (unk - 1) < req:
            return False
    return True


def can_be_empty(puzzle, state, i):
    st = state.status[i]
    if st == 1:
        return False
    if st == 0:
        return True

    for b in puzzle.adjacent_black_of_cell[i]:
        req, _ = puzzle.black_constraints[b]
        bulbs = state.black_bulbs[b]
        unk = state.black_unknown[b]
        # i is currently unknown and adjacent to b
        if bulbs > req:
            return False
        if bulbs + (unk - 1) < req:
            return False
    return True


def is_lit(puzzle, state, i):
    return state.row_bulbs[puzzle.row_seg_id[i]] > 0 or state.col_bulbs[puzzle.col_seg_id[i]] > 0


def possible_sources(puzzle, state, i):
    rsid = puzzle.row_seg_id[i]
    csid = puzzle.col_seg_id[i]
    out = []

    for j in puzzle.row_segments[rsid]:
        if can_be_bulb(puzzle, state, j):
            out.append(j)

    for j in puzzle.col_segments[csid]:
        if j != i and can_be_bulb(puzzle, state, j):
            out.append(j)

    return out


def constraint_patterns(puzzle, state, bidx):
    req, neigh = puzzle.black_constraints[bidx]
    m = len(neigh)
    patterns = []

    if m == 0:
        return [tuple()] if req == 0 else []

    affected = set()
    for i in neigh:
        for b in puzzle.adjacent_black_of_cell[i]:
            affected.add(b)

    for mask in range(1 << m):
        if mask.bit_count() != req:
            continue

        temp_bulbs = {}
        temp_unk = {}
        ok = True

        for pos, i in enumerate(neigh):
            bit = (mask >> pos) & 1
            st = state.status[i]

            if st == 1 and bit == 0:
                ok = False
                break
            if st == 0 and bit == 1:
                ok = False
                break

            if st == -1:
                if bit:
                    if not can_be_bulb(puzzle, state, i):
                        ok = False
                        break
                else:
                    if not can_be_empty(puzzle, state, i):
                        ok = False
                        break

                for b in puzzle.adjacent_black_of_cell[i]:
                    if b not in temp_bulbs:
                        temp_bulbs[b] = state.black_bulbs[b]
                        temp_unk[b] = state.black_unknown[b]
                    temp_unk[b] -= 1
                    if bit:
                        temp_bulbs[b] += 1

        if not ok:
            continue

        for b in affected:
            bulbs = temp_bulbs.get(b, state.black_bulbs[b])
            unk = temp_unk.get(b, state.black_unknown[b])
            req2, _ = puzzle.black_constraints[b]
            if bulbs > req2 or bulbs + unk < req2:
                ok = False
                break

        if ok:
            patterns.append(tuple((mask >> pos) & 1 for pos in range(m)))

    return patterns


def propagate(puzzle, state):
    while True:
        progress = False

        # Rule 1: if a segment already has a bulb, all other cells in that segment are empty.
        for sid, cells in enumerate(puzzle.row_segments):
            if state.row_bulbs[sid] > 0:
                for i in cells:
                    if state.status[i] == -1:
                        res = assign(puzzle, state, i, 0)
                        if res is None:
                            return False
                        progress |= res

        for sid, cells in enumerate(puzzle.col_segments):
            if state.col_bulbs[sid] > 0:
                for i in cells:
                    if state.status[i] == -1:
                        res = assign(puzzle, state, i, 0)
                        if res is None:
                            return False
                        progress |= res

        # Rule 2: numbered black constraints, using full local pattern filtering.
        for bidx, (req, neigh) in enumerate(puzzle.black_constraints):
            bulbs = state.black_bulbs[bidx]
            unk = state.black_unknown[bidx]

            if bulbs > req or bulbs + unk < req:
                return False
            if unk == 0:
                if bulbs != req:
                    return False
                continue

            pats = constraint_patterns(puzzle, state, bidx)
            if not pats:
                return False

            for pos, i in enumerate(neigh):
                if state.status[i] != -1:
                    continue
                v = pats[0][pos]
                if all(p[pos] == v for p in pats[1:]):
                    res = assign(puzzle, state, i, 1 if v else 0)
                    if res is None:
                        return False
                    progress |= res

        # Rule 3: per-cell domain check.
        for i in range(puzzle.wcount):
            if state.status[i] == -1:
                pb = can_be_bulb(puzzle, state, i)
                pe = can_be_empty(puzzle, state, i)
                if not pb and not pe:
                    return False
                if pb and not pe:
                    res = assign(puzzle, state, i, 1)
                    if res is None:
                        return False
                    progress |= res
                elif pe and not pb:
                    res = assign(puzzle, state, i, 0)
                    if res is None:
                        return False
                    progress |= res

        # Rule 4: every white cell must be lightable; singleton source => force bulb.
        for i in range(puzzle.wcount):
            if is_lit(puzzle, state, i):
                continue
            src = possible_sources(puzzle, state, i)
            if not src:
                return False
            if len(src) == 1:
                res = assign(puzzle, state, src[0], 1)
                if res is None:
                    return False
                progress |= res

        # Rule 5: if some unlit cell in a row segment can only be lit from that row segment,
        # then that row segment must contain a bulb. Same for columns.
        for sid, cells in enumerate(puzzle.row_segments):
            if state.row_bulbs[sid] > 0:
                continue

            row_hosts = [i for i in cells if can_be_bulb(puzzle, state, i)]
            need_row = False
            for i in cells:
                if is_lit(puzzle, state, i):
                    continue
                has_col_source = False
                for j in puzzle.col_segments[puzzle.col_seg_id[i]]:
                    if puzzle.row_seg_id[j] != sid and can_be_bulb(puzzle, state, j):
                        has_col_source = True
                        break
                if not has_col_source:
                    need_row = True
                    break

            if need_row:
                if not row_hosts:
                    return False
                if len(row_hosts) == 1:
                    res = assign(puzzle, state, row_hosts[0], 1)
                    if res is None:
                        return False
                    progress |= res

        for sid, cells in enumerate(puzzle.col_segments):
            if state.col_bulbs[sid] > 0:
                continue

            col_hosts = [i for i in cells if can_be_bulb(puzzle, state, i)]
            need_col = False
            for i in cells:
                if is_lit(puzzle, state, i):
                    continue
                has_row_source = False
                for j in puzzle.row_segments[puzzle.row_seg_id[i]]:
                    if puzzle.col_seg_id[j] != sid and can_be_bulb(puzzle, state, j):
                        has_row_source = True
                        break
                if not has_row_source:
                    need_col = True
                    break

            if need_col:
                if not col_hosts:
                    return False
                if len(col_hosts) == 1:
                    res = assign(puzzle, state, col_hosts[0], 1)
                    if res is None:
                        return False
                    progress |= res

        if not progress:
            return True


def solved_complete(puzzle, state):
    for bidx, (req, _) in enumerate(puzzle.black_constraints):
        if state.black_bulbs[bidx] != req:
            return False
    for i in range(puzzle.wcount):
        if not is_lit(puzzle, state, i):
            return False
    return True


def choose_branch(puzzle, state):
    # 1) Most constrained numbered black cell.
    best = None
    best_len = 10**9
    best_score = None

    for bidx, (req, neigh) in enumerate(puzzle.black_constraints):
        if state.black_unknown[bidx] == 0:
            continue
        pats = constraint_patterns(puzzle, state, bidx)
        if 1 < len(pats) < best_len:
            best = ("black", bidx, pats)
            best_len = len(pats)
            best_score = sum(puzzle.impact[i] for i in neigh)
            if best_len == 2:
                pass
        elif len(pats) == best_len and len(pats) > 1:
            score = sum(puzzle.impact[i] for i in neigh)
            if score > best_score:
                best = ("black", bidx, pats)
                best_score = score

    if best is not None:
        return best

    # 2) Necessary segment with few candidate hosts.
    seg_best = None
    seg_best_len = 10**9
    seg_best_score = None

    for sid, cells in enumerate(puzzle.row_segments):
        if state.row_bulbs[sid] > 0:
            continue
        hosts = [i for i in cells if can_be_bulb(puzzle, state, i)]
        if not hosts:
            continue
        need = False
        for i in cells:
            if is_lit(puzzle, state, i):
                continue
            has_other = False
            for j in puzzle.col_segments[puzzle.col_seg_id[i]]:
                if puzzle.row_seg_id[j] != sid and can_be_bulb(puzzle, state, j):
                    has_other = True
                    break
            if not has_other:
                need = True
                break
        if need and 1 < len(hosts) < seg_best_len:
            seg_best = ("segment", "row", sid, hosts)
            seg_best_len = len(hosts)
            seg_best_score = sum(puzzle.impact[i] for i in hosts)
        elif need and len(hosts) == seg_best_len:
            score = sum(puzzle.impact[i] for i in hosts)
            if score > seg_best_score:
                seg_best = ("segment", "row", sid, hosts)
                seg_best_score = score

    for sid, cells in enumerate(puzzle.col_segments):
        if state.col_bulbs[sid] > 0:
            continue
        hosts = [i for i in cells if can_be_bulb(puzzle, state, i)]
        if not hosts:
            continue
        need = False
        for i in cells:
            if is_lit(puzzle, state, i):
                continue
            has_other = False
            for j in puzzle.row_segments[puzzle.row_seg_id[i]]:
                if puzzle.col_seg_id[j] != sid and can_be_bulb(puzzle, state, j):
                    has_other = True
                    break
            if not has_other:
                need = True
                break
        if need and 1 < len(hosts) < seg_best_len:
            seg_best = ("segment", "col", sid, hosts)
            seg_best_len = len(hosts)
            seg_best_score = sum(puzzle.impact[i] for i in hosts)
        elif need and len(hosts) == seg_best_len:
            score = sum(puzzle.impact[i] for i in hosts)
            if score > seg_best_score:
                seg_best = ("segment", "col", sid, hosts)
                seg_best_score = score

    if seg_best is not None:
        return seg_best

    # 3) Unlit cell with fewest possible sources.
    cover_best = None
    cover_best_len = 10**9
    cover_best_score = None

    for i in range(puzzle.wcount):
        if is_lit(puzzle, state, i):
            continue
        src = possible_sources(puzzle, state, i)
        if 1 < len(src) < cover_best_len:
            cover_best = ("cover", i, src)
            cover_best_len = len(src)
            cover_best_score = sum(puzzle.impact[j] for j in src)
        elif len(src) == cover_best_len and len(src) > 1:
            score = sum(puzzle.impact[j] for j in src)
            if score > cover_best_score:
                cover_best = ("cover", i, src)
                cover_best_score = score

    if cover_best is not None:
        return cover_best

    # 4) Fallback: unknown cell with strong impact, branch bulb-first.
    best_cell = None
    best_cell_score = -1
    for i in range(puzzle.wcount):
        if state.status[i] == -1:
            pb = can_be_bulb(puzzle, state, i)
            pe = can_be_empty(puzzle, state, i)
            if pb and pe and puzzle.impact[i] > best_cell_score:
                best_cell = i
                best_cell_score = puzzle.impact[i]

    if best_cell is not None:
        return ("cell", best_cell)

    return None


def search(puzzle, state):
    if not propagate(puzzle, state):
        return None

    if solved_complete(puzzle, state):
        return state

    branch = choose_branch(puzzle, state)
    if branch is None:
        return state if solved_complete(puzzle, state) else None

    kind = branch[0]

    if kind == "black":
        _, bidx, pats = branch
        neigh = puzzle.black_constraints[bidx][1]

        # Prefer patterns that place bulbs on higher-impact cells.
        def pat_score(pat):
            return sum(puzzle.impact[neigh[pos]] for pos, bit in enumerate(pat) if bit)

        for pat in sorted(pats, key=pat_score, reverse=True):
            new_state = state.clone()
            ok = True
            for pos, i in enumerate(neigh):
                val = 1 if pat[pos] else 0
                res = assign(puzzle, new_state, i, val)
                if res is None:
                    ok = False
                    break
            if ok:
                ans = search(puzzle, new_state)
                if ans is not None:
                    return ans
        return None

    if kind == "segment":
        _, axis, sid, hosts = branch
        hosts = sorted(hosts, key=lambda i: puzzle.impact[i], reverse=True)
        for i in hosts:
            new_state = state.clone()
            res = assign(puzzle, new_state, i, 1)
            if res is None:
                continue
            ans = search(puzzle, new_state)
            if ans is not None:
                return ans
        return None

    if kind == "cover":
        _, target, src = branch
        src = sorted(src, key=lambda i: puzzle.impact[i], reverse=True)
        for i in src:
            new_state = state.clone()
            res = assign(puzzle, new_state, i, 1)
            if res is None:
                continue
            ans = search(puzzle, new_state)
            if ans is not None:
                return ans
        return None

    if kind == "cell":
        _, i = branch
        options = []
        if can_be_bulb(puzzle, state, i):
            options.append(1)
        if can_be_empty(puzzle, state, i):
            options.append(0)

        # Prefer bulb first when it has strong impact.
        for val in options:
            new_state = state.clone()
            res = assign(puzzle, new_state, i, val)
            if res is None:
                continue
            ans = search(puzzle, new_state)
            if ans is not None:
                return ans
        return None

    return None


def build_answer_grid(puzzle, state):
    grid = [[None for _ in range(puzzle.n)] for _ in range(puzzle.n)]
    for i, (r, c) in enumerate(puzzle.whites):
        if state.status[i] == 1:
            grid[r][c] = 'B'
    return grid


def solve(observation):
    sys.setrecursionlimit(10000)
    puzzle = Puzzle(observation["data"])
    state = State(puzzle)
    ans = search(puzzle, state)
    if ans is None:
        return "No Solution"
    return str(build_answer_grid(puzzle, ans))


if __name__ == "__main__":
    print(solve(OBSERVATION))

