from collections import deque, defaultdict
import sys

sys.setrecursionlimit(10000)


def solve(observation):
    grid = observation["data"]
    n = len(grid)

    islands = []
    required = []
    pos_to_idx = {}

    for r in range(n):
        for c in range(len(grid[r])):
            v = grid[r][c]
            if v is not None:
                idx = len(islands)
                islands.append((r, c))
                required.append(v)
                pos_to_idx[(r, c)] = idx

    island_count = len(islands)
    if island_count == 0:
        return {}

    edges = []

    # Horizontal visibility edges.
    for r in range(n):
        cols = [c for c in range(len(grid[r])) if grid[r][c] is not None]
        for c1, c2 in zip(cols, cols[1:]):
            a = pos_to_idx[(r, c1)]
            b = pos_to_idx[(r, c2)]
            edges.append(
                {
                    "a": a,
                    "b": b,
                    "p1": (r, c1),
                    "p2": (r, c2),
                    "ori": "H",
                    "cross": [],
                }
            )

    # Vertical visibility edges.
    width = max(len(row) for row in grid)
    for c in range(width):
        rows = [r for r in range(n) if c < len(grid[r]) and grid[r][c] is not None]
        for r1, r2 in zip(rows, rows[1:]):
            a = pos_to_idx[(r1, c)]
            b = pos_to_idx[(r2, c)]
            edges.append(
                {
                    "a": a,
                    "b": b,
                    "p1": (r1, c),
                    "p2": (r2, c),
                    "ori": "V",
                    "cross": [],
                }
            )

    m = len(edges)
    incident = [[] for _ in range(island_count)]
    for ei, e in enumerate(edges):
        incident[e["a"]].append(ei)
        incident[e["b"]].append(ei)

    # Crossing relations.
    horiz = [i for i, e in enumerate(edges) if e["ori"] == "H"]
    vert = [i for i, e in enumerate(edges) if e["ori"] == "V"]
    for hi in horiz:
        hr = edges[hi]["p1"][0]
        hc1 = edges[hi]["p1"][1]
        hc2 = edges[hi]["p2"][1]
        for vi in vert:
            vc = edges[vi]["p1"][1]
            vr1 = edges[vi]["p1"][0]
            vr2 = edges[vi]["p2"][0]
            if vr1 < hr < vr2 and hc1 < vc < hc2:
                edges[hi]["cross"].append(vi)
                edges[vi]["cross"].append(hi)

    initial_lb = [0] * m
    initial_ub = [min(2, required[e["a"]], required[e["b"]]) for e in edges]

    # Quick feasibility check.
    for i in range(island_count):
        if required[i] < 0 or required[i] > sum(initial_ub[e] for e in incident[i]):
            return "No Solution"

    def island_bounds(lb, ub, i):
        l = 0
        u = 0
        for e in incident[i]:
            l += lb[e]
            u += ub[e]
        return l, u

    def other_end(ei, i):
        e = edges[ei]
        return e["b"] if e["a"] == i else e["a"]

    def possible_graph_connected(ub):
        seen = [False] * island_count
        dq = [0]
        seen[0] = True
        while dq:
            i = dq.pop()
            for ei in incident[i]:
                if ub[ei] == 0:
                    continue
                j = other_end(ei, i)
                if not seen[j]:
                    seen[j] = True
                    dq.append(j)
        return all(seen)

    def mandatory_components(lb):
        parent = list(range(island_count))
        rank = [0] * island_count

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        for ei, v in enumerate(lb):
            if v > 0:
                union(edges[ei]["a"], edges[ei]["b"])

        comp_map = {}
        comp_of = [None] * island_count
        for i in range(island_count):
            r = find(i)
            if r not in comp_map:
                comp_map[r] = len(comp_map)
            comp_of[i] = comp_map[r]
        return comp_of, len(comp_map)

    def propagate(lb, ub):
        changed = True
        while changed:
            changed = False

            # Immediate domain sanity.
            for ei in range(m):
                if lb[ei] > ub[ei]:
                    return None

            # Island sum bounds consistency.
            for i in range(island_count):
                L, U = island_bounds(lb, ub, i)
                req = required[i]
                if req < L or req > U:
                    return None

                for ei in incident[i]:
                    otherL = L - lb[ei]
                    otherU = U - ub[ei]
                    new_lb = max(lb[ei], req - otherU)
                    new_ub = min(ub[ei], req - otherL)
                    if new_lb > new_ub:
                        return None
                    if new_lb != lb[ei] or new_ub != ub[ei]:
                        lb[ei] = new_lb
                        ub[ei] = new_ub
                        changed = True

            # Crossing propagation.
            for ei in range(m):
                if lb[ei] > 0:
                    for fj in edges[ei]["cross"]:
                        if lb[fj] > 0:
                            return None
                        if ub[fj] != 0:
                            ub[fj] = 0
                            changed = True

            # If something can no longer exist, keep domains sane.
            for ei in range(m):
                if ub[ei] == 0 and lb[ei] != 0:
                    return None

            # Graph using possible edges must remain connected.
            if not possible_graph_connected(ub):
                return None

            # Mandatory-component rule:
            # every current positive component must still have an external possible bridge
            # unless it already contains all islands. If exactly one such bridge exists, force it.
            comp_of, comp_count = mandatory_components(lb)
            if comp_count > 1:
                outgoing = defaultdict(set)
                for ei, e in enumerate(edges):
                    if ub[ei] == 0:
                        continue
                    ca = comp_of[e["a"]]
                    cb = comp_of[e["b"]]
                    if ca != cb:
                        outgoing[ca].add(ei)
                        outgoing[cb].add(ei)

                for comp_id in range(comp_count):
                    outs = outgoing.get(comp_id, set())
                    if not outs:
                        return None
                    if len(outs) == 1:
                        only = next(iter(outs))
                        if lb[only] < 1:
                            lb[only] = 1
                            if lb[only] > ub[only]:
                                return None
                            changed = True

        return lb, ub

    def final_check(sol):
        for i in range(island_count):
            if sum(sol[ei] for ei in incident[i]) != required[i]:
                return False

        # Connected positive network.
        seen = [False] * island_count
        dq = [0]
        seen[0] = True
        while dq:
            i = dq.pop()
            for ei in incident[i]:
                if sol[ei] <= 0:
                    continue
                j = other_end(ei, i)
                if not seen[j]:
                    seen[j] = True
                    dq.append(j)
        if not all(seen):
            return False

        # Crossing check.
        for ei in range(m):
            if sol[ei] > 0:
                for fj in edges[ei]["cross"]:
                    if sol[fj] > 0:
                        return False

        return True

    def endpoint_pressure(lb, ub, island_idx):
        L, U = island_bounds(lb, ub, island_idx)
        if U == L:
            return 1.0
        return (required[island_idx] - L) / (U - L)

    def choose_edge(lb, ub):
        best = None
        best_key = None
        for ei in range(m):
            if lb[ei] == ub[ei]:
                continue
            e = edges[ei]
            size = ub[ei] - lb[ei]
            impact = len(edges[ei]["cross"]) + len(incident[e["a"]]) + len(incident[e["b"]])
            pressure = endpoint_pressure(lb, ub, e["a"]) + endpoint_pressure(lb, ub, e["b"])
            key = (size, -impact, -pressure)
            if best_key is None or key < best_key:
                best_key = key
                best = ei
        return best

    def value_order(ei, lb, ub):
        vals = list(range(lb[ei], ub[ei] + 1))
        e = edges[ei]
        pressure = endpoint_pressure(lb, ub, e["a"]) + endpoint_pressure(lb, ub, e["b"])

        if len(vals) == 1:
            return vals
        if len(vals) == 2:
            if pressure >= 1.0:
                return vals[::-1]
            return vals
        # len == 3 for [0,1,2]
        if pressure > 1.34:
            order = [2, 1, 0]
        elif pressure < 0.66:
            order = [0, 1, 2]
        else:
            order = [1, 2, 0]
        return [v for v in order if lb[ei] <= v <= ub[ei]]

    seen_states = set()

    def dfs(lb, ub):
        state = propagate(lb[:], ub[:])
        if state is None:
            return None
        lb, ub = state

        key = (tuple(lb), tuple(ub))
        if key in seen_states:
            return None
        seen_states.add(key)

        complete = True
        for ei in range(m):
            if lb[ei] != ub[ei]:
                complete = False
                break
        if complete:
            if final_check(lb):
                return lb
            return None

        ei = choose_edge(lb, ub)
        if ei is None:
            return None

        for v in value_order(ei, lb, ub):
            lb2 = lb[:]
            ub2 = ub[:]
            lb2[ei] = v
            ub2[ei] = v
            res = dfs(lb2, ub2)
            if res is not None:
                return res
        return None

    solution = dfs(initial_lb, initial_ub)
    if solution is None:
        return "No Solution"

    answer = {}
    for ei, cnt in enumerate(solution):
        if cnt > 0:
            p1 = edges[ei]["p1"]
            p2 = edges[ei]["p2"]
            if p2 < p1:
                p1, p2 = p2, p1
            answer[(p1, p2)] = cnt
    return answer


