    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 2, None, 2, None, 5, None], [4, 5, 4, None, 6, 6, 3], [3, None, 5, None, 6, 6, None], [3, None, None, None, 5, 4, None], [3, None, 6, None, 5, 4, 4], [5, None, 6, None, 4, None, None], [None, 4, None, None, None, 3, 2]]}

from collections import defaultdict, deque

UNKNOWN = -1
WHITE = 0
BLACK = 1


def build_constraints(data):
    h = len(data)
    w = len(data[0]) if h else 0
    constraints = []
    for r in range(h):
        for c in range(w):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    cells.append(rr * w + cc)
            constraints.append((tuple(cells), val))
    return h, w, constraints


def reduce_constraints(values, base_constraints):
    reduced = {}
    for cells, target in base_constraints:
        rem = target
        unknowns = []
        for v in cells:
            cur = values[v]
            if cur == UNKNOWN:
                unknowns.append(v)
            else:
                rem -= cur
        if rem < 0 or rem > len(unknowns):
            return None
        if not unknowns:
            if rem != 0:
                return None
            continue
        key = frozenset(unknowns)
        prev = reduced.get(key)
        if prev is not None and prev != rem:
            return None
        reduced[key] = rem
    return reduced


def derive_closure(constraints_dict):
    allc = dict(constraints_dict)

    def add_constraint(cells, rhs):
        if rhs < 0 or rhs > len(cells):
            return -1
        if not cells:
            return 0 if rhs == 0 else -1
        prev = allc.get(cells)
        if prev is not None:
            return 0 if prev == rhs else -1
        allc[cells] = rhs
        return 1

    changed = True
    while changed:
        changed = False
        items = sorted(allc.items(), key=lambda x: (len(x[0]), tuple(sorted(x[0]))))
        n = len(items)
        for i in range(n):
            A, a = items[i]
            for j in range(i + 1, n):
                B, b = items[j]

                if A == B:
                    if a != b:
                        return None
                    continue

                if len(A) <= len(B) and A.issubset(B):
                    D = B - A
                    status = add_constraint(D, b - a)
                    if status < 0:
                        return None
                    if status > 0:
                        changed = True
                    continue

                I = A & B
                if not I:
                    continue

                A1 = A - I
                B1 = B - I

                low_I = max(0, a - len(A1), b - len(B1))
                high_I = min(len(I), a, b)
                if low_I > high_I:
                    return None

                if low_I == high_I:
                    status = add_constraint(I, low_I)
                    if status < 0:
                        return None
                    if status > 0:
                        changed = True

                low_A1 = a - high_I
                high_A1 = a - low_I
                if low_A1 == high_A1:
                    status = add_constraint(A1, low_A1)
                    if status < 0:
                        return None
                    if status > 0:
                        changed = True

                low_B1 = b - high_I
                high_B1 = b - low_I
                if low_B1 == high_B1:
                    status = add_constraint(B1, low_B1)
                    if status < 0:
                        return None
                    if status > 0:
                        changed = True

    return allc


def propagate(values, base_constraints):
    while True:
        reduced = reduce_constraints(values, base_constraints)
        if reduced is None:
            return None

        closed = derive_closure(reduced)
        if closed is None:
            return None

        progress = False
        for cells, rhs in closed.items():
            if rhs == 0:
                for v in cells:
                    cur = values[v]
                    if cur == UNKNOWN:
                        values[v] = WHITE
                        progress = True
                    elif cur != WHITE:
                        return None
            elif rhs == len(cells):
                for v in cells:
                    cur = values[v]
                    if cur == UNKNOWN:
                        values[v] = BLACK
                        progress = True
                    elif cur != BLACK:
                        return None

        if not progress:
            return closed


def choose_var(values, active_constraints):
    info = {}
    for cells, rhs in active_constraints.items():
        size = len(cells)
        density = rhs / size
        for v in cells:
            if values[v] != UNKNOWN:
                continue
            if v not in info:
                info[v] = [size, 0, 0.0, 0.0]
            rec = info[v]
            if size < rec[0]:
                rec[0] = size
            rec[1] += 1
            rec[2] += 1.0 / size
            rec[3] += density

    if info:
        return min(info, key=lambda v: (info[v][0], -info[v][1], -info[v][2], -info[v][3], v))

    for i, val in enumerate(values):
        if val == UNKNOWN:
            return i
    return None


def branch_order(var, active_constraints):
    num = 0.0
    den = 0
    for cells, rhs in active_constraints.items():
        if var in cells:
            num += rhs / len(cells)
            den += 1
    if den == 0:
        return (WHITE, BLACK)
    p = num / den
    return (BLACK, WHITE) if p >= 0.5 else (WHITE, BLACK)


def connected_components(values, active_constraints):
    cons_items = [(cells, rhs) for cells, rhs in active_constraints.items() if cells]
    var_to_cons = defaultdict(list)
    for ci, (cells, rhs) in enumerate(cons_items):
        for v in cells:
            var_to_cons[v].append(ci)

    unknown_vars = [i for i, x in enumerate(values) if x == UNKNOWN]
    seen_vars = set()
    components = []

    for start in unknown_vars:
        if start in seen_vars:
            continue
        if start not in var_to_cons:
            seen_vars.add(start)
            components.append(([start], {}))
            continue

        q = deque([start])
        seen_vars.add(start)
        comp_vars = set([start])
        comp_cons = set()

        while q:
            v = q.popleft()
            for ci in var_to_cons[v]:
                if ci not in comp_cons:
                    comp_cons.add(ci)
                    cells, rhs = cons_items[ci]
                    for u in cells:
                        if values[u] == UNKNOWN and u not in seen_vars:
                            seen_vars.add(u)
                            comp_vars.add(u)
                            q.append(u)

        comp_dict = {cons_items[ci][0]: cons_items[ci][1] for ci in comp_cons}
        components.append((sorted(comp_vars), comp_dict))

    return components


def analyze_component(comp_vars, comp_constraints):
    gvars = list(comp_vars)
    k = len(gvars)
    idx = {g: i for i, g in enumerate(gvars)}
    base_constraints = [(tuple(idx[v] for v in cells), rhs) for cells, rhs in comp_constraints.items()]

    seen0 = [False] * k
    seen1 = [False] * k
    found_any = False

    def rec(local_values):
        nonlocal found_any
        active = propagate(local_values, base_constraints)
        if active is None:
            return False

        v = choose_var(local_values, active)
        if v is None:
            found_any = True
            for i, val in enumerate(local_values):
                if val == WHITE:
                    seen0[i] = True
                else:
                    seen1[i] = True
            return all(a and b for a, b in zip(seen0, seen1))

        for val in branch_order(v, active):
            nxt = local_values[:]
            nxt[v] = val
            if rec(nxt):
                return True
        return False

    rec([UNKNOWN] * k)

    if not found_any:
        return None

    fixed = {}
    for i, g in enumerate(gvars):
        if seen0[i] and not seen1[i]:
            fixed[g] = WHITE
        elif seen1[i] and not seen0[i]:
            fixed[g] = BLACK
    return fixed


def verify_solution(values, data, h, w):
    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            total = 0
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    total += values[rr * w + cc]
            if total != clue:
                return False
    return True


def dfs(values, base_constraints):
    active = propagate(values, base_constraints)
    if active is None:
        return None

    if all(v != UNKNOWN for v in values):
        return values

    components = connected_components(values, active)
    progress = False

    for comp_vars, comp_constraints in sorted(components, key=lambda x: (len(x[0]), len(x[1]))):
        if not comp_constraints:
            continue
        if len(comp_vars) <= 18:
            fixed = analyze_component(comp_vars, comp_constraints)
            if fixed is None:
                return None
            for v, val in fixed.items():
                if values[v] == UNKNOWN:
                    values[v] = val
                    progress = True

    if progress:
        return dfs(values, base_constraints)

    v = choose_var(values, active)
    if v is None:
        return values

    for val in branch_order(v, active):
        nxt = values[:]
        nxt[v] = val
        sol = dfs(nxt, base_constraints)
        if sol is not None:
            return sol
    return None


def solve(observation):
    data = observation['data']
    h, w, base_constraints = build_constraints(data)
    values = [UNKNOWN] * (h * w)

    sol = dfs(values, base_constraints)
    if sol is None:
        return "No Solution"
    if not verify_solution(sol, data, h, w):
        return "No Solution"

    answer = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if sol[r * w + c] == BLACK else None)
        answer.append(row)
    return str(answer)


