def solve(observation):
    data = observation['data']
    N = len(data)
    if N == 0 or any(len(row) != N for row in data):
        return "No Solution"

    full = (1 << N) - 1

    def idx(r, c):
        return r * N + c

    def rc(i):
        return divmod(i, N)

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def bit_to_value(bit):
        return bit.bit_length()

    rows = [[idx(r, c) for c in range(N)] for r in range(N)]
    cols = [[idx(r, c) for r in range(N)] for c in range(N)]
    houses = rows + cols

    row_of = [i // N for i in range(N * N)]
    col_of = [i % N for i in range(N * N)]

    peers = []
    for i in range(N * N):
        r, c = rc(i)
        p = set(rows[r] + cols[c])
        p.remove(i)
        peers.append(tuple(sorted(p)))

    def is_int_like(x):
        return abs(x - round(x)) < 1e-9

    def is_half_like(x):
        return abs(x * 2 - round(x * 2)) < 1e-9 and not is_int_like(x)

    dot_pairs = set()
    for rr, cc in observation['adjacent']:
        if is_int_like(rr) and is_half_like(cc):
            r = int(round(rr))
            c = int(cc - 0.5)
            if 0 <= r < N and 0 <= c < N - 1:
                a, b = idx(r, c), idx(r, c + 1)
                if a > b:
                    a, b = b, a
                dot_pairs.add((a, b))
        elif is_half_like(rr) and is_int_like(cc):
            r = int(rr - 0.5)
            c = int(round(cc))
            if 0 <= r < N - 1 and 0 <= c < N:
                a, b = idx(r, c), idx(r + 1, c)
                if a > b:
                    a, b = b, a
                dot_pairs.add((a, b))

    REL_CONS = 1
    REL_NONCONS = 0

    support = [[0] * N for _ in range(2)]
    for v in range(1, N + 1):
        i = v - 1
        cons = 0
        if v > 1:
            cons |= 1 << (v - 2)
        if v < N:
            cons |= 1 << v
        noncons = full & ~(cons | (1 << i))
        support[REL_CONS][i] = cons
        support[REL_NONCONS][i] = noncons

    edges = []
    edge_neighbors = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            a = idx(r, c)
            if c + 1 < N:
                b = idx(r, c + 1)
                key = (a, b) if a < b else (b, a)
                rel = REL_CONS if key in dot_pairs else REL_NONCONS
                edges.append((a, b, rel))
                edge_neighbors[a].append((b, rel))
                edge_neighbors[b].append((a, rel))
            if r + 1 < N:
                b = idx(r + 1, c)
                key = (a, b) if a < b else (b, a)
                rel = REL_CONS if key in dot_pairs else REL_NONCONS
                edges.append((a, b, rel))
                edge_neighbors[a].append((b, rel))
                edge_neighbors[b].append((a, rel))

    row_masks = [tuple(rows[r]) for r in range(N)]
    col_masks = [tuple(cols[c]) for c in range(N)]

    def filtered_domain(dom_a, dom_b, rel):
        new_mask = 0
        m = dom_a
        while m:
            bit = m & -m
            v_idx = bit.bit_length() - 1
            if support[rel][v_idx] & dom_b:
                new_mask |= bit
            m ^= bit
        return new_mask

    def apply_basic_house_rules(domains):
        changed = False
        for house in houses:
            assigned_mask = 0
            union_mask = 0
            for cell in house:
                d = domains[cell]
                if d == 0:
                    return None
                union_mask |= d
                if is_single(d):
                    if assigned_mask & d:
                        return None
                    assigned_mask |= d
            if union_mask != full:
                return None
            for cell in house:
                d = domains[cell]
                if not is_single(d):
                    nd = d & ~assigned_mask
                    if nd == 0:
                        return None
                    if nd != d:
                        domains[cell] = nd
                        changed = True
        return changed

    def apply_edge_ac(domains):
        changed = False
        for a, b, rel in edges:
            da = domains[a]
            db = domains[b]
            nda = filtered_domain(da, db, rel)
            if nda == 0:
                return None
            if nda != da:
                domains[a] = nda
                changed = True
                da = nda
            ndb = filtered_domain(db, da, rel)
            if ndb == 0:
                return None
            if ndb != db:
                domains[b] = ndb
                changed = True
        return changed

    def apply_hidden_singles(domains):
        changed = False
        for house in houses:
            for v in range(N):
                bit = 1 << v
                loc = -1
                count = 0
                for cell in house:
                    if domains[cell] & bit:
                        count += 1
                        loc = cell
                        if count > 1:
                            break
                if count == 0:
                    return None
                if count == 1:
                    if domains[loc] != bit:
                        domains[loc] = bit
                        changed = True
        return changed

    def apply_hall_subsets(domains):
        changed = False

        for house in houses:
            cells = list(house)
            m = len(cells)

            # Naked subsets / Hall subsets on cell side
            for sm in range(1, 1 << m):
                k = sm.bit_count()
                if k == m:
                    continue
                union = 0
                for i in range(m):
                    if sm >> i & 1:
                        union |= domains[cells[i]]
                u = union.bit_count()
                if u < k:
                    return None
                if u == k:
                    for i in range(m):
                        if not (sm >> i & 1):
                            cell = cells[i]
                            nd = domains[cell] & ~union
                            if nd == 0:
                                return None
                            if nd != domains[cell]:
                                domains[cell] = nd
                                changed = True

            # Hidden subsets / Hall subsets on value side
            for vmask in range(1, full + 1):
                k = vmask.bit_count()
                if k == N:
                    continue
                support_cells = []
                for cell in cells:
                    if domains[cell] & vmask:
                        support_cells.append(cell)
                cnt = len(support_cells)
                if cnt < k:
                    return None
                if cnt == k:
                    for cell in support_cells:
                        nd = domains[cell] & vmask
                        if nd == 0:
                            return None
                        if nd != domains[cell]:
                            domains[cell] = nd
                            changed = True

        return changed

    def propagate(domains):
        while True:
            any_change = False

            for d in domains:
                if d == 0:
                    return False

            res = apply_basic_house_rules(domains)
            if res is None:
                return False
            any_change |= res

            res = apply_edge_ac(domains)
            if res is None:
                return False
            any_change |= res

            res = apply_hidden_singles(domains)
            if res is None:
                return False
            any_change |= res

            res = apply_hall_subsets(domains)
            if res is None:
                return False
            any_change |= res

            if not any_change:
                break

        # Final validation of all current singleton clashes and edge impossibilities
        for house in houses:
            seen = 0
            for cell in house:
                d = domains[cell]
                if d == 0:
                    return False
                if is_single(d):
                    if seen & d:
                        return False
                    seen |= d

        for a, b, rel in edges:
            if filtered_domain(domains[a], domains[b], rel) == 0:
                return False
            if filtered_domain(domains[b], domains[a], rel) == 0:
                return False

        return True

    domains = [full] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                domains[idx(r, c)] = 1 << (v - 1)

    if not propagate(domains):
        return "No Solution"

    def solved(domains):
        return all(is_single(d) for d in domains)

    def cell_branch_score(cell, domains):
        # Prefer cells tightly constrained by both Latin and adjacency structure.
        return (
            domains[cell].bit_count(),
            -len(edge_neighbors[cell]),
            -sum(1 for p in peers[cell] if not is_single(domains[p]))
        )

    def order_values(cell, domains):
        r = row_of[cell]
        c = col_of[cell]
        bits = []
        m = domains[cell]
        while m:
            bit = m & -m
            v_idx = bit.bit_length() - 1

            row_support = sum(1 for x in row_masks[r] if domains[x] & bit)
            col_support = sum(1 for x in col_masks[c] if domains[x] & bit)

            edge_support = 0
            for nb, rel in edge_neighbors[cell]:
                edge_support += (domains[nb] & support[rel][v_idx]).bit_count()

            # Smaller tuple first: fail-fast on rarer / tighter values
            bits.append(((row_support + col_support, edge_support), bit))
            m ^= bit

        bits.sort()
        return [bit for _, bit in bits]

    def search(domains):
        if not propagate(domains):
            return None
        if solved(domains):
            return domains

        unsolved = [i for i, d in enumerate(domains) if not is_single(d)]
        cell = min(unsolved, key=lambda i: cell_branch_score(i, domains))

        for bit in order_values(cell, domains):
            new_domains = domains[:]
            new_domains[cell] = bit
            result = search(new_domains)
            if result is not None:
                return result
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(bit_to_value(result[idx(r, c)]))
        grid.append(row)
    return str(grid)


