from functools import lru_cache

B = 1
W = 0
U = -1


def line_matches_known(pattern, line):
    for a, b in zip(pattern, line):
        if b != U and a != b:
            return False
    return True


@lru_cache(None)
def valid_patterns(n):
    if n % 2:
        return tuple()
    half = n // 2
    out = []

    def rec(pos, blacks, prev1, prev2, line):
        whites = pos - blacks
        if blacks > half or whites > half:
            return
        rem = n - pos
        if blacks + rem < half or whites + rem < half:
            return
        if pos == n:
            if blacks == half:
                out.append(tuple(line))
            return
        for v in (W, B):
            if prev1 == prev2 == v:
                continue
            line.append(v)
            rec(pos + 1, blacks + (1 if v == B else 0), prev2, v, line)
            line.pop()

    rec(0, 0, None, None, [])
    return tuple(out)


def deduce_from_line(line):
    n = len(line)
    half = n // 2
    out = {}

    def put(i, v):
        cur = out.get(i)
        if cur is not None and cur != v:
            return False
        if line[i] != U and line[i] != v:
            return False
        out[i] = v
        return True

    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a == b != U and c == U:
            if not put(i + 2, 1 - a):
                return None
        if b == c != U and a == U:
            if not put(i, 1 - b):
                return None
        if a == c != U and b == U:
            if not put(i + 1, 1 - a):
                return None

    blacks = sum(v == B for v in line)
    whites = sum(v == W for v in line)
    if blacks > half or whites > half:
        return None

    if blacks == half:
        for i, v in enumerate(line):
            if v == U and not put(i, W):
                return None
    if whites == half:
        for i, v in enumerate(line):
            if v == U and not put(i, B):
                return None

    return out


def apply_local_rules(grid):
    n = len(grid)
    changed = False

    def set_cell(r, c, v):
        nonlocal changed
        cur = grid[r][c]
        if cur == U:
            grid[r][c] = v
            changed = True
            return True
        return cur == v

    for r in range(n):
        ded = deduce_from_line(grid[r])
        if ded is None:
            return False, False
        for c, v in ded.items():
            if not set_cell(r, c, v):
                return False, False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        ded = deduce_from_line(col)
        if ded is None:
            return False, False
        for r, v in ded.items():
            if not set_cell(r, c, v):
                return False, False

    return True, changed


def compute_pos_values(domains, n):
    pos_values = []
    for dom in domains:
        if not dom:
            return None
        vals = [set() for _ in range(n)]
        for p in dom:
            for i, v in enumerate(p):
                vals[i].add(v)
        pos_values.append(vals)
    return pos_values


def prune_uniqueness(domains):
    changed = False
    fixed = {}
    for i, dom in enumerate(domains):
        if len(dom) == 1:
            fixed.setdefault(dom[0], []).append(i)
    for ids in fixed.values():
        if len(ids) > 1:
            return False, False
    used = set(fixed)
    for i, dom in enumerate(domains):
        if len(dom) > 1:
            nd = [p for p in dom if p not in used]
            if not nd:
                return False, False
            if len(nd) != len(dom):
                domains[i] = nd
                changed = True
    return True, changed


def propagate(grid, row_domains, col_domains):
    n = len(grid)

    while True:
        progress = False

        ok, changed = apply_local_rules(grid)
        if not ok:
            return None
        progress |= changed

        col_pos = compute_pos_values(col_domains, n)
        if col_pos is None:
            return None

        for r in range(n):
            dom = row_domains[r]
            nd = []
            for p in dom:
                good = True
                for c, v in enumerate(p):
                    g = grid[r][c]
                    if g != U and g != v:
                        good = False
                        break
                    if v not in col_pos[c][r]:
                        good = False
                        break
                if good:
                    nd.append(p)
            if not nd:
                return None
            if len(nd) != len(dom):
                row_domains[r] = nd
                progress = True

        ok, changed = prune_uniqueness(row_domains)
        if not ok:
            return None
        progress |= changed

        row_pos = compute_pos_values(row_domains, n)
        if row_pos is None:
            return None

        for c in range(n):
            dom = col_domains[c]
            nd = []
            for p in dom:
                good = True
                for r, v in enumerate(p):
                    g = grid[r][c]
                    if g != U and g != v:
                        good = False
                        break
                    if v not in row_pos[r][c]:
                        good = False
                        break
                if good:
                    nd.append(p)
            if not nd:
                return None
            if len(nd) != len(dom):
                col_domains[c] = nd
                progress = True

        ok, changed = prune_uniqueness(col_domains)
        if not ok:
            return None
        progress |= changed

        row_pos = compute_pos_values(row_domains, n)
        col_pos = compute_pos_values(col_domains, n)
        if row_pos is None or col_pos is None:
            return None

        for r in range(n):
            for c in range(n):
                poss = row_pos[r][c] & col_pos[c][r]
                if not poss:
                    return None
                if grid[r][c] == U:
                    if len(poss) == 1:
                        grid[r][c] = next(iter(poss))
                        progress = True
                elif grid[r][c] not in poss:
                    return None

        if not progress:
            break

    return grid, row_domains, col_domains


def is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)


def choose_branch(grid, row_domains, col_domains):
    n = len(grid)
    best = None

    for r, dom in enumerate(row_domains):
        if 1 < len(dom):
            known = sum(grid[r][c] != U for c in range(n))
            key = (len(dom), -known, 0, r)
            if best is None or key < best[0]:
                best = (key, "row", r)

    for c, dom in enumerate(col_domains):
        if 1 < len(dom):
            known = sum(grid[r][c] != U for r in range(n))
            key = (len(dom), -known, 1, c)
            if best is None or key < best[0]:
                best = (key, "col", c)

    return None if best is None else (best[1], best[2])


def search(grid, row_domains, col_domains):
    state = propagate(grid, row_domains, col_domains)
    if state is None:
        return None
    grid, row_domains, col_domains = state

    if is_solved(row_domains, col_domains):
        return [list(row_domains[r][0]) for r in range(len(grid))]

    branch = choose_branch(grid, row_domains, col_domains)
    if branch is None:
        return None

    kind, idx = branch
    n = len(grid)

    if kind == "row":
        for p in row_domains[idx]:
            new_grid = [row[:] for row in grid]
            consistent = True
            for c, v in enumerate(p):
                if new_grid[idx][c] != U and new_grid[idx][c] != v:
                    consistent = False
                    break
                new_grid[idx][c] = v
            if not consistent:
                continue
            new_row_domains = row_domains.copy()
            new_col_domains = col_domains.copy()
            new_row_domains[idx] = [p]
            ans = search(new_grid, new_row_domains, new_col_domains)
            if ans is not None:
                return ans
    else:
        for p in col_domains[idx]:
            new_grid = [row[:] for row in grid]
            consistent = True
            for r, v in enumerate(p):
                if new_grid[r][idx] != U and new_grid[r][idx] != v:
                    consistent = False
                    break
                new_grid[r][idx] = v
            if not consistent:
                continue
            new_row_domains = row_domains.copy()
            new_col_domains = col_domains.copy()
            new_col_domains[idx] = [p]
            ans = search(new_grid, new_row_domains, new_col_domains)
            if ans is not None:
                return ans

    return None


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data:
        return "No Solution"
    n = len(data)
    if n % 2 != 0:
        return "No Solution"
    if any(not isinstance(row, list) or len(row) != n for row in data):
        return "No Solution"

    grid = []
    for row in data:
        out_row = []
        for cell in row:
            if cell == "B":
                out_row.append(B)
            elif cell == "W":
                out_row.append(W)
            elif cell is None:
                out_row.append(U)
            else:
                return "No Solution"
        grid.append(out_row)

    patterns = valid_patterns(n)
    if not patterns:
        return "No Solution"

    row_domains = []
    for r in range(n):
        dom = [p for p in patterns if line_matches_known(p, grid[r])]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        dom = [p for p in patterns if line_matches_known(p, col)]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    ans = search(grid, row_domains, col_domains)
    if ans is None:
        return "No Solution"

    return repr([["B" if v == B else "W" for v in row] for row in ans])


if __name__ == "__main__":
    print(solve(OBSERVATION))

