from itertools import combinations

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    # Build region membership
    reg_cells = {}
    for r in range(n):
        for c in range(n):
            reg_cells.setdefault(region[r][c], []).append(r * n + c)
    reg_ids = sorted(reg_cells)
    if len(reg_ids) != n:
        return "No Solution"
    if any(len(reg_cells[k]) != n for k in reg_ids):
        return "No Solution"

    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    regs = [reg_cells[rid] for rid in reg_ids]
    units = rows + cols + regs

    cell_row = [i // n for i in range(n * n)]
    cell_col = [i % n for i in range(n * n)]
    cell_reg = [0] * (n * n)
    for ridx, cells in enumerate(regs):
        for idx in cells:
            cell_reg[idx] = ridx

    row_others = []
    col_others = []
    reg_others = []
    for i in range(n * n):
        r = cell_row[i]
        c = cell_col[i]
        g = cell_reg[i]
        row_others.append([x for x in rows[r] if x != i])
        col_others.append([x for x in cols[c] if x != i])
        reg_others.append([x for x in regs[g] if x != i])

    full = (1 << n) - 1
    domains0 = [full] * (n * n)

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains0[r * n + c] = 1 << (v - 1)

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def mask_to_val(mask):
        return mask.bit_length()

    # Human-like propagation:
    # 1) basic singles / unit exclusion
    # 2) hidden singles
    # 3) naked subsets (pairs/triples/quads)
    # 4) row/region and col/region intersection eliminations
    def propagate(domains):
        while True:
            changed = False

            # Basic consistency checks + unit deductions
            for unit in units:
                seen_single = 0
                for idx in unit:
                    d = domains[idx]
                    if d == 0:
                        return None
                    if d & (d - 1) == 0:
                        if seen_single & d:
                            return None
                        seen_single |= d

                if seen_single:
                    inv = ~seen_single
                    for idx in unit:
                        d = domains[idx]
                        if d & (d - 1):
                            nd = d & inv
                            if nd == 0:
                                return None
                            if nd != d:
                                domains[idx] = nd
                                changed = True

                # Hidden singles
                counts = [0] * n
                last = [-1] * n
                for idx in unit:
                    d = domains[idx]
                    for b in bit_iter(d):
                        k = b.bit_length() - 1
                        counts[k] += 1
                        last[k] = idx
                for k in range(n):
                    if counts[k] == 0:
                        return None
                    if counts[k] == 1:
                        idx = last[k]
                        m = 1 << k
                        if domains[idx] != m:
                            domains[idx] = m
                            changed = True

                # Naked subsets
                unsolved = [idx for idx in unit if domains[idx] & (domains[idx] - 1)]
                mlen = len(unsolved)
                max_k = min(4, mlen)
                for k in range(2, max_k + 1):
                    for combo in combinations(unsolved, k):
                        union = 0
                        for idx in combo:
                            union |= domains[idx]
                        if union.bit_count() != k:
                            continue
                        combo_set = set(combo)
                        for idx in unit:
                            if idx in combo_set:
                                continue
                            d = domains[idx]
                            nd = d & ~union
                            if nd == 0:
                                return None
                            if nd != d:
                                domains[idx] = nd
                                changed = True

            # Intersection elimination: region -> row/col
            for ridx, reg in enumerate(regs):
                reg_set = set(reg)
                for digit in range(n):
                    m = 1 << digit
                    pos = [idx for idx in reg if domains[idx] & m]
                    if not pos:
                        return None
                    rs = {cell_row[idx] for idx in pos}
                    if len(rs) == 1:
                        rr = next(iter(rs))
                        for idx in rows[rr]:
                            if idx not in reg_set and (domains[idx] & m):
                                nd = domains[idx] & ~m
                                if nd == 0:
                                    return None
                                if nd != domains[idx]:
                                    domains[idx] = nd
                                    changed = True
                    cs = {cell_col[idx] for idx in pos}
                    if len(cs) == 1:
                        cc = next(iter(cs))
                        for idx in cols[cc]:
                            if idx not in reg_set and (domains[idx] & m):
                                nd = domains[idx] & ~m
                                if nd == 0:
                                    return None
                                if nd != domains[idx]:
                                    domains[idx] = nd
                                    changed = True

            # Intersection elimination: row/col -> region
            for unit_group, coord_of in ((rows, cell_row), (cols, cell_col)):
                for uidx, unit in enumerate(unit_group):
                    unit_set = set(unit)
                    for digit in range(n):
                        m = 1 << digit
                        pos = [idx for idx in unit if domains[idx] & m]
                        if not pos:
                            return None
                        gs = {cell_reg[idx] for idx in pos}
                        if len(gs) == 1:
                            g = next(iter(gs))
                            for idx in regs[g]:
                                if idx not in unit_set and (domains[idx] & m):
                                    nd = domains[idx] & ~m
                                    if nd == 0:
                                        return None
                                    if nd != domains[idx]:
                                        domains[idx] = nd
                                        changed = True

            if not changed:
                return domains

    def solved(domains):
        return all(d and (d & (d - 1) == 0) for d in domains)

    def select_cell(domains):
        best_idx = -1
        best_size = 10**9
        best_score = -1
        for idx, d in enumerate(domains):
            bc = d.bit_count()
            if bc <= 1:
                continue
            # MRV first, then maximize peer pressure
            score = 0
            for peer in row_others[idx]:
                score += domains[peer].bit_count()
            for peer in col_others[idx]:
                score += domains[peer].bit_count()
            for peer in reg_others[idx]:
                score += domains[peer].bit_count()
            if bc < best_size or (bc == best_size and score > best_score):
                best_size = bc
                best_score = score
                best_idx = idx
        return best_idx

    def value_order(domains, idx):
        vals = []
        d = domains[idx]
        for b in bit_iter(d):
            impact = 0
            for peer in row_others[idx]:
                if domains[peer] & b:
                    impact += 1
            for peer in col_others[idx]:
                if domains[peer] & b:
                    impact += 1
            for peer in reg_others[idx]:
                if domains[peer] & b:
                    impact += 1
            vals.append((impact, b))
        vals.sort()
        return [b for _, b in vals]

    def search(domains):
        domains = propagate(domains[:])
        if domains is None:
            return None
        if solved(domains):
            return domains

        idx = select_cell(domains)
        if idx < 0:
            return None

        for b in value_order(domains, idx):
            nxt = domains[:]
            nxt[idx] = b
            res = search(nxt)
            if res is not None:
                return res
        return None

    result = search(domains0)
    if result is None:
        return "No Solution"

    grid = [[mask_to_val(result[r * n + c]) for c in range(n)] for r in range(n)]
    return grid

