import sys


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation["data"]
    n = len(data)

    islands = []
    pos_to_idx = {}
    targets = []
    for r in range(n):
        for c in range(len(data[r])):
            v = data[r][c]
            if v is not None:
                idx = len(islands)
                islands.append((r, c))
                pos_to_idx[(r, c)] = idx
                targets.append(v)

    I = len(islands)
    if I == 0:
        return {}
    if I == 1:
        return {} if targets[0] == 0 else "No Solution"

    edge_ends = []
    edge_pos = []
    edge_orient = []
    incident = [[] for _ in range(I)]

    # Build candidate edges to nearest visible island right/down.
    for i, (r, c) in enumerate(islands):
        cc = c + 1
        while cc < n:
            if data[r][cc] is not None:
                j = pos_to_idx[(r, cc)]
                e = len(edge_ends)
                edge_ends.append((i, j))
                edge_pos.append(((r, c), (r, cc)))
                edge_orient.append("H")
                incident[i].append(e)
                incident[j].append(e)
                break
            cc += 1

        rr = r + 1
        while rr < n:
            if data[rr][c] is not None:
                j = pos_to_idx[(rr, c)]
                e = len(edge_ends)
                edge_ends.append((i, j))
                edge_pos.append(((r, c), (rr, c)))
                edge_orient.append("V")
                incident[i].append(e)
                incident[j].append(e)
                break
            rr += 1

    E = len(edge_ends)
    if E == 0:
        return "No Solution"

    crossings = [[] for _ in range(E)]
    horiz = [e for e in range(E) if edge_orient[e] == "H"]
    vert = [e for e in range(E) if edge_orient[e] == "V"]

    for eh in horiz:
        (r, c1), (_, c2) = edge_pos[eh]
        if c1 > c2:
            c1, c2 = c2, c1
        for ev in vert:
            (r1, c), (r2, _) = edge_pos[ev]
            if r1 > r2:
                r1, r2 = r2, r1
            if r1 < r < r2 and c1 < c < c2:
                crossings[eh].append(ev)
                crossings[ev].append(eh)

    VALUES = [(), (0,), (1,), (0, 1), (2,), (0, 2), (1, 2), (0, 1, 2)]
    LB = [0] * 8
    UB = [-1] * 8
    BC = [0] * 8
    for m in range(1, 8):
        vals = VALUES[m]
        LB[m] = min(vals)
        UB[m] = max(vals)
        BC[m] = len(vals)

    RANGE_MASK = [[0] * 3 for _ in range(3)]
    for a in range(3):
        mask = 0
        for b in range(a, 3):
            mask |= 1 << b
            RANGE_MASK[a][b] = mask

    initial_masks = []
    for a, b in edge_ends:
        max_v = min(2, targets[a], targets[b])
        if max_v < 0:
            return "No Solution"
        initial_masks.append(RANGE_MASK[0][max_v])

    # Quick impossible check: island target must fit local degree capacity.
    for i in range(I):
        if targets[i] < 0 or targets[i] > 2 * len(incident[i]):
            return "No Solution"

    def calc_bounds(masks):
        minsum = [0] * I
        maxsum = [0] * I
        for i in range(I):
            smin = 0
            smax = 0
            for e in incident[i]:
                m = masks[e]
                smin += LB[m]
                smax += UB[m]
            minsum[i] = smin
            maxsum[i] = smax
        return minsum, maxsum

    def build_possible_adj(masks):
        adj = [[] for _ in range(I)]
        for e, (a, b) in enumerate(edge_ends):
            if UB[masks[e]] > 0:
                adj[a].append((b, e))
                adj[b].append((a, e))
        return adj

    def possible_connected(adj):
        seen = [False] * I
        stack = [0]
        seen[0] = True
        count = 1
        while stack:
            v = stack.pop()
            for to, _ in adj[v]:
                if not seen[to]:
                    seen[to] = True
                    count += 1
                    stack.append(to)
        return count == I

    def possible_bridges(adj):
        tin = [-1] * I
        low = [0] * I
        timer = 0
        bridges = []

        def dfs(v, pe):
            nonlocal timer
            tin[v] = low[v] = timer
            timer += 1
            for to, e in adj[v]:
                if e == pe:
                    continue
                if tin[to] != -1:
                    low[v] = min(low[v], tin[to])
                else:
                    dfs(to, e)
                    low[v] = min(low[v], low[to])
                    if low[to] > tin[v]:
                        bridges.append(e)

        dfs(0, -1)
        return bridges

    def dead_guaranteed_component(masks, minsum):
        comp = [-1] * I
        comps = []
        cid = 0

        for s in range(I):
            if comp[s] != -1:
                continue
            stack = [s]
            comp[s] = cid
            nodes = [s]
            while stack:
                v = stack.pop()
                for e in incident[v]:
                    if LB[masks[e]] <= 0:
                        continue
                    a, b = edge_ends[e]
                    to = b if a == v else a
                    if comp[to] == -1:
                        comp[to] = cid
                        nodes.append(to)
                        stack.append(to)
            comps.append(nodes)
            cid += 1

        if cid == 1:
            return False

        for k, nodes in enumerate(comps):
            if len(nodes) == I:
                continue

            # If all vertices in a guaranteed component are already fully satisfied
            # by lower bounds, the component can never connect outward.
            closed_by_satisfaction = True
            for v in nodes:
                if minsum[v] != targets[v]:
                    closed_by_satisfaction = False
                    break
            if closed_by_satisfaction:
                return True

            # If there is no still-possible outgoing edge, this component is isolated.
            has_exit = False
            for e, (a, b) in enumerate(edge_ends):
                if UB[masks[e]] <= 0:
                    continue
                if (comp[a] == k) != (comp[b] == k):
                    has_exit = True
                    break
            if not has_exit:
                return True

        return False

    def propagate(masks):
        masks = masks[:]

        while True:
            changed = False

            # Crossing rule: a forced-positive edge kills all crossing edges.
            for e in range(E):
                if LB[masks[e]] > 0:
                    for f in crossings[e]:
                        nm = masks[f] & 1
                        if nm == 0:
                            return None
                        if nm != masks[f]:
                            masks[f] = nm
                            changed = True

            minsum = [0] * I
            maxsum = [0] * I

            # Per-island degree propagation.
            for i in range(I):
                inc = incident[i]
                t = targets[i]

                smin = 0
                smax = 0
                for e in inc:
                    m = masks[e]
                    smin += LB[m]
                    smax += UB[m]

                minsum[i] = smin
                maxsum[i] = smax

                if t < smin or t > smax:
                    return None

                for e in inc:
                    m = masks[e]
                    l = LB[m]
                    u = UB[m]

                    other_min = smin - l
                    other_max = smax - u

                    nl = max(l, t - other_max)
                    nu = min(u, t - other_min)

                    if nl > nu:
                        return None

                    nm = masks[e] & RANGE_MASK[nl][nu]
                    if nm == 0:
                        return None
                    if nm != masks[e]:
                        masks[e] = nm
                        changed = True

            # Recompute bounds after local narrowing if something changed.
            if changed:
                continue

            adj = build_possible_adj(masks)
            if not possible_connected(adj):
                return None

            # Connectivity bridge rule on the graph of still-possible links.
            forced = False
            for e in possible_bridges(adj):
                if LB[masks[e]] == 0:
                    nm = masks[e] & 6
                    if nm == 0:
                        return None
                    if nm != masks[e]:
                        masks[e] = nm
                        forced = True
            if forced:
                continue

            # Guaranteed closed component detection.
            minsum, _ = calc_bounds(masks)
            if dead_guaranteed_component(masks, minsum):
                return None

            return masks

    def final_connected(masks):
        seen = [False] * I
        stack = [0]
        seen[0] = True
        count = 1
        while stack:
            v = stack.pop()
            for e in incident[v]:
                if LB[masks[e]] <= 0:
                    continue
                a, b = edge_ends[e]
                to = b if a == v else a
                if not seen[to]:
                    seen[to] = True
                    count += 1
                    stack.append(to)
        return count == I

    def choose_edge(masks):
        minsum, maxsum = calc_bounds(masks)
        best_e = None
        best_key = None

        for e in range(E):
            m = masks[e]
            if BC[m] == 1:
                continue

            a, b = edge_ends[e]
            slack = (maxsum[a] - minsum[a]) + (maxsum[b] - minsum[b])
            key = (
                BC[m],                    # smallest domain first
                slack,                    # tighter endpoints first
                -len(crossings[e]),       # more crossings => more impact
                -(targets[a] + targets[b])
            )
            if best_key is None or key < best_key:
                best_key = key
                best_e = e

        return best_e

    fail_cache = set()

    def dfs(masks):
        pm = propagate(masks)
        if pm is None:
            return None

        key = tuple(pm)
        if key in fail_cache:
            return None

        done = True
        for m in pm:
            if BC[m] != 1:
                done = False
                break

        if done:
            minsum, maxsum = calc_bounds(pm)
            for i in range(I):
                if minsum[i] != targets[i] or maxsum[i] != targets[i]:
                    fail_cache.add(key)
                    return None
            if not final_connected(pm):
                fail_cache.add(key)
                return None

            answer = {}
            for e, m in enumerate(pm):
                v = VALUES[m][0]
                if v > 0:
                    answer[edge_pos[e]] = v
            return answer

        e = choose_edge(pm)
        if e is None:
            fail_cache.add(key)
            return None

        a, b = edge_ends[e]
        m = pm[e]
        vals = VALUES[m]

        minsum, maxsum = calc_bounds(pm)
        rem_a = targets[a] - minsum[a]
        rem_b = targets[b] - minsum[b]
        flex_a = maxsum[a] - minsum[a]
        flex_b = maxsum[b] - minsum[b]

        branches = []
        if 0 in vals and (1 in vals or 2 in vals):
            posmask = m & 6
            zeromask = m & 1
            positive_first = (
                (flex_a > 0 and rem_a == flex_a) or
                (flex_b > 0 and rem_b == flex_b) or
                len(crossings[e]) == 0
            )
            if positive_first:
                if posmask:
                    branches.append(posmask)
                if zeromask:
                    branches.append(zeromask)
            else:
                if zeromask:
                    branches.append(zeromask)
                if posmask:
                    branches.append(posmask)
        else:
            for v in sorted(vals, reverse=True):
                branches.append(1 << v)

        for bm in branches:
            nm = pm[e] & bm
            if nm == 0 or nm == pm[e] and BC[pm[e]] == 1:
                continue
            new_masks = pm[:]
            new_masks[e] = nm
            res = dfs(new_masks)
            if res is not None:
                return res

        fail_cache.add(key)
        return None

    result = dfs(initial_masks)
    return result if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 0, None, 1, 1, 1, 0, None], [None, None, None, None, 1, None, 3, 0], [None, 1, None, 3, None, None, 1, None], [1, None, None, None, 1, None, 3, None], [2, 2, None, None, 4, None, None, 2], [None, None, None, 1, None, None, None, None], [None, 2, None, 4, None, 2, 1, 1], [None, 0, None, None, None, None, None, 0]]}

def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data or not all(isinstance(row, list) for row in data):
        return "No Solution"
    h = len(data)
    w = len(data[0])
    if any(len(row) != w for row in data) or h != w or h < 2:
        return "No Solution"

    n = h - 1
    m = n * n
    dot_count = (n + 1) * (n + 1)

    def cell_id(r, c):
        return r * n + c

    def dot_id(r, c):
        return r * (n + 1) + c

    # Value 0 = '/', value 1 = '\'
    endpoints = [None] * m
    for r in range(n):
        for c in range(n):
            i = cell_id(r, c)
            endpoints[i] = (
                (dot_id(r, c + 1), dot_id(r + 1, c)),      # '/'
                (dot_id(r, c), dot_id(r + 1, c + 1)),      # '\'
            )

    # Build exact-count constraints for numbered dots.
    constraints = []
    cell_constraints = [[] for _ in range(m)]

    for r in range(n + 1):
        for c in range(n + 1):
            clue = data[r][c]
            if clue is None:
                continue

            items = []
            # Each item: (cell_index, contributes_for_value0, contributes_for_value1)
            if r > 0 and c > 0:
                items.append((cell_id(r - 1, c - 1), 0, 1))  # '\' contributes
            if r > 0 and c < n:
                items.append((cell_id(r - 1, c), 1, 0))      # '/' contributes
            if r < n and c > 0:
                items.append((cell_id(r, c - 1), 1, 0))      # '/' contributes
            if r < n and c < n:
                items.append((cell_id(r, c), 0, 1))          # '\' contributes

            degree = len(items)
            if not isinstance(clue, int) or clue < 0 or clue > degree:
                return "No Solution"

            patterns = []
            for mask in range(1 << degree):
                tup = [0] * degree
                count = 0
                for pos, (_, c0, c1) in enumerate(items):
                    v = (mask >> pos) & 1
                    tup[pos] = v
                    count += c0 if v == 0 else c1
                if count == clue:
                    patterns.append(tuple(tup))

            if not patterns:
                return "No Solution"

            cid = len(constraints)
            cons = {
                "cells": [x[0] for x in items],
                "patterns": patterns,
                "pos": {},
            }
            for pos, (ci, _, _) in enumerate(items):
                cons["pos"][ci] = pos
                cell_constraints[ci].append(cid)
            constraints.append(cons)

    # Domains: bitmask 1 => '/', 2 => '\', 3 => both
    domains = [3] * m

    # Rollback DSU for the "no loops" forest condition.
    parent = list(range(dot_count))
    size = [1] * dot_count
    dsu_trail = []
    dom_trail = []

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        dsu_trail.append((rb, ra, size[ra]))
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    def assign_mask(i, newmask):
        oldmask = domains[i]
        if newmask == oldmask:
            return True
        if newmask == 0:
            return False

        dom_trail.append((i, oldmask))
        domains[i] = newmask

        # When a cell becomes fixed, immediately add its edge to the forest.
        if oldmask == 3 and newmask != 3:
            v = 0 if newmask == 1 else 1
            a, b = endpoints[i][v]
            if not union(a, b):
                return False
        return True

    def rollback(dom_mark, dsu_mark):
        while len(dom_trail) > dom_mark:
            i, oldmask = dom_trail.pop()
            domains[i] = oldmask
        while len(dsu_trail) > dsu_mark:
            rb, ra, old_size_ra = dsu_trail.pop()
            parent[rb] = rb
            size[ra] = old_size_ra

    # Human-like propagation:
    # 1) Exact clue filtering on each dot (tiny local truth tables).
    # 2) Loop prevention: if an orientation would connect two already-connected dots, forbid it.
    def propagate():
        changed = True
        while changed:
            changed = False

            # Clue-driven pruning.
            for cons in constraints:
                cells = cons["cells"]
                pats = cons["patterns"]
                support = [0] * len(cells)
                any_valid = False

                for pat in pats:
                    ok = True
                    for pos, v in enumerate(pat):
                        if not (domains[cells[pos]] & (1 << v)):
                            ok = False
                            break
                    if ok:
                        any_valid = True
                        for pos, v in enumerate(pat):
                            support[pos] |= (1 << v)

                if not any_valid:
                    return False

                for pos, ci in enumerate(cells):
                    newmask = domains[ci] & support[pos]
                    if newmask == 0:
                        return False
                    if newmask != domains[ci]:
                        if not assign_mask(ci, newmask):
                            return False
                        changed = True

            # Loop-driven pruning.
            for i in range(m):
                if domains[i] != 3:
                    continue

                bad = 0
                a0, b0 = endpoints[i][0]
                if find(a0) == find(b0):
                    bad |= 1
                a1, b1 = endpoints[i][1]
                if find(a1) == find(b1):
                    bad |= 2

                if bad:
                    newmask = domains[i] & (~bad)
                    if not assign_mask(i, newmask):
                        return False
                    changed = True

        return True

    def solved():
        for mask in domains:
            if mask == 3:
                return False
        return True

    # Choose the next cell with a fail-first heuristic based on local clue support.
    def choose_cell():
        best_i = None
        best_key = None
        best_order = (0, 1)

        for i in range(m):
            if domains[i] != 3:
                continue

            support0 = 1
            support1 = 1
            total_valid = 1

            for cid in cell_constraints[i]:
                cons = constraints[cid]
                pos = cons["pos"][i]
                cells = cons["cells"]

                c0 = 0
                c1 = 0
                valid = 0

                for pat in cons["patterns"]:
                    ok = True
                    for p, v in enumerate(pat):
                        if not (domains[cells[p]] & (1 << v)):
                            ok = False
                            break
                    if ok:
                        valid += 1
                        if pat[pos] == 0:
                            c0 += 1
                        else:
                            c1 += 1

                if valid == 0:
                    return i, (0, 1)

                support0 *= max(1, c0)
                support1 *= max(1, c1)
                total_valid *= valid

            key = (support0 * support1, support0 + support1, total_valid, -len(cell_constraints[i]))
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
                best_order = (0, 1) if support0 <= support1 else (1, 0)

        return best_i, best_order

    def dfs():
        dom_mark0 = len(dom_trail)
        dsu_mark0 = len(dsu_trail)

        if not propagate():
            rollback(dom_mark0, dsu_mark0)
            return False

        if solved():
            return True

        i, order = choose_cell()
        if i is None:
            rollback(dom_mark0, dsu_mark0)
            return False

        for v in order:
            bit = 1 << v
            if not (domains[i] & bit):
                continue

            dom_mark = len(dom_trail)
            dsu_mark = len(dsu_trail)

            if assign_mask(i, bit) and dfs():
                return True

            rollback(dom_mark, dsu_mark)

        rollback(dom_mark0, dsu_mark0)
        return False

    if not dfs():
        return "No Solution"

    answer = []
    for r in range(n):
        row = []
        for c in range(n):
            mask = domains[cell_id(r, c)]
            row.append('/' if mask == 1 else '\\')
        answer.append(row)
    return repr(answer)


