    print(solve(OBSERVATION))

OBSERVATION = {'data': [[1, None, None, None, None, 1, 1, None, None, -1], [None, 2, None, None, None, None, None, None, -1, None], [None, None, None, None, None, None, 0, None, None, None], [0, None, 1, None, None, None, None, None, None, None], [1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, 1], [None, None, None, None, None, None, None, 1, None, 2], [None, None, None, 1, None, None, None, None, None, None], [None, -1, None, None, None, None, None, None, 2, None], [-1, None, None, -1, -1, None, None, None, None, -1]]}

# Akari / Light Up solver using human-like deduction first, then tightly-pruned search.

UNDECIDED = 0
BULB = 1
FORBIDDEN = -1


class State:
    __slots__ = ("val", "lit", "clue_bulbs", "clue_undec")

    def __init__(self, w_count, c_count):
        self.val = [UNDECIDED] * w_count
        self.lit = [0] * w_count
        self.clue_bulbs = [0] * c_count
        self.clue_undec = [0] * c_count

    def clone(self):
        s = State(0, 0)
        s.val = self.val[:]
        s.lit = self.lit[:]
        s.clue_bulbs = self.clue_bulbs[:]
        s.clue_undec = self.clue_undec[:]
        return s


def solve(observation):
    data = observation["data"]
    if not data or not data[0]:
        return repr([])

    R = len(data)
    C = len(data[0])

    # White cells only are variable cells; black cells are fixed barriers/clues.
    cell_id = {}
    id_pos = []
    for r in range(R):
        for c in range(C):
            if data[r][c] is None:
                cell_id[(r, c)] = len(id_pos)
                id_pos.append((r, c))
    W = len(id_pos)

    # Precompute visibility domains: a bulb at w lights all cells in domains[w].
    domains = [None] * W
    peers = [None] * W
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for w, (r, c) in enumerate(id_pos):
        dom = [w]
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < R and 0 <= nc < C and data[nr][nc] is None:
                dom.append(cell_id[(nr, nc)])
                nr += dr
                nc += dc
        domains[w] = tuple(dom)
        peers[w] = tuple(x for x in dom if x != w)

    # Numbered clues and adjacency.
    clue_nums = []
    clue_adj = []
    adj_clues = [[] for _ in range(W)]

    for r in range(R):
        for c in range(C):
            v = data[r][c]
            if isinstance(v, int) and 0 <= v <= 4:
                adj = []
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in cell_id:
                        adj.append(cell_id[(nr, nc)])
                ci = len(clue_nums)
                clue_nums.append(v)
                clue_adj.append(tuple(adj))
                for w in adj:
                    adj_clues[w].append(ci)

    clue_adj = tuple(clue_adj)
    clue_nums = tuple(clue_nums)
    adj_clues = tuple(tuple(x) for x in adj_clues)
    CCOUNT = len(clue_nums)

    state0 = State(W, CCOUNT)
    for ci, adj in enumerate(clue_adj):
        state0.clue_undec[ci] = len(adj)

    def can_be_bulb(state, w):
        vw = state.val[w]
        if vw == FORBIDDEN:
            return False
        if vw == BULB:
            return True
        for p in peers[w]:
            if state.val[p] == BULB:
                return False
        for ci in adj_clues[w]:
            if state.clue_bulbs[ci] + 1 > clue_nums[ci]:
                return False
        return True

    def forbid_cell(state, w):
        if state.val[w] == FORBIDDEN:
            return True
        if state.val[w] == BULB:
            return False
        state.val[w] = FORBIDDEN
        for ci in adj_clues[w]:
            state.clue_undec[ci] -= 1
        return True

    def place_bulb(state, w):
        if state.val[w] == BULB:
            return True
        if not can_be_bulb(state, w):
            return False
        state.val[w] = BULB
        for ci in adj_clues[w]:
            state.clue_bulbs[ci] += 1
            state.clue_undec[ci] -= 1
        for v in domains[w]:
            state.lit[v] += 1
        for p in peers[w]:
            if state.val[p] == BULB:
                return False
            if state.val[p] == UNDECIDED and not forbid_cell(state, p):
                return False
        return True

    def unresolved_adj(state, ci):
        return [w for w in clue_adj[ci] if state.val[w] == UNDECIDED]

    def coverage_sources(state, v):
        # Cells that could still host a bulb and illuminate v.
        out = []
        for s in domains[v]:
            if can_be_bulb(state, s):
                out.append(s)
        return out

    def propagate(state):
        # Repeatedly apply direct human-like deductions until fixed point.
        while True:
            changed = False

            # Basic clue consistency.
            for ci in range(CCOUNT):
                b = state.clue_bulbs[ci]
                u = state.clue_undec[ci]
                need = clue_nums[ci]
                if b > need or b + u < need:
                    return False

            # Any undecided cell that can no longer be a bulb becomes forbidden.
            for w in range(W):
                if state.val[w] == UNDECIDED and not can_be_bulb(state, w):
                    if not forbid_cell(state, w):
                        return False
                    changed = True

            # Exact clue deductions:
            # - if clue already satisfied, all remaining adjacent undecided are forbidden
            # - if all remaining adjacent cells must be bulbs, place them
            for ci in range(CCOUNT):
                b = state.clue_bulbs[ci]
                u = state.clue_undec[ci]
                need = clue_nums[ci]
                if b > need or b + u < need:
                    return False
                if u == 0:
                    continue
                if b == need:
                    for w in clue_adj[ci]:
                        if state.val[w] == UNDECIDED:
                            if not forbid_cell(state, w):
                                return False
                            changed = True
                elif b + u == need:
                    for w in clue_adj[ci]:
                        if state.val[w] == UNDECIDED:
                            if not place_bulb(state, w):
                                return False
                            changed = True

            # Pairwise clue subset reasoning.
            # If Ua subset Ub:
            # - same remaining count => Ub\Ua cannot contain bulbs
            # - count difference equals set difference size => Ub\Ua all bulbs
            clue_sets = []
            rems = []
            for ci in range(CCOUNT):
                u = tuple(w for w in clue_adj[ci] if state.val[w] == UNDECIDED)
                clue_sets.append(u)
                rems.append(clue_nums[ci] - state.clue_bulbs[ci])

            for i in range(CCOUNT):
                Ui = clue_sets[i]
                if not Ui:
                    continue
                Si = set(Ui)
                ri = rems[i]
                for j in range(i + 1, CCOUNT):
                    Uj = clue_sets[j]
                    if not Uj:
                        continue
                    Sj = set(Uj)
                    rj = rems[j]

                    if Si <= Sj and Si != Sj:
                        diff = Sj - Si
                        if ri == rj:
                            for w in diff:
                                if state.val[w] == UNDECIDED:
                                    if not forbid_cell(state, w):
                                        return False
                                    changed = True
                        elif rj - ri == len(diff):
                            for w in diff:
                                if state.val[w] == UNDECIDED:
                                    if not place_bulb(state, w):
                                        return False
                                    changed = True

                    if Sj <= Si and Sj != Si:
                        diff = Si - Sj
                        if ri == rj:
                            for w in diff:
                                if state.val[w] == UNDECIDED:
                                    if not forbid_cell(state, w):
                                        return False
                                    changed = True
                        elif ri - rj == len(diff):
                            for w in diff:
                                if state.val[w] == UNDECIDED:
                                    if not place_bulb(state, w):
                                        return False
                                    changed = True

            # Coverage reasoning:
            # every unlit cell needs at least one possible source;
            # if exactly one possible source exists, that source must be a bulb.
            for v in range(W):
                if state.lit[v] > 0:
                    continue
                src = coverage_sources(state, v)
                if not src:
                    return False
                if len(src) == 1:
                    if not place_bulb(state, src[0]):
                        return False
                    changed = True

            if not changed:
                break

        # Final consistency check at fixed point.
        for ci in range(CCOUNT):
            b = state.clue_bulbs[ci]
            u = state.clue_undec[ci]
            need = clue_nums[ci]
            if b > need or b + u < need:
                return False

        for v in range(W):
            if state.lit[v] == 0 and not coverage_sources(state, v):
                return False

        return True

    def is_solved(state):
        for ci in range(CCOUNT):
            if state.clue_bulbs[ci] != clue_nums[ci]:
                return False
        for v in range(W):
            if state.lit[v] == 0:
                return False
        return True

    def select_branch_cell(state):
        # Best branching target:
        # 1) pick an unlit cell with the fewest candidate lighting sources
        # 2) otherwise pick a clue-adjacent undecided cell in the tightest clue
        # 3) otherwise highest-impact undecided cell
        best_sources = None
        best_len = None
        best_score = None

        for v in range(W):
            if state.lit[v] > 0:
                continue
            src = coverage_sources(state, v)
            if not src:
                return None
            if len(src) > 1:
                score = sum(len(adj_clues[s]) for s in src)
                if best_len is None or len(src) < best_len or (len(src) == best_len and score > best_score):
                    best_len = len(src)
                    best_score = score
                    best_sources = src

        if best_sources is not None:
            return max(
                best_sources,
                key=lambda w: (
                    len(adj_clues[w]),
                    sum(1 for v in domains[w] if state.lit[v] == 0),
                    len(domains[w]),
                    -w,
                ),
            )

        best = None
        for ci in range(CCOUNT):
            rem = clue_nums[ci] - state.clue_bulbs[ci]
            U = unresolved_adj(state, ci)
            if not U:
                continue
            if rem == 0 or rem == len(U):
                continue
            cand = max(
                U,
                key=lambda w: (
                    len(adj_clues[w]),
                    sum(1 for v in domains[w] if state.lit[v] == 0),
                    len(domains[w]),
                    -w,
                ),
            )
            item = (len(U), -rem, cand)
            if best is None or item < best:
                best = item

        if best is not None:
            return best[2]

        undec = [w for w in range(W) if state.val[w] == UNDECIDED]
        if not undec:
            return None

        return max(
            undec,
            key=lambda w: (
                len(adj_clues[w]),
                sum(1 for v in domains[w] if state.lit[v] == 0),
                len(domains[w]),
                -w,
            ),
        )

    def branch_order(state, w):
        bulb_score = 0

        if can_be_bulb(state, w):
            for v in domains[w]:
                if state.lit[v] == 0:
                    cnt = len(coverage_sources(state, v))
                    if cnt <= 2:
                        bulb_score += 4
                    else:
                        bulb_score += 1

            for ci in adj_clues[w]:
                rem = clue_nums[ci] - state.clue_bulbs[ci]
                u = sum(1 for x in clue_adj[ci] if state.val[x] == UNDECIDED)
                if rem == 0:
                    bulb_score -= 100
                elif rem == u:
                    bulb_score += 100
                else:
                    bulb_score += 3

        if can_be_bulb(state, w) and bulb_score >= 0:
            return (BULB, FORBIDDEN)
        return (FORBIDDEN, BULB)

    def dfs(state):
        if not propagate(state):
            return None
        if is_solved(state):
            return state

        w = select_branch_cell(state)
        if w is None:
            return state if is_solved(state) else None

        for choice in branch_order(state, w):
            nxt = state.clone()
            ok = place_bulb(nxt, w) if choice == BULB else forbid_cell(nxt, w)
            if not ok:
                continue
            res = dfs(nxt)
            if res is not None:
                return res
        return None

    result = dfs(state0)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(C)] for _ in range(R)]
    for w, (r, c) in enumerate(id_pos):
        if result.val[w] == BULB:
            answer[r][c] = "B"
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

