from collections import deque
from itertools import combinations


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    if n == 0 or any(len(row) != n for row in region) or any(len(row) != n for row in data):
        return "No Solution"

    full_mask = (1 << n) - 1
    size = n * n

    reg_ids = sorted({region[r][c] for r in range(n) for c in range(n)})
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    reg_count = len(reg_ids)

    rows = [[] for _ in range(n)]
    cols = [[] for _ in range(n)]
    regs = [[] for _ in range(reg_count)]
    row_of = [0] * size
    col_of = [0] * size
    reg_of = [0] * size

    for r in range(n):
        for c in range(n):
            idx = r * n + c
            g = reg_index[region[r][c]]
            rows[r].append(idx)
            cols[c].append(idx)
            regs[g].append(idx)
            row_of[idx] = r
            col_of[idx] = c
            reg_of[idx] = g

    # Standard jigsaw Latin puzzles should have exactly n regions of size n.
    if reg_count != n or any(len(regs[g]) != n for g in range(reg_count)):
        return "No Solution"

    all_units = rows + cols + regs
    peers = []
    for idx in range(size):
        s = set(rows[row_of[idx]])
        s.update(cols[col_of[idx]])
        s.update(regs[reg_of[idx]])
        s.discard(idx)
        peers.append(tuple(s))

    def iter_bits(mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask ^= bit

    def set_single(cands, idx, bit, queue):
        cur = cands[idx]
        if cur == bit:
            return True, False
        if (cur & bit) == 0:
            return False, False
        cands[idx] = bit
        queue.append(idx)
        return True, True

    def eliminate_bit(cands, idx, bit, queue):
        cur = cands[idx]
        if (cur & bit) == 0:
            return True, False
        new = cur & ~bit
        if new == 0:
            return False, False
        if new == cur:
            return True, False
        cands[idx] = new
        if new & (new - 1) == 0:
            queue.append(idx)
        return True, True

    def hidden_singles(cands, queue):
        changed = False
        for unit in all_units:
            counts = [0] * n
            last = [-1] * n
            for idx in unit:
                m = cands[idx]
                if m == 0:
                    return None
                for bit in iter_bits(m):
                    v = bit.bit_length() - 1
                    counts[v] += 1
                    last[v] = idx
            for v in range(n):
                if counts[v] == 0:
                    return None
                if counts[v] == 1:
                    ok, ch = set_single(cands, last[v], 1 << v, queue)
                    if not ok:
                        return None
                    changed |= ch
        return changed

    def naked_subsets(cands, queue):
        changed = False
        max_k = min(4, n - 1)
        for unit in all_units:
            unresolved = [idx for idx in unit if cands[idx] & (cands[idx] - 1)]
            if len(unresolved) < 2:
                continue

            # Exact repeated-mask subsets, e.g. two cells both {2,5}.
            groups = {}
            for idx in unresolved:
                groups.setdefault(cands[idx], []).append(idx)
            for mask, cells_m in groups.items():
                k = mask.bit_count()
                if 2 <= k == len(cells_m) < len(unit):
                    cellset = set(cells_m)
                    for idx in unit:
                        if idx in cellset:
                            continue
                        if cands[idx] & mask:
                            ok, ch = eliminate_bit(cands, idx, mask, queue)
                            if not ok:
                                return None
                            changed |= ch

            # General naked pairs/triples/quads.
            pool = [idx for idx in unresolved if cands[idx].bit_count() <= max_k]
            for k in range(2, min(max_k, len(pool)) + 1):
                seen = set()
                for comb in combinations(pool, k):
                    union = 0
                    for idx in comb:
                        union |= cands[idx]
                    if union.bit_count() != k or union in seen:
                        continue
                    subset_cells = [idx for idx in unresolved if (cands[idx] & ~union) == 0]
                    if len(subset_cells) != k:
                        continue
                    seen.add(union)
                    subset_set = set(subset_cells)
                    for idx in unit:
                        if idx in subset_set:
                            continue
                        if cands[idx] & union:
                            ok, ch = eliminate_bit(cands, idx, union, queue)
                            if not ok:
                                return None
                            changed |= ch
        return changed

    def locked_candidates(cands, queue):
        changed = False

        # Row -> region claims.
        for r in range(n):
            unit = rows[r]
            pos = [[] for _ in range(n)]
            for idx in unit:
                for bit in iter_bits(cands[idx]):
                    pos[bit.bit_length() - 1].append(idx)
            for v in range(n):
                cells = pos[v]
                if not cells:
                    return None
                gs = {reg_of[idx] for idx in cells}
                if len(gs) == 1:
                    g = next(iter(gs))
                    bit = 1 << v
                    for idx in regs[g]:
                        if row_of[idx] != r and (cands[idx] & bit):
                            ok, ch = eliminate_bit(cands, idx, bit, queue)
                            if not ok:
                                return None
                            changed |= ch

        # Column -> region claims.
        for c in range(n):
            unit = cols[c]
            pos = [[] for _ in range(n)]
            for idx in unit:
                for bit in iter_bits(cands[idx]):
                    pos[bit.bit_length() - 1].append(idx)
            for v in range(n):
                cells = pos[v]
                if not cells:
                    return None
                gs = {reg_of[idx] for idx in cells}
                if len(gs) == 1:
                    g = next(iter(gs))
                    bit = 1 << v
                    for idx in regs[g]:
                        if col_of[idx] != c and (cands[idx] & bit):
                            ok, ch = eliminate_bit(cands, idx, bit, queue)
                            if not ok:
                                return None
                            changed |= ch

        # Region -> row/column claims.
        for g in range(reg_count):
            unit = regs[g]
            pos = [[] for _ in range(n)]
            for idx in unit:
                for bit in iter_bits(cands[idx]):
                    pos[bit.bit_length() - 1].append(idx)
            for v in range(n):
                cells = pos[v]
                if not cells:
                    return None
                bit = 1 << v

                rs = {row_of[idx] for idx in cells}
                if len(rs) == 1:
                    r = next(iter(rs))
                    for idx in rows[r]:
                        if reg_of[idx] != g and (cands[idx] & bit):
                            ok, ch = eliminate_bit(cands, idx, bit, queue)
                            if not ok:
                                return None
                            changed |= ch

                cs = {col_of[idx] for idx in cells}
                if len(cs) == 1:
                    c = next(iter(cs))
                    for idx in cols[c]:
                        if reg_of[idx] != g and (cands[idx] & bit):
                            ok, ch = eliminate_bit(cands, idx, bit, queue)
                            if not ok:
                                return None
                            changed |= ch

        return changed

    def propagate(cands):
        queue = deque(idx for idx in range(size) if cands[idx] and (cands[idx] & (cands[idx] - 1)) == 0)

        while True:
            while queue:
                idx = queue.popleft()
                val = cands[idx]
                if val == 0:
                    return None
                if val & (val - 1):
                    continue
                for p in peers[idx]:
                    if cands[p] & val:
                        ok, _ = eliminate_bit(cands, p, val, queue)
                        if not ok:
                            return None

            progress = False

            ch = hidden_singles(cands, queue)
            if ch is None:
                return None
            progress |= ch

            ch = naked_subsets(cands, queue)
            if ch is None:
                return None
            progress |= ch

            ch = locked_candidates(cands, queue)
            if ch is None:
                return None
            progress |= ch

            if queue:
                continue
            if not progress:
                return cands

    def choose_branch(cands):
        best = None
        best_len = n + 1

        # Cell-based branching.
        for idx, mask in enumerate(cands):
            bc = mask.bit_count()
            if 1 < bc < best_len:
                bits = list(iter_bits(mask))
                # Try the value that constrains peers most first.
                bits.sort(key=lambda b: -sum(1 for p in peers[idx] if cands[p] & b))
                best = ("cell", idx, bits)
                best_len = bc

        # Unit-value branching: choose a value with very few possible places in a unit.
        for unit in all_units:
            pos = [[] for _ in range(n)]
            for idx in unit:
                for bit in iter_bits(cands[idx]):
                    pos[bit.bit_length() - 1].append(idx)
            for v in range(n):
                cells = pos[v]
                cnt = len(cells)
                if 1 < cnt < best_len or (best is not None and cnt == best_len and best[0] == "cell"):
                    bit = 1 << v
                    ordered = sorted(
                        cells,
                        key=lambda idx: (cands[idx].bit_count(), -sum(1 for p in peers[idx] if cands[p] & bit)),
                    )
                    best = ("place", bit, ordered)
                    best_len = cnt

        return best

    def search(cands):
        cands = propagate(cands)
        if cands is None:
            return None
        if all((m & (m - 1)) == 0 for m in cands):
            return cands

        choice = choose_branch(cands)
        if choice is None:
            return None

        if choice[0] == "cell":
            _, idx, bits = choice
            for bit in bits:
                nxt = cands[:]
                nxt[idx] = bit
                res = search(nxt)
                if res is not None:
                    return res
        else:
            _, bit, cells = choice
            for idx in cells:
                nxt = cands[:]
                if (nxt[idx] & bit) == 0:
                    continue
                nxt[idx] = bit
                res = search(nxt)
                if res is not None:
                    return res

        return None

    cands = [full_mask] * size
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            cands[r * n + c] = 1 << (v - 1)

    sol = search(cands)
    if sol is None:
        return "No Solution"

    grid = [[sol[r * n + c].bit_length() for c in range(n)] for r in range(n)]
    return str(grid)


