# General Hashi solver:
# - Build all visible island pairs as edge variables in {0,1,2}
# - Propagate degree bounds like a human would
# - Eliminate crossings as soon as any bridge is forced positive
# - Enforce "component must have an exit" connectivity deductions
# - Use a tightly-pruned backtracking search only after propagation stalls

def solve(observation):
    data = observation.get("data")
    if not data or not data[0]:
        return "No Solution"

    rows = len(data)
    cols = len(data[0])

    islands = []
    pos_to_idx = {}
    for r in range(rows):
        for c in range(cols):
            v = data[r][c]
            if isinstance(v, int):
                idx = len(islands)
                islands.append(((r, c), v))
                pos_to_idx[(r, c)] = idx

    n = len(islands)
    if n == 0:
        return "{}"

    vals = [v for _, v in islands]
    if sum(vals) % 2 != 0:
        return "No Solution"

    # Build visibility edges (right and down only to avoid duplicates).
    edges = []
    incident = [[] for _ in range(n)]

    for i, ((r, c), v) in enumerate(islands):
        cc = c + 1
        while cc < cols:
            if data[r][cc] is not None:
                j = pos_to_idx[(r, cc)]
                eidx = len(edges)
                edges.append({
                    "u": i,
                    "v": j,
                    "kind": "H",
                    "r": r,
                    "c1": c,
                    "c2": cc,
                })
                incident[i].append(eidx)
                incident[j].append(eidx)
                break
            cc += 1

        rr = r + 1
        while rr < rows:
            if data[rr][c] is not None:
                j = pos_to_idx[(rr, c)]
                eidx = len(edges)
                edges.append({
                    "u": i,
                    "v": j,
                    "kind": "V",
                    "c": c,
                    "r1": r,
                    "r2": rr,
                })
                incident[i].append(eidx)
                incident[j].append(eidx)
                break
            rr += 1

    m = len(edges)
    if m == 0:
        return "No Solution" if n > 1 else "{}"

    # Crossing relations.
    crossings = [set() for _ in range(m)]
    horizontals = [i for i, e in enumerate(edges) if e["kind"] == "H"]
    verticals = [i for i, e in enumerate(edges) if e["kind"] == "V"]
    for hi in horizontals:
        eh = edges[hi]
        r = eh["r"]
        c1 = eh["c1"]
        c2 = eh["c2"]
        for vi in verticals:
            ev = edges[vi]
            c = ev["c"]
            r1 = ev["r1"]
            r2 = ev["r2"]
            if r1 < r < r2 and c1 < c < c2:
                crossings[hi].add(vi)
                crossings[vi].add(hi)

    # Initial domains.
    lo0 = [0] * m
    hi0 = [min(2, vals[edges[e]["u"]], vals[edges[e]["v"]]) for e in range(m)]

    # Early impossible islands.
    for i in range(n):
        if vals[i] > sum(hi0[e] for e in incident[i]):
            return "No Solution"

    def edge_other(eidx, node):
        e = edges[eidx]
        return e["v"] if e["u"] == node else e["u"]

    def components_using(predicate):
        seen = [False] * n
        comps = []
        for s in range(n):
            if seen[s]:
                continue
            stack = [s]
            seen[s] = True
            comp = {s}
            while stack:
                x = stack.pop()
                for eidx in incident[x]:
                    if not predicate(eidx):
                        continue
                    y = edge_other(eidx, x)
                    if not seen[y]:
                        seen[y] = True
                        comp.add(y)
                        stack.append(y)
            comps.append(comp)
        return comps

    def graph_connected(predicate):
        if n <= 1:
            return True
        seen = [False] * n
        stack = [0]
        seen[0] = True
        while stack:
            x = stack.pop()
            for eidx in incident[x]:
                if not predicate(eidx):
                    continue
                y = edge_other(eidx, x)
                if not seen[y]:
                    seen[y] = True
                    stack.append(y)
        return all(seen)

    def exact_connected(counts):
        if n <= 1:
            return True
        seen = [False] * n
        stack = [0]
        seen[0] = True
        while stack:
            x = stack.pop()
            for eidx in incident[x]:
                if counts[eidx] <= 0:
                    continue
                y = edge_other(eidx, x)
                if not seen[y]:
                    seen[y] = True
                    stack.append(y)
        return all(seen)

    def propagate(lo, hi):
        lo = lo[:]
        hi = hi[:]

        while True:
            changed = False

            for eidx in range(m):
                if lo[eidx] > hi[eidx]:
                    return None

            # Any positive bridge blocks all crossing edges.
            for eidx in range(m):
                if lo[eidx] > 0:
                    for fidx in crossings[eidx]:
                        if hi[fidx] > 0:
                            hi[fidx] = 0
                            changed = True
                            if lo[fidx] > hi[fidx]:
                                return None

            # Degree propagation on each island.
            for i in range(n):
                t = vals[i]
                inc = incident[i]
                s_lo = 0
                s_hi = 0
                for eidx in inc:
                    s_lo += lo[eidx]
                    s_hi += hi[eidx]

                if t < s_lo or t > s_hi:
                    return None

                for eidx in inc:
                    new_lo = t - (s_hi - hi[eidx])
                    new_hi = t - (s_lo - lo[eidx])

                    if new_lo > lo[eidx]:
                        lo[eidx] = new_lo
                        changed = True
                    if new_hi < hi[eidx]:
                        hi[eidx] = new_hi
                        changed = True

                    if lo[eidx] > hi[eidx]:
                        return None

            # The graph of still-possible edges must stay connected.
            if not graph_connected(lambda eidx: hi[eidx] > 0):
                return None

            # Connectivity deduction on forced components:
            # every already-connected component must still have a possible exit
            # unless it already contains all islands.
            comps = components_using(lambda eidx: lo[eidx] > 0)
            for comp in comps:
                if len(comp) == n:
                    continue
                exits = set()
                for i in comp:
                    for eidx in incident[i]:
                        if hi[eidx] <= 0:
                            continue
                        j = edge_other(eidx, i)
                        if j not in comp:
                            exits.add(eidx)
                if not exits:
                    return None
                if len(exits) == 1:
                    eidx = next(iter(exits))
                    if lo[eidx] < 1:
                        lo[eidx] = 1
                        changed = True
                        if lo[eidx] > hi[eidx]:
                            return None

            if not changed:
                break

        return lo, hi

    def solved(lo, hi):
        if any(lo[eidx] != hi[eidx] for eidx in range(m)):
            return False
        for i in range(n):
            if sum(lo[eidx] for eidx in incident[i]) != vals[i]:
                return False
        return exact_connected(lo)

    def choose_edge(lo, hi):
        best = None
        best_key = None

        island_lo = [0] * n
        island_hi = [0] * n
        for i in range(n):
            for eidx in incident[i]:
                island_lo[i] += lo[eidx]
                island_hi[i] += hi[eidx]

        for eidx in range(m):
            if lo[eidx] == hi[eidx]:
                continue
            u = edges[eidx]["u"]
            v = edges[eidx]["v"]
            domain_size = hi[eidx] - lo[eidx] + 1
            tightness = (island_hi[u] - island_lo[u]) + (island_hi[v] - island_lo[v])
            cross_pressure = -len(crossings[eidx])
            key = (domain_size, tightness, cross_pressure, eidx)
            if best is None or key < best_key:
                best = eidx
                best_key = key
        return best

    def value_order(eidx, lo, hi):
        dom = list(range(lo[eidx], hi[eidx] + 1))
        if len(dom) <= 1:
            return dom

        u = edges[eidx]["u"]
        v = edges[eidx]["v"]

        u_need = vals[u] - sum(lo[x] for x in incident[u])
        v_need = vals[v] - sum(lo[x] for x in incident[v])

        # Prefer positive values when endpoints still need bridges.
        if 0 in dom and (u_need > 0 or v_need > 0):
            positives = [x for x in dom if x > 0]
            positives.sort(reverse=True)
            return positives + [0]

        dom.sort(reverse=True)
        return dom

    seen_states = set()

    def search(lo, hi):
        state = propagate(lo, hi)
        if state is None:
            return None
        lo, hi = state

        key = (tuple(lo), tuple(hi))
        if key in seen_states:
            return None
        seen_states.add(key)

        if solved(lo, hi):
            return lo

        eidx = choose_edge(lo, hi)
        if eidx is None:
            return None

        for val in value_order(eidx, lo, hi):
            lo2 = lo[:]
            hi2 = hi[:]
            lo2[eidx] = val
            hi2[eidx] = val
            out = search(lo2, hi2)
            if out is not None:
                return out

        return None

    result = search(lo0, hi0)
    if result is None:
        return "No Solution"

    # Final validation.
    for i in range(n):
        if sum(result[eidx] for eidx in incident[i]) != vals[i]:
            return "No Solution"
    if not exact_connected(result):
        return "No Solution"

    items = []
    for eidx, count in enumerate(result):
        if count <= 0:
            continue
        u = edges[eidx]["u"]
        v = edges[eidx]["v"]
        a = islands[u][0]
        b = islands[v][0]
        key = (a, b) if a < b else (b, a)
        items.append((key, count))
    items.sort(key=lambda kv: kv[0])

    answer = {}
    for k, v in items:
        answer[k] = v
    return repr(answer)


