OBSERVATION = {'data': [[None, None, None, 1, 1, None, None, None], [None, 2, 1, 3, 2, 1, 3, None], [1, None, None, 2, 2, 2, None, None], [None, None, 1, None, None, 2, 1, None], [None, 1, None, None, 2, 2, None, None], [None, 2, 1, None, 3, 2, 3, None], [None, 2, 1, 2, None, 3, 1, None], [None, None, None, None, None, None, None, None]]}

BS = 1   # '\'
SL = 2   # '/'


class State:
    __slots__ = ("domains", "assigned", "parent", "size")

    def __init__(self, cell_count, dot_count):
        self.domains = [BS | SL] * cell_count
        self.assigned = [0] * cell_count  # 0 = not yet unioned into DSU; otherwise BS/SL
        self.parent = list(range(dot_count))
        self.size = [1] * dot_count

    def copy(self):
        s = State.__new__(State)
        s.domains = self.domains[:]
        s.assigned = self.assigned[:]
        s.parent = self.parent[:]
        s.size = self.size[:]
        return s


class Solver:
    def __init__(self, observation):
        data = observation["data"]
        self.data = data
        self.n = len(data) - 1
        self.dot_n = self.n + 1
        self.cell_count = self.n * self.n
        self.dot_count = self.dot_n * self.dot_n

        self.clues = [None] * self.dot_count
        for r in range(self.dot_n):
            for c in range(self.dot_n):
                self.clues[self.dot_id(r, c)] = data[r][c]

        self.cell_info = [None] * self.cell_count
        self.cell_adj_dots = [None] * self.cell_count
        self.cell_clue_degree = [0] * self.cell_count
        self.dot_incidences = [[] for _ in range(self.dot_count)]

        for r in range(self.n):
            for c in range(self.n):
                cid = self.cell_id(r, c)
                nw = self.dot_id(r, c)
                ne = self.dot_id(r, c + 1)
                sw = self.dot_id(r + 1, c)
                se = self.dot_id(r + 1, c + 1)
                self.cell_info[cid] = (nw, se, ne, sw)  # BS(u,v), SL(u,v)
                self.cell_adj_dots[cid] = (nw, ne, sw, se)

                # Which orientation contributes to each adjacent dot
                self.dot_incidences[nw].append((cid, BS))
                self.dot_incidences[ne].append((cid, SL))
                self.dot_incidences[sw].append((cid, SL))
                self.dot_incidences[se].append((cid, BS))

        self.clue_dots = [i for i, v in enumerate(self.clues) if v is not None]

        for cid in range(self.cell_count):
            deg = 0
            for d in self.cell_adj_dots[cid]:
                if self.clues[d] is not None:
                    deg += 1
            self.cell_clue_degree[cid] = deg

    def dot_id(self, r, c):
        return r * self.dot_n + c

    def cell_id(self, r, c):
        return r * self.n + c

    def find(self, state, x):
        parent = state.parent
        while parent[x] != x:
            x = parent[x]
        return x

    def same(self, state, a, b):
        return self.find(state, a) == self.find(state, b)

    def union(self, state, a, b):
        ra = self.find(state, a)
        rb = self.find(state, b)
        if ra == rb:
            return False
        if state.size[ra] < state.size[rb]:
            ra, rb = rb, ra
        state.parent[rb] = ra
        state.size[ra] += state.size[rb]
        return True

    def set_exact(self, state, cid, orient):
        cur = state.domains[cid]
        if not (cur & orient):
            return -1
        if cur == orient:
            return 0
        if state.assigned[cid] and state.assigned[cid] != orient:
            return -1
        state.domains[cid] = orient
        return 1

    def remove_orient(self, state, cid, orient):
        cur = state.domains[cid]
        if not (cur & orient):
            return 0
        if state.assigned[cid] == orient:
            return -1
        newd = cur & ~orient
        if newd == 0:
            return -1
        if newd == cur:
            return 0
        state.domains[cid] = newd
        return 1

    def orientation_feasible(self, state, cid, orient):
        if not (state.domains[cid] & orient):
            return False

        if orient == BS:
            u, v = self.cell_info[cid][0], self.cell_info[cid][1]
        else:
            u, v = self.cell_info[cid][2], self.cell_info[cid][3]

        # No-loop rule: adding an edge inside the same current component closes a cycle.
        if self.same(state, u, v):
            return False

        # Local clue viability on the four surrounding dots.
        for dot in self.cell_adj_dots[cid]:
            clue = self.clues[dot]
            if clue is None:
                continue

            mn = 0
            mx = 0
            for ocid, need_orient in self.dot_incidences[dot]:
                if ocid == cid:
                    if orient == need_orient:
                        mn += 1
                        mx += 1
                else:
                    d = state.domains[ocid]
                    if d == need_orient:
                        mn += 1
                        mx += 1
                    elif d == (BS | SL):
                        mx += 1

            if clue < mn or clue > mx:
                return False

        return True

    def assign_singletons(self, state):
        changed = False
        for cid in range(self.cell_count):
            if state.assigned[cid]:
                continue
            d = state.domains[cid]
            if d == BS or d == SL:
                if d == BS:
                    u, v = self.cell_info[cid][0], self.cell_info[cid][1]
                else:
                    u, v = self.cell_info[cid][2], self.cell_info[cid][3]
                if self.same(state, u, v):
                    return None
                self.union(state, u, v)
                state.assigned[cid] = d
                changed = True
        return changed

    def propagate(self, state):
        while True:
            overall_changed = False

            # First, commit every fixed cell into the forest.
            ch = self.assign_singletons(state)
            if ch is None:
                return False
            if ch:
                overall_changed = True

            # Then eliminate impossible orientations by local clue bounds + loop test.
            for cid in range(self.cell_count):
                if state.assigned[cid]:
                    continue
                cur = state.domains[cid]
                if cur == (BS | SL):
                    nd = 0
                    if self.orientation_feasible(state, cid, BS):
                        nd |= BS
                    if self.orientation_feasible(state, cid, SL):
                        nd |= SL
                    if nd == 0:
                        return False
                    if nd != cur:
                        state.domains[cid] = nd
                        overall_changed = True
                else:
                    # A still-uncommitted singleton must also remain feasible.
                    if not self.orientation_feasible(state, cid, cur):
                        return False

            # Exact clue propagation: if remaining need is 0, all ambiguous literals are false;
            # if remaining need equals ambiguous count, all are true.
            for dot in self.clue_dots:
                clue = self.clues[dot]
                forced = 0
                ambiguous = []

                for cid, need_orient in self.dot_incidences[dot]:
                    d = state.domains[cid]
                    if d == need_orient:
                        forced += 1
                    elif d == (BS | SL):
                        ambiguous.append((cid, need_orient))

                if clue < forced or clue > forced + len(ambiguous):
                    return False

                if ambiguous:
                    if clue == forced:
                        for cid, need_orient in ambiguous:
                            res = self.remove_orient(state, cid, need_orient)
                            if res < 0:
                                return False
                            if res > 0:
                                overall_changed = True
                    elif clue == forced + len(ambiguous):
                        for cid, need_orient in ambiguous:
                            res = self.set_exact(state, cid, need_orient)
                            if res < 0:
                                return False
                            if res > 0:
                                overall_changed = True

            if not overall_changed:
                return True

    def choose_branch(self, state):
        # Prefer a clue with the fewest ambiguous literals: most human-like and constraining.
        best_key = None
        best_choice = None

        for dot in self.clue_dots:
            clue = self.clues[dot]
            forced = 0
            ambiguous = []

            for cid, need_orient in self.dot_incidences[dot]:
                d = state.domains[cid]
                if d == need_orient:
                    forced += 1
                elif d == (BS | SL):
                    ambiguous.append((cid, need_orient))

            if not ambiguous:
                continue

            need = clue - forced
            tightness = min(need, len(ambiguous) - need)
            key = (len(ambiguous), tightness)

            if best_key is None or key < best_key:
                ambiguous.sort(key=lambda x: (-self.cell_clue_degree[x[0]], x[0]))
                cid, need_orient = ambiguous[0]
                other = SL if need_orient == BS else BS
                if need * 2 > len(ambiguous):
                    order = [need_orient, other]
                elif need * 2 < len(ambiguous):
                    order = [other, need_orient]
                else:
                    order = [need_orient, other]
                best_key = key
                best_choice = (cid, order)

        if best_choice is not None:
            return best_choice

        # Fallback: choose the undecided cell touching the most clues.
        best_cid = None
        best_score = -1
        for cid in range(self.cell_count):
            if state.domains[cid] == (BS | SL):
                score = self.cell_clue_degree[cid]
                if score > best_score:
                    best_score = score
                    best_cid = cid

        if best_cid is None:
            return None

        return best_cid, [BS, SL]

    def is_complete(self, state):
        for d in state.domains:
            if d == (BS | SL):
                return False
        return True

    def validate_complete(self, state):
        if not self.is_complete(state):
            return False

        # Check all clues exactly.
        for dot in self.clue_dots:
            total = 0
            for cid, need_orient in self.dot_incidences[dot]:
                if state.domains[cid] == need_orient:
                    total += 1
            if total != self.clues[dot]:
                return False

        # Re-check no cycles by rebuilding a fresh DSU.
        parent = list(range(self.dot_count))
        size = [1] * self.dot_count

        def find(x):
            while parent[x] != x:
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            return True

        for cid, d in enumerate(state.domains):
            if d == BS:
                a, b = self.cell_info[cid][0], self.cell_info[cid][1]
            else:
                a, b = self.cell_info[cid][2], self.cell_info[cid][3]
            if not union(a, b):
                return False

        return True

    def search(self, state):
        if self.is_complete(state):
            return state if self.validate_complete(state) else None

        branch = self.choose_branch(state)
        if branch is None:
            return state if self.validate_complete(state) else None

        cid, order = branch
        for orient in order:
            if not (state.domains[cid] & orient):
                continue
            nxt = state.copy()
            nxt.domains[cid] = orient
            if self.propagate(nxt):
                res = self.search(nxt)
                if res is not None:
                    return res
        return None

    def grid_repr(self, state):
        grid = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                d = state.domains[self.cell_id(r, c)]
                row.append("\\" if d == BS else "/")
            grid.append(row)
        return repr(grid)

    def solve(self):
        state = State(self.cell_count, self.dot_count)
        if not self.propagate(state):
            return "No Solution"
        res = self.search(state)
        if res is None:
            return "No Solution"
        return self.grid_repr(res)


def solve(observation):
    try:
        return Solver(observation).solve()
    except Exception:
        return "No Solution"


