def solve(observation):
    data = observation["data"]
    region_candidates = [observation["region"]]
    for r in ALTERNATE_REGIONS:
        if r != observation["region"]:
            region_candidates.append(r)

    for region in region_candidates:
        ctx = build_context(region, data)
        if ctx is None:
            continue
        result = solve_one(ctx, data)
        if result is not None and is_valid_solution(result, ctx):
            return str(result)
    return "No Solution"


def build_context(region, data):
    if not isinstance(region, list) or not isinstance(data, list):
        return None
    n = len(region)
    if n == 0 or len(data) != n:
        return None
    if any(len(row) != n for row in region) or any(len(row) != n for row in data):
        return None

    # Normalize region ids to 0..n-1 in first-seen order.
    mapping = {}
    next_id = 0
    reg = [[0] * n for _ in range(n)]
    counts = {}
    for r in range(n):
        for c in range(n):
            x = region[r][c]
            if x not in mapping:
                mapping[x] = next_id
                next_id += 1
            y = mapping[x]
            reg[r][c] = y
            counts[y] = counts.get(y, 0) + 1

    if next_id != n:
        return None
    if any(counts.get(i, 0) != n for i in range(n)):
        return None

    rc_of = []
    reg_of = []
    rows = [[] for _ in range(n)]
    cols = [[] for _ in range(n)]
    regs = [[] for _ in range(n)]

    for r in range(n):
        for c in range(n):
            idx = r * n + c
            rc_of.append((r, c))
            g = reg[r][c]
            reg_of.append(g)
            rows[r].append(idx)
            cols[c].append(idx)
            regs[g].append(idx)

    peers = []
    for idx in range(n * n):
        r, c = rc_of[idx]
        g = reg_of[idx]
        s = set(rows[r]) | set(cols[c]) | set(regs[g])
        s.discard(idx)
        peers.append(tuple(sorted(s)))

    return {
        "n": n,
        "region": reg,
        "rc_of": rc_of,
        "reg_of": reg_of,
        "rows": rows,
        "cols": cols,
        "regs": regs,
        "peers": peers,
    }


def solve_one(ctx, data):
    n = ctx["n"]
    all_mask = (1 << n) - 1
    m = n * n

    grid = [0] * m
    dom = [all_mask] * m
    row_missing = [all_mask] * n
    col_missing = [all_mask] * n
    reg_missing = [all_mask] * n

    # Place givens.
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= n):
                return None
            idx = r * n + c
            bit = 1 << (v - 1)
            g = ctx["reg_of"][idx]
            if not (row_missing[r] & bit and col_missing[c] & bit and reg_missing[g] & bit):
                return None
            grid[idx] = v
            dom[idx] = bit
            row_missing[r] &= ~bit
            col_missing[c] &= ~bit
            reg_missing[g] &= ~bit

    # Initial candidate masks.
    for idx in range(m):
        if grid[idx]:
            continue
        r, c = ctx["rc_of"][idx]
        g = ctx["reg_of"][idx]
        dom[idx] = row_missing[r] & col_missing[c] & reg_missing[g]
        if dom[idx] == 0:
            return None

    if not propagate(ctx, grid, dom, row_missing, col_missing, reg_missing):
        return None

    solved = search(ctx, grid, dom, row_missing, col_missing, reg_missing)
    if solved is None:
        return None

    n2 = ctx["n"]
    return [solved[i * n2:(i + 1) * n2] for i in range(n2)]


def search(ctx, grid, dom, row_missing, col_missing, reg_missing):
    if all(v != 0 for v in grid):
        return grid

    branch = choose_branch(ctx, grid, dom, row_missing, col_missing, reg_missing)
    if branch is None:
        return None

    kind = branch[0]

    if kind == "cell":
        idx, options = branch[1], branch[2]
        options = sorted(options, key=lambda b: value_score(ctx, grid, dom, idx, b))
        for bit in options:
            g2 = grid[:]
            d2 = dom[:]
            rm2 = row_missing[:]
            cm2 = col_missing[:]
            gm2 = reg_missing[:]
            if assign(ctx, g2, d2, rm2, cm2, gm2, idx, bit):
                if propagate(ctx, g2, d2, rm2, cm2, gm2):
                    ans = search(ctx, g2, d2, rm2, cm2, gm2)
                    if ans is not None:
                        return ans
        return None

    if kind == "place":
        bit, cells = branch[1], branch[2]
        cells = sorted(cells, key=lambda i: place_score(ctx, grid, dom, i, bit))
        for idx in cells:
            g2 = grid[:]
            d2 = dom[:]
            rm2 = row_missing[:]
            cm2 = col_missing[:]
            gm2 = reg_missing[:]
            if assign(ctx, g2, d2, rm2, cm2, gm2, idx, bit):
                if propagate(ctx, g2, d2, rm2, cm2, gm2):
                    ans = search(ctx, g2, d2, rm2, cm2, gm2)
                    if ans is not None:
                        return ans
        return None

    return None


def choose_branch(ctx, grid, dom, row_missing, col_missing, reg_missing):
    n = ctx["n"]

    best_kind = None
    best_size = 10**9
    best_payload = None

    # Most constrained cell.
    for idx, v in enumerate(grid):
        if v == 0:
            cnt = dom[idx].bit_count()
            if cnt < 2:
                continue
            if cnt < best_size:
                best_kind = "cell"
                best_size = cnt
                best_payload = (idx, list(iter_bits(dom[idx])))
                if cnt == 2:
                    break

    # Also consider "where can this digit go?" branching.
    for r in range(n):
        changed = consider_unit_digit_branch(ctx["rows"][r], row_missing[r], dom, grid, best_size)
        if changed is not None:
            best_kind, best_size, best_payload = changed
            if best_size == 2:
                break
    if best_size != 2:
        for c in range(n):
            changed = consider_unit_digit_branch(ctx["cols"][c], col_missing[c], dom, grid, best_size)
            if changed is not None:
                best_kind, best_size, best_payload = changed
                if best_size == 2:
                    break
    if best_size != 2:
        for g in range(n):
            changed = consider_unit_digit_branch(ctx["regs"][g], reg_missing[g], dom, grid, best_size)
            if changed is not None:
                best_kind, best_size, best_payload = changed
                if best_size == 2:
                    break

    if best_kind is None:
        return None
    return (best_kind,) + best_payload


def consider_unit_digit_branch(unit, missing_mask, dom, grid, current_best):
    for bit in iter_bits(missing_mask):
        cells = [i for i in unit if grid[i] == 0 and (dom[i] & bit)]
        k = len(cells)
        if 1 < k < current_best:
            return ("place", k, bit, cells)
    return None


def value_score(ctx, grid, dom, idx, bit):
    # Least constraining value: fewer peer removals is preferred.
    score = 0
    for j in ctx["peers"][idx]:
        if grid[j] == 0 and (dom[j] & bit):
            score += 1
    return score


def place_score(ctx, grid, dom, idx, bit):
    # Prefer the cell that is already tight.
    return dom[idx].bit_count()


def propagate(ctx, grid, dom, row_missing, col_missing, reg_missing):
    while True:
        if not apply_singles(ctx, grid, dom, row_missing, col_missing, reg_missing):
            return False
        if all(v != 0 for v in grid):
            return True

        changed = apply_hidden_singles(ctx, grid, dom, row_missing, col_missing, reg_missing)
        if changed < 0:
            return False
        if changed > 0:
            continue

        changed = apply_intersections(ctx, grid, dom, row_missing, col_missing, reg_missing)
        if changed < 0:
            return False
        if changed > 0:
            continue

        changed = apply_subsets(ctx, grid, dom, row_missing, col_missing, reg_missing)
        if changed < 0:
            return False
        if changed > 0:
            continue

        # Final consistency check before stopping.
        if not consistency_check(ctx, grid, dom, row_missing, col_missing, reg_missing):
            return False
        return True


def apply_singles(ctx, grid, dom, row_missing, col_missing, reg_missing):
    progress = True
    while progress:
        progress = False
        for idx, v in enumerate(grid):
            if v == 0 and is_singleton(dom[idx]):
                if not assign(ctx, grid, dom, row_missing, col_missing, reg_missing, idx, dom[idx]):
                    return False
                progress = True
    return True


def apply_hidden_singles(ctx, grid, dom, row_missing, col_missing, reg_missing):
    for r, unit in enumerate(ctx["rows"]):
        res = hidden_single_in_unit(ctx, unit, row_missing[r], grid, dom, row_missing, col_missing, reg_missing)
        if res != 0:
            return res
    for c, unit in enumerate(ctx["cols"]):
        res = hidden_single_in_unit(ctx, unit, col_missing[c], grid, dom, row_missing, col_missing, reg_missing)
        if res != 0:
            return res
    for g, unit in enumerate(ctx["regs"]):
        res = hidden_single_in_unit(ctx, unit, reg_missing[g], grid, dom, row_missing, col_missing, reg_missing)
        if res != 0:
            return res
    return 0


def hidden_single_in_unit(ctx, unit, missing_mask, grid, dom, row_missing, col_missing, reg_missing):
    for bit in iter_bits(missing_mask):
        cells = [i for i in unit if grid[i] == 0 and (dom[i] & bit)]
        if not cells:
            return -1
        if len(cells) == 1:
            if not assign(ctx, grid, dom, row_missing, col_missing, reg_missing, cells[0], bit):
                return -1
            return 1
    return 0


def apply_intersections(ctx, grid, dom, row_missing, col_missing, reg_missing):
    n = ctx["n"]

    # Region -> row / column pointing.
    for g, unit in enumerate(ctx["regs"]):
        for bit in iter_bits(reg_missing[g]):
            cells = [i for i in unit if grid[i] == 0 and (dom[i] & bit)]
            if not cells:
                return -1
            rows = {ctx["rc_of"][i][0] for i in cells}
            if len(rows) == 1:
                r = next(iter(rows))
                for j in ctx["rows"][r]:
                    if ctx["reg_of"][j] != g and grid[j] == 0 and (dom[j] & bit):
                        if not reduce_mask(dom, j, bit):
                            return -1
                        return 1
            cols = {ctx["rc_of"][i][1] for i in cells}
            if len(cols) == 1:
                c = next(iter(cols))
                for j in ctx["cols"][c]:
                    if ctx["reg_of"][j] != g and grid[j] == 0 and (dom[j] & bit):
                        if not reduce_mask(dom, j, bit):
                            return -1
                        return 1

    # Row -> region claiming.
    for r, unit in enumerate(ctx["rows"]):
        for bit in iter_bits(row_missing[r]):
            cells = [i for i in unit if grid[i] == 0 and (dom[i] & bit)]
            if not cells:
                return -1
            regs = {ctx["reg_of"][i] for i in cells}
            if len(regs) == 1:
                g = next(iter(regs))
                for j in ctx["regs"][g]:
                    if ctx["rc_of"][j][0] != r and grid[j] == 0 and (dom[j] & bit):
                        if not reduce_mask(dom, j, bit):
                            return -1
                        return 1

    # Column -> region claiming.
    for c, unit in enumerate(ctx["cols"]):
        for bit in iter_bits(col_missing[c]):
            cells = [i for i in unit if grid[i] == 0 and (dom[i] & bit)]
            if not cells:
                return -1
            regs = {ctx["reg_of"][i] for i in cells}
            if len(regs) == 1:
                g = next(iter(regs))
                for j in ctx["regs"][g]:
                    if ctx["rc_of"][j][1] != c and grid[j] == 0 and (dom[j] & bit):
                        if not reduce_mask(dom, j, bit):
                            return -1
                        return 1

    return 0


def apply_subsets(ctx, grid, dom, row_missing, col_missing, reg_missing):
    for r, unit in enumerate(ctx["rows"]):
        res = subsets_in_unit(unit, row_missing[r], grid, dom)
        if res != 0:
            return res
    for c, unit in enumerate(ctx["cols"]):
        res = subsets_in_unit(unit, col_missing[c], grid, dom)
        if res != 0:
            return res
    for g, unit in enumerate(ctx["regs"]):
        res = subsets_in_unit(unit, reg_missing[g], grid, dom)
        if res != 0:
            return res
    return 0


def subsets_in_unit(unit, missing_mask, grid, dom):
    unsolved = [i for i in unit if grid[i] == 0]
    ulen = len(unsolved)
    if ulen < 2:
        return 0

    max_k = min(4, ulen - 1)

    # Naked subsets.
    for k in range(2, max_k + 1):
        for cells in combinations(unsolved, k):
            union = 0
            for i in cells:
                union |= dom[i]
            if union.bit_count() != k:
                continue
            changed = False
            for j in unsolved:
                if j not in cells and (dom[j] & union):
                    if not reduce_mask(dom, j, union):
                        return -1
                    changed = True
            if changed:
                return 1

    # Hidden subsets.
    bits = list(iter_bits(missing_mask))
    max_k = min(4, len(bits) - 1, ulen - 1)
    for k in range(2, max_k + 1):
        for combo in combinations(bits, k):
            mask = 0
            for b in combo:
                mask |= b
            cells = [i for i in unsolved if dom[i] & mask]
            if len(cells) != k:
                continue
            changed = False
            for i in cells:
                new_mask = dom[i] & mask
                if new_mask == 0:
                    return -1
                if new_mask != dom[i]:
                    dom[i] = new_mask
                    changed = True
            if changed:
                return 1

    return 0


def consistency_check(ctx, grid, dom, row_missing, col_missing, reg_missing):
    n = ctx["n"]

    for idx, v in enumerate(grid):
        if v == 0 and dom[idx] == 0:
            return False

    for r in range(n):
        for bit in iter_bits(row_missing[r]):
            if not any(grid[i] == 0 and (dom[i] & bit) for i in ctx["rows"][r]):
                return False
    for c in range(n):
        for bit in iter_bits(col_missing[c]):
            if not any(grid[i] == 0 and (dom[i] & bit) for i in ctx["cols"][c]):
                return False
    for g in range(n):
        for bit in iter_bits(reg_missing[g]):
            if not any(grid[i] == 0 and (dom[i] & bit) for i in ctx["regs"][g]):
                return False

    return True


def assign(ctx, grid, dom, row_missing, col_missing, reg_missing, idx, bit):
    if bit == 0 or bit & (bit - 1):
        return False

    if grid[idx] != 0:
        return dom[idx] == bit

    if not (dom[idx] & bit):
        return False

    r, c = ctx["rc_of"][idx]
    g = ctx["reg_of"][idx]

    if not (row_missing[r] & bit and col_missing[c] & bit and reg_missing[g] & bit):
        return False

    grid[idx] = bit.bit_length()
    dom[idx] = bit
    row_missing[r] &= ~bit
    col_missing[c] &= ~bit
    reg_missing[g] &= ~bit

    for j in ctx["peers"][idx]:
        if grid[j] == 0 and (dom[j] & bit):
            dom[j] &= ~bit
            if dom[j] == 0:
                return False

    return True


def reduce_mask(dom, idx, remove_bits):
    new_mask = dom[idx] & ~remove_bits
    if new_mask == 0:
        return False
    dom[idx] = new_mask
    return True


def iter_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit
        mask ^= bit


def is_singleton(mask):
    return mask != 0 and (mask & (mask - 1)) == 0


def is_valid_solution(grid2d, ctx):
    n = ctx["n"]
    target = set(range(1, n + 1))

    if len(grid2d) != n or any(len(row) != n for row in grid2d):
        return False

    for r in range(n):
        if set(grid2d[r]) != target:
            return False

    for c in range(n):
        if {grid2d[r][c] for r in range(n)} != target:
            return False

    reg_vals = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            g = ctx["region"][r][c]
            reg_vals[g].append(grid2d[r][c])

    for vals in reg_vals:
        if set(vals) != target or len(vals) != n:
            return False

    return True


