    print(solve(OBSERVATION))

OBSERVATION = {'tree': [[None, 'T', None, None, None, 'T', None, None, None, None], ['T', None, None, 'T', None, None, None, None, None, None], [None, None, None, None, None, None, None, None, 'T', None], [None, None, None, None, None, None, 'T', None, 'T', None], [None, None, None, None, None, None, None, None, None, None], ['T', None, None, 'T', None, None, None, 'T', 'T', None], [None, None, None, None, 'T', None, 'T', None, None, None], [None, 'T', None, None, None, None, None, 'T', 'T', None], [None, None, None, None, None, None, 'T', None, None, None], [None, 'T', None, 'T', None, None, None, None, 'T', None]], 'row_tent_counts': [2, 1, 2, 1, 2, 2, 3, 2, 3, 2], 'col_tent_counts': [3, 1, 1, 3, 1, 2, 2, 3, 0, 4]}

# Tents solver using human-style deduction plus constrained search.
# Key modeling choice:
# - A valid tent cell must be orthogonally adjacent to exactly one tree.
#   This makes every candidate belong to exactly one tree, so the 1-to-1 pairing
#   becomes a direct "exactly one candidate per tree" constraint.

def solve(observation):
    tree_grid = observation["tree"]
    row_counts = observation["row_tent_counts"][:]
    col_counts = observation["col_tent_counts"][:]

    R = len(tree_grid)
    C = len(tree_grid[0]) if R else 0

    trees = []
    tree_index = {}
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == "T":
                tree_index[(r, c)] = len(trees)
                trees.append((r, c))

    T = len(trees)
    total_tents = sum(row_counts)
    if total_tents != sum(col_counts) or total_tents != T:
        return "No Solution"

    ortho = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    candidates = []
    cand_of_tree = [[] for _ in range(T)]
    row_cells = [[] for _ in range(R)]
    col_cells = [[] for _ in range(C)]
    cell_to_cand = {}

    # Candidate cells: empty cells adjacent orthogonally to exactly one tree.
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == "T":
                continue
            adj = []
            for dr, dc in ortho:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and tree_grid[nr][nc] == "T":
                    adj.append(tree_index[(nr, nc)])
            if len(adj) == 1:
                t = adj[0]
                idx = len(candidates)
                candidates.append((r, c, t))
                cand_of_tree[t].append(idx)
                row_cells[r].append(idx)
                col_cells[c].append(idx)
                cell_to_cand[(r, c)] = idx

    # Every tree must have at least one candidate.
    for t in range(T):
        if not cand_of_tree[t]:
            return "No Solution"

    # Immediate row/column capacity checks.
    for r in range(R):
        if row_counts[r] > len(row_cells[r]):
            return "No Solution"
    for c in range(C):
        if col_counts[c] > len(col_cells[c]):
            return "No Solution"

    N = len(candidates)

    # Candidate conflict graph for "tents cannot touch, even diagonally".
    touch = [[] for _ in range(N)]
    for i, (r, c, _) in enumerate(candidates):
        for nr in range(max(0, r - 1), min(R, r + 2)):
            for nc in range(max(0, c - 1), min(C, c + 2)):
                if nr == r and nc == c:
                    continue
                j = cell_to_cand.get((nr, nc))
                if j is not None:
                    touch[i].append(j)

    # Trees that can affect each row/column.
    row_related_trees = [set() for _ in range(R)]
    col_related_trees = [set() for _ in range(C)]
    for t in range(T):
        for j in cand_of_tree[t]:
            r, c, _ = candidates[j]
            row_related_trees[r].add(t)
            col_related_trees[c].add(t)

    UNKNOWN, EMPTY, TENT = -1, 0, 1

    def propagate(status, row_need, col_need, row_unknown, col_unknown, tree_true, tree_unknown, pending, full_scan=False):
        queue = list(pending)
        qh = 0

        def process_tree(t):
            if tree_true[t] > 1:
                return False
            if tree_true[t] + tree_unknown[t] < 1:
                return False
            if tree_true[t] == 1:
                for j in cand_of_tree[t]:
                    if status[j] == UNKNOWN:
                        queue.append((EMPTY, j))
            elif tree_unknown[t] == 1:
                for j in cand_of_tree[t]:
                    if status[j] == UNKNOWN:
                        queue.append((TENT, j))
                        break
            return True

        def process_row(r):
            need = row_need[r]
            if need < 0 or need > row_unknown[r]:
                return False

            if need == 0:
                for j in row_cells[r]:
                    if status[j] == UNKNOWN:
                        queue.append((EMPTY, j))
            elif need == row_unknown[r]:
                for j in row_cells[r]:
                    if status[j] == UNKNOWN:
                        queue.append((TENT, j))

            forced_trees = []
            possible_trees = []

            for t in row_related_trees[r]:
                if tree_true[t] == 1:
                    continue
                has_in = False
                has_out = False
                for j in cand_of_tree[t]:
                    if status[j] != EMPTY:
                        rr, _, _ = candidates[j]
                        if rr == r:
                            has_in = True
                        else:
                            has_out = True
                if has_in:
                    possible_trees.append(t)
                    if not has_out:
                        forced_trees.append(t)

            lb = len(forced_trees)
            ub = len(possible_trees)
            if need < lb or need > ub:
                return False

            if need == lb:
                forced_set = set(forced_trees)
                for j in row_cells[r]:
                    if status[j] == UNKNOWN and candidates[j][2] not in forced_set:
                        queue.append((EMPTY, j))

            if need == ub:
                possible_set = set(possible_trees)
                for t in possible_set:
                    for j in cand_of_tree[t]:
                        if status[j] == UNKNOWN and candidates[j][0] != r:
                            queue.append((EMPTY, j))

            return True

        def process_col(c):
            need = col_need[c]
            if need < 0 or need > col_unknown[c]:
                return False

            if need == 0:
                for j in col_cells[c]:
                    if status[j] == UNKNOWN:
                        queue.append((EMPTY, j))
            elif need == col_unknown[c]:
                for j in col_cells[c]:
                    if status[j] == UNKNOWN:
                        queue.append((TENT, j))

            forced_trees = []
            possible_trees = []

            for t in col_related_trees[c]:
                if tree_true[t] == 1:
                    continue
                has_in = False
                has_out = False
                for j in cand_of_tree[t]:
                    if status[j] != EMPTY:
                        _, cc, _ = candidates[j]
                        if cc == c:
                            has_in = True
                        else:
                            has_out = True
                if has_in:
                    possible_trees.append(t)
                    if not has_out:
                        forced_trees.append(t)

            lb = len(forced_trees)
            ub = len(possible_trees)
            if need < lb or need > ub:
                return False

            if need == lb:
                forced_set = set(forced_trees)
                for j in col_cells[c]:
                    if status[j] == UNKNOWN and candidates[j][2] not in forced_set:
                        queue.append((EMPTY, j))

            if need == ub:
                possible_set = set(possible_trees)
                for t in possible_set:
                    for j in cand_of_tree[t]:
                        if status[j] == UNKNOWN and candidates[j][1] != c:
                            queue.append((EMPTY, j))

            return True

        if full_scan:
            for t in range(T):
                if not process_tree(t):
                    return False
            for r in range(R):
                if not process_row(r):
                    return False
            for c in range(C):
                if not process_col(c):
                    return False

        while qh < len(queue):
            action, j = queue[qh]
            qh += 1

            cur = status[j]
            if action == TENT:
                if cur == TENT:
                    continue
                if cur == EMPTY:
                    return False

                r, c, t = candidates[j]
                status[j] = TENT
                row_need[r] -= 1
                col_need[c] -= 1
                row_unknown[r] -= 1
                col_unknown[c] -= 1
                tree_true[t] += 1
                tree_unknown[t] -= 1

                if row_need[r] < 0 or col_need[c] < 0 or tree_true[t] > 1:
                    return False

                for k in touch[j]:
                    if status[k] == TENT:
                        return False
                    if status[k] == UNKNOWN:
                        queue.append((EMPTY, k))

                for k in cand_of_tree[t]:
                    if k != j:
                        if status[k] == TENT:
                            return False
                        if status[k] == UNKNOWN:
                            queue.append((EMPTY, k))

                if not process_tree(t):
                    return False
                if not process_row(r):
                    return False
                if not process_col(c):
                    return False

            else:
                if cur == EMPTY:
                    continue
                if cur == TENT:
                    return False

                r, c, t = candidates[j]
                status[j] = EMPTY
                row_unknown[r] -= 1
                col_unknown[c] -= 1
                tree_unknown[t] -= 1

                if row_need[r] > row_unknown[r] or col_need[c] > col_unknown[c]:
                    return False
                if tree_true[t] + tree_unknown[t] < 1:
                    return False

                if not process_tree(t):
                    return False
                if not process_row(r):
                    return False
                if not process_col(c):
                    return False

        return True

    def solved(tree_true, row_need, col_need):
        if any(x != 1 for x in tree_true):
            return False
        if any(x != 0 for x in row_need):
            return False
        if any(x != 0 for x in col_need):
            return False
        return True

    def choose_tree(status, tree_true, tree_unknown, row_need, col_need):
        best_t = None
        best_key = None
        for t in range(T):
            if tree_true[t] == 1:
                continue
            k = tree_unknown[t]
            if k <= 0:
                return None
            # Human-like MRV: choose tree with fewest remaining options.
            # Tie-break: options with tighter rows/cols and more conflicts.
            impact = 0
            for j in cand_of_tree[t]:
                if status[j] == UNKNOWN:
                    r, c, _ = candidates[j]
                    impact += len(touch[j]) * 4 + (row_unknown[r] - row_need[r]) + (col_unknown[c] - col_need[c])
            key = (k, -impact)
            if best_key is None or key < best_key:
                best_key = key
                best_t = t
        return best_t

    def ordered_candidates_for_tree(t, status, row_need, col_need, row_unknown, col_unknown):
        opts = [j for j in cand_of_tree[t] if status[j] == UNKNOWN]

        def key(j):
            r, c, _ = candidates[j]
            # Prefer cells in tighter lines and with larger exclusion effect.
            slack = (row_unknown[r] - row_need[r]) + (col_unknown[c] - col_need[c])
            return (slack, -len(touch[j]), r, c)

        opts.sort(key=key)
        return opts

    def dfs(status, row_need, col_need, row_unknown, col_unknown, tree_true, tree_unknown):
        if solved(tree_true, row_need, col_need):
            ans = [[None for _ in range(C)] for _ in range(R)]
            for j, s in enumerate(status):
                if s == TENT:
                    r, c, _ = candidates[j]
                    ans[r][c] = "t"
            return ans

        t = choose_tree(status, tree_true, tree_unknown, row_need, col_need)
        if t is None:
            return None

        for j in ordered_candidates_for_tree(t, status, row_need, col_need, row_unknown, col_unknown):
            s2 = status[:]
            rn2 = row_need[:]
            cn2 = col_need[:]
            ru2 = row_unknown[:]
            cu2 = col_unknown[:]
            tt2 = tree_true[:]
            tu2 = tree_unknown[:]

            if propagate(s2, rn2, cn2, ru2, cu2, tt2, tu2, [(TENT, j)], full_scan=False):
                res = dfs(s2, rn2, cn2, ru2, cu2, tt2, tu2)
                if res is not None:
                    return res

        return None

    status = [UNKNOWN] * N
    row_need = row_counts[:]
    col_need = col_counts[:]
    row_unknown = [len(row_cells[r]) for r in range(R)]
    col_unknown = [len(col_cells[c]) for c in range(C)]
    tree_true = [0] * T
    tree_unknown = [len(cand_of_tree[t]) for t in range(T)]

    if not propagate(status, row_need, col_need, row_unknown, col_unknown, tree_true, tree_unknown, [], full_scan=True):
        return "No Solution"

    result = dfs(status, row_need, col_need, row_unknown, col_unknown, tree_true, tree_unknown)
    if result is None:
        return "No Solution"
    return repr(result)


