from collections import deque

# The solver supports two interpretations:
# 1) Corner-hole model:
#    - region is an R x C cell grid
#    - holes are (R+1) x (C+1)
#    - every boundary edge between different regions must have exactly one of its endpoint holes used
#    - used holes must be pairable into stitches (a matching on the hole-grid graph)
#    - row/col clues count used holes
#
# 2) Center-hole model:
#    - region is an R x C cell grid
#    - holes are also R x C, one per cell center
#    - every orthogonally adjacent different-region cell pair is itself a required stitch
#    - row/col clues count used holes
#
# The image strongly suggests a corner-hole interpretation for this OBSERVATION,
# but the code keeps both paths generalized.

UNKNOWN = -1
UNUSED = 0
USED = 1


def solve(observation):
    region = observation["region"]
    row_counts = observation["row_stitch_counts"]
    col_counts = observation["col_stitch_counts"]

    attempts = []

    r = len(region)
    c = len(region[0]) if r else 0

    if len(row_counts) == r + 1 and len(col_counts) == c + 1:
        ans = solve_corner_hole_model(region, row_counts, col_counts)
        attempts.append(ans)

    if len(row_counts) == r and len(col_counts) == c:
        ans = solve_center_hole_model(region, row_counts, col_counts)
        attempts.append(ans)

    for ans in attempts:
        if ans != "No Solution":
            return ans
    return "No Solution"


def solve_center_hole_model(region, row_counts, col_counts):
    r = len(region)
    c = len(region[0]) if r else 0

    stitches = []
    degree = {}
    used = set()

    for i in range(r):
        for j in range(c):
            if j + 1 < c and region[i][j] != region[i][j + 1]:
                a = (i, j)
                b = (i, j + 1)
                degree[a] = degree.get(a, 0) + 1
                degree[b] = degree.get(b, 0) + 1
                stitches.append([a, b])
                used.add(a)
                used.add(b)
            if i + 1 < r and region[i][j] != region[i + 1][j]:
                a = (i, j)
                b = (i + 1, j)
                degree[a] = degree.get(a, 0) + 1
                degree[b] = degree.get(b, 0) + 1
                stitches.append([a, b])
                used.add(a)
                used.add(b)

    if any(v > 1 for v in degree.values()):
        return "No Solution"

    rr = [0] * r
    cc = [0] * c
    for i, j in used:
        rr[i] += 1
        cc[j] += 1

    if rr != row_counts or cc != col_counts:
        return "No Solution"

    stitches = normalize_stitches(stitches)
    return str(stitches)


def solve_corner_hole_model(region, row_counts, col_counts):
    problem = build_corner_problem(region, row_counts, col_counts)
    if problem is None:
        return "No Solution"

    H = problem["H"]
    W = problem["W"]

    target_total = sum(row_counts)
    if target_total != sum(col_counts):
        return "No Solution"
    if target_total % 2 != 0:
        return "No Solution"

    state = [UNKNOWN] * (H * W)

    state = search_holes(problem, state)
    if state is None:
        return "No Solution"

    stitches = build_matching_from_used(problem, state)
    if stitches is None:
        return "No Solution"

    stitches = normalize_stitches(stitches)
    return str(stitches)


def build_corner_problem(region, row_counts, col_counts):
    R = len(region)
    C = len(region[0]) if R else 0
    H = R + 1
    W = C + 1

    if len(row_counts) != H or len(col_counts) != W:
        return None

    def hid(i, j):
        return i * W + j

    neighbors = [[] for _ in range(H * W)]
    for i in range(H):
        for j in range(W):
            h = hid(i, j)
            if i > 0:
                neighbors[h].append(hid(i - 1, j))
            if i + 1 < H:
                neighbors[h].append(hid(i + 1, j))
            if j > 0:
                neighbors[h].append(hid(i, j - 1))
            if j + 1 < W:
                neighbors[h].append(hid(i, j + 1))

    # Boundary constraints:
    # For each adjacent different-region cell pair, exactly one endpoint hole on their shared edge is used.
    boundaries = []
    hole_to_boundaries = [[] for _ in range(H * W)]

    for i in range(R):
        for j in range(C):
            if j + 1 < C and region[i][j] != region[i][j + 1]:
                a = hid(i, j + 1)
                b = hid(i + 1, j + 1)
                idx = len(boundaries)
                boundaries.append((a, b))
                hole_to_boundaries[a].append(idx)
                hole_to_boundaries[b].append(idx)
            if i + 1 < R and region[i][j] != region[i + 1][j]:
                a = hid(i + 1, j)
                b = hid(i + 1, j + 1)
                idx = len(boundaries)
                boundaries.append((a, b))
                hole_to_boundaries[a].append(idx)
                hole_to_boundaries[b].append(idx)

    row_holes = [[hid(i, j) for j in range(W)] for i in range(H)]
    col_holes = [[hid(i, j) for i in range(H)] for j in range(W)]

    return {
        "R": R,
        "C": C,
        "H": H,
        "W": W,
        "row_counts": row_counts[:],
        "col_counts": col_counts[:],
        "neighbors": neighbors,
        "boundaries": boundaries,
        "hole_to_boundaries": hole_to_boundaries,
        "row_holes": row_holes,
        "col_holes": col_holes,
    }


def search_holes(problem, state):
    state = propagate(problem, state)
    if state is None:
        return None

    if all(v != UNKNOWN for v in state):
        stitches = build_matching_from_used(problem, state)
        if stitches is None:
            return None
        return state

    branch = choose_branch(problem, state)
    if branch is None:
        return None

    kind = branch[0]

    if kind == "boundary":
        _, a, b = branch
        order = boundary_branch_order(problem, state, a, b)
        for va, vb in order:
            nxt = state[:]
            nxt[a] = va
            nxt[b] = vb
            res = search_holes(problem, nxt)
            if res is not None:
                return res
        return None

    if kind == "hole":
        _, h = branch
        order = hole_branch_order(problem, state, h)
        for v in order:
            nxt = state[:]
            nxt[h] = v
            res = search_holes(problem, nxt)
            if res is not None:
                return res
        return None

    return None


def propagate(problem, state):
    H = problem["H"]
    W = problem["W"]
    row_counts = problem["row_counts"]
    col_counts = problem["col_counts"]
    boundaries = problem["boundaries"]
    neighbors = problem["neighbors"]
    row_holes = problem["row_holes"]
    col_holes = problem["col_holes"]

    changed = True
    while changed:
        changed = False

        # Exact-one propagation on every boundary.
        for a, b in boundaries:
            sa = state[a]
            sb = state[b]

            if sa == USED and sb == USED:
                return None
            if sa == UNUSED and sb == UNUSED:
                return None

            if sa == USED and sb == UNKNOWN:
                state[b] = UNUSED
                changed = True
            elif sb == USED and sa == UNKNOWN:
                state[a] = UNUSED
                changed = True
            elif sa == UNUSED and sb == UNKNOWN:
                state[b] = USED
                changed = True
            elif sb == UNUSED and sa == UNKNOWN:
                state[a] = USED
                changed = True

        # Row clue propagation.
        for i in range(H):
            holes = row_holes[i]
            used = 0
            unknowns = []
            for h in holes:
                if state[h] == USED:
                    used += 1
                elif state[h] == UNKNOWN:
                    unknowns.append(h)

            clue = row_counts[i]
            if used > clue or used + len(unknowns) < clue:
                return None
            if used == clue:
                for h in unknowns:
                    state[h] = UNUSED
                    changed = True
            elif used + len(unknowns) == clue:
                for h in unknowns:
                    state[h] = USED
                    changed = True

        # Column clue propagation.
        for j in range(W):
            holes = col_holes[j]
            used = 0
            unknowns = []
            for h in holes:
                if state[h] == USED:
                    used += 1
                elif state[h] == UNKNOWN:
                    unknowns.append(h)

            clue = col_counts[j]
            if used > clue or used + len(unknowns) < clue:
                return None
            if used == clue:
                for h in unknowns:
                    state[h] = UNUSED
                    changed = True
            elif used + len(unknowns) == clue:
                for h in unknowns:
                    state[h] = USED
                    changed = True

        # Local matching feasibility on hole graph.
        for h in range(H * W):
            if state[h] == UNKNOWN:
                possible_neighbors = [n for n in neighbors[h] if state[n] != UNUSED]
                if not possible_neighbors:
                    state[h] = UNUSED
                    changed = True

        for h in range(H * W):
            if state[h] == USED:
                possible_neighbors = [n for n in neighbors[h] if state[n] != UNUSED]
                if not possible_neighbors:
                    return None
                if len(possible_neighbors) == 1 and state[possible_neighbors[0]] == UNKNOWN:
                    state[possible_neighbors[0]] = USED
                    changed = True

        # Global parity checks from clues and current rows/cols.
        total_used = sum(1 for v in state if v == USED)
        total_unknown = sum(1 for v in state if v == UNKNOWN)
        target_total = sum(row_counts)
        if total_used > target_total or total_used + total_unknown < target_total:
            return None

    # Stronger feasibility check: every connected component of holes that are not UNUSED
    # must contain enough room for the currently forced USED holes, and every fully fixed
    # USED-only component must have even size.
    if not component_feasibility(problem, state):
        return None

    return state


def component_feasibility(problem, state):
    H = problem["H"]
    W = problem["W"]
    neighbors = problem["neighbors"]
    seen = [False] * (H * W)

    for s in range(H * W):
        if state[s] == UNUSED or seen[s]:
            continue

        stack = [s]
        seen[s] = True
        comp = []
        used_cnt = 0
        unknown_cnt = 0

        while stack:
            v = stack.pop()
            comp.append(v)
            if state[v] == USED:
                used_cnt += 1
            elif state[v] == UNKNOWN:
                unknown_cnt += 1
            for u in neighbors[v]:
                if state[u] != UNUSED and not seen[u]:
                    seen[u] = True
                    stack.append(u)

        if used_cnt > len(comp):
            return False

        # If the component is fully decided, it must have even size for a perfect matching.
        if unknown_cnt == 0 and used_cnt % 2 == 1:
            return False

        # Bipartite side balance is necessary for any perfect matching extension.
        left = 0
        right = 0
        for v in comp:
            i, j = divmod(v, W)
            if (i + j) & 1:
                right += 1
            else:
                left += 1
        if abs(left - right) > unknown_cnt:
            return False

    return True


def choose_branch(problem, state):
    boundaries = problem["boundaries"]
    hole_to_boundaries = problem["hole_to_boundaries"]

    # Human-like choice: first branch on an unresolved exact-one boundary.
    best = None
    best_score = None
    for a, b in boundaries:
        if state[a] == UNKNOWN and state[b] == UNKNOWN:
            score = len(hole_to_boundaries[a]) + len(hole_to_boundaries[b])
            if best_score is None or score > best_score:
                best_score = score
                best = ("boundary", a, b)
    if best is not None:
        return best

    # Otherwise branch on the most constrained hole.
    neighbors = problem["neighbors"]
    row_counts = problem["row_counts"]
    col_counts = problem["col_counts"]
    W = problem["W"]

    best = None
    best_key = None
    for h, v in enumerate(state):
        if v != UNKNOWN:
            continue
        i, j = divmod(h, W)
        possible_neighbors = sum(1 for n in neighbors[h] if state[n] != UNUSED)
        tightness = (
            abs(row_counts[i] - row_used_count(problem, state, i)),
            abs(col_counts[j] - col_used_count(problem, state, j)),
        )
        key = (
            possible_neighbors,
            -len(hole_to_boundaries[h]),
            tightness[0] + tightness[1],
        )
        if best_key is None or key < best_key:
            best_key = key
            best = ("hole", h)
    return best


def row_used_count(problem, state, i):
    return sum(1 for h in problem["row_holes"][i] if state[h] == USED)


def col_used_count(problem, state, j):
    return sum(1 for h in problem["col_holes"][j] if state[h] == USED)


def boundary_branch_order(problem, state, a, b):
    W = problem["W"]
    ai, aj = divmod(a, W)
    bi, bj = divmod(b, W)

    ra_need = problem["row_counts"][ai] - row_used_count(problem, state, ai)
    rb_need = problem["row_counts"][bi] - row_used_count(problem, state, bi)
    ca_need = problem["col_counts"][aj] - col_used_count(problem, state, aj)
    cb_need = problem["col_counts"][bj] - col_used_count(problem, state, bj)

    score_a = ra_need + ca_need
    score_b = rb_need + cb_need

    if score_a >= score_b:
        return [(USED, UNUSED), (UNUSED, USED)]
    return [(UNUSED, USED), (USED, UNUSED)]


def hole_branch_order(problem, state, h):
    W = problem["W"]
    i, j = divmod(h, W)
    row_need = problem["row_counts"][i] - row_used_count(problem, state, i)
    col_need = problem["col_counts"][j] - col_used_count(problem, state, j)

    if row_need > 0 and col_need > 0:
        return [USED, UNUSED]
    return [UNUSED, USED]


def build_matching_from_used(problem, state):
    H = problem["H"]
    W = problem["W"]
    neighbors = problem["neighbors"]

    used = [h for h, v in enumerate(state) if v == USED]
    if len(used) % 2 != 0:
        return None

    used_set = set(used)
    left = [h for h in used if ((h // W) + (h % W)) % 2 == 0]
    right = [h for h in used if ((h // W) + (h % W)) % 2 == 1]
    if len(left) != len(right):
        return None

    adj = {}
    for h in left:
        adj[h] = [n for n in neighbors[h] if n in used_set]

    if any(not adj[h] for h in left):
        return None

    matchL, matchR, matched = hopcroft_karp(left, right, adj)
    if matched != len(left):
        return None

    stitches = []
    for a in left:
        b = matchL[a]
        if b is None:
            return None
        ar, ac = divmod(a, W)
        br, bc = divmod(b, W)
        stitches.append([(ar, ac), (br, bc)])
    return stitches


def hopcroft_karp(left, right, adj):
    INF = 10**9
    matchL = {u: None for u in left}
    matchR = {v: None for v in right}
    dist = {}

    def bfs():
        q = deque()
        for u in left:
            if matchL[u] is None:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = INF
        found = False
        while q:
            u = q.popleft()
            for v in adj.get(u, []):
                mu = matchR[v]
                if mu is None:
                    found = True
                elif dist[mu] == INF:
                    dist[mu] = dist[u] + 1
                    q.append(mu)
        return found

    def dfs(u):
        for v in adj.get(u, []):
            mu = matchR[v]
            if mu is None or (dist.get(mu, INF) == dist[u] + 1 and dfs(mu)):
                matchL[u] = v
                matchR[v] = u
                return True
        dist[u] = INF
        return False

    matching = 0
    while bfs():
        for u in left:
            if matchL[u] is None and dfs(u):
                matching += 1
    return matchL, matchR, matching


def normalize_stitches(stitches):
    norm = []
    for a, b in stitches:
        a = tuple(a)
        b = tuple(b)
        if b < a:
            a, b = b, a
        norm.append([a, b])
    norm.sort()
    return norm


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 1], [0, 0, 0, 2, 1], [3, 0, 2, 2, 1], [3, 0, 2, 2, 2], [4, 4, 4, 4, 4]], 'row_stitch_counts': [2, 3, 3, 3, 3], 'col_stitch_counts': [4, 3, 2, 2, 3]}

from collections import deque

def solve(observation):
    region = observation["region"]
    row_clues = observation["row_stitch_counts"]
    col_clues = observation["col_stitch_counts"]
    n = len(region)

    if not (len(row_clues) == len(col_clues) == n and all(len(row) == n for row in region)):
        return "No Solution"

    class Engine:
        def __init__(self):
            self.n = n
            self.region = region
            self.row_clues = row_clues
            self.col_clues = col_clues

            self.boundaries = []
            self.stitch_keys = []
            self.stitch_id = {}

            self._build_model()

            self.S = len(self.stitch_keys)
            self.H = n * n
            self.B = len(self.boundaries)

            self.stitch_state = [0] * self.S      # -1 forbidden, 0 undecided, 1 chosen
            self.hole_state = [0] * self.H        # -1 unused, 0 free, 1 used
            self.hole_avail = [0] * self.H        # non-forbidden incident stitches
            self.boundary_pos = [len(c) for c in self.boundaries]
            self.boundary_chosen = [0] * self.B

            self.row_lb = [0] * n
            self.row_ub = [n] * n
            self.col_lb = [0] * n
            self.col_ub = [n] * n

            self.trail = []

            self._clear_pending()

            for h in range(self.H):
                self.hole_avail[h] = len(self.hole_incident[h])

            for r in range(n):
                self._schedule_row(r)
                self._schedule_col(r)
            for b in range(self.B):
                self._schedule_boundary(b)

            for h in range(self.H):
                if self.hole_avail[h] == 0:
                    if not self.set_hole(h, -1):
                        self.init_ok = False
                        return

            self.init_ok = self.propagate()

        def _clear_pending(self):
            self.q_holes = deque()
            self.q_rows = deque()
            self.q_cols = deque()
            self.q_boundaries = deque()
            self.p_holes = [False] * (self.H if hasattr(self, "H") else self.n * self.n)
            self.p_rows = [False] * self.n
            self.p_cols = [False] * self.n
            self.p_boundaries = [False] * (self.B if hasattr(self, "B") else 0)

        def _build_model(self):
            n = self.n

            def get_sid(key):
                sid = self.stitch_id.get(key)
                if sid is None:
                    sid = len(self.stitch_keys)
                    self.stitch_id[key] = sid
                    self.stitch_keys.append(key)
                return sid

            # Human-style abstraction:
            # For every region boundary between adjacent cells, there are one or two candidate stitches.
            # Horizontal cell-pair boundary -> horizontal stitch on its top endpoint, and maybe on its bottom endpoint.
            # Vertical cell-pair boundary -> vertical stitch on its left endpoint, and maybe on its right endpoint.
            for r in range(n):
                for c in range(n - 1):
                    if self.region[r][c] != self.region[r][c + 1]:
                        cands = [get_sid(("H", r, c))]
                        if r + 1 < n:
                            cands.append(get_sid(("H", r + 1, c)))
                        self.boundaries.append(cands)

            for r in range(n - 1):
                for c in range(n):
                    if self.region[r][c] != self.region[r + 1][c]:
                        cands = [get_sid(("V", r, c))]
                        if c + 1 < n:
                            cands.append(get_sid(("V", r, c + 1)))
                        self.boundaries.append(cands)

            s = len(self.stitch_keys)
            self.stitch_endpoints = [None] * s
            self.stitch_boundaries = [[] for _ in range(s)]
            self.hole_incident = [[] for _ in range(n * n)]

            for b, cands in enumerate(self.boundaries):
                for sid in cands:
                    self.stitch_boundaries[sid].append(b)

            for sid, key in enumerate(self.stitch_keys):
                kind, r, c = key
                if kind == "H":
                    h1 = r * n + c
                    h2 = r * n + (c + 1)
                else:
                    h1 = r * n + c
                    h2 = (r + 1) * n + c
                self.stitch_endpoints[sid] = (h1, h2)
                self.hole_incident[h1].append(sid)
                self.hole_incident[h2].append(sid)

        def _save(self, arr, idx, val):
            if arr[idx] != val:
                self.trail.append((arr, idx, arr[idx]))
                arr[idx] = val

        def _schedule_hole(self, h):
            if not self.p_holes[h]:
                self.p_holes[h] = True
                self.q_holes.append(h)

        def _schedule_row(self, r):
            if not self.p_rows[r]:
                self.p_rows[r] = True
                self.q_rows.append(r)

        def _schedule_col(self, c):
            if not self.p_cols[c]:
                self.p_cols[c] = True
                self.q_cols.append(c)

        def _schedule_boundary(self, b):
            if not self.p_boundaries[b]:
                self.p_boundaries[b] = True
                self.q_boundaries.append(b)

        def checkpoint(self):
            return len(self.trail)

        def restore(self, cp):
            while len(self.trail) > cp:
                arr, idx, old = self.trail.pop()
                arr[idx] = old
            self._clear_pending()

        def set_hole(self, h, val):
            cur = self.hole_state[h]
            if cur == val:
                return True
            if cur == -val:
                return False

            self._save(self.hole_state, h, val)
            r, c = divmod(h, self.n)

            if val == 1:
                self._save(self.row_lb, r, self.row_lb[r] + 1)
                self._save(self.col_lb, c, self.col_lb[c] + 1)
                self._schedule_row(r)
                self._schedule_col(c)
                self._schedule_hole(h)

                if self.hole_avail[h] == 0:
                    return False
                if self.hole_avail[h] == 1:
                    for sid in self.hole_incident[h]:
                        if self.stitch_state[sid] != -1:
                            return self.assign_stitch(sid, 1)
                return True

            self._save(self.row_ub, r, self.row_ub[r] - 1)
            self._save(self.col_ub, c, self.col_ub[c] - 1)
            self._schedule_row(r)
            self._schedule_col(c)

            for sid in self.hole_incident[h]:
                st = self.stitch_state[sid]
                if st == 1:
                    return False
                if st == 0 and not self.assign_stitch(sid, -1):
                    return False
            return True

        def assign_stitch(self, sid, val):
            cur = self.stitch_state[sid]
            if cur == val:
                return True
            if cur == -val:
                return False

            self._save(self.stitch_state, sid, val)

            if val == -1:
                for b in self.stitch_boundaries[sid]:
                    self._save(self.boundary_pos, b, self.boundary_pos[b] - 1)
                    self._schedule_boundary(b)

                h1, h2 = self.stitch_endpoints[sid]
                for h in (h1, h2):
                    self._save(self.hole_avail, h, self.hole_avail[h] - 1)
                    self._schedule_hole(h)
                return True

            for b in self.stitch_boundaries[sid]:
                self._save(self.boundary_chosen, b, self.boundary_chosen[b] + 1)
                self._schedule_boundary(b)

            h1, h2 = self.stitch_endpoints[sid]
            if not self.set_hole(h1, 1):
                return False
            if not self.set_hole(h2, 1):
                return False

            for h in (h1, h2):
                for other in self.hole_incident[h]:
                    if other != sid and self.stitch_state[other] == 0:
                        if not self.assign_stitch(other, -1):
                            return False
            return True

        def _process_hole(self, h):
            st = self.hole_state[h]
            avail = self.hole_avail[h]

            if st == 1:
                if avail == 0:
                    return False
                if avail == 1:
                    for sid in self.hole_incident[h]:
                        if self.stitch_state[sid] != -1:
                            return self.assign_stitch(sid, 1)
                return True

            if st == 0 and avail == 0:
                return self.set_hole(h, -1)

            return True

        def _process_boundary(self, b):
            chosen = self.boundary_chosen[b]
            pos = self.boundary_pos[b]
            cands = self.boundaries[b]

            if chosen > 1 or pos == 0:
                return False

            if chosen == 1:
                for sid in cands:
                    if self.stitch_state[sid] == 0:
                        if not self.assign_stitch(sid, -1):
                            return False
                return True

            if pos == 1:
                for sid in cands:
                    if self.stitch_state[sid] != -1:
                        return self.assign_stitch(sid, 1)

            return True

        def _process_row(self, r):
            clue = self.row_clues[r]
            lb = self.row_lb[r]
            ub = self.row_ub[r]

            if lb > clue or ub < clue:
                return False

            if lb == clue:
                for c in range(self.n):
                    h = r * self.n + c
                    if self.hole_state[h] == 0:
                        if not self.set_hole(h, -1):
                            return False

            elif ub == clue:
                for c in range(self.n):
                    h = r * self.n + c
                    if self.hole_state[h] == 0:
                        if not self.set_hole(h, 1):
                            return False

            return True

        def _process_col(self, c):
            clue = self.col_clues[c]
            lb = self.col_lb[c]
            ub = self.col_ub[c]

            if lb > clue or ub < clue:
                return False

            if lb == clue:
                for r in range(self.n):
                    h = r * self.n + c
                    if self.hole_state[h] == 0:
                        if not self.set_hole(h, -1):
                            return False

            elif ub == clue:
                for r in range(self.n):
                    h = r * self.n + c
                    if self.hole_state[h] == 0:
                        if not self.set_hole(h, 1):
                            return False

            return True

        def propagate(self):
            while self.q_holes or self.q_rows or self.q_cols or self.q_boundaries:
                while self.q_holes:
                    h = self.q_holes.popleft()
                    self.p_holes[h] = False
                    if not self._process_hole(h):
                        return False

                while self.q_boundaries:
                    b = self.q_boundaries.popleft()
                    self.p_boundaries[b] = False
                    if not self._process_boundary(b):
                        return False

                while self.q_rows:
                    r = self.q_rows.popleft()
                    self.p_rows[r] = False
                    if not self._process_row(r):
                        return False

                while self.q_cols:
                    c = self.q_cols.popleft()
                    self.p_cols[c] = False
                    if not self._process_col(c):
                        return False
            return True

        def solved(self):
            for b in range(self.B):
                if self.boundary_chosen[b] != 1:
                    return False
            for i in range(self.n):
                if self.row_lb[i] != self.row_clues[i] or self.row_ub[i] != self.row_clues[i]:
                    return False
                if self.col_lb[i] != self.col_clues[i] or self.col_ub[i] != self.col_clues[i]:
                    return False
            return True

        def pick_branch(self):
            best = None

            # Prefer unresolved boundary constraints first.
            for b, cands in enumerate(self.boundaries):
                if self.boundary_chosen[b] != 0:
                    continue
                rem = [sid for sid in cands if self.stitch_state[sid] != -1]
                if len(rem) <= 1:
                    continue

                score = []
                for sid in rem:
                    h1, h2 = self.stitch_endpoints[sid]
                    involvement = len(self.stitch_boundaries[sid])
                    tight = self.hole_avail[h1] + self.hole_avail[h2]
                    score.append((-involvement, tight, sid))
                score.sort()
                ordered = [sid for _, _, sid in score]

                cand_score = (len(rem), score[0][0], score[0][1])
                if best is None or cand_score < best[0]:
                    best = (cand_score, ("boundary", ordered))
            if best is not None:
                return best[1]

            # Next, forced-used holes with multiple remaining possibilities.
            for h in range(self.H):
                if self.hole_state[h] != 1:
                    continue
                rem = [sid for sid in self.hole_incident[h] if self.stitch_state[sid] != -1]
                if len(rem) <= 1:
                    continue
                scored = []
                for sid in rem:
                    h1, h2 = self.stitch_endpoints[sid]
                    involvement = len(self.stitch_boundaries[sid])
                    tight = self.hole_avail[h1] + self.hole_avail[h2]
                    scored.append((-involvement, tight, sid))
                scored.sort()
                return ("hole", [sid for _, _, sid in scored])

            # Last resort: branch on a still-undecided stitch.
            undecided = [sid for sid in range(self.S) if self.stitch_state[sid] == 0]
            if undecided:
                undecided.sort(key=lambda sid: (-len(self.stitch_boundaries[sid]), sum(self.hole_avail[h] for h in self.stitch_endpoints[sid])))
                return ("stitch", undecided[0])

            return None

        def extract_answer(self):
            ans = []
            for sid, st in enumerate(self.stitch_state):
                if st == 1:
                    h1, h2 = self.stitch_endpoints[sid]
                    p1 = (h1 // self.n, h1 % self.n)
                    p2 = (h2 // self.n, h2 % self.n)
                    ans.append([p1, p2])
            ans.sort()
            return ans

        def search(self):
            if not self.propagate():
                return None
            if self.solved():
                return self.extract_answer()

            branch = self.pick_branch()
            if branch is None:
                return None

            kind = branch[0]

            if kind in ("boundary", "hole"):
                for sid in branch[1]:
                    cp = self.checkpoint()
                    if self.assign_stitch(sid, 1):
                        out = self.search()
                        if out is not None:
                            return out
                    self.restore(cp)
                return None

            sid = branch[1]
            cp = self.checkpoint()
            if self.assign_stitch(sid, 1):
                out = self.search()
                if out is not None:
                    return out
            self.restore(cp)

            cp = self.checkpoint()
            if self.assign_stitch(sid, -1):
                out = self.search()
                if out is not None:
                    return out
            self.restore(cp)
            return None

    engine = Engine()
    if not engine.init_ok:
        return "No Solution"

    ans = engine.search()
    return "No Solution" if ans is None else str(ans)


