import sys

sys.setrecursionlimit(10000)


def solve(observation):
    data = observation["data"]
    n = len(data) - 1
    if n < 0 or any(len(row) != n + 1 for row in data):
        return "No Solution"

    m = n * n
    vcount = (n + 1) * (n + 1)

    def dot_id(r, c):
        return r * (n + 1) + c

    cell_pos = []
    endpoints = []
    for r in range(n):
        for c in range(n):
            cell_pos.append((r, c))
            # 0 => '/', 1 => '\'
            endpoints.append((
                (dot_id(r, c + 1), dot_id(r + 1, c)),
                (dot_id(r, c), dot_id(r + 1, c + 1)),
            ))

    clue_targets = []
    clue_incidents = []
    cell_to_clues = [[] for _ in range(m)]

    for i in range(n + 1):
        for j in range(n + 1):
            k = data[i][j]
            if k is None:
                continue
            inc = []
            if i > 0 and j > 0:
                cid = (i - 1) * n + (j - 1)
                inc.append((cid, 1))
            if i > 0 and j < n:
                cid = (i - 1) * n + j
                inc.append((cid, 0))
            if i < n and j > 0:
                cid = i * n + (j - 1)
                inc.append((cid, 0))
            if i < n and j < n:
                cid = i * n + j
                inc.append((cid, 1))
            q = len(clue_targets)
            clue_targets.append(k)
            clue_incidents.append(inc)
            for cid, o in inc:
                cell_to_clues[cid].append((q, o))

    singleton_to_orient = {1: 0, 2: 1}

    def propagate(domains):
        # Repeatedly apply:
        # 1) clue saturation/bounds
        # 2) anti-loop pruning via DSU on assigned edges
        while True:
            changed = False

            # Clue-based propagation
            for q, k in enumerate(clue_targets):
                inc = clue_incidents[q]
                yes = 0
                unk = 0
                pending = []
                for cid, want in inc:
                    d = domains[cid]
                    want_bit = 1 << want
                    if d == want_bit:
                        yes += 1
                    elif d & want_bit:
                        unk += 1
                        pending.append((cid, want))
                if yes > k or yes + unk < k:
                    return None
                if unk:
                    if yes == k:
                        for cid, want in pending:
                            new_d = domains[cid] & (2 if want == 0 else 1)
                            if new_d == 0:
                                return None
                            if new_d != domains[cid]:
                                domains[cid] = new_d
                                changed = True
                    elif yes + unk == k:
                        for cid, want in pending:
                            new_d = domains[cid] & (1 << want)
                            if new_d == 0:
                                return None
                            if new_d != domains[cid]:
                                domains[cid] = new_d
                                changed = True

            # DSU for current fixed edges; reject existing cycle
            parent = list(range(vcount))
            rank = [0] * vcount

            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x

            def union(a, b):
                ra = find(a)
                rb = find(b)
                if ra == rb:
                    return False
                if rank[ra] < rank[rb]:
                    parent[ra] = rb
                elif rank[ra] > rank[rb]:
                    parent[rb] = ra
                else:
                    parent[rb] = ra
                    rank[ra] += 1
                return True

            for cid, d in enumerate(domains):
                if d in singleton_to_orient:
                    o = singleton_to_orient[d]
                    a, b = endpoints[cid][o]
                    if not union(a, b):
                        return None

            # If one orientation would instantly create a loop, remove it
            for cid, d in enumerate(domains):
                if d == 3:
                    nd = d
                    a0, b0 = endpoints[cid][0]
                    if find(a0) == find(b0):
                        nd &= ~1
                    a1, b1 = endpoints[cid][1]
                    if find(a1) == find(b1):
                        nd &= ~2
                    if nd == 0:
                        return None
                    if nd != d:
                        domains[cid] = nd
                        changed = True

            if not changed:
                return domains

    def choose_cell(domains):
        # Human-like heuristic:
        # branch at a cell involved in the tightest clue neighborhoods.
        clue_yes = [0] * len(clue_targets)
        clue_unk = [0] * len(clue_targets)
        for q, inc in enumerate(clue_incidents):
            y = 0
            u = 0
            for cid, want in inc:
                d = domains[cid]
                bit = 1 << want
                if d == bit:
                    y += 1
                elif d & bit:
                    u += 1
            clue_yes[q] = y
            clue_unk[q] = u

        best_cid = -1
        best_score = -1
        best_pref = (0, 0)

        for cid, d in enumerate(domains):
            if d != 3:
                continue
            score = 0
            pref0 = 0
            pref1 = 0
            for q, want_for_this_cell in cell_to_clues[cid]:
                u = clue_unk[q]
                if u <= 0:
                    continue
                k = clue_targets[q]
                y = clue_yes[q]
                # Smaller u => tighter
                score += 12 - min(u, 10)
                rem = k - y
                if rem * 2 > u:
                    desired = 1
                elif rem * 2 < u:
                    desired = -1
                else:
                    desired = 0
                if want_for_this_cell == 0:
                    pref0 += desired
                    pref1 -= desired
                else:
                    pref1 += desired
                    pref0 -= desired

            if score > best_score:
                best_score = score
                best_cid = cid
                best_pref = (pref0, pref1)

        if best_cid == -1:
            for cid, d in enumerate(domains):
                if d == 3:
                    best_cid = cid
                    best_pref = (0, 0)
                    break

        if best_cid == -1:
            return None, None

        if best_pref[1] > best_pref[0]:
            return best_cid, (2, 1)
        return best_cid, (1, 2)

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        complete = True
        for d in domains:
            if d == 3:
                complete = False
                break
        if complete:
            return domains

        cid, order = choose_cell(domains)
        if cid is None:
            return None

        for bit in order:
            if domains[cid] & bit:
                new_domains = domains.copy()
                new_domains[cid] = bit
                res = dfs(new_domains)
                if res is not None:
                    return res
        return None

    domains = [3] * m
    sol = dfs(domains)
    if sol is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        base = r * n
        for c in range(n):
            row.append('/' if sol[base + c] == 1 else '\\')
        out.append(row)
    return out


