from collections import deque


WHITE = 1
BLACK = 2
BOTH = 3


def transpose_grid(grid):
    return [list(row) for row in zip(*grid)]


def build_problem(data):
    r_count = len(data)
    c_count = len(data[0]) if r_count else 0
    n = r_count * c_count

    clues = []
    var_to_clues = [[] for _ in range(n)]

    def vid(r, c):
        return r * c_count + c

    for r in range(r_count):
        for c in range(c_count):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(r_count, r + 2)):
                for cc in range(max(0, c - 1), min(c_count, c + 2)):
                    cells.append(vid(rr, cc))
            k = len(clues)
            clues.append((tuple(cells), val))
            for v in cells:
                var_to_clues[v].append(k)

    clue_pairs = []
    m = len(clues)
    for i in range(m):
        for j in range(i + 1, m):
            clue_pairs.append((i, j))

    return {
        'rows': r_count,
        'cols': c_count,
        'nvars': n,
        'clues': clues,
        'var_to_clues': var_to_clues,
        'clue_pairs': clue_pairs,
    }


def set_value(domains, v, is_black):
    want = BLACK if is_black else WHITE
    cur = domains[v]
    if cur == want:
        return False
    if not (cur & want):
        return None
    domains[v] = want
    return True


def process_constraint(domains, clue):
    cells, target = clue
    forced_black = 0
    max_black = 0
    undecided = []

    for v in cells:
        d = domains[v]
        if d == BLACK:
            forced_black += 1
            max_black += 1
        elif d == BOTH:
            max_black += 1
            undecided.append(v)

    if target < forced_black or target > max_black:
        return None

    changed_vars = []
    if target == forced_black:
        for v in undecided:
            res = set_value(domains, v, False)
            if res is None:
                return None
            if res:
                changed_vars.append(v)
    elif target == max_black:
        for v in undecided:
            res = set_value(domains, v, True)
            if res is None:
                return None
            if res:
                changed_vars.append(v)

    return changed_vars


def pairwise_deductions(domains, problem):
    clues = problem['clues']
    changed = False

    unresolved_sets = []
    residuals = []

    for cells, target in clues:
        forced_black = 0
        unresolved = set()
        for v in cells:
            d = domains[v]
            if d == BLACK:
                forced_black += 1
            elif d == BOTH:
                unresolved.add(v)
        residual = target - forced_black
        if residual < 0 or residual > len(unresolved):
            return None
        unresolved_sets.append(unresolved)
        residuals.append(residual)

    for i, j in problem['clue_pairs']:
        ua = unresolved_sets[i]
        ub = unresolved_sets[j]
        ra = residuals[i]
        rb = residuals[j]

        inter = ua & ub
        a_only = ua - ub
        b_only = ub - ua

        la = len(a_only)
        lb = len(b_only)
        li = len(inter)

        d = ra - rb

        low_a = max(0, d)
        high_a = min(la, d + lb)
        if low_a > high_a:
            return None

        low_b = max(0, -d)
        high_b = min(lb, la - d)
        if low_b > high_b:
            return None

        # Force A-only if its exact sum collapses to 0 or full.
        if low_a == high_a:
            if low_a == 0:
                for v in a_only:
                    res = set_value(domains, v, False)
                    if res is None:
                        return None
                    changed = changed or res
            elif low_a == la:
                for v in a_only:
                    res = set_value(domains, v, True)
                    if res is None:
                        return None
                    changed = changed or res

        # Force B-only if its exact sum collapses to 0 or full.
        if low_b == high_b:
            if low_b == 0:
                for v in b_only:
                    res = set_value(domains, v, False)
                    if res is None:
                        return None
                    changed = changed or res
            elif low_b == lb:
                for v in b_only:
                    res = set_value(domains, v, True)
                    if res is None:
                        return None
                    changed = changed or res

        # Bound the overlap count; if overlap collapses to 0 or full, force it.
        low_i = max(0, ra - high_a, rb - high_b)
        high_i = min(li, ra - low_a, rb - low_b)
        if low_i > high_i:
            return None
        if low_i == high_i:
            if low_i == 0:
                for v in inter:
                    res = set_value(domains, v, False)
                    if res is None:
                        return None
                    changed = changed or res
            elif low_i == li:
                for v in inter:
                    res = set_value(domains, v, True)
                    if res is None:
                        return None
                    changed = changed or res

    return changed


def propagate(domains, problem):
    clues = problem['clues']
    var_to_clues = problem['var_to_clues']

    while True:
        changed_any = False
        q = deque(range(len(clues)))
        in_q = [True] * len(clues)

        while q:
            k = q.popleft()
            in_q[k] = False
            changed_vars = process_constraint(domains, clues[k])
            if changed_vars is None:
                return False
            if changed_vars:
                changed_any = True
                for v in changed_vars:
                    for kk in var_to_clues[v]:
                        if not in_q[kk]:
                            in_q[kk] = True
                            q.append(kk)

        pair_changed = pairwise_deductions(domains, problem)
        if pair_changed is None:
            return False
        if pair_changed:
            changed_any = True

        if not changed_any:
            return True


def domains_to_grid(domains, rows, cols):
    out = []
    idx = 0
    for _ in range(rows):
        row = []
        for _ in range(cols):
            row.append(domains[idx])
            idx += 1
        out.append(row)
    return out


def answer_from_domains(domains, rows, cols):
    out = []
    idx = 0
    for _ in range(rows):
        row = []
        for _ in range(cols):
            row.append('B' if domains[idx] == BLACK else None)
            idx += 1
        out.append(row)
    return out


def verify_answer(answer, data):
    rows = len(data)
    cols = len(data[0]) if rows else 0

    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is None:
                continue
            s = 0
            for rr in range(max(0, r - 1), min(rows, r + 2)):
                for cc in range(max(0, c - 1), min(cols, c + 2)):
                    if answer[rr][cc] == 'B':
                        s += 1
            if s != val:
                return False
    return True


def solve_by_row_dp(data, domains_grid, max_width=12):
    rows = len(data)
    cols = len(data[0]) if rows else 0
    transposed = False

    if cols > rows:
        data = transpose_grid(data)
        domains_grid = transpose_grid(domains_grid)
        rows, cols = cols, rows
        transposed = True

    if cols > max_width:
        return None

    all_masks = list(range(1 << cols))
    bitcount = [m.bit_count() for m in all_masks]

    col_masks = []
    for c in range(cols):
        mask = 0
        for cc in range(max(0, c - 1), min(cols, c + 2)):
            mask |= 1 << cc
        col_masks.append(mask)

    contrib = [[0] * cols for _ in all_masks]
    for m in all_masks:
        row = contrib[m]
        for c in range(cols):
            row[c] = bitcount[m & col_masks[c]]

    row_clues = []
    for r in range(rows):
        rc = []
        for c in range(cols):
            if data[r][c] is not None:
                rc.append((c, data[r][c]))
        row_clues.append(rc)

    allowed = []
    for r in range(rows):
        force_black = 0
        force_white = 0
        for c in range(cols):
            d = domains_grid[r][c]
            if d == BLACK:
                force_black |= 1 << c
            elif d == WHITE:
                force_white |= 1 << c
        masks = [m for m in all_masks if (m & force_black) == force_black and (m & force_white) == 0]
        if not masks:
            return None
        allowed.append(masks)

    def row_ok(r, prev_mask, cur_mask, next_mask):
        for c, target in row_clues[r]:
            s = contrib[prev_mask][c] + contrib[cur_mask][c] + contrib[next_mask][c]
            if s != target:
                return False
        return True

    if rows == 0:
        return []

    if rows == 1:
        for m0 in allowed[0]:
            if row_ok(0, 0, m0, 0):
                out = [[('B' if (m0 >> c) & 1 else None) for c in range(cols)]]
                if transposed:
                    out = transpose_grid(out)
                return out
        return None

    layers = []

    init = {}
    for m0 in allowed[0]:
        for m1 in allowed[1]:
            if row_ok(0, 0, m0, m1):
                init[(m0, m1)] = None

    if not init:
        return None

    layers.append(init)
    states = init

    for r in range(1, rows - 1):
        next_masks = allowed[r + 1]
        new_states = {}
        for a, b in states:
            for c in next_masks:
                if row_ok(r, a, b, c) and (b, c) not in new_states:
                    new_states[(b, c)] = (a, b)
        if not new_states:
            return None
        layers.append(new_states)
        states = new_states

    final_state = None
    for a, b in states:
        if row_ok(rows - 1, a, b, 0):
            final_state = (a, b)
            break

    if final_state is None:
        return None

    row_masks = [0] * rows
    state = final_state
    for layer in range(rows - 2, -1, -1):
        a, b = state
        row_masks[layer] = a
        row_masks[layer + 1] = b
        prev_state = layers[layer][state]
        if prev_state is None:
            break
        state = prev_state

    out = []
    for r in range(rows):
        out.append([('B' if (row_masks[r] >> c) & 1 else None) for c in range(cols)])

    if transposed:
        out = transpose_grid(out)
    return out


def choose_branch_variable(domains, problem):
    clues = problem['clues']
    var_to_clues = problem['var_to_clues']

    residual = [0] * len(clues)
    undec_count = [0] * len(clues)

    for k, (cells, target) in enumerate(clues):
        black = 0
        undec = 0
        for v in cells:
            if domains[v] == BLACK:
                black += 1
            elif domains[v] == BOTH:
                undec += 1
        residual[k] = target - black
        undec_count[k] = undec

    best_v = None
    best_key = None
    best_bias = 0.5

    for v, d in enumerate(domains):
        if d != BOTH:
            continue
        incidents = var_to_clues[v]
        total_span = 0
        tight = 0
        ratio_sum = 0.0
        useful = 0
        for k in incidents:
            u = undec_count[k]
            if u <= 0:
                continue
            r = residual[k]
            total_span += u
            tight += min(r, u - r)
            ratio_sum += r / u
            useful += 1
        key = (total_span, tight, -len(incidents))
        if best_key is None or key < best_key:
            best_key = key
            best_v = v
            best_bias = (ratio_sum / useful) if useful else 0.5

    return best_v, best_bias >= 0.5


def dfs_search(domains, problem):
    domains = domains[:]
    if not propagate(domains, problem):
        return None
    if all(d != BOTH for d in domains):
        return domains

    v, prefer_black = choose_branch_variable(domains, problem)
    if v is None:
        return domains

    order = (True, False) if prefer_black else (False, True)
    for is_black in order:
        new_domains = domains[:]
        res = set_value(new_domains, v, is_black)
        if res is None:
            continue
        ans = dfs_search(new_domains, problem)
        if ans is not None:
            return ans
    return None


def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return repr([])

    problem = build_problem(data)
    domains = [BOTH] * problem['nvars']

    # Human-like propagation first:
    # - direct saturation of each clue
    # - overlap/subset style pair deductions
    if not propagate(domains, problem):
        return "No Solution"

    rows, cols = problem['rows'], problem['cols']
    if all(d != BOTH for d in domains):
        answer = answer_from_domains(domains, rows, cols)
        return repr(answer) if verify_answer(answer, data) else "No Solution"

    domains_grid = domains_to_grid(domains, rows, cols)

    # Structured exact completion using row-pattern DP when the narrow dimension is small.
    answer = solve_by_row_dp(data, domains_grid, max_width=12)
    if answer is not None:
        return repr(answer) if verify_answer(answer, data) else "No Solution"

    # Fallback: constrained search with the same deduction engine.
    solved_domains = dfs_search(domains, problem)
    if solved_domains is None:
        return "No Solution"

    answer = answer_from_domains(solved_domains, rows, cols)
    return repr(answer) if verify_answer(answer, data) else "No Solution"


