# Consecutive-dot Latin square solver.
# Strategy:
# 1) Bitmask domains per cell.
# 2) Strong propagation:
#    - arc consistency on all orthogonal neighbor relations
#    - all-different reasoning on every row/column:
#      * direct singleton elimination
#      * hidden singles
#      * Hall subset checks on cell subsets (naked subsets)
#      * dual Hall checks on digit subsets (hidden subsets)
# 3) MRV branching only after propagation is exhausted.

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    fullmask = (1 << n) - 1
    size = n * n

    popcount = [0] * (1 << n)
    for i in range(1, 1 << n):
        popcount[i] = popcount[i >> 1] + (i & 1)

    # Consecutive relation support tables.
    consec_of_value = [0] * n
    nonconsec_of_value = [0] * n
    for v in range(n):
        m = 0
        if v > 0:
            m |= 1 << (v - 1)
        if v + 1 < n:
            m |= 1 << (v + 1)
        consec_of_value[v] = m
        nonconsec_of_value[v] = fullmask & ~m

    support_pos = [0] * (1 << n)
    support_neg = [0] * (1 << n)
    for s in range(1, 1 << n):
        lsb = s & -s
        i = lsb.bit_length() - 1
        prev = s ^ lsb
        support_pos[s] = support_pos[prev] | consec_of_value[i]
        support_neg[s] = support_neg[prev] | nonconsec_of_value[i]

    def rc_to_idx(r, c):
        return r * n + c

    # Parse dotted adjacencies from midpoint coordinates.
    dotted = set()
    for a, b in adjacent:
        if abs(a - round(a)) < 1e-9:
            r = int(round(a))
            c = int(round(b - 0.5))
            if 0 <= r < n and 0 <= c < n - 1:
                i = rc_to_idx(r, c)
                j = rc_to_idx(r, c + 1)
                if i > j:
                    i, j = j, i
                dotted.add((i, j))
        else:
            r = int(round(a - 0.5))
            c = int(round(b))
            if 0 <= r < n - 1 and 0 <= c < n:
                i = rc_to_idx(r, c)
                j = rc_to_idx(r + 1, c)
                if i > j:
                    i, j = j, i
                dotted.add((i, j))

    edges = []
    cell_edges = [[] for _ in range(size)]
    degree = [0] * size
    for r in range(n):
        for c in range(n):
            i = rc_to_idx(r, c)
            if c + 1 < n:
                j = rc_to_idx(r, c + 1)
                key = (i, j) if i < j else (j, i)
                is_dot = key in dotted
                edges.append((i, j, is_dot))
                cell_edges[i].append((j, is_dot))
                cell_edges[j].append((i, is_dot))
                degree[i] += 1
                degree[j] += 1
            if r + 1 < n:
                j = rc_to_idx(r + 1, c)
                key = (i, j) if i < j else (j, i)
                is_dot = key in dotted
                edges.append((i, j, is_dot))
                cell_edges[i].append((j, is_dot))
                cell_edges[j].append((i, is_dot))
                degree[i] += 1
                degree[j] += 1

    row_units = [[rc_to_idx(r, c) for c in range(n)] for r in range(n)]
    col_units = [[rc_to_idx(r, c) for r in range(n)] for c in range(n)]
    units = row_units + col_units
    row_of = [i // n for i in range(size)]
    col_of = [i % n for i in range(size)]

    domains0 = [fullmask] * size
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains0[rc_to_idx(r, c)] = 1 << (v - 1)

    def is_single(m):
        return m and (m & (m - 1)) == 0

    def enforce_unit(dom, unit):
        changed_any = False
        k = len(unit)

        while True:
            progress = False

            # Basic singleton logic and duplicate-single check.
            fixed = 0
            for idx in unit:
                m = dom[idx]
                if m == 0:
                    return None
                if is_single(m):
                    if fixed & m:
                        return None
                    fixed |= m

            if fixed:
                for idx in unit:
                    m = dom[idx]
                    if not is_single(m):
                        nm = m & ~fixed
                        if nm == 0:
                            return None
                        if nm != m:
                            dom[idx] = nm
                            progress = True
                if progress:
                    changed_any = True
                    continue

            # Hidden singles.
            masks = [dom[idx] for idx in unit]
            for d in range(n):
                bit = 1 << d
                count = 0
                last_pos = -1
                for pos, m in enumerate(masks):
                    if m & bit:
                        count += 1
                        last_pos = pos
                if count == 0:
                    return None
                if count == 1:
                    idx = unit[last_pos]
                    if dom[idx] != bit:
                        dom[idx] = bit
                        progress = True
                        break
            if progress:
                changed_any = True
                continue

            # Hall subsets on cell subsets.
            masks = [dom[idx] for idx in unit]
            unions = [0] * (1 << k)
            for s in range(1, 1 << k):
                lsb = s & -s
                i = lsb.bit_length() - 1
                unions[s] = unions[s ^ lsb] | masks[i]
                cell_count = popcount[s]
                digit_count = popcount[unions[s]]

                if digit_count < cell_count:
                    return None

                if 1 < cell_count < k and digit_count == cell_count:
                    locked = unions[s]
                    for j, idx in enumerate(unit):
                        if ((s >> j) & 1) == 0:
                            nm = dom[idx] & ~locked
                            if nm == 0:
                                return None
                            if nm != dom[idx]:
                                dom[idx] = nm
                                progress = True
                                break
                    if progress:
                        break
            if progress:
                changed_any = True
                continue

            # Dual Hall subsets on digit subsets.
            masks = [dom[idx] for idx in unit]
            for t in range(1, fullmask + 1):
                digit_count = popcount[t]
                if digit_count <= 1 or digit_count >= k:
                    continue
                cells_mask = 0
                for j, m in enumerate(masks):
                    if m & t:
                        cells_mask |= 1 << j
                cell_count = popcount[cells_mask]

                if cell_count < digit_count:
                    return None

                if cell_count == digit_count:
                    for j, idx in enumerate(unit):
                        if (cells_mask >> j) & 1:
                            nm = dom[idx] & t
                            if nm == 0:
                                return None
                            if nm != dom[idx]:
                                dom[idx] = nm
                                progress = True
                                break
                    if progress:
                        break
            if progress:
                changed_any = True
                continue

            break

        return changed_any

    def propagate(dom):
        dom = dom[:]
        while True:
            changed = False

            # Arc consistency on all orthogonal relations.
            for i, j, is_dot in edges:
                sup = support_pos if is_dot else support_neg
                a = dom[i]
                b = dom[j]
                while True:
                    na = a & sup[b]
                    if na == 0:
                        return None
                    nb = b & sup[na]
                    if nb == 0:
                        return None
                    if na == a and nb == b:
                        break
                    a, b = na, nb
                if a != dom[i]:
                    dom[i] = a
                    changed = True
                if b != dom[j]:
                    dom[j] = b
                    changed = True

            # All-different propagation on rows and columns.
            for unit in units:
                res = enforce_unit(dom, unit)
                if res is None:
                    return None
                if res:
                    changed = True

            if not changed:
                break

        return dom

    def solved(dom):
        return all(is_single(m) for m in dom)

    def value_order(idx, dom):
        vals = []
        m = dom[idx]
        while m:
            bit = m & -m
            m ^= bit

            # Higher score = less constraining on adjacency supports.
            score = 0
            for nb, is_dot in cell_edges[idx]:
                allowed = support_pos[bit] if is_dot else support_neg[bit]
                score += popcount[dom[nb] & allowed]

            # Mild tie-breakers from row/column availability.
            r = row_of[idx]
            c = col_of[idx]
            row_avail = sum(1 for p in row_units[r] if dom[p] & bit)
            col_avail = sum(1 for p in col_units[c] if dom[p] & bit)

            vals.append((-(score), row_avail + col_avail, bit))
        vals.sort()
        return [bit for _, _, bit in vals]

    failed = set()

    def dfs(dom):
        dom = propagate(dom)
        if dom is None:
            return None

        key = tuple(dom)
        if key in failed:
            return None

        if solved(dom):
            return dom

        # MRV + degree tie-break.
        best = -1
        best_size = n + 1
        best_degree = -1
        for idx, m in enumerate(dom):
            s = popcount[m]
            if 1 < s < best_size or (s == best_size and degree[idx] > best_degree):
                best = idx
                best_size = s
                best_degree = degree[idx]

        for bit in value_order(best, dom):
            nxt = dom[:]
            nxt[best] = bit
            ans = dfs(nxt)
            if ans is not None:
                return ans

        failed.add(key)
        return None

    result = dfs(domains0)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            bit = result[rc_to_idx(r, c)]
            row.append(bit.bit_length())
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

