from collections import deque
from itertools import combinations


class Context:
    __slots__ = (
        "sub_r", "sub_c", "N", "ALL",
        "rows", "cols", "boxes", "units",
        "peers", "row_of", "col_of", "box_of"
    )

    def __init__(self, sub_r, sub_c):
        self.sub_r = sub_r
        self.sub_c = sub_c
        self.N = sub_r * sub_c
        self.ALL = (1 << self.N) - 1

        N = self.N
        self.rows = [[r * N + c for c in range(N)] for r in range(N)]
        self.cols = [[r * N + c for r in range(N)] for c in range(N)]

        self.boxes = []
        for br in range(0, N, sub_r):
            for bc in range(0, N, sub_c):
                box = []
                for r in range(br, br + sub_r):
                    for c in range(bc, bc + sub_c):
                        box.append(r * N + c)
                self.boxes.append(box)

        self.units = self.rows + self.cols + self.boxes

        self.row_of = [0] * (N * N)
        self.col_of = [0] * (N * N)
        self.box_of = [0] * (N * N)

        boxes_per_row = N // sub_c
        for r in range(N):
            for c in range(N):
                idx = r * N + c
                self.row_of[idx] = r
                self.col_of[idx] = c
                self.box_of[idx] = (r // sub_r) * boxes_per_row + (c // sub_c)

        self.peers = []
        for idx in range(N * N):
            r = self.row_of[idx]
            c = self.col_of[idx]
            b = self.box_of[idx]
            s = set(self.rows[r])
            s.update(self.cols[c])
            s.update(self.boxes[b])
            s.discard(idx)
            self.peers.append(tuple(s))


def parse_unit(unit):
    s = str(unit).strip().lower()
    if "x" in s:
        a, b = s.split("x", 1)
        return int(a), int(b)
    v = int(s)
    return v, v


def iter_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit
        mask ^= bit


def eliminate_mask(cands, idx, remove_mask, queue):
    old = cands[idx]
    new = old & ~remove_mask
    if new == old:
        return False
    if new == 0:
        return None
    cands[idx] = new
    if new & (new - 1) == 0:
        queue.append(idx)
    return True


def propagate_singles(cands, ctx, queue):
    changed = False
    while queue:
        idx = queue.popleft()
        val = cands[idx]
        if val == 0:
            return None
        if val & (val - 1):
            continue
        for p in ctx.peers[idx]:
            if cands[p] & val:
                res = eliminate_mask(cands, p, val, queue)
                if res is None:
                    return None
                if res:
                    changed = True
    return changed


def apply_hidden_singles(cands, ctx, queue):
    N = ctx.N
    changed = False

    for unit in ctx.units:
        counts = [0] * N
        places = [-1] * N

        for idx in unit:
            m = cands[idx]
            if m == 0:
                return None
            mm = m
            while mm:
                bit = mm & -mm
                d = bit.bit_length() - 1
                counts[d] += 1
                places[d] = idx
                mm ^= bit

        for d, cnt in enumerate(counts):
            if cnt == 0:
                return None
            if cnt == 1:
                idx = places[d]
                bit = 1 << d
                if cands[idx] != bit:
                    cands[idx] = bit
                    queue.append(idx)
                    changed = True

    return changed


def apply_locked_candidates(cands, ctx, queue):
    N = ctx.N
    changed = False

    # Pointing: box -> row/col
    for box_index, box in enumerate(ctx.boxes):
        row_masks = [0] * N
        col_masks = [0] * N
        counts = [0] * N

        for idx in box:
            r = ctx.row_of[idx]
            c = ctx.col_of[idx]
            mm = cands[idx]
            while mm:
                bit = mm & -mm
                d = bit.bit_length() - 1
                counts[d] += 1
                row_masks[d] |= 1 << r
                col_masks[d] |= 1 << c
                mm ^= bit

        for d in range(N):
            if counts[d] <= 1:
                continue
            bit = 1 << d

            rm = row_masks[d]
            if rm and (rm & (rm - 1)) == 0:
                r = rm.bit_length() - 1
                for idx in ctx.rows[r]:
                    if ctx.box_of[idx] != box_index and (cands[idx] & bit):
                        res = eliminate_mask(cands, idx, bit, queue)
                        if res is None:
                            return None
                        if res:
                            changed = True

            cm = col_masks[d]
            if cm and (cm & (cm - 1)) == 0:
                c = cm.bit_length() - 1
                for idx in ctx.cols[c]:
                    if ctx.box_of[idx] != box_index and (cands[idx] & bit):
                        res = eliminate_mask(cands, idx, bit, queue)
                        if res is None:
                            return None
                        if res:
                            changed = True

    # Claiming: row/col -> box
    for r, row in enumerate(ctx.rows):
        box_masks = [0] * N
        counts = [0] * N

        for idx in row:
            b = ctx.box_of[idx]
            mm = cands[idx]
            while mm:
                bit = mm & -mm
                d = bit.bit_length() - 1
                counts[d] += 1
                box_masks[d] |= 1 << b
                mm ^= bit

        for d in range(N):
            if counts[d] <= 1:
                continue
            bm = box_masks[d]
            if bm and (bm & (bm - 1)) == 0:
                box_index = bm.bit_length() - 1
                bit = 1 << d
                for idx in ctx.boxes[box_index]:
                    if ctx.row_of[idx] != r and (cands[idx] & bit):
                        res = eliminate_mask(cands, idx, bit, queue)
                        if res is None:
                            return None
                        if res:
                            changed = True

    for c, col in enumerate(ctx.cols):
        box_masks = [0] * N
        counts = [0] * N

        for idx in col:
            b = ctx.box_of[idx]
            mm = cands[idx]
            while mm:
                bit = mm & -mm
                d = bit.bit_length() - 1
                counts[d] += 1
                box_masks[d] |= 1 << b
                mm ^= bit

        for d in range(N):
            if counts[d] <= 1:
                continue
            bm = box_masks[d]
            if bm and (bm & (bm - 1)) == 0:
                box_index = bm.bit_length() - 1
                bit = 1 << d
                for idx in ctx.boxes[box_index]:
                    if ctx.col_of[idx] != c and (cands[idx] & bit):
                        res = eliminate_mask(cands, idx, bit, queue)
                        if res is None:
                            return None
                        if res:
                            changed = True

    return changed


def apply_naked_subsets(cands, ctx, queue, max_subset=3):
    changed = False

    for unit in ctx.units:
        unsolved = [idx for idx in unit if cands[idx].bit_count() > 1]
        if len(unsolved) < 2:
            continue

        limit = min(max_subset, len(unsolved) - 1)
        for k in range(2, limit + 1):
            eligible = [idx for idx in unsolved if 2 <= cands[idx].bit_count() <= k]
            if len(eligible) < k:
                continue

            for combo in combinations(eligible, k):
                union = 0
                for idx in combo:
                    union |= cands[idx]
                if union.bit_count() != k:
                    continue

                combo_set = set(combo)
                for idx in unit:
                    if idx not in combo_set and (cands[idx] & union):
                        res = eliminate_mask(cands, idx, union, queue)
                        if res is None:
                            return None
                        if res:
                            changed = True

    return changed


def deduce(cands, ctx, initial_queue=None):
    queue = deque(initial_queue or [])

    if not queue:
        for idx, m in enumerate(cands):
            if m == 0:
                return False
            if m & (m - 1) == 0:
                queue.append(idx)

    subset_limit = 3 if ctx.N <= 12 else 4

    while True:
        progress = False

        res = propagate_singles(cands, ctx, queue)
        if res is None:
            return False
        progress |= res

        res = apply_hidden_singles(cands, ctx, queue)
        if res is None:
            return False
        progress |= res

        res = propagate_singles(cands, ctx, queue)
        if res is None:
            return False
        progress |= res

        res = apply_locked_candidates(cands, ctx, queue)
        if res is None:
            return False
        progress |= res

        res = propagate_singles(cands, ctx, queue)
        if res is None:
            return False
        progress |= res

        res = apply_naked_subsets(cands, ctx, queue, max_subset=subset_limit)
        if res is None:
            return False
        progress |= res

        res = propagate_singles(cands, ctx, queue)
        if res is None:
            return False
        progress |= res

        if not progress and not queue:
            break

    return True


def choose_branch_cell(cands, ctx):
    best_idx = -1
    best_count = ctx.N + 1
    best_score = -1

    for idx, m in enumerate(cands):
        bc = m.bit_count()
        if bc <= 1:
            continue
        peer_pressure = 0
        for p in ctx.peers[idx]:
            if cands[p].bit_count() > 1:
                peer_pressure += 1
        if bc < best_count or (bc == best_count and peer_pressure > best_score):
            best_count = bc
            best_idx = idx
            best_score = peer_pressure
            if bc == 2 and peer_pressure == len(ctx.peers[idx]):
                break

    return best_idx


def ordered_values(cands, ctx, idx):
    options = []
    for bit in iter_bits(cands[idx]):
        impact = 0
        for p in ctx.peers[idx]:
            if cands[p] & bit:
                impact += 1
        options.append((-impact, bit))
    options.sort()
    return [bit for _, bit in options]


def search(cands, ctx):
    idx = choose_branch_cell(cands, ctx)
    if idx == -1:
        return cands

    for bit in ordered_values(cands, ctx, idx):
        nxt = cands.copy()
        nxt[idx] = bit
        if deduce(nxt, ctx, [idx]):
            solved = search(nxt, ctx)
            if solved is not None:
                return solved
    return None


def solve(observation):
    try:
        data = observation["data"]
        sub_r, sub_c = parse_unit(observation["unit"])
        ctx = Context(sub_r, sub_c)
        N = ctx.N

        if not isinstance(data, list) or len(data) != N:
            return "No Solution"
        for row in data:
            if not isinstance(row, list) or len(row) != N:
                return "No Solution"

        cands = [ctx.ALL] * (N * N)
        givens = []

        for r in range(N):
            for c in range(N):
                v = data[r][c]
                if v is None:
                    continue
                if not isinstance(v, int) or not (1 <= v <= N):
                    return "No Solution"
                idx = r * N + c
                cands[idx] = 1 << (v - 1)
                givens.append(idx)

        if not deduce(cands, ctx, givens):
            return "No Solution"

        solved = search(cands, ctx)
        if solved is None:
            return "No Solution"

        grid = []
        for r in range(N):
            row = []
            for c in range(N):
                bit = solved[r * N + c]
                if bit == 0 or (bit & (bit - 1)):
                    return "No Solution"
                row.append(bit.bit_length())
            grid.append(row)

        return repr(grid)
    except Exception:
        return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [7, 7, 6, 7], 'col_sum': [7, 7, 6, 7]}

from functools import lru_cache


def solve(observation):
    row_sum = tuple(int(x) for x in observation['row_sum'])
    col_sum = tuple(int(x) for x in observation['col_sum'])

    n = len(row_sum)
    m = len(col_sum)

    # Default weights are the visible 1..N labels on the puzzle frame.
    row_weights = tuple(observation.get('row_weight', tuple(range(1, n + 1))))
    col_weights = tuple(observation.get('col_weight', tuple(range(1, m + 1))))

    if len(row_weights) != n or len(col_weights) != m:
        return "No Solution"

    row_all_bits = (1 << m) - 1
    col_all_bits = (1 << n) - 1

    def make_mask_generator(weights):
        weights = tuple(int(w) for w in weights)
        prefix = [0]
        for w in weights:
            prefix.append(prefix[-1] + w)

        @lru_cache(None)
        def rec(k, target):
            if target < 0 or target > prefix[k]:
                return ()
            if k == 0:
                return (0,) if target == 0 else ()
            without_k = rec(k - 1, target)
            with_k = rec(k - 1, target - weights[k - 1])
            if not with_k:
                return without_k
            bit = 1 << (k - 1)
            return without_k + tuple(mask | bit for mask in with_k)

        def generate(target):
            return rec(len(weights), int(target))

        return generate

    row_mask_gen = make_mask_generator(col_weights)
    col_mask_gen = make_mask_generator(row_weights)

    row_domains = []
    for tgt in row_sum:
        dom = row_mask_gen(tgt)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for tgt in col_sum:
        dom = col_mask_gen(tgt)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    def summarize_domain(domain, all_bits):
        it = iter(domain)
        first = next(it)
        union = first
        inter = first
        for mask in it:
            union |= mask
            inter &= mask
        return union, inter

    def filter_domain(domain, must1, must0):
        if must1 & must0:
            return None
        if must1 == 0 and must0 == 0:
            return domain
        filtered = tuple(mask for mask in domain if (mask & must1) == must1 and (mask & must0) == 0)
        return filtered if filtered else None

    def propagate(row_domains, col_domains):
        row_domains = tuple(tuple(d) for d in row_domains)
        col_domains = tuple(tuple(d) for d in col_domains)

        while True:
            changed = False

            row_union = [0] * n
            row_inter = [0] * n
            for i, dom in enumerate(row_domains):
                u, inter = summarize_domain(dom, row_all_bits)
                row_union[i] = u
                row_inter[i] = inter

            col_union = [0] * m
            col_inter = [0] * m
            for j, dom in enumerate(col_domains):
                u, inter = summarize_domain(dom, col_all_bits)
                col_union[j] = u
                col_inter[j] = inter

            row_must1 = [0] * n
            row_must0 = [0] * n
            col_must1 = [0] * m
            col_must0 = [0] * m

            # Cross-propagation:
            # a cell is black iff both its row and column domains still support black there.
            # likewise for white; if only one state survives, force it into both domains.
            for i in range(n):
                rbit = 1 << i
                for j in range(m):
                    cbit = 1 << j

                    row_can_1 = bool(row_union[i] & cbit)
                    row_can_0 = not bool(row_inter[i] & cbit)

                    col_can_1 = bool(col_union[j] & rbit)
                    col_can_0 = not bool(col_inter[j] & rbit)

                    can_1 = row_can_1 and col_can_1
                    can_0 = row_can_0 and col_can_0

                    if not can_1 and not can_0:
                        return None

                    if not can_0:
                        row_must1[i] |= cbit
                        col_must1[j] |= rbit
                    elif not can_1:
                        row_must0[i] |= cbit
                        col_must0[j] |= rbit

            new_rows = []
            for i, dom in enumerate(row_domains):
                filtered = filter_domain(dom, row_must1[i], row_must0[i])
                if filtered is None:
                    return None
                if filtered != dom:
                    changed = True
                new_rows.append(filtered)

            new_cols = []
            for j, dom in enumerate(col_domains):
                filtered = filter_domain(dom, col_must1[j], col_must0[j])
                if filtered is None:
                    return None
                if filtered != dom:
                    changed = True
                new_cols.append(filtered)

            row_domains = tuple(new_rows)
            col_domains = tuple(new_cols)

            if not changed:
                return row_domains, col_domains

    def choose_branch_var(row_domains, col_domains):
        best = None

        for i, dom in enumerate(row_domains):
            if len(dom) > 1:
                union, inter = summarize_domain(dom, row_all_bits)
                undecided = (union ^ inter).bit_count()
                key = (len(dom), -undecided, 0, i)
                if best is None or key < best[0]:
                    best = (key, 'row', i)

        for j, dom in enumerate(col_domains):
            if len(dom) > 1:
                union, inter = summarize_domain(dom, col_all_bits)
                undecided = (union ^ inter).bit_count()
                key = (len(dom), -undecided, 1, j)
                if best is None or key < best[0]:
                    best = (key, 'col', j)

        return None if best is None else (best[1], best[2])

    def ordered_masks_for_row(i, domain, col_domains):
        bit = 1 << i
        support1 = [0] * m
        support0 = [0] * m
        for j, dom in enumerate(col_domains):
            c1 = 0
            for mask in dom:
                if mask & bit:
                    c1 += 1
            support1[j] = c1
            support0[j] = len(dom) - c1

        return tuple(sorted(
            domain,
            key=lambda mask: sum(support1[j] if ((mask >> j) & 1) else support0[j] for j in range(m))
        ))

    def ordered_masks_for_col(j, domain, row_domains):
        bit = 1 << j
        support1 = [0] * n
        support0 = [0] * n
        for i, dom in enumerate(row_domains):
            c1 = 0
            for mask in dom:
                if mask & bit:
                    c1 += 1
            support1[i] = c1
            support0[i] = len(dom) - c1

        return tuple(sorted(
            domain,
            key=lambda mask: sum(support1[i] if ((mask >> i) & 1) else support0[i] for i in range(n))
        ))

    @lru_cache(None)
    def dfs(row_domains, col_domains):
        state = propagate(row_domains, col_domains)
        if state is None:
            return None

        row_domains, col_domains = state

        if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
            return row_domains

        choice = choose_branch_var(row_domains, col_domains)
        if choice is None:
            return None

        kind, idx = choice

        if kind == 'row':
            domain = row_domains[idx]
            for mask in ordered_masks_for_row(idx, domain, col_domains):
                new_rows = list(row_domains)
                new_rows[idx] = (mask,)
                result = dfs(tuple(new_rows), col_domains)
                if result is not None:
                    return result
        else:
            domain = col_domains[idx]
            for mask in ordered_masks_for_col(idx, domain, row_domains):
                new_cols = list(col_domains)
                new_cols[idx] = (mask,)
                result = dfs(row_domains, tuple(new_cols))
                if result is not None:
                    return result

        return None

    solution_rows = dfs(tuple(row_domains), tuple(col_domains))
    if solution_rows is None:
        return "No Solution"

    answer = []
    for i in range(n):
        mask = solution_rows[i][0]
        row = []
        for j in range(m):
            row.append('B' if (mask >> j) & 1 else None)
        answer.append(row)

    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

