# Takuzu / Binairo solver:
# - equal number of B/W in every row and column
# - no three consecutive same color
# - all rows distinct, all columns distinct
# - respects givens
#
# The solver is generalized and combines:
# 1) human-style local deductions (adjacency and balance rules),
# 2) line-domain propagation using all valid row/column patterns,
# 3) uniqueness pruning for completed lines,
# 4) small, highly constrained backtracking over line patterns.

_PATTERN_CACHE = {}


def valid_patterns(length):
    if length in _PATTERN_CACHE:
        return _PATTERN_CACHE[length]

    if length % 2 != 0:
        _PATTERN_CACHE[length] = []
        return []

    half = length // 2
    out = []

    def dfs(pos, prev2, prev1, blacks, mask):
        if pos == length:
            if blacks == half:
                out.append(mask)
            return

        remaining = length - pos - 1
        for bit in (0, 1):  # 0 = W, 1 = B
            if prev2 is not None and prev1 is not None and prev2 == prev1 == bit:
                continue

            new_blacks = blacks + bit
            new_whites = (pos + 1) - new_blacks

            if new_blacks > half or new_whites > half:
                continue
            if new_blacks + remaining < half:
                continue
            if new_whites + remaining < half:
                continue

            dfs(pos + 1, prev1, bit, new_blacks, mask | (bit << pos))

    dfs(0, None, None, 0, 0)
    _PATTERN_CACHE[length] = out
    return out


def pattern_matches_line(pattern, line):
    for i, v in enumerate(line):
        if v != -1 and ((pattern >> i) & 1) != v:
            return False
    return True


def check_line_partial(line):
    n = len(line)
    half = n // 2
    b = sum(1 for x in line if x == 1)
    w = sum(1 for x in line if x == 0)
    u = n - b - w

    if b > half or w > half:
        return False
    if b + u < half or w + u < half:
        return False

    for i in range(n - 2):
        a, b2, c = line[i], line[i + 1], line[i + 2]
        if a != -1 and a == b2 == c:
            return False
    return True


def deduce_line_simple(line):
    n = len(line)
    half = n // 2
    updates = []

    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a != -1 and a == b and c == -1:
            updates.append((i + 2, 1 - a))
        if b != -1 and b == c and a == -1:
            updates.append((i, 1 - b))
        if a != -1 and a == c and b == -1:
            updates.append((i + 1, 1 - a))

    count_b = sum(1 for x in line if x == 1)
    count_w = sum(1 for x in line if x == 0)

    if count_b == half:
        for i, v in enumerate(line):
            if v == -1:
                updates.append((i, 0))
    if count_w == half:
        for i, v in enumerate(line):
            if v == -1:
                updates.append((i, 1))

    return updates


def enforce_uniqueness(domains):
    fixed = {}
    for i, dom in enumerate(domains):
        if len(dom) == 1:
            p = dom[0]
            if p in fixed:
                return False
            fixed[p] = i

    if not fixed:
        return 0

    fixed_patterns = set(fixed)
    changed = 0
    for i, dom in enumerate(domains):
        if len(dom) > 1:
            new_dom = [p for p in dom if p not in fixed_patterns]
            if not new_dom:
                return False
            if len(new_dom) != len(dom):
                domains[i] = new_dom
                changed = 1
    return changed


def assign_cell(grid, r, c, value):
    cur = grid[r][c]
    if cur == -1:
        grid[r][c] = value
        return 1
    if cur == value:
        return 0
    return -1


def is_complete_and_valid(grid):
    if not grid or not grid[0]:
        return False

    r_count = len(grid)
    c_count = len(grid[0])

    for row in grid:
        if -1 in row or not check_line_partial(row):
            return False

    cols = []
    for c in range(c_count):
        col = [grid[r][c] for r in range(r_count)]
        if -1 in col or not check_line_partial(col):
            return False
        cols.append(tuple(col))

    rows = [tuple(row) for row in grid]
    if len(set(rows)) != len(rows):
        return False
    if len(set(cols)) != len(cols):
        return False
    return True


def propagate(grid, row_domains, col_domains):
    r_count = len(grid)
    c_count = len(grid[0])
    row_fullmask = (1 << c_count) - 1
    col_fullmask = (1 << r_count) - 1

    while True:
        changed = 0

        # Check current partial lines.
        for r in range(r_count):
            if not check_line_partial(grid[r]):
                return False
        for c in range(c_count):
            col = [grid[r][c] for r in range(r_count)]
            if not check_line_partial(col):
                return False

        # Filter row domains against current grid.
        for r in range(r_count):
            dom = row_domains[r]
            line = grid[r]
            new_dom = [p for p in dom if pattern_matches_line(p, line)]
            if not new_dom:
                return False
            if len(new_dom) != len(dom):
                row_domains[r] = new_dom
                changed = 1

        # Filter column domains against current grid.
        for c in range(c_count):
            dom = col_domains[c]
            line = [grid[r][c] for r in range(r_count)]
            new_dom = [p for p in dom if pattern_matches_line(p, line)]
            if not new_dom:
                return False
            if len(new_dom) != len(dom):
                col_domains[c] = new_dom
                changed = 1

        # Uniqueness pruning: once a line pattern is fixed, no other line can equal it.
        uniq = enforce_uniqueness(row_domains)
        if uniq is False:
            return False
        changed |= uniq

        uniq = enforce_uniqueness(col_domains)
        if uniq is False:
            return False
        changed |= uniq

        # Domain summaries and consensus.
        row_allow = [[0] * c_count for _ in range(r_count)]
        col_allow = [[0] * r_count for _ in range(c_count)]

        for r in range(r_count):
            dom = row_domains[r]
            union1 = 0
            union0 = 0
            common1 = row_fullmask
            common0 = row_fullmask
            for p in dom:
                union1 |= p
                inv = (~p) & row_fullmask
                union0 |= inv
                common1 &= p
                common0 &= inv

            for c in range(c_count):
                allow = 0
                if (union0 >> c) & 1:
                    allow |= 1  # W
                if (union1 >> c) & 1:
                    allow |= 2  # B
                row_allow[r][c] = allow

                if (common1 >> c) & 1:
                    res = assign_cell(grid, r, c, 1)
                    if res < 0:
                        return False
                    changed |= res
                elif (common0 >> c) & 1:
                    res = assign_cell(grid, r, c, 0)
                    if res < 0:
                        return False
                    changed |= res

        for c in range(c_count):
            dom = col_domains[c]
            union1 = 0
            union0 = 0
            common1 = col_fullmask
            common0 = col_fullmask
            for p in dom:
                union1 |= p
                inv = (~p) & col_fullmask
                union0 |= inv
                common1 &= p
                common0 &= inv

            for r in range(r_count):
                allow = 0
                if (union0 >> r) & 1:
                    allow |= 1
                if (union1 >> r) & 1:
                    allow |= 2
                col_allow[c][r] = allow

                if (common1 >> r) & 1:
                    res = assign_cell(grid, r, c, 1)
                    if res < 0:
                        return False
                    changed |= res
                elif (common0 >> r) & 1:
                    res = assign_cell(grid, r, c, 0)
                    if res < 0:
                        return False
                    changed |= res

        # Intersect row/column cell possibilities.
        cell_allowed = [[0] * c_count for _ in range(r_count)]
        for r in range(r_count):
            for c in range(c_count):
                allow = row_allow[r][c] & col_allow[c][r]
                if allow == 0:
                    return False
                cell_allowed[r][c] = allow

                if allow == 1:
                    res = assign_cell(grid, r, c, 0)
                    if res < 0:
                        return False
                    changed |= res
                elif allow == 2:
                    res = assign_cell(grid, r, c, 1)
                    if res < 0:
                        return False
                    changed |= res

        # Filter domains again using cross-line cell allowances.
        for r in range(r_count):
            dom = row_domains[r]
            new_dom = []
            for p in dom:
                ok = True
                for c in range(c_count):
                    bitmask = 2 if ((p >> c) & 1) else 1
                    if not (cell_allowed[r][c] & bitmask):
                        ok = False
                        break
                if ok:
                    new_dom.append(p)
            if not new_dom:
                return False
            if len(new_dom) != len(dom):
                row_domains[r] = new_dom
                changed = 1

        for c in range(c_count):
            dom = col_domains[c]
            new_dom = []
            for p in dom:
                ok = True
                for r in range(r_count):
                    bitmask = 2 if ((p >> r) & 1) else 1
                    if not (cell_allowed[r][c] & bitmask):
                        ok = False
                        break
                if ok:
                    new_dom.append(p)
            if not new_dom:
                return False
            if len(new_dom) != len(dom):
                col_domains[c] = new_dom
                changed = 1

        # Human-style local deductions on current partial rows.
        for r in range(r_count):
            for c, value in deduce_line_simple(grid[r]):
                res = assign_cell(grid, r, c, value)
                if res < 0:
                    return False
                changed |= res

        # Human-style local deductions on current partial columns.
        for c in range(c_count):
            col = [grid[r][c] for r in range(r_count)]
            for r, value in deduce_line_simple(col):
                res = assign_cell(grid, r, c, value)
                if res < 0:
                    return False
                changed |= res

        if not changed:
            break

    return True


def choose_branch(grid, row_domains, col_domains):
    r_count = len(grid)
    c_count = len(grid[0])
    best = None

    for r in range(r_count):
        size = len(row_domains[r])
        if size > 1:
            unknowns = sum(1 for v in grid[r] if v == -1)
            score = (size, -unknowns, 0, r)
            if best is None or score < best[0]:
                best = (score, "row", r, row_domains[r][:])

    for c in range(c_count):
        size = len(col_domains[c])
        if size > 1:
            unknowns = sum(1 for r in range(r_count) if grid[r][c] == -1)
            score = (size, -unknowns, 1, c)
            if best is None or score < best[0]:
                best = (score, "col", c, col_domains[c][:])

    if best is None:
        return None
    return best[1], best[2], best[3]


def search(grid, row_domains, col_domains):
    if not propagate(grid, row_domains, col_domains):
        return None

    if is_complete_and_valid(grid):
        return grid

    branch = choose_branch(grid, row_domains, col_domains)
    if branch is None:
        return None

    kind, idx, domain = branch
    r_count = len(grid)
    c_count = len(grid[0])

    for pattern in domain:
        new_grid = [row[:] for row in grid]
        new_row_domains = [dom[:] for dom in row_domains]
        new_col_domains = [dom[:] for dom in col_domains]

        if kind == "row":
            new_row_domains[idx] = [pattern]
            ok = True
            for c in range(c_count):
                value = (pattern >> c) & 1
                res = assign_cell(new_grid, idx, c, value)
                if res < 0:
                    ok = False
                    break
            if not ok:
                continue
        else:
            new_col_domains[idx] = [pattern]
            ok = True
            for r in range(r_count):
                value = (pattern >> r) & 1
                res = assign_cell(new_grid, r, idx, value)
                if res < 0:
                    ok = False
                    break
            if not ok:
                continue

        ans = search(new_grid, new_row_domains, new_col_domains)
        if ans is not None:
            return ans

    return None


def solve(observation):
    data = observation.get('data')
    if not isinstance(data, list) or not data or not all(isinstance(row, list) for row in data):
        return "No Solution"

    r_count = len(data)
    c_count = len(data[0])

    if any(len(row) != c_count for row in data):
        return "No Solution"
    if r_count % 2 != 0 or c_count % 2 != 0:
        return "No Solution"

    grid = []
    for r in range(r_count):
        row = []
        for c in range(c_count):
            v = data[r][c]
            if v is None:
                row.append(-1)
            elif v == 'B':
                row.append(1)
            elif v == 'W':
                row.append(0)
            else:
                return "No Solution"
        grid.append(row)

    row_patterns = valid_patterns(c_count)
    col_patterns = valid_patterns(r_count)
    if not row_patterns or not col_patterns:
        return "No Solution"

    row_domains = []
    for r in range(r_count):
        dom = [p for p in row_patterns if pattern_matches_line(p, grid[r])]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(c_count):
        col = [grid[r][c] for r in range(r_count)]
        dom = [p for p in col_patterns if pattern_matches_line(p, col)]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    result = search(grid, row_domains, col_domains)
    if result is None:
        return "No Solution"

    return [['B' if v == 1 else 'W' for v in row] for row in result]


