from functools import lru_cache


@lru_cache(maxsize=None)
def generate_line_masks(length, clues):
    clues = tuple(clues)
    if not clues:
        return (0,)

    suffix_sums = [0] * (len(clues) + 1)
    for i in range(len(clues) - 1, -1, -1):
        suffix_sums[i] = suffix_sums[i + 1] + clues[i]

    @lru_cache(maxsize=None)
    def place(i, pos):
        if i == len(clues):
            return (0,)

        run = clues[i]
        # Minimal space needed from clue i onward = remaining blacks + mandatory separators.
        rem = suffix_sums[i] + (len(clues) - i - 1)
        max_start = length - rem

        out = []
        for start in range(pos, max_start + 1):
            block = ((1 << run) - 1) << start
            next_pos = start + run + 1
            for tail in place(i + 1, next_pos):
                out.append(block | tail)
        return tuple(out)

    return place(0, 0)


def bit_count(x):
    return x.bit_count()


def propagate(row_poss, col_poss, row_black, row_white):
    n_rows = len(row_poss)
    n_cols = len(col_poss)
    full_row = (1 << n_cols) - 1
    full_col = (1 << n_rows) - 1

    while True:
        changed = False

        # Row-side filtering and overlap deductions.
        for r in range(n_rows):
            if row_black[r] & row_white[r]:
                return None

            poss = row_poss[r]
            filtered = tuple(
                m for m in poss
                if (m & row_black[r]) == row_black[r] and (m & row_white[r]) == 0
            )
            if not filtered:
                return None
            if len(filtered) != len(poss):
                row_poss[r] = filtered
                poss = filtered
                changed = True
            else:
                poss = filtered

            inter = full_row
            union = 0
            for m in poss:
                inter &= m
                union |= m

            new_black = row_black[r] | inter
            new_white = row_white[r] | (full_row ^ union)
            if new_black & new_white:
                return None
            if new_black != row_black[r] or new_white != row_white[r]:
                row_black[r] = new_black
                row_white[r] = new_white
                changed = True

        # Column-side filtering and overlap deductions, pushed back into row cell knowledge.
        for c in range(n_cols):
            must_black = 0
            must_white = 0
            col_bit = 1 << c
            for r in range(n_rows):
                row_bit = 1 << r
                if row_black[r] & col_bit:
                    must_black |= row_bit
                if row_white[r] & col_bit:
                    must_white |= row_bit

            poss = col_poss[c]
            filtered = tuple(
                m for m in poss
                if (m & must_black) == must_black and (m & must_white) == 0
            )
            if not filtered:
                return None
            if len(filtered) != len(poss):
                col_poss[c] = filtered
                poss = filtered
                changed = True
            else:
                poss = filtered

            inter = full_col
            union = 0
            for m in poss:
                inter &= m
                union |= m

            # Push forced column cells back into row knowledge.
            for r in range(n_rows):
                row_bit = 1 << r
                cell_bit = 1 << c
                if inter & row_bit:
                    if row_white[r] & cell_bit:
                        return None
                    if not (row_black[r] & cell_bit):
                        row_black[r] |= cell_bit
                        changed = True
                if not (union & row_bit):
                    if row_black[r] & cell_bit:
                        return None
                    if not (row_white[r] & cell_bit):
                        row_white[r] |= cell_bit
                        changed = True

        if not changed:
            break

    return row_poss, col_poss, row_black, row_white


def choose_branch(row_poss, col_poss, row_black, row_white):
    n_rows = len(row_poss)
    n_cols = len(col_poss)

    best = None

    # Prefer the line with the fewest remaining patterns; tiebreak by more known cells.
    for r in range(n_rows):
        k = len(row_poss[r])
        if k > 1:
            known = bit_count(row_black[r] | row_white[r])
            score = (k, -known, 0, r)
            if best is None or score < best:
                best = score

    for c in range(n_cols):
        k = len(col_poss[c])
        if k > 1:
            known = 0
            bit = 1 << c
            for r in range(n_rows):
                if (row_black[r] | row_white[r]) & bit:
                    known += 1
            score = (k, -known, 1, c)
            if best is None or score < best:
                best = score

    return best


def build_solution_grid(row_black, n_cols):
    grid = []
    for r_mask in row_black:
        row = []
        for c in range(n_cols):
            row.append('B' if (r_mask >> c) & 1 else None)
        grid.append(row)
    return grid


def search(row_poss, col_poss, row_black, row_white):
    state = propagate(row_poss, col_poss, row_black, row_white)
    if state is None:
        return None

    row_poss, col_poss, row_black, row_white = state
    choice = choose_branch(row_poss, col_poss, row_black, row_white)
    if choice is None:
        # Fully determined.
        return build_solution_grid(row_black, len(col_poss))

    _, _, line_type, idx = choice
    n_rows = len(row_poss)
    n_cols = len(col_poss)
    full_row = (1 << n_cols) - 1

    if line_type == 0:
        # Branch on a row pattern.
        for mask in row_poss[idx]:
            new_row_poss = list(row_poss)
            new_col_poss = list(col_poss)
            new_row_black = row_black[:]
            new_row_white = row_white[:]

            new_row_black[idx] = mask
            new_row_white[idx] = full_row ^ mask
            new_row_poss[idx] = (mask,)

            ans = search(new_row_poss, new_col_poss, new_row_black, new_row_white)
            if ans is not None:
                return ans
    else:
        # Branch on a column pattern; translate it into row cell assignments.
        c = idx
        cell_bit = 1 << c
        for mask in col_poss[c]:
            new_row_poss = list(row_poss)
            new_col_poss = list(col_poss)
            new_row_black = row_black[:]
            new_row_white = row_white[:]

            ok = True
            for r in range(n_rows):
                if (mask >> r) & 1:
                    if new_row_white[r] & cell_bit:
                        ok = False
                        break
                    new_row_black[r] |= cell_bit
                else:
                    if new_row_black[r] & cell_bit:
                        ok = False
                        break
                    new_row_white[r] |= cell_bit
            if not ok:
                continue

            new_col_poss[c] = (mask,)
            ans = search(new_row_poss, new_col_poss, new_row_black, new_row_white)
            if ans is not None:
                return ans

    return None


def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    n_rows = len(row_clues)
    n_cols = len(col_clues)

    row_poss = [generate_line_masks(n_cols, tuple(clues)) for clues in row_clues]
    col_poss = [generate_line_masks(n_rows, tuple(clues)) for clues in col_clues]

    row_black = [0] * n_rows
    row_white = [0] * n_rows

    result = search(row_poss, col_poss, row_black, row_white)
    if result is None:
        return "No Solution"
    return repr(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

