from functools import lru_cache
from collections import deque


@lru_cache(maxsize=None)
def line_patterns(length, clues):
    clues = tuple(clues)
    if not clues:
        return (0,)

    out = []

    def rec(idx, pos, mask):
        if idx == len(clues):
            out.append(mask)
            return
        block = clues[idx]
        remaining = sum(clues[idx + 1:]) + max(0, len(clues) - idx - 1)
        max_start = length - block - remaining
        for start in range(pos, max_start + 1):
            new_mask = mask | (((1 << block) - 1) << start)
            next_pos = start + block if idx == len(clues) - 1 else start + block + 1
            rec(idx + 1, next_pos, new_mask)

    rec(0, 0, 0)
    return tuple(out)


def summarize(domain, full_mask):
    any_black = 0
    all_black = full_mask
    for p in domain:
        any_black |= p
        all_black &= p
    return any_black, all_black


class State:
    __slots__ = (
        "h", "w",
        "row_full", "col_full",
        "row_domains", "col_domains",
        "row_any_black", "row_all_black",
        "col_any_black", "col_all_black",
        "row_black", "row_white",
        "col_black", "col_white",
    )

    def __init__(self, row_domains, col_domains, h, w):
        self.h = h
        self.w = w
        self.row_full = (1 << w) - 1
        self.col_full = (1 << h) - 1

        self.row_domains = [list(d) for d in row_domains]
        self.col_domains = [list(d) for d in col_domains]

        self.row_any_black = [0] * h
        self.row_all_black = [0] * h
        self.col_any_black = [0] * w
        self.col_all_black = [0] * w

        for i in range(h):
            self.row_any_black[i], self.row_all_black[i] = summarize(self.row_domains[i], self.row_full)
        for j in range(w):
            self.col_any_black[j], self.col_all_black[j] = summarize(self.col_domains[j], self.col_full)

        self.row_black = [0] * h
        self.row_white = [0] * h
        self.col_black = [0] * w
        self.col_white = [0] * w

    def copy(self):
        s = State.__new__(State)
        s.h = self.h
        s.w = self.w
        s.row_full = self.row_full
        s.col_full = self.col_full

        s.row_domains = [d[:] for d in self.row_domains]
        s.col_domains = [d[:] for d in self.col_domains]

        s.row_any_black = self.row_any_black[:]
        s.row_all_black = self.row_all_black[:]
        s.col_any_black = self.col_any_black[:]
        s.col_all_black = self.col_all_black[:]

        s.row_black = self.row_black[:]
        s.row_white = self.row_white[:]
        s.col_black = self.col_black[:]
        s.col_white = self.col_white[:]
        return s


def assign_cell(state, r, c, value):
    row_bit = 1 << c
    col_bit = 1 << r

    if value:
        if (state.row_white[r] & row_bit) or (state.col_white[c] & col_bit):
            return -1
        if state.row_black[r] & row_bit:
            return 0
        state.row_black[r] |= row_bit
        state.col_black[c] |= col_bit
        return 1

    if (state.row_black[r] & row_bit) or (state.col_black[c] & col_bit):
        return -1
    if state.row_white[r] & row_bit:
        return 0
    state.row_white[r] |= row_bit
    state.col_white[c] |= col_bit
    return 1


def process_row(state, i, enqueue_col):
    req = state.row_black[i]
    forb = state.row_white[i]
    row_marker = 1 << i

    # Human-like cross-check:
    # - if a column can only be black here, require black
    # - if a column can never be black here, require white
    for c in range(state.w):
        bit = 1 << c
        if state.col_all_black[c] & row_marker:
            req |= bit
        elif not (state.col_any_black[c] & row_marker):
            forb |= bit

    if req & forb:
        return False

    dom = state.row_domains[i]
    new_dom = [p for p in dom if (p & req) == req and (p & forb) == 0]
    if not new_dom:
        return False

    if len(new_dom) != len(dom):
        state.row_domains[i] = new_dom
        any_black, all_black = summarize(new_dom, state.row_full)
        if any_black != state.row_any_black[i] or all_black != state.row_all_black[i]:
            state.row_any_black[i] = any_black
            state.row_all_black[i] = all_black
            for c in range(state.w):
                enqueue_col(c)
    else:
        any_black = state.row_any_black[i]
        all_black = state.row_all_black[i]

    unknown = state.row_full ^ (state.row_black[i] | state.row_white[i])

    to_black = all_black & unknown
    while to_black:
        bit = to_black & -to_black
        c = bit.bit_length() - 1
        if assign_cell(state, i, c, 1) < 0:
            return False
        enqueue_col(c)
        to_black ^= bit

    to_white = (state.row_full ^ any_black) & unknown
    while to_white:
        bit = to_white & -to_white
        c = bit.bit_length() - 1
        if assign_cell(state, i, c, 0) < 0:
            return False
        enqueue_col(c)
        to_white ^= bit

    return True


def process_col(state, j, enqueue_row):
    req = state.col_black[j]
    forb = state.col_white[j]
    col_marker = 1 << j

    # Symmetric cross-check with rows.
    for r in range(state.h):
        bit = 1 << r
        if state.row_all_black[r] & col_marker:
            req |= bit
        elif not (state.row_any_black[r] & col_marker):
            forb |= bit

    if req & forb:
        return False

    dom = state.col_domains[j]
    new_dom = [p for p in dom if (p & req) == req and (p & forb) == 0]
    if not new_dom:
        return False

    if len(new_dom) != len(dom):
        state.col_domains[j] = new_dom
        any_black, all_black = summarize(new_dom, state.col_full)
        if any_black != state.col_any_black[j] or all_black != state.col_all_black[j]:
            state.col_any_black[j] = any_black
            state.col_all_black[j] = all_black
            for r in range(state.h):
                enqueue_row(r)
    else:
        any_black = state.col_any_black[j]
        all_black = state.col_all_black[j]

    unknown = state.col_full ^ (state.col_black[j] | state.col_white[j])

    to_black = all_black & unknown
    while to_black:
        bit = to_black & -to_black
        r = bit.bit_length() - 1
        if assign_cell(state, r, j, 1) < 0:
            return False
        enqueue_row(r)
        to_black ^= bit

    to_white = (state.col_full ^ any_black) & unknown
    while to_white:
        bit = to_white & -to_white
        r = bit.bit_length() - 1
        if assign_cell(state, r, j, 0) < 0:
            return False
        enqueue_row(r)
        to_white ^= bit

    return True


def propagate(state, initial_queue=None):
    q = deque()
    row_in = [False] * state.h
    col_in = [False] * state.w

    def enqueue_row(r):
        if not row_in[r]:
            row_in[r] = True
            q.append(("r", r))

    def enqueue_col(c):
        if not col_in[c]:
            col_in[c] = True
            q.append(("c", c))

    if initial_queue is None:
        for r in range(state.h):
            enqueue_row(r)
        for c in range(state.w):
            enqueue_col(c)
    else:
        for kind, idx in initial_queue:
            if kind == "r":
                enqueue_row(idx)
            else:
                enqueue_col(idx)

    while q:
        kind, idx = q.popleft()
        if kind == "r":
            row_in[idx] = False
            if not process_row(state, idx, enqueue_col):
                return False
        else:
            col_in[idx] = False
            if not process_col(state, idx, enqueue_row):
                return False

    return True


def is_solved(state):
    return all((state.row_black[r] | state.row_white[r]) == state.row_full for r in range(state.h))


def choose_branch_line(state):
    best = None

    for r in range(state.h):
        d = len(state.row_domains[r])
        if d > 1:
            unknown_count = (state.row_full ^ (state.row_black[r] | state.row_white[r])).bit_count()
            key = (d, -unknown_count, 0, r)
            if best is None or key < best:
                best = key

    for c in range(state.w):
        d = len(state.col_domains[c])
        if d > 1:
            unknown_count = (state.col_full ^ (state.col_black[c] | state.col_white[c])).bit_count()
            key = (d, -unknown_count, 1, c)
            if best is None or key < best:
                best = key

    if best is None:
        return None

    _, _, kind_flag, idx = best
    return ("r" if kind_flag == 0 else "c", idx)


def ordered_patterns_for_row(state, r):
    # Prefer patterns aligning with current column possibilities.
    scored = []
    row_marker = 1 << r
    for p in state.row_domains[r]:
        score = 0
        for c in range(state.w):
            bit = 1 << c
            val = 1 if (p & bit) else 0
            col_any = 1 if (state.col_any_black[c] & row_marker) else 0
            col_all = 1 if (state.col_all_black[c] & row_marker) else 0
            if val == col_all:
                score += 2
            if val == 1 and col_any:
                score += 1
            if val == 0 and not col_all:
                score += 1
        scored.append((-score, p))
    scored.sort()
    return [p for _, p in scored]


def ordered_patterns_for_col(state, c):
    scored = []
    col_marker = 1 << c
    for p in state.col_domains[c]:
        score = 0
        for r in range(state.h):
            bit = 1 << r
            val = 1 if (p & bit) else 0
            row_any = 1 if (state.row_any_black[r] & col_marker) else 0
            row_all = 1 if (state.row_all_black[r] & col_marker) else 0
            if val == row_all:
                score += 2
            if val == 1 and row_any:
                score += 1
            if val == 0 and not row_all:
                score += 1
        scored.append((-score, p))
    scored.sort()
    return [p for _, p in scored]


def search(state, initial_queue=None):
    if not propagate(state, initial_queue):
        return None
    if is_solved(state):
        return state

    branch = choose_branch_line(state)
    if branch is None:
        return None

    kind, idx = branch

    if kind == "r":
        patterns = ordered_patterns_for_row(state, idx)
        for p in patterns:
            child = state.copy()
            child.row_domains[idx] = [p]
            child.row_any_black[idx] = p
            child.row_all_black[idx] = p

            ok = True
            for c in range(child.w):
                v = 1 if (p >> c) & 1 else 0
                if assign_cell(child, idx, c, v) < 0:
                    ok = False
                    break
            if not ok:
                continue

            init = [("r", idx)] + [("c", c) for c in range(child.w)]
            out = search(child, init)
            if out is not None:
                return out

    else:
        patterns = ordered_patterns_for_col(state, idx)
        for p in patterns:
            child = state.copy()
            child.col_domains[idx] = [p]
            child.col_any_black[idx] = p
            child.col_all_black[idx] = p

            ok = True
            for r in range(child.h):
                v = 1 if (p >> r) & 1 else 0
                if assign_cell(child, r, idx, v) < 0:
                    ok = False
                    break
            if not ok:
                continue

            init = [("c", idx)] + [("r", r) for r in range(child.h)]
            out = search(child, init)
            if out is not None:
                return out

    return None


def render_solution(state):
    grid = []
    for r in range(state.h):
        row = []
        for c in range(state.w):
            row.append('B' if (state.row_black[r] >> c) & 1 else None)
        grid.append(row)
    return repr(grid)


def solve(observation):
    row_clues = observation["row_black_runs"]
    col_clues = observation["col_black_runs"]

    h = len(row_clues)
    w = len(col_clues)

    row_domains = []
    for clues in row_clues:
        dom = line_patterns(w, tuple(clues))
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for clues in col_clues:
        dom = line_patterns(h, tuple(clues))
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    state = State(row_domains, col_domains, h, w)
    result = search(state)
    return render_solution(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

