from functools import lru_cache
import sys

sys.setrecursionlimit(1000000)


def solve(observation):
    data = observation["data"]
    if not data or not data[0]:
        return repr([])

    orig_h = len(data)
    orig_w = len(data[0])

    # Reduce exponential width by transposing when useful.
    transposed = orig_w > orig_h
    if transposed:
        data = [list(row) for row in zip(*data)]

    H = len(data)
    W = len(data[0])
    N = H * W
    full_mask = (1 << N) - 1

    def idx(r, c):
        return r * W + c

    # Build exact 3x3-sum constraints from numbered cells.
    constraints = []
    constraint_cells = []
    clue_positions_by_row = [[] for _ in range(H)]
    degrees = [0] * N

    for r in range(H):
        for c in range(W):
            v = data[r][c]
            if v is None:
                continue
            mask = 0
            cells = []
            for rr in range(max(0, r - 1), min(H, r + 2)):
                for cc in range(max(0, c - 1), min(W, c + 2)):
                    k = idx(rr, cc)
                    mask |= 1 << k
                    cells.append(k)
                    degrees[k] += 1
            constraints.append((mask, v))
            constraint_cells.append(cells)
            clue_positions_by_row[r].append((c, v))

    M = len(constraints)

    # Human-like propagation: local exact-fill, overlap reasoning, and limited contradiction probes.
    def assign_value(black, white, bit, value):
        if value:
            if white & bit:
                return None
            if black & bit:
                return black, white, False
            return black | bit, white, True
        else:
            if black & bit:
                return None
            if white & bit:
                return black, white, False
            return black, white | bit, True

    def assign_mask(black, white, mask, value):
        changed = False
        m = mask
        while m:
            bit = m & -m
            out = assign_value(black, white, bit, value)
            if out is None:
                return None
            black, white, ch = out
            changed |= ch
            m ^= bit
        return black, white, changed

    def propagate(black, white, allow_probe=True):
        while True:
            changed_any = False
            unknown = full_mask ^ (black | white)

            residuals = [0] * M
            umasks = [0] * M

            # Basic exact-sum propagation.
            for i, (cmask, target) in enumerate(constraints):
                assigned_black = (cmask & black).bit_count()
                um = cmask & unknown
                uc = um.bit_count()
                rem = target - assigned_black
                if rem < 0 or rem > uc:
                    return None
                residuals[i] = rem
                umasks[i] = um

                if uc == 0:
                    if rem != 0:
                        return None
                    continue
                if rem == 0:
                    out = assign_mask(black, white, um, 0)
                    if out is None:
                        return None
                    black, white, ch = out
                    changed_any |= ch
                elif rem == uc:
                    out = assign_mask(black, white, um, 1)
                    if out is None:
                        return None
                    black, white, ch = out
                    changed_any |= ch

            if changed_any:
                continue

            # Overlap / subset reasoning between constraints.
            overlap_changed = False
            for i in range(M):
                Ui = umasks[i]
                if not Ui:
                    continue
                ri = residuals[i]
                for j in range(i + 1, M):
                    Uj = umasks[j]
                    if not Uj:
                        continue
                    I = Ui & Uj
                    if not I:
                        continue

                    rj = residuals[j]
                    A = Ui & ~Uj
                    B = Uj & ~Ui
                    a = A.bit_count()
                    b = B.bit_count()
                    inter = I.bit_count()

                    minI = max(0, ri - a, rj - b)
                    maxI = min(inter, ri, rj)
                    if minI > maxI:
                        return None

                    # Force A if its sum becomes exact 0 or exact full.
                    minA = ri - maxI
                    maxA = ri - minI
                    if minA == maxA:
                        if minA == 0 and A:
                            out = assign_mask(black, white, A, 0)
                            if out is None:
                                return None
                            black, white, ch = out
                            overlap_changed |= ch
                        elif minA == a and A:
                            out = assign_mask(black, white, A, 1)
                            if out is None:
                                return None
                            black, white, ch = out
                            overlap_changed |= ch

                    # Force B if its sum becomes exact 0 or exact full.
                    minB = rj - maxI
                    maxB = rj - minI
                    if minB == maxB:
                        if minB == 0 and B:
                            out = assign_mask(black, white, B, 0)
                            if out is None:
                                return None
                            black, white, ch = out
                            overlap_changed |= ch
                        elif minB == b and B:
                            out = assign_mask(black, white, B, 1)
                            if out is None:
                                return None
                            black, white, ch = out
                            overlap_changed |= ch

                    # Force the intersection if its sum is exact 0 or exact full.
                    if minI == maxI:
                        if minI == 0 and I:
                            out = assign_mask(black, white, I, 0)
                            if out is None:
                                return None
                            black, white, ch = out
                            overlap_changed |= ch
                        elif minI == inter and I:
                            out = assign_mask(black, white, I, 1)
                            if out is None:
                                return None
                            black, white, ch = out
                            overlap_changed |= ch

            if overlap_changed:
                continue

            # Limited contradiction probing for stubborn cells.
            if allow_probe:
                unknown = full_mask ^ (black | white)
                unknown_indices = []
                m = unknown
                while m:
                    bit = m & -m
                    k = bit.bit_length() - 1
                    unknown_indices.append(k)
                    m ^= bit

                if unknown_indices:
                    unknown_indices.sort(key=lambda k: (-degrees[k], k))
                    probe_limit = len(unknown_indices) if len(unknown_indices) <= 18 else 18

                    probe_changed = False
                    for k in unknown_indices[:probe_limit]:
                        bit = 1 << k
                        res0 = propagate(black, white | bit, allow_probe=False)
                        res1 = propagate(black | bit, white, allow_probe=False)

                        if res0 is None and res1 is None:
                            return None
                        if res0 is None:
                            black, white = res1
                            probe_changed = True
                            break
                        if res1 is None:
                            black, white = res0
                            probe_changed = True
                            break

                    if probe_changed:
                        continue

            return black, white

    prop = propagate(0, 0, allow_probe=True)
    if prop is None:
        return "No Solution"
    black_fixed, white_fixed = prop

    fixed_black_rows = [0] * H
    fixed_white_rows = [0] * H
    for r in range(H):
        rb = 0
        rw = 0
        for c in range(W):
            bit = 1 << idx(r, c)
            if black_fixed & bit:
                rb |= 1 << c
            elif white_fixed & bit:
                rw |= 1 << c
        if rb & rw:
            return "No Solution"
        fixed_black_rows[r] = rb
        fixed_white_rows[r] = rw

    # Precompute 1-row horizontal 3-cell sums for all row masks.
    row_count_limit = 1 << W
    hcount = [[0] * W for _ in range(row_count_limit)]
    for mask in range(row_count_limit):
        for c in range(W):
            s = (mask >> c) & 1
            if c > 0:
                s += (mask >> (c - 1)) & 1
            if c + 1 < W:
                s += (mask >> (c + 1)) & 1
            hcount[mask][c] = s

    def enumerate_row_masks(fb, fw):
        if fb & fw:
            return []
        masks = [fb]
        for c in range(W):
            bit = 1 << c
            if (fb | fw) & bit:
                continue
            masks += [m | bit for m in masks]
        return masks

    row0_candidates = enumerate_row_masks(fixed_black_rows[0], fixed_white_rows[0])
    if not row0_candidates:
        return "No Solution"

    def row_valid(r, above, mid, below):
        for c, val in clue_positions_by_row[r]:
            if hcount[above][c] + hcount[mid][c] + hcount[below][c] != val:
                return False
        return True

    # Generate the next row from a fixed pair of previous rows by solving the induced 1D local equations.
    @lru_cache(maxsize=None)
    def generate_next_rows(r, above, mid):
        next_row = r + 1
        if next_row >= H:
            return ()

        req = [None] * W
        for c, val in clue_positions_by_row[r]:
            need = val - hcount[above][c] - hcount[mid][c]
            limit = 2 if c == 0 or c == W - 1 else 3
            if need < 0 or need > limit:
                return ()
            req[c] = need

        fb = fixed_black_rows[next_row]
        fw = fixed_white_rows[next_row]
        if fb & fw:
            return ()

        def allowed_bit(c):
            bit = 1 << c
            if fb & bit:
                return (1,)
            if fw & bit:
                return (0,)
            return (0, 1)

        out = []

        if W == 1:
            for b0 in allowed_bit(0):
                if req[0] is not None and b0 != req[0]:
                    continue
                out.append(b0)
            return tuple(out)

        def rec(pos, a, b, mask):
            # After choosing bit at index pos-1 (= b), clue at column pos-1 becomes checkable
            # once current bit x is selected.
            if pos == W:
                if req[W - 1] is not None and a + b != req[W - 1]:
                    return
                out.append(mask)
                return

            for x in allowed_bit(pos):
                if req[pos - 1] is not None and a + b + x != req[pos - 1]:
                    continue
                rec(pos + 1, b, x, mask | (x << pos))

        for b0 in allowed_bit(0):
            for b1 in allowed_bit(1):
                if req[0] is not None and b0 + b1 != req[0]:
                    continue
                rec(2, b0, b1, b0 | (b1 << 1))

        return tuple(out)

    # Order the first row by how constrained its second-row continuations are.
    if H == 1:
        for row0 in row0_candidates:
            if row_valid(0, 0, row0, 0):
                solution_rows = (row0,)
                break
        else:
            return "No Solution"
    else:
        scored = []
        for row0 in row0_candidates:
            nexts = generate_next_rows(0, 0, row0)
            if nexts:
                scored.append((len(nexts), row0))
        if not scored:
            return "No Solution"
        scored.sort()

        @lru_cache(maxsize=None)
        def search(r, prev, curr):
            # Rows 0..r are fixed, and clue rows < r are already satisfied.
            if r == H - 1:
                if row_valid(r, prev, curr, 0):
                    return (curr,)
                return None

            for nxt in generate_next_rows(r, prev, curr):
                tail = search(r + 1, curr, nxt)
                if tail is not None:
                    return (curr,) + tail
            return None

        solution_rows = None
        for _, row0 in scored:
            for row1 in generate_next_rows(0, 0, row0):
                tail = search(1, row0, row1)
                if tail is not None:
                    solution_rows = (row0,) + tail
                    break
            if solution_rows is not None:
                break

        if solution_rows is None:
            return "No Solution"

    # Build oriented answer grid.
    oriented = []
    for r in range(H):
        row = []
        mask = solution_rows[r]
        for c in range(W):
            row.append('B' if ((mask >> c) & 1) else None)
        oriented.append(row)

    # Validate all clues before returning.
    def black_at(rr, cc):
        return 1 if oriented[rr][cc] == 'B' else 0

    for r in range(H):
        for c in range(W):
            v = data[r][c]
            if v is None:
                continue
            s = 0
            for rr in range(max(0, r - 1), min(H, r + 2)):
                for cc in range(max(0, c - 1), min(W, c + 2)):
                    s += black_at(rr, cc)
            if s != v:
                return "No Solution"

    # Transpose back to original orientation if needed.
    if transposed:
        oriented = [list(row) for row in zip(*oriented)]

    return repr(oriented)


if __name__ == "__main__":
    print(solve(OBSERVATION))

