import sys

def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation.get("data")
    adjacent = observation.get("adjacent", [])
    if not isinstance(data, list) or not data:
        return "No Solution"

    N = len(data)
    if any(not isinstance(row, list) or len(row) != N for row in data):
        return "No Solution"

    full = (1 << N) - 1
    cellmask_full = (1 << N) - 1
    bits = [1 << i for i in range(N)]
    bitcount = [0] * (full + 1)
    for m in range(full + 1):
        bitcount[m] = m.bit_count()

    # Precompute value-neighbor relations.
    consecutive_masks = [0] * N
    nonconsecutive_masks = [0] * N
    for i in range(N):
        m = 0
        if i > 0:
            m |= bits[i - 1]
        if i + 1 < N:
            m |= bits[i + 1]
        consecutive_masks[i] = m
        nonconsecutive_masks[i] = full ^ m ^ bits[i]

    # Domain-support tables for binary adjacency constraints.
    dot_support = [0] * (full + 1)
    nodot_support = [0] * (full + 1)
    for other in range(full + 1):
        ds = 0
        ns = 0
        for i in range(N):
            b = bits[i]
            if consecutive_masks[i] & other:
                ds |= b
            if nonconsecutive_masks[i] & other:
                ns |= b
        dot_support[other] = ds
        nodot_support[other] = ns

    subsets_hall = [m for m in range(1, full + 1) if 1 < bitcount[m] < N]

    # Build units.
    rows = [[r * N + c for c in range(N)] for r in range(N)]
    cols = [[r * N + c for r in range(N)] for c in range(N)]
    units = rows + cols

    # Build adjacency graph from midpoint coordinates.
    adjset = set()
    for rc in adjacent:
        if not isinstance(rc, (list, tuple)) or len(rc) != 2:
            return "No Solution"
        adjset.add((float(rc[0]), float(rc[1])))

    size = N * N
    cell_edges = [[] for _ in range(size)]
    edges = []

    for r in range(N):
        for c in range(N):
            i = r * N + c
            if c + 1 < N:
                j = i + 1
                mid = (float(r), float(c) + 0.5)
                is_dot = mid in adjset
                edges.append((i, j, is_dot))
                cell_edges[i].append((j, is_dot))
                cell_edges[j].append((i, is_dot))
            if r + 1 < N:
                j = (r + 1) * N + c
                mid = (float(r) + 0.5, float(c))
                is_dot = mid in adjset
                edges.append((i, j, is_dot))
                cell_edges[i].append((j, is_dot))
                cell_edges[j].append((i, is_dot))

    # Initialize domains.
    domains0 = [full] * size
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= N):
                return "No Solution"
            domains0[r * N + c] = bits[v - 1]

    def propagate(domains):
        # Repeatedly apply:
        # - arc consistency on every orthogonal adjacency
        # - row/column all-different filtering
        # - hidden singles
        # - Hall-style hidden subsets
        # - Hall-style naked subsets
        while True:
            changed = False

            # Binary adjacency constraints.
            for i, j, is_dot in edges:
                di = domains[i]
                dj = domains[j]
                support_table = dot_support if is_dot else nodot_support

                ni = di & support_table[dj]
                if ni != di:
                    if ni == 0:
                        return False
                    domains[i] = ni
                    di = ni
                    changed = True

                nj = dj & support_table[di]
                if nj != dj:
                    if nj == 0:
                        return False
                    domains[j] = nj
                    changed = True

            # Latin constraints by unit.
            for unit in units:
                used = 0

                # Assigned values must be unique in the unit.
                for idx in unit:
                    d = domains[idx]
                    if d == 0:
                        return False
                    if d & (d - 1) == 0:
                        if used & d:
                            return False
                        used |= d

                # Remove assigned values from non-singletons.
                if used:
                    keep_mask = ~used
                    for idx in unit:
                        d = domains[idx]
                        if d & (d - 1):
                            nd = d & keep_mask
                            if nd != d:
                                if nd == 0:
                                    return False
                                domains[idx] = nd
                                changed = True

                # Occurrence map per value -> positions in the unit.
                occ = [0] * N
                for pos, idx in enumerate(unit):
                    d = domains[idx]
                    m = d
                    while m:
                        b = m & -m
                        occ[b.bit_length() - 1] |= 1 << pos
                        m ^= b

                # Hidden singles and immediate Hall failures.
                for vi in range(N):
                    posmask = occ[vi]
                    if posmask == 0:
                        return False
                    if posmask & (posmask - 1) == 0:
                        pos = posmask.bit_length() - 1
                        idx = unit[pos]
                        nd = domains[idx] & bits[vi]
                        if nd != domains[idx]:
                            if nd == 0:
                                return False
                            domains[idx] = nd
                            changed = True

                # Hidden subsets via value subsets.
                union_pos = [0] * (full + 1)
                for s in range(1, full + 1):
                    lsb = s & -s
                    union_pos[s] = union_pos[s ^ lsb] | occ[lsb.bit_length() - 1]

                for s in subsets_hall:
                    k = bitcount[s]
                    posmask = union_pos[s]
                    cnt = posmask.bit_count()
                    if cnt < k:
                        return False
                    if cnt == k:
                        pm = posmask
                        while pm:
                            pbit = pm & -pm
                            pos = pbit.bit_length() - 1
                            idx = unit[pos]
                            nd = domains[idx] & s
                            if nd != domains[idx]:
                                if nd == 0:
                                    return False
                                domains[idx] = nd
                                changed = True
                            pm ^= pbit

                # Naked subsets via value subsets.
                for s in subsets_hall:
                    k = bitcount[s]
                    posmask = 0
                    for pos, idx in enumerate(unit):
                        if domains[idx] & ~s == 0:
                            posmask |= 1 << pos
                    if posmask.bit_count() == k:
                        other = cellmask_full ^ posmask
                        pm = other
                        while pm:
                            pbit = pm & -pm
                            pos = pbit.bit_length() - 1
                            idx = unit[pos]
                            nd = domains[idx] & ~s
                            if nd != domains[idx]:
                                if nd == 0:
                                    return False
                                domains[idx] = nd
                                changed = True
                            pm ^= pbit

            if not changed:
                return True

    def choose_cell(domains):
        best_idx = None
        best_key = None
        for idx, d in enumerate(domains):
            bc = d.bit_count()
            if bc <= 1:
                continue
            r, c = divmod(idx, N)

            # Tie-break toward more constrained cells.
            degree = 0
            for j in rows[r]:
                if j != idx and domains[j].bit_count() > 1:
                    degree += 1
            for j in cols[c]:
                if j != idx and domains[j].bit_count() > 1:
                    degree += 1
            for j, _ in cell_edges[idx]:
                if domains[j].bit_count() > 1:
                    degree += 2

            key = (bc, -degree)
            if best_key is None or key < best_key:
                best_key = key
                best_idx = idx
        return best_idx

    def value_order(domains, idx):
        d = domains[idx]
        values = []
        m = d
        while m:
            b = m & -m
            values.append(b)
            m ^= b

        r, c = divmod(idx, N)

        # Least-constraining-ish ordering:
        # larger score = leaves more support in neighbors/peers.
        def score(b):
            vi = b.bit_length() - 1
            s = 0
            for j in rows[r]:
                if j != idx and (domains[j] & b):
                    s += 1
            for j in cols[c]:
                if j != idx and (domains[j] & b):
                    s += 1
            rel_dot = consecutive_masks[vi]
            rel_nodot = nonconsecutive_masks[vi]
            for j, is_dot in cell_edges[idx]:
                allowed = rel_dot if is_dot else rel_nodot
                s += 2 * (allowed & domains[j]).bit_count()
            return s

        values.sort(key=score, reverse=True)
        return values

    failed = set()

    def search(domains):
        if not propagate(domains):
            return None

        state = tuple(domains)
        if state in failed:
            return None

        idx = choose_cell(domains)
        if idx is None:
            return domains

        for b in value_order(domains, idx):
            nd = domains.copy()
            nd[idx] = b
            out = search(nd)
            if out is not None:
                return out

        failed.add(state)
        return None

    def decode_solution(domains):
        grid = []
        for r in range(N):
            row = []
            for c in range(N):
                d = domains[r * N + c]
                if d == 0 or d & (d - 1):
                    return None
                row.append(d.bit_length())
            grid.append(row)
        return grid

    def validate(grid):
        target = set(range(1, N + 1))
        for r in range(N):
            if set(grid[r]) != target:
                return False
        for c in range(N):
            if set(grid[r][c] for r in range(N)) != target:
                return False
        for i, j, is_dot in edges:
            a = grid[i // N][i % N]
            b = grid[j // N][j % N]
            if (abs(a - b) == 1) != is_dot:
                return False
        return True

    result_domains = search(domains0.copy())
    if result_domains is None:
        return "No Solution"

    grid = decode_solution(result_domains)
    if grid is None or not validate(grid):
        return "No Solution"
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

