from itertools import combinations


def solve(observation):
    region = observation.get("region")
    data = observation.get("data")
    if not isinstance(region, list) or not isinstance(data, list):
        return "No Solution"
    n = len(region)
    if n == 0 or len(data) != n:
        return "No Solution"
    if any(len(row) != n for row in region) or any(len(row) != n for row in data):
        return "No Solution"

    # Normalize region ids to 0..R-1 in encounter order.
    reg_map = {}
    reg_ids = [[None] * n for _ in range(n)]
    next_id = 0
    for r in range(n):
        for c in range(n):
            x = region[r][c]
            if x not in reg_map:
                reg_map[x] = next_id
                next_id += 1
            reg_ids[r][c] = reg_map[x]
    if next_id != n:
        return "No Solution"

    m = n * n
    all_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def popcount(mask):
        return mask.bit_count()

    def single_value(mask):
        return mask.bit_length()

    # Build units.
    row_units = [[r * n + c for c in range(n)] for r in range(n)]
    col_units = [[r * n + c for r in range(n)] for c in range(n)]

    region_units = [[] for _ in range(n)]
    cell_region = [0] * m
    for r in range(n):
        for c in range(n):
            idx = r * n + c
            rid = reg_ids[r][c]
            region_units[rid].append(idx)
            cell_region[idx] = rid

    if any(len(u) != n for u in region_units):
        return "No Solution"

    cell_units = [[] for _ in range(m)]
    for r in range(n):
        for idx in row_units[r]:
            cell_units[idx].append(row_units[r])
    for c in range(n):
        for idx in col_units[c]:
            cell_units[idx].append(col_units[c])
    for rid in range(n):
        for idx in region_units[rid]:
            cell_units[idx].append(region_units[rid])

    peers = []
    for idx in range(m):
        s = set()
        for u in cell_units[idx]:
            s.update(u)
        s.discard(idx)
        peers.append(tuple(s))

    row_of = [i // n for i in range(m)]
    col_of = [i % n for i in range(m)]

    # Initial masks from givens.
    masks = [all_mask] * m
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= n):
                return "No Solution"
            masks[r * n + c] = bit(v)

    # Fast consistency check on givens.
    for unit in row_units + col_units + region_units:
        seen = 0
        for idx in unit:
            if is_single(masks[idx]):
                if seen & masks[idx]:
                    return "No Solution"
                seen |= masks[idx]

    def reduce_mask(cur_masks, idx, remove_bits, queue, queued):
        old = cur_masks[idx]
        new = old & ~remove_bits
        if new == old:
            return True, False
        if new == 0:
            return False, False
        cur_masks[idx] = new
        if is_single(new) and not queued[idx]:
            queue.append(idx)
            queued[idx] = True
        return True, True

    def force_mask(cur_masks, idx, forced_bit, queue, queued):
        old = cur_masks[idx]
        if old == forced_bit:
            return True, False
        if not (old & forced_bit):
            return False, False
        cur_masks[idx] = forced_bit
        if not queued[idx]:
            queue.append(idx)
            queued[idx] = True
        return True, True

    def hidden_singles(cur_masks, queue, queued):
        changed = False
        for unit in row_units + col_units + region_units:
            counts = [0] * n
            last = [-1] * n
            for idx in unit:
                x = cur_masks[idx]
                while x:
                    b = x & -x
                    d = b.bit_length() - 1
                    counts[d] += 1
                    last[d] = idx
                    x ^= b
            for d in range(n):
                if counts[d] == 0:
                    return False, changed
                if counts[d] == 1:
                    ok, ch = force_mask(cur_masks, last[d], 1 << d, queue, queued)
                    if not ok:
                        return False, changed
                    changed |= ch
        return True, changed

    def naked_subsets(cur_masks, queue, queued):
        changed = False
        for unit in row_units + col_units + region_units:
            unsolved = [idx for idx in unit if not is_single(cur_masks[idx])]
            if len(unsolved) < 2:
                continue

            # Exact-mask naked subsets.
            by_mask = {}
            for idx in unsolved:
                by_mask.setdefault(cur_masks[idx], []).append(idx)
            for mask, cells in by_mask.items():
                k = popcount(mask)
                if 2 <= k <= 4 and len(cells) == k:
                    for idx in unit:
                        if idx not in cells:
                            ok, ch = reduce_mask(cur_masks, idx, mask, queue, queued)
                            if not ok:
                                return False, changed
                            changed |= ch

            # General 2/3-cell naked subsets.
            small = [idx for idx in unsolved if 2 <= popcount(cur_masks[idx]) <= 3]
            for k in (2, 3):
                if len(small) < k:
                    continue
                for combo in combinations(small, k):
                    union = 0
                    for idx in combo:
                        union |= cur_masks[idx]
                    if popcount(union) != k:
                        continue
                    others = [idx for idx in unit if idx not in combo]
                    useful = False
                    for idx in others:
                        if cur_masks[idx] & union:
                            useful = True
                            break
                    if not useful:
                        continue
                    for idx in others:
                        ok, ch = reduce_mask(cur_masks, idx, union, queue, queued)
                        if not ok:
                            return False, changed
                        changed |= ch
        return True, changed

    def locked_candidates(cur_masks, queue, queued):
        changed = False

        # Region -> row/col
        for rid, unit in enumerate(region_units):
            unit_set = set(unit)
            for d in range(n):
                b = 1 << d
                cells = [idx for idx in unit if cur_masks[idx] & b]
                if not cells:
                    return False, changed
                rows = {row_of[idx] for idx in cells}
                if len(rows) == 1:
                    rr = next(iter(rows))
                    for idx in row_units[rr]:
                        if idx not in unit_set:
                            ok, ch = reduce_mask(cur_masks, idx, b, queue, queued)
                            if not ok:
                                return False, changed
                            changed |= ch
                cols = {col_of[idx] for idx in cells}
                if len(cols) == 1:
                    cc = next(iter(cols))
                    for idx in col_units[cc]:
                        if idx not in unit_set:
                            ok, ch = reduce_mask(cur_masks, idx, b, queue, queued)
                            if not ok:
                                return False, changed
                            changed |= ch

        # Row/col -> region
        for r in range(n):
            for d in range(n):
                b = 1 << d
                cells = [idx for idx in row_units[r] if cur_masks[idx] & b]
                if not cells:
                    return False, changed
                regs = {cell_region[idx] for idx in cells}
                if len(regs) == 1:
                    rid = next(iter(regs))
                    for idx in region_units[rid]:
                        if row_of[idx] != r:
                            ok, ch = reduce_mask(cur_masks, idx, b, queue, queued)
                            if not ok:
                                return False, changed
                            changed |= ch

        for c in range(n):
            for d in range(n):
                b = 1 << d
                cells = [idx for idx in col_units[c] if cur_masks[idx] & b]
                if not cells:
                    return False, changed
                regs = {cell_region[idx] for idx in cells}
                if len(regs) == 1:
                    rid = next(iter(regs))
                    for idx in region_units[rid]:
                        if col_of[idx] != c:
                            ok, ch = reduce_mask(cur_masks, idx, b, queue, queued)
                            if not ok:
                                return False, changed
                            changed |= ch
        return True, changed

    def propagate(cur_masks):
        queue = [i for i in range(m) if is_single(cur_masks[i])]
        queued = [False] * m
        for i in queue:
            queued[i] = True

        while True:
            progress = False

            while queue:
                idx = queue.pop()
                queued[idx] = False
                mask = cur_masks[idx]
                if not is_single(mask):
                    continue
                for p in peers[idx]:
                    ok, ch = reduce_mask(cur_masks, p, mask, queue, queued)
                    if not ok:
                        return None
                    progress |= ch

            ok, ch = hidden_singles(cur_masks, queue, queued)
            if not ok:
                return None
            progress |= ch
            if queue:
                continue

            ok, ch = locked_candidates(cur_masks, queue, queued)
            if not ok:
                return None
            progress |= ch
            if queue:
                continue

            ok, ch = naked_subsets(cur_masks, queue, queued)
            if not ok:
                return None
            progress |= ch
            if queue:
                continue

            # Recheck each unit has every digit still possible.
            for unit in row_units + col_units + region_units:
                union = 0
                for idx in unit:
                    if cur_masks[idx] == 0:
                        return None
                    union |= cur_masks[idx]
                if union != all_mask:
                    return None

            if not progress:
                return cur_masks

    def choose_cell(cur_masks):
        best_idx = -1
        best_size = n + 1
        best_score = None
        for idx, mask in enumerate(cur_masks):
            pc = popcount(mask)
            if pc <= 1:
                continue
            # Tie-break by peer pressure: choose cell affecting the most constrained neighborhood.
            score = sum(popcount(cur_masks[p]) for p in peers[idx])
            if pc < best_size or (pc == best_size and (best_score is None or score < best_score)):
                best_size = pc
                best_score = score
                best_idx = idx
        return best_idx

    def ordered_bits(cur_masks, idx):
        mask = cur_masks[idx]
        bits = []
        x = mask
        while x:
            b = x & -x
            x ^= b
            # Prefer digits that are scarcer in the three units containing this cell.
            scarcity = 0
            for unit in cell_units[idx]:
                scarcity += sum(1 for j in unit if cur_masks[j] & b)
            bits.append((scarcity, b))
        bits.sort()
        return [b for _, b in bits]

    def search(cur_masks):
        cur_masks = propagate(cur_masks[:])
        if cur_masks is None:
            return None
        if all(is_single(x) for x in cur_masks):
            return cur_masks

        idx = choose_cell(cur_masks)
        if idx < 0:
            return None

        for b in ordered_bits(cur_masks, idx):
            nxt = cur_masks[:]
            nxt[idx] = b
            res = search(nxt)
            if res is not None:
                return res
        return None

    solved = search(masks)
    if solved is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(solved[r * n + c]))
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 0, 2, 2], [0, 0, 0, 0, 0, 2, 2], [0, 0, 0, 0, 0, 2, 3], [0, 0, 0, 0, 4, 2, 3], [5, 5, 5, 5, 6, 2, 3], [5, 7, 6, 6, 6, 6, 3], [7, 7, 6, 8, 8, 3, 3]], 'row_stitch_counts': [2, 2, 0, 1, 4, 4, 3], 'col_stitch_counts': [2, 4, 3, 3, 2, 2, 0]}

from collections import deque


# General solver for the "stitches on region boundaries" puzzle.
#
# Modeling used here:
# - Region grid is N x N cells.
# - Hole grid is N x N holes.
# - A stitch is an orthogonal segment between adjacent holes.
# - For every border between two orthogonally adjacent cells from different regions,
#   exactly one of the two endpoint-parallel stitch positions must be chosen.
# - No two stitches may share a hole, so chosen stitches form a matching on holes.
# - Row/column clues count used holes.
#
# This matches the usual human reasoning structure:
# 1) each region boundary creates a binary local choice;
# 2) choosing a stitch immediately forbids all other stitches using its endpoints;
# 3) row/column clues force holes to be used / unused;
# 4) holes forced used with one remaining option determine a stitch;
# 5) boundaries with one remaining candidate determine a stitch;
# 6) only then, branch on the most constrained unresolved boundary/hole.


def solve(observation):
    region = observation["region"]
    row_clues = observation["row_stitch_counts"]
    col_clues = observation["col_stitch_counts"]

    if not region or not row_clues or not col_clues:
        return "No Solution"

    n = len(region)
    if any(len(row) != n for row in region):
        return "No Solution"
    if len(row_clues) != n or len(col_clues) != n:
        return "No Solution"

    # ---------- Build segments and boundary constraints ----------

    def hole_id(r, c):
        return r * n + c

    seg_index = {}
    seg_coords = []

    def add_segment(a, b):
        if a > b:
            a, b = b, a
        key = (a, b)
        idx = seg_index.get(key)
        if idx is None:
            idx = len(seg_coords)
            seg_index[key] = idx
            seg_coords.append(key)
        return idx

    boundaries = []

    # Horizontal cell adjacencies: cells (r,c) and (r,c+1)
    # Candidate stitches are horizontal segments at rows r and r+1.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                cand = []
                for rr in (r, r + 1):
                    if 0 <= rr < n and 0 <= c < n - 1:
                        cand.append(add_segment(hole_id(rr, c), hole_id(rr, c + 1)))
                cand = sorted(set(cand))
                if not cand:
                    return "No Solution"
                boundaries.append(cand)

    # Vertical cell adjacencies: cells (r,c) and (r+1,c)
    # Candidate stitches are vertical segments at cols c and c+1.
    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                cand = []
                for cc in (c, c + 1):
                    if 0 <= cc < n and 0 <= r < n - 1:
                        cand.append(add_segment(hole_id(r, cc), hole_id(r + 1, cc)))
                cand = sorted(set(cand))
                if not cand:
                    return "No Solution"
                boundaries.append(cand)

    s_count = len(seg_coords)
    b_count = len(boundaries)
    h_count = n * n

    incident = [[] for _ in range(h_count)]
    seg_bounds = [[] for _ in range(s_count)]
    for s, (a, b) in enumerate(seg_coords):
        incident[a].append(s)
        incident[b].append(s)
    for b, cand in enumerate(boundaries):
        for s in cand:
            seg_bounds[s].append(b)

    row_holes = [[hole_id(r, c) for c in range(n)] for r in range(n)]
    col_holes = [[hole_id(r, c) for r in range(n)] for c in range(n)]

    # ---------- Solver state with trail-based backtracking ----------

    # Segment state: -1 false, 0 undecided, 1 true
    seg_state = [0] * s_count

    # Hole state: -1 undecided, 0 unused, 1 used
    hole_state = [-1] * h_count

    # If a hole is already matched, which segment uses it; otherwise -1
    hole_chosen = [-1] * h_count

    # Number of not-false incident segments remaining for this hole
    hole_live = [len(incident[h]) for h in range(h_count)]

    # Boundary satisfied by which segment; otherwise -1
    bound_sat = [-1] * b_count

    # Number of candidate segments for boundary that are not false
    bound_live = [len(boundaries[b]) for b in range(b_count)]

    # Row/column fixed-count bookkeeping
    row_yes = [0] * n
    row_unk = [n] * n
    col_yes = [0] * n
    col_unk = [n] * n

    trail = []

    def save(arr, idx, old):
        trail.append((arr, idx, old))

    def set_hole_state(h, value, q):
        old = hole_state[h]
        if old == value:
            return True
        if old != -1 and old != value:
            return False

        save(hole_state, h, old)
        hole_state[h] = value

        r, c = divmod(h, n)

        save(row_unk, r, row_unk[r])
        row_unk[r] -= 1
        save(col_unk, c, col_unk[c])
        col_unk[c] -= 1

        if value == 1:
            save(row_yes, r, row_yes[r])
            row_yes[r] += 1
            save(col_yes, c, col_yes[c])
            col_yes[c] += 1

            if hole_chosen[h] == -1:
                if hole_live[h] == 0:
                    return False
                if hole_live[h] == 1:
                    for s in incident[h]:
                        if seg_state[s] != -1:
                            q.append(("seg", s, 1))
                            break
        else:
            if hole_chosen[h] != -1:
                return False
            for s in incident[h]:
                if seg_state[s] == 0:
                    q.append(("seg", s, -1))

        q.append(("row", r))
        q.append(("col", c))
        return True

    def set_seg_true(s, q):
        old = seg_state[s]
        if old == 1:
            return True
        if old == -1:
            return False

        save(seg_state, s, old)
        seg_state[s] = 1
        a, b = seg_coords[s]

        for h in (a, b):
            if hole_chosen[h] not in (-1, s):
                return False
            if hole_chosen[h] == -1:
                save(hole_chosen, h, -1)
                hole_chosen[h] = s
                q.append(("hole", h, 1))
                for other in incident[h]:
                    if other != s and seg_state[other] == 0:
                        q.append(("seg", other, -1))

        for bd in seg_bounds[s]:
            if bound_sat[bd] not in (-1, s):
                return False
            if bound_sat[bd] == -1:
                save(bound_sat, bd, -1)
                bound_sat[bd] = s
                for other in boundaries[bd]:
                    if other != s and seg_state[other] == 0:
                        q.append(("seg", other, -1))

        return True

    def set_seg_false(s, q):
        old = seg_state[s]
        if old == -1:
            return True
        if old == 1:
            return False

        save(seg_state, s, old)
        seg_state[s] = -1
        a, b = seg_coords[s]

        for h in (a, b):
            if hole_chosen[h] == -1:
                save(hole_live, h, hole_live[h])
                hole_live[h] -= 1
                if hole_live[h] < 0:
                    return False
                if hole_live[h] == 0:
                    q.append(("hole", h, 0))
                elif hole_state[h] == 1 and hole_live[h] == 1:
                    for other in incident[h]:
                        if seg_state[other] != -1:
                            q.append(("seg", other, 1))
                            break

        for bd in seg_bounds[s]:
            if bound_sat[bd] == -1:
                save(bound_live, bd, bound_live[bd])
                bound_live[bd] -= 1
                if bound_live[bd] <= 0:
                    return False
                if bound_live[bd] == 1:
                    for other in boundaries[bd]:
                        if seg_state[other] != -1:
                            q.append(("seg", other, 1))
                            break

        return True

    def check_row(r, q):
        yes = row_yes[r]
        unk = row_unk[r]
        clue = row_clues[r]
        if yes > clue or yes + unk < clue:
            return False
        need = clue - yes
        if need == 0:
            for h in row_holes[r]:
                if hole_state[h] == -1:
                    q.append(("hole", h, 0))
        elif need == unk:
            for h in row_holes[r]:
                if hole_state[h] == -1:
                    q.append(("hole", h, 1))
        return True

    def check_col(c, q):
        yes = col_yes[c]
        unk = col_unk[c]
        clue = col_clues[c]
        if yes > clue or yes + unk < clue:
            return False
        need = clue - yes
        if need == 0:
            for h in col_holes[c]:
                if hole_state[h] == -1:
                    q.append(("hole", h, 0))
        elif need == unk:
            for h in col_holes[c]:
                if hole_state[h] == -1:
                    q.append(("hole", h, 1))
        return True

    def propagate(q):
        while q:
            typ, idx, value = q.popleft()
            if typ == "seg":
                ok = set_seg_true(idx, q) if value == 1 else set_seg_false(idx, q)
            elif typ == "hole":
                ok = set_hole_state(idx, value, q)
            elif typ == "row":
                ok = check_row(idx, q)
            else:
                ok = check_col(idx, q)
            if not ok:
                return False
        return True

    def restore(mark):
        while len(trail) > mark:
            arr, idx, old = trail.pop()
            arr[idx] = old

    def solved():
        for bd in range(b_count):
            if bound_sat[bd] == -1:
                return False
        for r in range(n):
            if row_yes[r] != row_clues[r] or row_unk[r] != 0:
                return False
        for c in range(n):
            if col_yes[c] != col_clues[c] or col_unk[c] != 0:
                return False
        return True

    def choose_branch():
        # 1) Most constrained unsatisfied boundary.
        best = None
        best_size = 10**9
        for bd in range(b_count):
            if bound_sat[bd] == -1:
                opts = [s for s in boundaries[bd] if seg_state[s] != -1]
                if len(opts) < best_size:
                    best_size = len(opts)
                    best = ("boundary", bd, opts)
                    if best_size <= 2:
                        break
        if best is not None:
            return best

        # 2) Used hole still waiting for its unique segment.
        best = None
        best_size = 10**9
        for h in range(h_count):
            if hole_state[h] == 1 and hole_chosen[h] == -1:
                opts = [s for s in incident[h] if seg_state[s] != -1]
                if len(opts) < best_size:
                    best_size = len(opts)
                    best = ("hole", h, opts)
                    if best_size <= 2:
                        break
        if best is not None:
            return best

        return None

    def extract_answer():
        ans = []
        for s, st in enumerate(seg_state):
            if st == 1:
                a, b = seg_coords[s]
                r1, c1 = divmod(a, n)
                r2, c2 = divmod(b, n)
                ans.append([(r1, c1), (r2, c2)])
        ans.sort()
        return ans

    def dfs():
        if solved():
            return extract_answer()

        branch = choose_branch()
        if branch is None:
            return None

        kind, _, opts = branch

        # Human-like branching: try the most informative stitch first,
        # preferring one that satisfies the most boundaries.
        opts = sorted(opts, key=lambda s: (-len(seg_bounds[s]), seg_coords[s]))

        for s in opts:
            mark = len(trail)
            q = deque([("seg", s, 1)])
            if propagate(q):
                res = dfs()
                if res is not None:
                    return res
            restore(mark)

        # If branch came from a hole, all candidates exhausted means dead end.
        # If branch came from a boundary, same.
        return None

    # ---------- Initial propagation ----------

    init_q = deque()
    for h in range(h_count):
        if hole_live[h] == 0:
            init_q.append(("hole", h, 0))
    for r in range(n):
        init_q.append(("row", r, None))
    for c in range(n):
        init_q.append(("col", c, None))

    if not propagate(init_q):
        return "No Solution"

    result = dfs()
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

