from math import comb
import sys

BS = 1   # '\'
SL = 2   # '/'

def solve(observation):
    data = observation.get('data')
    if not data or len(data) < 2 or any(len(row) != len(data[0]) for row in data):
        return "No Solution"

    H = len(data)
    W = len(data[0])
    if H != W:
        return "No Solution"
    N = H - 1
    if N <= 0:
        return "No Solution"

    sys.setrecursionlimit(10000)

    def vid(r, c):
        return r * (N + 1) + c

    def cid(r, c):
        return r * N + c

    num_cells = N * N
    num_vertices = (N + 1) * (N + 1)

    # Per-cell geometry
    bs_u = [0] * num_cells
    bs_v = [0] * num_cells
    sl_u = [0] * num_cells
    sl_v = [0] * num_cells
    cell_clue_vertices = [[] for _ in range(num_cells)]

    # For each vertex, list of (cell_index, orientation_that_touches_vertex)
    incident = [[] for _ in range(num_vertices)]
    clues = [None] * num_vertices
    clue_vertices = []

    for r in range(N + 1):
        for c in range(N + 1):
            v = vid(r, c)
            clues[v] = data[r][c]
            if data[r][c] is not None:
                clue_vertices.append(v)

    for r in range(N):
        for c in range(N):
            cell = cid(r, c)
            tl = vid(r, c)
            tr = vid(r, c + 1)
            bl = vid(r + 1, c)
            br = vid(r + 1, c + 1)

            bs_u[cell], bs_v[cell] = tl, br
            sl_u[cell], sl_v[cell] = tr, bl

            incident[tl].append((cell, BS))
            incident[tr].append((cell, SL))
            incident[bl].append((cell, SL))
            incident[br].append((cell, BS))

    for cell in range(num_cells):
        r, c = divmod(cell, N)
        verts = [vid(r, c), vid(r, c + 1), vid(r + 1, c), vid(r + 1, c + 1)]
        cell_clue_vertices[cell] = [v for v in verts if clues[v] is not None]

    # Quick impossible clue check from static local degree
    for v in clue_vertices:
        if clues[v] < 0 or clues[v] > len(incident[v]):
            return "No Solution"

    class RollbackDSU:
        __slots__ = ("parent", "size", "history")
        def __init__(self, n):
            self.parent = list(range(n))
            self.size = [1] * n
            self.history = []

        def find(self, x):
            while self.parent[x] != x:
                x = self.parent[x]
            return x

        def union(self, a, b):
            a = self.find(a)
            b = self.find(b)
            if a == b:
                return False
            if self.size[a] < self.size[b]:
                a, b = b, a
            self.history.append((b, self.parent[b], a, self.size[a]))
            self.parent[b] = a
            self.size[a] += self.size[b]
            return True

        def snapshot(self):
            return len(self.history)

        def rollback(self, snap):
            while len(self.history) > snap:
                b, old_pb, a, old_sa = self.history.pop()
                self.parent[b] = old_pb
                self.size[a] = old_sa

        def comp_size(self, x):
            return self.size[self.find(x)]

    dsu = RollbackDSU(num_vertices)
    domain = [BS | SL] * num_cells
    changes = []

    def other(o):
        return SL if o == BS else BS

    def vertex_state(v, override_cell=-1, override_orient=0):
        # Returns:
        # forced_includes: count already fixed to touch v
        # amb: list of (cell, touch_orientation) among still undecided
        forced = 0
        amb = []
        for cell, touch_orient in incident[v]:
            if cell == override_cell:
                if override_orient == touch_orient:
                    forced += 1
                continue
            dom = domain[cell]
            if dom == touch_orient:
                forced += 1
            elif dom == (BS | SL):
                amb.append((cell, touch_orient))
        return forced, amb

    def orientation_endpoints(cell, orient):
        if orient == BS:
            return bs_u[cell], bs_v[cell]
        return sl_u[cell], sl_v[cell]

    def orientation_possible(cell, orient):
        dom = domain[cell]
        if not (dom & orient):
            return False
        if dom == orient:
            return True

        u, v = orientation_endpoints(cell, orient)
        if dsu.find(u) == dsu.find(v):
            return False

        # Local clue feasibility after fixing this cell to orient
        for vx in cell_clue_vertices[cell]:
            forced, amb = vertex_state(vx, cell, orient)
            k = clues[vx]
            if k < forced or k > forced + len(amb):
                return False
        return True

    def set_domain(cell, orient):
        old = domain[cell]
        if old == orient:
            return True
        if not (old & orient):
            return False
        if old != (BS | SL):
            return False
        if not orientation_possible(cell, orient):
            return False

        changes.append((cell, old))
        domain[cell] = orient

        u, v = orientation_endpoints(cell, orient)
        if not dsu.union(u, v):
            return False
        return True

    def snapshot():
        return (len(changes), dsu.snapshot())

    def rollback(mark):
        chg_len, dsu_snap = mark
        while len(changes) > chg_len:
            cell, old = changes.pop()
            domain[cell] = old
        dsu.rollback(dsu_snap)

    def propagate():
        # Repeatedly apply:
        # 1) exact-count saturation at each numbered dot
        # 2) per-cell impossible-orientation elimination
        while True:
            changed = False

            # Human-like clue saturation:
            # if clue == forced, all undecided around it must avoid the dot
            # if clue == forced + undecided, all undecided must touch the dot
            for v in clue_vertices:
                forced, amb = vertex_state(v)
                k = clues[v]
                if k < forced or k > forced + len(amb):
                    return False
                if not amb:
                    continue
                if k == forced:
                    for cell, touch_orient in amb:
                        if domain[cell] == (BS | SL):
                            if not set_domain(cell, other(touch_orient)):
                                return False
                            changed = True
                elif k == forced + len(amb):
                    for cell, touch_orient in amb:
                        if domain[cell] == (BS | SL):
                            if not set_domain(cell, touch_orient):
                                return False
                            changed = True

            # Human-like contradiction scan on each undecided cell:
            # if one slash direction violates some clue or closes a loop,
            # the other direction is forced.
            for cell in range(num_cells):
                if domain[cell] != (BS | SL):
                    continue
                ok_bs = orientation_possible(cell, BS)
                ok_sl = orientation_possible(cell, SL)

                if not ok_bs and not ok_sl:
                    return False
                if ok_bs and ok_sl:
                    continue

                if not set_domain(cell, BS if ok_bs else SL):
                    return False
                changed = True

            if not changed:
                break
        return True

    def cell_branch_score(cell):
        # Smaller is tighter.
        total_ways = 0
        total_amb = 0
        touched = 0
        for v in cell_clue_vertices[cell]:
            forced, amb = vertex_state(v)
            k = clues[v] - forced
            a = len(amb)
            if a > 0 and 0 <= k <= a:
                total_ways += comb(a, k)
                total_amb += a
                touched += 1
        return (total_ways, total_amb, -touched, cell)

    def choose_cell():
        # Prefer branching from the tightest clue first:
        # smallest number of local combinations C(amb, need).
        best_v = None
        best_key = None
        for v in clue_vertices:
            forced, amb = vertex_state(v)
            a = len(amb)
            if a < 2:
                continue
            need = clues[v] - forced
            if not (0 <= need <= a):
                return None
            key = (comb(a, need), a, v)
            if best_key is None or key < best_key:
                best_key = key
                best_v = v

        if best_v is not None:
            candidates = [cell for cell, _ in vertex_state(best_v)[1] if domain[cell] == (BS | SL)]
            candidates.sort(key=cell_branch_score)
            return candidates[0] if candidates else None

        # Fallback: globally most constrained undecided cell
        best = None
        best_key = None
        for cell in range(num_cells):
            if domain[cell] != (BS | SL):
                continue
            key = cell_branch_score(cell)
            if best_key is None or key < best_key:
                best_key = key
                best = cell
        return best

    def option_score(cell, orient):
        # Prefer the move that leaves fewer local clue combinations.
        total_ways = 0
        comp_penalty = 0
        u, v = orientation_endpoints(cell, orient)
        comp_penalty = -(dsu.comp_size(u) + dsu.comp_size(v))

        for vx in cell_clue_vertices[cell]:
            forced, amb = vertex_state(vx, cell, orient)
            need = clues[vx] - forced
            a = len(amb)
            if not (0 <= need <= a):
                return (10**9, 10**9)
            total_ways += comb(a, need)
        return (total_ways, comp_penalty)

    def solved():
        return all(dom != (BS | SL) for dom in domain)

    def dfs():
        if not propagate():
            return False
        if solved():
            return True

        cell = choose_cell()
        if cell is None:
            return False

        options = []
        for orient in (BS, SL):
            if domain[cell] & orient and orientation_possible(cell, orient):
                options.append((option_score(cell, orient), orient))
        options.sort()

        for _, orient in options:
            mark = snapshot()
            if set_domain(cell, orient) and dfs():
                return True
            rollback(mark)
        return False

    if not dfs():
        return "No Solution"

    ans = []
    for r in range(N):
        row = []
        for c in range(N):
            dom = domain[cid(r, c)]
            row.append('\\' if dom == BS else '/')
        ans.append(row)
    return str(ans)

