OBSERVATION = {'row_sum': [6, 4, 9, 7, 11], 'col_sum': [4, 9, 3, 7, 13]}

from functools import lru_cache


# Assumption implied by the puzzle format shown:
# - column weights are 1..number_of_columns
# - row weights are 1..number_of_rows
# Observation therefore only needs row targets and column targets.


@lru_cache(maxsize=None)
def subset_masks(num_bits, target):
    # All bitmasks over weights 1..num_bits whose selected weights sum to target.
    if target < 0 or target > num_bits * (num_bits + 1) // 2:
        return ()
    if num_bits == 0:
        return (0,) if target == 0 else ()
    without_last = subset_masks(num_bits - 1, target)
    with_last_base = subset_masks(num_bits - 1, target - num_bits)
    if not with_last_base:
        return without_last
    bit = 1 << (num_bits - 1)
    return without_last + tuple(mask | bit for mask in with_last_base)


def line_any_all(domains, full_mask):
    any_ones = 0
    all_ones = full_mask
    for mask in domains:
        any_ones |= mask
        all_ones &= mask
    return any_ones, all_ones


def propagate(row_domains, col_domains):
    m = len(row_domains)
    n = len(col_domains)
    full_row_mask = (1 << m) - 1
    full_col_mask = (1 << n) - 1

    while True:
        changed = False

        # From column domains, derive forced / forbidden bits in each row.
        row_required_ones = [0] * m
        row_forbidden_ones = [0] * m

        for c in range(n):
            dom = col_domains[c]
            if not dom:
                return None
            any_ones, all_ones = line_any_all(dom, full_row_mask)
            bit_c = 1 << c
            for r in range(m):
                bit_r = 1 << r
                if all_ones & bit_r:
                    row_required_ones[r] |= bit_c
                elif not (any_ones & bit_r):
                    row_forbidden_ones[r] |= bit_c

        new_row_domains = []
        for r in range(m):
            dom = row_domains[r]
            if not dom:
                return None
            req = row_required_ones[r]
            forbid = row_forbidden_ones[r]
            filtered = tuple(mask for mask in dom if (mask & req) == req and (mask & forbid) == 0)
            if not filtered:
                return None
            if len(filtered) != len(dom):
                changed = True
            new_row_domains.append(filtered)
        row_domains = new_row_domains

        # From row domains, derive forced / forbidden bits in each column.
        col_required_ones = [0] * n
        col_forbidden_ones = [0] * n

        for r in range(m):
            dom = row_domains[r]
            if not dom:
                return None
            any_ones, all_ones = line_any_all(dom, full_col_mask)
            bit_r = 1 << r
            for c in range(n):
                bit_c = 1 << c
                if all_ones & bit_c:
                    col_required_ones[c] |= bit_r
                elif not (any_ones & bit_c):
                    col_forbidden_ones[c] |= bit_r

        new_col_domains = []
        for c in range(n):
            dom = col_domains[c]
            if not dom:
                return None
            req = col_required_ones[c]
            forbid = col_forbidden_ones[c]
            filtered = tuple(mask for mask in dom if (mask & req) == req and (mask & forbid) == 0)
            if not filtered:
                return None
            if len(filtered) != len(dom):
                changed = True
            new_col_domains.append(filtered)
        col_domains = new_col_domains

        if not changed:
            return row_domains, col_domains


def choose_branch(row_domains, col_domains):
    # Most constrained line first.
    best_kind = None
    best_idx = -1
    best_size = 10**18

    for r, dom in enumerate(row_domains):
        size = len(dom)
        if 1 < size < best_size:
            best_kind = 'row'
            best_idx = r
            best_size = size

    for c, dom in enumerate(col_domains):
        size = len(dom)
        if 1 < size < best_size:
            best_kind = 'col'
            best_idx = c
            best_size = size

    return best_kind, best_idx


def order_row_values(r, row_domains, col_domains):
    # Prefer values that immediately agree more strongly with current column domains.
    m = len(row_domains)
    n = len(col_domains)
    full_row_mask = (1 << m) - 1

    col_any = [0] * n
    col_all = [0] * n
    for c in range(n):
        any_ones, all_ones = line_any_all(col_domains[c], full_row_mask)
        col_any[c] = any_ones
        col_all[c] = all_ones

    scored = []
    bit_r = 1 << r
    for mask in row_domains[r]:
        score = 0
        for c in range(n):
            bit_c = 1 << c
            val = 1 if (mask & bit_c) else 0
            if val == 1:
                if col_all[c] & bit_r:
                    score += 3
                elif col_any[c] & bit_r:
                    score += 1
            else:
                if not (col_any[c] & bit_r):
                    score += 3
                elif not (col_all[c] & bit_r):
                    score += 1
        scored.append((-score, mask))
    scored.sort()
    return [mask for _, mask in scored]


def order_col_values(c, row_domains, col_domains):
    # Symmetric ordering heuristic for column branching.
    m = len(row_domains)
    n = len(col_domains)
    full_col_mask = (1 << n) - 1

    row_any = [0] * m
    row_all = [0] * m
    for r in range(m):
        any_ones, all_ones = line_any_all(row_domains[r], full_col_mask)
        row_any[r] = any_ones
        row_all[r] = all_ones

    scored = []
    bit_c = 1 << c
    for mask in col_domains[c]:
        score = 0
        for r in range(m):
            bit_r = 1 << r
            val = 1 if (mask & bit_r) else 0
            if val == 1:
                if row_all[r] & bit_c:
                    score += 3
                elif row_any[r] & bit_c:
                    score += 1
            else:
                if not (row_any[r] & bit_c):
                    score += 3
                elif not (row_all[r] & bit_c):
                    score += 1
        scored.append((-score, mask))
    scored.sort()
    return [mask for _, mask in scored]


def search(row_domains, col_domains):
    propagated = propagate(row_domains, col_domains)
    if propagated is None:
        return None
    row_domains, col_domains = propagated

    if all(len(dom) == 1 for dom in row_domains) and all(len(dom) == 1 for dom in col_domains):
        return row_domains, col_domains

    kind, idx = choose_branch(row_domains, col_domains)
    if kind is None:
        return row_domains, col_domains

    if kind == 'row':
        for mask in order_row_values(idx, row_domains, col_domains):
            new_row_domains = list(row_domains)
            new_row_domains[idx] = (mask,)
            result = search(new_row_domains, col_domains)
            if result is not None:
                return result
    else:
        for mask in order_col_values(idx, row_domains, col_domains):
            new_col_domains = list(col_domains)
            new_col_domains[idx] = (mask,)
            result = search(row_domains, new_col_domains)
            if result is not None:
                return result

    return None


def build_grid(row_domains, n):
    grid = []
    for dom in row_domains:
        mask = dom[0]
        row = ['B' if (mask >> c) & 1 else None for c in range(n)]
        grid.append(row)
    return grid


def verify_solution(grid, observation):
    m = len(grid)
    n = len(grid[0]) if m else 0
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    for r in range(m):
        total = 0
        for c in range(n):
            if grid[r][c] == 'B':
                total += c + 1
        if total != row_targets[r]:
            return False

    for c in range(n):
        total = 0
        for r in range(m):
            if grid[r][c] == 'B':
                total += r + 1
        if total != col_targets[c]:
            return False

    return True


def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    m = len(row_targets)
    n = len(col_targets)

    # Immediate feasibility checks from subset sums.
    row_domains = []
    for target in row_targets:
        dom = subset_masks(n, target)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for target in col_targets:
        dom = subset_masks(m, target)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    result = search(row_domains, col_domains)
    if result is None:
        return "No Solution"

    final_row_domains, final_col_domains = result
    grid = build_grid(final_row_domains, n)

    if not verify_solution(grid, observation):
        return "No Solution"

    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

