from collections import deque


class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0] * n

    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return
        if self.r[a] < self.r[b]:
            a, b = b, a
        self.p[b] = a
        if self.r[a] == self.r[b]:
            self.r[a] += 1


class SlitherlinkSolver:
    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.vcount = (self.n + 1) * (self.n + 1)

        self.edge_ends = []
        self.edge_cells = []
        self.vertex_edges = [[] for _ in range(self.vcount)]
        self.cell_edges = []
        self.cell_clues = []

        self.h = [[None] * self.n for _ in range(self.n + 1)]
        self.v = [[None] * (self.n + 1) for _ in range(self.n)]

        self._build_edges_and_cells()

        self.ecount = len(self.edge_ends)
        self.state = [-1] * self.ecount
        self.trail = []

        self.q_cells = deque()
        self.q_verts = deque()
        self.in_q_cell = [False] * (self.n * self.n)
        self.in_q_vert = [False] * self.vcount

        self.cell_masks = {k: [m for m in range(16) if m.bit_count() == k] for k in range(4)}
        self.vertex_masks = {d: [m for m in range(1 << d) if m.bit_count() in (0, 2)] for d in range(5)}

        self.edge_tightness = [0] * self.ecount
        for e in range(self.ecount):
            score = 0
            for ci in self.edge_cells[e]:
                if ci is not None and self.cell_clues[ci] is not None:
                    score += 3
            u, v = self.edge_ends[e]
            score += len(self.vertex_edges[u]) + len(self.vertex_edges[v])
            self.edge_tightness[e] = score

    def vid(self, r, c):
        return r * (self.n + 1) + c

    def _add_edge(self, u, v):
        idx = len(self.edge_ends)
        self.edge_ends.append((u, v))
        self.edge_cells.append([None, None])
        self.vertex_edges[u].append(idx)
        self.vertex_edges[v].append(idx)
        return idx

    def _build_edges_and_cells(self):
        for r in range(self.n + 1):
            for c in range(self.n):
                self.h[r][c] = self._add_edge(self.vid(r, c), self.vid(r, c + 1))
        for r in range(self.n):
            for c in range(self.n + 1):
                self.v[r][c] = self._add_edge(self.vid(r, c), self.vid(r + 1, c))

        for r in range(self.n):
            for c in range(self.n):
                top = self.h[r][c]
                right = self.v[r][c + 1]
                bottom = self.h[r + 1][c]
                left = self.v[r][c]
                ci = len(self.cell_edges)
                self.cell_edges.append([top, right, bottom, left])
                self.cell_clues.append(self.data[r][c])

                for e in (top, right, bottom, left):
                    slots = self.edge_cells[e]
                    if slots[0] is None:
                        slots[0] = ci
                    else:
                        slots[1] = ci

    def reset_queues(self):
        self.q_cells = deque()
        self.q_verts = deque()
        self.in_q_cell = [False] * (self.n * self.n)
        self.in_q_vert = [False] * self.vcount
        for ci, clue in enumerate(self.cell_clues):
            if clue is not None:
                self.enqueue_cell(ci)
        for vi in range(self.vcount):
            self.enqueue_vert(vi)

    def enqueue_cell(self, ci):
        if not self.in_q_cell[ci]:
            self.in_q_cell[ci] = True
            self.q_cells.append(ci)

    def enqueue_vert(self, vi):
        if not self.in_q_vert[vi]:
            self.in_q_vert[vi] = True
            self.q_verts.append(vi)

    def assign(self, e, val):
        cur = self.state[e]
        if cur != -1:
            return cur == val
        self.state[e] = val
        self.trail.append(e)
        for ci in self.edge_cells[e]:
            if ci is not None and self.cell_clues[ci] is not None:
                self.enqueue_cell(ci)
        u, v = self.edge_ends[e]
        self.enqueue_vert(u)
        self.enqueue_vert(v)
        return True

    def undo(self, mark):
        while len(self.trail) > mark:
            e = self.trail.pop()
            self.state[e] = -1
        self.reset_queues()

    def _filtered_cell_masks(self, ci):
        clue = self.cell_clues[ci]
        edges = self.cell_edges[ci]
        valid = []
        for m in self.cell_masks[clue]:
            ok = True
            for i, e in enumerate(edges):
                s = self.state[e]
                if s != -1 and s != ((m >> i) & 1):
                    ok = False
                    break
            if ok:
                valid.append(m)
        return valid

    def _filtered_vertex_masks(self, vi):
        edges = self.vertex_edges[vi]
        d = len(edges)
        valid = []
        for m in self.vertex_masks[d]:
            ok = True
            for i, e in enumerate(edges):
                s = self.state[e]
                if s != -1 and s != ((m >> i) & 1):
                    ok = False
                    break
            if ok:
                valid.append(m)
        return valid

    def process_cell(self, ci):
        valid = self._filtered_cell_masks(ci)
        if not valid:
            return False
        edges = self.cell_edges[ci]
        for i, e in enumerate(edges):
            if self.state[e] != -1:
                continue
            b = (valid[0] >> i) & 1
            if all(((m >> i) & 1) == b for m in valid):
                if not self.assign(e, b):
                    return False
        return True

    def process_vertex(self, vi):
        valid = self._filtered_vertex_masks(vi)
        if not valid:
            return False
        edges = self.vertex_edges[vi]
        for i, e in enumerate(edges):
            if self.state[e] != -1:
                continue
            b = (valid[0] >> i) & 1
            if all(((m >> i) & 1) == b for m in valid):
                if not self.assign(e, b):
                    return False
        return True

    def _degree_on(self):
        deg = [0] * self.vcount
        for e, s in enumerate(self.state):
            if s == 1:
                u, v = self.edge_ends[e]
                deg[u] += 1
                deg[v] += 1
        return deg

    def all_clues_exact_now(self):
        for ci, clue in enumerate(self.cell_clues):
            if clue is None:
                continue
            cnt = 0
            for e in self.cell_edges[ci]:
                if self.state[e] == 1:
                    cnt += 1
            if cnt != clue:
                return False
        return True

    def global_checks(self):
        deg = self._degree_on()
        on_vertices = [vi for vi, d in enumerate(deg) if d > 0]

        if on_vertices:
            dsu = DSU(self.vcount)
            for e, s in enumerate(self.state):
                if s != 0:
                    u, v = self.edge_ends[e]
                    dsu.union(u, v)
            root = dsu.find(on_vertices[0])
            for vi in on_vertices[1:]:
                if dsu.find(vi) != root:
                    return False

        if on_vertices:
            adj = [[] for _ in range(self.vcount)]
            for e, s in enumerate(self.state):
                if s == 1:
                    u, v = self.edge_ends[e]
                    adj[u].append(v)
                    adj[v].append(u)

            seen = set()
            total_on_vertex_set = set(on_vertices)
            for start in on_vertices:
                if start in seen:
                    continue
                stack = [start]
                comp = []
                seen.add(start)
                while stack:
                    x = stack.pop()
                    comp.append(x)
                    for y in adj[x]:
                        if y not in seen:
                            seen.add(y)
                            stack.append(y)

                if comp and all(deg[v] == 2 for v in comp):
                    if set(comp) != total_on_vertex_set:
                        return False
                    if not self.all_clues_exact_now():
                        return False

        return True

    def propagate(self):
        while self.q_cells or self.q_verts:
            while self.q_cells:
                ci = self.q_cells.popleft()
                self.in_q_cell[ci] = False
                if not self.process_cell(ci):
                    return False
            while self.q_verts:
                vi = self.q_verts.popleft()
                self.in_q_vert[vi] = False
                if not self.process_vertex(vi):
                    return False
        return self.global_checks()

    def is_complete(self):
        if any(s == -1 for s in self.state):
            return False

        for ci, clue in enumerate(self.cell_clues):
            if clue is None:
                continue
            if sum(1 for e in self.cell_edges[ci] if self.state[e] == 1) != clue:
                return False

        deg = self._degree_on()
        used = [vi for vi, d in enumerate(deg) if d > 0]
        if not used:
            return False
        if any(d not in (0, 2) for d in deg):
            return False

        adj = [[] for _ in range(self.vcount)]
        for e, s in enumerate(self.state):
            if s == 1:
                u, v = self.edge_ends[e]
                adj[u].append(v)
                adj[v].append(u)

        seen = set()
        stack = [used[0]]
        seen.add(used[0])
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return len(seen) == len(used)

    def would_close_cycle(self, e):
        u, v = self.edge_ends[e]
        adj = [[] for _ in range(self.vcount)]
        has_on = False
        for i, s in enumerate(self.state):
            if s == 1:
                has_on = True
                a, b = self.edge_ends[i]
                adj[a].append(b)
                adj[b].append(a)
        if not has_on:
            return False
        stack = [u]
        seen = {u}
        while stack:
            x = stack.pop()
            if x == v:
                return True
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return False

    def choose_branch(self):
        best = None
        best_edge = None
        prefer = 1

        for ci, clue in enumerate(self.cell_clues):
            if clue is None:
                continue
            edges = self.cell_edges[ci]
            if not any(self.state[e] == -1 for e in edges):
                continue
            valid = self._filtered_cell_masks(ci)
            if len(valid) <= 1:
                continue
            mcount = len(valid)
            for i, e in enumerate(edges):
                if self.state[e] != -1:
                    continue
                ones = sum((m >> i) & 1 for m in valid)
                zeros = mcount - ones
                if ones == 0 or zeros == 0:
                    continue
                score = (mcount, min(ones, zeros), -abs(ones - zeros), -self.edge_tightness[e], e)
                if best is None or score < best:
                    best = score
                    best_edge = e
                    prefer = 1 if ones > zeros else 0

        for vi in range(self.vcount):
            edges = self.vertex_edges[vi]
            if not any(self.state[e] == -1 for e in edges):
                continue
            valid = self._filtered_vertex_masks(vi)
            if len(valid) <= 1:
                continue
            mcount = len(valid)
            for i, e in enumerate(edges):
                if self.state[e] != -1:
                    continue
                ones = sum((m >> i) & 1 for m in valid)
                zeros = mcount - ones
                if ones == 0 or zeros == 0:
                    continue
                score = (mcount, min(ones, zeros), -abs(ones - zeros), -self.edge_tightness[e], e)
                if best is None or score < best:
                    best = score
                    best_edge = e
                    prefer = 1 if ones > zeros else 0

        if best_edge is None:
            unknown = [e for e, s in enumerate(self.state) if s == -1]
            if not unknown:
                return None, None
            best_edge = max(unknown, key=lambda e: (self.edge_tightness[e], -e))
            prefer = 1

        if prefer == 1 and self.would_close_cycle(best_edge) and not self.all_clues_exact_now():
            prefer = 0

        return best_edge, prefer

    def dfs(self):
        if not self.propagate():
            return False
        if self.is_complete():
            return True

        e, prefer = self.choose_branch()
        if e is None:
            return False

        for val in (prefer, 1 - prefer):
            mark = len(self.trail)
            if self.assign(e, val):
                if self.dfs():
                    return True
            self.undo(mark)
        return False

    def extract_loop(self):
        adj = {}
        for e, s in enumerate(self.state):
            if s == 1:
                u, v = self.edge_ends[e]
                ur, uc = divmod(u, self.n + 1)
                vr, vc = divmod(v, self.n + 1)
                a = (ur, uc)
                b = (vr, vc)
                adj.setdefault(a, []).append(b)
                adj.setdefault(b, []).append(a)

        if not adj:
            return None

        start = min(adj)
        path = [start]
        prev = None
        cur = start

        while True:
            nbrs = adj[cur]
            if prev is None:
                nxt = min(nbrs)
            else:
                nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break

        return path


def solve(observation):
    data = observation.get('data')
    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    solver = SlitherlinkSolver(data)
    solver.reset_queues()
    if not solver.dfs():
        return "No Solution"

    loop = solver.extract_loop()
    if not loop:
        return "No Solution"
    return str(loop)


if __name__ == "__main__":
    print(solve(OBSERVATION))

