from collections import deque
from itertools import combinations
import sys


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation.get("data")
    unit = observation.get("unit")

    if not isinstance(data, list) or not data:
        return "No Solution"

    br, bc = _parse_unit(unit)
    n = br * bc
    nn = n * n

    if len(data) != n or any(len(row) != n for row in data):
        return "No Solution"

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    boxes = []
    for rb in range(0, n, br):
        for cb in range(0, n, bc):
            box = []
            for r in range(rb, rb + br):
                for c in range(cb, cb + bc):
                    box.append(r * n + c)
            boxes.append(box)

    all_units = rows + cols + boxes

    row_of = [i // n for i in range(nn)]
    col_of = [i % n for i in range(nn)]
    box_of = [0] * nn
    for b_idx, box in enumerate(boxes):
        for cell in box:
            box_of[cell] = b_idx

    peers = []
    for cell in range(nn):
        s = set(rows[row_of[cell]]) | set(cols[col_of[cell]]) | set(boxes[box_of[cell]])
        s.remove(cell)
        peers.append(tuple(s))

    full_mask = (1 << n) - 1

    state = [full_mask] * nn
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            idx = r * n + c
            if v is None:
                continue
            if not isinstance(v, int) or v < 1 or v > n:
                return "No Solution"
            state[idx] = 1 << (v - 1)

    solver = _SudokuEngine(
        n=n,
        br=br,
        bc=bc,
        rows=rows,
        cols=cols,
        boxes=boxes,
        all_units=all_units,
        row_of=row_of,
        col_of=col_of,
        box_of=box_of,
        peers=peers,
        full_mask=full_mask,
    )

    solved = solver.search(state)
    if solved is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            m = solved[r * n + c]
            if not _is_single(m):
                return "No Solution"
            row.append(_bit_to_value(m))
        grid.append(row)
    return repr(grid)


def _parse_unit(unit):
    if isinstance(unit, str) and "x" in unit:
        a, b = unit.lower().split("x", 1)
        return int(a), int(b)
    k = int(unit)
    return k, k


def _is_single(mask):
    return mask != 0 and (mask & (mask - 1)) == 0


def _bit_to_value(mask):
    return mask.bit_length()


def _iter_bits(mask):
    while mask:
        b = mask & -mask
        yield b
        mask ^= b


class _SudokuEngine:
    def __init__(self, n, br, bc, rows, cols, boxes, all_units, row_of, col_of, box_of, peers, full_mask):
        self.n = n
        self.br = br
        self.bc = bc
        self.rows = rows
        self.cols = cols
        self.boxes = boxes
        self.all_units = all_units
        self.row_of = row_of
        self.col_of = col_of
        self.box_of = box_of
        self.peers = peers
        self.full_mask = full_mask
        self.max_subset = 3 if n <= 12 else 4

    def search(self, state):
        state = state[:]
        if not self.propagate(state):
            return None
        if all(_is_single(m) for m in state):
            return state

        cell = self.select_branch_cell(state)
        if cell is None:
            return None

        values = self.ordered_candidates(state, cell)
        for bit in values:
            nxt = state[:]
            nxt[cell] = bit
            solved = self.search(nxt)
            if solved is not None:
                return solved
        return None

    def propagate(self, state):
        processed_single = [0] * (self.n * self.n)
        queue = deque(i for i, m in enumerate(state) if _is_single(m))

        if not self._propagate_singles(state, queue, processed_single):
            return False

        while True:
            ok, changed = self._hidden_singles(state, queue)
            if not ok:
                return False
            if changed:
                if not self._propagate_singles(state, queue, processed_single):
                    return False
                continue

            ok, changed = self._locked_candidates(state, queue)
            if not ok:
                return False
            if changed:
                if not self._propagate_singles(state, queue, processed_single):
                    return False
                continue

            ok, changed = self._naked_subsets(state, queue)
            if not ok:
                return False
            if changed:
                if not self._propagate_singles(state, queue, processed_single):
                    return False
                continue

            ok, changed = self._hidden_subsets(state, queue)
            if not ok:
                return False
            if changed:
                if not self._propagate_singles(state, queue, processed_single):
                    return False
                continue

            break

        return self._final_consistency_check(state)

    def select_branch_cell(self, state):
        best = None
        best_key = None
        for cell, mask in enumerate(state):
            cnt = mask.bit_count()
            if cnt <= 1:
                continue
            impact = sum(1 for p in self.peers[cell] if not _is_single(state[p]))
            key = (cnt, -impact, cell)
            if best_key is None or key < best_key:
                best_key = key
                best = cell
        return best

    def ordered_candidates(self, state, cell):
        vals = []
        for bit in _iter_bits(state[cell]):
            score = 0
            for p in self.peers[cell]:
                if state[p] & bit:
                    score += 1
            vals.append((score, bit))
        vals.sort()
        return [bit for _, bit in vals]

    def _propagate_singles(self, state, queue, processed_single):
        while queue:
            cell = queue.popleft()
            mask = state[cell]
            if not _is_single(mask):
                continue
            if processed_single[cell] == mask:
                continue
            processed_single[cell] = mask

            for p in self.peers[cell]:
                if state[p] & mask:
                    new_mask = state[p] & ~mask
                    if new_mask == 0:
                        return False
                    if new_mask != state[p]:
                        state[p] = new_mask
                        if _is_single(new_mask):
                            queue.append(p)
        return True

    def _eliminate(self, state, cell, remove_mask, queue):
        if remove_mask == 0:
            return True, False
        old = state[cell]
        new = old & ~remove_mask
        if new == old:
            return True, False
        if new == 0:
            return False, False
        state[cell] = new
        if _is_single(new):
            queue.append(cell)
        return True, True

    def _force(self, state, cell, keep_mask, queue):
        old = state[cell]
        if (old & keep_mask) == 0:
            return False, False
        if old == keep_mask:
            return True, False
        state[cell] = keep_mask
        queue.append(cell)
        return True, True

    def _hidden_singles(self, state, queue):
        changed = False
        for unit in self.all_units:
            counts = [0] * self.n
            last_cell = [-1] * self.n
            for cell in unit:
                m = state[cell]
                x = m
                while x:
                    b = x & -x
                    d = b.bit_length() - 1
                    counts[d] += 1
                    last_cell[d] = cell
                    x ^= b
            for d in range(self.n):
                if counts[d] == 0:
                    return False, False
                if counts[d] == 1:
                    ok, ch = self._force(state, last_cell[d], 1 << d, queue)
                    if not ok:
                        return False, False
                    changed |= ch
        return True, changed

    def _locked_candidates(self, state, queue):
        changed = False

        for b_idx, box in enumerate(self.boxes):
            for d in range(self.n):
                bit = 1 << d
                cells = [cell for cell in box if state[cell] & bit]
                if not cells:
                    return False, False
                if len(cells) <= 1:
                    continue

                r0 = self.row_of[cells[0]]
                if all(self.row_of[cell] == r0 for cell in cells):
                    for cell in self.rows[r0]:
                        if self.box_of[cell] != b_idx:
                            ok, ch = self._eliminate(state, cell, bit, queue)
                            if not ok:
                                return False, False
                            changed |= ch

                c0 = self.col_of[cells[0]]
                if all(self.col_of[cell] == c0 for cell in cells):
                    for cell in self.cols[c0]:
                        if self.box_of[cell] != b_idx:
                            ok, ch = self._eliminate(state, cell, bit, queue)
                            if not ok:
                                return False, False
                            changed |= ch

        for r, row in enumerate(self.rows):
            for d in range(self.n):
                bit = 1 << d
                cells = [cell for cell in row if state[cell] & bit]
                if not cells:
                    return False, False
                if len(cells) <= 1:
                    continue
                b0 = self.box_of[cells[0]]
                if all(self.box_of[cell] == b0 for cell in cells):
                    for cell in self.boxes[b0]:
                        if self.row_of[cell] != r:
                            ok, ch = self._eliminate(state, cell, bit, queue)
                            if not ok:
                                return False, False
                            changed |= ch

        for c, col in enumerate(self.cols):
            for d in range(self.n):
                bit = 1 << d
                cells = [cell for cell in col if state[cell] & bit]
                if not cells:
                    return False, False
                if len(cells) <= 1:
                    continue
                b0 = self.box_of[cells[0]]
                if all(self.box_of[cell] == b0 for cell in cells):
                    for cell in self.boxes[b0]:
                        if self.col_of[cell] != c:
                            ok, ch = self._eliminate(state, cell, bit, queue)
                            if not ok:
                                return False, False
                            changed |= ch

        return True, changed

    def _naked_subsets(self, state, queue):
        changed = False
        max_k = min(self.max_subset, self.n - 1)

        for unit in self.all_units:
            candidates = [cell for cell in unit if 2 <= state[cell].bit_count() <= max_k]
            if len(candidates) < 2:
                continue

            for k in range(2, max_k + 1):
                if len(candidates) < k:
                    break
                seen_unions = set()

                for combo in combinations(candidates, k):
                    union = 0
                    valid = True
                    for cell in combo:
                        union |= state[cell]
                        if union.bit_count() > k:
                            valid = False
                            break
                    if not valid or union.bit_count() != k or union in seen_unions:
                        continue
                    seen_unions.add(union)

                    subset_cells = []
                    for cell in unit:
                        if (state[cell] & ~union) == 0:
                            subset_cells.append(cell)

                    if len(subset_cells) != k:
                        continue

                    subset_set = set(subset_cells)
                    for cell in unit:
                        if cell not in subset_set:
                            ok, ch = self._eliminate(state, cell, union, queue)
                            if not ok:
                                return False, False
                            changed |= ch

        return True, changed

    def _hidden_subsets(self, state, queue):
        changed = False
        max_k = min(self.max_subset, self.n - 1)

        for unit in self.all_units:
            pos_masks = [0] * self.n
            for pos, cell in enumerate(unit):
                m = state[cell]
                x = m
                while x:
                    b = x & -x
                    d = b.bit_length() - 1
                    pos_masks[d] |= 1 << pos
                    x ^= b

            useful_digits = [d for d in range(self.n) if 2 <= pos_masks[d].bit_count() <= max_k]
            for k in range(2, max_k + 1):
                if len(useful_digits) < k:
                    break
                seen_pos = set()

                for combo in combinations(useful_digits, k):
                    pos_union = 0
                    valid = True
                    allow_mask = 0
                    for d in combo:
                        pos_union |= pos_masks[d]
                        allow_mask |= 1 << d
                        if pos_union.bit_count() > k:
                            valid = False
                            break
                    if not valid or pos_union.bit_count() != k or pos_union in seen_pos:
                        continue
                    seen_pos.add(pos_union)

                    pu = pos_union
                    while pu:
                        bitpos = pu & -pu
                        pos = bitpos.bit_length() - 1
                        cell = unit[pos]
                        remove = state[cell] & ~allow_mask
                        ok, ch = self._eliminate(state, cell, remove, queue)
                        if not ok:
                            return False, False
                        changed |= ch
                        pu ^= bitpos

        return True, changed

    def _final_consistency_check(self, state):
        for mask in state:
            if mask == 0:
                return False

        for unit in self.all_units:
            seen_singles = 0
            union = 0
            for cell in unit:
                m = state[cell]
                union |= m
                if _is_single(m):
                    if seen_singles & m:
                        return False
                    seen_singles |= m
            if union != self.full_mask:
                return False

        return True


