from functools import lru_cache

def solve(observation):
    region = observation.get("region")
    row_clues = observation.get("row_stitch_counts")
    col_clues = observation.get("col_stitch_counts")

    if not region or not row_clues or not col_clues:
        return "No Solution"

    R = len(region)
    C = len(region[0])
    if any(len(row) != C for row in region):
        return "No Solution"
    if len(row_clues) != R or len(col_clues) != C:
        return "No Solution"
    if sum(row_clues) != sum(col_clues):
        return "No Solution"
    if any(x < 0 or x > C for x in row_clues):
        return "No Solution"
    if any(x < 0 or x > R for x in col_clues):
        return "No Solution"

    # Candidate stitches are orthogonally adjacent cells from different regions.
    # This turns the puzzle into a grid-matching CSP:
    # - A hole/cell is "used" iff one selected stitch touches it.
    # - Each used hole contributes 1 to its row clue and 1 to its column clue.
    # - No two stitches may share a hole => selected stitches form a matching.
    #
    # The solver works row-by-row:
    # - 'inmask' marks vertices in the current row already matched from above.
    # - For each row, enumerate all feasible combinations of:
    #     * horizontal stitches inside the row
    #     * downward stitches into the next row
    #   while exactly meeting the row clue and decrementing column remainders.
    # - Memoized DFS over rows gives strong pruning and good performance.

    allowed_h = [[False] * (C - 1) for _ in range(R)]
    allowed_v = [[False] * C for _ in range(R - 1)]
    for r in range(R):
        for c in range(C - 1):
            allowed_h[r][c] = region[r][c] != region[r][c + 1]
    for r in range(R - 1):
        for c in range(C):
            allowed_v[r][c] = region[r][c] != region[r + 1][c]

    row_suffix = [0] * (R + 1)
    for r in range(R - 1, -1, -1):
        row_suffix[r] = row_suffix[r + 1] + row_clues[r]

    @lru_cache(maxsize=None)
    def search_rows(r, inmask, col_rem):
        col_rem = list(col_rem)

        # Global consistency checks before expanding the row.
        if r > R:
            return None
        if sum(col_rem) != row_suffix[r]:
            return None
        rows_left = R - r
        for c in range(C):
            if col_rem[c] < 0 or col_rem[c] > rows_left:
                return None

        if r == R:
            if inmask == 0 and all(x == 0 for x in col_rem):
                return ()
            return None

        clue = row_clues[r]

        # Forced used cells from above.
        forced = inmask.bit_count()
        if forced > clue:
            return None

        # Enumerate all feasible patterns for this row.
        solutions = []

        def enum_row(c, outmask, used, cols_left, stitches):
            # Human-like row pruning:
            # - mandatory remaining from above cannot exceed clue
            # - even if every remaining position were used, clue must still be reachable
            mandatory_remaining = (inmask >> c).bit_count() if c < C else 0
            possible_remaining = C - c
            if used + mandatory_remaining > clue:
                return
            if used + possible_remaining < clue:
                return

            # Column feasibility with remaining future rows.
            future_rows = R - (r + 1)
            for cc in range(C):
                if cols_left[cc] < 0:
                    return
                if cols_left[cc] > future_rows + ((outmask >> cc) & 1):
                    # After this row, a column can still be used in each later row at most once.
                    return

            if c >= C:
                if used == clue:
                    rem_after = tuple(cols_left)
                    tail = search_rows(r + 1, outmask, rem_after)
                    if tail is not None:
                        solutions.append(tuple(stitches) + tail)
                return

            bit = (inmask >> c) & 1

            if bit:
                # Already matched from above: must count as used here.
                if cols_left[c] <= 0:
                    return
                cols_left[c] -= 1
                enum_row(c + 1, outmask, used + 1, cols_left, stitches)
                cols_left[c] += 1
                return

            # Option 1: leave unmatched.
            enum_row(c + 1, outmask, used, cols_left, stitches)

            # Option 2: horizontal stitch to the right.
            if c + 1 < C and ((inmask >> (c + 1)) & 1) == 0 and allowed_h[r][c]:
                if cols_left[c] > 0 and cols_left[c + 1] > 0:
                    cols_left[c] -= 1
                    cols_left[c + 1] -= 1
                    stitches.append(((r, c), (r, c + 1)))
                    enum_row(c + 2, outmask, used + 2, cols_left, stitches)
                    stitches.pop()
                    cols_left[c] += 1
                    cols_left[c + 1] += 1

            # Option 3: vertical stitch downward.
            if r + 1 < R and allowed_v[r][c] and cols_left[c] > 0:
                cols_left[c] -= 1
                stitches.append(((r, c), (r + 1, c)))
                enum_row(c + 1, outmask | (1 << c), used + 1, cols_left, stitches)
                stitches.pop()
                cols_left[c] += 1

        enum_row(0, 0, 0, col_rem[:], [])

        if not solutions:
            return None

        # Choose the lexicographically smallest solution for determinism.
        solutions.sort()
        return solutions[0]

    result = search_rows(0, 0, tuple(col_clues))
    if result is None:
        return "No Solution"

    answer = [[list(a), list(b)] for (a, b) in result]
    return repr(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

