# Consecutive Kropki-Latin solver.
# Strategy:
# 1) Build all feasible row patterns and all feasible column patterns.
#    Each pattern is a full permutation 1..N satisfying that line's clue cells and
#    its exact consecutive / non-consecutive adjacency relations.
# 2) Repeatedly cross-filter row patterns and column patterns through cell domains.
#    This mirrors human deduction: "these are the only row arrangements left", then
#    "therefore these cell values are possible", then columns shrink, and so on.
# 3) If deduction stalls, branch on the smallest unresolved row/column pattern set,
#    otherwise on the most constrained cell.

def solve(observation):
    data = observation.get("data")
    adjacent = observation.get("adjacent")
    if not isinstance(data, list) or not data:
        return "No Solution"
    N = len(data)
    if any(not isinstance(row, list) or len(row) != N for row in data):
        return "No Solution"

    ALL = (1 << N) - 1
    BIT = [0] + [1 << (v - 1) for v in range(1, N + 1)]

    adj_set = {(float(a), float(b)) for a, b in adjacent}

    # Exact relation grids:
    # True  -> there is a dot, so values must be consecutive.
    # False -> no dot, so values must NOT be consecutive.
    h_rel = [[(float(r), c + 0.5) in adj_set for c in range(N - 1)] for r in range(N)]
    v_rel = [[(r + 0.5, float(c)) in adj_set for r in range(N - 1)] for c in range(N)]

    # Basic value masks.
    consec_from = [0] * (N + 1)
    nonconsec_from = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v > 1:
            m |= BIT[v - 1]
        if v < N:
            m |= BIT[v + 1]
        consec_from[v] = m
        nonconsec_from[v] = ALL ^ m ^ BIT[v]

    # Initial cell domains from clues.
    domains0 = [ALL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= N):
                return "No Solution"
            domains0[r * N + c] = BIT[v]

    def generate_line_candidates(dom_masks, rels):
        # Generate all permutations consistent with:
        # - per-position domain masks
        # - exact adjacency relation between neighboring positions
        out = []
        cur = [0] * N

        def dfs(i, prev, remaining):
            if i == N:
                out.append(tuple(cur))
                return

            mask = dom_masks[i] & remaining
            if i > 0:
                mask &= consec_from[prev] if rels[i - 1] else nonconsec_from[prev]

            while mask:
                b = mask & -mask
                mask ^= b
                v = b.bit_length()

                # Cheap one-step lookahead.
                if i < N - 1:
                    nxt = dom_masks[i + 1] & (remaining ^ b)
                    nxt &= consec_from[v] if rels[i] else nonconsec_from[v]
                    if nxt == 0:
                        continue

                cur[i] = v
                dfs(i + 1, v, remaining ^ b)

        dfs(0, 0, ALL)
        return list(out)

    # Precompute feasible rows and columns from local constraints only.
    row_cands0 = []
    for r in range(N):
        dom_masks = [domains0[r * N + c] for c in range(N)]
        cands = generate_line_candidates(dom_masks, h_rel[r])
        if not cands:
            return "No Solution"
        row_cands0.append(cands)

    col_cands0 = []
    for c in range(N):
        dom_masks = [domains0[r * N + c] for r in range(N)]
        cands = generate_line_candidates(dom_masks, v_rel[c])
        if not cands:
            return "No Solution"
        col_cands0.append(cands)

    def is_singleton(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def mask_value(mask):
        return mask.bit_length()

    def propagate(domains, row_cands, col_cands):
        # Repeated fixed-point filtering between row-patterns, column-patterns,
        # and per-cell domains.
        while True:
            changed = False

            # Filter rows.
            for r in range(N):
                old = row_cands[r]
                if not old:
                    return None

                base = r * N
                new = []
                pos_masks = [0] * N

                for cand in old:
                    ok = True
                    for c, v in enumerate(cand):
                        if not (domains[base + c] & BIT[v]):
                            ok = False
                            break
                    if ok:
                        new.append(cand)
                        for c, v in enumerate(cand):
                            pos_masks[c] |= BIT[v]

                if not new:
                    return None
                if len(new) != len(old):
                    row_cands[r] = new
                    changed = True

                for c in range(N):
                    idx = base + c
                    nd = domains[idx] & pos_masks[c]
                    if nd == 0:
                        return None
                    if nd != domains[idx]:
                        domains[idx] = nd
                        changed = True

            # Filter columns.
            for c in range(N):
                old = col_cands[c]
                if not old:
                    return None

                new = []
                pos_masks = [0] * N

                for cand in old:
                    ok = True
                    for r, v in enumerate(cand):
                        if not (domains[r * N + c] & BIT[v]):
                            ok = False
                            break
                    if ok:
                        new.append(cand)
                        for r, v in enumerate(cand):
                            pos_masks[r] |= BIT[v]

                if not new:
                    return None
                if len(new) != len(old):
                    col_cands[c] = new
                    changed = True

                for r in range(N):
                    idx = r * N + c
                    nd = domains[idx] & pos_masks[r]
                    if nd == 0:
                        return None
                    if nd != domains[idx]:
                        domains[idx] = nd
                        changed = True

            if not changed:
                return domains, row_cands, col_cands

    def solved(domains):
        return all(is_singleton(d) for d in domains)

    def build_grid(domains):
        return [[mask_value(domains[r * N + c]) for c in range(N)] for r in range(N)]

    def verify(grid):
        target = set(range(1, N + 1))

        for r in range(N):
            if set(grid[r]) != target:
                return False
        for c in range(N):
            if {grid[r][c] for r in range(N)} != target:
                return False

        for r in range(N):
            for c in range(N - 1):
                cons = abs(grid[r][c] - grid[r][c + 1]) == 1
                if cons != h_rel[r][c]:
                    return False
        for c in range(N):
            for r in range(N - 1):
                cons = abs(grid[r][c] - grid[r + 1][c]) == 1
                if cons != v_rel[c][r]:
                    return False
        return True

    failed = set()

    def choose_branch(domains, row_cands, col_cands):
        # Prefer the smallest unresolved line (row/col candidate set).
        best_line = None
        best_len = 10 ** 9

        for r, cands in enumerate(row_cands):
            k = len(cands)
            if 1 < k < best_len:
                best_len = k
                best_line = ("row", r)
        for c, cands in enumerate(col_cands):
            k = len(cands)
            if 1 < k < best_len:
                best_len = k
                best_line = ("col", c)

        best_cell = None
        best_cell_len = 10 ** 9
        for i, d in enumerate(domains):
            k = d.bit_count()
            if 1 < k < best_cell_len:
                best_cell_len = k
                best_cell = i

        if best_line is not None and best_len <= best_cell_len:
            return best_line[0], best_line[1]
        return "cell", best_cell

    def ordered_cell_values(idx, domains, row_cands, col_cands):
        r, c = divmod(idx, N)
        row_freq = [0] * (N + 1)
        col_freq = [0] * (N + 1)

        for cand in row_cands[r]:
            row_freq[cand[c]] += 1
        for cand in col_cands[c]:
            col_freq[cand[r]] += 1

        vals = []
        mask = domains[idx]
        while mask:
            b = mask & -mask
            mask ^= b
            v = b.bit_length()
            score = row_freq[v] * col_freq[v]
            vals.append((score, v))
        vals.sort(reverse=True)
        return [v for _, v in vals]

    def ordered_row_candidates(r, row_cands, col_cands):
        options = row_cands[r]
        scored = []
        for cand in options:
            score = 0
            for c, v in enumerate(cand):
                cnt = 0
                for cc in col_cands[c]:
                    if cc[r] == v:
                        cnt += 1
                score += cnt
            scored.append((score, cand))
        scored.sort(reverse=True, key=lambda x: x[0])
        return [cand for _, cand in scored]

    def ordered_col_candidates(c, row_cands, col_cands):
        options = col_cands[c]
        scored = []
        for cand in options:
            score = 0
            for r, v in enumerate(cand):
                cnt = 0
                for rr in row_cands[r]:
                    if rr[c] == v:
                        cnt += 1
                score += cnt
            scored.append((score, cand))
        scored.sort(reverse=True, key=lambda x: x[0])
        return [cand for _, cand in scored]

    def search(domains, row_cands, col_cands):
        state = propagate(domains, row_cands, col_cands)
        if state is None:
            return None

        domains, row_cands, col_cands = state
        key = tuple(domains)
        if key in failed:
            return None

        if solved(domains):
            grid = build_grid(domains)
            if verify(grid):
                return grid
            failed.add(key)
            return None

        kind, idx = choose_branch(domains, row_cands, col_cands)

        if kind == "row":
            r = idx
            for cand in ordered_row_candidates(r, row_cands, col_cands):
                new_domains = domains[:]
                base = r * N
                ok = True
                for c, v in enumerate(cand):
                    b = BIT[v]
                    if not (new_domains[base + c] & b):
                        ok = False
                        break
                    new_domains[base + c] = b
                if not ok:
                    continue
                new_rows = row_cands[:]
                new_cols = col_cands[:]
                new_rows[r] = [cand]
                ans = search(new_domains, new_rows, new_cols)
                if ans is not None:
                    return ans

        elif kind == "col":
            c = idx
            for cand in ordered_col_candidates(c, row_cands, col_cands):
                new_domains = domains[:]
                ok = True
                for r, v in enumerate(cand):
                    b = BIT[v]
                    cell = r * N + c
                    if not (new_domains[cell] & b):
                        ok = False
                        break
                    new_domains[cell] = b
                if not ok:
                    continue
                new_rows = row_cands[:]
                new_cols = col_cands[:]
                new_cols[c] = [cand]
                ans = search(new_domains, new_rows, new_cols)
                if ans is not None:
                    return ans

        else:
            for v in ordered_cell_values(idx, domains, row_cands, col_cands):
                new_domains = domains[:]
                new_domains[idx] = BIT[v]
                ans = search(new_domains, row_cands[:], col_cands[:])
                if ans is not None:
                    return ans

        failed.add(key)
        return None

    result = search(domains0[:], row_cands0[:], col_cands0[:])
    if result is None:
        return "No Solution"
    return str(result)


