OBSERVATION = {'data': [[None, 'B', 'B', 'W', 'W', None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, 'W', 'W', 'B', 'B', None]], 'horizontal': {'(1,2.5)': '='}, 'vertical': {'(0.5,5)': 'x', '(2.5,2)': 'x', '(2.5,4)': '=', '(2.5,5)': '=', '(3.5,0)': 'x', '(4.5,0)': 'x'}}

import ast

B = 1
W = 2
BW = B | W
MASK_TO_CHAR = {B: 'B', W: 'W'}
TRIPLE_PATTERNS = (
    (0, 0, 1),
    (0, 1, 0),
    (0, 1, 1),
    (1, 0, 0),
    (1, 0, 1),
    (1, 1, 0),
)


def parse_coord(key):
    if isinstance(key, str):
        a, b = ast.literal_eval(key)
    else:
        a, b = key
    return float(a), float(b)


def color_mask_from_bit(bit):
    return B if bit else W


def is_single(mask):
    return mask == B or mask == W


def mask_to_bit(mask):
    return 1 if mask == B else 0


def clone_domains(domains):
    return [row[:] for row in domains]


def precompute_patterns(length):
    half = length // 2
    out = []

    def dfs(i, last1, last2, count_b, bits):
        if i == length:
            if count_b == half:
                out.append(bits)
            return

        for bit in (0, 1):
            nb = count_b + bit
            if nb > half:
                continue
            rem = length - i - 1
            if nb + rem < half:
                continue
            if i >= 2 and last1 == last2 == bit:
                continue
            dfs(i + 1, last2, bit, nb, bits | (bit << i))

    dfs(0, -1, -2, 0, 0)
    return tuple(out)


def filter_line(patterns, masks, relations):
    length = len(masks)
    cands = []
    union = [0] * length

    for p in patterns:
        ok = True

        for i, m in enumerate(masks):
            col = B if ((p >> i) & 1) else W
            if not (m & col):
                ok = False
                break
        if not ok:
            continue

        for i, rel in enumerate(relations):
            if rel is None:
                continue
            a = (p >> i) & 1
            b = (p >> (i + 1)) & 1
            if rel == '=':
                if a != b:
                    ok = False
                    break
            else:
                if a == b:
                    ok = False
                    break
        if not ok:
            continue

        cands.append(p)
        for i in range(length):
            union[i] |= B if ((p >> i) & 1) else W

    return cands, union


def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0

    if rows == 0 or cols == 0:
        return "No Solution"
    if cols % 2 != 0 or rows % 2 != 0:
        return "No Solution"

    domains = []
    for r in range(rows):
        row = []
        for c in range(cols):
            v = data[r][c]
            if v == 'B':
                row.append(B)
            elif v == 'W':
                row.append(W)
            else:
                row.append(BW)
        domains.append(row)

    row_rels = [[None] * (cols - 1) for _ in range(rows)]
    col_rels = [[None] * (rows - 1) for _ in range(cols)]
    pair_constraints = []

    for k, rel in observation.get('horizontal', {}).items():
        rr, cc = parse_coord(k)
        r = int(round(rr))
        c = int(cc // 1)
        row_rels[r][c] = rel
        pair_constraints.append((r, c, r, c + 1, rel))

    for k, rel in observation.get('vertical', {}).items():
        rr, cc = parse_coord(k)
        r = int(rr // 1)
        c = int(round(cc))
        col_rels[c][r] = rel
        pair_constraints.append((r, c, r + 1, c, rel))

    patterns_cache = {}
    patterns_cache[cols] = precompute_patterns(cols)
    patterns_cache[rows] = precompute_patterns(rows)
    row_patterns = patterns_cache[cols]
    col_patterns = patterns_cache[rows]

    degree = [[0] * cols for _ in range(rows)]
    for r1, c1, r2, c2, _ in pair_constraints:
        degree[r1][c1] += 1
        degree[r2][c2] += 1

    def assign_cell(ds, r, c, new_mask):
        old = ds[r][c]
        nm = old & new_mask
        if nm == 0:
            return None
        if nm != old:
            ds[r][c] = nm
            return True
        return False

    def apply_pair_rules(ds):
        changed = False
        for r1, c1, r2, c2, rel in pair_constraints:
            d1 = ds[r1][c1]
            d2 = ds[r2][c2]

            if rel == '=':
                nd = d1 & d2
                if nd == 0:
                    return None
                if d1 != nd:
                    ds[r1][c1] = nd
                    changed = True
                if d2 != nd:
                    ds[r2][c2] = nd
                    changed = True
            else:
                allow1 = 0
                if d2 & B:
                    allow1 |= W
                if d2 & W:
                    allow1 |= B
                allow2 = 0
                if d1 & B:
                    allow2 |= W
                if d1 & W:
                    allow2 |= B

                nd1 = d1 & allow1
                nd2 = d2 & allow2
                if nd1 == 0 or nd2 == 0:
                    return None
                if nd1 != d1:
                    ds[r1][c1] = nd1
                    changed = True
                if nd2 != d2:
                    ds[r2][c2] = nd2
                    changed = True
        return changed

    def apply_triple_rules(ds):
        changed = False

        for r in range(rows):
            for c in range(cols - 2):
                masks = [ds[r][c], ds[r][c + 1], ds[r][c + 2]]
                union = [0, 0, 0]
                for pat in TRIPLE_PATTERNS:
                    cols3 = [color_mask_from_bit(pat[i]) for i in range(3)]
                    if all(masks[i] & cols3[i] for i in range(3)):
                        union[0] |= cols3[0]
                        union[1] |= cols3[1]
                        union[2] |= cols3[2]
                if 0 in union:
                    return None
                for i in range(3):
                    if union[i] != masks[i]:
                        ds[r][c + i] = union[i]
                        changed = True

        for c in range(cols):
            for r in range(rows - 2):
                masks = [ds[r][c], ds[r + 1][c], ds[r + 2][c]]
                union = [0, 0, 0]
                for pat in TRIPLE_PATTERNS:
                    cols3 = [color_mask_from_bit(pat[i]) for i in range(3)]
                    if all(masks[i] & cols3[i] for i in range(3)):
                        union[0] |= cols3[0]
                        union[1] |= cols3[1]
                        union[2] |= cols3[2]
                if 0 in union:
                    return None
                for i in range(3):
                    if union[i] != masks[i]:
                        ds[r + i][c] = union[i]
                        changed = True

        return changed

    def apply_balance_rules(ds):
        changed = False

        def process_line(coords):
            nonlocal changed
            masks = [ds[r][c] for r, c in coords]
            half = len(masks) // 2

            fixed_b = sum(1 for m in masks if m == B)
            fixed_w = sum(1 for m in masks if m == W)
            possible_b = sum(1 for m in masks if m & B)
            possible_w = sum(1 for m in masks if m & W)

            if fixed_b > half or fixed_w > half:
                return None
            if possible_b < half or possible_w < half:
                return None

            if fixed_b == half:
                for r, c in coords:
                    res = assign_cell(ds, r, c, W)
                    if res is None:
                        return None
                    if res:
                        changed = True

            if fixed_w == half:
                for r, c in coords:
                    res = assign_cell(ds, r, c, B)
                    if res is None:
                        return None
                    if res:
                        changed = True

            if possible_b == half:
                for r, c in coords:
                    if ds[r][c] & B:
                        res = assign_cell(ds, r, c, B)
                        if res is None:
                            return None
                        if res:
                            changed = True

            if possible_w == half:
                for r, c in coords:
                    if ds[r][c] & W:
                        res = assign_cell(ds, r, c, W)
                        if res is None:
                            return None
                        if res:
                            changed = True

            return True

        for r in range(rows):
            if process_line([(r, c) for c in range(cols)]) is None:
                return None
        for c in range(cols):
            if process_line([(r, c) for r in range(rows)]) is None:
                return None

        return changed

    def compute_line_candidates(ds):
        row_cands = []
        row_union = []
        for r in range(rows):
            cands, union = filter_line(row_patterns, ds[r], row_rels[r])
            if not cands:
                return None
            row_cands.append(cands)
            row_union.append(union)

        col_cands = []
        col_union = []
        for c in range(cols):
            masks = [ds[r][c] for r in range(rows)]
            cands, union = filter_line(col_patterns, masks, col_rels[c])
            if not cands:
                return None
            col_cands.append(cands)
            col_union.append(union)

        return row_cands, row_union, col_cands, col_union

    def propagate(ds):
        while True:
            changed = False

            res = apply_pair_rules(ds)
            if res is None:
                return None
            changed |= res

            res = apply_triple_rules(ds)
            if res is None:
                return None
            changed |= res

            res = apply_balance_rules(ds)
            if res is None:
                return None
            changed |= res

            line_info = compute_line_candidates(ds)
            if line_info is None:
                return None
            row_cands, row_union, col_cands, col_union = line_info

            for r in range(rows):
                for c in range(cols):
                    nd = ds[r][c] & row_union[r][c] & col_union[c][r]
                    if nd == 0:
                        return None
                    if nd != ds[r][c]:
                        ds[r][c] = nd
                        changed = True

            if not changed:
                return ds, row_cands, col_cands

    def solved(ds):
        return all(is_single(ds[r][c]) for r in range(rows) for c in range(cols))

    dead = set()

    def signature(ds):
        return tuple(tuple(row) for row in ds)

    def choose_branch(ds, row_cands, col_cands):
        best_line = None
        best_line_key = None

        for r in range(rows):
            if any(not is_single(ds[r][c]) for c in range(cols)):
                n = len(row_cands[r])
                if n > 1:
                    unresolved = sum(1 for c in range(cols) if not is_single(ds[r][c]))
                    key = (n, -unresolved)
                    if best_line_key is None or key < best_line_key:
                        best_line_key = key
                        best_line = ('row', r, row_cands[r])

        for c in range(cols):
            if any(not is_single(ds[r][c]) for r in range(rows)):
                n = len(col_cands[c])
                if n > 1:
                    unresolved = sum(1 for r in range(rows) if not is_single(ds[r][c]))
                    key = (n, -unresolved)
                    if best_line_key is None or key < best_line_key:
                        best_line_key = key
                        best_line = ('col', c, col_cands[c])

        if best_line is not None and len(best_line[2]) <= 2:
            return best_line

        best_cell = None
        best_key = None
        best_order = None

        for r in range(rows):
            for c in range(cols):
                if is_single(ds[r][c]):
                    continue

                row_count = len(row_cands[r])
                col_count = len(col_cands[c])

                rb = sum(1 for p in row_cands[r] if ((p >> c) & 1) == 1)
                rw = row_count - rb
                cb = sum(1 for p in col_cands[c] if ((p >> r) & 1) == 1)
                cw = col_count - cb

                support_b = rb * cb
                support_w = rw * cw

                key = (row_count * col_count, row_count + col_count, -degree[r][c])
                if best_key is None or key < best_key:
                    best_key = key
                    best_cell = ('cell', r, c)
                    opts = []
                    if ds[r][c] & B:
                        opts.append((support_b, B))
                    if ds[r][c] & W:
                        opts.append((support_w, W))
                    opts.sort()
                    best_order = [m for _, m in opts]

        return best_cell + (best_order,)

    def search(ds):
        prop = propagate(ds)
        if prop is None:
            return None

        ds, row_cands, col_cands = prop
        sig = signature(ds)
        if sig in dead:
            return None

        if solved(ds):
            return ds

        branch = choose_branch(ds, row_cands, col_cands)

        if branch[0] == 'row':
            _, r, cands = branch
            for p in cands:
                nds = clone_domains(ds)
                ok = True
                for c in range(cols):
                    col = B if ((p >> c) & 1) else W
                    if not (nds[r][c] & col):
                        ok = False
                        break
                    nds[r][c] = col
                if not ok:
                    continue
                res = search(nds)
                if res is not None:
                    return res

        elif branch[0] == 'col':
            _, c, cands = branch
            for p in cands:
                nds = clone_domains(ds)
                ok = True
                for r in range(rows):
                    col = B if ((p >> r) & 1) else W
                    if not (nds[r][c] & col):
                        ok = False
                        break
                    nds[r][c] = col
                if not ok:
                    continue
                res = search(nds)
                if res is not None:
                    return res

        else:
            _, r, c, order = branch
            for col in order:
                nds = clone_domains(ds)
                if not (nds[r][c] & col):
                    continue
                nds[r][c] = col
                res = search(nds)
                if res is not None:
                    return res

        dead.add(sig)
        return None

    result = search(domains)
    if result is None:
        return "No Solution"
    return [[MASK_TO_CHAR[result[r][c]] for c in range(cols)] for r in range(rows)]


