import ast

W_MASK = 1
B_MASK = 2
BOTH_MASK = W_MASK | B_MASK

CHAR_TO_MASK = {'W': W_MASK, 'B': B_MASK}
MASK_TO_CHAR = {W_MASK: 'W', B_MASK: 'B'}


def parse_coord_key(s):
    return ast.literal_eval(s)


def generate_line_patterns(length):
    if length % 2 != 0:
        return []
    half = length // 2
    result = []

    def rec(pos, b_count, prev1, prev2, mask):
        w_count = pos - b_count
        rem = length - pos

        if b_count > half or w_count > half:
            return
        if b_count + rem < half or w_count + rem < half:
            return

        if pos == length:
            if b_count == half:
                result.append(mask)
            return

        for bit in (0, 1):
            if pos >= 2 and prev1 == prev2 == bit:
                continue
            rec(pos + 1, b_count + bit, bit, prev1, mask | (bit << pos))

    rec(0, 0, -1, -1, 0)
    return result


def pattern_matches_adj_constraints(pattern, rels):
    for i, rel in rels:
        a = (pattern >> i) & 1
        b = (pattern >> (i + 1)) & 1
        if rel == '=':
            if a != b:
                return False
        else:
            if a == b:
                return False
    return True


def filter_candidates(base_candidates, line_domains):
    length = len(line_domains)
    allowed = [0] * length
    out = []

    for p in base_candidates:
        ok = True
        vals = [0] * length
        for i, dom in enumerate(line_domains):
            val = B_MASK if ((p >> i) & 1) else W_MASK
            vals[i] = val
            if not (dom & val):
                ok = False
                break
        if ok:
            out.append(p)
            for i in range(length):
                allowed[i] |= vals[i]

    return out, allowed


def solve(observation):
    data = observation['data']
    horizontal = observation.get('horizontal', {})
    vertical = observation.get('vertical', {})

    rows = len(data)
    if rows == 0:
        return "No Solution"
    cols = len(data[0])

    if any(len(row) != cols for row in data):
        return "No Solution"
    if rows % 2 != 0 or cols % 2 != 0:
        return "No Solution"

    # Internal adjacent constraints for each row / column.
    row_rels = [[] for _ in range(rows)]
    col_rels = [[] for _ in range(cols)]
    edges = []

    for key, rel in horizontal.items():
        rf, cf = parse_coord_key(key)
        r = int(round(rf))
        c = int(round(cf - 0.5))
        if not (0 <= r < rows and 0 <= c < cols - 1):
            return "No Solution"
        row_rels[r].append((c, rel))
        edges.append((r, c, r, c + 1, rel))

    for key, rel in vertical.items():
        rf, cf = parse_coord_key(key)
        r = int(round(rf - 0.5))
        c = int(round(cf))
        if not (0 <= r < rows - 1 and 0 <= c < cols):
            return "No Solution"
        col_rels[c].append((r, rel))
        edges.append((r, c, r + 1, c, rel))

    for rels in row_rels:
        rels.sort()
    for rels in col_rels:
        rels.sort()

    row_patterns = generate_line_patterns(cols)
    col_patterns = generate_line_patterns(rows)

    row_base = []
    for r in range(rows):
        base = [p for p in row_patterns if pattern_matches_adj_constraints(p, row_rels[r])]
        if not base:
            return "No Solution"
        row_base.append(base)

    col_base = []
    for c in range(cols):
        base = [p for p in col_patterns if pattern_matches_adj_constraints(p, col_rels[c])]
        if not base:
            return "No Solution"
        col_base.append(base)

    domains = [[BOTH_MASK for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            v = data[r][c]
            if v is not None:
                if v not in CHAR_TO_MASK:
                    return "No Solution"
                domains[r][c] = CHAR_TO_MASK[v]

    def opposite_mask(mask):
        out = 0
        if mask & W_MASK:
            out |= B_MASK
        if mask & B_MASK:
            out |= W_MASK
        return out

    def apply_balance_rule(line, set_func, half):
        fixed_b = sum(1 for d in line if d == B_MASK)
        fixed_w = sum(1 for d in line if d == W_MASK)
        can_b = sum(1 for d in line if d & B_MASK)
        can_w = sum(1 for d in line if d & W_MASK)

        if fixed_b > half or fixed_w > half:
            return False
        if can_b < half or can_w < half:
            return False

        if fixed_b == half:
            for i in range(len(line)):
                if not set_func(i, W_MASK):
                    return False
        if fixed_w == half:
            for i in range(len(line)):
                if not set_func(i, B_MASK):
                    return False
        if can_b == half:
            for i in range(len(line)):
                if line[i] & B_MASK:
                    if not set_func(i, B_MASK):
                        return False
        if can_w == half:
            for i in range(len(line)):
                if line[i] & W_MASK:
                    if not set_func(i, W_MASK):
                        return False
        return True

    def apply_triple_rule(line, set_func):
        for i in range(len(line) - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]

            if a in (W_MASK, B_MASK) and a == b:
                if not set_func(i + 2, BOTH_MASK ^ a):
                    return False
            if b in (W_MASK, B_MASK) and b == c:
                if not set_func(i, BOTH_MASK ^ b):
                    return False
            if a in (W_MASK, B_MASK) and a == c:
                if not set_func(i + 1, BOTH_MASK ^ a):
                    return False
        return True

    def propagate(cur_domains):
        row_cands = [None] * rows
        col_cands = [None] * cols

        while True:
            changed = False

            def reduce_cell(r, c, allowed):
                nonlocal changed
                new_mask = cur_domains[r][c] & allowed
                if new_mask == 0:
                    return False
                if new_mask != cur_domains[r][c]:
                    cur_domains[r][c] = new_mask
                    changed = True
                return True

            # Binary edge propagation.
            for r1, c1, r2, c2, rel in edges:
                d1 = cur_domains[r1][c1]
                d2 = cur_domains[r2][c2]
                if rel == '=':
                    allowed = d1 & d2
                    if allowed == 0:
                        return None
                    if not reduce_cell(r1, c1, allowed):
                        return None
                    if not reduce_cell(r2, c2, allowed):
                        return None
                else:
                    nd1 = d1 & opposite_mask(d2)
                    nd2 = d2 & opposite_mask(d1)
                    if nd1 == 0 or nd2 == 0:
                        return None
                    if not reduce_cell(r1, c1, nd1):
                        return None
                    if not reduce_cell(r2, c2, nd2):
                        return None

            # Human-like row deductions.
            for r in range(rows):
                row_line = cur_domains[r]

                if not apply_balance_rule(
                    row_line,
                    lambda c, allowed, rr=r: reduce_cell(rr, c, allowed),
                    cols // 2,
                ):
                    return None

                if not apply_triple_rule(
                    row_line,
                    lambda c, allowed, rr=r: reduce_cell(rr, c, allowed),
                ):
                    return None

            # Human-like column deductions.
            for c in range(cols):
                col_line = [cur_domains[r][c] for r in range(rows)]

                if not apply_balance_rule(
                    col_line,
                    lambda r, allowed, cc=c: reduce_cell(r, cc, allowed),
                    rows // 2,
                ):
                    return None

                if not apply_triple_rule(
                    col_line,
                    lambda r, allowed, cc=c: reduce_cell(r, cc, allowed),
                ):
                    return None

            # Full line-domain pruning using all valid row patterns.
            for r in range(rows):
                cands, allowed = filter_candidates(row_base[r], cur_domains[r])
                if not cands:
                    return None
                row_cands[r] = cands
                for c in range(cols):
                    if not reduce_cell(r, c, allowed[c]):
                        return None

            # Full line-domain pruning using all valid column patterns.
            for c in range(cols):
                line = [cur_domains[r][c] for r in range(rows)]
                cands, allowed = filter_candidates(col_base[c], line)
                if not cands:
                    return None
                col_cands[c] = cands
                for r in range(rows):
                    if not reduce_cell(r, c, allowed[r]):
                        return None

            if not changed:
                return row_cands, col_cands

    def solved(cur_domains):
        return all(cur_domains[r][c] in (W_MASK, B_MASK) for r in range(rows) for c in range(cols))

    def clone_domains(cur_domains):
        return [row[:] for row in cur_domains]

    def assign_row_pattern(cur_domains, r, pattern):
        for c in range(cols):
            cur_domains[r][c] = B_MASK if ((pattern >> c) & 1) else W_MASK

    def assign_col_pattern(cur_domains, c, pattern):
        for r in range(rows):
            cur_domains[r][c] = B_MASK if ((pattern >> r) & 1) else W_MASK

    def search(cur_domains):
        prop = propagate(cur_domains)
        if prop is None:
            return None
        row_cands, col_cands = prop

        if solved(cur_domains):
            return cur_domains

        best_kind = None
        best_idx = None
        best_cands = None
        best_len = 10**9

        for r, cands in enumerate(row_cands):
            k = len(cands)
            if 1 < k < best_len:
                best_kind = 'row'
                best_idx = r
                best_cands = cands
                best_len = k

        for c, cands in enumerate(col_cands):
            k = len(cands)
            if 1 < k < best_len:
                best_kind = 'col'
                best_idx = c
                best_cands = cands
                best_len = k

        if best_cands is None:
            return None

        for pattern in best_cands:
            nxt = clone_domains(cur_domains)
            if best_kind == 'row':
                assign_row_pattern(nxt, best_idx, pattern)
            else:
                assign_col_pattern(nxt, best_idx, pattern)
            found = search(nxt)
            if found is not None:
                return found

        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    answer = [[MASK_TO_CHAR[result[r][c]] for c in range(cols)] for r in range(rows)]
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1], [0, 0, 2, 2, 3, 3], [0, 0, 2, 2, 3, 3], [4, 0, 5, 2, 2, 3], [4, 0, 5, 5, 2, 2], [4, 4, 5, 5, 5, 2]]}

from collections import defaultdict, deque

# Free tetrominoes allowed by the puzzle. Reflections count as the same type,
# so each type is generated under the full dihedral symmetry group.
_BASE_SHAPES = {
    "I": {(0, 0), (0, 1), (0, 2), (0, 3)},
    "L": {(0, 0), (1, 0), (2, 0), (2, 1)},
    "T": {(0, 0), (0, 1), (0, 2), (1, 1)},
    "S": {(0, 1), (0, 2), (1, 0), (1, 1)},
}


def _normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))


def _all_orientations(cells):
    pts = list(cells)
    out = set()
    for swap in (0, 1):
        for sr in (1, -1):
            for sc in (1, -1):
                transformed = []
                for r, c in pts:
                    x, y = (c, r) if swap else (r, c)
                    transformed.append((sr * x, sc * y))
                out.add(_normalize(transformed))
    return sorted(out)


ORIENTATIONS = {t: _all_orientations(shape) for t, shape in _BASE_SHAPES.items()}


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = len(data[0]) if n else 0
    if n == 0 or m == 0:
        return "No Solution"

    def idx(r, c):
        return r * m + c

    def rc(k):
        return divmod(k, m)

    cell_region = {}
    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            reg = data[r][c]
            k = idx(r, c)
            cell_region[k] = reg
            regions[reg].append(k)
    region_ids = sorted(regions)

    neighbors4 = {}
    for r in range(n):
        for c in range(m):
            k = idx(r, c)
            adj = []
            if r > 0:
                adj.append(idx(r - 1, c))
            if r + 1 < n:
                adj.append(idx(r + 1, c))
            if c > 0:
                adj.append(idx(r, c - 1))
            if c + 1 < m:
                adj.append(idx(r, c + 1))
            neighbors4[k] = tuple(adj)

    # Region adjacency from the partition itself.
    region_adj = {r: set() for r in region_ids}
    for r in range(n):
        for c in range(m):
            a = data[r][c]
            if r + 1 < n:
                b = data[r + 1][c]
                if a != b:
                    region_adj[a].add(b)
                    region_adj[b].add(a)
            if c + 1 < m:
                b = data[r][c + 1]
                if a != b:
                    region_adj[a].add(b)
                    region_adj[b].add(a)

    # Enumerate all tetromino placements fully contained in each region.
    candidates = {}
    for reg in region_ids:
        coords = [rc(k) for k in regions[reg]]
        coord_set = set(coords)
        seen = set()
        reg_cands = []
        for typ, orients in ORIENTATIONS.items():
            for orient in orients:
                max_r = max(r for r, c in orient)
                max_c = max(c for r, c in orient)
                for ar, ac in coords:
                    # Translate normalized orientation so its min corner sits at (ar, ac).
                    placed = tuple(sorted((ar + dr, ac + dc) for dr, dc in orient))
                    if any((pr, pc) not in coord_set for pr, pc in placed):
                        continue
                    key = (typ, placed)
                    if key in seen:
                        continue
                    seen.add(key)
                    cell_ids = tuple(sorted(idx(pr, pc) for pr, pc in placed))
                    reg_cands.append({
                        "type": typ,
                        "cells": cell_ids,
                        "cellset": frozenset(cell_ids),
                        "mask": sum(1 << k for k in cell_ids),
                    })
        if not reg_cands:
            return "No Solution"
        candidates[reg] = reg_cands

    # Precompute cell-to-candidate incidence for quick local reasoning if needed.
    cand_cells = {
        reg: [cand["cellset"] for cand in candidates[reg]]
        for reg in region_ids
    }

    # Touch relation between candidates of adjacent regions:
    # two chosen tetrominoes can be connected only if at least one shaded cell pair
    # lies orthogonally across a region border.
    touch = {}
    for a in region_ids:
        for b in region_adj[a]:
            if (a, b) in touch:
                continue
            ta = [set() for _ in range(len(candidates[a]))]
            tb = [set() for _ in range(len(candidates[b]))]
            for i, ca in enumerate(candidates[a]):
                aset = ca["cellset"]
                frontier = set()
                for cell in aset:
                    frontier.update(neighbors4[cell])
                frontier.difference_update(aset)
                for j, cb in enumerate(candidates[b]):
                    if frontier & cb["cellset"]:
                        ta[i].add(j)
                        tb[j].add(i)
            touch[(a, b)] = tuple(frozenset(s) for s in ta)
            touch[(b, a)] = tuple(frozenset(s) for s in tb)

    # Precompute every 2x2 block.
    blocks = []
    for r in range(n - 1):
        for c in range(m - 1):
            cells = [idx(r, c), idx(r, c + 1), idx(r + 1, c), idx(r + 1, c + 1)]
            involved = sorted({cell_region[k] for k in cells})
            cover = {}
            for reg in involved:
                arr = []
                for cand in candidates[reg]:
                    mask4 = 0
                    cset = cand["cellset"]
                    for bit, cell in enumerate(cells):
                        if cell in cset:
                            mask4 |= 1 << bit
                    arr.append(mask4)
                cover[reg] = tuple(arr)
            blocks.append((tuple(cells), tuple(involved), cover))

    all_regions = tuple(region_ids)
    multi_region = len(all_regions) > 1

    def deep_copy_domain(domain):
        return {r: set(v) for r, v in domain.items()}

    def type_set(reg, domain):
        return {candidates[reg][i]["type"] for i in domain[reg]}

    def candidate_component_filter(domain):
        # Human-like connectivity deduction:
        # The final connected solution must lie in a single component of "still possible"
        # shaded cells. So only components that contain at least one candidate from every
        # region can survive.
        possible_cells = set()
        for reg in all_regions:
            for i in domain[reg]:
                possible_cells.update(cand_cells[reg][i])
        if not possible_cells:
            return None, False

        comp_id = {}
        cid = 0
        for start in possible_cells:
            if start in comp_id:
                continue
            dq = [start]
            comp_id[start] = cid
            while dq:
                cur = dq.pop()
                for nb in neighbors4[cur]:
                    if nb in possible_cells and nb not in comp_id:
                        comp_id[nb] = cid
                        dq.append(nb)
            cid += 1

        feasible = None
        cand_comp = {}
        for reg in all_regions:
            s = set()
            local = {}
            for i in domain[reg]:
                c0 = comp_id[candidates[reg][i]["cells"][0]]
                local[i] = c0
                s.add(c0)
            cand_comp[reg] = local
            feasible = s if feasible is None else (feasible & s)
            if not feasible:
                return None, False

        changed = False
        for reg in all_regions:
            bad = {i for i in domain[reg] if cand_comp[reg][i] not in feasible}
            if bad:
                domain[reg] -= bad
                if not domain[reg]:
                    return None, False
                changed = True
        return domain, changed

    def possible_touch_graph(domain):
        g = {r: set() for r in all_regions}
        for a in all_regions:
            for b in region_adj[a]:
                if b < a:
                    continue
                ok = False
                dom_b = domain[b]
                for i in domain[a]:
                    ti = candidates[a][i]["type"]
                    js = touch[(a, b)][i]
                    if not js:
                        continue
                    for j in js:
                        if j in dom_b and candidates[b][j]["type"] != ti:
                            ok = True
                            break
                    if ok:
                        break
                if ok:
                    g[a].add(b)
                    g[b].add(a)
        return g

    def connected_region_graph(graph):
        start = all_regions[0]
        seen = {start}
        dq = [start]
        while dq:
            cur = dq.pop()
            for nb in graph[cur]:
                if nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(all_regions)

    def block_arc_consistency(domain):
        changed = False
        for _, involved, cover in blocks:
            supported = {r: set() for r in involved}
            seq = involved
            chosen = []

            def rec(k, covered_mask):
                if covered_mask == 0b1111:
                    return
                if k == len(seq):
                    for rr, ii in chosen:
                        supported[rr].add(ii)
                    return
                rr = seq[k]
                dom_rr = domain[rr]
                if not dom_rr:
                    return
                cov_rr = cover[rr]
                for ii in dom_rr:
                    new_mask = covered_mask | cov_rr[ii]
                    if new_mask == 0b1111:
                        continue
                    chosen.append((rr, ii))
                    rec(k + 1, new_mask)
                    chosen.pop()

            rec(0, 0)

            for reg in involved:
                bad = domain[reg] - supported[reg]
                if bad:
                    domain[reg] -= bad
                    if not domain[reg]:
                        return None, False
                    changed = True
        return domain, changed

    def propagate(domain):
        domain = deep_copy_domain(domain)
        while True:
            changed = False

            # Basic emptiness.
            for reg in all_regions:
                if not domain[reg]:
                    return None

            # Adjacent regions cannot use the same tetromino type.
            for a in all_regions:
                for b in region_adj[a]:
                    if b < a:
                        continue
                    types_a = type_set(a, domain)
                    types_b = type_set(b, domain)
                    if not types_a or not types_b:
                        return None

                    bad_a = {i for i in domain[a] if not any(
                        candidates[a][i]["type"] != t for t in types_b
                    )}
                    if bad_a:
                        domain[a] -= bad_a
                        if not domain[a]:
                            return None
                        changed = True

                    bad_b = {j for j in domain[b] if not any(
                        candidates[b][j]["type"] != t for t in types_a
                    )}
                    if bad_b:
                        domain[b] -= bad_b
                        if not domain[b]:
                            return None
                        changed = True

            # Every chosen tetromino must be able to touch at least one other region's
            # tetromino in some still-possible way; otherwise global connectivity is impossible.
            if multi_region:
                for a in all_regions:
                    bad = set()
                    for i in domain[a]:
                        typ = candidates[a][i]["type"]
                        ok = False
                        for b in region_adj[a]:
                            dom_b = domain[b]
                            js = touch[(a, b)][i]
                            if not js:
                                continue
                            for j in js:
                                if j in dom_b and candidates[b][j]["type"] != typ:
                                    ok = True
                                    break
                            if ok:
                                break
                        if not ok:
                            bad.add(i)
                    if bad:
                        domain[a] -= bad
                        if not domain[a]:
                            return None
                        changed = True

                # The graph of still-possible region connections must remain connected.
                g = possible_touch_graph(domain)
                if not connected_region_graph(g):
                    return None

            # No 2x2 block may be fully shaded.
            domain2, ch = block_arc_consistency(domain)
            if domain2 is None:
                return None
            domain = domain2
            changed |= ch

            # Global connectivity via a single possible cell-component.
            domain2, ch = candidate_component_filter(domain)
            if domain2 is None:
                return None
            domain = domain2
            changed |= ch

            if not changed:
                return domain

    def final_check(chosen):
        shaded = set()
        answer = [[None for _ in range(m)] for _ in range(n)]

        for reg in all_regions:
            cand = candidates[reg][chosen[reg]]
            typ = cand["type"]
            for cell in cand["cells"]:
                if cell in shaded:
                    return None
                shaded.add(cell)
                r, c = rc(cell)
                answer[r][c] = typ

        for a in all_regions:
            for b in region_adj[a]:
                if b < a:
                    continue
                if candidates[a][chosen[a]]["type"] == candidates[b][chosen[b]]["type"]:
                    return None

        for r in range(n - 1):
            for c in range(m - 1):
                block = [idx(r, c), idx(r, c + 1), idx(r + 1, c), idx(r + 1, c + 1)]
                if all(k in shaded for k in block):
                    return None

        if shaded:
            start = next(iter(shaded))
            seen = {start}
            dq = [start]
            while dq:
                cur = dq.pop()
                for nb in neighbors4[cur]:
                    if nb in shaded and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(shaded):
                return None

        return answer

    def choose_region(domain):
        # Human-like branching: pick the region with the fewest surviving placements.
        # Tie-break by fewest surviving types, then by most constrained adjacency.
        best = None
        best_key = None
        for reg in all_regions:
            d = len(domain[reg])
            if d <= 1:
                continue
            key = (
                d,
                len(type_set(reg, domain)),
                -len(region_adj[reg]),
            )
            if best is None or key < best_key:
                best = reg
                best_key = key
        return best

    def ordered_values(reg, domain):
        # Prefer candidates that maintain many possible touches to neighbors
        # and fit the currently feasible global structure.
        scored = []
        for i in domain[reg]:
            typ = candidates[reg][i]["type"]
            touch_score = 0
            for b in region_adj[reg]:
                for j in touch[(reg, b)][i]:
                    if j in domain[b] and candidates[b][j]["type"] != typ:
                        touch_score += 1
            scored.append((-touch_score, candidates[reg][i]["type"], i))
        scored.sort()
        return [i for _, _, i in scored]

    def search(domain):
        domain = propagate(domain)
        if domain is None:
            return None

        if all(len(domain[r]) == 1 for r in all_regions):
            chosen = {r: next(iter(domain[r])) for r in all_regions}
            return final_check(chosen)

        reg = choose_region(domain)
        if reg is None:
            return None

        for i in ordered_values(reg, domain):
            new_domain = deep_copy_domain(domain)
            new_domain[reg] = {i}
            result = search(new_domain)
            if result is not None:
                return result
        return None

    initial_domain = {reg: set(range(len(candidates[reg]))) for reg in all_regions}
    answer = search(initial_domain)
    return repr(answer) if answer is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 0, 1], [2, 2, 0, 0, 3, 1], [2, 4, 4, 0, 3, 1], [2, 2, 4, 0, 3, 1], [5, 2, 4, 4, 3, 1], [5, 5, 5, 5, 5, 1]]}

from collections import defaultdict, deque

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    if n == 0 or m == 0:
        return "No Solution"

    def cell_index(r, c):
        return r * m + c

    def bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def singleton_index(mask):
        return mask.bit_length() - 1 if mask and (mask & (mask - 1)) == 0 else None

    # Global cell data
    ncells = n * m
    coords = [(r, c) for r in range(n) for c in range(m)]
    cell_neighbors = [[] for _ in range(ncells)]
    for r in range(n):
        for c in range(m):
            i = cell_index(r, c)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    cell_neighbors[i].append(cell_index(rr, cc))

    # Regions
    region_ids = []
    seen = set()
    for row in grid:
        for rid in row:
            if rid not in seen:
                seen.add(rid)
                region_ids.append(rid)
    rid_to_idx = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    region_cells = [[] for _ in range(R)]
    region_coord_sets = [set() for _ in range(R)]
    owner = [None] * ncells
    for r in range(n):
        for c in range(m):
            ri = rid_to_idx[grid[r][c]]
            idx = cell_index(r, c)
            region_cells[ri].append(idx)
            region_coord_sets[ri].add((r, c))
            owner[idx] = ri

    # Region adjacency
    neighbors = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = rid_to_idx[grid[r][c]]
            for dr, dc in ((1, 0), (0, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    b = rid_to_idx[grid[rr][cc]]
                    if a != b:
                        neighbors[a].add(b)
                        neighbors[b].add(a)
    neighbors = [tuple(sorted(s)) for s in neighbors]

    # 2x2 blocks
    blocks = []
    blocks_by_region = [[] for _ in range(R)]
    for r in range(n - 1):
        for c in range(m - 1):
            block = (
                cell_index(r, c),
                cell_index(r, c + 1),
                cell_index(r + 1, c),
                cell_index(r + 1, c + 1),
            )
            blocks.append(block)
            rs = {owner[x] for x in block}
            for ri in rs:
                blocks_by_region[ri].append(block)

    # Tetromino orientations
    base_shapes = {
        "I": [(0, 0), (1, 0), (2, 0), (3, 0)],
        "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
        "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
        "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
    }

    def all_orientations(cells):
        out = set()
        for reflect in (1, -1):
            pts = [(r, c * reflect) for r, c in cells]
            for _ in range(4):
                min_r = min(r for r, _ in pts)
                min_c = min(c for _, c in pts)
                norm = tuple(sorted((r - min_r, c - min_c) for r, c in pts))
                out.add(norm)
                pts = [(c, -r) for r, c in pts]
        return sorted(out)

    shape_orients = {t: all_orientations(cells) for t, cells in base_shapes.items()}

    # Placement generation per region
    p_types = [[] for _ in range(R)]
    p_masks = [[] for _ in range(R)]
    p_nbr_masks = [[] for _ in range(R)]
    cell_cover = [dict() for _ in range(R)]

    for ri in range(R):
        rcells = region_coord_sets[ri]
        if len(region_cells[ri]) < 4:
            return "No Solution"

        seen_pmasks = set()
        for t, orients in shape_orients.items():
            for shape in orients:
                max_r = max(r for r, _ in shape)
                max_c = max(c for _, c in shape)
                for sr in range(n - max_r):
                    for sc in range(m - max_c):
                        coords_here = [(sr + r, sc + c) for r, c in shape]
                        if all(x in rcells for x in coords_here):
                            mask = 0
                            nbr_mask = 0
                            for r, c in coords_here:
                                idx = cell_index(r, c)
                                mask |= 1 << idx
                            if (t, mask) in seen_pmasks:
                                continue
                            seen_pmasks.add((t, mask))
                            for idx in [cell_index(r, c) for r, c in coords_here]:
                                for nb in cell_neighbors[idx]:
                                    nbr_mask |= 1 << nb
                            nbr_mask &= ~mask
                            p_types[ri].append(t)
                            p_masks[ri].append(mask)
                            p_nbr_masks[ri].append(nbr_mask)

        if not p_masks[ri]:
            return "No Solution"

        for pi, mask in enumerate(p_masks[ri]):
            mm = mask
            while mm:
                b = mm & -mm
                cell = b.bit_length() - 1
                cell_cover[ri][cell] = cell_cover[ri].get(cell, 0) | (1 << pi)
                mm ^= b

    # Type masks per region
    all_types = ("L", "I", "T", "S")
    type_masks = []
    not_type_masks = []
    for ri in range(R):
        tm = {t: 0 for t in all_types}
        for pi, t in enumerate(p_types[ri]):
            tm[t] |= 1 << pi
        ntm = {t: ((1 << len(p_types[ri])) - 1) ^ tm[t] for t in all_types}
        type_masks.append(tm)
        not_type_masks.append(ntm)

    # Touch support masks:
    # touch_ok[ri][pi][rj] = bitmask of placements in rj that both touch placement pi and use a different type
    touch_ok = []
    for ri in range(R):
        local = []
        for pi in range(len(p_masks[ri])):
            d = {}
            for rj in neighbors[ri]:
                mask = 0
                pm_nbr = p_nbr_masks[ri][pi]
                pt = p_types[ri][pi]
                for qj, qmask in enumerate(p_masks[rj]):
                    if p_types[rj][qj] != pt and (pm_nbr & qmask):
                        mask |= 1 << qj
                d[rj] = mask
            local.append(d)
        touch_ok.append(local)

    # Quick impossible if a region has no adjacent region in region graph and there are multiple regions.
    if R > 1:
        for ri in range(R):
            if not neighbors[ri]:
                return "No Solution"

    initial_domains = [(1 << len(p_masks[ri])) - 1 for ri in range(R)]

    def compute_forced_cells(domains):
        forced = [False] * ncells
        for ri in range(R):
            D = domains[ri]
            for cell in region_cells[ri]:
                cover = cell_cover[ri].get(cell, 0)
                if D and (D & cover) and (D & ~cover) == 0:
                    forced[cell] = True
        return forced

    def placement_completes_forbidden_block(ri, pi, forced):
        pmask = p_masks[ri][pi]
        for block in blocks_by_region[ri]:
            ok = True
            for cell in block:
                if owner[cell] == ri:
                    if not (pmask & (1 << cell)):
                        ok = False
                        break
                else:
                    if not forced[cell]:
                        ok = False
                        break
            if ok:
                return True
        return False

    def edge_possible(domains, a, b):
        Da = domains[a]
        Db = domains[b]
        for pa in bits(Da):
            if touch_ok[a][pa].get(b, 0) & Db:
                return True
        return False

    def possible_graph_connected(domains):
        if R <= 1:
            return True
        seen_regions = {0}
        stack = [0]
        while stack:
            x = stack.pop()
            for y in neighbors[x]:
                if y not in seen_regions and edge_possible(domains, x, y):
                    seen_regions.add(y)
                    stack.append(y)
        return len(seen_regions) == R

    def propagate(domains):
        domains = domains[:]
        while True:
            changed = False

            # Human-like local filtering:
            # 1) every placement must be type-compatible with all adjacent regions
            # 2) every placement must be able to touch at least one neighboring region
            for ri in range(R):
                D = domains[ri]
                newD = 0
                for pi in bits(D):
                    t = p_types[ri][pi]

                    # Adjacent regions cannot share a tetromino type.
                    ok = True
                    for rj in neighbors[ri]:
                        if (domains[rj] & not_type_masks[rj][t]) == 0:
                            ok = False
                            break
                    if not ok:
                        continue

                    # Global shaded area must remain connectable:
                    # each chosen tetromino must have at least one possible touching neighbor.
                    if R > 1:
                        can_touch = False
                        for rj in neighbors[ri]:
                            if touch_ok[ri][pi].get(rj, 0) & domains[rj]:
                                can_touch = True
                                break
                        if not can_touch:
                            continue

                    newD |= 1 << pi

                if newD != D:
                    domains[ri] = newD
                    changed = True
                    if newD == 0:
                        return None

            forced = compute_forced_cells(domains)

            # Forced 2x2 contradiction
            for a, b, c, d in blocks:
                if forced[a] and forced[b] and forced[c] and forced[d]:
                    return None

            # If a placement would complete a 2x2 together with currently forced cells, remove it.
            for ri in range(R):
                D = domains[ri]
                newD = D
                for pi in bits(D):
                    if placement_completes_forbidden_block(ri, pi, forced):
                        newD &= ~(1 << pi)
                if newD != D:
                    domains[ri] = newD
                    changed = True
                    if newD == 0:
                        return None

            # The full set of regions must still be connectable through possible touching choices.
            if not possible_graph_connected(domains):
                return None

            if not changed:
                return domains

    def verify_and_build(domains):
        chosen = []
        total_mask = 0
        answer = [[None for _ in range(m)] for _ in range(n)]

        for ri in range(R):
            pi = singleton_index(domains[ri])
            if pi is None:
                return None
            chosen.append(pi)

        # Same-type adjacency
        for ri in range(R):
            for rj in neighbors[ri]:
                if ri < rj and p_types[ri][chosen[ri]] == p_types[rj][chosen[rj]]:
                    return None

        # Fill answer and total mask
        for ri in range(R):
            pi = chosen[ri]
            t = p_types[ri][pi]
            mask = p_masks[ri][pi]
            total_mask |= mask
            mm = mask
            while mm:
                b = mm & -mm
                cell = b.bit_length() - 1
                r, c = divmod(cell, m)
                answer[r][c] = t
                mm ^= b

        # Each region contributes exactly 4 cells by construction
        if total_mask.bit_count() != 4 * R:
            return None

        # No 2x2 all-shaded
        for a, b, c, d in blocks:
            if ((total_mask >> a) & 1) and ((total_mask >> b) & 1) and ((total_mask >> c) & 1) and ((total_mask >> d) & 1):
                return None

        # Global orthogonal connectivity of all shaded cells
        if total_mask:
            start_bit = total_mask & -total_mask
            start = start_bit.bit_length() - 1
            seen_cells = {start}
            dq = deque([start])
            while dq:
                x = dq.popleft()
                for y in cell_neighbors[x]:
                    if (total_mask >> y) & 1 and y not in seen_cells:
                        seen_cells.add(y)
                        dq.append(y)
            if len(seen_cells) != total_mask.bit_count():
                return None

        return answer

    fail_cache = set()

    def region_type_count(ri, D):
        return sum(1 for t in all_types if D & type_masks[ri][t])

    def choose_region(domains):
        best = None
        best_key = None
        for ri in range(R):
            D = domains[ri]
            cnt = D.bit_count()
            if cnt <= 1:
                continue
            possible_touch_regions = 0
            for rj in neighbors[ri]:
                if edge_possible(domains, ri, rj):
                    possible_touch_regions += 1
            key = (cnt, region_type_count(ri, D), -possible_touch_regions, -len(neighbors[ri]))
            if best_key is None or key < best_key:
                best_key = key
                best = ri
        return best

    def ordered_values(domains, ri):
        vals = []
        D = domains[ri]
        for pi in bits(D):
            touch_regions = 0
            touch_total = 0
            for rj in neighbors[ri]:
                sup = touch_ok[ri][pi].get(rj, 0) & domains[rj]
                if sup:
                    touch_regions += 1
                    touch_total += sup.bit_count()
            # Prefer placements that stay well-connected and leave more options.
            score = (touch_regions, touch_total)
            vals.append((score, pi))
        vals.sort(reverse=True)
        return [pi for _, pi in vals]

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        state = tuple(domains)
        if state in fail_cache:
            return None

        if all((d & (d - 1)) == 0 for d in domains):
            built = verify_and_build(domains)
            if built is not None:
                return built
            fail_cache.add(state)
            return None

        ri = choose_region(domains)
        if ri is None:
            fail_cache.add(state)
            return None

        for pi in ordered_values(domains, ri):
            new_domains = domains[:]
            new_domains[ri] = 1 << pi
            result = dfs(new_domains)
            if result is not None:
                return result

        fail_cache.add(state)
        return None

    result = dfs(initial_domains)
    if result is None:
        return "No Solution"
    return repr(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 0, 1, 1], [2, 3, 3, 3, 4, 4], [2, 5, 6, 6, 4, 4], [2, 5, 6, 6, 7, 7], [8, 8, 9, 9, 9, 10], [8, 8, 11, 11, 12, 10]], 'data': [[1, None, None, None, 2, None], [None, None, None, None, None, None], [None, 0, None, None, None, None], [None, None, None, None, 0, None], [1, None, 1, None, None, 1], [None, None, None, None, None, None]]}

# Generalized Heyawake-style solver:
# 1) numbered regions contain exactly that many black cells
# 2) black cells do not touch orthogonally
# 3) any uninterrupted white segment in a row/col crosses at most 2 region-blocks
# 4) all white cells are connected

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    R = len(region)
    C = len(region[0]) if R else 0
    N = R * C
    ALL = (1 << N) - 1

    def idx(r, c):
        return r * C + c

    def rc(i):
        return divmod(i, C)

    # Cell -> region
    cell_region = [0] * N
    region_cells = {}
    clue_by_region = {}
    for r in range(R):
        for c in range(C):
            i = idx(r, c)
            rid = region[r][c]
            cell_region[i] = rid
            region_cells.setdefault(rid, []).append(i)
            v = data[r][c]
            if v is not None:
                if rid in clue_by_region and clue_by_region[rid] != v:
                    return "No Solution"
                clue_by_region[rid] = v

    region_ids = sorted(region_cells)
    region_index = {rid: k for k, rid in enumerate(region_ids)}
    cell_region_index = [region_index[cell_region[i]] for i in range(N)]
    region_masks = {}
    for rid, cells in region_cells.items():
        m = 0
        for i in cells:
            m |= 1 << i
        region_masks[rid] = m

    # Orthogonal neighbors
    neighbors = [0] * N
    neighbor_lists = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            i = idx(r, c)
            m = 0
            lst = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < R and 0 <= cc < C:
                    j = idx(rr, cc)
                    m |= 1 << j
                    lst.append(j)
            neighbors[i] = m
            neighbor_lists[i] = lst

    # Build room-patterns (exact black placements inside a region),
    # already respecting internal orthogonal non-touching.
    # For numbered regions: exact count. For unnumbered: any independent subset.
    region_patterns = {}
    for rid in region_ids:
        cells = region_cells[rid]
        clue = clue_by_region.get(rid)
        s = len(cells)
        local_neighbors = [0] * s
        global_bits = [1 << i for i in cells]
        for a in range(s):
            ia = cells[a]
            mask = 0
            for b in range(s):
                if a != b and ((1 << cells[b]) & neighbors[ia]):
                    mask |= 1 << b
            local_neighbors[a] = mask

        patterns = []

        def rec(rem, chosen, cnt):
            if clue is not None:
                if cnt > clue:
                    return
                if cnt + rem.bit_count() < clue:
                    return
            if rem == 0:
                if clue is None or cnt == clue:
                    gmask = 0
                    lmask = chosen
                    t = 0
                    while lmask:
                        b = lmask & -lmask
                        k = b.bit_length() - 1
                        gmask |= global_bits[k]
                        lmask ^= b
                        t += 1
                    nbr_union = 0
                    gm = gmask
                    while gm:
                        b = gm & -gm
                        i = b.bit_length() - 1
                        nbr_union |= neighbors[i]
                        gm ^= b
                    patterns.append((gmask, nbr_union))
                return
            b = rem & -rem
            k = b.bit_length() - 1
            rem2 = rem ^ b
            rec(rem2, chosen, cnt)
            rec(rem2 & ~local_neighbors[k], chosen | b, cnt + 1)

        rec((1 << s) - 1, 0, 0)
        region_patterns[rid] = patterns

    # Build line constraints:
    # every interval covering 3 consecutive region-blocks must contain a black.
    intervals = []
    interval_seen = set()

    def add_line_intervals(line_cells):
        blocks = []
        cur_mask = 0
        prev_rid = None
        for i in line_cells:
            rid = cell_region[i]
            if rid != prev_rid:
                if cur_mask:
                    blocks.append(cur_mask)
                cur_mask = 1 << i
                prev_rid = rid
            else:
                cur_mask |= 1 << i
        if cur_mask:
            blocks.append(cur_mask)
        for k in range(len(blocks) - 2):
            m = blocks[k] | blocks[k + 1] | blocks[k + 2]
            if m not in interval_seen:
                interval_seen.add(m)
                intervals.append(m)

    for r in range(R):
        add_line_intervals([idx(r, c) for c in range(C)])
    for c in range(C):
        add_line_intervals([idx(r, c) for r in range(R)])

    cell_interval_count = [0] * N
    for m in intervals:
        x = m
        while x:
            b = x & -x
            i = b.bit_length() - 1
            cell_interval_count[i] += 1
            x ^= b

    def flood(start_bit, allowed):
        seen = start_bit
        stack = [start_bit.bit_length() - 1]
        while stack:
            i = stack.pop()
            m = neighbors[i] & allowed & ~seen
            while m:
                b = m & -m
                j = b.bit_length() - 1
                seen |= b
                stack.append(j)
                m ^= b
        return seen

    def connectivity_possible(black_mask, white_mask):
        allowed = ALL & ~black_mask
        if white_mask:
            start = white_mask & -white_mask
            reach = flood(start, allowed)
            if white_mask & ~reach:
                return False
        return True

    def forced_connectivity_whites(black_mask, white_mask):
        # If removing an unknown disconnects already-forced whites, that cell must be white.
        if white_mask.bit_count() < 2:
            return 0
        allowed = ALL & ~black_mask
        start = white_mask & -white_mask
        forced = 0
        unknown = allowed & ~white_mask
        while unknown:
            b = unknown & -unknown
            allowed2 = allowed ^ b
            reach = flood(start, allowed2)
            if white_mask & ~reach:
                forced |= b
            unknown ^= b
        return forced

    def filter_region_possibilities(black_mask, white_mask):
        poss_by_region = []
        for rid in region_ids:
            reg_mask = region_masks[rid]
            assigned_black = black_mask & reg_mask
            poss = []
            for pmask, pnbrs in region_patterns[rid]:
                if pmask & white_mask:
                    continue
                if assigned_black & ~pmask:
                    continue
                if pnbrs & (black_mask & ~pmask):
                    continue
                poss.append((pmask, pnbrs))
            if not poss:
                return None
            poss_by_region.append(poss)
        return poss_by_region

    def propagate(black_mask, white_mask):
        if black_mask & white_mask:
            return None

        while True:
            changed = False

            # Black adjacency -> orthogonal neighbors become white.
            forbid = 0
            bm = black_mask
            while bm:
                b = bm & -bm
                i = b.bit_length() - 1
                if neighbors[i] & black_mask:
                    return None
                forbid |= neighbors[i]
                bm ^= b
            if forbid & black_mask:
                return None
            new_white = forbid & ~white_mask
            if new_white:
                white_mask |= new_white
                if black_mask & white_mask:
                    return None
                changed = True

            # Region pattern propagation.
            poss_by_region = filter_region_possibilities(black_mask, white_mask)
            if poss_by_region is None:
                return None

            for ridx, rid in enumerate(region_ids):
                poss = poss_by_region[ridx]
                reg_mask = region_masks[rid]
                inter = poss[0][0]
                union = 0
                for pmask, _ in poss:
                    inter &= pmask
                    union |= pmask
                add_black = inter & ~black_mask
                if add_black:
                    if add_black & white_mask:
                        return None
                    black_mask |= add_black
                    changed = True
                add_white = (reg_mask & ~union) & ~white_mask
                if add_white:
                    if add_white & black_mask:
                        return None
                    white_mask |= add_white
                    changed = True

            if black_mask & white_mask:
                return None

            # 3-room line rule.
            for im in intervals:
                if black_mask & im:
                    continue
                avail = im & ~white_mask
                if avail == 0:
                    return None
                if avail & (avail - 1) == 0:
                    if avail & white_mask:
                        return None
                    if not (avail & black_mask):
                        black_mask |= avail
                        changed = True

            if black_mask & white_mask:
                return None

            # Connectivity feasibility.
            if not connectivity_possible(black_mask, white_mask):
                return None

            # Connectivity deductions.
            add_white = forced_connectivity_whites(black_mask, white_mask)
            if add_white:
                if add_white & black_mask:
                    return None
                white_mask |= add_white
                changed = True

            if not changed:
                poss_by_region = filter_region_possibilities(black_mask, white_mask)
                if poss_by_region is None:
                    return None
                return black_mask, white_mask, poss_by_region

    def validate_complete(black_mask):
        # Rule 2
        bm = black_mask
        while bm:
            b = bm & -bm
            i = b.bit_length() - 1
            if neighbors[i] & black_mask:
                return False
            bm ^= b

        # Rule 1
        for rid in region_ids:
            clue = clue_by_region.get(rid)
            if clue is not None:
                if (black_mask & region_masks[rid]).bit_count() != clue:
                    return False

        # Rule 3 direct validation
        def valid_line(line_cells):
            t = 0
            while t < len(line_cells):
                i = line_cells[t]
                if black_mask & (1 << i):
                    t += 1
                    continue
                prev_rid = None
                blocks = 0
                while t < len(line_cells):
                    j = line_cells[t]
                    if black_mask & (1 << j):
                        break
                    rid = cell_region[j]
                    if rid != prev_rid:
                        blocks += 1
                        prev_rid = rid
                        if blocks > 2:
                            return False
                    t += 1
            return True

        for r in range(R):
            if not valid_line([idx(r, c) for c in range(C)]):
                return False
        for c in range(C):
            if not valid_line([idx(r, c) for r in range(R)]):
                return False

        # Rule 4
        white_mask = ALL & ~black_mask
        if white_mask:
            start = white_mask & -white_mask
            if flood(start, white_mask) != white_mask:
                return False

        return True

    dead = set()

    def dfs(black_mask, white_mask):
        res = propagate(black_mask, white_mask)
        if res is None:
            return None
        black_mask, white_mask, poss_by_region = res
        key = (black_mask, white_mask)
        if key in dead:
            return None

        if (black_mask | white_mask) == ALL:
            if validate_complete(black_mask):
                return black_mask
            dead.add(key)
            return None

        # Prefer branching on a numbered region with few remaining exact patterns.
        chosen_region = None
        chosen_patterns = None
        best_key = None

        for ridx, rid in enumerate(region_ids):
            poss = poss_by_region[ridx]
            cnt = len(poss)
            if cnt <= 1:
                continue
            numbered = clue_by_region.get(rid) is not None
            if numbered or cnt <= 8:
                rk = (0 if numbered else 1, cnt, len(region_cells[rid]))
                if best_key is None or rk < best_key:
                    best_key = rk
                    chosen_region = rid
                    chosen_patterns = poss

        if chosen_region is not None:
            reg_mask = region_masks[chosen_region]
            ordered = sorted(chosen_patterns, key=lambda x: x[0].bit_count())
            for pmask, _ in ordered:
                nb = black_mask | pmask
                nw = white_mask | (reg_mask & ~pmask)
                ans = dfs(nb, nw)
                if ans is not None:
                    return ans
            dead.add(key)
            return None

        # Otherwise branch on the most constrained cell.
        unknown = ALL & ~(black_mask | white_mask)
        best_cell = None
        best_metric = None
        best_order = None

        # Count black-support per cell within each region's remaining patterns.
        support_counts = {}
        for ridx, rid in enumerate(region_ids):
            poss = poss_by_region[ridx]
            counts = {}
            for i in region_cells[rid]:
                counts[i] = 0
            for pmask, _ in poss:
                x = pmask & region_masks[rid]
                while x:
                    b = x & -x
                    i = b.bit_length() - 1
                    counts[i] += 1
                    x ^= b
            support_counts[rid] = (counts, len(poss))

        x = unknown
        while x:
            b = x & -x
            i = b.bit_length() - 1
            rid = cell_region[i]
            counts, total = support_counts[rid]
            bc = counts[i]
            wc = total - bc
            impact = 3 * cell_interval_count[i] + len(neighbor_lists[i])
            metric = (min(bc, wc), -impact)
            if best_metric is None or metric < best_metric:
                best_metric = metric
                best_cell = i
                best_order = [1, 0] if bc <= wc else [0, 1]  # 1=black first, 0=white first
            x ^= b

        bit = 1 << best_cell
        for v in best_order:
            if v == 1:
                ans = dfs(black_mask | bit, white_mask)
            else:
                ans = dfs(black_mask, white_mask | bit)
            if ans is not None:
                return ans

        dead.add(key)
        return None

    result = dfs(0, 0)
    if result is None:
        return "No Solution"

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            i = idx(r, c)
            row.append('B' if (result & (1 << i)) else None)
        out.append(row)
    return repr(out)


