from functools import lru_cache

# General solver for the weighted black-cell grid puzzle.
# If row/column weights are not explicitly supplied, default to 1..N as implied by the board labels.

_MASK_CACHE = {}


def generate_masks(weights, target):
    key = (tuple(weights), target)
    if key in _MASK_CACHE:
        return list(_MASK_CACHE[key])

    n = len(weights)
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]

    out = []

    def dfs(i, rem, mask):
        if rem < 0 or rem > suffix[i]:
            return
        if i == n:
            if rem == 0:
                out.append(mask)
            return
        w = weights[i]
        # Skip current position
        dfs(i + 1, rem, mask)
        # Take current position
        if rem >= w:
            dfs(i + 1, rem - w, mask | (1 << i))

    dfs(0, target, 0)
    _MASK_CACHE[key] = tuple(out)
    return list(_MASK_CACHE[key])


def summarize_domains(domains, width):
    limit = (1 << width) - 1
    all1 = []
    any1 = []
    for dom in domains:
        if not dom:
            return None, None
        a = limit
        o = 0
        for m in dom:
            a &= m
            o |= m
        all1.append(a)
        any1.append(o)
    return all1, any1


def propagate(row_domains, col_domains, nrows, ncols):
    row_domains = tuple(tuple(d) for d in row_domains)
    col_domains = tuple(tuple(d) for d in col_domains)

    while True:
        row_all1, row_any1 = summarize_domains(row_domains, ncols)
        if row_all1 is None:
            return None

        col_all1, col_any1 = summarize_domains(col_domains, nrows)
        if col_all1 is None:
            return None

        changed = False

        # Filter row domains using forced/forbidden cell values implied by columns.
        new_rows = []
        for r, dom in enumerate(row_domains):
            bit_r = 1 << r
            need1 = 0
            need0 = 0
            for c in range(ncols):
                bit_c = 1 << c
                if col_all1[c] & bit_r:
                    need1 |= bit_c
                elif not (col_any1[c] & bit_r):
                    need0 |= bit_c

            filtered = tuple(m for m in dom if (m & need0) == 0 and (m & need1) == need1)
            if not filtered:
                return None
            if len(filtered) != len(dom):
                changed = True
            new_rows.append(filtered)
        row_domains = tuple(new_rows)

        row_all1, row_any1 = summarize_domains(row_domains, ncols)
        if row_all1 is None:
            return None

        # Filter column domains using forced/forbidden cell values implied by rows.
        new_cols = []
        for c, dom in enumerate(col_domains):
            bit_c = 1 << c
            need1 = 0
            need0 = 0
            for r in range(nrows):
                bit_r = 1 << r
                if row_all1[r] & bit_c:
                    need1 |= bit_r
                elif not (row_any1[r] & bit_c):
                    need0 |= bit_r

            filtered = tuple(m for m in dom if (m & need0) == 0 and (m & need1) == need1)
            if not filtered:
                return None
            if len(filtered) != len(dom):
                changed = True
            new_cols.append(filtered)
        col_domains = tuple(new_cols)

        if not changed:
            return row_domains, col_domains


def choose_branch(row_domains, col_domains):
    best = None

    for r, dom in enumerate(row_domains):
        if 1 < len(dom) and (best is None or len(dom) < best[0]):
            best = (len(dom), "row", r)

    for c, dom in enumerate(col_domains):
        if 1 < len(dom) and (best is None or len(dom) < best[0]):
            best = (len(dom), "col", c)

    return None if best is None else (best[1], best[2])


def order_row_patterns(r, row_domains, col_domains, nrows, ncols):
    # Prefer patterns that align with rarer column supports, to maximize pruning early.
    support1 = [0] * ncols
    support0 = [0] * ncols
    bit_r = 1 << r
    for c in range(ncols):
        cnt1 = 0
        for m in col_domains[c]:
            if m & bit_r:
                cnt1 += 1
        support1[c] = cnt1
        support0[c] = len(col_domains[c]) - cnt1

    def score(mask):
        s = 0
        for c in range(ncols):
            if (mask >> c) & 1:
                s += support1[c]
            else:
                s += support0[c]
        return s

    return sorted(row_domains[r], key=score)


def order_col_patterns(c, row_domains, col_domains, nrows, ncols):
    support1 = [0] * nrows
    support0 = [0] * nrows
    bit_c = 1 << c
    for r in range(nrows):
        cnt1 = 0
        for m in row_domains[r]:
            if m & bit_c:
                cnt1 += 1
        support1[r] = cnt1
        support0[r] = len(row_domains[r]) - cnt1

    def score(mask):
        s = 0
        for r in range(nrows):
            if (mask >> r) & 1:
                s += support1[r]
            else:
                s += support0[r]
        return s

    return sorted(col_domains[c], key=score)


def validate(row_masks, row_sum, col_sum, row_weights, col_weights):
    nrows = len(row_masks)
    ncols = len(col_sum)

    for r in range(nrows):
        total = 0
        m = row_masks[r]
        for c in range(ncols):
            if (m >> c) & 1:
                total += col_weights[c]
        if total != row_sum[r]:
            return False

    for c in range(ncols):
        total = 0
        bit_c = 1 << c
        for r in range(nrows):
            if row_masks[r] & bit_c:
                total += row_weights[r]
        if total != col_sum[c]:
            return False

    return True


def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]

    nrows = len(row_sum)
    ncols = len(col_sum)

    row_weights = observation.get("row_weights", list(range(1, nrows + 1)))
    col_weights = observation.get("col_weights", list(range(1, ncols + 1)))

    if len(row_weights) != nrows or len(col_weights) != ncols:
        return "No Solution"

    row_domains = [generate_masks(col_weights, target) for target in row_sum]
    col_domains = [generate_masks(row_weights, target) for target in col_sum]

    if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
        return "No Solution"

    failed = set()

    def dfs(rdom, cdom):
        state = propagate(rdom, cdom, nrows, ncols)
        if state is None:
            return None
        rdom, cdom = state

        key = (rdom, cdom)
        if key in failed:
            return None

        branch = choose_branch(rdom, cdom)
        if branch is None:
            row_masks = [dom[0] for dom in rdom]
            if validate(row_masks, row_sum, col_sum, row_weights, col_weights):
                return row_masks
            failed.add(key)
            return None

        kind, idx = branch

        if kind == "row":
            for mask in order_row_patterns(idx, rdom, cdom, nrows, ncols):
                new_rdom = list(rdom)
                new_rdom[idx] = (mask,)
                ans = dfs(tuple(new_rdom), cdom)
                if ans is not None:
                    return ans
        else:
            for mask in order_col_patterns(idx, rdom, cdom, nrows, ncols):
                new_cdom = list(cdom)
                new_cdom[idx] = (mask,)
                ans = dfs(rdom, tuple(new_cdom))
                if ans is not None:
                    return ans

        failed.add(key)
        return None

    row_masks = dfs(tuple(tuple(d) for d in row_domains), tuple(tuple(d) for d in col_domains))
    if row_masks is None:
        return "No Solution"

    grid = []
    for r in range(nrows):
        row = []
        for c in range(ncols):
            row.append("B" if ((row_masks[r] >> c) & 1) else None)
        grid.append(row)

    return str(grid)


