from itertools import combinations

def solve(observation):
    region = observation.get("region")
    data = observation.get("data")
    if not region or not data or len(region) != len(data):
        return "No Solution"

    N = len(data)
    if any(len(row) != N for row in data) or any(len(row) != N for row in region):
        return "No Solution"

    # Normalize region ids by first appearance
    reg_map = {}
    next_id = 0
    reg_of = [0] * (N * N)
    region_units = []
    for r in range(N):
        for c in range(N):
            raw = region[r][c]
            if raw not in reg_map:
                reg_map[raw] = next_id
                region_units.append([])
                next_id += 1
            rid = reg_map[raw]
            idx = r * N + c
            reg_of[idx] = rid
            region_units[rid].append(idx)

    # Basic structural validation
    if len(region_units) != N:
        return "No Solution"
    if any(len(cells) != N for cells in region_units):
        return "No Solution"

    row_units = [[r * N + c for c in range(N)] for r in range(N)]
    col_units = [[r * N + c for r in range(N)] for c in range(N)]
    units = row_units + col_units + region_units

    row_of = [i // N for i in range(N * N)]
    col_of = [i % N for i in range(N * N)]

    peers = []
    for i in range(N * N):
        s = set(row_units[row_of[i]]) | set(col_units[col_of[i]]) | set(region_units[reg_of[i]])
        s.discard(i)
        peers.append(tuple(s))

    ALL = (1 << N) - 1

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def mask_to_value(mask):
        return mask.bit_length()

    def grid_from_cands(cands):
        return [[mask_to_value(cands[r * N + c]) for c in range(N)] for r in range(N)]

    def apply_change(cands, idx, new_mask, queue):
        old = cands[idx]
        if old == new_mask:
            return True, False
        if new_mask == 0:
            return False, False
        cands[idx] = new_mask
        if is_single(new_mask):
            queue.append(idx)
        return True, True

    def propagate(cands):
        queue = [i for i, m in enumerate(cands) if is_single(m)]

        while True:
            # Peer elimination from resolved cells
            while queue:
                i = queue.pop()
                m = cands[i]
                if not is_single(m):
                    continue
                for p in peers[i]:
                    pm = cands[p]
                    if pm & m:
                        new = pm & ~m
                        if new == 0:
                            return None
                        if new != pm:
                            cands[p] = new
                            if is_single(new):
                                queue.append(p)

            progress = False

            # Unit-based checks and deductions
            for unit in units:
                solved_seen = 0
                pos = [[] for _ in range(N)]
                unsolved = []

                for i in unit:
                    m = cands[i]
                    if m == 0:
                        return None
                    if is_single(m):
                        if solved_seen & m:
                            return None
                        solved_seen |= m
                    else:
                        unsolved.append(i)
                    mm = m
                    while mm:
                        b = mm & -mm
                        pos[b.bit_length() - 1].append(i)
                        mm ^= b

                # Hidden singles
                for d in range(N):
                    cells = pos[d]
                    if not cells:
                        return None
                    if len(cells) == 1:
                        bit = 1 << d
                        ok, changed = apply_change(cands, cells[0], bit, queue)
                        if not ok:
                            return None
                        progress |= changed

                # Simple hidden subsets (pairs/triples/quads)
                locmap = {}
                for d in range(N):
                    cells = pos[d]
                    if 1 < len(cells) <= 4:
                        key = tuple(cells)
                        locmap[key] = locmap.get(key, 0) | (1 << d)
                for cells, bits in locmap.items():
                    k = len(cells)
                    if 2 <= k <= 4 and bits.bit_count() == k:
                        for i in cells:
                            new = cands[i] & bits
                            ok, changed = apply_change(cands, i, new, queue)
                            if not ok:
                                return None
                            progress |= changed

                # Naked subsets up to size 4
                if len(unsolved) >= 2:
                    for k in range(2, min(4, len(unsolved)) + 1):
                        candidates = [i for i in unsolved if 2 <= cands[i].bit_count() <= k]
                        if len(candidates) < k:
                            continue
                        seen_unions = set()
                        for combo in combinations(candidates, k):
                            union = 0
                            for i in combo:
                                union |= cands[i]
                            if union.bit_count() != k or union in seen_unions:
                                continue
                            seen_unions.add(union)
                            subset_cells = [i for i in unit if (cands[i] | union) == union]
                            if len(subset_cells) != k:
                                continue
                            subset_set = set(subset_cells)
                            for i in unit:
                                if i not in subset_set and (cands[i] & union):
                                    new = cands[i] & ~union
                                    ok, changed = apply_change(cands, i, new, queue)
                                    if not ok:
                                        return None
                                    progress |= changed

            # Locked candidates: region -> row/col
            for rid, unit in enumerate(region_units):
                pos = [[] for _ in range(N)]
                for i in unit:
                    mm = cands[i]
                    while mm:
                        b = mm & -mm
                        pos[b.bit_length() - 1].append(i)
                        mm ^= b
                for d in range(N):
                    cells = pos[d]
                    if len(cells) <= 1:
                        continue
                    bit = 1 << d

                    rr = row_of[cells[0]]
                    if all(row_of[i] == rr for i in cells[1:]):
                        for j in row_units[rr]:
                            if reg_of[j] != rid and (cands[j] & bit):
                                new = cands[j] & ~bit
                                ok, changed = apply_change(cands, j, new, queue)
                                if not ok:
                                    return None
                                progress |= changed

                    cc = col_of[cells[0]]
                    if all(col_of[i] == cc for i in cells[1:]):
                        for j in col_units[cc]:
                            if reg_of[j] != rid and (cands[j] & bit):
                                new = cands[j] & ~bit
                                ok, changed = apply_change(cands, j, new, queue)
                                if not ok:
                                    return None
                                progress |= changed

            # Locked candidates: row/col -> region
            for unit_list, member_of in ((row_units, row_of), (col_units, col_of)):
                for uid, unit in enumerate(unit_list):
                    pos = [[] for _ in range(N)]
                    for i in unit:
                        mm = cands[i]
                        while mm:
                            b = mm & -mm
                            pos[b.bit_length() - 1].append(i)
                            mm ^= b
                    for d in range(N):
                        cells = pos[d]
                        if len(cells) <= 1:
                            continue
                        rid = reg_of[cells[0]]
                        if all(reg_of[i] == rid for i in cells[1:]):
                            bit = 1 << d
                            for j in region_units[rid]:
                                if member_of[j] != uid and (cands[j] & bit):
                                    new = cands[j] & ~bit
                                    ok, changed = apply_change(cands, j, new, queue)
                                    if not ok:
                                        return None
                                    progress |= changed

            if not progress and not queue:
                break

        return cands

    def choose_branch(cands):
        # Branch on the tightest choice:
        # either a cell with minimal candidates or a digit placement in a unit with minimal positions.
        best_kind = None
        best_payload = None
        best_score = N + 1

        for i, m in enumerate(cands):
            bc = m.bit_count()
            if 1 < bc < best_score:
                best_kind = "cell"
                best_payload = i
                best_score = bc
                if best_score == 2:
                    break

        if best_score > 2:
            for unit in units:
                pos = [[] for _ in range(N)]
                for i in unit:
                    mm = cands[i]
                    while mm:
                        b = mm & -mm
                        pos[b.bit_length() - 1].append(i)
                        mm ^= b
                for d in range(N):
                    cnt = len(pos[d])
                    if 1 < cnt < best_score:
                        best_kind = "digit"
                        best_payload = ((1 << d), pos[d])
                        best_score = cnt
                        if best_score == 2:
                            return best_kind, best_payload

        return best_kind, best_payload

    def search(cands):
        cands = propagate(cands)
        if cands is None:
            return None
        if all(is_single(m) for m in cands):
            return cands

        kind, payload = choose_branch(cands)
        if kind is None:
            return None

        if kind == "digit":
            bit, cells = payload
            ordered = sorted(cells, key=lambda i: sum(1 for p in peers[i] if cands[p] & bit))
            for i in ordered:
                nxt = cands[:]
                nxt[i] = bit
                out = search(nxt)
                if out is not None:
                    return out
            return None

        i = payload
        values = list(iter_bits(cands[i]))
        values.sort(key=lambda b: sum(1 for p in peers[i] if cands[p] & b))
        for bit in values:
            nxt = cands[:]
            nxt[i] = bit
            out = search(nxt)
            if out is not None:
                return out
        return None

    # Initialize candidate masks
    cands = [ALL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= N):
                return "No Solution"
            cands[r * N + c] = 1 << (v - 1)

    result = search(cands)
    if result is None:
        return "No Solution"
    return str(grid_from_cands(result))

