# Weighted black-cell puzzle solver.
# Assumption from the puzzle format:
# - Row weights are 1..R from top to bottom.
# - Column weights are 1..C from left to right.
#
# Human-like solving model implemented here:
# 1. For each row, enumerate all black-cell patterns whose weighted sum matches the row target.
# 2. For each column, enumerate all black-cell patterns whose weighted sum matches the column target.
# 3. Repeatedly propagate:
#    - If every remaining pattern of a row forces a cell black/white, reflect that in the column domains.
#    - If every remaining pattern of a column forces a cell black/white, reflect that in the row domains.
#    - Remove any row/column pattern incompatible with cross-line forced/possible cells.
# 4. Only if deduction stalls, branch on the most constrained row/column.
#
# This avoids naive cell-by-cell brute force.

def _subset_masks_by_weight(count):
    total = 1 << count
    sums = [0] * total
    buckets = {0: [0]}
    for mask in range(1, total):
        lsb = mask & -mask
        idx = lsb.bit_length() - 1
        s = sums[mask ^ lsb] + (idx + 1)
        sums[mask] = s
        if s in buckets:
            buckets[s].append(mask)
        else:
            buckets[s] = [mask]
    return buckets


def _domain_signature(domains):
    return tuple(frozenset(d) for d in domains)


def _propagate(row_domains, col_domains):
    m = len(row_domains)
    n = len(col_domains)
    row_all_bits = (1 << n) - 1
    col_all_bits = (1 << m) - 1

    while True:
        if any(not d for d in row_domains) or any(not d for d in col_domains):
            return None

        row_may = [0] * m
        row_must = [row_all_bits] * m
        for r, domain in enumerate(row_domains):
            may = 0
            must = row_all_bits
            for mask in domain:
                may |= mask
                must &= mask
            row_may[r] = may
            row_must[r] = must

        col_may = [0] * n
        col_must = [col_all_bits] * n
        for c, domain in enumerate(col_domains):
            may = 0
            must = col_all_bits
            for mask in domain:
                may |= mask
                must &= mask
            col_may[c] = may
            col_must[c] = must

        # Immediate contradiction check from forced cells.
        for r in range(m):
            rb = 1 << r
            for c in range(n):
                cb = 1 << c
                if (row_must[r] & cb) and not (col_may[c] & rb):
                    return None
                if not (row_may[r] & cb) and (col_must[c] & rb):
                    return None

        changed = False

        # Filter row patterns by what columns still allow/force at each cell.
        new_row_domains = []
        for r, domain in enumerate(row_domains):
            rb = 1 << r
            required_on = 0
            allowed_on = 0
            for c in range(n):
                cb = 1 << c
                if col_must[c] & rb:
                    required_on |= cb
                if col_may[c] & rb:
                    allowed_on |= cb

            filtered = {mask for mask in domain if (mask & required_on) == required_on and (mask & ~allowed_on) == 0}
            if not filtered:
                return None
            if len(filtered) != len(domain):
                changed = True
            new_row_domains.append(filtered)

        if changed:
            row_domains = new_row_domains
            continue

        # Filter column patterns by what rows still allow/force at each cell.
        new_col_domains = []
        for c, domain in enumerate(col_domains):
            cb = 1 << c
            required_on = 0
            allowed_on = 0
            for r in range(m):
                rb = 1 << r
                if row_must[r] & cb:
                    required_on |= rb
                if row_may[r] & cb:
                    allowed_on |= rb

            filtered = {mask for mask in domain if (mask & required_on) == required_on and (mask & ~allowed_on) == 0}
            if not filtered:
                return None
            if len(filtered) != len(domain):
                changed = True
            new_col_domains.append(filtered)

        if changed:
            col_domains = new_col_domains
            continue

        return row_domains, col_domains


def _search(row_domains, col_domains, seen):
    state_key = (_domain_signature(row_domains), _domain_signature(col_domains))
    if state_key in seen:
        return None

    propagated = _propagate(row_domains, col_domains)
    if propagated is None:
        seen.add(state_key)
        return None

    row_domains, col_domains = propagated

    solved = all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)
    if solved:
        return row_domains, col_domains

    best_kind = None
    best_idx = -1
    best_size = 10**18

    for i, d in enumerate(row_domains):
        ld = len(d)
        if 1 < ld < best_size:
            best_kind = "row"
            best_idx = i
            best_size = ld

    for i, d in enumerate(col_domains):
        ld = len(d)
        if 1 < ld < best_size:
            best_kind = "col"
            best_idx = i
            best_size = ld

    if best_kind is None:
        seen.add(state_key)
        return None

    if best_kind == "row":
        # Deterministic ordering for reproducibility.
        for mask in sorted(row_domains[best_idx], key=lambda x: (x.bit_count(), x)):
            new_rows = [set(d) for d in row_domains]
            new_cols = [set(d) for d in col_domains]
            new_rows[best_idx] = {mask}
            result = _search(new_rows, new_cols, seen)
            if result is not None:
                return result
    else:
        for mask in sorted(col_domains[best_idx], key=lambda x: (x.bit_count(), x)):
            new_rows = [set(d) for d in row_domains]
            new_cols = [set(d) for d in col_domains]
            new_cols[best_idx] = {mask}
            result = _search(new_rows, new_cols, seen)
            if result is not None:
                return result

    seen.add(state_key)
    return None


def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']

    m = len(row_sum)
    n = len(col_sum)

    row_mask_buckets = _subset_masks_by_weight(n)
    col_mask_buckets = _subset_masks_by_weight(m)

    row_domains = []
    for target in row_sum:
        masks = row_mask_buckets.get(target, [])
        if not masks:
            return "No Solution"
        row_domains.append(set(masks))

    col_domains = []
    for target in col_sum:
        masks = col_mask_buckets.get(target, [])
        if not masks:
            return "No Solution"
        col_domains.append(set(masks))

    result = _search(row_domains, col_domains, seen=set())
    if result is None:
        return "No Solution"

    solved_rows, _ = result
    row_masks = [next(iter(d)) for d in solved_rows]

    grid = []
    for r in range(m):
        mask = row_masks[r]
        grid.append(['B' if (mask >> c) & 1 else None for c in range(n)])

    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B', None, None, None, None, 'W', None], [None, 'B', None, None, None, None, 'W', None], [None, None, 'B', None, None, 'B', None, None], [None, None, None, None, None, None, None, None], [None, None, None, 'W', 'B', None, None, None], ['W', None, None, None, None, None, None, 'W'], [None, None, None, 'B', 'W', None, None, None], [None, 'W', None, None, None, None, 'B', None]], 'horizontal': {'(5,1.5)': '='}, 'vertical': {'(0.5,4)': '=', '(1.5,0)': 'x', '(2.5,6)': 'x', '(3.5,2)': '=', '(5.5,5)': '='}}

import ast

W = 1
B = 2
BOTH = 3

MASK_TO_CHAR = {W: 'W', B: 'B'}
CHAR_TO_MASK = {'W': W, 'B': B, None: BOTH}


def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return "No Solution"

    R = len(data)
    C = len(data[0])

    if any(len(row) != C for row in data):
        return "No Solution"
    if R % 2 != 0 or C % 2 != 0:
        return "No Solution"

    def norm_cell(x):
        if x is None:
            return None
        s = str(x).upper()
        if s in ('B', 'W'):
            return s
        raise ValueError("Bad cell value")

    def parse_key(k):
        if isinstance(k, str):
            return ast.literal_eval(k)
        return k

    # Edge constraints as cell-indexed pairs:
    # horizontal[(r, c)] is relation between (r, c) and (r, c+1)
    # vertical[(r, c)] is relation between (r, c) and (r+1, c)
    horizontal = {}
    for k, rel in observation.get('horizontal', {}).items():
        r, c_half = parse_key(k)
        r = int(round(float(r)))
        c = int(round(float(c_half) - 0.5))
        if 0 <= r < R and 0 <= c < C - 1 and rel in ('=', 'x'):
            horizontal[(r, c)] = rel

    vertical = {}
    for k, rel in observation.get('vertical', {}).items():
        r_half, c = parse_key(k)
        r = int(round(float(r_half) - 0.5))
        c = int(round(float(c)))
        if 0 <= r < R - 1 and 0 <= c < C and rel in ('=', 'x'):
            vertical[(r, c)] = rel

    # Per-line adjacency constraints
    row_cons = []
    for r in range(R):
        cons = [None] * (C - 1)
        for c in range(C - 1):
            if (r, c) in horizontal:
                cons[c] = horizontal[(r, c)]
        row_cons.append(tuple(cons))

    col_cons = []
    for c in range(C):
        cons = [None] * (R - 1)
        for r in range(R - 1):
            if (r, c) in vertical:
                cons[r] = vertical[(r, c)]
        col_cons.append(tuple(cons))

    # Initial domains
    try:
        domains = []
        for r in range(R):
            row = []
            for c in range(C):
                cell = norm_cell(data[r][c])
                row.append(CHAR_TO_MASK[cell])
            domains.append(row)
    except Exception:
        return "No Solution"

    # Base valid line patterns: balanced + no 3 consecutive
    base_patterns_cache = {}

    def base_patterns(length):
        if length in base_patterns_cache:
            return base_patterns_cache[length]
        if length % 2 != 0:
            base_patterns_cache[length] = []
            return []

        target_b = length // 2
        out = []

        def rec(pat, count_b):
            pos = len(pat)
            rem = length - pos

            if count_b > target_b:
                return
            if count_b + rem < target_b:
                return

            if pos == length:
                if count_b == target_b:
                    out.append(tuple(pat))
                return

            for v in (0, 1):  # 0=W, 1=B
                if pos >= 2 and pat[-1] == pat[-2] == v:
                    continue
                pat.append(v)
                rec(pat, count_b + (1 if v == 1 else 0))
                pat.pop()

        rec([], 0)
        base_patterns_cache[length] = out
        return out

    line_cache = {}

    def line_possibilities(dom_line, cons):
        key = (len(dom_line), tuple(dom_line), cons)
        if key in line_cache:
            return line_cache[key]

        poss = []
        unions = [0] * len(dom_line)

        for pat in base_patterns(len(dom_line)):
            ok = True

            for i, v in enumerate(pat):
                need = B if v == 1 else W
                if dom_line[i] & need == 0:
                    ok = False
                    break
            if not ok:
                continue

            for i, rel in enumerate(cons):
                if rel is None:
                    continue
                if rel == '=' and pat[i] != pat[i + 1]:
                    ok = False
                    break
                if rel == 'x' and pat[i] == pat[i + 1]:
                    ok = False
                    break
            if not ok:
                continue

            poss.append(pat)
            for i, v in enumerate(pat):
                unions[i] |= (B if v == 1 else W)

        res = (poss, tuple(unions))
        line_cache[key] = res
        return res

    h_edges = list(horizontal.items())
    v_edges = list(vertical.items())

    def reduce_pair(a, b, rel):
        if rel == '=':
            na = a & b
            nb = b & a
            return na, nb

        # rel == 'x'
        if b == BOTH:
            na = a
        elif b == W:
            na = a & B
        else:
            na = a & W

        if a == BOTH:
            nb = b
        elif a == W:
            nb = b & B
        else:
            nb = b & W

        return na, nb

    def propagate(dom):
        row_opts = None
        col_opts = None

        while True:
            changed = False

            # Binary edge consistency
            for (r, c), rel in h_edges:
                a = dom[r][c]
                b = dom[r][c + 1]
                na, nb = reduce_pair(a, b, rel)
                if na == 0 or nb == 0:
                    return None, None, None
                if na != a:
                    dom[r][c] = na
                    changed = True
                if nb != b:
                    dom[r][c + 1] = nb
                    changed = True

            for (r, c), rel in v_edges:
                a = dom[r][c]
                b = dom[r + 1][c]
                na, nb = reduce_pair(a, b, rel)
                if na == 0 or nb == 0:
                    return None, None, None
                if na != a:
                    dom[r][c] = na
                    changed = True
                if nb != b:
                    dom[r + 1][c] = nb
                    changed = True

            # Row filtering by all legal row completions
            row_opts = [None] * R
            for r in range(R):
                poss, unions = line_possibilities(tuple(dom[r]), row_cons[r])
                if not poss:
                    return None, None, None
                row_opts[r] = poss
                for c in range(C):
                    nd = dom[r][c] & unions[c]
                    if nd == 0:
                        return None, None, None
                    if nd != dom[r][c]:
                        dom[r][c] = nd
                        changed = True

            # Column filtering by all legal column completions
            col_opts = [None] * C
            for c in range(C):
                col_dom = tuple(dom[r][c] for r in range(R))
                poss, unions = line_possibilities(col_dom, col_cons[c])
                if not poss:
                    return None, None, None
                col_opts[c] = poss
                for r in range(R):
                    nd = dom[r][c] & unions[r]
                    if nd == 0:
                        return None, None, None
                    if nd != dom[r][c]:
                        dom[r][c] = nd
                        changed = True

            if not changed:
                return dom, row_opts, col_opts

    dead_states = set()

    def solved(dom):
        for row in dom:
            for v in row:
                if v == BOTH:
                    return False
        return True

    def search(dom):
        dom = [row[:] for row in dom]
        dom, row_opts, col_opts = propagate(dom)
        if dom is None:
            return None

        sig = tuple(tuple(row) for row in dom)
        if sig in dead_states:
            return None

        if solved(dom):
            return dom

        # If a row/column has very few whole-line possibilities, branch on it.
        best_line = None  # (count, kind, idx)
        for r in range(R):
            k = len(row_opts[r])
            if 1 < k and (best_line is None or k < best_line[0]):
                best_line = (k, 'row', r)
        for c in range(C):
            k = len(col_opts[c])
            if 1 < k and (best_line is None or k < best_line[0]):
                best_line = (k, 'col', c)

        if best_line is not None and best_line[0] <= 2:
            _, kind, idx = best_line
            options = row_opts[idx] if kind == 'row' else col_opts[idx]
            for pat in options:
                new_dom = [row[:] for row in dom]
                if kind == 'row':
                    for c, v in enumerate(pat):
                        new_dom[idx][c] = B if v == 1 else W
                else:
                    for r, v in enumerate(pat):
                        new_dom[r][idx] = B if v == 1 else W
                ans = search(new_dom)
                if ans is not None:
                    return ans
            dead_states.add(sig)
            return None

        # Otherwise branch on the most constrained cell.
        best = None
        best_score = None
        best_order = None

        for r in range(R):
            for c in range(C):
                if dom[r][c] != BOTH:
                    continue

                ro = row_opts[r]
                co = col_opts[c]

                rb = sum(1 for p in ro if p[c] == 1)
                rw = len(ro) - rb
                cb = sum(1 for p in co if p[r] == 1)
                cw = len(co) - cb

                support_b = rb * cb
                support_w = rw * cw

                score = (
                    len(ro) * len(co),
                    min(support_b, support_w),
                    abs(support_b - support_w),
                )

                if best_score is None or score < best_score:
                    best_score = score
                    best = (r, c)
                    best_order = [B, W] if support_b < support_w else [W, B]

        if best is None:
            dead_states.add(sig)
            return None

        r, c = best
        for val in best_order:
            new_dom = [row[:] for row in dom]
            new_dom[r][c] = val
            ans = search(new_dom)
            if ans is not None:
                return ans

        dead_states.add(sig)
        return None

    ans = search(domains)
    if ans is None:
        return "No Solution"

    out = [[MASK_TO_CHAR[v] for v in row] for row in ans]
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 1, 2, 2], [3, 3, 4, 5, 6, 6], [3, 3, 4, 7, 6, 6], [3, 3, 8, 8, 6, 6], [3, 3, 8, 8, 9, 9], [3, 3, 10, 10, 10, 10]], 'data': [[None, None, None, None, 1, None], [3, None, 0, None, 1, None], [None, None, None, 1, None, None], [None, None, 1, None, None, None], [None, None, None, None, 1, None], [None, None, 1, None, None, None]]}

from functools import lru_cache

UNKNOWN = -1
WHITE = 0
BLACK = 1


class Solver:
    def __init__(self, observation):
        self.region_grid = observation["region"]
        self.data_grid = observation["data"]
        self.n = len(self.region_grid)
        self.m = self.n * self.n

        self.idx_of = lambda r, c: r * self.n + c
        self.rc_of = lambda i: (i // self.n, i % self.n)

        self.region_of = [0] * self.m
        self.neigh = [[] for _ in range(self.m)]
        self.rows = []
        self.cols = []

        for r in range(self.n):
            row = []
            for c in range(self.n):
                i = self.idx_of(r, c)
                row.append(i)
                self.region_of[i] = self.region_grid[r][c]
                if r > 0:
                    self.neigh[i].append(self.idx_of(r - 1, c))
                if r + 1 < self.n:
                    self.neigh[i].append(self.idx_of(r + 1, c))
                if c > 0:
                    self.neigh[i].append(self.idx_of(r, c - 1))
                if c + 1 < self.n:
                    self.neigh[i].append(self.idx_of(r, c + 1))
            self.rows.append(row)

        for c in range(self.n):
            col = []
            for r in range(self.n):
                col.append(self.idx_of(r, c))
            self.cols.append(col)

        self.regions = {}
        for i, rid in enumerate(self.region_of):
            self.regions.setdefault(rid, []).append(i)

        self.region_clue = {rid: None for rid in self.regions}
        for r in range(self.n):
            for c in range(self.n):
                v = self.data_grid[r][c]
                if v is not None:
                    rid = self.region_grid[r][c]
                    if self.region_clue[rid] is None:
                        self.region_clue[rid] = v
                    elif self.region_clue[rid] != v:
                        raise ValueError("Conflicting clues in one region")

        self.numbered_regions = [(rid, self.region_clue[rid]) for rid in self.regions if self.region_clue[rid] is not None]

        self.lines = []
        for row in self.rows:
            self.lines.append((row, tuple(self.region_of[i] for i in row)))
        for col in self.cols:
            self.lines.append((col, tuple(self.region_of[i] for i in col)))

        self.region_local_adj = {}
        self.region_local_conflict = {}
        for rid, cells in self.regions.items():
            local_index = {g: i for i, g in enumerate(cells)}
            adj = [0] * len(cells)
            conf = [0] * len(cells)
            for i, g in enumerate(cells):
                mask = 0
                for nb in self.neigh[g]:
                    if nb in local_index:
                        mask |= 1 << local_index[nb]
                adj[i] = mask
                conf[i] = mask | (1 << i)
            self.region_local_adj[rid] = adj
            self.region_local_conflict[rid] = conf

        self.line_cache = {}
        self.region_cache = {}

        self.boundary_score = [0] * self.m
        for i in range(self.m):
            rid = self.region_of[i]
            score = 0
            for nb in self.neigh[i]:
                if self.region_of[nb] != rid:
                    score += 1
            self.boundary_score[i] = score

    def _force(self, state, idx, val, pending):
        cur = state[idx]
        if cur == val:
            return 0
        if cur != UNKNOWN:
            return -1
        state[idx] = val
        pending.append(idx)
        return 1

    def _line_white_next(self, prev, rid):
        tag = prev[0]
        if tag == "S" or tag == "B":
            return ("W1", rid)
        if tag == "W1":
            a = prev[1]
            if rid == a:
                return prev
            return ("W2", a, rid) if a < rid else ("W2", rid, a)
        a, b = prev[1], prev[2]
        if rid == a or rid == b:
            return prev
        return None

    def line_support(self, line_id, domains):
        key = (line_id, domains)
        if key in self.line_cache:
            return self.line_cache[key]

        cells, regseq = self.lines[line_id]
        length = len(cells)

        @lru_cache(None)
        def feasible(pos, prev):
            if pos == length:
                return True

            d = domains[pos]
            rid = regseq[pos]

            if d != WHITE and prev[0] != "B":
                if feasible(pos + 1, ("B",)):
                    return True

            if d != BLACK:
                nxt = self._line_white_next(prev, rid)
                if nxt is not None and feasible(pos + 1, nxt):
                    return True

            return False

        if not feasible(0, ("S",)):
            self.line_cache[key] = None
            return None

        can_white = 0
        can_black = 0
        seen = set()

        def walk(pos, prev):
            nonlocal can_white, can_black
            if pos == length:
                return
            stamp = (pos, prev)
            if stamp in seen:
                return
            seen.add(stamp)

            d = domains[pos]
            rid = regseq[pos]

            if d != WHITE and prev[0] != "B":
                nxt = ("B",)
                if feasible(pos + 1, nxt):
                    can_black |= 1 << pos
                    walk(pos + 1, nxt)

            if d != BLACK:
                nxt = self._line_white_next(prev, rid)
                if nxt is not None and feasible(pos + 1, nxt):
                    can_white |= 1 << pos
                    walk(pos + 1, nxt)

        walk(0, ("S",))
        out = (can_white, can_black)
        self.line_cache[key] = out
        return out

    def region_support(self, rid, domains):
        key = (rid, domains)
        if key in self.region_cache:
            return self.region_cache[key]

        clue = self.region_clue[rid]
        cells = self.regions[rid]
        size = len(cells)
        adj = self.region_local_adj[rid]
        conf = self.region_local_conflict[rid]

        fixed_black = 0
        fixed_white = 0
        for i, d in enumerate(domains):
            if d == BLACK:
                fixed_black |= 1 << i
            elif d == WHITE:
                fixed_white |= 1 << i

        for i in range(size):
            if (fixed_black >> i) & 1:
                if adj[i] & fixed_black:
                    self.region_cache[key] = None
                    return None

        need = clue - fixed_black.bit_count()
        if need < 0:
            self.region_cache[key] = None
            return None

        avail = 0
        for i, d in enumerate(domains):
            if d == UNKNOWN:
                avail |= 1 << i

        if need > avail.bit_count():
            self.region_cache[key] = None
            return None

        best_union = 0
        best_inter = 0
        found = False

        def choose_vertex(mask):
            best_v = None
            best_deg = -1
            mm = mask
            while mm:
                b = mm & -mm
                v = b.bit_length() - 1
                deg = (adj[v] & mask).bit_count()
                if deg > best_deg:
                    best_deg = deg
                    best_v = v
                mm ^= b
            return best_v

        def rec(avail_mask, need_left, picked_mask):
            nonlocal best_union, best_inter, found
            if need_left == 0:
                sol = fixed_black | picked_mask
                if not found:
                    best_union = sol
                    best_inter = sol
                    found = True
                else:
                    best_union |= sol
                    best_inter &= sol
                return
            if avail_mask == 0:
                return
            if avail_mask.bit_count() < need_left:
                return

            v = choose_vertex(avail_mask)
            bit = 1 << v

            rec(avail_mask & ~conf[v], need_left - 1, picked_mask | bit)
            rec(avail_mask & ~bit, need_left, picked_mask)

        rec(avail, need, 0)

        if not found:
            self.region_cache[key] = None
            return None

        out = (best_union, best_inter)
        self.region_cache[key] = out
        return out

    def connectivity_filter(self, state, pending):
        open_cells = [i for i, v in enumerate(state) if v != BLACK]
        if not open_cells:
            return False, False

        open_set = set(open_cells)
        comps = []
        seen = set()

        for start in open_cells:
            if start in seen:
                continue
            stack = [start]
            seen.add(start)
            comp = []
            while stack:
                x = stack.pop()
                comp.append(x)
                for nb in self.neigh[x]:
                    if nb in open_set and nb not in seen:
                        seen.add(nb)
                        stack.append(nb)
            comps.append(comp)

        white_comp_ids = []
        for ci, comp in enumerate(comps):
            if any(state[x] == WHITE for x in comp):
                white_comp_ids.append(ci)

        changed = False
        main_comp = None

        if white_comp_ids:
            if len(white_comp_ids) > 1:
                return False, False
            main_idx = white_comp_ids[0]
            main_comp = comps[main_idx]
            for ci, comp in enumerate(comps):
                if ci == main_idx:
                    continue
                if len(comp) > 1:
                    return False, False
                x = comp[0]
                r = self._force(state, x, BLACK, pending)
                if r < 0:
                    return False, False
                if r > 0:
                    changed = True
        else:
            big = [comp for comp in comps if len(comp) > 1]
            if len(big) > 1:
                return False, False
            if len(big) == 1:
                main_comp = big[0]
                big_set = set(main_comp)
                for comp in comps:
                    if comp[0] in big_set:
                        continue
                    if len(comp) > 1:
                        return False, False
                    x = comp[0]
                    r = self._force(state, x, BLACK, pending)
                    if r < 0:
                        return False, False
                    if r > 0:
                        changed = True

        if pending:
            return True, changed

        if main_comp is None:
            return True, changed

        main_set = set(main_comp)
        whites_exist = any(state[i] == WHITE for i in range(self.m))

        for cut in main_comp:
            if state[cut] != UNKNOWN:
                continue

            rem_seen = set()
            live = 0

            for start in main_comp:
                if start == cut or start in rem_seen or state[start] == BLACK:
                    continue
                stack = [start]
                rem_seen.add(start)
                comp = []
                while stack:
                    x = stack.pop()
                    comp.append(x)
                    for nb in self.neigh[x]:
                        if nb != cut and nb in main_set and state[nb] != BLACK and nb not in rem_seen:
                            rem_seen.add(nb)
                            stack.append(nb)

                if whites_exist:
                    if any(state[x] == WHITE for x in comp) or len(comp) > 1:
                        live += 1
                else:
                    if len(comp) > 1:
                        live += 1

                if live > 1:
                    r = self._force(state, cut, WHITE, pending)
                    if r < 0:
                        return False, False
                    if r > 0:
                        changed = True
                    break

        return True, changed

    def propagate(self, state, initial_pending=None):
        pending = list(initial_pending or [])

        while True:
            made = False

            while pending:
                made = True
                idx = pending.pop()
                if state[idx] == BLACK:
                    for nb in self.neigh[idx]:
                        r = self._force(state, nb, WHITE, pending)
                        if r < 0:
                            return False

            for rid, clue in self.numbered_regions:
                cells = self.regions[rid]
                blacks = 0
                unknowns = []
                for i in cells:
                    if state[i] == BLACK:
                        blacks += 1
                    elif state[i] == UNKNOWN:
                        unknowns.append(i)
                if blacks > clue or blacks + len(unknowns) < clue:
                    return False
                if blacks == clue:
                    for i in unknowns:
                        r = self._force(state, i, WHITE, pending)
                        if r < 0:
                            return False
                        if r > 0:
                            made = True
                elif blacks + len(unknowns) == clue:
                    for i in unknowns:
                        r = self._force(state, i, BLACK, pending)
                        if r < 0:
                            return False
                        if r > 0:
                            made = True

            if pending:
                continue

            for rid, clue in self.numbered_regions:
                cells = self.regions[rid]
                domains = tuple(state[i] for i in cells)
                if UNKNOWN not in domains:
                    continue
                sup = self.region_support(rid, domains)
                if sup is None:
                    return False
                union_black, inter_black = sup
                for li, gi in enumerate(cells):
                    if state[gi] != UNKNOWN:
                        continue
                    can_b = (union_black >> li) & 1
                    must_b = (inter_black >> li) & 1
                    if not can_b:
                        r = self._force(state, gi, WHITE, pending)
                        if r < 0:
                            return False
                        if r > 0:
                            made = True
                    elif must_b:
                        r = self._force(state, gi, BLACK, pending)
                        if r < 0:
                            return False
                        if r > 0:
                            made = True

            if pending:
                continue

            for line_id, (cells, _) in enumerate(self.lines):
                domains = tuple(state[i] for i in cells)
                sup = self.line_support(line_id, domains)
                if sup is None:
                    return False
                can_white, can_black = sup
                for pos, gi in enumerate(cells):
                    if state[gi] != UNKNOWN:
                        continue
                    w = (can_white >> pos) & 1
                    b = (can_black >> pos) & 1
                    if not w and not b:
                        return False
                    if w and not b:
                        r = self._force(state, gi, WHITE, pending)
                        if r < 0:
                            return False
                        if r > 0:
                            made = True
                    elif b and not w:
                        r = self._force(state, gi, BLACK, pending)
                        if r < 0:
                            return False
                        if r > 0:
                            made = True

            if pending:
                continue

            ok, changed = self.connectivity_filter(state, pending)
            if not ok:
                return False
            if changed:
                made = True

            if pending:
                continue

            if not made:
                return True

    def heuristic_score(self, state, idx):
        score = 0
        rid = self.region_of[idx]
        clue = self.region_clue[rid]
        if clue is not None:
            cells = self.regions[rid]
            undec = 0
            blacks = 0
            for x in cells:
                if state[x] == UNKNOWN:
                    undec += 1
                elif state[x] == BLACK:
                    blacks += 1
            need = clue - blacks
            score += 100
            score += 20 - undec
            score += max(0, 12 - 3 * abs(undec - 2 * need))
        score += 4 * sum(1 for nb in self.neigh[idx] if state[nb] == UNKNOWN)
        score += 3 * self.boundary_score[idx]
        return score

    def choose_branch(self, state):
        unknowns = [i for i, v in enumerate(state) if v == UNKNOWN]
        if not unknowns:
            return None

        ranked = sorted(unknowns, key=lambda i: self.heuristic_score(state, i), reverse=True)
        ranked = ranked[: min(6, len(ranked))]

        best = None
        best_metric = None

        for idx in ranked:
            outcomes = {}
            fails = []

            for val in (BLACK, WHITE):
                st = state.copy()
                pending = []
                r = self._force(st, idx, val, pending)
                if r < 0 or not self.propagate(st, pending):
                    fails.append(val)
                else:
                    outcomes[val] = st

            if len(fails) == 2:
                continue

            if len(fails) == 1:
                good = WHITE if fails[0] == BLACK else BLACK
                return idx, [good]

            ub = sum(1 for v in outcomes[BLACK] if v == UNKNOWN)
            uw = sum(1 for v in outcomes[WHITE] if v == UNKNOWN)
            metric = (ub + uw, max(ub, uw))
            order = [BLACK, WHITE] if ub <= uw else [WHITE, BLACK]

            if best_metric is None or metric < best_metric:
                best_metric = metric
                best = (idx, order)

        if best is not None:
            return best

        idx = ranked[0]
        rid = self.region_of[idx]
        clue = self.region_clue[rid]
        if clue is not None:
            cells = self.regions[rid]
            blacks = sum(1 for x in cells if state[x] == BLACK)
            undec = sum(1 for x in cells if state[x] == UNKNOWN)
            need = clue - blacks
            if need * 2 >= undec:
                return idx, [BLACK, WHITE]
        return idx, [WHITE, BLACK]

    def is_complete(self, state):
        return all(v != UNKNOWN for v in state)

    def validate(self, state):
        if any(v == UNKNOWN for v in state):
            return False

        for i, v in enumerate(state):
            if v == BLACK:
                for nb in self.neigh[i]:
                    if state[nb] == BLACK:
                        return False

        for rid, clue in self.numbered_regions:
            cnt = sum(1 for i in self.regions[rid] if state[i] == BLACK)
            if cnt != clue:
                return False

        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return False

        seen = {whites[0]}
        stack = [whites[0]]
        while stack:
            x = stack.pop()
            for nb in self.neigh[x]:
                if state[nb] == WHITE and nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
        if len(seen) != len(whites):
            return False

        for cells, _ in self.lines:
            j = 0
            while j < len(cells):
                if state[cells[j]] == BLACK:
                    j += 1
                    continue
                regs = set()
                while j < len(cells) and state[cells[j]] == WHITE:
                    regs.add(self.region_of[cells[j]])
                    if len(regs) > 2:
                        return False
                    j += 1

        return True

    def search(self, state):
        if self.is_complete(state):
            return state if self.validate(state) else None

        choice = self.choose_branch(state)
        if choice is None:
            return state if self.validate(state) else None

        idx, values = choice
        for val in values:
            st = state.copy()
            pending = []
            r = self._force(st, idx, val, pending)
            if r < 0:
                continue
            if not self.propagate(st, pending):
                continue
            ans = self.search(st)
            if ans is not None:
                return ans
        return None

    def format_answer(self, state):
        out = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                v = state[self.idx_of(r, c)]
                row.append('B' if v == BLACK else None)
            out.append(row)
        return out


def solve(observation):
    solver = Solver(observation)
    state = [UNKNOWN] * solver.m
    if not solver.propagate(state):
        return "No Solution"
    ans = solver.search(state)
    if ans is None:
        return "No Solution"
    return solver.format_answer(ans)


