    print(solve(OBSERVATION))

OBSERVATION = {'data': [['B3', None, None, 'B5', 'W2', None], [None, None, None, None, 'B3', None], ['B2', None, None, None, None, None], [None, None, None, None, None, None], [None, 'B2', None, 'B2', None, 'B2'], ['B3', None, None, None, None, None]]}

# General solver for a single-loop orthogonal puzzle on dot grids:
# - vertices are grid dots
# - each used vertex has degree 2
# - white clue => straight-through
# - black clue => turn
# - number k => sum of distances from the clue along its two incident directions
#   until the next turn on each side
#
# The solver uses:
# - vertex-state domains
# - edge arc-consistency
# - clue-distance feasibility propagation
# - forced-cycle contradiction checks
# - depth-first search with strong propagation

U, R, D, L = 1, 2, 4, 8
OPP = {U: D, D: U, L: R, R: L}

EMPTY = 0
H = L | R
V = U | D
UR = U | R
UL = U | L
DR = D | R
DL = D | L

STATES = [EMPTY, H, V, UR, UL, DR, DL]
SBIT = {s: 1 << i for i, s in enumerate(STATES)}
BIT_TO_STATE = {1 << i: s for i, s in enumerate(STATES)}
ALL_DOM = (1 << len(STATES)) - 1

TURN_STATES = (UR, UL, DR, DL)
STATE_DIRS = {
    H: (L, R),
    V: (U, D),
    UR: (U, R),
    UL: (U, L),
    DR: (D, R),
    DL: (D, L),
}
DIRS = (U, R, D, L)

WITH_EDGE_BITS = {}
NO_EDGE_BITS = {}
STRAIGHT_BITS = {
    U: SBIT[V],
    D: SBIT[V],
    L: SBIT[H],
    R: SBIT[H],
}
TURN_IN_BITS = {}
for d in DIRS:
    bits = 0
    turn_in = 0
    for s in STATES:
        if s & d:
            bits |= SBIT[s]
        if s in TURN_STATES and (s & OPP[d]):
            turn_in |= SBIT[s]
    WITH_EDGE_BITS[d] = bits
    NO_EDGE_BITS[d] = ALL_DOM ^ bits
    TURN_IN_BITS[d] = turn_in

WHITE_BITS = SBIT[H] | SBIT[V]
BLACK_BITS = SBIT[UR] | SBIT[UL] | SBIT[DR] | SBIT[DL]
EMPTY_BIT = SBIT[EMPTY]


def iter_states(dom):
    for s in STATES:
        if dom & SBIT[s]:
            yield s


def only_state(dom):
    return BIT_TO_STATE[dom & -dom]


def build_puzzle(observation):
    data = observation["data"]
    rows = len(data)
    cols = len(data[0]) if rows else 0
    n = rows * cols

    neighbors = [{U: -1, R: -1, D: -1, L: -1} for _ in range(n)]
    for r in range(rows):
        for c in range(cols):
            i = r * cols + c
            if r > 0:
                neighbors[i][U] = (r - 1) * cols + c
            if r + 1 < rows:
                neighbors[i][D] = (r + 1) * cols + c
            if c > 0:
                neighbors[i][L] = r * cols + (c - 1)
            if c + 1 < cols:
                neighbors[i][R] = r * cols + (c + 1)

    clues = []
    clue_map = {}
    clue_set = set()
    for r in range(rows):
        for c in range(cols):
            tok = data[r][c]
            if tok is None:
                continue
            typ = tok[0]
            k = int(tok[1:])
            idx = r * cols + c
            clues.append((idx, typ, k))
            clue_map[idx] = (typ, k)
            clue_set.add(idx)

    return {
        "rows": rows,
        "cols": cols,
        "n": n,
        "neighbors": neighbors,
        "clues": clues,
        "clue_map": clue_map,
        "clue_set": clue_set,
    }


def initial_domains(puzzle):
    rows = puzzle["rows"]
    cols = puzzle["cols"]
    n = puzzle["n"]
    neighbors = puzzle["neighbors"]
    clue_map = puzzle["clue_map"]

    domains = [ALL_DOM] * n
    for r in range(rows):
        for c in range(cols):
            i = r * cols + c
            dom = ALL_DOM
            for d in DIRS:
                if neighbors[i][d] == -1:
                    dom &= NO_EDGE_BITS[d]
            if i in clue_map:
                typ, _ = clue_map[i]
                if typ == "W":
                    dom &= WHITE_BITS
                else:
                    dom &= BLACK_BITS
            domains[i] = dom
            if dom == 0:
                return None
    return domains


def advance(puzzle, idx, d, dist):
    cur = idx
    for _ in range(dist):
        cur = puzzle["neighbors"][cur][d]
        if cur == -1:
            return -1
    return cur


def feasible_dists(domains, puzzle, idx, d):
    neighbors = puzzle["neighbors"]
    cur = idx
    res = []
    while True:
        cur = neighbors[cur][d]
        if cur == -1:
            break
        if domains[cur] & TURN_IN_BITS[d]:
            res.append(len(res) + 1 if False else 0)  # overwritten below
        # This branch keeps a compact loop while still storing exact t.
        if not (domains[cur] & STRAIGHT_BITS[d]):
            break

    # Recompute exact distances in a second tiny pass for correctness/readability.
    cur = idx
    t = 0
    exact = []
    while True:
        cur = neighbors[cur][d]
        if cur == -1:
            break
        t += 1
        if domains[cur] & TURN_IN_BITS[d]:
            exact.append(t)
        if not (domains[cur] & STRAIGHT_BITS[d]):
            break
    return exact


def feasible_pairs(domains, puzzle, idx, state, k):
    dirs = STATE_DIRS[state]
    d1, d2 = dirs[0], dirs[1]
    f1 = feasible_dists(domains, puzzle, idx, d1)
    f2 = feasible_dists(domains, puzzle, idx, d2)
    if not f1 or not f2:
        return []
    set_f2 = set(f2)
    pairs = []
    for a in f1:
        b = k - a
        if b in set_f2:
            pairs.append((a, b))
    return pairs


def forced_cycle_contradiction(domains, puzzle):
    n = puzzle["n"]
    neighbors = puzzle["neighbors"]
    clue_set = puzzle["clue_set"]

    forced_adj = [[] for _ in range(n)]
    forced_deg = [0] * n

    for i in range(n):
        for d in (R, D):
            j = neighbors[i][d]
            if j == -1:
                continue
            if (domains[i] & NO_EDGE_BITS[d]) == 0 and (domains[j] & NO_EDGE_BITS[OPP[d]]) == 0:
                forced_adj[i].append(j)
                forced_adj[j].append(i)
                forced_deg[i] += 1
                forced_deg[j] += 1

    seen = [False] * n
    must_used = {i for i, dom in enumerate(domains) if not (dom & EMPTY_BIT)}

    for i in range(n):
        if seen[i] or forced_deg[i] == 0:
            continue
        stack = [i]
        seen[i] = True
        comp = []
        while stack:
            v = stack.pop()
            comp.append(v)
            for w in forced_adj[v]:
                if not seen[w]:
                    seen[w] = True
                    stack.append(w)

        if all(forced_deg[v] == 2 for v in comp):
            comp_set = set(comp)
            if not clue_set.issubset(comp_set):
                return True
            if any(v not in comp_set for v in must_used):
                return True

    return False


def propagate(domains, puzzle):
    clues = puzzle["clues"]
    neighbors = puzzle["neighbors"]
    n = puzzle["n"]

    while True:
        changed = False

        # Arc consistency on edges.
        for i in range(n):
            domi = domains[i]
            if domi == 0:
                return None
            for d in DIRS:
                j = neighbors[i][d]
                if j == -1:
                    new_domi = domi & NO_EDGE_BITS[d]
                else:
                    domj = domains[j]
                    allow_in = bool(domj & WITH_EDGE_BITS[OPP[d]])
                    allow_out = bool(domj & NO_EDGE_BITS[OPP[d]])
                    mask = 0
                    if allow_in:
                        mask |= WITH_EDGE_BITS[d]
                    if allow_out:
                        mask |= NO_EDGE_BITS[d]
                    new_domi = domi & mask
                if new_domi != domi:
                    domains[i] = domi = new_domi
                    changed = True
                    if domi == 0:
                        return None

        # Clue support.
        cache = {}
        for idx, typ, k in clues:
            dom = domains[idx]
            supported = 0
            info = {}
            for s in iter_states(dom):
                if typ == "W" and s not in (H, V):
                    continue
                if typ == "B" and s not in TURN_STATES:
                    continue
                pairs = feasible_pairs(domains, puzzle, idx, s, k)
                if pairs:
                    supported |= SBIT[s]
                    info[s] = pairs
            new_dom = dom & supported
            if new_dom != dom:
                domains[idx] = new_dom
                changed = True
                if new_dom == 0:
                    return None
            cache[idx] = info

        # Stronger local deductions for singleton clues.
        for idx, typ, k in clues:
            dom = domains[idx]
            if dom.bit_count() != 1:
                continue
            s = only_state(dom)
            info = cache.get(idx, {})
            pairs = info.get(s)
            if pairs is None:
                pairs = feasible_pairs(domains, puzzle, idx, s, k)
            if not pairs:
                return None

            d1, d2 = STATE_DIRS[s]
            poss1 = sorted({a for a, _ in pairs})
            poss2 = sorted({b for _, b in pairs})

            for d, poss in ((d1, poss1), (d2, poss2)):
                min_dist = poss[0]
                cur = idx
                for _ in range(1, min_dist):
                    cur = neighbors[cur][d]
                    new_dom = domains[cur] & STRAIGHT_BITS[d]
                    if new_dom != domains[cur]:
                        domains[cur] = new_dom
                        changed = True
                        if new_dom == 0:
                            return None

                if len(poss) == 1:
                    end = advance(puzzle, idx, d, poss[0])
                    if end == -1:
                        return None
                    new_dom = domains[end] & TURN_IN_BITS[d]
                    if new_dom != domains[end]:
                        domains[end] = new_dom
                        changed = True
                        if new_dom == 0:
                            return None

        if forced_cycle_contradiction(domains, puzzle):
            return None

        if not changed:
            return domains


def choose_var(domains, puzzle):
    clue_set = puzzle["clue_set"]
    neighbors = puzzle["neighbors"]

    best = None
    best_key = None
    for i, dom in enumerate(domains):
        bc = dom.bit_count()
        if bc <= 1:
            continue
        deg = sum(1 for d in DIRS if neighbors[i][d] != -1)
        key = (
            bc,
            0 if i in clue_set else 1,
            0 if not (dom & EMPTY_BIT) else 1,
            -deg,
        )
        if best_key is None or key < best_key:
            best_key = key
            best = i
    return best


def ordered_states_for_branch(dom):
    vals = list(iter_states(dom))
    if EMPTY in vals:
        vals.remove(EMPTY)
        return [EMPTY] + vals
    return vals


def validate_solution(domains, puzzle):
    if any(dom.bit_count() != 1 for dom in domains):
        return False

    states = [only_state(dom) for dom in domains]
    neighbors = puzzle["neighbors"]
    clue_map = puzzle["clue_map"]
    n = puzzle["n"]

    # Edge reciprocity and degrees.
    used = []
    adj = [[] for _ in range(n)]
    for i, s in enumerate(states):
        if s == EMPTY:
            continue
        used.append(i)
        dirs = STATE_DIRS[s]
        if len(dirs) != 2:
            return False
        for d in dirs:
            j = neighbors[i][d]
            if j == -1:
                return False
            if not (states[j] & OPP[d]):
                return False

    for i in range(n):
        for d in (R, D):
            j = neighbors[i][d]
            if j == -1:
                continue
            a = bool(states[i] & d)
            b = bool(states[j] & OPP[d])
            if a != b:
                return False
            if a:
                adj[i].append(j)
                adj[j].append(i)

    for i in used:
        if len(adj[i]) != 2:
            return False

    if not used:
        return False

    # Single cycle.
    seen = set()
    stack = [used[0]]
    seen.add(used[0])
    while stack:
        v = stack.pop()
        for w in adj[v]:
            if w not in seen:
                seen.add(w)
                stack.append(w)
    if set(used) != seen:
        return False

    # Clue semantics and lengths.
    for idx, (typ, k) in clue_map.items():
        s = states[idx]
        if typ == "W" and s not in (H, V):
            return False
        if typ == "B" and s not in TURN_STATES:
            return False

        total = 0
        for d in STATE_DIRS[s]:
            cur = idx
            dist = 0
            while True:
                cur = neighbors[cur][d]
                if cur == -1:
                    return False
                dist += 1
                cs = states[cur]
                if cs in TURN_STATES and (cs & OPP[d]):
                    total += dist
                    break
                if cs != (V if d in (U, D) else H):
                    return False
        if total != k:
            return False

    return True


def extract_cycle(domains, puzzle):
    states = [only_state(dom) for dom in domains]
    rows = puzzle["rows"]
    cols = puzzle["cols"]
    neighbors = puzzle["neighbors"]
    n = puzzle["n"]

    adj = [[] for _ in range(n)]
    used = []
    for i, s in enumerate(states):
        if s == EMPTY:
            continue
        used.append(i)
        for d in (R, D):
            j = neighbors[i][d]
            if j != -1 and (s & d):
                adj[i].append(j)
                adj[j].append(i)

    start = min(used)
    path = []
    prev = -1
    cur = start
    while True:
        r, c = divmod(cur, cols)
        path.append((r, c))
        nxts = adj[cur]
        if len(nxts) != 2:
            return None
        nxt = nxts[0] if nxts[0] != prev else nxts[1]
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > n + 1:
            return None
    path.append(divmod(start, cols))
    return path


def search(domains, puzzle):
    domains = propagate(domains[:], puzzle)
    if domains is None:
        return None

    if all(dom.bit_count() == 1 for dom in domains):
        if validate_solution(domains, puzzle):
            return domains
        return None

    var = choose_var(domains, puzzle)
    if var is None:
        return None

    for s in ordered_states_for_branch(domains[var]):
        new_domains = domains[:]
        new_domains[var] = SBIT[s]
        res = search(new_domains, puzzle)
        if res is not None:
            return res
    return None


def solve(observation):
    puzzle = build_puzzle(observation)
    domains = initial_domains(puzzle)
    if domains is None:
        return "No Solution"

    result = search(domains, puzzle)
    if result is None:
        return "No Solution"

    cycle = extract_cycle(result, puzzle)
    if cycle is None:
        return "No Solution"
    return cycle


if __name__ == "__main__":
    print(solve(OBSERVATION))

