from collections import deque
import sys

sys.setrecursionlimit(10000)


class SlitherlinkSolver:
    # Human-style solver:
    # 1) Exact clue saturation on each cell.
    # 2) Degree-0-or-2 propagation on each dot/vertex.
    # 3) Early rejection of premature closed subloops.
    # 4) Failed-literal deductions (try edge on/off locally; if one side fails, force the other).
    # 5) Depth-first search only on the most constrained remaining edge.

    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.C = self.n * self.n
        self.V = (self.n + 1) * (self.n + 1)

        self.h_id = [[None] * self.n for _ in range(self.n + 1)]
        self.v_id = [[None] * (self.n + 1) for _ in range(self.n)]

        self.edge_verts = []
        self.edge_cells = []

        eid = 0
        for r in range(self.n + 1):
            for c in range(self.n):
                self.h_id[r][c] = eid
                a = r * (self.n + 1) + c
                b = r * (self.n + 1) + (c + 1)
                self.edge_verts.append((a, b))
                self.edge_cells.append([])
                eid += 1

        for r in range(self.n):
            for c in range(self.n + 1):
                self.v_id[r][c] = eid
                a = r * (self.n + 1) + c
                b = (r + 1) * (self.n + 1) + c
                self.edge_verts.append((a, b))
                self.edge_cells.append([])
                eid += 1

        self.E = eid

        self.cell_edges = []
        self.clues = []
        for r in range(self.n):
            for c in range(self.n):
                edges = [
                    self.h_id[r][c],       # top
                    self.v_id[r][c + 1],   # right
                    self.h_id[r + 1][c],   # bottom
                    self.v_id[r][c],       # left
                ]
                cid = r * self.n + c
                self.cell_edges.append(edges)
                self.clues.append(data[r][c])
                for e in edges:
                    self.edge_cells[e].append(cid)

        self.vert_edges = [[] for _ in range(self.V)]
        for e, (a, b) in enumerate(self.edge_verts):
            self.vert_edges[a].append(e)
            self.vert_edges[b].append(e)

        self.edge_cons = [[] for _ in range(self.E)]
        for cid, edges in enumerate(self.cell_edges):
            for e in edges:
                self.edge_cons[e].append(cid)
        for vid, edges in enumerate(self.vert_edges):
            qid = self.C + vid
            for e in edges:
                self.edge_cons[e].append(qid)

        self.vid_to_coord = [(r, c) for r in range(self.n + 1) for c in range(self.n + 1)]
        self.clued_cells = [cid for cid, clue in enumerate(self.clues) if clue is not None]
        self.nodes = 0

    def _cell_counts(self, vals, cid):
        on = 0
        unk = 0
        for e in self.cell_edges[cid]:
            v = vals[e]
            if v == 1:
                on += 1
            elif v == -1:
                unk += 1
        return on, unk

    def _vert_counts(self, vals, vid):
        on = 0
        unk = 0
        for e in self.vert_edges[vid]:
            v = vals[e]
            if v == 1:
                on += 1
            elif v == -1:
                unk += 1
        return on, unk

    def _check_subloops(self, vals):
        on_adj = [[] for _ in range(self.V)]
        total_on = 0
        for e, val in enumerate(vals):
            if val == 1:
                a, b = self.edge_verts[e]
                on_adj[a].append(b)
                on_adj[b].append(a)
                total_on += 1

        if total_on == 0:
            return True

        seen = [False] * self.V
        for start in range(self.V):
            if seen[start] or not on_adj[start]:
                continue
            stack = [start]
            seen[start] = True
            comp_vs = []
            comp_edge_twice = 0
            while stack:
                v = stack.pop()
                comp_vs.append(v)
                comp_edge_twice += len(on_adj[v])
                for w in on_adj[v]:
                    if not seen[w]:
                        seen[w] = True
                        stack.append(w)
            comp_edges = comp_edge_twice // 2
            if all(len(on_adj[v]) == 2 for v in comp_vs):
                # A closed cycle already exists.
                # If it does not contain all current "on" edges, it's an illegal subloop.
                if comp_edges != total_on:
                    return False
                # If any clue still needs extra on-edges, this closed loop is too early and impossible.
                for cid in self.clued_cells:
                    clue = self.clues[cid]
                    on, _ = self._cell_counts(vals, cid)
                    if on < clue:
                        return False
                return True
        return True

    def propagate(self, vals, queue_items=None, lookahead=True):
        if queue_items is None:
            queue = deque(range(self.C + self.V))
            inq = [True] * (self.C + self.V)
        else:
            queue = deque()
            inq = [False] * (self.C + self.V)
            for item in queue_items:
                if not inq[item]:
                    inq[item] = True
                    queue.append(item)

        def push(item):
            if not inq[item]:
                inq[item] = True
                queue.append(item)

        def assign(e, value):
            cur = vals[e]
            if cur == value:
                return True
            if cur != -1:
                return False
            vals[e] = value
            for item in self.edge_cons[e]:
                push(item)
            return True

        while True:
            while queue:
                item = queue.popleft()
                inq[item] = False

                if item < self.C:
                    cid = item
                    clue = self.clues[cid]
                    if clue is None:
                        continue
                    edges = self.cell_edges[cid]
                    on = 0
                    unk = []
                    for e in edges:
                        v = vals[e]
                        if v == 1:
                            on += 1
                        elif v == -1:
                            unk.append(e)

                    if on > clue or on + len(unk) < clue:
                        return None
                    if unk:
                        if on == clue:
                            for e in unk:
                                if not assign(e, 0):
                                    return None
                        elif on + len(unk) == clue:
                            for e in unk:
                                if not assign(e, 1):
                                    return None

                else:
                    vid = item - self.C
                    edges = self.vert_edges[vid]
                    on = 0
                    unk = []
                    for e in edges:
                        v = vals[e]
                        if v == 1:
                            on += 1
                        elif v == -1:
                            unk.append(e)

                    if on > 2:
                        return None
                    if on == 1 and not unk:
                        return None
                    if on > 0 and on + len(unk) < 2:
                        return None

                    if on == 2:
                        for e in unk:
                            if not assign(e, 0):
                                return None
                    elif on == 1 and len(unk) == 1:
                        if not assign(unk[0], 1):
                            return None
                    elif on == 0 and len(unk) == 1:
                        if not assign(unk[0], 0):
                            return None

            if not self._check_subloops(vals):
                return None

            if not lookahead:
                return vals

            forced = self.failed_literal(vals)
            if forced is None:
                return vals
            if forced is False:
                return None

            e, value = forced
            if not assign(e, value):
                return None

    def try_assignment(self, vals, e, value):
        new_vals = vals.copy()
        cur = new_vals[e]
        if cur != -1 and cur != value:
            return None
        new_vals[e] = value
        return self.propagate(new_vals, self.edge_cons[e], lookahead=False)

    def edge_score(self, vals, e):
        score = 0
        endpoint_count = 0
        prob_sum = 0.0
        prob_cnt = 0

        for cid in self.edge_cells[e]:
            clue = self.clues[cid]
            if clue is None:
                continue
            on, unk = self._cell_counts(vals, cid)
            if unk:
                rem = clue - on
                score += (5 - unk) * 8 + abs(2 * rem - unk)
                prob_sum += rem / unk
                prob_cnt += 1

        for vid in self.edge_verts[e]:
            on, unk = self._vert_counts(vals, vid)
            if on == 1:
                endpoint_count += 1
                score += 20
            elif on == 0 and unk == 2:
                score += 6
            elif on == 0 and unk == 1:
                score += 12

        score += endpoint_count * 10
        prefer = 1 if endpoint_count > 0 else (1 if (prob_cnt and (prob_sum / prob_cnt) >= 0.5) else 0)
        return score, prefer

    def failed_literal(self, vals):
        unknown = [e for e, v in enumerate(vals) if v == -1]
        if not unknown:
            return None

        scored = []
        for e in unknown:
            score, prefer = self.edge_score(vals, e)
            scored.append((score, prefer, e))
        scored.sort(reverse=True)

        m = len(scored)
        if m > 120:
            limit = 10
        elif m > 80:
            limit = 16
        elif m > 40:
            limit = 24
        else:
            limit = m

        for _, _, e in scored[:limit]:
            off_try = self.try_assignment(vals, e, 0)
            on_try = self.try_assignment(vals, e, 1)
            if off_try is None and on_try is None:
                return False
            if off_try is None:
                return (e, 1)
            if on_try is None:
                return (e, 0)
        return None

    def is_solved(self, vals):
        if any(v == -1 for v in vals):
            return False

        for cid in self.clued_cells:
            clue = self.clues[cid]
            total = 0
            for e in self.cell_edges[cid]:
                total += vals[e]
            if total != clue:
                return False

        deg = [0] * self.V
        total_on = 0
        for e, val in enumerate(vals):
            if val == 1:
                a, b = self.edge_verts[e]
                deg[a] += 1
                deg[b] += 1
                total_on += 1

        if total_on == 0:
            return False

        active = [v for v in range(self.V) if deg[v] > 0]
        for v in active:
            if deg[v] != 2:
                return False

        start = active[0]
        seen = {start}
        stack = [start]
        adj = [[] for _ in range(self.V)]
        for e, val in enumerate(vals):
            if val == 1:
                a, b = self.edge_verts[e]
                adj[a].append(b)
                adj[b].append(a)

        while stack:
            v = stack.pop()
            for w in adj[v]:
                if w not in seen:
                    seen.add(w)
                    stack.append(w)

        return len(seen) == len(active)

    def choose_edge(self, vals):
        best = None
        best_key = None
        for e, v in enumerate(vals):
            if v != -1:
                continue
            score, prefer = self.edge_score(vals, e)
            key = (score, len(self.edge_cells[e]), prefer)
            if best is None or key > best_key:
                best = (e, prefer)
                best_key = key
        return best

    def search(self, vals, queue_items=None):
        self.nodes += 1
        vals = self.propagate(vals, queue_items, lookahead=True)
        if vals is None:
            return None
        if self.is_solved(vals):
            return vals

        choice = self.choose_edge(vals)
        if choice is None:
            return None

        e, prefer = choice
        order = [prefer, 1 - prefer]

        for value in order:
            new_vals = vals.copy()
            cur = new_vals[e]
            if cur != -1 and cur != value:
                continue
            new_vals[e] = value
            result = self.search(new_vals, self.edge_cons[e])
            if result is not None:
                return result
        return None

    def extract_loop(self, vals):
        adj = [[] for _ in range(self.V)]
        for e, val in enumerate(vals):
            if val == 1:
                a, b = self.edge_verts[e]
                adj[a].append(b)
                adj[b].append(a)

        start = None
        for v in range(self.V):
            if len(adj[v]) == 2:
                start = v
                break
        if start is None:
            return []

        first = min(adj[start])
        path = [self.vid_to_coord[start]]

        prev = start
        cur = first
        while True:
            path.append(self.vid_to_coord[cur])
            if cur == start:
                break
            a, b = adj[cur]
            nxt = b if a == prev else a
            prev, cur = cur, nxt

        return path


def solve(observation):
    data = observation.get("data")
    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    solver = SlitherlinkSolver(data)
    vals = [-1] * solver.E
    result = solver.search(vals)
    if result is None:
        return "No Solution"
    loop = solver.extract_loop(result)
    return repr(loop)


