# General Heyawake solver:
# - numbered regions: exact black count
# - black cells orthogonally non-touching
# - no white run may span 3 regions in a row/column
# - all white cells connected

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = n * n
    allmask = (1 << m) - 1

    def idx(r, c):
        return r * n + c

    def bit(i):
        return 1 << i

    # Cell neighbors
    neighbors = [0] * m
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            mask = 0
            if r > 0:
                mask |= bit(idx(r - 1, c))
            if r + 1 < n:
                mask |= bit(idx(r + 1, c))
            if c > 0:
                mask |= bit(idx(r, c - 1))
            if c + 1 < n:
                mask |= bit(idx(r, c + 1))
            neighbors[i] = mask

    # Region cells and clues
    region_ids = sorted({x for row in region for x in row})
    reg_cells = {rid: [] for rid in region_ids}
    reg_clue = {rid: None for rid in region_ids}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            reg_cells[rid].append(idx(r, c))
            val = data[r][c]
            if val is not None:
                reg_clue[rid] = val

    reg_mask = {}
    for rid in region_ids:
        mask = 0
        for i in reg_cells[rid]:
            mask |= bit(i)
        reg_mask[rid] = mask

    # Precompute exact-pattern domains for numbered regions
    numbered_rids = [rid for rid in region_ids if reg_clue[rid] is not None]

    def generate_patterns(cells, k):
        cells = list(cells)
        s = len(cells)
        if k < 0 or k > s:
            return []
        local_nei = {i: neighbors[i] & sum(bit(c) for c in cells) for i in cells}
        out = []

        def rec(pos, need, chosen):
            if need == 0:
                out.append(chosen)
                return
            if pos == s or s - pos < need:
                return
            cell = cells[pos]
            rec(pos + 1, need, chosen)
            if (chosen & local_nei[cell]) == 0:
                rec(pos + 1, need - 1, chosen | bit(cell))

        rec(0, k, 0)
        return out

    num_region_masks = []
    num_domains0 = []
    num_pattern_adj = []
    cell_to_num_region = {}
    for nr, rid in enumerate(numbered_rids):
        cells = reg_cells[rid]
        k = reg_clue[rid]
        pats = generate_patterns(cells, k)
        if not pats:
            return "No Solution"
        adj_map = {}
        for p in pats:
            a = 0
            x = p
            while x:
                lsb = x & -x
                x -= lsb
                a |= neighbors[lsb.bit_length() - 1]
            adj_map[p] = a
        num_region_masks.append(reg_mask[rid])
        num_domains0.append(tuple(pats))
        num_pattern_adj.append(adj_map)
        for i in cells:
            cell_to_num_region[i] = nr

    # Precompute exact blockers for the "3 regions max in a white run" rule.
    # For segments A,B,C on a line, at least one of:
    # - boundary-adjacent cell of A,
    # - any cell of B,
    # - boundary-adjacent cell of C
    # must be black.
    blocker_masks = set()

    for r in range(n):
        segs = []
        c = 0
        while c < n:
            rid = region[r][c]
            start = c
            mask = 0
            while c < n and region[r][c] == rid:
                mask |= bit(idx(r, c))
                c += 1
            end = c - 1
            segs.append((start, end, mask))
        for i in range(len(segs) - 2):
            a = segs[i]
            b = segs[i + 1]
            cseg = segs[i + 2]
            bm = bit(idx(r, a[1])) | b[2] | bit(idx(r, cseg[0]))
            blocker_masks.add(bm)

    for c in range(n):
        segs = []
        r = 0
        while r < n:
            rid = region[r][c]
            start = r
            mask = 0
            while r < n and region[r][c] == rid:
                mask |= bit(idx(r, c))
                r += 1
            end = r - 1
            segs.append((start, end, mask))
        for i in range(len(segs) - 2):
            a = segs[i]
            b = segs[i + 1]
            cseg = segs[i + 2]
            bm = bit(idx(a[1], c)) | b[2] | bit(idx(cseg[0], c))
            blocker_masks.add(bm)

    blocker_masks = tuple(sorted(blocker_masks))
    blocker_count = [0] * m
    for bm in blocker_masks:
        x = bm
        while x:
            lsb = x & -x
            x -= lsb
            blocker_count[lsb.bit_length() - 1] += 1

    # Small helpers
    def reachable(start_bit, allowed):
        seen = 0
        stack = start_bit
        while stack:
            lsb = stack & -stack
            stack -= lsb
            if seen & lsb:
                continue
            seen |= lsb
            i = lsb.bit_length() - 1
            stack |= neighbors[i] & allowed & ~seen
        return seen

    def connectivity_possible(B, W):
        if W == 0:
            return True
        allowed = allmask ^ B
        start = W & -W
        seen = reachable(start, allowed)
        return (W & ~seen) == 0

    def forced_connectors(B, W):
        if W == 0 or (W & (W - 1)) == 0:
            return 0
        allowed = allmask ^ B
        root = W & -W
        unknown = allowed & ~W
        force = 0
        x = unknown
        while x:
            lsb = x & -x
            x -= lsb
            seen = reachable(root, allowed ^ lsb)
            if (W & ~seen) != 0:
                force |= lsb
        return force

    def propagate(B, W, doms):
        doms = list(doms)
        while True:
            changed = False

            if B & W:
                return None

            # Black adjacency
            adjB = 0
            x = B
            while x:
                lsb = x & -x
                x -= lsb
                adjB |= neighbors[lsb.bit_length() - 1]
            if adjB & B:
                return None
            forceW = adjB & ~(B | W)
            if forceW:
                W |= forceW
                changed = True

            # Numbered regions: filter feasible patterns, then take intersections/unions
            for i in range(len(doms)):
                regm = num_region_masks[i]
                reqB = B & regm
                forbB = W & regm
                outsideB = B & ~regm
                old = doms[i]
                new = []
                poss = 0
                common = None
                adj_map = num_pattern_adj[i]
                for p in old:
                    if reqB & ~p:
                        continue
                    if forbB & p:
                        continue
                    if adj_map[p] & outsideB:
                        continue
                    new.append(p)
                    poss |= p
                    common = p if common is None else (common & p)
                if not new:
                    return None
                if len(new) != len(old):
                    doms[i] = tuple(new)
                    changed = True
                forceB = common & ~(B | W)
                forceW = (regm & ~poss) & ~(B | W)
                if forceB:
                    B |= forceB
                    changed = True
                if forceW:
                    W |= forceW
                    changed = True

            # 3-region white-run blockers
            for bm in blocker_masks:
                if B & bm:
                    continue
                u = bm & ~(B | W)
                if u == 0:
                    return None
                if (u & (u - 1)) == 0:
                    B |= u
                    changed = True

            # White connectivity feasibility
            if not connectivity_possible(B, W):
                return None

            # Human-like bridge rule: if making an unknown black disconnects known whites, it must be white.
            force = forced_connectors(B, W)
            if force:
                W |= force
                changed = True

            if not changed:
                break

        return B, W, tuple(doms)

    def choose_cell(B, W, doms):
        U = allmask ^ (B | W)
        best_i = None
        best_score = None
        x = U
        while x:
            lsb = x & -x
            x -= lsb
            i = lsb.bit_length() - 1
            score = 10 * blocker_count[i]
            score += ((neighbors[i] & U).bit_count())
            if i in cell_to_num_region:
                score += 6
                score -= len(doms[cell_to_num_region[i]])
            if best_score is None or score > best_score:
                best_score = score
                best_i = i
        return best_i

    def final_valid(B):
        # 1. Numbered regions
        for rid in numbered_rids:
            k = reg_clue[rid]
            if (B & reg_mask[rid]).bit_count() != k:
                return False

        # 2. No orthogonally touching blacks
        x = B
        while x:
            lsb = x & -x
            x -= lsb
            if neighbors[lsb.bit_length() - 1] & B:
                return False

        # 3. White runs span at most 2 regions
        for r in range(n):
            c = 0
            while c < n:
                if B & bit(idx(r, c)):
                    c += 1
                    continue
                blocks = 0
                last_rid = None
                while c < n and not (B & bit(idx(r, c))):
                    rid = region[r][c]
                    if rid != last_rid:
                        blocks += 1
                        last_rid = rid
                    c += 1
                if blocks > 2:
                    return False

        for c in range(n):
            r = 0
            while r < n:
                if B & bit(idx(r, c)):
                    r += 1
                    continue
                blocks = 0
                last_rid = None
                while r < n and not (B & bit(idx(r, c))):
                    rid = region[r][c]
                    if rid != last_rid:
                        blocks += 1
                        last_rid = rid
                    r += 1
                if blocks > 2:
                    return False

        # 4. White connected
        W = allmask ^ B
        if W:
            start = W & -W
            if reachable(start, W) != W:
                return False

        return True

    def dfs(B, W, doms):
        state = propagate(B, W, doms)
        if state is None:
            return None
        B, W, doms = state

        if (B | W) == allmask:
            if final_valid(B):
                return B
            return None

        # Branch first on the most constrained numbered region
        best_region = None
        best_len = None
        for i, d in enumerate(doms):
            if len(d) > 1:
                l = len(d)
                if best_len is None or l < best_len:
                    best_len = l
                    best_region = i
        if best_region is not None:
            regm = num_region_masks[best_region]
            for p in sorted(doms[best_region], key=lambda x: (x.bit_count(), x)):
                new_doms = list(doms)
                new_doms[best_region] = (p,)
                res = dfs(B | p, W | (regm ^ p), tuple(new_doms))
                if res is not None:
                    return res
            return None

        # Otherwise branch on a single undecided cell
        i = choose_cell(B, W, doms)
        b = bit(i)

        # Try black first if not immediately impossible
        if (neighbors[i] & B) == 0:
            res = dfs(B | b, W, doms)
            if res is not None:
                return res

        return dfs(B, W | b, doms)

    result = dfs(0, 0, tuple(num_domains0))
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if (result & bit(idx(r, c))) else None)
        out.append(row)
    return repr(out)


