from collections import deque

# The solver models a common "stitch" interpretation that matches the rule shape:
# - Region boundaries induce exact-one constraints on the two endpoint holes of each shared side.
# - A used hole must belong to exactly one stitch.
# - A stitch is a domino on the hole grid between orthogonally adjacent holes.
#
# Human-like deductions encoded explicitly:
# 1) Boundary constraints are mostly XOR relations, so hole usages alternate on connected components.
# 2) Each XOR-component has only 2 possible orientations.
# 3) Row/column clues select the component orientations.
# 4) Final stitch placement is a perfect matching on the chosen used holes.
# 5) Forced degree-1 matches are propagated before a Hopcroft-Karp check.


def solve(observation):
    region = observation["region"]
    row_clues = observation["row_stitch_counts"]
    col_clues = observation["col_stitch_counts"]
    n = len(region)

    if len(row_clues) != n or len(col_clues) != n:
        return "No Solution"

    total_used = sum(row_clues)
    if total_used != sum(col_clues):
        return "No Solution"
    if total_used % 2:
        return "No Solution"

    # Try the four natural ways to embed an N x N clue-grid into an (N+1) x (N+1) corner lattice.
    for r_off in (0, 1):
        for c_off in (0, 1):
            model = build_model(region, n, r_off, c_off)
            if model is None:
                continue
            ans = solve_model(model, row_clues, col_clues, n)
            if ans is not None:
                return repr(ans)

    return "No Solution"


def build_model(region, n, r_off, c_off):
    hole_count = n * n
    edges = set()
    fixed1 = set()

    def inside(ar, ac):
        return r_off <= ar < r_off + n and c_off <= ac < c_off + n

    def map_hole(ar, ac):
        return (ar - r_off) * n + (ac - c_off)

    def add_boundary_constraint(points):
        inside_pts = [map_hole(ar, ac) for (ar, ac) in points if inside(ar, ac)]
        if len(inside_pts) == 0:
            return False
        if len(inside_pts) == 1:
            fixed1.add(inside_pts[0])
            return True
        a, b = inside_pts
        if a == b:
            return False
        if a > b:
            a, b = b, a
        edges.add((a, b))
        return True

    # Horizontal neighboring cells: shared vertical side with two endpoint holes.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                if not add_boundary_constraint(((r, c + 1), (r + 1, c + 1))):
                    return None

    # Vertical neighboring cells: shared horizontal side with two endpoint holes.
    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                if not add_boundary_constraint(((r + 1, c), (r + 1, c + 1))):
                    return None

    adj = [[] for _ in range(hole_count)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    color = [-1] * hole_count
    components = []

    for start in range(hole_count):
        if color[start] != -1:
            continue

        # BFS for XOR parity. Isolated holes become singleton 2-state components.
        queue = deque([start])
        color[start] = 0
        nodes = []
        ok = True
        while queue and ok:
            v = queue.popleft()
            nodes.append(v)
            for u in adj[v]:
                if color[u] == -1:
                    color[u] = color[v] ^ 1
                    queue.append(u)
                elif color[u] == color[v]:
                    ok = False
                    break
        if not ok:
            return None

        mask0 = 0
        mask1 = 0
        rows0 = [0] * n
        rows1 = [0] * n
        cols0 = [0] * n
        cols1 = [0] * n

        fixed_orient = None
        has_edge = any(adj[v] for v in nodes)

        for v in nodes:
            r, c = divmod(v, n)
            if color[v] == 0:
                mask0 |= 1 << v
                rows0[r] += 1
                cols0[c] += 1
            else:
                mask1 |= 1 << v
                rows1[r] += 1
                cols1[c] += 1

            if v in fixed1:
                orient = color[v]
                if fixed_orient is None:
                    fixed_orient = orient
                elif fixed_orient != orient:
                    return None

        # Pure isolated hole with no boundary participation:
        # orientation 0 => used, orientation 1 => unused.
        if not has_edge:
            v = nodes[0]
            r, c = divmod(v, n)
            mask0 = 1 << v
            mask1 = 0
            rows0 = [0] * n
            rows1 = [0] * n
            cols0 = [0] * n
            cols1 = [0] * n
            rows0[r] = 1
            cols0[c] = 1
            if v in fixed1:
                fixed_orient = 0

        components.append({
            "mask": (mask0, mask1),
            "rows": (tuple(rows0), tuple(rows1)),
            "cols": (tuple(cols0), tuple(cols1)),
            "fixed": fixed_orient,
            "size": len(nodes),
            "score": sum(abs(rows0[i] - rows1[i]) for i in range(n)) + sum(abs(cols0[i] - cols1[i]) for i in range(n))
        })

    return {
        "n": n,
        "components": components
    }


def solve_model(model, row_clues, col_clues, n):
    comps = model["components"]

    used_mask = 0
    row_need = list(row_clues)
    col_need = list(col_clues)

    fixed_comps = []
    var_comps = []

    for comp in comps:
        if comp["fixed"] is None:
            var_comps.append(comp)
        else:
            fixed_comps.append(comp)

    for comp in fixed_comps:
        t = comp["fixed"]
        used_mask |= comp["mask"][t]
        for i in range(n):
            row_need[i] -= comp["rows"][t][i]
            col_need[i] -= comp["cols"][t][i]

    if min(row_need) < 0 or min(col_need) < 0:
        return None
    if sum(row_need) != sum(col_need):
        return None

    # Most informative components first.
    var_comps.sort(key=lambda cp: (cp["score"], cp["size"]), reverse=True)

    m = len(var_comps)
    suf_row_min = [[0] * n for _ in range(m + 1)]
    suf_row_max = [[0] * n for _ in range(m + 1)]
    suf_col_min = [[0] * n for _ in range(m + 1)]
    suf_col_max = [[0] * n for _ in range(m + 1)]

    for i in range(m - 1, -1, -1):
        comp = var_comps[i]
        r0, r1 = comp["rows"]
        c0, c1 = comp["cols"]
        for k in range(n):
            suf_row_min[i][k] = suf_row_min[i + 1][k] + min(r0[k], r1[k])
            suf_row_max[i][k] = suf_row_max[i + 1][k] + max(r0[k], r1[k])
            suf_col_min[i][k] = suf_col_min[i + 1][k] + min(c0[k], c1[k])
            suf_col_max[i][k] = suf_col_max[i + 1][k] + max(c0[k], c1[k])

    match_cache = {}

    def feasible_bounds(idx, rows, cols):
        for k in range(n):
            if rows[k] < suf_row_min[idx][k] or rows[k] > suf_row_max[idx][k]:
                return False
            if cols[k] < suf_col_min[idx][k] or cols[k] > suf_col_max[idx][k]:
                return False
        return True

    if not feasible_bounds(0, row_need, col_need):
        return None

    def search(idx, rows, cols, mask):
        if idx == m:
            if any(rows) or any(cols):
                return None
            if mask in match_cache:
                return match_cache[mask]
            sol = perfect_matching_as_stitches(mask, n)
            match_cache[mask] = sol
            return sol

        comp = var_comps[idx]
        r0, r1 = comp["rows"]
        c0, c1 = comp["cols"]

        # Try the orientation that better fits current deficits first.
        score0 = 0
        score1 = 0
        for k in range(n):
            score0 += abs((rows[k] - r0[k])) + abs((cols[k] - c0[k]))
            score1 += abs((rows[k] - r1[k])) + abs((cols[k] - c1[k]))
        order = (0, 1) if score0 <= score1 else (1, 0)

        for t in order:
            new_rows = [rows[k] - comp["rows"][t][k] for k in range(n)]
            new_cols = [cols[k] - comp["cols"][t][k] for k in range(n)]
            if min(new_rows) < 0 or min(new_cols) < 0:
                continue
            if not feasible_bounds(idx + 1, new_rows, new_cols):
                continue
            ans = search(idx + 1, tuple(new_rows), tuple(new_cols), mask | comp["mask"][t])
            if ans is not None:
                return ans
        return None

    return search(0, tuple(row_need), tuple(col_need), used_mask)


def perfect_matching_as_stitches(mask, n):
    total = mask.bit_count()
    if total == 0:
        return []
    if total & 1:
        return None

    used = [i for i in range(n * n) if (mask >> i) & 1]
    used_set = set(used)

    nbrs = {v: [] for v in used}
    for v in used:
        r, c = divmod(v, n)
        for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= rr < n and 0 <= cc < n:
                u = rr * n + cc
                if u in used_set:
                    nbrs[v].append(u)

    # Human-like forced matching: degree-1 holes must use their only possible stitch.
    active = {v: True for v in used}
    degree = {v: len(nbrs[v]) for v in used}
    q = deque([v for v in used if degree[v] <= 1])
    forced = []

    while q:
        v = q.popleft()
        if not active.get(v, False):
            continue
        if degree[v] == 0:
            return None
        if degree[v] > 1:
            continue

        u = None
        for x in nbrs[v]:
            if active.get(x, False):
                u = x
                break
        if u is None:
            return None

        if not active.get(u, False):
            return None

        forced.append((v, u))

        for x in (v, u):
            if not active.get(x, False):
                continue
            active[x] = False
            for y in nbrs[x]:
                if active.get(y, False):
                    degree[y] -= 1
                    if degree[y] <= 1:
                        q.append(y)

    rem = [v for v in used if active.get(v, False)]
    if not rem:
        return canonicalize_stitches(forced, n)

    # Remaining graph must decompose into even-size components.
    seen = set()
    for start in rem:
        if start in seen:
            continue
        comp = []
        dq = deque([start])
        seen.add(start)
        while dq:
            v = dq.popleft()
            comp.append(v)
            for u in nbrs[v]:
                if active.get(u, False) and u not in seen:
                    seen.add(u)
                    dq.append(u)
        if len(comp) & 1:
            return None

    left = [v for v in rem if ((v // n) + (v % n)) % 2 == 0]
    right_set = set(rem) - set(left)

    graph = {}
    for v in left:
        graph[v] = [u for u in nbrs[v] if active.get(u, False)]

    if any(len(graph[v]) == 0 for v in left):
        return None

    pair_u = {}
    pair_v = {}
    dist = {}

    def bfs():
        dq = deque()
        found_free = False
        for u in left:
            if u not in pair_u:
                dist[u] = 0
                dq.append(u)
            else:
                dist[u] = -1
        while dq:
            u = dq.popleft()
            for v in graph[u]:
                pu = pair_v.get(v)
                if pu is None:
                    found_free = True
                elif dist.get(pu, -1) == -1:
                    dist[pu] = dist[u] + 1
                    dq.append(pu)
        return found_free

    def dfs(u):
        for v in graph[u]:
            pu = pair_v.get(v)
            if pu is None or (dist.get(pu, -1) == dist[u] + 1 and dfs(pu)):
                pair_u[u] = v
                pair_v[v] = u
                return True
        dist[u] = -1
        return False

    matching = 0
    while bfs():
        for u in left:
            if u not in pair_u and dfs(u):
                matching += 1

    if matching * 2 != len(rem):
        return None

    hk_pairs = [(u, v) for u, v in pair_u.items()]
    all_pairs = forced + hk_pairs
    return canonicalize_stitches(all_pairs, n)


def canonicalize_stitches(pairs, n):
    out = []
    for a, b in pairs:
        ra, ca = divmod(a, n)
        rb, cb = divmod(b, n)
        p = (ra, ca)
        q = (rb, cb)
        if q < p:
            p, q = q, p
        out.append([p, q])
    out.sort()
    return out


