OBSERVATION = {'data': [[None, None, 8, None, None, None, None, None, None], [None, 3, None, None, None, None, 1, 7, None], [9, None, None, 4, 7, None, 5, None, 3], [None, 4, None, None, 1, None, None, None, None], [None, 1, None, 6, None, 8, None, 9, None], [None, None, None, None, 9, None, None, 2, None], [1, None, 6, None, 2, 7, None, None, 8], [None, 7, 3, None, None, None, None, 5, None], [None, None, None, None, None, None, 9, None, None]], 'unit': '3x3'}

from itertools import combinations


def solve(observation):
    data = observation['data']
    unit = observation['unit']

    def parse_unit(text):
        text = str(text).lower().strip()
        if 'x' in text:
            a, b = text.split('x', 1)
            return int(a), int(b)
        n = int(text)
        return n, n

    box_r, box_c = parse_unit(unit)
    n = box_r * box_c
    if len(data) != n or any(len(row) != n for row in data):
        return "No Solution"

    full_mask = (1 << n) - 1
    bit_list = tuple(1 << i for i in range(n))
    cell_count = n * n

    def is_single(mask):
        return mask and not (mask & (mask - 1))

    def mask_to_value(mask):
        return mask.bit_length()

    row_of = [i // n for i in range(cell_count)]
    col_of = [i % n for i in range(cell_count)]
    box_of = [((i // n) // box_r) * (n // box_c) + ((i % n) // box_c) for i in range(cell_count)]

    rows = [tuple(r * n + c for c in range(n)) for r in range(n)]
    cols = [tuple(r * n + c for r in range(n)) for c in range(n)]
    boxes = []
    for br in range(0, n, box_r):
        for bc in range(0, n, box_c):
            boxes.append(tuple((r * n + c) for r in range(br, br + box_r) for c in range(bc, bc + box_c)))
    houses = tuple(rows + cols + boxes)

    cell_houses = []
    for idx in range(cell_count):
        cell_houses.append((
            row_of[idx],
            n + col_of[idx],
            2 * n + box_of[idx],
        ))
    cell_houses = tuple(cell_houses)

    peers = []
    for idx in range(cell_count):
        s = set()
        for h in cell_houses[idx]:
            s.update(houses[h])
        s.discard(idx)
        peers.append(tuple(s))
    peers = tuple(peers)

    def assign(cands, idx, keep_bit):
        return eliminate(cands, idx, cands[idx] & ~keep_bit)

    def eliminate(cands, idx, remove_mask):
        cur = cands[idx]
        if not (cur & remove_mask):
            return True

        new = cur & ~remove_mask
        if new == 0:
            return False

        cands[idx] = new

        if is_single(new):
            bit = new
            for p in peers[idx]:
                if not eliminate(cands, p, bit):
                    return False

        removed = cur & ~new
        while removed:
            bit = removed & -removed
            removed -= bit
            for h in cell_houses[idx]:
                last = -1
                for j in houses[h]:
                    if cands[j] & bit:
                        if last != -1:
                            last = -2
                            break
                        last = j
                if last == -1:
                    return False
                if last >= 0 and not assign(cands, last, bit):
                    return False

        return True

    def apply_locked_candidates(cands):
        # Pointing
        for box in boxes:
            for bit in bit_list:
                count = 0
                same_row = -1
                same_col = -1
                for idx in box:
                    if cands[idx] & bit:
                        count += 1
                        r = row_of[idx]
                        c = col_of[idx]
                        if same_row == -1:
                            same_row = r
                        elif same_row != r:
                            same_row = -2
                        if same_col == -1:
                            same_col = c
                        elif same_col != c:
                            same_col = -2
                        if same_row == -2 and same_col == -2 and count > 1:
                            break
                if count > 1:
                    if same_row >= 0:
                        for j in rows[same_row]:
                            if box_of[j] != box_of[box[0]] and (cands[j] & bit):
                                if not eliminate(cands, j, bit):
                                    return False
                    if same_col >= 0:
                        for j in cols[same_col]:
                            if box_of[j] != box_of[box[0]] and (cands[j] & bit):
                                if not eliminate(cands, j, bit):
                                    return False

        # Claiming
        for row in rows:
            for bit in bit_list:
                count = 0
                same_box = -1
                for idx in row:
                    if cands[idx] & bit:
                        count += 1
                        b = box_of[idx]
                        if same_box == -1:
                            same_box = b
                        elif same_box != b:
                            same_box = -2
                            break
                if count > 1 and same_box >= 0:
                    for j in boxes[same_box]:
                        if row_of[j] != row_of[row[0]] and (cands[j] & bit):
                            if not eliminate(cands, j, bit):
                                return False

        for col in cols:
            for bit in bit_list:
                count = 0
                same_box = -1
                for idx in col:
                    if cands[idx] & bit:
                        count += 1
                        b = box_of[idx]
                        if same_box == -1:
                            same_box = b
                        elif same_box != b:
                            same_box = -2
                            break
                if count > 1 and same_box >= 0:
                    for j in boxes[same_box]:
                        if col_of[j] != col_of[col[0]] and (cands[j] & bit):
                            if not eliminate(cands, j, bit):
                                return False
        return True

    def apply_naked_subsets(cands, max_k=4):
        for house in houses:
            candidates = [idx for idx in house if 2 <= cands[idx].bit_count() <= max_k]
            if len(candidates) < 2:
                continue
            limit = min(max_k, len(candidates))
            for k in range(2, limit + 1):
                for comb in combinations(candidates, k):
                    union = 0
                    valid = True
                    for idx in comb:
                        union |= cands[idx]
                        if union.bit_count() > k:
                            valid = False
                            break
                    if not valid or union.bit_count() != k:
                        continue
                    comb_set = set(comb)
                    for j in house:
                        if j not in comb_set and (cands[j] & union):
                            if not eliminate(cands, j, union):
                                return False
        return True

    def apply_hidden_subsets(cands, max_k=3):
        for house in houses:
            digit_positions = []
            for bit in bit_list:
                pos = tuple(idx for idx in house if cands[idx] & bit)
                if 2 <= len(pos) <= max_k:
                    digit_positions.append((bit, pos))
            if len(digit_positions) < 2:
                continue

            limit = min(max_k, len(digit_positions))
            for k in range(2, limit + 1):
                for comb in combinations(digit_positions, k):
                    keep_mask = 0
                    cells = set()
                    for bit, pos in comb:
                        keep_mask |= bit
                        cells.update(pos)
                        if len(cells) > k:
                            break
                    if len(cells) != k:
                        continue
                    for idx in cells:
                        remove = cands[idx] & ~keep_mask
                        if remove:
                            if not eliminate(cands, idx, remove):
                                return False
        return True

    def stabilize(cands):
        while True:
            before = tuple(cands)
            if not apply_locked_candidates(cands):
                return False
            if not apply_naked_subsets(cands, 4):
                return False
            if not apply_hidden_subsets(cands, 3):
                return False
            if all(is_single(m) for m in cands):
                return True
            if tuple(cands) == before:
                return True

    def choose_cell(cands):
        best_idx = -1
        best_size = n + 1
        for idx, mask in enumerate(cands):
            bc = mask.bit_count()
            if 1 < bc < best_size:
                best_size = bc
                best_idx = idx
                if bc == 2:
                    break
        return best_idx

    def ordered_bits(cands, idx):
        items = []
        mask = cands[idx]
        while mask:
            bit = mask & -mask
            mask -= bit
            score = 0
            for p in peers[idx]:
                if cands[p] & bit:
                    score += 1
            items.append((score, bit))
        items.sort()
        return [bit for _, bit in items]

    def search(cands):
        if not stabilize(cands):
            return None
        if all(is_single(m) for m in cands):
            return cands

        idx = choose_cell(cands)
        if idx < 0:
            return None

        for bit in ordered_bits(cands, idx):
            nxt = cands[:]
            if assign(nxt, idx, bit):
                res = search(nxt)
                if res is not None:
                    return res
        return None

    cands = [full_mask] * cell_count

    for r in range(n):
        for c in range(n):
            value = data[r][c]
            if value is None:
                continue
            if not (1 <= value <= n):
                return "No Solution"
            if not assign(cands, r * n + c, 1 << (value - 1)):
                return "No Solution"

    solved = search(cands)
    if solved is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(mask_to_value(solved[r * n + c]))
        grid.append(row)
    return str(grid)


