# General solver for the described single-loop dot-grid puzzle.
# The solver uses:
# - vertex-state CSP (unused / straight / turn)
# - arc-consistency on adjacent vertices
# - clue-pattern generation with length constraints
# - forced-pattern propagation
# - bad-subcycle pruning
# - limited backtracking guided by clue-pattern ambiguity

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # N, E, S, W
OPP = [2, 3, 0, 1]
DBIT = [1, 2, 4, 8]

STATE_NAMES = ["U", "H", "V", "NE", "ES", "SW", "WN"]
STATE_EDGES = [
    0,          # U
    DBIT[1] | DBIT[3],  # H
    DBIT[0] | DBIT[2],  # V
    DBIT[0] | DBIT[1],  # NE
    DBIT[1] | DBIT[2],  # ES
    DBIT[2] | DBIT[3],  # SW
    DBIT[3] | DBIT[0],  # WN
]

U_IDX = 0
H_IDX = 1
V_IDX = 2
TURN_IDXS = (3, 4, 5, 6)

ALL_STATE_MASK = (1 << len(STATE_NAMES)) - 1
USED_MASK = sum(1 << i for i, e in enumerate(STATE_EDGES) if e)
TURN_MASK = sum(1 << i for i in TURN_IDXS)
WHITE_MASK = (1 << H_IDX) | (1 << V_IDX)

STATE_LISTS = [tuple(i for i in range(len(STATE_NAMES)) if (m >> i) & 1) for m in range(1 << len(STATE_NAMES))]
EDGE_YES_MASK = [0, 0, 0, 0]
for d in range(4):
    mask = 0
    for i, e in enumerate(STATE_EDGES):
        if e & DBIT[d]:
            mask |= 1 << i
    EDGE_YES_MASK[d] = mask
EDGE_NO_MASK = [ALL_STATE_MASK ^ EDGE_YES_MASK[d] for d in range(4)]

STRAIGHT_FOR_DIR = [V_IDX, H_IDX, V_IDX, H_IDX]
STRAIGHT_MASK_FOR_DIR = [1 << STRAIGHT_FOR_DIR[d] for d in range(4)]

TURN_IN_MASK = [0, 0, 0, 0]
for incoming_dir in range(4):
    mask = 0
    for i in TURN_IDXS:
        if STATE_EDGES[i] & DBIT[incoming_dir]:
            mask |= 1 << i
    TURN_IN_MASK[incoming_dir] = mask


def solve(observation):
    data = observation["data"]
    R = len(data)
    C = len(data[0])
    if R != C:
        return "No Solution"
    N = R - 1
    VCOUNT = R * C

    def vid(r, c):
        return r * C + c

    def rc(v):
        return divmod(v, C)

    neighbors = [[None] * 4 for _ in range(VCOUNT)]
    for r in range(R):
        for c in range(C):
            v = vid(r, c)
            for d, (dr, dc) in enumerate(DIRS):
                rr, cc = r + dr, c + dc
                if 0 <= rr < R and 0 <= cc < C:
                    neighbors[v][d] = vid(rr, cc)

    clues = {}
    clue_order = []
    for r in range(R):
        for c in range(C):
            tok = data[r][c]
            if tok is not None:
                color = tok[0]
                k = int(tok[1:])
                v = vid(r, c)
                clues[v] = (color, k)
                clue_order.append(v)

    base_domains = [0] * VCOUNT
    for r in range(R):
        for c in range(C):
            v = vid(r, c)
            dom = ALL_STATE_MASK
            # Border validity
            valid = 0
            for si, e in enumerate(STATE_EDGES):
                ok = True
                for d in range(4):
                    if (e & DBIT[d]) and neighbors[v][d] is None:
                        ok = False
                        break
                if ok:
                    valid |= 1 << si
            dom &= valid

            # Clue restrictions
            tok = data[r][c]
            if tok is not None:
                if tok[0] == "W":
                    dom &= WHITE_MASK
                else:
                    dom &= TURN_MASK
            base_domains[v] = dom

    if any(d == 0 for d in base_domains):
        return "No Solution"

    def is_singleton(mask):
        return mask and (mask & (mask - 1)) == 0

    def singleton_idx(mask):
        if not is_singleton(mask):
            return -1
        return mask.bit_length() - 1

    def revise_pair(domains, a, b, d):
        da = domains[a]
        db = domains[b]
        need_yes = db & EDGE_YES_MASK[OPP[d]]
        need_no = db & EDGE_NO_MASK[OPP[d]]
        new_da = 0
        for si in STATE_LISTS[da]:
            if STATE_EDGES[si] & DBIT[d]:
                if need_yes:
                    new_da |= 1 << si
            else:
                if need_no:
                    new_da |= 1 << si
        if new_da != da:
            if new_da == 0:
                return False, True
            domains[a] = new_da
            return True, True
        return True, False

    def ray_lengths(domains, start_v, d):
        sr = STRAIGHT_FOR_DIR[d]
        turnmask = TURN_IN_MASK[OPP[d]]
        out = []
        cur = start_v
        dist = 0
        while True:
            cur = neighbors[cur][d]
            if cur is None:
                break
            dist += 1
            dom = domains[cur]
            if dom & turnmask:
                out.append(dist)
            if not (dom & (1 << sr)):
                break
        return out

    def enumerate_clue_patterns(domains, clue_v):
        color, k = clues[clue_v]
        patterns = []
        seen = set()
        for si in STATE_LISTS[domains[clue_v]]:
            if color == "W" and si not in (H_IDX, V_IDX):
                continue
            if color == "B" and si not in TURN_IDXS:
                continue
            e = STATE_EDGES[si]
            dirs = [d for d in range(4) if e & DBIT[d]]
            if len(dirs) != 2:
                continue
            lsets = [ray_lengths(domains, clue_v, dirs[0]), ray_lengths(domains, clue_v, dirs[1])]
            if not lsets[0] or not lsets[1]:
                continue

            for l1 in lsets[0]:
                l2 = k - l1
                if l2 not in lsets[1]:
                    continue

                cons = {clue_v: 1 << si}
                ok = True
                for d, L in ((dirs[0], l1), (dirs[1], l2)):
                    cur = clue_v
                    for _ in range(1, L):
                        cur = neighbors[cur][d]
                        req = STRAIGHT_MASK_FOR_DIR[d]
                        nm = cons.get(cur, ALL_STATE_MASK) & req
                        if not (nm & domains[cur]):
                            ok = False
                            break
                        cons[cur] = nm
                    if not ok:
                        break
                    cur = clue_v
                    for _ in range(L):
                        cur = neighbors[cur][d]
                        if cur is None:
                            ok = False
                            break
                    if not ok:
                        break
                    req = TURN_IN_MASK[OPP[d]]
                    nm = cons.get(cur, ALL_STATE_MASK) & req
                    if not (nm & domains[cur]):
                        ok = False
                        break
                    cons[cur] = nm
                if not ok:
                    continue

                key = tuple(sorted(cons.items()))
                if key not in seen:
                    seen.add(key)
                    patterns.append(cons)
        return patterns

    def bad_forced_cycle(domains):
        fixed_used = [False] * VCOUNT
        for v in range(VCOUNT):
            if is_singleton(domains[v]):
                si = singleton_idx(domains[v])
                if si != U_IDX:
                    fixed_used[v] = True

        seen = [False] * VCOUNT
        closed_components = []

        for v in range(VCOUNT):
            if not fixed_used[v] or seen[v]:
                continue
            stack = [v]
            seen[v] = True
            comp = []
            while stack:
                x = stack.pop()
                comp.append(x)
                si = singleton_idx(domains[x])
                e = STATE_EDGES[si]
                for d in range(4):
                    if e & DBIT[d]:
                        y = neighbors[x][d]
                        if y is None or not fixed_used[y]:
                            continue
                        sj = singleton_idx(domains[y])
                        if not (STATE_EDGES[sj] & DBIT[OPP[d]]):
                            continue
                        if not seen[y]:
                            seen[y] = True
                            stack.append(y)

            closed = True
            for x in comp:
                si = singleton_idx(domains[x])
                e = STATE_EDGES[si]
                for d in range(4):
                    if e & DBIT[d]:
                        y = neighbors[x][d]
                        if y is None or y not in comp:
                            closed = False
                            break
                        sj = singleton_idx(domains[y])
                        if sj < 0 or not (STATE_EDGES[sj] & DBIT[OPP[d]]):
                            closed = False
                            break
                if not closed:
                    break
            if closed:
                closed_components.append(set(comp))

        if not closed_components:
            return False
        if len(closed_components) > 1:
            return True

        comp = closed_components[0]
        for cv in clue_order:
            if cv not in comp:
                return True
        for v in range(VCOUNT):
            if v not in comp and (domains[v] & USED_MASK):
                return True
        return False

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # Local adjacency consistency
            local_change = True
            while local_change:
                local_change = False
                for v in range(VCOUNT):
                    for d in range(4):
                        u = neighbors[v][d]
                        if u is None:
                            continue
                        ok, ch = revise_pair(domains, v, u, d)
                        if not ok:
                            return None
                        if ch:
                            local_change = True
                            changed = True

            # Clue-pattern analysis
            for clue_v in clue_order:
                patterns = enumerate_clue_patterns(domains, clue_v)
                if not patterns:
                    return None

                # Clue state pruning
                clue_allowed = 0
                for p in patterns:
                    clue_allowed |= p[clue_v]
                nd = domains[clue_v] & clue_allowed
                if nd == 0:
                    return None
                if nd != domains[clue_v]:
                    domains[clue_v] = nd
                    changed = True

                # If only one pattern remains, force it
                if len(patterns) == 1:
                    p = patterns[0]
                    for v, mask in p.items():
                        nd = domains[v] & mask
                        if nd == 0:
                            return None
                        if nd != domains[v]:
                            domains[v] = nd
                            changed = True
                else:
                    # If every pattern constrains a vertex, union those allowed masks.
                    counts = {}
                    unions = {}
                    for p in patterns:
                        for v, mask in p.items():
                            counts[v] = counts.get(v, 0) + 1
                            unions[v] = unions.get(v, 0) | mask
                    plen = len(patterns)
                    for v, cnt in counts.items():
                        if cnt == plen:
                            nd = domains[v] & unions[v]
                            if nd == 0:
                                return None
                            if nd != domains[v]:
                                domains[v] = nd
                                changed = True

            # Re-run local consistency after clue forcing
            local_change = True
            while local_change:
                local_change = False
                for v in range(VCOUNT):
                    for d in range(4):
                        u = neighbors[v][d]
                        if u is None:
                            continue
                        ok, ch = revise_pair(domains, v, u, d)
                        if not ok:
                            return None
                        if ch:
                            local_change = True
                            changed = True

            if bad_forced_cycle(domains):
                return None

        return domains

    def final_validate(domains):
        if not all(is_singleton(d) for d in domains):
            return False

        states = [singleton_idx(d) for d in domains]

        # Base validity
        for v in range(VCOUNT):
            if not (base_domains[v] & (1 << states[v])):
                return False

        # Build adjacency for used graph
        adj = [[] for _ in range(VCOUNT)]
        used_vertices = []
        for v in range(VCOUNT):
            si = states[v]
            e = STATE_EDGES[si]
            if si != U_IDX:
                used_vertices.append(v)
            for d in range(4):
                if e & DBIT[d]:
                    u = neighbors[v][d]
                    if u is None:
                        return False
                    if not (STATE_EDGES[states[u]] & DBIT[OPP[d]]):
                        return False
                    adj[v].append(u)

        for v in used_vertices:
            if len(adj[v]) != 2:
                return False

        if not used_vertices:
            return False

        # Single cycle
        start = used_vertices[0]
        seen = set()
        prev = None
        cur = start
        while True:
            if cur in seen:
                if cur != start:
                    return False
                break
            seen.add(cur)
            nbs = adj[cur]
            if len(nbs) != 2:
                return False
            nxt = nbs[0] if nbs[0] != prev else nbs[1]
            prev, cur = cur, nxt
            if cur == start:
                break
        if set(used_vertices) != seen:
            return False

        # Exact clue validation
        def arm_length(clue_v, d):
            cur = clue_v
            dist = 0
            while True:
                cur = neighbors[cur][d]
                if cur is None:
                    return None
                dist += 1
                si = states[cur]
                if si == STRAIGHT_FOR_DIR[d]:
                    continue
                if si in TURN_IDXS and (STATE_EDGES[si] & DBIT[OPP[d]]):
                    return dist
                return None

        for clue_v in clue_order:
            color, k = clues[clue_v]
            si = states[clue_v]
            if color == "W" and si not in (H_IDX, V_IDX):
                return False
            if color == "B" and si not in TURN_IDXS:
                return False
            dirs = [d for d in range(4) if STATE_EDGES[si] & DBIT[d]]
            if len(dirs) != 2:
                return False
            l1 = arm_length(clue_v, dirs[0])
            l2 = arm_length(clue_v, dirs[1])
            if l1 is None or l2 is None or l1 + l2 != k:
                return False

        return True

    def build_path(domains):
        states = [singleton_idx(d) for d in domains]
        adj = [[] for _ in range(VCOUNT)]
        used = []
        for v in range(VCOUNT):
            si = states[v]
            if si == U_IDX:
                continue
            used.append(v)
            e = STATE_EDGES[si]
            for d in range(4):
                if e & DBIT[d]:
                    adj[v].append(neighbors[v][d])

        start = min(used)
        path = [rc(start)]
        prev = None
        cur = start
        seen = set()
        while True:
            seen.add(cur)
            nbs = adj[cur]
            nxt = nbs[0] if nbs[0] != prev else nbs[1]
            prev, cur = cur, nxt
            path.append(rc(cur))
            if cur == start:
                break
            if cur in seen:
                return "No Solution"
        return path

    def choose_branch_vertex(domains):
        best = None
        best_key = None
        for v in range(VCOUNT):
            d = domains[v]
            bc = d.bit_count()
            if bc <= 1:
                continue
            key = (0 if v in clues else 1, bc, -sum(1 for x in neighbors[v] if x is not None))
            if best_key is None or key < best_key:
                best = v
                best_key = key
        return best

    def search(domains):
        domains = propagate(list(domains))
        if domains is None:
            return None

        if all(is_singleton(d) for d in domains):
            if final_validate(domains):
                return domains
            return None

        # Prefer branching on the most constrained clue pattern set
        best_clue = None
        best_patterns = None
        for clue_v in clue_order:
            pats = enumerate_clue_patterns(domains, clue_v)
            if len(pats) > 1:
                if best_patterns is None or len(pats) < len(best_patterns):
                    best_clue = clue_v
                    best_patterns = pats

        if best_patterns is not None:
            best_patterns.sort(key=lambda p: (-len(p), sorted(p.items())))
            for p in best_patterns:
                nd = list(domains)
                ok = True
                for v, mask in p.items():
                    nv = nd[v] & mask
                    if nv == 0:
                        ok = False
                        break
                    nd[v] = nv
                if ok:
                    res = search(nd)
                    if res is not None:
                        return res
            return None

        # Fallback: branch on a vertex state
        v = choose_branch_vertex(domains)
        if v is None:
            return None

        options = list(STATE_LISTS[domains[v]])
        options.sort(key=lambda si: (si == U_IDX, si))
        for si in options:
            nd = list(domains)
            nd[v] = 1 << si
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(base_domains)
    if result is None:
        return "No Solution"
    return build_path(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 0, 0, 1, 1], [0, 2, 2, 2, 2, 3, 1, 1], [4, 4, 5, 5, 3, 3, 3, 1], [4, 4, 5, 5, 3, 3, 7, 7], [8, 4, 5, 5, 6, 6, 7, 7], [8, 8, 8, 5, 6, 6, 7, 7], [8, 9, 9, 9, 9, 6, 10, 10], [8, 8, 8, 8, 9, 10, 10, 10]]}

from collections import defaultdict

TYPE_ORDER = "ILTS"
TYPE_INDEX = {ch: i for i, ch in enumerate(TYPE_ORDER)}


def iter_bits(mask):
    while mask:
        lb = mask & -mask
        yield lb.bit_length() - 1
        mask ^= lb


def normalize_shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))


def all_symmetries(cells):
    out = set()
    for sr, sc, swap in (
        (1, 1, False), (1, -1, False), (-1, 1, False), (-1, -1, False),
        (1, 1, True), (1, -1, True), (-1, 1, True), (-1, -1, True),
    ):
        transformed = []
        for r, c in cells:
            if swap:
                r, c = c, r
            transformed.append((sr * r, sc * c))
        out.add(normalize_shape(transformed))
    return sorted(out)


def build_orientations():
    bases = {
        "I": [(0, 0), (1, 0), (2, 0), (3, 0)],
        "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
        "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
        "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
    }
    return {k: all_symmetries(v) for k, v in bases.items()}


ORIENTATIONS = build_orientations()


def mask_connected(mask, cell_neighbors):
    if mask == 0:
        return True
    start = mask & -mask
    seen = 0
    frontier = start
    while frontier:
        seen |= frontier
        nxt = 0
        for idx in iter_bits(frontier):
            nxt |= cell_neighbors[idx]
        frontier = nxt & mask & ~seen
    return seen == mask


def components_of(mask, cell_neighbors):
    comps = []
    remaining = mask
    while remaining:
        start = remaining & -remaining
        comp = 0
        frontier = start
        while frontier:
            comp |= frontier
            nxt = 0
            for idx in iter_bits(frontier):
                nxt |= cell_neighbors[idx]
            frontier = nxt & mask & ~comp
        comps.append(comp)
        remaining &= ~comp
    return comps


def solve(observation):
    data = observation["data"]
    n = len(data)
    total_cells = n * n

    cell_idx = lambda r, c: r * n + c

    cell_neighbors = [0] * total_cells
    for r in range(n):
        for c in range(n):
            idx = cell_idx(r, c)
            m = 0
            if r > 0:
                m |= 1 << cell_idx(r - 1, c)
            if r + 1 < n:
                m |= 1 << cell_idx(r + 1, c)
            if c > 0:
                m |= 1 << cell_idx(r, c - 1)
            if c + 1 < n:
                m |= 1 << cell_idx(r, c + 1)
            cell_neighbors[idx] = m

    raw_ids = sorted({x for row in data for x in row})
    rid_map = {rid: i for i, rid in enumerate(raw_ids)}
    region_grid = [[rid_map[x] for x in row] for row in data]
    region_count = len(raw_ids)

    region_cells = [[] for _ in range(region_count)]
    region_cell_set = [set() for _ in range(region_count)]
    cell_region = [None] * total_cells

    for r in range(n):
        for c in range(n):
            reg = region_grid[r][c]
            idx = cell_idx(r, c)
            region_cells[reg].append((r, c))
            region_cell_set[reg].add((r, c))
            cell_region[idx] = reg

    region_adj = [set() for _ in range(region_count)]
    for r in range(n):
        for c in range(n):
            a = region_grid[r][c]
            if r + 1 < n:
                b = region_grid[r + 1][c]
                if a != b:
                    region_adj[a].add(b)
                    region_adj[b].add(a)
            if c + 1 < n:
                b = region_grid[r][c + 1]
                if a != b:
                    region_adj[a].add(b)
                    region_adj[b].add(a)

    block_masks = []
    for r in range(n - 1):
        for c in range(n - 1):
            block_masks.append(
                (1 << cell_idx(r, c))
                | (1 << cell_idx(r + 1, c))
                | (1 << cell_idx(r, c + 1))
                | (1 << cell_idx(r + 1, c + 1))
            )

    candidates = []
    cand_cells = []
    cand_types = []
    cand_nbrmask = []
    cell_to_candmask = []

    for reg in range(region_count):
        cellset = region_cell_set[reg]
        seen = {}
        for tchar, orients in ORIENTATIONS.items():
            tidx = TYPE_INDEX[tchar]
            for shape in orients:
                for br, bc in region_cells[reg]:
                    placed = tuple(sorted((br + dr, bc + dc) for dr, dc in shape))
                    if all((rr, cc) in cellset for rr, cc in placed):
                        key = placed
                        if key not in seen:
                            mask = 0
                            for rr, cc in placed:
                                mask |= 1 << cell_idx(rr, cc)
                            nbrmask = 0
                            for rr, cc in placed:
                                nbrmask |= cell_neighbors[cell_idx(rr, cc)]
                            seen[key] = (mask, tidx, nbrmask)
        region_cands = list(seen.values())
        if not region_cands:
            return "No Solution"
        candidates.append(region_cands)
        cand_cells.append([x[0] for x in region_cands])
        cand_types.append([x[1] for x in region_cands])
        cand_nbrmask.append([x[2] for x in region_cands])

        cell_masks = defaultdict(int)
        for i, (mask, _, _) in enumerate(region_cands):
            bit = 1 << i
            for idx in iter_bits(mask):
                cell_masks[idx] |= bit
        cell_to_candmask.append(cell_masks)

    full_domains = tuple((1 << len(candidates[r])) - 1 for r in range(region_count))

    type_support = [dict() for _ in range(region_count)]
    touch_support = [dict() for _ in range(region_count)]

    for a in range(region_count):
        for b in region_adj[a]:
            t_sup = [0] * len(candidates[a])
            c_sup = [0] * len(candidates[a])
            for i in range(len(candidates[a])):
                ti = cand_types[a][i]
                nm = cand_nbrmask[a][i]
                ts = 0
                cs = 0
                for j in range(len(candidates[b])):
                    if cand_types[b][j] != ti:
                        ts |= 1 << j
                        if nm & cand_cells[b][j]:
                            cs |= 1 << j
                t_sup[i] = ts
                c_sup[i] = cs
            type_support[a][b] = t_sup
            touch_support[a][b] = c_sup

    def domain_stats(domains):
        unions = [0] * region_count
        inters = [0] * region_count
        typemasks = [0] * region_count
        for r in range(region_count):
            d = domains[r]
            first = True
            u = 0
            inter = 0
            tmask = 0
            for i in iter_bits(d):
                cm = cand_cells[r][i]
                u |= cm
                inter = cm if first else (inter & cm)
                first = False
                tmask |= 1 << cand_types[r][i]
            unions[r] = u
            inters[r] = inter
            typemasks[r] = tmask
        return unions, inters, typemasks

    def connected_region_graph(domains, comp_masks):
        g = [set() for _ in range(region_count)]
        for a in range(region_count):
            for b in region_adj[a]:
                if a < b:
                    da = domains[a]
                    db = domains[b]
                    ok = False
                    for i in iter_bits(da):
                        if db & touch_support[a][b][i]:
                            ok = True
                            break
                    if ok:
                        g[a].add(b)
                        g[b].add(a)
        seen = {0}
        stack = [0]
        while stack:
            x = stack.pop()
            for y in g[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return len(seen) == region_count

    def propagate(domains):
        domains = list(domains)
        while True:
            changed = False

            for r in range(region_count):
                if domains[r] == 0:
                    return None

            unions, inters, _ = domain_stats(domains)
            possible_global = 0
            forced_global = 0
            for r in range(region_count):
                possible_global |= unions[r]
                forced_global |= inters[r]

            # Connectivity-by-components pruning:
            comps = components_of(possible_global, cell_neighbors)
            strong_comps = []
            comp_allowed = []

            for comp in comps:
                subdomains = [0] * region_count
                good = True
                for r in range(region_count):
                    sd = 0
                    for i in iter_bits(domains[r]):
                        if cand_cells[r][i] & ~comp == 0:
                            sd |= 1 << i
                    if sd == 0:
                        good = False
                        break
                    subdomains[r] = sd
                if good and (region_count == 1 or connected_region_graph(subdomains, comp)):
                    strong_comps.append(comp)
                    comp_allowed.append(subdomains)

            if not strong_comps:
                return None

            # If forced cells already exist, they must all fit in some surviving component.
            forced_fit = [k for k, comp in enumerate(strong_comps) if forced_global & ~comp == 0]
            if forced_global and not forced_fit:
                return None

            # Prune candidates outside all surviving components.
            for r in range(region_count):
                keep = 0
                for sub in comp_allowed:
                    keep |= sub[r]
                nd = domains[r] & keep
                if nd != domains[r]:
                    domains[r] = nd
                    changed = True
                    if nd == 0:
                        return None

            if changed:
                continue

            # Type arc consistency.
            for a in range(region_count):
                rem = 0
                for i in iter_bits(domains[a]):
                    ok = True
                    for b in region_adj[a]:
                        if domains[b] & type_support[a][b][i] == 0:
                            ok = False
                            break
                    if not ok:
                        rem |= 1 << i
                if rem:
                    domains[a] &= ~rem
                    changed = True
                    if domains[a] == 0:
                        return None
            if changed:
                continue

            unions, inters, _ = domain_stats(domains)
            possible_global = 0
            forced_global = 0
            for r in range(region_count):
                possible_global |= unions[r]
                forced_global |= inters[r]

            # 2x2 pruning with forced cells.
            for block in block_masks:
                f = forced_global & block
                fc = f.bit_count()
                if fc == 4:
                    return None
                if fc == 3:
                    leftover = block & ~forced_global
                    if leftover and (possible_global & leftover):
                        idx = (leftover & -leftover).bit_length() - 1
                        reg = cell_region[idx]
                        forbid = domains[reg] & cell_to_candmask[reg].get(idx, 0)
                        if forbid:
                            domains[reg] &= ~forbid
                            changed = True
                            if domains[reg] == 0:
                                return None
            if changed:
                continue

            # Every candidate must be able to touch at least one neighbor in a connected solution.
            if region_count > 1:
                for a in range(region_count):
                    rem = 0
                    for i in iter_bits(domains[a]):
                        touch_ok = False
                        for b in region_adj[a]:
                            if domains[b] & touch_support[a][b][i]:
                                touch_ok = True
                                break
                        if not touch_ok:
                            rem |= 1 << i
                    if rem:
                        domains[a] &= ~rem
                        changed = True
                        if domains[a] == 0:
                            return None
                if changed:
                    continue

            # Potential region-touch graph must remain connected.
            if region_count > 1:
                g = [set() for _ in range(region_count)]
                for a in range(region_count):
                    for b in region_adj[a]:
                        if a < b:
                            ok = False
                            for i in iter_bits(domains[a]):
                                if domains[b] & touch_support[a][b][i]:
                                    ok = True
                                    break
                            if ok:
                                g[a].add(b)
                                g[b].add(a)
                seen = {0}
                stack = [0]
                while stack:
                    x = stack.pop()
                    for y in g[x]:
                        if y not in seen:
                            seen.add(y)
                            stack.append(y)
                if len(seen) != region_count:
                    return None

            return tuple(domains)

    def final_check(domains):
        chosen_masks = []
        chosen_types = []
        shaded = 0
        for r in range(region_count):
            d = domains[r]
            if d == 0 or d & (d - 1):
                return None
            i = d.bit_length() - 1
            chosen_masks.append(cand_cells[r][i])
            chosen_types.append(cand_types[r][i])
            shaded |= cand_cells[r][i]

        for a in range(region_count):
            for b in region_adj[a]:
                if a < b and chosen_types[a] == chosen_types[b]:
                    return None

        for block in block_masks:
            if shaded & block == block:
                return None

        if not mask_connected(shaded, cell_neighbors):
            return None

        ans = [[None for _ in range(n)] for _ in range(n)]
        for r in range(region_count):
            letter = TYPE_ORDER[chosen_types[r]]
            for idx in iter_bits(chosen_masks[r]):
                rr, cc = divmod(idx, n)
                ans[rr][cc] = letter
        return ans

    seen_fail = set()

    def choose_region(domains):
        best = None
        best_key = None
        for r in range(region_count):
            cnt = domains[r].bit_count()
            if cnt > 1:
                # Prefer the smallest domain, then the most constrained adjacency.
                key = (cnt, -len(region_adj[r]))
                if best_key is None or key < best_key:
                    best_key = key
                    best = r
        return best

    def candidate_order(domains, r):
        out = []
        for i in iter_bits(domains[r]):
            touch_score = 0
            type_pressure = 0
            for b in region_adj[r]:
                touch_score += (domains[b] & touch_support[r][b][i]).bit_count()
                type_pressure += (domains[b] & type_support[r][b][i]).bit_count()
            out.append((-touch_score, type_pressure, i))
        out.sort()
        return [i for _, _, i in out]

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if domains in seen_fail:
            return None

        if all(d.bit_count() == 1 for d in domains):
            ans = final_check(domains)
            if ans is not None:
                return ans
            seen_fail.add(domains)
            return None

        r = choose_region(domains)
        for i in candidate_order(domains, r):
            new_domains = list(domains)
            new_domains[r] = 1 << i
            ans = dfs(tuple(new_domains))
            if ans is not None:
                return ans

        seen_fail.add(domains)
        return None

    answer = dfs(full_domains)
    return "No Solution" if answer is None else repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 2, None, 2, None], [None, None, 2, None, None], [1, 2, 1, 3, 2], [2, 3, None, None, None], [None, 2, 3, 3, None]]}

class State:
    __slots__ = ("vals", "masks")

    def __init__(self, vals, masks):
        self.vals = vals
        self.masks = masks


class SlitherlinkSolver:
    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.vertex_count = (self.n + 1) * (self.n + 1)

        self.h_edges = [[None] * self.n for _ in range(self.n + 1)]
        self.v_edges = [[None] * (self.n + 1) for _ in range(self.n)]
        self.edge_vertices = []
        self.edge_cells_all = []
        self.vertex_edges = [[] for _ in range(self.vertex_count)]
        self.cell_edges_all = [None] * (self.n * self.n)

        self._build_edges()

        self.clue_cells = []
        self.clue_values = []
        self.clue_edges = []
        self.clue_patterns = []
        self.clue_pat_to_bit = []
        self.edge_clue_pos = [[] for _ in range(len(self.edge_vertices))]
        self._build_clues()

        self.vertex_patterns = {
            d: [p for p in range(1 << d) if p.bit_count() in (0, 2)]
            for d in range(5)
        }

        self.edge_priority_base = []
        for e in range(len(self.edge_vertices)):
            clue_adj = len(self.edge_clue_pos[e])
            border = 1 if len(self.edge_cells_all[e]) == 1 else 0
            self.edge_priority_base.append(clue_adj * 10 + border)

    def _vid(self, r, c):
        return r * (self.n + 1) + c

    def _build_edges(self):
        eid = 0
        for r in range(self.n + 1):
            for c in range(self.n):
                self.h_edges[r][c] = eid
                u = self._vid(r, c)
                v = self._vid(r, c + 1)
                self.edge_vertices.append((u, v))
                self.edge_cells_all.append([])
                self.vertex_edges[u].append(eid)
                self.vertex_edges[v].append(eid)
                eid += 1

        for r in range(self.n):
            for c in range(self.n + 1):
                self.v_edges[r][c] = eid
                u = self._vid(r, c)
                v = self._vid(r + 1, c)
                self.edge_vertices.append((u, v))
                self.edge_cells_all.append([])
                self.vertex_edges[u].append(eid)
                self.vertex_edges[v].append(eid)
                eid += 1

        for r in range(self.n):
            for c in range(self.n):
                top = self.h_edges[r][c]
                right = self.v_edges[r][c + 1]
                bottom = self.h_edges[r + 1][c]
                left = self.v_edges[r][c]
                flat = r * self.n + c
                self.cell_edges_all[flat] = (top, right, bottom, left)
                for e in (top, right, bottom, left):
                    self.edge_cells_all[e].append(flat)

    def _build_clues(self):
        for r in range(self.n):
            for c in range(self.n):
                clue = self.data[r][c]
                if clue is None:
                    continue
                flat = r * self.n + c
                edges = self.cell_edges_all[flat]
                pats = [p for p in range(16) if p.bit_count() == clue]
                self.clue_cells.append(flat)
                self.clue_values.append(clue)
                self.clue_edges.append(edges)
                self.clue_patterns.append(pats)
                self.clue_pat_to_bit.append({p: i for i, p in enumerate(pats)})
                ci = len(self.clue_cells) - 1
                for pos, e in enumerate(edges):
                    self.edge_clue_pos[e].append((ci, pos))

    def initial_state(self):
        vals = [-1] * len(self.edge_vertices)
        masks = [(1 << len(pats)) - 1 for pats in self.clue_patterns]
        return State(vals, masks)

    def clone_state(self, state):
        return State(state.vals[:], state.masks[:])

    def _check_components(self, state):
        vals = state.vals
        deg = [0] * self.vertex_count
        on_adj = {}

        for e, v in enumerate(vals):
            if v == 1:
                a, b = self.edge_vertices[e]
                deg[a] += 1
                deg[b] += 1
                if deg[a] > 2 or deg[b] > 2:
                    return False
                on_adj.setdefault(a, []).append(b)
                on_adj.setdefault(b, []).append(a)

        seen = set()
        comp_count = 0
        cycle_count = 0

        for start in on_adj:
            if start in seen:
                continue
            comp_count += 1
            stack = [start]
            seen.add(start)
            all_deg2 = True
            while stack:
                u = stack.pop()
                if len(on_adj[u]) != 2:
                    all_deg2 = False
                for v in on_adj[u]:
                    if v not in seen:
                        seen.add(v)
                        stack.append(v)
            if all_deg2:
                cycle_count += 1
                if cycle_count > 1:
                    return False

        if cycle_count == 1 and comp_count > 1:
            return False
        return True

    def propagate_basic(self, state):
        vals = state.vals
        masks = state.masks

        while True:
            changed = False

            for ci, edges in enumerate(self.clue_edges):
                pats = self.clue_patterns[ci]
                mask = masks[ci]
                newmask = 0
                kept = []

                for i, p in enumerate(pats):
                    if not ((mask >> i) & 1):
                        continue
                    ok = True
                    for d, e in enumerate(edges):
                        ev = vals[e]
                        if ev != -1 and ev != ((p >> d) & 1):
                            ok = False
                            break
                    if ok:
                        newmask |= 1 << i
                        kept.append(p)

                if newmask == 0:
                    return False
                if newmask != mask:
                    masks[ci] = newmask
                    changed = True

                if kept:
                    for d, e in enumerate(edges):
                        if vals[e] != -1:
                            continue
                        b = (kept[0] >> d) & 1
                        same = True
                        for p in kept[1:]:
                            if ((p >> d) & 1) != b:
                                same = False
                                break
                        if same:
                            vals[e] = b
                            changed = True

            for vid, inc in enumerate(self.vertex_edges):
                d = len(inc)
                allowed = self.vertex_patterns[d]
                kept = []

                for p in allowed:
                    ok = True
                    for i, e in enumerate(inc):
                        ev = vals[e]
                        if ev != -1 and ev != ((p >> i) & 1):
                            ok = False
                            break
                    if ok:
                        kept.append(p)

                if not kept:
                    return False

                for i, e in enumerate(inc):
                    if vals[e] != -1:
                        continue
                    b = (kept[0] >> i) & 1
                    same = True
                    for p in kept[1:]:
                        if ((p >> i) & 1) != b:
                            same = False
                            break
                    if same:
                        vals[e] = b
                        changed = True

            if not self._check_components(state):
                return False

            if not changed:
                return True

    def _edge_support_counts(self, state, e):
        on = 0
        off = 0
        for ci, pos in self.edge_clue_pos[e]:
            pats = self.clue_patterns[ci]
            mask = state.masks[ci]
            for i, p in enumerate(pats):
                if (mask >> i) & 1:
                    if (p >> pos) & 1:
                        on += 1
                    else:
                        off += 1
        return on, off

    def lookahead_deduce(self, state):
        unknown = [e for e, v in enumerate(state.vals) if v == -1]
        if not unknown:
            return 0

        clue_adj = [e for e in unknown if self.edge_clue_pos[e]]
        cands = clue_adj if clue_adj else unknown

        def key(e):
            on, off = self._edge_support_counts(state, e)
            bias = min(on, off) if self.edge_clue_pos[e] else 99
            return (-self.edge_priority_base[e], bias)

        cands.sort(key=key)

        for e in cands:
            bad0 = False
            bad1 = False

            st0 = self.clone_state(state)
            st0.vals[e] = 0
            if not self.propagate_basic(st0):
                bad0 = True

            st1 = self.clone_state(state)
            st1.vals[e] = 1
            if not self.propagate_basic(st1):
                bad1 = True

            if bad0 and bad1:
                return -1
            if bad0 and not bad1:
                state.vals[e] = 1
                return 1
            if bad1 and not bad0:
                state.vals[e] = 0
                return 1

        return 0

    def propagate(self, state):
        if not self.propagate_basic(state):
            return False

        while True:
            step = self.lookahead_deduce(state)
            if step == -1:
                return False
            if step == 0:
                return True
            if not self.propagate_basic(state):
                return False

    def _mask_patterns(self, ci, mask):
        pats = self.clue_patterns[ci]
        out = []
        for i, p in enumerate(pats):
            if (mask >> i) & 1:
                out.append(p)
        return out

    def _apply_cell_pattern(self, state, ci, p):
        edges = self.clue_edges[ci]
        vals = state.vals
        for d, e in enumerate(edges):
            b = (p >> d) & 1
            cur = vals[e]
            if cur != -1 and cur != b:
                return False
            vals[e] = b
        bit = self.clue_pat_to_bit[ci][p]
        state.masks[ci] = 1 << bit
        return True

    def choose_branch(self, state):
        best_ci = None
        best_key = None

        for ci, mask in enumerate(state.masks):
            size = mask.bit_count()
            if size <= 1:
                continue
            unknowns = sum(1 for e in self.clue_edges[ci] if state.vals[e] == -1)
            key = (size, -unknowns, -self.clue_values[ci])
            if best_key is None or key < best_key:
                best_key = key
                best_ci = ci

        if best_ci is not None:
            patterns = self._mask_patterns(best_ci, state.masks[best_ci])
            patterns.sort(key=lambda p: (-p.bit_count(), p))
            return ("cell", best_ci, patterns)

        best_e = None
        best_score = None
        for e, v in enumerate(state.vals):
            if v != -1:
                continue
            on, off = self._edge_support_counts(state, e)
            score = (self.edge_priority_base[e], -(abs(on - off)), -(on + off))
            if best_score is None or score > best_score:
                best_score = score
                best_e = e

        if best_e is None:
            return None

        on, off = self._edge_support_counts(state, best_e)
        if on < off:
            order = [1, 0]
        elif off < on:
            order = [0, 1]
        else:
            order = [1, 0]
        return ("edge", best_e, order)

    def is_complete_solution(self, state):
        if any(v == -1 for v in state.vals):
            return False

        for ci, edges in enumerate(self.clue_edges):
            total = sum(state.vals[e] for e in edges)
            if total != self.clue_values[ci]:
                return False

        if not self._check_components(state):
            return False

        on_adj = {}
        on_edges = 0
        for e, v in enumerate(state.vals):
            if v == 1:
                on_edges += 1
                a, b = self.edge_vertices[e]
                on_adj.setdefault(a, []).append(b)
                on_adj.setdefault(b, []).append(a)

        if on_edges == 0:
            return False

        for u, nbrs in on_adj.items():
            if len(nbrs) != 2:
                return False

        start = next(iter(on_adj))
        seen = {start}
        stack = [start]
        while stack:
            u = stack.pop()
            for v in on_adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)

        return len(seen) == len(on_adj)

    def extract_loop(self, state):
        on_adj = {}
        for e, v in enumerate(state.vals):
            if v == 1:
                a, b = self.edge_vertices[e]
                on_adj.setdefault(a, []).append(b)
                on_adj.setdefault(b, []).append(a)

        start = min(on_adj)
        path = [start]
        prev = None
        cur = start

        while True:
            nbrs = on_adj[cur]
            if prev is None:
                nxt = min(nbrs)
            else:
                nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break

        return [divmod(v, self.n + 1) for v in path]

    def dfs(self, state):
        if not self.propagate(state):
            return None

        if self.is_complete_solution(state):
            return self.extract_loop(state)

        branch = self.choose_branch(state)
        if branch is None:
            return None

        kind, target, options = branch

        if kind == "cell":
            for p in options:
                nxt = self.clone_state(state)
                if not self._apply_cell_pattern(nxt, target, p):
                    continue
                ans = self.dfs(nxt)
                if ans is not None:
                    return ans
        else:
            e = target
            for v in options:
                nxt = self.clone_state(state)
                cur = nxt.vals[e]
                if cur != -1 and cur != v:
                    continue
                nxt.vals[e] = v
                ans = self.dfs(nxt)
                if ans is not None:
                    return ans

        return None

    def run(self):
        return self.dfs(self.initial_state())


def solve(observation):
    data = observation["data"]
    solver = SlitherlinkSolver(data)
    ans = solver.run()
    return "No Solution" if ans is None else repr(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

