from functools import lru_cache


def solve(observation):
    data = observation["data"]
    if not data or not data[0]:
        return "No Solution"

    n = len(data)
    m = len(data[0])

    # Normalize region ids to 0..R-1
    region_map = {}
    region_cells = []
    reg = [[0] * m for _ in range(n)]

    for r in range(n):
        for c in range(m):
            raw = data[r][c]
            if raw not in region_map:
                region_map[raw] = len(region_cells)
                region_cells.append([])
            rr = region_map[raw]
            reg[r][c] = rr
            region_cells[rr].append((r, c))

    R = len(region_cells)

    # All orthogonally adjacent cell-pairs are potential dominoes.
    domino_cells = []
    domino_regions = []
    region_incident = [set() for _ in range(R)]

    for r in range(n):
        for c in range(m):
            if r + 1 < n:
                a = (r, c)
                b = (r + 1, c)
                d = len(domino_cells)
                domino_cells.append((a, b))
                ra, rb = reg[a[0]][a[1]], reg[b[0]][b[1]]
                domino_regions.append((ra, rb))
                region_incident[ra].add(d)
                region_incident[rb].add(d)
            if c + 1 < m:
                a = (r, c)
                b = (r, c + 1)
                d = len(domino_cells)
                domino_cells.append((a, b))
                ra, rb = reg[a[0]][a[1]], reg[b[0]][b[1]]
                domino_regions.append((ra, rb))
                region_incident[ra].add(d)
                region_incident[rb].add(d)

    D = len(domino_cells)

    def touch_or_overlap(d1, d2):
        (a1, b1) = domino_cells[d1]
        (a2, b2) = domino_cells[d2]
        for x in (a1, b1):
            for y in (a2, b2):
                if x == y:
                    return True
                if abs(x[0] - y[0]) + abs(x[1] - y[1]) == 1:
                    return True
        return False

    # Conflict masks between dominoes.
    conflict = [0] * D
    for d1 in range(D):
        for d2 in range(d1 + 1, D):
            if touch_or_overlap(d1, d2):
                conflict[d1] |= 1 << d2
                conflict[d2] |= 1 << d1

    # Shared crossing-domino mask for each ordered region pair.
    shared_cross = [[0] * R for _ in range(R)]
    for d, (ra, rb) in enumerate(domino_regions):
        if ra != rb:
            shared_cross[ra][rb] |= 1 << d
            shared_cross[rb][ra] |= 1 << d

    # Human-style abstraction:
    # For each region, enumerate every local way to place exactly 2 shaded cells:
    #   - one internal domino fully inside the region, or
    #   - two crossing dominoes, each contributing one shaded cell to the region.
    region_patterns = []
    pattern_bits = []
    pattern_conflict_bits = []

    for rr in range(R):
        internal = []
        crossing = []

        for d in region_incident[rr]:
            a, b = domino_cells[d]
            ra, rb = domino_regions[d]
            if ra == rr and rb == rr:
                internal.append(d)
            else:
                cell_in_region = a if reg[a[0]][a[1]] == rr else b
                crossing.append((d, cell_in_region))

        pats = set()

        for d in internal:
            pats.add((d,))

        L = len(crossing)
        for i in range(L):
            d1, c1 = crossing[i]
            for j in range(i + 1, L):
                d2, c2 = crossing[j]
                if c1 == c2:
                    continue
                if (conflict[d1] >> d2) & 1:
                    continue
                pats.add(tuple(sorted((d1, d2))))

        if not pats:
            return "No Solution"

        pats = sorted(pats)
        region_patterns.append(pats)

        bits_list = []
        conf_list = []
        for pat in pats:
            bits = 0
            conf = 0
            for d in pat:
                bits |= 1 << d
                conf |= conflict[d]
            bits_list.append(bits)
            pattern_conflict_bits.append if False else None
            conf_list.append(conf)
        pattern_bits.append(bits_list)
        pattern_conflict_bits.append(conf_list)

    # Pairwise compatibility between region patterns.
    compat = [[None] * R for _ in range(R)]
    neighbors = [set() for _ in range(R)]

    for r1 in range(R):
        for r2 in range(R):
            if r1 == r2:
                continue
            full_mask_r2 = (1 << len(region_patterns[r2])) - 1
            arr = []
            constrained = False

            shared = shared_cross[r1][r2]
            for i, bits1 in enumerate(pattern_bits[r1]):
                ok_mask = 0
                conf1 = pattern_conflict_bits[r1][i]
                for j, bits2 in enumerate(pattern_bits[r2]):
                    # Shared crossing dominoes must be chosen by both endpoint regions or by neither.
                    if ((bits1 ^ bits2) & shared) != 0:
                        continue
                    # Different dominoes cannot touch orthogonally.
                    if conf1 & bits2:
                        continue
                    ok_mask |= 1 << j
                arr.append(ok_mask)
                if ok_mask != full_mask_r2:
                    constrained = True

            compat[r1][r2] = arr
            if constrained:
                neighbors[r1].add(r2)

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def singleton_index(mask):
        return mask.bit_length() - 1 if mask and (mask & (mask - 1)) == 0 else None

    def propagate(domains):
        domains = list(domains)
        queue = [(a, b) for a in range(R) for b in neighbors[a]]

        while queue:
            a, b = queue.pop()
            old = domains[a]
            db = domains[b]
            new = old

            mm = old
            while mm:
                lsb = mm & -mm
                i = lsb.bit_length() - 1
                if compat[a][b][i] & db == 0:
                    new &= ~lsb
                mm ^= lsb

            if new != old:
                if new == 0:
                    return None
                domains[a] = new
                for z in neighbors[a]:
                    if z != b:
                        queue.append((z, a))

        return tuple(domains)

    @lru_cache(maxsize=None)
    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        choice_region = -1
        choice_count = 10**9
        for rr in range(R):
            cnt = domains[rr].bit_count()
            if 1 < cnt < choice_count:
                choice_count = cnt
                choice_region = rr

        if choice_region == -1:
            return domains

        # Least-constraining-value ordering.
        options = list(iter_bits(domains[choice_region]))

        def score(i):
            s = 0
            for other in neighbors[choice_region]:
                s += (compat[choice_region][other][i] & domains[other]).bit_count()
            return -s

        options.sort(key=score)

        for i in options:
            new_domains = list(domains)
            new_domains[choice_region] = 1 << i

            fail = False
            for other in neighbors[choice_region]:
                new_domains[other] &= compat[choice_region][other][i]
                if new_domains[other] == 0:
                    fail = True
                    break
            if fail:
                continue

            res = search(tuple(new_domains))
            if res is not None:
                return res

        return None

    init_domains = tuple((1 << len(region_patterns[r])) - 1 for r in range(R))
    solved = search(init_domains)
    if solved is None:
        return "No Solution"

    selected_dominoes = set()
    for rr in range(R):
        idx = singleton_index(solved[rr])
        if idx is None:
            return "No Solution"
        for d in region_patterns[rr][idx]:
            selected_dominoes.add(d)

    answer = [[None for _ in range(m)] for _ in range(n)]
    shaded = set()

    for d in selected_dominoes:
        a, b = domino_cells[d]
        shaded.add(a)
        shaded.add(b)

    # Final validation.
    region_count = [0] * R
    for r, c in shaded:
        answer[r][c] = 'S'
        region_count[reg[r][c]] += 1

    if any(x != 2 for x in region_count):
        return "No Solution"

    for r, c in shaded:
        cnt = 0
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < n and 0 <= nc < m and (nr, nc) in shaded:
                cnt += 1
        if cnt != 1:
            return "No Solution"

    return str(answer)


