import ast

W_MASK = 1
B_MASK = 2
BOTH = W_MASK | B_MASK

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0]) if R else 0
    if R == 0 or C == 0:
        return "No Solution"
    if R % 2 or C % 2:
        return "No Solution"

    h_cons = [[None] * (C - 1) for _ in range(R)]
    v_cons = [[None] * C for _ in range(R - 1)]

    for k, v in observation.get('horizontal', {}).items():
        r, x = ast.literal_eval(k)
        r = int(round(r))
        c = int(round(x - 0.5))
        if 0 <= r < R and 0 <= c < C - 1:
            h_cons[r][c] = v

    for k, v in observation.get('vertical', {}).items():
        y, c = ast.literal_eval(k)
        r = int(round(y - 0.5))
        c = int(round(c))
        if 0 <= r < R - 1 and 0 <= c < C:
            v_cons[r][c] = v

    pair_constraints = []
    for r in range(R):
        for c in range(C - 1):
            if h_cons[r][c] is not None:
                pair_constraints.append((r, c, r, c + 1, h_cons[r][c]))
    for r in range(R - 1):
        for c in range(C):
            if v_cons[r][c] is not None:
                pair_constraints.append((r, c, r + 1, c, v_cons[r][c]))

    pattern_cache = {}

    def generate_patterns(n):
        if n in pattern_cache:
            return pattern_cache[n]
        half = n // 2
        out = []

        def rec(i, prev2, prev1, blacks, pat):
            rem = n - i
            if blacks > half or blacks + rem < half:
                return
            if i == n:
                if blacks == half:
                    out.append(pat)
                return
            for bit in (0, 1):
                if i >= 2 and prev2 == prev1 == bit:
                    continue
                rec(i + 1, prev1, bit, blacks + bit, pat | (bit << i))

        rec(0, -1, -1, 0, 0)
        pattern_cache[n] = out
        return out

    def bit_to_mask(bit):
        return B_MASK if bit else W_MASK

    def mask_to_val(mask):
        if mask == W_MASK:
            return 0
        if mask == B_MASK:
            return 1
        return None

    def opposite(mask):
        out = 0
        if mask & W_MASK:
            out |= B_MASK
        if mask & B_MASK:
            out |= W_MASK
        return out

    row_patterns_all = generate_patterns(C)
    col_patterns_all = generate_patterns(R)

    row_base = []
    for r in range(R):
        cands = []
        for p in row_patterns_all:
            ok = True
            for c in range(C):
                if data[r][c] == 'B' and ((p >> c) & 1) != 1:
                    ok = False
                    break
                if data[r][c] == 'W' and ((p >> c) & 1) != 0:
                    ok = False
                    break
            if not ok:
                continue
            for c in range(C - 1):
                rel = h_cons[r][c]
                if rel is None:
                    continue
                a = (p >> c) & 1
                b = (p >> (c + 1)) & 1
                if rel == '=' and a != b:
                    ok = False
                    break
                if rel == 'x' and a == b:
                    ok = False
                    break
            if ok:
                cands.append(p)
        if not cands:
            return "No Solution"
        row_base.append(cands)

    col_base = []
    for c in range(C):
        cands = []
        for p in col_patterns_all:
            ok = True
            for r in range(R):
                if data[r][c] == 'B' and ((p >> r) & 1) != 1:
                    ok = False
                    break
                if data[r][c] == 'W' and ((p >> r) & 1) != 0:
                    ok = False
                    break
            if not ok:
                continue
            for r in range(R - 1):
                rel = v_cons[r][c]
                if rel is None:
                    continue
                a = (p >> r) & 1
                b = (p >> (r + 1)) & 1
                if rel == '=' and a != b:
                    ok = False
                    break
                if rel == 'x' and a == b:
                    ok = False
                    break
            if ok:
                cands.append(p)
        if not cands:
            return "No Solution"
        col_base.append(cands)

    domains0 = [[BOTH] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if data[r][c] == 'B':
                domains0[r][c] = B_MASK
            elif data[r][c] == 'W':
                domains0[r][c] = W_MASK

    def apply_line_rules(masks):
        n = len(masks)
        half = n // 2
        changed = False

        b_fixed = sum(1 for m in masks if m == B_MASK)
        w_fixed = sum(1 for m in masks if m == W_MASK)
        b_possible = sum(1 for m in masks if m & B_MASK)
        w_possible = sum(1 for m in masks if m & W_MASK)

        if b_fixed > half or w_fixed > half or b_possible < half or w_possible < half:
            return None, False

        if b_fixed == half:
            for i, m in enumerate(masks):
                nm = m & W_MASK
                if nm == 0:
                    return None, False
                if nm != m:
                    masks[i] = nm
                    changed = True

        if w_fixed == half:
            for i, m in enumerate(masks):
                nm = m & B_MASK
                if nm == 0:
                    return None, False
                if nm != m:
                    masks[i] = nm
                    changed = True

        b_fixed = sum(1 for m in masks if m == B_MASK)
        w_fixed = sum(1 for m in masks if m == W_MASK)
        need_b = half - b_fixed
        need_w = half - w_fixed
        b_positions = [i for i, m in enumerate(masks) if m & B_MASK]
        w_positions = [i for i, m in enumerate(masks) if m & W_MASK]

        if need_b < 0 or need_w < 0 or len(b_positions) < need_b or len(w_positions) < need_w:
            return None, False

        if len(b_positions) == need_b:
            for i in b_positions:
                if masks[i] != B_MASK:
                    masks[i] = B_MASK
                    changed = True

        if len(w_positions) == need_w:
            for i in w_positions:
                if masks[i] != W_MASK:
                    masks[i] = W_MASK
                    changed = True

        for i in range(n - 2):
            for color in (W_MASK, B_MASK):
                other = BOTH ^ color
                if masks[i] == color and masks[i + 1] == color:
                    nm = masks[i + 2] & other
                    if nm == 0:
                        return None, False
                    if nm != masks[i + 2]:
                        masks[i + 2] = nm
                        changed = True
                if masks[i] == color and masks[i + 2] == color:
                    nm = masks[i + 1] & other
                    if nm == 0:
                        return None, False
                    if nm != masks[i + 1]:
                        masks[i + 1] = nm
                        changed = True
                if masks[i + 1] == color and masks[i + 2] == color:
                    nm = masks[i] & other
                    if nm == 0:
                        return None, False
                    if nm != masks[i]:
                        masks[i] = nm
                        changed = True

        return masks, changed

    def filter_row_candidates(row_cands, domains, r):
        out = []
        for p in row_cands[r]:
            ok = True
            for c in range(C):
                m = domains[r][c]
                if ((p >> c) & 1) == 1:
                    if not (m & B_MASK):
                        ok = False
                        break
                else:
                    if not (m & W_MASK):
                        ok = False
                        break
            if ok:
                out.append(p)
        return out

    def filter_col_candidates(col_cands, domains, c):
        out = []
        for p in col_cands[c]:
            ok = True
            for r in range(R):
                m = domains[r][c]
                if ((p >> r) & 1) == 1:
                    if not (m & B_MASK):
                        ok = False
                        break
                else:
                    if not (m & W_MASK):
                        ok = False
                        break
            if ok:
                out.append(p)
        return out

    def support_mask_row(cands, c):
        mask = 0
        for p in cands:
            mask |= B_MASK if ((p >> c) & 1) else W_MASK
            if mask == BOTH:
                break
        return mask

    def support_mask_col(cands, r):
        mask = 0
        for p in cands:
            mask |= B_MASK if ((p >> r) & 1) else W_MASK
            if mask == BOTH:
                break
        return mask

    def propagate(domains, row_cands, col_cands):
        while True:
            changed = False

            for r1, c1, r2, c2, rel in pair_constraints:
                m1 = domains[r1][c1]
                m2 = domains[r2][c2]
                if rel == '=':
                    nm1 = m1 & m2
                    nm2 = m2 & m1
                else:
                    nm1 = m1 & opposite(m2)
                    nm2 = m2 & opposite(m1)
                if nm1 == 0 or nm2 == 0:
                    return False
                if nm1 != m1:
                    domains[r1][c1] = nm1
                    changed = True
                if nm2 != m2:
                    domains[r2][c2] = nm2
                    changed = True

            for r in range(R):
                line = domains[r][:]
                line2, ch = apply_line_rules(line)
                if line2 is None:
                    return False
                if ch:
                    domains[r] = line2
                    changed = True

            for c in range(C):
                line = [domains[r][c] for r in range(R)]
                line2, ch = apply_line_rules(line)
                if line2 is None:
                    return False
                if ch:
                    for r in range(R):
                        if domains[r][c] != line2[r]:
                            domains[r][c] = line2[r]
                            changed = True

            for r in range(R):
                new = filter_row_candidates(row_cands, domains, r)
                if not new:
                    return False
                if len(new) != len(row_cands[r]):
                    row_cands[r] = new
                    changed = True

            for c in range(C):
                new = filter_col_candidates(col_cands, domains, c)
                if not new:
                    return False
                if len(new) != len(col_cands[c]):
                    col_cands[c] = new
                    changed = True

            for r in range(R):
                for c in range(C):
                    rm = support_mask_row(row_cands[r], c)
                    cm = support_mask_col(col_cands[c], r)
                    nm = domains[r][c] & rm & cm
                    if nm == 0:
                        return False
                    if nm != domains[r][c]:
                        domains[r][c] = nm
                        changed = True

            if not changed:
                return True

    def is_solved(domains, row_cands, col_cands):
        for r in range(R):
            if len(row_cands[r]) != 1:
                return False
        for c in range(C):
            if len(col_cands[c]) != 1:
                return False
        for r in range(R):
            for c in range(C):
                if domains[r][c] not in (W_MASK, B_MASK):
                    return False
        return True

    def extract_solution(domains):
        out = []
        for r in range(R):
            row = []
            for c in range(C):
                row.append('B' if domains[r][c] == B_MASK else 'W')
            out.append(row)
        return out

    def clone_state(domains, row_cands, col_cands):
        return [row[:] for row in domains], [lst[:] for lst in row_cands], [lst[:] for lst in col_cands]

    def dfs(domains, row_cands, col_cands):
        if not propagate(domains, row_cands, col_cands):
            return None
        if is_solved(domains, row_cands, col_cands):
            return extract_solution(domains)

        best_kind = None
        best_idx = None
        best_size = 10**9

        for r in range(R):
            k = len(row_cands[r])
            if 1 < k < best_size:
                best_size = k
                best_kind = 'row'
                best_idx = r

        for c in range(C):
            k = len(col_cands[c])
            if 1 < k < best_size:
                best_size = k
                best_kind = 'col'
                best_idx = c

        if best_kind is None:
            for r in range(R):
                for c in range(C):
                    if domains[r][c] == BOTH:
                        for valmask in (W_MASK, B_MASK):
                            nd, nr, nc = clone_state(domains, row_cands, col_cands)
                            nd[r][c] = valmask
                            res = dfs(nd, nr, nc)
                            if res is not None:
                                return res
                        return None
            return None

        if best_kind == 'row':
            r = best_idx
            for p in row_cands[r]:
                nd, nr, nc = clone_state(domains, row_cands, col_cands)
                nr[r] = [p]
                for c in range(C):
                    nd[r][c] &= bit_to_mask((p >> c) & 1)
                    if nd[r][c] == 0:
                        break
                else:
                    res = dfs(nd, nr, nc)
                    if res is not None:
                        return res
        else:
            c = best_idx
            for p in col_cands[c]:
                nd, nr, nc = clone_state(domains, row_cands, col_cands)
                nc[c] = [p]
                for r in range(R):
                    nd[r][c] &= bit_to_mask((p >> r) & 1)
                    if nd[r][c] == 0:
                        break
                else:
                    res = dfs(nd, nr, nc)
                    if res is not None:
                        return res

        return None

    result = dfs(domains0, [lst[:] for lst in row_base], [lst[:] for lst in col_base])
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 2, 2], [0, 0, 3, 3, 3, 4, 5, 6], [7, 8, 3, 3, 3, 9, 9, 6], [7, 8, 3, 3, 3, 9, 9, 6], [7, 10, 10, 11, 12, 9, 9, 6], [7, 10, 10, 11, 12, 9, 9, 6], [13, 13, 13, 11, 12, 14, 14, 6], [13, 13, 13, 15, 15, 16, 16, 16]], 'data': [[2, None, None, None, 0, None, None, None], [None, None, None, None, None, None, 1, None], [None, 0, None, None, None, 2, None, None], [None, None, None, None, None, None, None, None], [None, 1, None, 2, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, None, None, 0, None, None]]}

from collections import deque, defaultdict

def solve(observation):
    region_grid = observation["region"]
    data_grid = observation["data"]
    n = len(region_grid)
    if n == 0 or any(len(row) != n for row in region_grid) or any(len(row) != n for row in data_grid):
        return "No Solution"

    num_cells = n * n
    all_mask = (1 << num_cells) - 1

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    cell_bits = [1 << i for i in range(num_cells)]

    # Orthogonal neighbors
    neighbor_mask = [0] * num_cells
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            m = 0
            if r > 0:
                m |= cell_bits[idx(r - 1, c)]
            if r + 1 < n:
                m |= cell_bits[idx(r + 1, c)]
            if c > 0:
                m |= cell_bits[idx(r, c - 1)]
            if c + 1 < n:
                m |= cell_bits[idx(r, c + 1)]
            neighbor_mask[i] = m

    # Regions
    region_cells = defaultdict(list)
    region_ids = set()
    cell_region = [0] * num_cells
    for r in range(n):
        for c in range(n):
            reg = region_grid[r][c]
            region_ids.add(reg)
            i = idx(r, c)
            region_cells[reg].append(i)
            cell_region[i] = reg

    region_ids = sorted(region_ids)
    region_masks = {reg: sum(cell_bits[i] for i in cells) for reg, cells in region_cells.items()}
    region_sizes = {reg: len(cells) for reg, cells in region_cells.items()}

    # Region clues
    region_clue = {reg: None for reg in region_ids}
    for r in range(n):
        for c in range(n):
            v = data_grid[r][c]
            if v is not None:
                reg = region_grid[r][c]
                if region_clue[reg] is None:
                    region_clue[reg] = v
                elif region_clue[reg] != v:
                    return "No Solution"

    # Precompute "three-block" Heyawake line constraints:
    # any uninterrupted white line cannot span three consecutive region blocks.
    spans = []
    span_seen = set()

    def add_line_spans(line_indices):
        blocks = []
        cur_reg = None
        cur_mask = 0
        for i in line_indices:
            reg = cell_region[i]
            if reg != cur_reg:
                if cur_mask:
                    blocks.append(cur_mask)
                cur_reg = reg
                cur_mask = cell_bits[i]
            else:
                cur_mask |= cell_bits[i]
        if cur_mask:
            blocks.append(cur_mask)
        for j in range(len(blocks) - 2):
            m = blocks[j] | blocks[j + 1] | blocks[j + 2]
            if m not in span_seen:
                span_seen.add(m)
                spans.append(m)

    for r in range(n):
        add_line_spans([idx(r, c) for c in range(n)])
    for c in range(n):
        add_line_spans([idx(r, c) for r in range(n)])

    cell_span_count = [0] * num_cells
    cell_spans = [[] for _ in range(num_cells)]
    for s_idx, m in enumerate(spans):
        x = m
        while x:
            b = x & -x
            i = b.bit_length() - 1
            cell_span_count[i] += 1
            cell_spans[i].append(s_idx)
            x ^= b

    # Numbered-region pattern generation:
    # exact black count inside the region + no orthogonally adjacent blacks within the pattern.
    region_patterns = {}
    for reg in region_ids:
        clue = region_clue[reg]
        if clue is None:
            continue
        cells = region_cells[reg]
        size = len(cells)
        if clue < 0 or clue > size:
            return "No Solution"

        patterns = []

        def rec(pos, need, chosen_mask, banned_mask, adj_mask):
            if need == 0:
                patterns.append((chosen_mask, adj_mask))
                return
            if pos == size:
                return
            if size - pos < need:
                return

            # Skip current cell
            rec(pos + 1, need, chosen_mask, banned_mask, adj_mask)

            # Take current cell if not banned
            i = cells[pos]
            b = cell_bits[i]
            if not (b & banned_mask):
                rec(
                    pos + 1,
                    need - 1,
                    chosen_mask | b,
                    banned_mask | b | neighbor_mask[i],
                    adj_mask | neighbor_mask[i],
                )

        rec(0, clue, 0, 0, 0)
        region_patterns[reg] = patterns
        if not patterns:
            return "No Solution"

    # Bit helpers
    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def is_single_bit(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def bfs_mask(start_bit, allowed_mask):
        start_i = start_bit.bit_length() - 1
        seen = start_bit
        q = deque([start_i])
        while q:
            i = q.popleft()
            x = neighbor_mask[i] & allowed_mask & ~seen
            while x:
                b = x & -x
                j = b.bit_length() - 1
                seen |= b
                q.append(j)
                x ^= b
        return seen

    def components_of(mask):
        comps = []
        rem = mask
        while rem:
            b = rem & -rem
            comp = bfs_mask(b, mask)
            comps.append(comp)
            rem &= ~comp
        return comps

    def finalize_board(black_mask):
        out = []
        for r in range(n):
            row = []
            for c in range(n):
                i = idx(r, c)
                row.append('B' if (black_mask & cell_bits[i]) else None)
            out.append(row)
        return out

    def final_check(black_mask, white_mask):
        if (black_mask | white_mask) != all_mask:
            return False
        # No adjacent blacks
        for i in iter_bits(black_mask):
            if neighbor_mask[i] & black_mask:
                return False
        # Region clues
        for reg in region_ids:
            clue = region_clue[reg]
            if clue is not None:
                if (black_mask & region_masks[reg]).bit_count() != clue:
                    return False
        # Three-block constraints
        for m in spans:
            if (m & black_mask) == 0:
                return False
        # White connectivity
        if white_mask:
            start = white_mask & -white_mask
            if bfs_mask(start, white_mask) != white_mask:
                return False
        return True

    def propagate(black_mask, white_mask):
        region_valid_masks = {}
        black_possible = 0

        while True:
            changed = False

            if black_mask & white_mask:
                return None

            # Black adjacency contradiction / forced white around blacks
            adj_of_black = 0
            for i in iter_bits(black_mask):
                if neighbor_mask[i] & black_mask:
                    return None
                adj_of_black |= neighbor_mask[i]

            new_white = adj_of_black & ~white_mask
            if new_white & black_mask:
                return None
            if new_white:
                white_mask |= new_white
                changed = True
                if black_mask & white_mask:
                    return None

            # Region reasoning via valid pattern filtering
            region_valid_masks = {}
            black_possible = black_mask

            for reg in region_ids:
                reg_mask = region_masks[reg]
                clue = region_clue[reg]

                if clue is None:
                    # Unnumbered region: only immediate impossibility from adjacency/fixed white.
                    poss = reg_mask & ~white_mask & ~adj_of_black
                    black_possible |= poss
                    continue

                fixed_b = black_mask & reg_mask
                fixed_w = white_mask & reg_mask
                outside_b = black_mask & ~reg_mask

                valids = []
                can_black = 0
                must_black = None

                for pat_mask, pat_adj in region_patterns[reg]:
                    if fixed_b & ~pat_mask:
                        continue
                    if fixed_w & pat_mask:
                        continue
                    if pat_adj & (outside_b | (fixed_b & ~pat_mask)):
                        continue
                    valids.append(pat_mask)
                    can_black |= pat_mask
                    if must_black is None:
                        must_black = pat_mask
                    else:
                        must_black &= pat_mask

                if not valids:
                    return None

                region_valid_masks[reg] = valids
                black_possible |= can_black

                force_b = must_black & ~black_mask
                force_w = (reg_mask & ~can_black) & ~white_mask

                if force_b & white_mask:
                    return None
                if force_w & black_mask:
                    return None

                if force_b:
                    black_mask |= force_b
                    changed = True
                if force_w:
                    white_mask |= force_w
                    changed = True

            if black_mask & white_mask:
                return None

            # Update immediate black feasibility after any new black
            adj_of_black = 0
            for i in iter_bits(black_mask):
                if neighbor_mask[i] & black_mask:
                    return None
                adj_of_black |= neighbor_mask[i]

            # Unknown cells adjacent to black cannot be black
            # For unnumbered regions, this was already reflected in black_possible.
            # If a remaining unknown cell is globally impossible to be black and not already white, force white.
            unknown_mask = all_mask & ~(black_mask | white_mask)
            impossible_black = unknown_mask & ~black_possible
            if impossible_black:
                white_mask |= impossible_black
                changed = True

            if black_mask & white_mask:
                return None

            # Three-block Heyawake spans: each span must contain at least one black.
            unsatisfied_spans = []
            for m in spans:
                if m & black_mask:
                    continue
                span_unknown = m & ~(black_mask | white_mask)
                if span_unknown == 0:
                    return None
                span_black_candidates = m & black_possible & ~white_mask
                if span_black_candidates == 0:
                    return None
                if is_single_bit(span_black_candidates):
                    if span_black_candidates & white_mask:
                        return None
                    if not (span_black_candidates & black_mask):
                        black_mask |= span_black_candidates
                        changed = True
                unsatisfied_spans.append(m)

            if black_mask & white_mask:
                return None

            # Potential white connectivity:
            # all confirmed white cells must remain connected through non-black cells.
            nonblack = all_mask & ~black_mask
            if white_mask:
                root = white_mask & -white_mask
                reach = bfs_mask(root, nonblack)
                if white_mask & ~reach:
                    return None

            # Component-level pruning:
            # if multiple non-black components are each guaranteed to contain white, impossible.
            comps = components_of(nonblack)
            if len(comps) > 1:
                must_white_components = 0
                for comp in comps:
                    must = False
                    if comp & white_mask:
                        must = True
                    else:
                        for reg in region_ids:
                            clue = region_clue[reg]
                            if clue is not None and clue < region_sizes[reg]:
                                if region_masks[reg] & ~comp == 0:
                                    must = True
                                    break
                    if must:
                        must_white_components += 1
                        if must_white_components > 1:
                            return None

            # Articulation-style forcing:
            # if removing an unknown cell from the non-black graph disconnects confirmed whites,
            # that cell cannot be black -> force white.
            if white_mask and white_mask.bit_count() >= 2:
                root = white_mask & -white_mask
                for i in iter_bits(all_mask & ~(black_mask | white_mask)):
                    b = cell_bits[i]
                    if not (black_possible & b):
                        continue
                    allowed = nonblack & ~b
                    # root is confirmed white, so root != b
                    reach = bfs_mask(root, allowed)
                    if white_mask & ~reach:
                        white_mask |= b
                        changed = True

            if black_mask & white_mask:
                return None

            if not changed:
                # Refresh black_possible after the final stabilized pass
                adj_of_black = 0
                for i in iter_bits(black_mask):
                    adj_of_black |= neighbor_mask[i]

                final_black_possible = black_mask
                for reg in region_ids:
                    reg_mask = region_masks[reg]
                    clue = region_clue[reg]
                    if clue is None:
                        final_black_possible |= reg_mask & ~white_mask & ~adj_of_black
                    else:
                        valids = region_valid_masks[reg]
                        can_black = 0
                        for pm in valids:
                            can_black |= pm
                        final_black_possible |= can_black

                return black_mask, white_mask, region_valid_masks, final_black_possible

    dead = set()

    def choose_branch(black_mask, white_mask, region_valid_masks, black_possible):
        unknown_mask = all_mask & ~(black_mask | white_mask)

        # First: branch from the most constrained numbered region.
        best = None
        for reg, valids in region_valid_masks.items():
            total = len(valids)
            if total <= 1:
                continue
            for i in region_cells[reg]:
                b = cell_bits[i]
                if not (unknown_mask & b):
                    continue
                freq = 0
                for pm in valids:
                    if pm & b:
                        freq += 1
                if freq == 0 or freq == total:
                    continue
                score = (
                    total,                      # fewer valid patterns first
                    abs(total - 2 * freq),     # more balanced split
                    -cell_span_count[i],       # more Heyawake influence
                    -(neighbor_mask[i] & unknown_mask).bit_count(),
                    i,
                )
                prefer_black = (
                    (freq * 2 >= total) or
                    any((spans[s_idx] & black_mask) == 0 for s_idx in cell_spans[i])
                )
                if best is None or score < best[0]:
                    best = (score, i, prefer_black)

        if best is not None:
            return best[1], best[2]

        # Fallback: choose the unknown cell participating in most unsatisfied structure.
        best = None
        for i in iter_bits(unknown_mask):
            b = cell_bits[i]
            can_black = bool(black_possible & b)
            unsat_span_hits = sum(1 for s_idx in cell_spans[i] if (spans[s_idx] & black_mask) == 0)
            score = (
                -unsat_span_hits,
                -can_black,
                -(neighbor_mask[i] & unknown_mask).bit_count(),
                i,
            )
            prefer_black = can_black and unsat_span_hits > 0
            if best is None or score < best[0]:
                best = (score, i, prefer_black)

        return (best[1], best[2]) if best is not None else (None, False)

    def dfs(black_mask, white_mask):
        propagated = propagate(black_mask, white_mask)
        if propagated is None:
            return None

        black_mask, white_mask, region_valid_masks, black_possible = propagated
        key = (black_mask, white_mask)
        if key in dead:
            return None

        if (black_mask | white_mask) == all_mask:
            if final_check(black_mask, white_mask):
                return black_mask, white_mask
            dead.add(key)
            return None

        branch_cell, prefer_black = choose_branch(black_mask, white_mask, region_valid_masks, black_possible)
        if branch_cell is None:
            dead.add(key)
            return None

        b = cell_bits[branch_cell]
        orders = [1, 0] if prefer_black else [0, 1]

        # Avoid pointless black branch if already known impossible.
        if not (black_possible & b):
            orders = [0]

        for v in orders:
            if v == 1:
                res = dfs(black_mask | b, white_mask)
            else:
                res = dfs(black_mask, white_mask | b)
            if res is not None:
                return res

        dead.add(key)
        return None

    result = dfs(0, 0)
    if result is None:
        return "No Solution"

    black_mask, white_mask = result
    return finalize_board(black_mask)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [15, 15, 7, 12, 14, 12], 'col_sum': [2, 13, 7, 11, 11, 18]}

from functools import lru_cache
import sys

sys.setrecursionlimit(10000)


@lru_cache(maxsize=None)
def generate_subset_masks(weights, target):
    weights = tuple(weights)
    n = len(weights)
    if target < 0:
        return ()
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]
    if target > suffix[0]:
        return ()

    out = []

    def dfs(i, rem, mask):
        if rem < 0 or rem > suffix[i]:
            return
        if i == n:
            if rem == 0:
                out.append(mask)
            return
        dfs(i + 1, rem, mask)
        w = weights[i]
        if rem >= w:
            dfs(i + 1, rem - w, mask | (1 << i))

    dfs(0, target, 0)
    return tuple(out)


def summarize_domains(domains):
    ors = []
    ands = []
    for dom in domains:
        first = dom[0]
        o = first
        a = first
        for m in dom[1:]:
            o |= m
            a &= m
        ors.append(o)
        ands.append(a)
    return tuple(ors), tuple(ands)


def propagate(row_domains, col_domains, r_count, c_count):
    # Arc-consistency between row-pattern domains and column-pattern domains.
    while True:
        changed = False

        col_or, col_and = summarize_domains(col_domains)
        new_rows = []
        for r, dom in enumerate(row_domains):
            kept = []
            for m in dom:
                ok = True
                for c in range(c_count):
                    bit = (m >> c) & 1
                    if bit:
                        if ((col_or[c] >> r) & 1) == 0:
                            ok = False
                            break
                    else:
                        if ((col_and[c] >> r) & 1) == 1:
                            ok = False
                            break
                if ok:
                    kept.append(m)
            if not kept:
                return None
            if len(kept) != len(dom):
                changed = True
            new_rows.append(tuple(kept))
        row_domains = tuple(new_rows)

        row_or, row_and = summarize_domains(row_domains)
        new_cols = []
        for c, dom in enumerate(col_domains):
            kept = []
            for m in dom:
                ok = True
                for r in range(r_count):
                    bit = (m >> r) & 1
                    if bit:
                        if ((row_or[r] >> c) & 1) == 0:
                            ok = False
                            break
                    else:
                        if ((row_and[r] >> c) & 1) == 1:
                            ok = False
                            break
                if ok:
                    kept.append(m)
            if not kept:
                return None
            if len(kept) != len(dom):
                changed = True
            new_cols.append(tuple(kept))
        col_domains = tuple(new_cols)

        if not changed:
            return row_domains, col_domains


def choose_branch(row_domains, col_domains, c_count, r_count):
    row_or, row_and = summarize_domains(row_domains)
    col_or, col_and = summarize_domains(col_domains)

    best = None
    best_key = None

    for r, dom in enumerate(row_domains):
        if len(dom) > 1:
            unresolved = (row_or[r] ^ row_and[r]).bit_count()
            key = (len(dom), -unresolved, 0, r)
            if best_key is None or key < best_key:
                best_key = key
                best = ("row", r)

    for c, dom in enumerate(col_domains):
        if len(dom) > 1:
            unresolved = (col_or[c] ^ col_and[c]).bit_count()
            key = (len(dom), -unresolved, 1, c)
            if best_key is None or key < best_key:
                best_key = key
                best = ("col", c)

    return best


def order_options(kind, idx, options, row_domains, col_domains, r_count, c_count):
    # Fail-fast ordering: prefer masks that use rarer supported bits.
    if len(options) <= 1:
        return options

    if kind == "row":
        counts1 = []
        counts0 = []
        for dom in col_domains:
            c1 = 0
            for m in dom:
                c1 += (m >> idx) & 1
            counts1.append(c1)
            counts0.append(len(dom) - c1)

        def score(mask):
            s = 0
            for c in range(c_count):
                s += counts1[c] if ((mask >> c) & 1) else counts0[c]
            return (s, mask.bit_count())

    else:
        counts1 = []
        counts0 = []
        for dom in row_domains:
            c1 = 0
            for m in dom:
                c1 += (m >> idx) & 1
            counts1.append(c1)
            counts0.append(len(dom) - c1)

        def score(mask):
            s = 0
            for r in range(r_count):
                s += counts1[r] if ((mask >> r) & 1) else counts0[r]
            return (s, mask.bit_count())

    return tuple(sorted(options, key=score))


def build_grid(row_domains, c_count):
    grid = []
    for dom in row_domains:
        m = dom[0]
        grid.append(['B' if ((m >> c) & 1) else None for c in range(c_count)])
    return grid


def verify(grid, row_sum, col_sum, row_weights, col_weights):
    r_count = len(row_sum)
    c_count = len(col_sum)

    for r in range(r_count):
        s = 0
        for c in range(c_count):
            if grid[r][c] == 'B':
                s += col_weights[c]
        if s != row_sum[r]:
            return False

    for c in range(c_count):
        s = 0
        for r in range(r_count):
            if grid[r][c] == 'B':
                s += row_weights[r]
        if s != col_sum[c]:
            return False

    return True


def apply_fixed_cells(row_domains, col_domains, fixed_black, fixed_white):
    row_domains = list(row_domains)
    col_domains = list(col_domains)

    for r, c in fixed_black:
        bit_c = 1 << c
        bit_r = 1 << r
        row_domains[r] = tuple(m for m in row_domains[r] if m & bit_c)
        col_domains[c] = tuple(m for m in col_domains[c] if m & bit_r)
        if not row_domains[r] or not col_domains[c]:
            return None

    for r, c in fixed_white:
        bit_c = 1 << c
        bit_r = 1 << r
        row_domains[r] = tuple(m for m in row_domains[r] if (m & bit_c) == 0)
        col_domains[c] = tuple(m for m in col_domains[c] if (m & bit_r) == 0)
        if not row_domains[r] or not col_domains[c]:
            return None

    return tuple(row_domains), tuple(col_domains)


def dfs(row_domains, col_domains, row_sum, col_sum, row_weights, col_weights, dead_cache):
    r_count = len(row_domains)
    c_count = len(col_domains)

    state = propagate(row_domains, col_domains, r_count, c_count)
    if state is None:
        return None
    row_domains, col_domains = state

    if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
        grid = build_grid(row_domains, c_count)
        return grid if verify(grid, row_sum, col_sum, row_weights, col_weights) else None

    sig = (row_domains, col_domains)
    if sig in dead_cache:
        return None

    branch = choose_branch(row_domains, col_domains, c_count, r_count)
    if branch is None:
        dead_cache.add(sig)
        return None

    kind, idx = branch
    if kind == "row":
        options = order_options(kind, idx, row_domains[idx], row_domains, col_domains, r_count, c_count)
        for mask in options:
            new_rows = list(row_domains)
            new_rows[idx] = (mask,)
            result = dfs(tuple(new_rows), col_domains, row_sum, col_sum, row_weights, col_weights, dead_cache)
            if result is not None:
                return result
    else:
        options = order_options(kind, idx, col_domains[idx], row_domains, col_domains, r_count, c_count)
        for mask in options:
            new_cols = list(col_domains)
            new_cols[idx] = (mask,)
            result = dfs(row_domains, tuple(new_cols), row_sum, col_sum, row_weights, col_weights, dead_cache)
            if result is not None:
                return result

    dead_cache.add(sig)
    return None


def solve(observation):
    row_sum = tuple(observation['row_sum'])
    col_sum = tuple(observation['col_sum'])
    r_count = len(row_sum)
    c_count = len(col_sum)

    row_weights = tuple(observation.get('row_weights', tuple(range(1, r_count + 1))))
    col_weights = tuple(observation.get('col_weights', tuple(range(1, c_count + 1))))

    if len(row_weights) != r_count or len(col_weights) != c_count:
        return "No Solution"

    if any(t < 0 or t > sum(col_weights) for t in row_sum):
        return "No Solution"
    if any(t < 0 or t > sum(row_weights) for t in col_sum):
        return "No Solution"

    row_domains = []
    for t in row_sum:
        dom = generate_subset_masks(col_weights, t)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for t in col_sum:
        dom = generate_subset_masks(row_weights, t)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    row_domains = tuple(row_domains)
    col_domains = tuple(col_domains)

    fixed_black = tuple(observation.get('fixed_black', observation.get('black', ())))
    fixed_white = tuple(observation.get('fixed_white', observation.get('white', ())))

    if fixed_black or fixed_white:
        constrained = apply_fixed_cells(row_domains, col_domains, fixed_black, fixed_white)
        if constrained is None:
            return "No Solution"
        row_domains, col_domains = constrained

    dead_cache = set()
    result = dfs(row_domains, col_domains, row_sum, col_sum, row_weights, col_weights, dead_cache)
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [17, 24, 21, 19, 23, 24, 8], 'col_sum': [20, 24, 21, 12, 16, 27, 14]}

# Weighted black-cell puzzle solver.
# Human-like strategy:
# 1) For each row, enumerate all black-cell patterns whose column-weight sum matches the row target.
# 2) For each column, enumerate all black-cell patterns whose row-weight sum matches the column target.
# 3) Repeatedly cross-filter row/column pattern domains:
#    - if a column can never be black at (r,c), remove row patterns placing black there
#    - if a column forces black at (r,c), keep only row patterns placing black there
#    - symmetrically for columns
# 4) If deduction stalls, branch on the most constrained row/column pattern domain.
# This is strong constraint propagation, not naive cell-by-cell brute force.

from typing import List, Optional, Tuple


def build_masks_by_sum(length: int) -> dict:
    # Group all subset masks of positions [0..length-1] by weighted sum,
    # where the weight of position i is (i+1).
    by_sum = {0: [0]}
    for i in range(length):
        w = i + 1
        bit = 1 << i
        items = list(by_sum.items())
        for s, masks in items:
            ns = s + w
            bucket = by_sum.setdefault(ns, [])
            for m in masks:
                bucket.append(m | bit)
    for s in by_sum:
        by_sum[s].sort()
    return by_sum


def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]
    nrows = len(row_sum)
    ncols = len(col_sum)

    row_masks_by_sum = build_masks_by_sum(ncols)
    col_masks_by_sum = build_masks_by_sum(nrows)

    row_domains = []
    for target in row_sum:
        domain = row_masks_by_sum.get(target, [])
        if not domain:
            return "No Solution"
        row_domains.append(domain[:])

    col_domains = []
    for target in col_sum:
        domain = col_masks_by_sum.get(target, [])
        if not domain:
            return "No Solution"
        col_domains.append(domain[:])

    full_colmask = (1 << ncols) - 1
    full_rowmask = (1 << nrows) - 1
    failed_states = set()

    def propagate(rd: List[List[int]], cd: List[List[int]]) -> Optional[Tuple[List[List[int]], List[List[int]]]]:
        # Repeated bidirectional domain reduction.
        while True:
            changed = False

            for dom in rd:
                if not dom:
                    return None
            for dom in cd:
                if not dom:
                    return None

            row_any = [0] * nrows
            row_all = [0] * nrows
            for r in range(nrows):
                dom = rd[r]
                any_mask = 0
                all_mask = full_colmask
                for p in dom:
                    any_mask |= p
                    all_mask &= p
                row_any[r] = any_mask
                row_all[r] = all_mask

            col_any = [0] * ncols
            col_all = [0] * ncols
            for c in range(ncols):
                dom = cd[c]
                any_mask = 0
                all_mask = full_rowmask
                for p in dom:
                    any_mask |= p
                    all_mask &= p
                col_any[c] = any_mask
                col_all[c] = all_mask

            # Filter row domains using column support.
            for r in range(nrows):
                forced1 = 0
                can1 = 0
                bit_r = 1 << r
                for c in range(ncols):
                    bit_c = 1 << c
                    if col_all[c] & bit_r:
                        forced1 |= bit_c
                    if col_any[c] & bit_r:
                        can1 |= bit_c

                old = rd[r]
                new = [p for p in old if (p & forced1) == forced1 and (p & ~can1) == 0]
                if not new:
                    return None
                if len(new) != len(old):
                    rd[r] = new
                    changed = True

            # Recompute row any/all if rows changed before filtering columns.
            if changed:
                row_any = [0] * nrows
                row_all = [0] * nrows
                for r in range(nrows):
                    dom = rd[r]
                    any_mask = 0
                    all_mask = full_colmask
                    for p in dom:
                        any_mask |= p
                        all_mask &= p
                    row_any[r] = any_mask
                    row_all[r] = all_mask

            # Filter column domains using row support.
            for c in range(ncols):
                forced1 = 0
                can1 = 0
                bit_c = 1 << c
                for r in range(nrows):
                    bit_r = 1 << r
                    if row_all[r] & bit_c:
                        forced1 |= bit_r
                    if row_any[r] & bit_c:
                        can1 |= bit_r

                old = cd[c]
                new = [p for p in old if (p & forced1) == forced1 and (p & ~can1) == 0]
                if not new:
                    return None
                if len(new) != len(old):
                    cd[c] = new
                    changed = True

            if not changed:
                # Final consistency check at fixed point.
                row_any = [0] * nrows
                row_all = [0] * nrows
                for r in range(nrows):
                    dom = rd[r]
                    any_mask = 0
                    all_mask = full_colmask
                    for p in dom:
                        any_mask |= p
                        all_mask &= p
                    row_any[r] = any_mask
                    row_all[r] = all_mask

                col_any = [0] * ncols
                col_all = [0] * ncols
                for c in range(ncols):
                    dom = cd[c]
                    any_mask = 0
                    all_mask = full_rowmask
                    for p in dom:
                        any_mask |= p
                        all_mask &= p
                    col_any[c] = any_mask
                    col_all[c] = all_mask

                for r in range(nrows):
                    bit_r = 1 << r
                    for c in range(ncols):
                        bit_c = 1 << c
                        row_can_1 = bool(row_any[r] & bit_c)
                        row_can_0 = not bool(row_all[r] & bit_c)
                        col_can_1 = bool(col_any[c] & bit_r)
                        col_can_0 = not bool(col_all[c] & bit_r)
                        if row_can_1 != col_can_1 or row_can_0 != col_can_0:
                            return None
                return rd, cd

    def state_key(rd: List[List[int]], cd: List[List[int]]):
        return (tuple(tuple(x) for x in rd), tuple(tuple(x) for x in cd))

    def order_patterns(kind: str, idx: int, patterns: List[int], rd: List[List[int]], cd: List[List[int]]) -> List[int]:
        # Prefer patterns that are more supported by the perpendicular domains.
        scored = []
        if kind == "row":
            r = idx
            bit_r = 1 << r
            for p in patterns:
                score = 0
                for c in range(ncols):
                    want = (p >> c) & 1
                    cnt = 0
                    for q in cd[c]:
                        if ((q & bit_r) != 0) == bool(want):
                            cnt += 1
                    score += cnt
                scored.append((-score, p))
        else:
            c = idx
            bit_c = 1 << c
            for p in patterns:
                score = 0
                for r in range(nrows):
                    want = (p >> r) & 1
                    cnt = 0
                    for q in rd[r]:
                        if ((q & bit_c) != 0) == bool(want):
                            cnt += 1
                    score += cnt
                scored.append((-score, p))
        scored.sort()
        return [p for _, p in scored]

    def verify(row_masks: List[int]) -> bool:
        if len(row_masks) != nrows:
            return False
        for r in range(nrows):
            total = 0
            mask = row_masks[r]
            for c in range(ncols):
                if (mask >> c) & 1:
                    total += c + 1
            if total != row_sum[r]:
                return False

        for c in range(ncols):
            total = 0
            for r in range(nrows):
                if (row_masks[r] >> c) & 1:
                    total += r + 1
            if total != col_sum[c]:
                return False
        return True

    def search(rd: List[List[int]], cd: List[List[int]]) -> Optional[List[int]]:
        propagated = propagate([x[:] for x in rd], [x[:] for x in cd])
        if propagated is None:
            return None
        rd, cd = propagated

        key = state_key(rd, cd)
        if key in failed_states:
            return None

        solved = all(len(dom) == 1 for dom in rd) and all(len(dom) == 1 for dom in cd)
        if solved:
            row_masks = [dom[0] for dom in rd]
            if verify(row_masks):
                return row_masks
            failed_states.add(key)
            return None

        # Choose the most constrained unsolved line.
        best_kind = None
        best_idx = -1
        best_size = 10**9
        best_span = -1

        for r in range(nrows):
            size = len(rd[r])
            if 1 < size < best_size:
                best_kind, best_idx, best_size = "row", r, size
                any_mask = 0
                all_mask = full_colmask
                for p in rd[r]:
                    any_mask |= p
                    all_mask &= p
                best_span = (any_mask ^ all_mask).bit_count()
            elif 1 < size == best_size:
                any_mask = 0
                all_mask = full_colmask
                for p in rd[r]:
                    any_mask |= p
                    all_mask &= p
                span = (any_mask ^ all_mask).bit_count()
                if span > best_span:
                    best_kind, best_idx, best_span = "row", r, span

        for c in range(ncols):
            size = len(cd[c])
            if 1 < size < best_size:
                best_kind, best_idx, best_size = "col", c, size
                any_mask = 0
                all_mask = full_rowmask
                for p in cd[c]:
                    any_mask |= p
                    all_mask &= p
                best_span = (any_mask ^ all_mask).bit_count()
            elif 1 < size == best_size:
                any_mask = 0
                all_mask = full_rowmask
                for p in cd[c]:
                    any_mask |= p
                    all_mask &= p
                span = (any_mask ^ all_mask).bit_count()
                if span > best_span:
                    best_kind, best_idx, best_span = "col", c, span

        if best_kind is None:
            failed_states.add(key)
            return None

        if best_kind == "row":
            patterns = order_patterns("row", best_idx, rd[best_idx], rd, cd)
            for p in patterns:
                new_rd = [x[:] for x in rd]
                new_cd = [x[:] for x in cd]
                new_rd[best_idx] = [p]
                ans = search(new_rd, new_cd)
                if ans is not None:
                    return ans
        else:
            patterns = order_patterns("col", best_idx, cd[best_idx], rd, cd)
            for p in patterns:
                new_rd = [x[:] for x in rd]
                new_cd = [x[:] for x in cd]
                new_cd[best_idx] = [p]
                ans = search(new_rd, new_cd)
                if ans is not None:
                    return ans

        failed_states.add(key)
        return None

    row_masks = search(row_domains, col_domains)
    if row_masks is None:
        return "No Solution"

    grid = []
    for r in range(nrows):
        row = []
        mask = row_masks[r]
        for c in range(ncols):
            row.append("B" if ((mask >> c) & 1) else None)
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[8, 9, None, None, None, None, 2, None, None], [None, 1, None, None, 5, 9, None, None, None], [None, 7, 2, None, None, None, None, 4, None], [None, None, None, 8, 6, None, None, None, 9], [None, None, 5, 9, None, 7, 8, None, None], [9, None, None, None, 1, 2, None, None, None], [None, 3, None, None, None, None, 5, 7, None], [None, None, None, 7, 2, None, None, 9, None], [None, None, 8, None, None, None, None, 2, 1]], 'unit': '3x3'}

import sys
from itertools import combinations

sys.setrecursionlimit(10000)


class State:
    __slots__ = ("values", "cand", "row_used", "col_used", "box_used")

    def __init__(self, values, cand, row_used, col_used, box_used):
        self.values = values
        self.cand = cand
        self.row_used = row_used
        self.col_used = col_used
        self.box_used = box_used

    def clone(self):
        return State(
            self.values[:],
            self.cand[:],
            self.row_used[:],
            self.col_used[:],
            self.box_used[:],
        )


def solve(observation):
    data = observation.get("data")
    unit = observation.get("unit")

    if not isinstance(data, list) or not data or not all(isinstance(row, list) for row in data):
        return "No Solution"

    def parse_unit(u):
        if isinstance(u, int):
            return u, u
        s = str(u).strip().lower()
        if "x" in s:
            a, b = s.split("x", 1)
            return int(a), int(b)
        v = int(s)
        return v, v

    try:
        box_r, box_c = parse_unit(unit)
    except Exception:
        return "No Solution"

    n = box_r * box_c
    if len(data) != n or any(len(row) != n for row in data):
        return "No Solution"

    m = n * n
    full_mask = (1 << n) - 1
    box_cols = n // box_c
    box_count = (n // box_r) * (n // box_c)

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    boxes = [[] for _ in range(box_count)]

    row_of = [0] * m
    col_of = [0] * m
    box_of = [0] * m

    for r in range(n):
        for c in range(n):
            idx = r * n + c
            b = (r // box_r) * box_cols + (c // box_c)
            boxes[b].append(idx)
            row_of[idx] = r
            col_of[idx] = c
            box_of[idx] = b

    houses = rows + cols + boxes

    peers = []
    for idx in range(m):
        r = row_of[idx]
        c = col_of[idx]
        b = box_of[idx]
        p = set(rows[r])
        p.update(cols[c])
        p.update(boxes[b])
        p.discard(idx)
        peers.append(tuple(p))

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def bit_to_digit(bit):
        return bit.bit_length()

    def assign(state, idx, digit, queue):
        bit = 1 << (digit - 1)
        cur = state.cand[idx]
        if not (cur & bit):
            return False
        if state.values[idx]:
            return state.values[idx] == digit
        r = row_of[idx]
        c = col_of[idx]
        b = box_of[idx]
        if (state.row_used[r] & bit) or (state.col_used[c] & bit) or (state.box_used[b] & bit):
            return False
        state.values[idx] = digit
        state.cand[idx] = bit
        state.row_used[r] |= bit
        state.col_used[c] |= bit
        state.box_used[b] |= bit
        queue.append(idx)
        return True

    def eliminate_mask(state, idx, rem_mask, queue):
        cur = state.cand[idx]
        if not (cur & rem_mask):
            return True, False
        if state.values[idx]:
            return False, False
        new_mask = cur & ~rem_mask
        if new_mask == 0:
            return False, False
        state.cand[idx] = new_mask
        if is_single(new_mask):
            if not assign(state, idx, bit_to_digit(new_mask), queue):
                return False, False
        return True, True

    def house_hidden_singles(state, house, used_mask, queue):
        counts = [0] * n
        last = [-1] * n
        for idx in house:
            if state.values[idx] == 0:
                mm = state.cand[idx] & ~used_mask
                while mm:
                    bit = mm & -mm
                    d = bit.bit_length() - 1
                    counts[d] += 1
                    last[d] = idx
                    mm -= bit
        missing = full_mask & ~used_mask
        while missing:
            bit = missing & -missing
            d = bit.bit_length() - 1
            if counts[d] == 0:
                return False, False
            if counts[d] == 1:
                if not assign(state, last[d], d + 1, queue):
                    return False, False
                return True, True
            missing -= bit
        return True, False

    def apply_hidden_singles(state, queue):
        for r in range(n):
            ok, changed = house_hidden_singles(state, rows[r], state.row_used[r], queue)
            if not ok or changed:
                return ok, changed
        for c in range(n):
            ok, changed = house_hidden_singles(state, cols[c], state.col_used[c], queue)
            if not ok or changed:
                return ok, changed
        for b in range(box_count):
            ok, changed = house_hidden_singles(state, boxes[b], state.box_used[b], queue)
            if not ok or changed:
                return ok, changed
        return True, False

    def apply_locked_candidates(state, queue):
        # Pointing from box to row/col.
        for b, box in enumerate(boxes):
            missing = full_mask & ~state.box_used[b]
            mm = missing
            while mm:
                bit = mm & -mm
                cells = [idx for idx in box if state.values[idx] == 0 and (state.cand[idx] & bit)]
                if not cells:
                    return False, False
                if len(cells) >= 2:
                    r0 = row_of[cells[0]]
                    same_row = True
                    for idx in cells[1:]:
                        if row_of[idx] != r0:
                            same_row = False
                            break
                    if same_row:
                        for idx in rows[r0]:
                            if box_of[idx] != b and state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
                    c0 = col_of[cells[0]]
                    same_col = True
                    for idx in cells[1:]:
                        if col_of[idx] != c0:
                            same_col = False
                            break
                    if same_col:
                        for idx in cols[c0]:
                            if box_of[idx] != b and state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
                mm -= bit

        # Claiming from row to box.
        for r, row in enumerate(rows):
            missing = full_mask & ~state.row_used[r]
            mm = missing
            while mm:
                bit = mm & -mm
                cells = [idx for idx in row if state.values[idx] == 0 and (state.cand[idx] & bit)]
                if not cells:
                    return False, False
                if len(cells) >= 2:
                    b0 = box_of[cells[0]]
                    same_box = True
                    for idx in cells[1:]:
                        if box_of[idx] != b0:
                            same_box = False
                            break
                    if same_box:
                        for idx in boxes[b0]:
                            if row_of[idx] != r and state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
                mm -= bit

        # Claiming from col to box.
        for c, col in enumerate(cols):
            missing = full_mask & ~state.col_used[c]
            mm = missing
            while mm:
                bit = mm & -mm
                cells = [idx for idx in col if state.values[idx] == 0 and (state.cand[idx] & bit)]
                if not cells:
                    return False, False
                if len(cells) >= 2:
                    b0 = box_of[cells[0]]
                    same_box = True
                    for idx in cells[1:]:
                        if box_of[idx] != b0:
                            same_box = False
                            break
                    if same_box:
                        for idx in boxes[b0]:
                            if col_of[idx] != c and state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
                mm -= bit

        return True, False

    def apply_naked_subsets(state, queue, max_k=4):
        for house in houses:
            unsolved = [idx for idx in house if state.values[idx] == 0]
            ulen = len(unsolved)
            if ulen < 3:
                continue
            limit = min(max_k, ulen - 1)
            for k in range(2, limit + 1):
                pool = [idx for idx in unsolved if 2 <= state.cand[idx].bit_count() <= k]
                if len(pool) < k:
                    continue
                for combo in combinations(pool, k):
                    union = 0
                    for idx in combo:
                        union |= state.cand[idx]
                    if union.bit_count() != k:
                        continue
                    subset_cells = 0
                    for idx in unsolved:
                        if state.cand[idx] & ~union == 0:
                            subset_cells += 1
                            if subset_cells > k:
                                break
                    if subset_cells != k:
                        continue
                    combo_set = set(combo)
                    for idx in unsolved:
                        if idx not in combo_set and (state.cand[idx] & union):
                            return eliminate_mask(state, idx, union, queue)
        return True, False

    def apply_hidden_subsets(state, queue, max_k=4):
        for house in houses:
            unsolved = [idx for idx in house if state.values[idx] == 0]
            ulen = len(unsolved)
            if ulen < 3:
                continue

            pos_by_digit = [0] * n
            for pos, idx in enumerate(unsolved):
                mm = state.cand[idx]
                while mm:
                    bit = mm & -mm
                    d = bit.bit_length() - 1
                    pos_by_digit[d] |= 1 << pos
                    mm -= bit

            limit = min(max_k, ulen - 1)
            for k in range(2, limit + 1):
                active_digits = [d for d in range(n) if 2 <= pos_by_digit[d].bit_count() <= k]
                if len(active_digits) < k:
                    continue
                for ds in combinations(active_digits, k):
                    cells_mask = 0
                    combo_mask = 0
                    for d in ds:
                        cells_mask |= pos_by_digit[d]
                        combo_mask |= 1 << d
                    if cells_mask.bit_count() != k:
                        continue

                    supporting_digits = 0
                    for d in range(n):
                        pd = pos_by_digit[d]
                        if pd and (pd & ~cells_mask) == 0:
                            supporting_digits += 1
                            if supporting_digits > k:
                                break
                    if supporting_digits != k:
                        continue

                    cm = cells_mask
                    while cm:
                        bitpos = cm & -cm
                        pos = bitpos.bit_length() - 1
                        idx = unsolved[pos]
                        rem = state.cand[idx] & ~combo_mask
                        if rem:
                            return eliminate_mask(state, idx, rem, queue)
                        cm -= bitpos
        return True, False

    def apply_xwing(state, queue):
        # Row-based X-Wing.
        for d in range(n):
            bit = 1 << d
            patterns = {}
            for r in range(n):
                cols_here = []
                for idx in rows[r]:
                    if state.values[idx] == 0 and (state.cand[idx] & bit):
                        cols_here.append(col_of[idx])
                        if len(cols_here) > 2:
                            break
                if len(cols_here) == 2:
                    patterns.setdefault(tuple(cols_here), []).append(r)
            for cols_pair, rs in patterns.items():
                if len(rs) == 2:
                    r1, r2 = rs
                    c1, c2 = cols_pair
                    for r in range(n):
                        if r != r1 and r != r2:
                            idx = r * n + c1
                            if state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
                            idx = r * n + c2
                            if state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)

        # Column-based X-Wing.
        for d in range(n):
            bit = 1 << d
            patterns = {}
            for c in range(n):
                rows_here = []
                for idx in cols[c]:
                    if state.values[idx] == 0 and (state.cand[idx] & bit):
                        rows_here.append(row_of[idx])
                        if len(rows_here) > 2:
                            break
                if len(rows_here) == 2:
                    patterns.setdefault(tuple(rows_here), []).append(c)
            for rows_pair, cs in patterns.items():
                if len(cs) == 2:
                    c1, c2 = cs
                    r1, r2 = rows_pair
                    for c in range(n):
                        if c != c1 and c != c2:
                            idx = r1 * n + c
                            if state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
                            idx = r2 * n + c
                            if state.values[idx] == 0 and (state.cand[idx] & bit):
                                return eliminate_mask(state, idx, bit, queue)
        return True, False

    def propagate(state, queue):
        while True:
            while queue:
                idx = queue.pop()
                bit = state.cand[idx]
                for p in peers[idx]:
                    ok, _ = eliminate_mask(state, p, bit, queue)
                    if not ok:
                        return False

            progress = False

            for rule in (
                apply_hidden_singles,
                apply_locked_candidates,
                apply_naked_subsets,
                apply_hidden_subsets,
                apply_xwing,
            ):
                ok, changed = rule(state, queue)
                if not ok:
                    return False
                if changed:
                    progress = True
                    break

            if not progress:
                break
        return True

    def choose_branch_cell(state):
        best_idx = -1
        best_count = n + 1
        best_pressure = -1
        for idx in range(m):
            if state.values[idx] == 0:
                cnt = state.cand[idx].bit_count()
                if cnt < best_count:
                    best_count = cnt
                    pressure = 0
                    for p in peers[idx]:
                        if state.values[p] == 0:
                            pressure += 1
                    best_pressure = pressure
                    best_idx = idx
                elif cnt == best_count:
                    pressure = 0
                    for p in peers[idx]:
                        if state.values[p] == 0:
                            pressure += 1
                    if pressure > best_pressure:
                        best_pressure = pressure
                        best_idx = idx
        return best_idx

    def ordered_digits_for_cell(state, idx):
        bits = []
        mm = state.cand[idx]
        while mm:
            bit = mm & -mm
            impact = 0
            for p in peers[idx]:
                if state.values[p] == 0 and (state.cand[p] & bit):
                    impact += 1
            bits.append((impact, bit))
            mm -= bit
        bits.sort()
        return [bit_to_digit(bit) for _, bit in bits]

    def search(state):
        if all(state.values):
            return state

        idx = choose_branch_cell(state)
        if idx < 0:
            return None

        for digit in ordered_digits_for_cell(state, idx):
            next_state = state.clone()
            queue = []
            if not assign(next_state, idx, digit, queue):
                continue
            if not propagate(next_state, queue):
                continue
            result = search(next_state)
            if result is not None:
                return result
        return None

    initial = State([0] * m, [full_mask] * m, [0] * n, [0] * n, [0] * box_count)

    dummy_queue = []
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is None:
                continue
            if not isinstance(val, int) or not (1 <= val <= n):
                return "No Solution"
            idx = r * n + c
            if not assign(initial, idx, val, dummy_queue):
                return "No Solution"

    queue = []
    for idx in range(m):
        if initial.values[idx] == 0:
            mask = full_mask & ~initial.row_used[row_of[idx]] & ~initial.col_used[col_of[idx]] & ~initial.box_used[box_of[idx]]
            if mask == 0:
                return "No Solution"
            initial.cand[idx] = mask

    for idx in range(m):
        if initial.values[idx] == 0 and is_single(initial.cand[idx]):
            if not assign(initial, idx, bit_to_digit(initial.cand[idx]), queue):
                return "No Solution"

    if not propagate(initial, queue):
        return "No Solution"

    solved = search(initial)
    if solved is None:
        return "No Solution"

    answer = [[solved.values[r * n + c] for c in range(n)] for r in range(n)]
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

