from functools import lru_cache

B_MASK = 1
W_MASK = 2
BOTH_MASK = 3


def solve(observation):
    data = observation['data']
    h = len(data)
    if h == 0:
        return []
    w = len(data[0])

    if h % 2 or w % 2:
        return "No Solution"

    horizontal = observation.get('horizontal', {})
    vertical = observation.get('vertical', {})

    def rel_lookup(mapping, y, x):
        keys = (
            f"({y:.1f},{x:.1f})",
            f"({y},{x})",
            (y, x),
        )
        for k in keys:
            if k in mapping:
                return mapping[k]
        return None

    row_rels = []
    for r in range(h):
        rels = []
        for c in range(w - 1):
            rels.append(rel_lookup(horizontal, float(r), c + 0.5))
        row_rels.append(tuple(rels))
    row_rels = tuple(row_rels)

    col_rels = []
    for c in range(w):
        rels = []
        for r in range(h - 1):
            rels.append(rel_lookup(vertical, r + 0.5, float(c)))
        col_rels.append(tuple(rels))
    col_rels = tuple(col_rels)

    initial = []
    for r in range(h):
        row = []
        for c in range(w):
            v = data[r][c]
            if v == 'B':
                row.append(B_MASK)
            elif v == 'W':
                row.append(W_MASK)
            else:
                row.append(BOTH_MASK)
        initial.append(tuple(row))
    initial = tuple(initial)

    @lru_cache(None)
    def base_valid_lines(n):
        if n % 2:
            return tuple()
        target_b = n // 2
        out = []

        def rec(pos, b_count, last1, last2, bits):
            w_count = pos - b_count
            rem = n - pos
            if b_count > target_b or w_count > target_b:
                return
            if b_count + rem < target_b or w_count + rem < target_b:
                return
            if pos == n:
                if b_count == target_b:
                    out.append(bits)
                return
            for v in (0, 1):
                if pos >= 2 and last1 == last2 == v:
                    continue
                rec(pos + 1, b_count + v, last2, v, bits | (v << pos))

        rec(0, 0, -1, -1, 0)
        return tuple(out)

    @lru_cache(None)
    def constrained_lines(n, rel_sig):
        out = []
        for seq in base_valid_lines(n):
            ok = True
            for i, rel in enumerate(rel_sig):
                if rel is None:
                    continue
                a = (seq >> i) & 1
                b = (seq >> (i + 1)) & 1
                if rel == '=' and a != b:
                    ok = False
                    break
                if rel == 'x' and a == b:
                    ok = False
                    break
            if ok:
                out.append(seq)
        return tuple(out)

    @lru_cache(None)
    def candidate_lines(n, rel_sig, dom_sig):
        full_mask = (1 << n) - 1
        must_b = 0
        must_w = 0
        for i, d in enumerate(dom_sig):
            if d == B_MASK:
                must_b |= 1 << i
            elif d == W_MASK:
                must_w |= 1 << i

        out = []
        for seq in constrained_lines(n, rel_sig):
            if seq & must_w:
                continue
            if ((~seq) & full_mask) & must_b:
                continue
            out.append(seq)
        return tuple(out)

    def propagate(domains):
        domains = [list(row) for row in domains]

        while True:
            row_cands = []
            for r in range(h):
                cands = candidate_lines(w, row_rels[r], tuple(domains[r]))
                if not cands:
                    return None
                row_cands.append(cands)

            col_cands = []
            for c in range(w):
                dom_sig = tuple(domains[r][c] for r in range(h))
                cands = candidate_lines(h, col_rels[c], dom_sig)
                if not cands:
                    return None
                col_cands.append(cands)

            changed = False
            for r in range(h):
                for c in range(w):
                    allow_row = 0
                    for seq in row_cands[r]:
                        allow_row |= B_MASK if ((seq >> c) & 1) else W_MASK
                        if allow_row == BOTH_MASK:
                            break

                    allow_col = 0
                    for seq in col_cands[c]:
                        allow_col |= B_MASK if ((seq >> r) & 1) else W_MASK
                        if allow_col == BOTH_MASK:
                            break

                    new_mask = domains[r][c] & allow_row & allow_col
                    if new_mask == 0:
                        return None
                    if new_mask != domains[r][c]:
                        domains[r][c] = new_mask
                        changed = True

            if not changed:
                return (
                    tuple(tuple(row) for row in domains),
                    tuple(row_cands),
                    tuple(col_cands),
                )

    def is_solved(domains):
        for r in range(h):
            for c in range(w):
                if domains[r][c] == BOTH_MASK:
                    return False
        return True

    def to_answer(domains):
        return [['B' if domains[r][c] == B_MASK else 'W' for c in range(w)] for r in range(h)]

    dead = set()

    def dfs(domains):
        prop = propagate(domains)
        if prop is None:
            return None

        domains, row_cands, col_cands = prop
        if domains in dead:
            return None

        if is_solved(domains):
            return domains

        best_kind = None
        best_idx = None
        best_cands = None
        best_len = 10 ** 9

        for r, cands in enumerate(row_cands):
            k = len(cands)
            if 1 < k < best_len:
                best_len = k
                best_kind = 'row'
                best_idx = r
                best_cands = cands

        for c, cands in enumerate(col_cands):
            k = len(cands)
            if 1 < k < best_len:
                best_len = k
                best_kind = 'col'
                best_idx = c
                best_cands = cands

        if best_cands is not None and best_len <= 8:
            for seq in best_cands:
                new_domains = [list(row) for row in domains]
                if best_kind == 'row':
                    r = best_idx
                    for c in range(w):
                        new_domains[r][c] = B_MASK if ((seq >> c) & 1) else W_MASK
                else:
                    c = best_idx
                    for r in range(h):
                        new_domains[r][c] = B_MASK if ((seq >> r) & 1) else W_MASK
                ans = dfs(tuple(tuple(row) for row in new_domains))
                if ans is not None:
                    return ans
        else:
            best_cell = None
            best_score = None
            for r in range(h):
                for c in range(w):
                    if domains[r][c] != BOTH_MASK:
                        continue
                    score = len(row_cands[r]) * len(col_cands[c])
                    if best_score is None or score < best_score:
                        best_score = score
                        best_cell = (r, c)

            if best_cell is None:
                dead.add(domains)
                return None

            r, c = best_cell
            rb = sum(1 for seq in row_cands[r] if (seq >> c) & 1)
            rw = len(row_cands[r]) - rb
            cb = sum(1 for seq in col_cands[c] if (seq >> r) & 1)
            cw = len(col_cands[c]) - cb

            choices = []
            if domains[r][c] & B_MASK:
                choices.append((rb + cb, B_MASK))
            if domains[r][c] & W_MASK:
                choices.append((rw + cw, W_MASK))
            choices.sort()

            for _, val in choices:
                new_domains = [list(row) for row in domains]
                new_domains[r][c] = val
                ans = dfs(tuple(tuple(row) for row in new_domains))
                if ans is not None:
                    return ans

        dead.add(domains)
        return None

    solved = dfs(initial)
    if solved is None:
        return "No Solution"
    return to_answer(solved)


