    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 1, 2, 2, 3, 4], [0, 1, 2, 2, 3, 4], [0, 1, 5, 6, 7, 7], [0, 0, 5, 6, 8, 7], [0, 0, 6, 6, 8, 8], [9, 9, 9, 9, 8, 8]]}

# General solver for the "2-per-region isolated dominoes" puzzle.
# It uses region-configuration generation plus aggressive propagation,
# then a small guided search only when logic is insufficient.

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    cells = [(r, c) for r in range(n) for c in range(n)]
    cell_index = {cell: i for i, cell in enumerate(cells)}

    # Regions
    region_ids = sorted({data[r][c] for r in range(n) for c in range(n)})
    rid_to_idx = {rid: i for i, rid in enumerate(region_ids)}
    region_of = {}
    region_cells = [[] for _ in region_ids]
    for r in range(n):
        for c in range(n):
            rr = rid_to_idx[data[r][c]]
            region_of[(r, c)] = rr
            region_cells[rr].append((r, c))

    # Orthogonal neighbors
    nbrs = {}
    for r in range(n):
        for c in range(n):
            cur = []
            if r > 0:
                cur.append((r - 1, c))
            if r + 1 < n:
                cur.append((r + 1, c))
            if c > 0:
                cur.append((r, c - 1))
            if c + 1 < n:
                cur.append((r, c + 1))
            nbrs[(r, c)] = cur

    # Dominoes: all orthogonally adjacent pairs
    domino_cells = []
    pair_to_domino = {}
    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                a, b = (r, c), (r, c + 1)
                d = len(domino_cells)
                domino_cells.append((a, b))
                pair_to_domino[frozenset((a, b))] = d
            if r + 1 < n:
                a, b = (r, c), (r + 1, c)
                d = len(domino_cells)
                domino_cells.append((a, b))
                pair_to_domino[frozenset((a, b))] = d

    D = len(domino_cells)
    domino_bits = [1 << d for d in range(D)]

    cell_to_dominoes = {cell: [] for cell in cells}
    domino_regions = []
    for d, (a, b) in enumerate(domino_cells):
        cell_to_dominoes[a].append(d)
        cell_to_dominoes[b].append(d)
        ra = region_of[a]
        rb = region_of[b]
        if ra == rb:
            domino_regions.append((ra,))
        else:
            domino_regions.append(tuple(sorted((ra, rb))))

    # Incompatibility: overlap or orthogonal touching between different dominoes
    inc_bits = [0] * D
    dom_cell_sets = [set(x) for x in domino_cells]
    for i in range(D):
        ai, bi = domino_cells[i]
        si = dom_cell_sets[i]
        for j in range(i + 1, D):
            sj = dom_cell_sets[j]
            bad = False
            if si & sj:
                bad = True
            else:
                for x in si:
                    for y in sj:
                        if abs(x[0] - y[0]) + abs(x[1] - y[1]) == 1:
                            bad = True
                            break
                    if bad:
                        break
            if bad:
                inc_bits[i] |= 1 << j
                inc_bits[j] |= 1 << i

    # Region configurations:
    # A config is a set of 1 or 2 dominoes causing exactly 2 shaded cells in the region.
    region_touching_dominoes = []
    region_configs = []
    region_contains_masks = []
    region_allcfg_masks = []

    for rr, rcells in enumerate(region_cells):
        rset = set(rcells)
        touching = set()
        external_by_cell = {}

        for cell in rcells:
            ext = []
            for d in cell_to_dominoes[cell]:
                touching.add(d)
                a, b = domino_cells[d]
                other = b if a == cell else a
                if other not in rset:
                    ext.append(d)
            external_by_cell[cell] = ext

        configs_set = set()

        m = len(rcells)
        for i in range(m):
            a = rcells[i]
            for j in range(i + 1, m):
                b = rcells[j]
                if abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1:
                    d = pair_to_domino.get(frozenset((a, b)))
                    if d is not None:
                        configs_set.add(1 << d)
                else:
                    for da in external_by_cell[a]:
                        for db in external_by_cell[b]:
                            if da == db:
                                continue
                            if (inc_bits[da] >> db) & 1:
                                continue
                            configs_set.add((1 << da) | (1 << db))

        configs = sorted(configs_set, key=lambda x: (x.bit_count(), x))
        region_configs.append(configs)
        region_touching_dominoes.append(sorted(touching))

        contains = {}
        for idx, cfg in enumerate(configs):
            bits = cfg
            while bits:
                lb = bits & -bits
                d = lb.bit_length() - 1
                contains[d] = contains.get(d, 0) | (1 << idx)
                bits ^= lb
        region_contains_masks.append(contains)
        region_allcfg_masks.append((1 << len(configs)) - 1)

    # Quick impossible check
    for rr in range(len(region_ids)):
        if not region_configs[rr]:
            return "No Solution"

    def propagate(poss, selected, forbidden):
        while True:
            changed = False

            if selected & forbidden:
                return None

            # Selected dominoes forbid all incompatible dominoes
            add_forbidden = forbidden
            bits = selected
            while bits:
                lb = bits & -bits
                d = lb.bit_length() - 1
                add_forbidden |= inc_bits[d]
                bits ^= lb
            add_forbidden &= ~selected
            if add_forbidden != forbidden:
                forbidden = add_forbidden
                changed = True
                if selected & forbidden:
                    return None

            # Filter region configs and derive forced selections/forbiddances
            for rr in range(len(region_ids)):
                mask = poss[rr]
                allmask = region_allcfg_masks[rr]
                contains = region_contains_masks[rr]
                touching = region_touching_dominoes[rr]

                # Apply selected / forbidden constraints
                for d in touching:
                    bit = 1 << d
                    cm = contains.get(d, 0)
                    if selected & bit:
                        nm = mask & cm
                        if nm == 0:
                            return None
                        if nm != mask:
                            mask = nm
                            changed = True
                    elif forbidden & bit:
                        if cm:
                            nm = mask & (allmask ^ cm)
                            if nm != mask:
                                mask = nm
                                changed = True

                if mask == 0:
                    return None
                poss[rr] = mask

                # Region-wise forced domino status
                for d in touching:
                    bit = 1 << d
                    cm = contains.get(d, 0)
                    if (mask & cm) == 0:
                        if not (forbidden & bit):
                            forbidden |= bit
                            changed = True
                            if selected & bit:
                                return None
                    elif (mask & (allmask ^ cm)) == 0:
                        if not (selected & bit):
                            if forbidden & bit:
                                return None
                            selected |= bit
                            changed = True

            if not changed:
                return poss, selected, forbidden

    def singleton_index(mask):
        return mask.bit_length() - 1

    def verify(selected):
        shaded = set()
        bits = selected
        while bits:
            lb = bits & -bits
            d = lb.bit_length() - 1
            a, b = domino_cells[d]
            shaded.add(a)
            shaded.add(b)
            bits ^= lb

        # Exactly 2 shaded per region
        counts = [0] * len(region_ids)
        for cell in shaded:
            counts[region_of[cell]] += 1
        if any(x != 2 for x in counts):
            return False

        # Each shaded cell belongs to a domino; and shaded cells form isolated dominoes
        # Since we already select dominoes, just check each shaded cell has exactly one shaded neighbor.
        for cell in shaded:
            k = 0
            for nb in nbrs[cell]:
                if nb in shaded:
                    k += 1
            if k != 1:
                return False

        return True

    def build_answer(selected):
        ans = [[None for _ in range(n)] for _ in range(n)]
        bits = selected
        while bits:
            lb = bits & -bits
            d = lb.bit_length() - 1
            a, b = domino_cells[d]
            ans[a[0]][a[1]] = 'S'
            ans[b[0]][b[1]] = 'S'
            bits ^= lb
        return ans

    def dfs(poss, selected, forbidden):
        state = propagate(poss, selected, forbidden)
        if state is None:
            return None
        poss, selected, forbidden = state

        # If every region is fixed, reconstruct from chosen configs
        done = True
        chosen = 0
        for rr in range(len(region_ids)):
            mask = poss[rr]
            if mask == 0:
                return None
            if mask & (mask - 1):
                done = False
            else:
                cfg = region_configs[rr][singleton_index(mask)]
                chosen |= cfg

        if done:
            if verify(chosen):
                return build_answer(chosen)
            return None

        # Choose the most constrained unresolved region
        best_r = None
        best_count = None
        for rr in range(len(region_ids)):
            cnt = poss[rr].bit_count()
            if cnt > 1 and (best_count is None or cnt < best_count):
                best_count = cnt
                best_r = rr

        mask = poss[best_r]
        cfg_ids = []
        tmp = mask
        while tmp:
            lb = tmp & -tmp
            cfg_ids.append(lb.bit_length() - 1)
            tmp ^= lb

        # Try configurations with more already-selected overlap first
        cfg_ids.sort(
            key=lambda idx: (
                -((region_configs[best_r][idx] & selected).bit_count()),
                region_configs[best_r][idx].bit_count()
            )
        )

        for idx in cfg_ids:
            new_poss = poss[:]
            new_poss[best_r] = 1 << idx
            res = dfs(new_poss, selected, forbidden)
            if res is not None:
                return res
        return None

    initial_poss = region_allcfg_masks[:]
    result = dfs(initial_poss, 0, 0)
    return result if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None, 3, None], [3, None, 2, 2, None, None, None, None, 1, None], [None, None, 2, 3, 2, 0, None, None, 3, 2], [None, None, 1, None, None, 1, None, None, 2, 3], [1, None, None, 3, 3, 3, None, 3, 2, None], [None, 3, None, 2, None, None, None, 2, 2, None], [None, 1, None, 2, None, None, None, 1, 1, 2], [3, None, 2, None, None, None, None, 2, None, None], [None, None, 2, 3, None, None, 2, 1, None, None], [3, None, 2, 3, None, 1, 2, None, 3, None]]}

from collections import deque
import sys

sys.setrecursionlimit(10000)


class SlitherlinkSolver:
    # domain bitmask: 1 => edge is OFF, 2 => edge is ON, 3 => unknown
    def __init__(self, observation):
        self.data = observation["data"]
        self.n = len(self.data)
        self.m = len(self.data[0]) if self.n else 0
        self.V = (self.n + 1) * (self.m + 1)

        self.h = [[-1] * self.m for _ in range(self.n + 1)]
        self.v = [[-1] * (self.m + 1) for _ in range(self.n)]
        self.endpoints = []

        def vid(r, c):
            return r * (self.m + 1) + c

        idx = 0
        for r in range(self.n + 1):
            for c in range(self.m):
                self.h[r][c] = idx
                self.endpoints.append((vid(r, c), vid(r, c + 1)))
                idx += 1
        for r in range(self.n):
            for c in range(self.m + 1):
                self.v[r][c] = idx
                self.endpoints.append((vid(r, c), vid(r + 1, c)))
                idx += 1

        self.E = idx
        self.constraints = []
        self.edge_constraints = [[] for _ in range(self.E)]
        self.clue_cells = []
        self.edge_priority = [0] * self.E

        def add_constraint(edges, allowed):
            cid = len(self.constraints)
            self.constraints.append((tuple(edges), tuple(allowed)))
            for e in edges:
                self.edge_constraints[e].append(cid)

        # Cell constraints
        for r in range(self.n):
            for c in range(self.m):
                clue = self.data[r][c]
                if clue is None:
                    continue
                edges = (
                    self.h[r][c],       # top
                    self.v[r][c + 1],   # right
                    self.h[r + 1][c],   # bottom
                    self.v[r][c],       # left
                )
                allowed = [mask for mask in range(16) if mask.bit_count() == clue]
                add_constraint(edges, allowed)
                self.clue_cells.append((edges, clue))
                w = 8 if clue in (0, 3) else 5
                for e in edges:
                    self.edge_priority[e] += w

        # Dot constraints: degree must be 0 or 2
        for r in range(self.n + 1):
            for c in range(self.m + 1):
                edges = []
                if r > 0:
                    edges.append(self.v[r - 1][c])  # up
                if c < self.m:
                    edges.append(self.h[r][c])      # right
                if r < self.n:
                    edges.append(self.v[r][c])      # down
                if c > 0:
                    edges.append(self.h[r][c - 1])  # left
                k = len(edges)
                allowed = [mask for mask in range(1 << k) if mask.bit_count() in (0, 2)]
                add_constraint(edges, allowed)

    def propagate(self, domains, seed_edges=None):
        queue = deque()
        inq = [False] * len(self.constraints)

        def enqueue_edge(e):
            for cid in self.edge_constraints[e]:
                if not inq[cid]:
                    inq[cid] = True
                    queue.append(cid)

        def assign(e, new_mask):
            new_mask &= domains[e]
            if new_mask == 0:
                return False
            if new_mask == domains[e]:
                return True
            domains[e] = new_mask
            enqueue_edge(e)
            return True

        if seed_edges is None:
            for cid in range(len(self.constraints)):
                inq[cid] = True
                queue.append(cid)
        else:
            for e in seed_edges:
                enqueue_edge(e)

        while True:
            while queue:
                cid = queue.popleft()
                inq[cid] = False
                edges, allowed = self.constraints[cid]
                support = [0] * len(edges)
                found = False
                for pat in allowed:
                    ok = True
                    for i, e in enumerate(edges):
                        need = 2 if ((pat >> i) & 1) else 1
                        if not (domains[e] & need):
                            ok = False
                            break
                    if not ok:
                        continue
                    found = True
                    for i, e in enumerate(edges):
                        support[i] |= 2 if ((pat >> i) & 1) else 1
                if not found:
                    return False
                for i, e in enumerate(edges):
                    if support[i] != domains[e]:
                        if not assign(e, support[i]):
                            return False

            ok, changed = self.global_step(domains, assign)
            if not ok:
                return False
            if not changed:
                break

        return True

    def global_step(self, domains, assign):
        changed = False

        on_edges = [e for e, d in enumerate(domains) if d == 2]
        if not on_edges:
            return True, False

        possible_edges = [e for e, d in enumerate(domains) if d & 2]

        deg_on = [0] * self.V
        on_adj = [[] for _ in range(self.V)]
        possible_adj = [[] for _ in range(self.V)]

        for e in possible_edges:
            u, v = self.endpoints[e]
            possible_adj[u].append(v)
            possible_adj[v].append(u)

        active_vertices = set()
        for e in on_edges:
            u, v = self.endpoints[e]
            deg_on[u] += 1
            deg_on[v] += 1
            if deg_on[u] > 2 or deg_on[v] > 2:
                return False, False
            on_adj[u].append(v)
            on_adj[v].append(u)
            active_vertices.add(u)
            active_vertices.add(v)

        # All currently ON edges/components must still be connectable in the graph of possible ON edges.
        start = next(iter(active_vertices))
        seen = {start}
        stack = [start]
        while stack:
            u = stack.pop()
            for v in possible_adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        if any(v not in seen for v in active_vertices):
            return False, False

        # Identify ON-components.
        comp_of = {}
        comps = []
        for v in active_vertices:
            if v in comp_of:
                continue
            cid = len(comps)
            comp = []
            stack = [v]
            comp_of[v] = cid
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in on_adj[x]:
                    if y not in comp_of:
                        comp_of[y] = cid
                        stack.append(y)
            comps.append(comp)

        # A closed cycle is only allowed if it already consumes all edges that can still be ON.
        cycle_count = 0
        for comp in comps:
            if all(deg_on[v] == 2 for v in comp):
                cycle_count += 1
                comp_set = set(comp)
                for e in possible_edges:
                    u, v = self.endpoints[e]
                    if not (u in comp_set and v in comp_set):
                        return False, False
        if cycle_count > 1:
            return False, False

        # If multiple ON-components already exist, any undecided edge that closes one of them into a cycle is impossible.
        if len(comps) > 1:
            for e, d in enumerate(domains):
                if d != 3:
                    continue
                u, v = self.endpoints[e]
                cu = comp_of.get(u)
                cv = comp_of.get(v)
                if cu is not None and cu == cv:
                    if not assign(e, 1):
                        return False, False
                    changed = True

        return True, changed

    def select_branch(self, domains):
        best = None
        best_count = 10 ** 9

        for cid, (edges, allowed) in enumerate(self.constraints):
            count = 0
            stats = [[0, 0] for _ in edges]  # off_count, on_count
            for pat in allowed:
                ok = True
                for i, e in enumerate(edges):
                    need = 2 if ((pat >> i) & 1) else 1
                    if not (domains[e] & need):
                        ok = False
                        break
                if not ok:
                    continue
                count += 1
                for i in range(len(edges)):
                    if (pat >> i) & 1:
                        stats[i][1] += 1
                    else:
                        stats[i][0] += 1
            if 1 < count < best_count:
                undec = [i for i, e in enumerate(edges) if domains[e] == 3]
                if undec:
                    best = (edges, stats)
                    best_count = count
                    if count == 2:
                        break

        if best is not None:
            edges, stats = best
            chosen_e = None
            chosen_pair = None
            chosen_score = None
            for i, e in enumerate(edges):
                if domains[e] != 3:
                    continue
                off_count, on_count = stats[i]
                score = min(off_count, on_count)
                pair = (off_count, on_count)
                if chosen_e is None or score < chosen_score or (score == chosen_score and max(pair) > max(chosen_pair)):
                    chosen_e = e
                    chosen_pair = pair
                    chosen_score = score
            off_count, on_count = chosen_pair
            order = [1, 2] if off_count <= on_count else [2, 1]
            return chosen_e, order

        undecided = [e for e, d in enumerate(domains) if d == 3]
        if not undecided:
            return None, None
        e = max(undecided, key=lambda x: (self.edge_priority[x], len(self.edge_constraints[x])))
        return e, [2, 1]

    def check_clues(self, domains):
        for edges, clue in self.clue_cells:
            s = 0
            for e in edges:
                if domains[e] == 2:
                    s += 1
            if s != clue:
                return False
        return True

    def extract_loop(self, domains):
        on_edges = [e for e, d in enumerate(domains) if d == 2]
        if not on_edges:
            return None

        adj = [[] for _ in range(self.V)]
        for e in on_edges:
            u, v = self.endpoints[e]
            adj[u].append(v)
            adj[v].append(u)

        active = [v for v in range(self.V) if adj[v]]
        if not active:
            return None
        if any(len(adj[v]) != 2 for v in active):
            return None

        seen = {active[0]}
        stack = [active[0]]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        if len(seen) != len(active):
            return None

        start = min(active)
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(on_edges) + 1:
                return None

        if len(path) != len(on_edges) + 1:
            return None

        coords = [(v // (self.m + 1), v % (self.m + 1)) for v in path]
        return coords

    def dfs(self, domains, depth=0):
        if not self.propagate(domains):
            return None

        # Limited human-like contradiction probing on the currently best edge.
        for _ in range(4):
            if all(d != 3 for d in domains):
                break
            e, order = self.select_branch(domains)
            if e is None:
                break
            viable = []
            bad = []
            for val in order:
                if not (domains[e] & val):
                    continue
                trial = domains.copy()
                trial[e] = val
                if self.propagate(trial, [e]):
                    viable.append(val)
                else:
                    bad.append(val)
            if len(viable) == 1 and len(bad) == 1:
                domains[e] = viable[0]
                if not self.propagate(domains, [e]):
                    return None
            else:
                break

        if all(d != 3 for d in domains):
            if not self.check_clues(domains):
                return None
            loop = self.extract_loop(domains)
            return loop

        e, order = self.select_branch(domains)
        if e is None:
            return None

        for val in order:
            if not (domains[e] & val):
                continue
            trial = domains.copy()
            trial[e] = val
            res = self.dfs(trial, depth + 1)
            if res is not None:
                return res
        return None

    def solve(self):
        domains = [3] * self.E
        res = self.dfs(domains)
        if res is None:
            return "No Solution"
        return repr(res)


def solve(observation):
    return SlitherlinkSolver(observation).solve()


