# General LITS-style solver.
# The code is designed to mirror human deduction:
# 1) enumerate all tetromino placements inside each region,
# 2) propagate region-local certainty,
# 3) eliminate same-type conflicts across neighboring regions,
# 4) use the global "no 2x2" rule to force cells white,
# 5) keep the eventual shaded cells connectable,
# 6) branch only on the most constrained region.

from collections import defaultdict, deque

TYPE_NAMES = ("L", "I", "T", "S")
TYPE_INDEX = {t: i for i, t in enumerate(TYPE_NAMES)}


def normalize(shape):
    mr = min(r for r, c in shape)
    mc = min(c for r, c in shape)
    return tuple(sorted((r - mr, c - mc) for r, c in shape))


def generate_variants():
    bases = {
        "I": [(0, 0), (0, 1), (0, 2), (0, 3)],
        "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
        "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
        "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
    }
    out = {k: [] for k in bases}
    for name, shape in bases.items():
        seen = set()
        for swap in (False, True):
            for sr in (-1, 1):
                for sc in (-1, 1):
                    pts = []
                    for r, c in shape:
                        x, y = (c, r) if swap else (r, c)
                        pts.append((sr * x, sc * y))
                    canon = normalize(pts)
                    if canon not in seen:
                        seen.add(canon)
                        out[name].append(canon)
    return out


VARIANTS = generate_variants()


def bits_iter(x):
    while x:
        b = x & -x
        yield b.bit_length() - 1
        x ^= b


def flood_component(mask, start, neighbors):
    seen = 1 << start
    dq = [start]
    while dq:
        u = dq.pop()
        for v in neighbors[u]:
            if ((mask >> v) & 1) and not ((seen >> v) & 1):
                seen |= 1 << v
                dq.append(v)
    return seen


def connected_mask(mask, neighbors):
    if mask == 0:
        return True
    start = (mask & -mask).bit_length() - 1
    return flood_component(mask, start, neighbors) == mask


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    total = n * m

    def idx(r, c):
        return r * m + c

    cells = [(r, c) for r in range(n) for c in range(m)]
    cell_region = [grid[r][c] for r, c in cells]

    # Region cell lists.
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))
    region_ids = sorted(region_cells)
    reg_pos = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    # Cell adjacency.
    neighbors = [[] for _ in range(total)]
    for r in range(n):
        for c in range(m):
            u = idx(r, c)
            if r > 0:
                neighbors[u].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[u].append(idx(r + 1, c))
            if c > 0:
                neighbors[u].append(idx(r, c - 1))
            if c + 1 < m:
                neighbors[u].append(idx(r, c + 1))

    # Region adjacency graph.
    region_neighbors = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = reg_pos[grid[r][c]]
            if r + 1 < n:
                b = reg_pos[grid[r + 1][c]]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)
            if c + 1 < m:
                b = reg_pos[grid[r][c + 1]]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)

    # Precompute all 2x2 masks.
    squares_2x2 = []
    for r in range(n - 1):
        for c in range(m - 1):
            mask = 0
            mask |= 1 << idx(r, c)
            mask |= 1 << idx(r + 1, c)
            mask |= 1 << idx(r, c + 1)
            mask |= 1 << idx(r + 1, c + 1)
            squares_2x2.append(mask)

    # Enumerate all tetromino placements per region.
    region_cands = []
    region_cand_masks = []
    region_cand_types = []
    region_cell_to_candbits = []
    region_type_to_candbits = []

    for rid in region_ids:
        rcells = region_cells[rid]
        rset = set(rcells)
        cands = []
        seen = set()

        for tname, variants in VARIANTS.items():
            tix = TYPE_INDEX[tname]
            for var in variants:
                maxr = max(r for r, c in var)
                maxc = max(c for r, c in var)
                # Human-like region-local scan: place each oriented tetromino wherever it fits.
                for br, bc in rcells:
                    pts = [(br + dr, bc + dc) for dr, dc in var]
                    if any((r, c) not in rset for r, c in pts):
                        continue
                    mask = 0
                    for r, c in pts:
                        mask |= 1 << idx(r, c)
                    key = (mask, tix)
                    if key not in seen:
                        seen.add(key)
                        cands.append((mask, tix))

        if not cands:
            return "No Solution"

        region_cands.append(cands)
        region_cand_masks.append([mask for mask, t in cands])
        region_cand_types.append([t for mask, t in cands])

        cellbits = {}
        for r, c in rcells:
            bit = 0
            cell = idx(r, c)
            for i, (mask, _t) in enumerate(cands):
                if (mask >> cell) & 1:
                    bit |= 1 << i
            cellbits[cell] = bit
        region_cell_to_candbits.append(cellbits)

        typebits = [0, 0, 0, 0]
        for i, (_mask, t) in enumerate(cands):
            typebits[t] |= 1 << i
        region_type_to_candbits.append(typebits)

    all_domain = [(1 << len(cands)) - 1 for cands in region_cands]

    # Region ownership by cell index.
    cell_to_regpos = [reg_pos[cell_region[i]] for i in range(total)]

    # Small cache for type sets.
    def domain_types(reg, dom):
        ts = 0
        for t in range(4):
            if dom & region_type_to_candbits[reg][t]:
                ts |= 1 << t
        return ts

    def popcount(x):
        return x.bit_count()

    def compute_region_union_intersection(reg, dom):
        masks = region_cand_masks[reg]
        first = True
        u = 0
        inter = 0
        count = 0
        x = dom
        while x:
            b = x & -x
            i = b.bit_length() - 1
            cm = masks[i]
            u |= cm
            if first:
                inter = cm
                first = False
            else:
                inter &= cm
            count += 1
            x ^= b
        return u, inter, count

    def propagate(domains):
        # Repeatedly apply deterministic logic until stable.
        while True:
            changed = False

            # Basic emptiness.
            for reg in range(R):
                if domains[reg] == 0:
                    return None

            # Same-type adjacency pruning.
            type_masks = [domain_types(reg, domains[reg]) for reg in range(R)]
            for reg in range(R):
                dom = domains[reg]
                new_dom = dom
                for nb in region_neighbors[reg]:
                    nb_types = type_masks[nb]
                    # Candidate is unsupported only if every possibility in the neighbor has the same type.
                    if nb_types and (nb_types & (nb_types - 1)) == 0:
                        forced_t = nb_types.bit_length() - 1
                        new_dom &= ~region_type_to_candbits[reg][forced_t]
                if new_dom != dom:
                    if new_dom == 0:
                        return None
                    domains[reg] = new_dom
                    changed = True

            # Recompute region-local unions/intersections.
            possible_mask = 0
            forced_mask = 0
            region_union = [0] * R
            region_inter = [0] * R
            region_sizes = [0] * R
            for reg in range(R):
                u, inter, count = compute_region_union_intersection(reg, domains[reg])
                if count == 0:
                    return None
                region_union[reg] = u
                region_inter[reg] = inter
                region_sizes[reg] = count
                possible_mask |= u
                forced_mask |= inter

            # No 2x2 rule propagation.
            for sq in squares_2x2:
                f = popcount(forced_mask & sq)
                if f == 4:
                    return None
                if f == 3:
                    extra = sq & ~forced_mask
                    x = extra & possible_mask
                    while x:
                        b = x & -x
                        cell = b.bit_length() - 1
                        reg = cell_to_regpos[cell]
                        nd = domains[reg] & ~region_cell_to_candbits[reg].get(cell, 0)
                        if nd != domains[reg]:
                            if nd == 0:
                                return None
                            domains[reg] = nd
                            changed = True
                        x ^= b

            # Recompute after 2x2 forced-white eliminations if needed.
            if changed:
                continue

            # Connectivity pruning:
            # All already-forced shaded cells must lie in one connected component of still-possible shaded cells.
            if forced_mask:
                start = (forced_mask & -forced_mask).bit_length() - 1
                comp = flood_component(possible_mask, start, neighbors)
                if forced_mask & ~comp:
                    return None

                # Every undecided region must still have at least one possible cell in that reachable component,
                # otherwise its tetromino can never join the eventual connected cluster.
                for reg in range(R):
                    if region_union[reg] & comp:
                        continue
                    return None

            # Candidate-level support check against neighboring type domains.
            # This is a stronger pass than the singleton-type rule above.
            type_masks = [domain_types(reg, domains[reg]) for reg in range(R)]
            for reg in range(R):
                dom = domains[reg]
                new_dom = dom
                x = dom
                while x:
                    b = x & -x
                    i = b.bit_length() - 1
                    t = region_cand_types[reg][i]
                    ok = True
                    for nb in region_neighbors[reg]:
                        nb_ts = type_masks[nb]
                        if nb_ts == (1 << t):
                            ok = False
                            break
                    if not ok:
                        new_dom ^= b
                    x ^= b
                if new_dom != dom:
                    if new_dom == 0:
                        return None
                    domains[reg] = new_dom
                    changed = True

            if not changed:
                return domains

    def finalize(domains):
        chosen_masks = []
        chosen_types = []
        shaded = 0
        for reg in range(R):
            dom = domains[reg]
            if dom == 0 or (dom & (dom - 1)):
                return None
            i = dom.bit_length() - 1
            mask, t = region_cands[reg][i]
            chosen_masks.append(mask)
            chosen_types.append(t)
            shaded |= mask

        # Verify adjacency type rule.
        for reg in range(R):
            for nb in region_neighbors[reg]:
                if reg < nb and chosen_types[reg] == chosen_types[nb]:
                    return None

        # Verify no 2x2 shaded.
        for sq in squares_2x2:
            if (sq & shaded) == sq:
                return None

        # Verify global connectivity.
        if not connected_mask(shaded, neighbors):
            return None

        # Build answer grid with tetromino type letter on shaded cells, None otherwise.
        ans = [[None for _ in range(m)] for _ in range(n)]
        for reg in range(R):
            tname = TYPE_NAMES[chosen_types[reg]]
            mask = chosen_masks[reg]
            x = mask
            while x:
                b = x & -x
                cell = b.bit_length() - 1
                rr, cc = divmod(cell, m)
                ans[rr][cc] = tname
                x ^= b
        return ans

    def choose_region(domains):
        # Human-style: branch on the tightest region.
        best = None
        best_key = None
        for reg in range(R):
            dom = domains[reg]
            cnt = dom.bit_count()
            if cnt <= 1:
                continue
            u, inter, _ = compute_region_union_intersection(reg, dom)
            uncertainty = (u ^ inter).bit_count()
            type_cnt = domain_types(reg, dom).bit_count()
            key = (cnt, type_cnt, uncertainty)
            if best is None or key < best_key:
                best = reg
                best_key = key
        return best

    def candidate_order(reg, domains):
        dom = domains[reg]
        forced_mask = 0
        for r in range(R):
            _u, inter, _ = compute_region_union_intersection(r, domains[r])
            forced_mask |= inter

        items = []
        x = dom
        while x:
            b = x & -x
            i = b.bit_length() - 1
            mask, t = region_cands[reg][i]

            # Prefer candidates touching the existing forced component.
            touch = 0
            y = mask
            while y:
                bb = y & -y
                cell = bb.bit_length() - 1
                for nb in neighbors[cell]:
                    if (forced_mask >> nb) & 1:
                        touch += 1
                y ^= bb

            # Penalize local 2x2 pressure.
            penalty = 0
            for sq in squares_2x2:
                if popcount(sq & mask) >= 3:
                    penalty += 1

            items.append((-touch, penalty, TYPE_NAMES[t], i))
            x ^= b

        items.sort()
        return [i for *_rest, i in items]

    def search(domains):
        domains = propagate(domains[:])
        if domains is None:
            return None

        done = True
        for dom in domains:
            if dom & (dom - 1):
                done = False
                break
        if done:
            return finalize(domains)

        reg = choose_region(domains)
        if reg is None:
            return None

        for i in candidate_order(reg, domains):
            nd = domains[:]
            nd[reg] = 1 << i
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(all_domain)
    return repr(result) if result is not None else "No Solution"


