# General-purpose tetromino-region puzzle solver.
# It models each region as choosing exactly one tetromino placement,
# then propagates human-style deductions:
# - region candidate enumeration
# - region type fixing and neighboring type exclusion
# - forced-cell analysis
# - 2x2 forbidden-block elimination
# - global connectivity viability pruning
# - depth-first search only after propagation stalls

from collections import defaultdict

TYPE_CHARS = ['L', 'I', 'T', 'S']
TYPE_INDEX = {ch: i for i, ch in enumerate(TYPE_CHARS)}


def _normalize(coords):
    min_r = min(r for r, _ in coords)
    min_c = min(c for _, c in coords)
    return tuple(sorted((r - min_r, c - min_c) for r, c in coords))


def _transform(coords, rot, ref):
    out = []
    for r, c in coords:
        if ref:
            c = -c
        if rot == 0:
            rr, cc = r, c
        elif rot == 1:
            rr, cc = c, -r
        elif rot == 2:
            rr, cc = -r, -c
        else:
            rr, cc = -c, r
        out.append((rr, cc))
    return _normalize(out)


def build_shape_variants():
    base = {
        'L': [(0, 0), (1, 0), (2, 0), (2, 1)],
        'I': [(0, 0), (1, 0), (2, 0), (3, 0)],
        'T': [(0, 0), (0, 1), (0, 2), (1, 1)],
        'S': [(0, 1), (0, 2), (1, 0), (1, 1)],
    }
    variants = {}
    for t, coords in base.items():
        seen = set()
        for rot in range(4):
            for ref in (0, 1):
                seen.add(_transform(coords, rot, ref))
        variants[t] = sorted(seen)
    return variants


SHAPE_VARIANTS = build_shape_variants()


class Puzzle:
    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.n2 = self.n * self.n

        ids = sorted({x for row in data for x in row})
        remap = {rid: i for i, rid in enumerate(ids)}
        self.region_grid = [[remap[x] for x in row] for row in data]
        self.region_count = len(ids)

        self.cell_region = [0] * self.n2
        self.region_cells = [[] for _ in range(self.region_count)]
        self.region_coord_sets = [set() for _ in range(self.region_count)]

        for r in range(self.n):
            for c in range(self.n):
                cid = r * self.n + c
                reg = self.region_grid[r][c]
                self.cell_region[cid] = reg
                self.region_cells[reg].append(cid)
                self.region_coord_sets[reg].add((r, c))

        self.neigh_bits = [0] * self.n2
        for r in range(self.n):
            for c in range(self.n):
                cid = r * self.n + c
                bits = 0
                if r > 0:
                    bits |= 1 << ((r - 1) * self.n + c)
                if r + 1 < self.n:
                    bits |= 1 << ((r + 1) * self.n + c)
                if c > 0:
                    bits |= 1 << (r * self.n + c - 1)
                if c + 1 < self.n:
                    bits |= 1 << (r * self.n + c + 1)
                self.neigh_bits[cid] = bits

        self.blocks = []
        self.block_cells = []
        self.blocks_by_cell = [[] for _ in range(self.n2)]
        for r in range(self.n - 1):
            for c in range(self.n - 1):
                cells = (
                    r * self.n + c,
                    r * self.n + (c + 1),
                    (r + 1) * self.n + c,
                    (r + 1) * self.n + (c + 1),
                )
                mask = 0
                for cid in cells:
                    mask |= 1 << cid
                bi = len(self.blocks)
                self.blocks.append(mask)
                self.block_cells.append(cells)
                for cid in cells:
                    self.blocks_by_cell[cid].append(bi)

        self.region_adj = [set() for _ in range(self.region_count)]
        for r in range(self.n):
            for c in range(self.n):
                a = self.region_grid[r][c]
                if r + 1 < self.n:
                    b = self.region_grid[r + 1][c]
                    if a != b:
                        self.region_adj[a].add(b)
                        self.region_adj[b].add(a)
                if c + 1 < self.n:
                    b = self.region_grid[r][c + 1]
                    if a != b:
                        self.region_adj[a].add(b)
                        self.region_adj[b].add(a)

        self.candidate_bits = [[] for _ in range(self.region_count)]
        self.candidate_types = [[] for _ in range(self.region_count)]
        self.candidate_blocks = [[] for _ in range(self.region_count)]
        self.candidate_touch = [[] for _ in range(self.region_count)]
        self.type_to_candmask = [[0] * 4 for _ in range(self.region_count)]
        self.region_info_cache = [dict() for _ in range(self.region_count)]

        self._enumerate_candidates()

        self.initial_domains = []
        for r in range(self.region_count):
            k = len(self.candidate_bits[r])
            if k == 0:
                self.initial_domains = None
                return
            self.initial_domains.append((1 << k) - 1)

        self.fail_cache = set()

    def _enumerate_candidates(self):
        region_cell_masks = [0] * self.region_count
        for reg in range(self.region_count):
            bits = 0
            for cid in self.region_cells[reg]:
                bits |= 1 << cid
            region_cell_masks[reg] = bits

        for reg in range(self.region_count):
            coords = self.region_coord_sets[reg]
            found = {}
            for tchar, variants in SHAPE_VARIANTS.items():
                tid = TYPE_INDEX[tchar]
                local_seen = set()
                for var in variants:
                    for base_r, base_c in coords:
                        placed = tuple(sorted((base_r + dr, base_c + dc) for dr, dc in var))
                        if all(p in coords for p in placed):
                            local_seen.add(placed)
                for placed in local_seen:
                    bits = 0
                    touch_bits = 0
                    rel_blocks = set()
                    for rr, cc in placed:
                        cid = rr * self.n + cc
                        bits |= 1 << cid
                        touch_bits |= self.neigh_bits[cid]
                        rel_blocks.update(self.blocks_by_cell[cid])
                    touch_bits &= ~bits
                    border_touch = 0
                    tb = touch_bits
                    while tb:
                        b = tb & -tb
                        tb -= b
                        cid = b.bit_length() - 1
                        if self.cell_region[cid] != reg:
                            border_touch += 1
                    found[(bits, tid)] = (bits, tid, sorted(rel_blocks), border_touch)

            ordered = sorted(found.values(), key=lambda x: (x[1], x[0]))
            for idx, (bits, tid, rel_blocks, border_touch) in enumerate(ordered):
                self.candidate_bits[reg].append(bits)
                self.candidate_types[reg].append(tid)
                self.candidate_blocks[reg].append(rel_blocks)
                self.candidate_touch[reg].append(border_touch)
                self.type_to_candmask[reg][tid] |= 1 << idx

    def _region_info(self, reg, dommask):
        cache = self.region_info_cache[reg]
        if dommask in cache:
            return cache[dommask]
        if dommask == 0:
            return None
        m = dommask
        possible = 0
        forced = None
        tmask = 0
        count = 0
        last = -1
        while m:
            b = m & -m
            m -= b
            idx = b.bit_length() - 1
            bits = self.candidate_bits[reg][idx]
            possible |= bits
            forced = bits if forced is None else (forced & bits)
            tmask |= 1 << self.candidate_types[reg][idx]
            count += 1
            last = idx
        info = (possible, forced if forced is not None else 0, tmask, count, last if count == 1 else -1)
        cache[dommask] = info
        return info

    def _all_region_stats(self, domains):
        possible = [0] * self.region_count
        forced = [0] * self.region_count
        tmask = [0] * self.region_count
        counts = [0] * self.region_count
        single = [-1] * self.region_count
        for reg in range(self.region_count):
            info = self._region_info(reg, domains[reg])
            if info is None:
                return None
            possible[reg], forced[reg], tmask[reg], counts[reg], single[reg] = info
        return possible, forced, tmask, counts, single

    def _candidate_makes_forbidden_block(self, reg, idx, forced):
        cbits = self.candidate_bits[reg][idx]
        for bi in self.candidate_blocks[reg][idx]:
            full = True
            for cid in self.block_cells[bi]:
                owner = self.cell_region[cid]
                bit = 1 << cid
                if owner == reg:
                    if (cbits & bit) == 0:
                        full = False
                        break
                else:
                    if (forced[owner] & bit) == 0:
                        full = False
                        break
            if full:
                return True
        return False

    def _compute_possible_components(self, possible, forced):
        P = 0
        D = 0
        for reg in range(self.region_count):
            P |= possible[reg]
            D |= forced[reg]
        if P == 0:
            return None

        comp_of = [-1] * self.n2
        comps = []
        rem = P
        while rem:
            seed = rem & -rem
            frontier = seed
            comp = 0
            while frontier:
                b = frontier & -frontier
                frontier -= b
                if comp & b:
                    continue
                comp |= b
                cid = b.bit_length() - 1
                frontier |= self.neigh_bits[cid] & P & ~comp
            cid_list_bits = comp
            comp_id = len(comps)
            while cid_list_bits:
                b = cid_list_bits & -cid_list_bits
                cid_list_bits -= b
                comp_of[b.bit_length() - 1] = comp_id
            comps.append(comp)
            rem &= ~comp

        viable_ids = []
        if D:
            first_comp = -1
            x = D
            while x:
                b = x & -x
                x -= b
                cid = b.bit_length() - 1
                comp_id = comp_of[cid]
                if first_comp == -1:
                    first_comp = comp_id
                elif first_comp != comp_id:
                    return None
            comp = comps[first_comp]
            for reg in range(self.region_count):
                if (possible[reg] & comp) == 0:
                    return None
            viable_ids = [first_comp]
        else:
            for comp_id, comp in enumerate(comps):
                ok = True
                for reg in range(self.region_count):
                    if (possible[reg] & comp) == 0:
                        ok = False
                        break
                if ok:
                    viable_ids.append(comp_id)
            if not viable_ids:
                return None

        return comps, comp_of, viable_ids

    def propagate(self, domains):
        domains = list(domains)

        while True:
            stats = self._all_region_stats(domains)
            if stats is None:
                return None
            possible, forced, tmask, counts, single = stats

            progress = False

            # Same-type exclusion when a region's tetromino type is fixed.
            for reg in range(self.region_count):
                tm = tmask[reg]
                if tm == 0:
                    return None
                if (tm & (tm - 1)) == 0:
                    tid = tm.bit_length() - 1
                    for nb in self.region_adj[reg]:
                        new_dom = domains[nb] & ~self.type_to_candmask[nb][tid]
                        if new_dom != domains[nb]:
                            if new_dom == 0:
                                return None
                            domains[nb] = new_dom
                            progress = True
            if progress:
                continue

            # Direct forbidden 2x2 detection from globally forced shaded cells.
            global_forced = 0
            for reg in range(self.region_count):
                global_forced |= forced[reg]
            for block_mask in self.blocks:
                if (global_forced & block_mask) == block_mask:
                    return None

            # Candidate-specific forbidden 2x2 pruning.
            for reg in range(self.region_count):
                dom = domains[reg]
                remove = 0
                m = dom
                while m:
                    b = m & -m
                    m -= b
                    idx = b.bit_length() - 1
                    if self._candidate_makes_forbidden_block(reg, idx, forced):
                        remove |= b
                if remove:
                    new_dom = dom & ~remove
                    if new_dom == 0:
                        return None
                    domains[reg] = new_dom
                    progress = True
            if progress:
                continue

            # Connectivity viability on the union of possible shaded cells.
            comp_data = self._compute_possible_components(possible, forced)
            if comp_data is None:
                return None
            comps, comp_of, viable_ids = comp_data
            viable_mask_bits = 0
            for comp_id in viable_ids:
                viable_mask_bits |= comps[comp_id]

            for reg in range(self.region_count):
                dom = domains[reg]
                remove = 0
                m = dom
                while m:
                    b = m & -m
                    m -= b
                    idx = b.bit_length() - 1
                    cbits = self.candidate_bits[reg][idx]
                    if (cbits & viable_mask_bits) != cbits:
                        remove |= b
                if remove:
                    new_dom = dom & ~remove
                    if new_dom == 0:
                        return None
                    domains[reg] = new_dom
                    progress = True
            if progress:
                continue

            return tuple(domains)

    def _bitcount(self, x):
        return x.bit_count()

    def _choose_region(self, domains):
        stats = self._all_region_stats(domains)
        possible, forced, tmask, counts, single = stats
        best = None
        best_key = None
        for reg in range(self.region_count):
            if counts[reg] <= 1:
                continue
            key = (
                counts[reg],
                self._bitcount(tmask[reg]),
                -len(self.region_adj[reg]),
                -self._bitcount(forced[reg]),
            )
            if best_key is None or key < best_key:
                best_key = key
                best = reg
        return best

    def _order_candidates(self, reg, domains):
        stats = self._all_region_stats(domains)
        possible, forced, tmask, counts, single = stats

        other_possible = 0
        for r in range(self.region_count):
            if r != reg:
                other_possible |= possible[r]

        scored = []
        dom = domains[reg]
        m = dom
        while m:
            b = m & -m
            m -= b
            idx = b.bit_length() - 1
            cbits = self.candidate_bits[reg][idx]
            tid = self.candidate_types[reg][idx]

            edge_touch = 0
            x = cbits
            while x:
                bb = x & -x
                x -= bb
                cid = bb.bit_length() - 1
                edge_touch += (self.neigh_bits[cid] & other_possible).bit_count()

            conflict = 0
            for nb in self.region_adj[reg]:
                if (tmask[nb] >> tid) & 1:
                    conflict += 1

            # Prefer candidates that touch more possible shading and create fewer type conflicts.
            score = (-edge_touch, conflict, -self.candidate_touch[reg][idx], idx)
            scored.append((score, idx))

        scored.sort()
        return [idx for _, idx in scored]

    def _is_connected(self, bits):
        if bits == 0:
            return False
        seed = bits & -bits
        seen = 0
        frontier = seed
        while frontier:
            b = frontier & -frontier
            frontier -= b
            if seen & b:
                continue
            seen |= b
            cid = b.bit_length() - 1
            frontier |= self.neigh_bits[cid] & bits & ~seen
        return seen == bits

    def _final_check(self, domains):
        shaded = 0
        chosen_type = [-1] * self.region_count
        for reg in range(self.region_count):
            if self._bitcount(domains[reg]) != 1:
                return False
            idx = domains[reg].bit_length() - 1
            chosen_type[reg] = self.candidate_types[reg][idx]
            shaded |= self.candidate_bits[reg][idx]

        for reg in range(self.region_count):
            for nb in self.region_adj[reg]:
                if reg < nb and chosen_type[reg] == chosen_type[nb]:
                    return False

        for block_mask in self.blocks:
            if (shaded & block_mask) == block_mask:
                return False

        if not self._is_connected(shaded):
            return False

        return True

    def _build_answer(self, domains):
        ans = [[None for _ in range(self.n)] for _ in range(self.n)]
        for reg in range(self.region_count):
            idx = domains[reg].bit_length() - 1
            ch = TYPE_CHARS[self.candidate_types[reg][idx]]
            bits = self.candidate_bits[reg][idx]
            x = bits
            while x:
                b = x & -x
                x -= b
                cid = b.bit_length() - 1
                r, c = divmod(cid, self.n)
                ans[r][c] = ch
        return ans

    def dfs(self, domains):
        domains = self.propagate(domains)
        if domains is None:
            return None

        if domains in self.fail_cache:
            return None

        done = True
        for d in domains:
            if d & (d - 1):
                done = False
                break

        if done:
            if self._final_check(domains):
                return domains
            self.fail_cache.add(domains)
            return None

        reg = self._choose_region(domains)
        if reg is None:
            self.fail_cache.add(domains)
            return None

        for idx in self._order_candidates(reg, domains):
            new_domains = list(domains)
            new_domains[reg] = 1 << idx
            res = self.dfs(tuple(new_domains))
            if res is not None:
                return res

        self.fail_cache.add(domains)
        return None

    def solve(self):
        if self.initial_domains is None:
            return None
        result = self.dfs(tuple(self.initial_domains))
        if result is None:
            return None
        return self._build_answer(result)


def solve(observation):
    data = observation.get('data')
    if not isinstance(data, list) or not data or any(not isinstance(row, list) for row in data):
        return "No Solution"
    n = len(data)
    if any(len(row) != n for row in data):
        return "No Solution"

    puzzle = Puzzle(data)
    answer = puzzle.solve()
    if answer is None:
        return "No Solution"
    return repr(answer)


