from collections import defaultdict, deque

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    R = len(region)
    C = len(region[0])
    N = R * C

    def idx(r, c):
        return r * C + c

    def rc(i):
        return divmod(i, C)

    # Grid graph
    neighbors = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < R:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < C:
                neighbors[i].append(idx(r, c + 1))

    # Regions and clues
    reg_cells = defaultdict(list)
    clue_by_region = {}
    for r in range(R):
        for c in range(C):
            rid = region[r][c]
            reg_cells[rid].append(idx(r, c))
            v = data[r][c]
            if v is not None:
                if rid in clue_by_region and clue_by_region[rid] != v:
                    return "No Solution"
                clue_by_region[rid] = v

    # Precompute clue-region black patterns (exact count + no orthogonal touching inside region)
    clue_region_cells = {}
    clue_region_patterns = {}
    for rid, k in clue_by_region.items():
        cells = reg_cells[rid]
        m = len(cells)
        clue_region_cells[rid] = cells
        pos_of = {cell: i for i, cell in enumerate(cells)}
        adjmask = [0] * m
        for i, cell in enumerate(cells):
            mask = 0
            for nb in neighbors[cell]:
                j = pos_of.get(nb)
                if j is not None:
                    mask |= 1 << j
            adjmask[i] = mask

        pats = []
        full = 1 << m
        for mask in range(full):
            if mask.bit_count() != k:
                continue
            ok = True
            for i in range(m):
                if (mask >> i) & 1:
                    if mask & adjmask[i]:
                        ok = False
                        break
            if ok:
                pats.append(mask)

        if not pats:
            return "No Solution"
        clue_region_patterns[rid] = pats

    # Precompute 3-run line constraints:
    # in each row/col, any 3 consecutive region-runs cannot all be white
    windows = []
    seen_windows = set()

    def add_line(line_cells):
        runs = []
        cur = [line_cells[0]]
        prev_rid = region[line_cells[0] // C][line_cells[0] % C]
        for cell in line_cells[1:]:
            rid = region[cell // C][cell % C]
            if rid == prev_rid:
                cur.append(cell)
            else:
                runs.append(cur)
                cur = [cell]
                prev_rid = rid
        runs.append(cur)
        for i in range(len(runs) - 2):
            win = tuple(runs[i] + runs[i + 1] + runs[i + 2])
            if win not in seen_windows:
                seen_windows.add(win)
                windows.append(win)

    for r in range(R):
        add_line([idx(r, c) for c in range(C)])
    for c in range(C):
        add_line([idx(r, c) for r in range(R)])

    cell_windows = [[] for _ in range(N)]
    for wi, win in enumerate(windows):
        for cell in win:
            cell_windows[cell].append(wi)

    # Values: -1 unknown, 0 white, 1 black
    def compute_candidates(vals):
        region_cands = {}
        black_possible = [False] * N

        # Numbered regions
        for rid, pats in clue_region_patterns.items():
            cells = clue_region_cells[rid]
            valid = []
            union = 0
            for pat in pats:
                ok = True
                for i, cell in enumerate(cells):
                    bit = (pat >> i) & 1
                    v = vals[cell]
                    if v == 1 and not bit:
                        ok = False
                        break
                    if v == 0 and bit:
                        ok = False
                        break
                    if bit:
                        # chosen black cannot touch any fixed black anywhere
                        for nb in neighbors[cell]:
                            if vals[nb] == 1:
                                ok = False
                                break
                        if not ok:
                            break
                if ok:
                    valid.append(pat)
                    union |= pat
            if not valid:
                return None, None
            region_cands[rid] = valid
            for i, cell in enumerate(cells):
                if vals[cell] == 1 or ((union >> i) & 1):
                    black_possible[cell] = True

        # Unnumbered regions: black is possible unless touching a fixed black
        for rid, cells in reg_cells.items():
            if rid in clue_region_patterns:
                continue
            for cell in cells:
                if vals[cell] == 1:
                    black_possible[cell] = True
                elif vals[cell] == -1:
                    can_black = True
                    for nb in neighbors[cell]:
                        if vals[nb] == 1:
                            can_black = False
                            break
                    if can_black:
                        black_possible[cell] = True

        return region_cands, black_possible

    def potential_component(start, vals):
        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            for nb in neighbors[cur]:
                if vals[nb] != 1 and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return seen

    def propagate(vals):
        vals = vals[:]

        while True:
            changed = False

            # Black adjacency
            for cell, v in enumerate(vals):
                if v != 1:
                    continue
                for nb in neighbors[cell]:
                    if vals[nb] == 1:
                        return None, None
                    if vals[nb] == -1:
                        vals[nb] = 0
                        changed = True
            if changed:
                continue

            # Region pattern filtering
            region_cands, black_possible = compute_candidates(vals)
            if region_cands is None:
                return None, None

            for rid, valid in region_cands.items():
                cells = clue_region_cells[rid]
                m = len(cells)
                inter = (1 << m) - 1
                union = 0
                for pat in valid:
                    inter &= pat
                    union |= pat
                for i, cell in enumerate(cells):
                    if vals[cell] != -1:
                        continue
                    if (inter >> i) & 1:
                        vals[cell] = 1
                        changed = True
                    elif not ((union >> i) & 1):
                        vals[cell] = 0
                        changed = True
            if changed:
                continue

            # Any cell that cannot be black becomes white
            for cell in range(N):
                if vals[cell] == -1 and not black_possible[cell]:
                    vals[cell] = 0
                    changed = True
            if changed:
                continue

            # 3-run windows: at least one black in each
            for win in windows:
                has_black = False
                unknown_exists = False
                feasible = []
                for cell in win:
                    if vals[cell] == 1:
                        has_black = True
                        break
                    if vals[cell] == -1:
                        unknown_exists = True
                        if black_possible[cell]:
                            feasible.append(cell)
                if has_black:
                    continue
                if not unknown_exists:
                    return None, None
                if not feasible:
                    return None, None
                if len(feasible) == 1:
                    vals[feasible[0]] = 1
                    changed = True
                    break
            if changed:
                continue

            # White connectivity
            white_cells = [i for i, v in enumerate(vals) if v == 0]
            if white_cells:
                comp = potential_component(white_cells[0], vals)
                for w in white_cells[1:]:
                    if w not in comp:
                        return None, None

                # Any potential cell disconnected from current white component can never be white
                outside = [i for i, v in enumerate(vals) if v != 1 and i not in comp]
                if outside:
                    for cell in outside:
                        vals[cell] = 1
                    changed = True
                    continue

                # Unknown articulation for already-white cells must stay white
                if len(white_cells) >= 2:
                    forced_white = None
                    white_set = set(white_cells)
                    for cell in comp:
                        if vals[cell] != -1:
                            continue
                        local_deg = 0
                        for nb in neighbors[cell]:
                            if nb in comp and vals[nb] != 1:
                                local_deg += 1
                        if local_deg < 2:
                            continue

                        start = None
                        for w in white_cells:
                            if w != cell:
                                start = w
                                break
                        if start is None:
                            continue

                        seen = {start}
                        dq = deque([start])
                        while dq:
                            cur = dq.popleft()
                            for nb in neighbors[cur]:
                                if nb == cell or vals[nb] == 1 or nb not in comp or nb in seen:
                                    continue
                                seen.add(nb)
                                dq.append(nb)

                        bad = False
                        for w in white_cells:
                            if w != cell and w not in seen:
                                bad = True
                                break
                        if bad:
                            forced_white = cell
                            break

                    if forced_white is not None:
                        vals[forced_white] = 0
                        changed = True
                        continue

            # Stable
            region_cands, black_possible = compute_candidates(vals)
            if region_cands is None:
                return None, None
            return vals, {"region_cands": region_cands, "black_possible": black_possible}

    def validate(vals):
        if any(v == -1 for v in vals):
            return False

        # No adjacent blacks
        for cell, v in enumerate(vals):
            if v == 1:
                for nb in neighbors[cell]:
                    if vals[nb] == 1:
                        return False

        # Numbered region counts
        for rid, k in clue_by_region.items():
            cnt = sum(1 for cell in reg_cells[rid] if vals[cell] == 1)
            if cnt != k:
                return False

        # 3-run line rule
        for win in windows:
            if not any(vals[cell] == 1 for cell in win):
                return False

        # White connectivity
        whites = [i for i, v in enumerate(vals) if v == 0]
        if whites:
            seen = {whites[0]}
            dq = deque([whites[0]])
            while dq:
                cur = dq.popleft()
                for nb in neighbors[cur]:
                    if vals[nb] == 0 and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(whites):
                return False

        return True

    dead = set()

    def choose_branch(vals, ctx):
        # Prefer a numbered region with few candidate patterns
        best = None
        for rid, cands in ctx["region_cands"].items():
            if len(cands) <= 1:
                continue
            cells = clue_region_cells[rid]
            m = len(cells)
            total = len(cands)
            freq = [0] * m
            for pat in cands:
                b = pat
                while b:
                    lsb = b & -b
                    i = lsb.bit_length() - 1
                    freq[i] += 1
                    b ^= lsb
            for i, cell in enumerate(cells):
                if vals[cell] != -1:
                    continue
                f = freq[i]
                if f == 0 or f == total:
                    continue
                score = (total, abs(total - 2 * f), -len(cell_windows[cell]), -len(neighbors[cell]), cell)
                if best is None or score < best[0]:
                    best = (score, cell, f, total)

        if best is not None:
            _, cell, f, total = best
            black_first = f <= (total - f)
            order = [1, 0] if black_first else [0, 1]
            return cell, order

        # Fallback: most constrained unknown cell
        best = None
        black_possible = ctx["black_possible"]
        for cell, v in enumerate(vals):
            if v != -1:
                continue
            score = (-len(cell_windows[cell]), -sum(1 for nb in neighbors[cell] if vals[nb] == -1), cell)
            if best is None or score < best[0]:
                best = (score, cell)
        if best is None:
            return None, []
        cell = best[1]
        if black_possible[cell]:
            return cell, [1, 0]
        return cell, [0]

    def dfs(vals):
        vals, ctx = propagate(vals)
        if vals is None:
            return None

        key = tuple(vals)
        if key in dead:
            return None

        if all(v != -1 for v in vals):
            if validate(vals):
                return vals
            dead.add(key)
            return None

        cell, order = choose_branch(vals, ctx)
        if cell is None:
            dead.add(key)
            return None

        for val in order:
            if val == 1 and not ctx["black_possible"][cell]:
                continue
            new_vals = vals[:]
            if new_vals[cell] != -1 and new_vals[cell] != val:
                continue
            new_vals[cell] = val
            ans = dfs(new_vals)
            if ans is not None:
                return ans

        dead.add(key)
        return None

    start = [-1] * N
    result = dfs(start)
    if result is None:
        return "No Solution"

    return [[("B" if result[idx(r, c)] == 1 else None) for c in range(C)] for r in range(R)]


