# Generalized Masyu-on-dots solver.
# The solver is built around human-style local deductions:
# - every vertex has a small domain of legal local path patterns
# - edge consistency propagates between neighboring vertices
# - white-circle "must go straight, and turn before or after" is enforced explicitly
# - black-circle "must turn, with straight neighbors before and after" is enforced by adjacency compatibility
# - global pruning prevents disconnected clue regions and premature closed subloops
# Search is only used after aggressive propagation.

SID_UNUSED = 0
SID_SV = 1
SID_SH = 2
SID_UL = 3
SID_UR = 4
SID_DL = 5
SID_DR = 6

DIRS = ('U', 'D', 'L', 'R')
U, D, L, R = 0, 1, 2, 3
DIR_BITS = (1, 2, 4, 8)
OPP = (D, U, R, L)
AXIS = ('v', 'v', 'h', 'h')

STATE_EDGES = (
    0,
    DIR_BITS[U] | DIR_BITS[D],
    DIR_BITS[L] | DIR_BITS[R],
    DIR_BITS[U] | DIR_BITS[L],
    DIR_BITS[U] | DIR_BITS[R],
    DIR_BITS[D] | DIR_BITS[L],
    DIR_BITS[D] | DIR_BITS[R],
)

STATE_NAME = ('unused', 'sv', 'sh', 'ul', 'ur', 'dl', 'dr')
STATE_AXIS = (None, 'v', 'h', None, None, None, None)
STATE_TURN = (False, False, False, True, True, True, True)

BIT = tuple(1 << i for i in range(7))
UNUSED_BIT = BIT[SID_UNUSED]
SV_BIT = BIT[SID_SV]
SH_BIT = BIT[SID_SH]
TURN_MASK = BIT[SID_UL] | BIT[SID_UR] | BIT[SID_DL] | BIT[SID_DR]
USED_MASK = SV_BIT | SH_BIT | TURN_MASK
ALL_STATE_MASK = UNUSED_BIT | USED_MASK

USE_DIR_MASK = [0, 0, 0, 0]
TURN_USE_DIR_MASK = [0, 0, 0, 0]
for sid in range(7):
    e = STATE_EDGES[sid]
    for di in range(4):
        if e & DIR_BITS[di]:
            USE_DIR_MASK[di] |= BIT[sid]
            if STATE_TURN[sid]:
                TURN_USE_DIR_MASK[di] |= BIT[sid]

TYPE_NONE = 0
TYPE_WHITE = 1
TYPE_BLACK = 2


def _bits(mask):
    while mask:
        b = mask & -mask
        yield b.bit_length() - 1, b
        mask ^= b


def _bitcount(x):
    return x.bit_count()


def _singleton_sid(mask):
    return mask.bit_length() - 1


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    vcount = n * n

    def vid(r, c):
        return r * n + c

    def rc(v):
        return divmod(v, n)

    types = [TYPE_NONE] * vcount
    white_vertices = []
    clue_vertices = []
    for r in range(n):
        for c in range(n):
            v = vid(r, c)
            cell = data[r][c]
            if cell == 'W':
                types[v] = TYPE_WHITE
                white_vertices.append(v)
                clue_vertices.append(v)
            elif cell == 'B':
                types[v] = TYPE_BLACK
                clue_vertices.append(v)

    nb = [[-1] * 4 for _ in range(vcount)]
    neighdirs = [[] for _ in range(vcount)]
    undirected_edges = []

    for r in range(n):
        for c in range(n):
            v = vid(r, c)
            if r > 0:
                u = vid(r - 1, c)
                nb[v][U] = u
                neighdirs[v].append((u, U))
            if r + 1 < n:
                u = vid(r + 1, c)
                nb[v][D] = u
                neighdirs[v].append((u, D))
                undirected_edges.append((v, u, D))
            if c > 0:
                u = vid(r, c - 1)
                nb[v][L] = u
                neighdirs[v].append((u, L))
            if c + 1 < n:
                u = vid(r, c + 1)
                nb[v][R] = u
                neighdirs[v].append((u, R))
                undirected_edges.append((v, u, R))

    # Precompute directional compatibility tables for each endpoint clue-type pair.
    # Compatibility includes:
    # - both ends agree whether the shared edge is used
    # - if a black clue uses the edge, the neighbor must be straight in that axis
    # - same symmetrically for the other endpoint
    FULL_COMP = [[[[0] * 4 for _ in range(7)] for _ in range(3)] for _ in range(3)]
    ON_COMP = [[[[0] * 4 for _ in range(7)] for _ in range(3)] for _ in range(3)]
    OFF_COMP = [[[[0] * 4 for _ in range(7)] for _ in range(3)] for _ in range(3)]

    for ta in range(3):
        for tb in range(3):
            for sid_a in range(7):
                ea = STATE_EDGES[sid_a]
                for di in range(4):
                    axis = AXIS[di]
                    opp = OPP[di]
                    a_uses = bool(ea & DIR_BITS[di])
                    full_mask = 0
                    on_mask = 0
                    off_mask = 0
                    for sid_b in range(7):
                        eb = STATE_EDGES[sid_b]
                        b_uses = bool(eb & DIR_BITS[opp])
                        if a_uses != b_uses:
                            continue
                        if a_uses:
                            if ta == TYPE_BLACK and STATE_AXIS[sid_b] != axis:
                                continue
                            if tb == TYPE_BLACK and STATE_AXIS[sid_a] != axis:
                                continue
                            on_mask |= BIT[sid_b]
                        else:
                            off_mask |= BIT[sid_b]
                        full_mask |= BIT[sid_b]
                    FULL_COMP[ta][tb][sid_a][di] = full_mask
                    ON_COMP[ta][tb][sid_a][di] = on_mask
                    OFF_COMP[ta][tb][sid_a][di] = off_mask

    def initial_domain(v):
        avail = 0
        for di in range(4):
            if nb[v][di] != -1:
                avail |= DIR_BITS[di]
        if types[v] == TYPE_WHITE:
            base = SV_BIT | SH_BIT
        elif types[v] == TYPE_BLACK:
            base = TURN_MASK
        else:
            base = ALL_STATE_MASK
        out = 0
        for sid, b in _bits(base):
            if (STATE_EDGES[sid] & ~avail) == 0:
                out |= b
        return out

    domains0 = [initial_domain(v) for v in range(vcount)]
    if any(m == 0 for m in domains0):
        return "No Solution"

    def edge_possibilities(domains, v, u, di):
        ta = types[v]
        tb = types[u]
        du = domains[u]
        any_on = False
        any_off = False
        for sid, _ in _bits(domains[v]):
            if not any_on and (ON_COMP[ta][tb][sid][di] & du):
                any_on = True
            if not any_off and (OFF_COMP[ta][tb][sid][di] & du):
                any_off = True
            if any_on and any_off:
                break
        return any_on, any_off

    def global_prune(domains):
        possible_adj = [[] for _ in range(vcount)]
        forced_adj = [[] for _ in range(vcount)]
        forced_edge_total = 0

        for v, u, di in undirected_edges:
            on, off = edge_possibilities(domains, v, u, di)
            if not on and not off:
                return False
            if on:
                possible_adj[v].append(u)
                possible_adj[u].append(v)
            if on and not off:
                forced_adj[v].append(u)
                forced_adj[u].append(v)
                forced_edge_total += 1

        must_active = []
        for v in range(vcount):
            if types[v] != TYPE_NONE or not (domains[v] & UNUSED_BIT):
                must_active.append(v)
                if len(possible_adj[v]) < 2:
                    return False

        if must_active:
            start = must_active[0]
            seen = {start}
            stack = [start]
            while stack:
                x = stack.pop()
                for y in possible_adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            for v in must_active:
                if v not in seen:
                    return False

        seen = set()
        cycle_components = []
        for v in range(vcount):
            if v in seen or not forced_adj[v]:
                continue
            comp = []
            stack = [v]
            seen.add(v)
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in forced_adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            ecount = sum(len(forced_adj[x]) for x in comp) // 2
            if ecount == len(comp) and all(len(forced_adj[x]) == 2 for x in comp):
                cycle_components.append(comp)

        if cycle_components:
            if len(cycle_components) > 1:
                return False
            comp = set(cycle_components[0])
            if forced_edge_total != len(comp):
                return False
            for v in range(vcount):
                if v in comp:
                    continue
                if types[v] != TYPE_NONE:
                    return False
                if not (domains[v] & UNUSED_BIT):
                    return False

        return True

    def propagate(domains):
        dom = list(domains)
        changed = True
        while changed:
            changed = False

            # Pairwise edge-consistency propagation.
            for v in range(vcount):
                ta = types[v]
                m = dom[v]
                for u, di in neighdirs[v]:
                    tb = types[u]
                    support = FULL_COMP[ta][tb]
                    du = dom[u]
                    newm = 0
                    for sid, b in _bits(m):
                        if support[sid][di] & du:
                            newm |= b
                    if newm == 0:
                        return None
                    if newm != m:
                        dom[v] = newm
                        m = newm
                        changed = True

            # White-circle propagation:
            # must be straight, and at least one adjacent continuation vertex must turn.
            for v in white_vertices:
                m = dom[v]
                newm = m

                if m & SV_BIT:
                    up = nb[v][U]
                    dn = nb[v][D]
                    upm = dom[up]
                    dnm = dom[dn]
                    if not (
                        (upm & USE_DIR_MASK[D]) and
                        (dnm & USE_DIR_MASK[U]) and
                        ((upm & TURN_USE_DIR_MASK[D]) or (dnm & TURN_USE_DIR_MASK[U]))
                    ):
                        newm &= ~SV_BIT

                if m & SH_BIT:
                    lf = nb[v][L]
                    rt = nb[v][R]
                    lfm = dom[lf]
                    rtm = dom[rt]
                    if not (
                        (lfm & USE_DIR_MASK[R]) and
                        (rtm & USE_DIR_MASK[L]) and
                        ((lfm & TURN_USE_DIR_MASK[R]) or (rtm & TURN_USE_DIR_MASK[L]))
                    ):
                        newm &= ~SH_BIT

                if newm == 0:
                    return None
                if newm != m:
                    dom[v] = newm
                    changed = True

                # If the white orientation is fixed, then if one side cannot turn,
                # the other side is forced to turn.
                m = dom[v]
                if m == SV_BIT:
                    up = nb[v][U]
                    dn = nb[v][D]
                    if not (dom[up] & TURN_USE_DIR_MASK[D]):
                        nd = dom[dn] & TURN_USE_DIR_MASK[U]
                        if nd == 0:
                            return None
                        if nd != dom[dn]:
                            dom[dn] = nd
                            changed = True
                    if not (dom[dn] & TURN_USE_DIR_MASK[U]):
                        nu = dom[up] & TURN_USE_DIR_MASK[D]
                        if nu == 0:
                            return None
                        if nu != dom[up]:
                            dom[up] = nu
                            changed = True

                elif m == SH_BIT:
                    lf = nb[v][L]
                    rt = nb[v][R]
                    if not (dom[lf] & TURN_USE_DIR_MASK[R]):
                        nr = dom[rt] & TURN_USE_DIR_MASK[L]
                        if nr == 0:
                            return None
                        if nr != dom[rt]:
                            dom[rt] = nr
                            changed = True
                    if not (dom[rt] & TURN_USE_DIR_MASK[L]):
                        nl = dom[lf] & TURN_USE_DIR_MASK[R]
                        if nl == 0:
                            return None
                        if nl != dom[lf]:
                            dom[lf] = nl
                            changed = True

            if not global_prune(dom):
                return None

        return tuple(dom)

    def verify_and_build(domains):
        states = [_singleton_sid(m) for m in domains]

        adj = [[] for _ in range(vcount)]
        used_vertices = set()

        for v, u, di in undirected_edges:
            sv = states[v]
            su = states[u]
            v_on = bool(STATE_EDGES[sv] & DIR_BITS[di])
            u_on = bool(STATE_EDGES[su] & DIR_BITS[OPP[di]])
            if v_on != u_on:
                return None
            if v_on:
                adj[v].append(u)
                adj[u].append(v)

        for v in range(vcount):
            sid = states[v]
            deg = len(adj[v])
            if sid == SID_UNUSED:
                if deg != 0:
                    return None
            else:
                if deg != 2:
                    return None
                used_vertices.add(v)

        for v in clue_vertices:
            if states[v] == SID_UNUSED:
                return None

        for v in white_vertices:
            sid = states[v]
            if sid == SID_SV:
                up = nb[v][U]
                dn = nb[v][D]
                if up == -1 or dn == -1:
                    return None
                if up not in adj[v] or dn not in adj[v]:
                    return None
                if not (STATE_TURN[states[up]] or STATE_TURN[states[dn]]):
                    return None
            elif sid == SID_SH:
                lf = nb[v][L]
                rt = nb[v][R]
                if lf == -1 or rt == -1:
                    return None
                if lf not in adj[v] or rt not in adj[v]:
                    return None
                if not (STATE_TURN[states[lf]] or STATE_TURN[states[rt]]):
                    return None
            else:
                return None

        for v in clue_vertices:
            if types[v] != TYPE_BLACK:
                continue
            sid = states[v]
            if sid not in (SID_UL, SID_UR, SID_DL, SID_DR):
                return None
            for di in range(4):
                if STATE_EDGES[sid] & DIR_BITS[di]:
                    u = nb[v][di]
                    if u == -1 or u not in adj[v]:
                        return None
                    if STATE_AXIS[states[u]] != AXIS[di]:
                        return None

        if not used_vertices:
            return None

        start = min(used_vertices)
        path = [rc(start)]
        visited_edges = set()
        prev = -1
        cur = start

        while True:
            nbrs = adj[cur]
            if len(nbrs) != 2:
                return None
            if prev == -1:
                nxt = nbrs[0] if nbrs[0] < nbrs[1] else nbrs[1]
            else:
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]

            e = (cur, nxt) if cur < nxt else (nxt, cur)
            if e in visited_edges and nxt != start:
                return None
            visited_edges.add(e)
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(used_vertices) + 1:
                return None

        if len(visited_edges) != sum(len(adj[v]) for v in range(vcount)) // 2:
            return None

        seen_vertices = set()
        for r, c in path[:-1]:
            seen_vertices.add(vid(r, c))
        if seen_vertices != used_vertices:
            return None

        return path

    dead = set()

    def choose_branch_vertex(domains):
        best_v = None
        best_key = None
        for v in range(vcount):
            cnt = _bitcount(domains[v])
            if cnt <= 1:
                continue
            clue_bias = 0 if types[v] != TYPE_NONE else 1
            neighbor_count = len(neighdirs[v])
            key = (cnt, clue_bias, -neighbor_count, v)
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
        return best_v

    def ordered_states_for_vertex(domains, v):
        tv = types[v]
        scores = []
        for sid, b in _bits(domains[v]):
            score = 0
            for u, di in neighdirs[v]:
                tu = types[u]
                support = FULL_COMP[tv][tu][sid][di] & domains[u]
                score += _bitcount(support)
            # Fewer supports first: stronger guesses first.
            # Tiebreak toward non-unused to keep loop structure advancing.
            prefer_unused_late = 1 if sid == SID_UNUSED else 0
            scores.append((score, prefer_unused_late, sid))
        scores.sort()
        return [sid for _, __, sid in scores]

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if domains in dead:
            return None

        solved = all((m & (m - 1)) == 0 for m in domains)
        if solved:
            path = verify_and_build(domains)
            if path is not None:
                return path
            dead.add(domains)
            return None

        v = choose_branch_vertex(domains)
        if v is None:
            dead.add(domains)
            return None

        for sid in ordered_states_for_vertex(domains, v):
            new_domains = list(domains)
            new_domains[v] = BIT[sid]
            ans = search(tuple(new_domains))
            if ans is not None:
                return ans

        dead.add(domains)
        return None

    result = search(tuple(domains0))
    if result is None:
        return "No Solution"
    return repr(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'tree': [[None, 'T', None, None, None, None], [None, None, 'T', None, None, None], [None, None, None, None, None, 'T'], [None, 'T', None, None, None, None], [None, None, None, 'T', None, None], [None, 'T', None, None, None, 'T']], 'row_tent_counts': [1, 2, 1, 0, 1, 2], 'col_tent_counts': [2, 1, 1, 1, 1, 1]}

# Human-style generalized Tents solver:
# - Build legal tent candidates: empty cells orthogonally adjacent to exactly one tree.
# - Propagate deterministic rules aggressively:
#   * singleton tree domains
#   * row/column lower/upper-bound deductions
#   * no-touch pruning after each forced tent
#   * lightweight failed-literal checks on small domains
# - Use backtracking only after propagation stalls.

def solve(observation):
    tree_grid = observation['tree']
    row_counts = list(observation['row_tent_counts'])
    col_counts = list(observation['col_tent_counts'])

    if not tree_grid or not tree_grid[0]:
        return "No Solution"

    R = len(tree_grid)
    C = len(tree_grid[0])

    trees = []
    tree_set = set()
    for r in range(R):
        if len(tree_grid[r]) != C:
            return "No Solution"
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))
                tree_set.add((r, c))

    T = len(trees)
    if sum(row_counts) != T or sum(col_counts) != T:
        return "No Solution"

    tree_index = {pos: i for i, pos in enumerate(trees)}
    orth = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Candidate cells must be adjacent to exactly one tree.
    tree_to_cells = [[] for _ in range(T)]
    for r in range(R):
        for c in range(C):
            if (r, c) in tree_set:
                continue
            adj = []
            for dr, dc in orth:
                rr, cc = r + dr, c + dc
                if 0 <= rr < R and 0 <= cc < C and (rr, cc) in tree_set:
                    adj.append(tree_index[(rr, cc)])
            if len(adj) == 1:
                tree_to_cells[adj[0]].append((r, c))

    for t in range(T):
        if not tree_to_cells[t]:
            return "No Solution"

    cand_cells = []
    cand_tree = []
    cand_row = []
    cand_col = []
    initial_domains = [0] * T

    for t in range(T):
        for r, c in tree_to_cells[t]:
            idx = len(cand_cells)
            cand_cells.append((r, c))
            cand_tree.append(t)
            cand_row.append(r)
            cand_col.append(c)
            initial_domains[t] |= (1 << idx)

    M = len(cand_cells)

    row_mask = [0] * R
    col_mask = [0] * C
    for i in range(M):
        row_mask[cand_row[i]] |= (1 << i)
        col_mask[cand_col[i]] |= (1 << i)

    conflict_mask = [0] * M
    for i in range(M):
        r1, c1 = cand_cells[i]
        mask = 0
        for j in range(M):
            r2, c2 = cand_cells[j]
            if max(abs(r1 - r2), abs(c1 - c2)) <= 1:
                mask |= (1 << j)
        conflict_mask[i] = mask

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def is_singleton(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def do_assign(domains, assignments, row_rem, col_rem, t, cand):
        if assignments[t] != -1:
            return assignments[t] == cand

        r = cand_row[cand]
        c = cand_col[cand]
        row_rem[r] -= 1
        col_rem[c] -= 1
        if row_rem[r] < 0 or col_rem[c] < 0:
            return False

        assignments[t] = cand
        domains[t] = 0

        ban = conflict_mask[cand]
        for tt in range(T):
            if assignments[tt] == -1:
                new_mask = domains[tt] & ~ban
                if new_mask != domains[tt]:
                    domains[tt] = new_mask
                    if new_mask == 0:
                        return False
        return True

    def propagate(domains_in, assignments_in, row_rem_in, col_rem_in, allow_lookahead=True):
        domains = list(domains_in)
        assignments = list(assignments_in)
        row_rem = list(row_rem_in)
        col_rem = list(col_rem_in)

        while True:
            progress = False

            unassigned = 0
            for t in range(T):
                if assignments[t] == -1:
                    if domains[t] == 0:
                        return None
                    unassigned += 1
            if sum(row_rem) != unassigned or sum(col_rem) != unassigned:
                return None

            # Force singleton tree domains.
            changed = True
            while changed:
                changed = False
                for t in range(T):
                    if assignments[t] == -1 and is_singleton(domains[t]):
                        cand = domains[t].bit_length() - 1
                        if not do_assign(domains, assignments, row_rem, col_rem, t, cand):
                            return None
                        progress = True
                        changed = True

            # Re-check totals after any forced assignments.
            unassigned = 0
            for t in range(T):
                if assignments[t] == -1:
                    if domains[t] == 0:
                        return None
                    unassigned += 1
            if sum(row_rem) != unassigned or sum(col_rem) != unassigned:
                return None

            # Row deductions using lower/upper bounds:
            # lower = trees forced into row, upper = trees able to go into row.
            for r in range(R):
                rem = row_rem[r]
                if rem < 0:
                    return None
                lower = 0
                upper = 0
                touched = []
                rmask = row_mask[r]
                for t in range(T):
                    if assignments[t] != -1:
                        continue
                    dm = domains[t]
                    in_row = dm & rmask
                    if in_row:
                        upper += 1
                        if in_row == dm:
                            lower += 1
                        touched.append((t, in_row, dm))
                if lower > rem or upper < rem:
                    return None

                # If row quota already fully accounted for by forced-in-row trees,
                # every optional row candidate must be removed.
                if rem == 0 or lower == rem:
                    for t, in_row, dm in touched:
                        if in_row != dm:
                            new_dm = dm & ~in_row
                            if new_dm == 0:
                                return None
                            if new_dm != dm:
                                domains[t] = new_dm
                                progress = True

                # If every possible contributor is needed, force those trees into this row.
                elif upper == rem:
                    for t, in_row, dm in touched:
                        if in_row != dm:
                            if in_row == 0:
                                return None
                            domains[t] = in_row
                            progress = True

            # Column deductions.
            for c in range(C):
                rem = col_rem[c]
                if rem < 0:
                    return None
                lower = 0
                upper = 0
                touched = []
                cmask = col_mask[c]
                for t in range(T):
                    if assignments[t] != -1:
                        continue
                    dm = domains[t]
                    in_col = dm & cmask
                    if in_col:
                        upper += 1
                        if in_col == dm:
                            lower += 1
                        touched.append((t, in_col, dm))
                if lower > rem or upper < rem:
                    return None

                if rem == 0 or lower == rem:
                    for t, in_col, dm in touched:
                        if in_col != dm:
                            new_dm = dm & ~in_col
                            if new_dm == 0:
                                return None
                            if new_dm != dm:
                                domains[t] = new_dm
                                progress = True

                elif upper == rem:
                    for t, in_col, dm in touched:
                        if in_col != dm:
                            if in_col == 0:
                                return None
                            domains[t] = in_col
                            progress = True

            if progress:
                continue

            # Lightweight failed-literal pruning:
            # if choosing a candidate instantly contradicts constraints, delete it now.
            if allow_lookahead:
                unresolved = [t for t in range(T) if assignments[t] == -1]
                small_limit = 2 if len(unresolved) > 10 else 3
                pruned = False

                for t in unresolved:
                    dm = domains[t]
                    k = dm.bit_count()
                    if 1 < k <= small_limit:
                        bad = 0
                        for cand in iter_bits(dm):
                            nd = list(domains)
                            na = list(assignments)
                            nr = list(row_rem)
                            nc = list(col_rem)
                            nd[t] = 1 << cand
                            if propagate(tuple(nd), tuple(na), tuple(nr), tuple(nc), allow_lookahead=False) is None:
                                bad |= (1 << cand)
                        if bad:
                            new_dm = dm & ~bad
                            if new_dm == 0:
                                return None
                            domains[t] = new_dm
                            pruned = True
                            break

                if pruned:
                    continue

            return (tuple(domains), tuple(assignments), tuple(row_rem), tuple(col_rem))

    failed = set()

    def search(domains, assignments, row_rem, col_rem):
        state = propagate(domains, assignments, row_rem, col_rem, allow_lookahead=True)
        if state is None:
            return None

        domains, assignments, row_rem, col_rem = state
        key = (domains, row_rem, col_rem)
        if key in failed:
            return None

        if all(a != -1 for a in assignments):
            if all(x == 0 for x in row_rem) and all(x == 0 for x in col_rem):
                return assignments
            failed.add(key)
            return None

        # Choose the most constrained tree.
        row_upper = [0] * R
        col_upper = [0] * C
        for t in range(T):
            if assignments[t] != -1:
                continue
            dm = domains[t]
            seen_rows = set()
            seen_cols = set()
            for cand in iter_bits(dm):
                seen_rows.add(cand_row[cand])
                seen_cols.add(cand_col[cand])
            for r in seen_rows:
                row_upper[r] += 1
            for c in seen_cols:
                col_upper[c] += 1

        best_t = -1
        best_key = None
        for t in range(T):
            if assignments[t] != -1:
                continue
            k = domains[t].bit_count()
            if k <= 1:
                continue
            impact = 0
            for cand in iter_bits(domains[t]):
                impact += conflict_mask[cand].bit_count()
            key2 = (k, -impact)
            if best_key is None or key2 < best_key:
                best_key = key2
                best_t = t

        if best_t == -1:
            failed.add(key)
            return None

        options = list(iter_bits(domains[best_t]))

        def option_score(cand):
            r = cand_row[cand]
            c = cand_col[cand]
            row_slack = row_upper[r] - row_rem[r]
            col_slack = col_upper[c] - col_rem[c]
            return (row_slack + col_slack, row_slack, col_slack, -conflict_mask[cand].bit_count())

        options.sort(key=option_score)

        for cand in options:
            nd = list(domains)
            na = list(assignments)
            nr = list(row_rem)
            nc = list(col_rem)
            nd[best_t] = 1 << cand
            result = search(tuple(nd), tuple(na), tuple(nr), tuple(nc))
            if result is not None:
                return result

        failed.add(key)
        return None

    assignments = search(tuple(initial_domains), tuple([-1] * T), tuple(row_counts), tuple(col_counts))
    if assignments is None:
        return "No Solution"

    answer = [[None for _ in range(C)] for _ in range(R)]
    for cand in assignments:
        if cand != -1:
            r, c = cand_cells[cand]
            answer[r][c] = 't'
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

