# Domino-shading region puzzle solver.
# Rules:
# - Each region contains exactly 2 shaded cells.
# - Every shaded cell belongs to a domino (2 orthogonally adjacent shaded cells).
# - Different dominoes cannot touch orthogonally.
# - Dominoes may cross region borders.
#
# Strategy:
# 1) Generate every possible domino placement.
# 2) Precompute conflicts between dominoes (share/touch).
# 3) For each region, precompute all local ways to realize exactly 2 shaded cells:
#    - one domino contributing 2 cells to the region
#    - or two non-conflicting dominoes each contributing 1 cell
# 4) Propagate region-option constraints aggressively.
# 5) Search only on region options, not on individual cells.

from collections import defaultdict

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    cell_count = n * n

    def cid(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    # Regions
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            region_cells[data[r][c]].append(cid(r, c))
    region_ids = sorted(region_cells)
    rid_to_idx = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    region_of = [0] * cell_count
    for rid, cells in region_cells.items():
        idx = rid_to_idx[rid]
        for x in cells:
            region_of[x] = idx

    # Generate all dominoes (adjacent cell pairs)
    dominos = []
    domino_cells = []
    domino_regions = []
    contrib = []  # sparse dict: region_idx -> 1 or 2
    cell_to_dominos = [[] for _ in range(cell_count)]

    for r in range(n):
        for c in range(n):
            a = cid(r, c)
            if c + 1 < n:
                b = cid(r, c + 1)
                d = len(dominos)
                dominos.append((a, b))
                domino_cells.append((a, b))
                ra, rb = region_of[a], region_of[b]
                if ra == rb:
                    cr = {ra: 2}
                    regs = (ra,)
                else:
                    cr = {ra: 1, rb: 1}
                    regs = (ra, rb)
                domino_regions.append(regs)
                contrib.append(cr)
                cell_to_dominos[a].append(d)
                cell_to_dominos[b].append(d)
            if r + 1 < n:
                b = cid(r + 1, c)
                d = len(dominos)
                dominos.append((a, b))
                domino_cells.append((a, b))
                ra, rb = region_of[a], region_of[b]
                if ra == rb:
                    cr = {ra: 2}
                    regs = (ra,)
                else:
                    cr = {ra: 1, rb: 1}
                    regs = (ra, rb)
                domino_regions.append(regs)
                contrib.append(cr)
                cell_to_dominos[a].append(d)
                cell_to_dominos[b].append(d)

    D = len(dominos)

    # Orthogonal neighbors for conflict checks
    neighbors = [[] for _ in range(cell_count)]
    for r in range(n):
        for c in range(n):
            x = cid(r, c)
            if r > 0:
                neighbors[x].append(cid(r - 1, c))
            if r + 1 < n:
                neighbors[x].append(cid(r + 1, c))
            if c > 0:
                neighbors[x].append(cid(r, c - 1))
            if c + 1 < n:
                neighbors[x].append(cid(r, c + 1))

    # Conflict masks between dominoes:
    # - share a cell
    # - or any cell of one is orthogonally adjacent to any cell of the other
    conflict_masks = [0] * D
    domino_cell_sets = [set(pair) for pair in domino_cells]
    touch_zone = []
    for a, b in domino_cells:
        z = {a, b}
        z.update(neighbors[a])
        z.update(neighbors[b])
        touch_zone.append(z)

    for i in range(D):
        ai, bi = domino_cells[i]
        set_i = domino_cell_sets[i]
        zone_i = touch_zone[i]
        mask = 0
        for j in range(D):
            if i == j:
                continue
            aj, bj = domino_cells[j]
            set_j = domino_cell_sets[j]
            if set_i & set_j:
                mask |= 1 << j
                continue
            if aj in zone_i or bj in zone_i:
                mask |= 1 << j
        conflict_masks[i] = mask

    # Per-region domino contributors
    region_dominos = [[] for _ in range(R)]
    region_contributor_mask = [0] * R
    region_domino_contrib = [dict() for _ in range(R)]
    for d in range(D):
        for r_idx, cnt in contrib[d].items():
            region_dominos[r_idx].append(d)
            region_contributor_mask[r_idx] |= 1 << d
            region_domino_contrib[r_idx][d] = cnt

    # Precompute region options:
    # exactly two shaded cells in region via:
    # - one domino contributing 2
    # - two non-conflicting dominoes contributing 1 each
    region_options = []
    for r_idx in range(R):
        opts = set()
        one_list = []
        for d in region_dominos[r_idx]:
            cnt = region_domino_contrib[r_idx][d]
            if cnt == 2:
                opts.add(1 << d)
            else:
                one_list.append(d)
        m = len(one_list)
        for i in range(m):
            d1 = one_list[i]
            for j in range(i + 1, m):
                d2 = one_list[j]
                if (conflict_masks[d1] >> d2) & 1:
                    continue
                opts.add((1 << d1) | (1 << d2))
        opt_list = sorted(opts, key=lambda x: (x.bit_count(), x))
        if not opt_list:
            return "No Solution"
        region_options.append(opt_list)

    full_region_masks = [(1 << len(region_options[r])) - 1 for r in range(R)]

    # Helper bit iteration
    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    # Propagation on (selected dominos, forbidden dominos, per-region feasible option masks)
    def propagate(sel_mask, forb_mask, reg_masks):
        reg_masks = list(reg_masks)

        while True:
            changed = False

            if sel_mask & forb_mask:
                return None

            # Selected dominoes force all conflicting dominoes forbidden
            combined_conf = 0
            for d in iter_bits(sel_mask):
                combined_conf |= conflict_masks[d]
            new_forb = forb_mask | combined_conf
            if new_forb != forb_mask:
                forb_mask = new_forb
                if sel_mask & forb_mask:
                    return None
                changed = True

            # Region-by-region filtering
            for r_idx in range(R):
                opts = region_options[r_idx]
                old_mask = reg_masks[r_idx]
                selected_contributors = sel_mask & region_contributor_mask[r_idx]

                new_mask = 0
                union_dom = 0
                common_dom = None

                for oi in iter_bits(old_mask):
                    om = opts[oi]
                    if om & forb_mask:
                        continue
                    if selected_contributors & ~om:
                        continue
                    new_mask |= 1 << oi
                    union_dom |= om
                    common_dom = om if common_dom is None else (common_dom & om)

                if new_mask == 0:
                    return None

                if new_mask != old_mask:
                    reg_masks[r_idx] = new_mask
                    changed = True

                # Dominoes appearing in every remaining option are forced selected
                if common_dom is None:
                    return None
                forced_sel = common_dom & ~sel_mask
                if forced_sel:
                    sel_mask |= forced_sel
                    changed = True

                # Dominoes touching this region but absent from all remaining options
                # can never be used, otherwise region would exceed its quota.
                forced_forb = region_contributor_mask[r_idx] & ~union_dom & ~forb_mask
                if forced_forb:
                    forb_mask |= forced_forb
                    changed = True

                # If exactly one option remains, it fully decides the region
                if new_mask & (new_mask - 1) == 0:
                    only_idx = (new_mask & -new_mask).bit_length() - 1
                    only_dom = opts[only_idx]
                    add_sel = only_dom & ~sel_mask
                    add_forb = region_contributor_mask[r_idx] & ~only_dom & ~forb_mask
                    if add_sel:
                        sel_mask |= add_sel
                        changed = True
                    if add_forb:
                        forb_mask |= add_forb
                        changed = True

            if not changed:
                break

        # Final quick consistency check
        if sel_mask & forb_mask:
            return None
        return sel_mask, forb_mask, tuple(reg_masks)

    # Check completed state and build answer
    def validate_and_format(sel_mask):
        shaded = [False] * cell_count
        used_regions = [0] * R
        selected_dom_list = list(iter_bits(sel_mask))

        # Dominoes pairwise non-conflicting
        for i, d1 in enumerate(selected_dom_list):
            for d2 in selected_dom_list[i + 1:]:
                if (conflict_masks[d1] >> d2) & 1:
                    return None

        for d in selected_dom_list:
            a, b = domino_cells[d]
            if shaded[a] or shaded[b]:
                return None
            shaded[a] = True
            shaded[b] = True

        for x in range(cell_count):
            if shaded[x]:
                used_regions[region_of[x]] += 1

        if any(v != 2 for v in used_regions):
            return None

        out = [[None for _ in range(n)] for _ in range(n)]
        for x in range(cell_count):
            if shaded[x]:
                r, c = rc(x)
                out[r][c] = 'S'
        return out

    # DFS with memoization
    seen = set()

    def search(state):
        if state is None:
            return None
        sel_mask, forb_mask, reg_masks = state

        key = (sel_mask, forb_mask, reg_masks)
        if key in seen:
            return None
        seen.add(key)

        # If every region has a single option, we should have a complete solution
        done = True
        for m in reg_masks:
            if m & (m - 1):
                done = False
                break
        if done:
            grid = validate_and_format(sel_mask)
            if grid is not None:
                return grid
            return None

        # Choose the most constrained region
        best_r = None
        best_count = None
        for r_idx, mask in enumerate(reg_masks):
            cnt = mask.bit_count()
            if cnt > 1 and (best_count is None or cnt < best_count):
                best_count = cnt
                best_r = r_idx

        opts = region_options[best_r]
        mask = reg_masks[best_r]

        # Mild heuristic: try options with more already-selected dominos first,
        # then smaller option size.
        cand = []
        for oi in iter_bits(mask):
            om = opts[oi]
            cand.append((
                -(om & sel_mask).bit_count(),
                om.bit_count(),
                oi,
                om
            ))
        cand.sort()

        for _, _, oi, om in cand:
            new_reg_masks = list(reg_masks)
            new_reg_masks[best_r] = 1 << oi
            nxt = propagate(sel_mask, forb_mask, new_reg_masks)
            ans = search(nxt)
            if ans is not None:
                return ans

        return None

    initial = propagate(0, 0, full_region_masks)
    result = search(initial)
    if result is None:
        return "No Solution"
    return repr(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))

