# General solver for the described single-loop puzzle on dot grids.
# It uses:
# - vertex-state domains (none / straight / turn),
# - clue candidate generation from segment-length interpretations,
# - aggressive propagation (edge-consistency + clue-candidate filtering),
# - controlled backtracking,
# - final exact verification of the loop and clue arithmetic.

from collections import defaultdict, deque

# Direction indexing
U, R, D, L = 0, 1, 2, 3
DIR_BITS = [1, 2, 4, 8]
OPP = [D, L, U, R]
DR = [-1, 0, 1, 0]
DC = [0, 1, 0, -1]

# Vertex local states as incident-edge bitmasks
# 0: none, 10: H, 5: V, 9: UL, 3: UR, 12: DL, 6: DR
STATE_MASKS = [0, 10, 5, 9, 3, 12, 6]
MASK_TO_STATE = {m: i for i, m in enumerate(STATE_MASKS)}
STATE_BITS = [1 << i for i in range(len(STATE_MASKS))]
ALL_DOMAIN = (1 << len(STATE_MASKS)) - 1

DOM_NONE = STATE_BITS[MASK_TO_STATE[0]]
DOM_H = STATE_BITS[MASK_TO_STATE[10]]
DOM_V = STATE_BITS[MASK_TO_STATE[5]]
DOM_UL = STATE_BITS[MASK_TO_STATE[9]]
DOM_UR = STATE_BITS[MASK_TO_STATE[3]]
DOM_DL = STATE_BITS[MASK_TO_STATE[12]]
DOM_DR = STATE_BITS[MASK_TO_STATE[6]]

DOM_WHITE = DOM_H | DOM_V
DOM_BLACK = DOM_UL | DOM_UR | DOM_DL | DOM_DR
DOM_TURN_WITH_U = DOM_UL | DOM_UR
DOM_TURN_WITH_R = DOM_UR | DOM_DR
DOM_TURN_WITH_D = DOM_DL | DOM_DR
DOM_TURN_WITH_L = DOM_UL | DOM_DL

# Precompute support/filter tables for domain propagation
CAN_ON = [[False] * 4 for _ in range(ALL_DOMAIN + 1)]
CAN_OFF = [[False] * 4 for _ in range(ALL_DOMAIN + 1)]
ALL_ON = [[False] * 4 for _ in range(ALL_DOMAIN + 1)]
FILTER = [[[[0 for _ in range(2)] for _ in range(2)] for _ in range(4)] for _ in range(ALL_DOMAIN + 1)]

for dom in range(ALL_DOMAIN + 1):
    if dom == 0:
        continue
    for di in range(4):
        any_on = False
        any_off = False
        all_on = True
        for si, sm in enumerate(STATE_MASKS):
            if dom & STATE_BITS[si]:
                if sm & DIR_BITS[di]:
                    any_on = True
                else:
                    any_off = True
                    all_on = False
        CAN_ON[dom][di] = any_on
        CAN_OFF[dom][di] = any_off
        ALL_ON[dom][di] = all_on

for dom in range(ALL_DOMAIN + 1):
    for di in range(4):
        for neigh_can_on in (0, 1):
            for neigh_can_off in (0, 1):
                nd = 0
                for si, sm in enumerate(STATE_MASKS):
                    bit = STATE_BITS[si]
                    if not (dom & bit):
                        continue
                    uses = 1 if (sm & DIR_BITS[di]) else 0
                    if uses:
                        if neigh_can_on:
                            nd |= bit
                    else:
                        if neigh_can_off:
                            nd |= bit
                FILTER[dom][di][neigh_can_on][neigh_can_off] = nd


def solve(observation):
    data = observation.get("data")
    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    n = len(data) - 1
    side = n + 1
    vcount = side * side

    def vid(r, c):
        return r * side + c

    def rc(v):
        return divmod(v, side)

    def add_restr(d, v, mask_bits):
        old = d.get(v)
        if old is None:
            d[v] = mask_bits
            return mask_bits != 0
        new = old & mask_bits
        if new == 0:
            return False
        d[v] = new
        return True

    # Initial domains per vertex
    domains0 = [ALL_DOMAIN] * vcount
    clue_positions = []
    clue_at_vertex = {}

    for r in range(side):
        for c in range(side):
            v = vid(r, c)
            tok = data[r][c]
            if tok is None:
                dom = ALL_DOMAIN
            elif tok[0] == "W":
                dom = DOM_WHITE
                clue_positions.append((r, c, tok))
                clue_at_vertex[v] = tok
            elif tok[0] == "B":
                dom = DOM_BLACK
                clue_positions.append((r, c, tok))
                clue_at_vertex[v] = tok
            else:
                return "No Solution"

            # Boundary trimming
            trimmed = 0
            for si, sm in enumerate(STATE_MASKS):
                bit = STATE_BITS[si]
                if not (dom & bit):
                    continue
                ok = True
                if r == 0 and (sm & DIR_BITS[U]):
                    ok = False
                if r == n and (sm & DIR_BITS[D]):
                    ok = False
                if c == 0 and (sm & DIR_BITS[L]):
                    ok = False
                if c == n and (sm & DIR_BITS[R]):
                    ok = False
                if ok:
                    trimmed |= bit
            domains0[v] = trimmed
            if domains0[v] == 0:
                return "No Solution"

    # Enumerate clue candidates
    candidates = []
    clue_vertices = []

    def build_white_candidates(r, c, k):
        out = []

        # Horizontal
        for a in range(1, k):
            b = k - a
            if a <= c and b <= (n - c):
                d = {}
                if not add_restr(d, vid(r, c), DOM_H):
                    continue
                ok = True
                for x in range(1, a):
                    if not add_restr(d, vid(r, c - x), DOM_H):
                        ok = False
                        break
                if ok and not add_restr(d, vid(r, c - a), DOM_TURN_WITH_R):
                    ok = False
                if ok:
                    for x in range(1, b):
                        if not add_restr(d, vid(r, c + x), DOM_H):
                            ok = False
                            break
                if ok and not add_restr(d, vid(r, c + b), DOM_TURN_WITH_L):
                    ok = False
                if ok:
                    out.append(d)

        # Vertical
        for a in range(1, k):
            b = k - a
            if a <= r and b <= (n - r):
                d = {}
                if not add_restr(d, vid(r, c), DOM_V):
                    continue
                ok = True
                for x in range(1, a):
                    if not add_restr(d, vid(r - x, c), DOM_V):
                        ok = False
                        break
                if ok and not add_restr(d, vid(r - a, c), DOM_TURN_WITH_D):
                    ok = False
                if ok:
                    for x in range(1, b):
                        if not add_restr(d, vid(r + x, c), DOM_V):
                            ok = False
                            break
                if ok and not add_restr(d, vid(r + b, c), DOM_TURN_WITH_U):
                    ok = False
                if ok:
                    out.append(d)

        return out

    def build_black_candidates(r, c, k):
        out = []

        # UR
        for a in range(1, k):
            b = k - a
            if a <= r and b <= (n - c):
                d = {}
                ok = add_restr(d, vid(r, c), DOM_UR)
                for x in range(1, a):
                    if ok and not add_restr(d, vid(r - x, c), DOM_V):
                        ok = False
                if ok and not add_restr(d, vid(r - a, c), DOM_TURN_WITH_D):
                    ok = False
                for x in range(1, b):
                    if ok and not add_restr(d, vid(r, c + x), DOM_H):
                        ok = False
                if ok and not add_restr(d, vid(r, c + b), DOM_TURN_WITH_L):
                    ok = False
                if ok:
                    out.append(d)

        # UL
        for a in range(1, k):
            b = k - a
            if a <= r and b <= c:
                d = {}
                ok = add_restr(d, vid(r, c), DOM_UL)
                for x in range(1, a):
                    if ok and not add_restr(d, vid(r - x, c), DOM_V):
                        ok = False
                if ok and not add_restr(d, vid(r - a, c), DOM_TURN_WITH_D):
                    ok = False
                for x in range(1, b):
                    if ok and not add_restr(d, vid(r, c - x), DOM_H):
                        ok = False
                if ok and not add_restr(d, vid(r, c - b), DOM_TURN_WITH_R):
                    ok = False
                if ok:
                    out.append(d)

        # DR
        for a in range(1, k):
            b = k - a
            if a <= (n - r) and b <= (n - c):
                d = {}
                ok = add_restr(d, vid(r, c), DOM_DR)
                for x in range(1, a):
                    if ok and not add_restr(d, vid(r + x, c), DOM_V):
                        ok = False
                if ok and not add_restr(d, vid(r + a, c), DOM_TURN_WITH_U):
                    ok = False
                for x in range(1, b):
                    if ok and not add_restr(d, vid(r, c + x), DOM_H):
                        ok = False
                if ok and not add_restr(d, vid(r, c + b), DOM_TURN_WITH_L):
                    ok = False
                if ok:
                    out.append(d)

        # DL
        for a in range(1, k):
            b = k - a
            if a <= (n - r) and b <= c:
                d = {}
                ok = add_restr(d, vid(r, c), DOM_DL)
                for x in range(1, a):
                    if ok and not add_restr(d, vid(r + x, c), DOM_V):
                        ok = False
                if ok and not add_restr(d, vid(r + a, c), DOM_TURN_WITH_U):
                    ok = False
                for x in range(1, b):
                    if ok and not add_restr(d, vid(r, c - x), DOM_H):
                        ok = False
                if ok and not add_restr(d, vid(r, c - b), DOM_TURN_WITH_R):
                    ok = False
                if ok:
                    out.append(d)

        return out

    for r, c, tok in clue_positions:
        k = int(tok[1:])
        if tok[0] == "W":
            clist = build_white_candidates(r, c, k)
        else:
            clist = build_black_candidates(r, c, k)

        # Remove duplicate candidates structurally
        uniq = []
        seen = set()
        for cand in clist:
            key = tuple(sorted(cand.items()))
            if key not in seen:
                seen.add(key)
                uniq.append(cand)
        clist = uniq

        if not clist:
            return "No Solution"

        candidates.append(clist)
        clue_vertices.append(vid(r, c))

    rem0 = [list(range(len(clist))) for clist in candidates]

    # Fast edge list for propagation
    edge_pairs = []
    for r in range(side):
        for c in range(side):
            v = vid(r, c)
            if r < n:
                edge_pairs.append((v, vid(r + 1, c), D, U))
            if c < n:
                edge_pairs.append((v, vid(r, c + 1), R, L))

    def propagate(domains, rem):
        while True:
            changed = False

            # Edge consistency
            for v, u, dvu, duv in edge_pairs:
                dv = domains[v]
                du = domains[u]

                ndv = FILTER[dv][dvu][1 if CAN_ON[du][duv] else 0][1 if CAN_OFF[du][duv] else 0]
                if ndv == 0:
                    return False
                if ndv != dv:
                    domains[v] = ndv
                    dv = ndv
                    changed = True

                ndu = FILTER[du][duv][1 if CAN_ON[dv][dvu] else 0][1 if CAN_OFF[dv][dvu] else 0]
                if ndu == 0:
                    return False
                if ndu != du:
                    domains[u] = ndu
                    changed = True

            # Clue candidate filtering + mandatory intersections
            for i, cands in enumerate(candidates):
                alive = []
                for ci in rem[i]:
                    cand = cands[ci]
                    ok = True
                    for v, mask_bits in cand.items():
                        if domains[v] & mask_bits == 0:
                            ok = False
                            break
                    if ok:
                        alive.append(ci)

                if not alive:
                    return False
                if len(alive) != len(rem[i]):
                    rem[i] = alive
                    changed = True

                total = len(alive)
                counts = {}
                unions = {}
                for ci in alive:
                    cand = cands[ci]
                    for v, mask_bits in cand.items():
                        counts[v] = counts.get(v, 0) + 1
                        unions[v] = unions.get(v, 0) | mask_bits

                for v, cnt in counts.items():
                    if cnt == total:
                        nd = domains[v] & unions[v]
                        if nd == 0:
                            return False
                        if nd != domains[v]:
                            domains[v] = nd
                            changed = True

            # Forced closed-cycle pruning
            if detect_bad_forced_cycle(domains, n, side, vid):
                return False

            if not changed:
                return True

    def detect_bad_forced_cycle(domains, n, side, vid_func):
        adj = defaultdict(list)
        active = set()

        for r in range(side):
            for c in range(side):
                v = vid_func(r, c)
                if c < n:
                    u = vid_func(r, c + 1)
                    if ALL_ON[domains[v]][R] and ALL_ON[domains[u]][L]:
                        adj[v].append(u)
                        adj[u].append(v)
                        active.add(v)
                        active.add(u)
                if r < n:
                    u = vid_func(r + 1, c)
                    if ALL_ON[domains[v]][D] and ALL_ON[domains[u]][U]:
                        adj[v].append(u)
                        adj[u].append(v)
                        active.add(v)
                        active.add(u)

        seen = set()
        for s in list(active):
            if s in seen:
                continue
            comp = []
            stack = [s]
            seen.add(s)
            ok_cycle = True
            while stack:
                x = stack.pop()
                comp.append(x)
                if len(adj[x]) != 2:
                    ok_cycle = False
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)

            if ok_cycle:
                comp_set = set(comp)
                for v in range(len(domains)):
                    if v not in comp_set and (domains[v] & DOM_NONE) == 0:
                        return True
        return False

    def choose_branch(domains, rem):
        best = None

        # Prefer clue-candidate branching
        for i, alive in enumerate(rem):
            if len(alive) > 1:
                score = len(alive)
                impact = -sum(len(candidates[i][ci]) for ci in alive)
                key = (0, score, impact, i)
                if best is None or key < best[0]:
                    best = (key, ("clue", i, alive))
        if best is not None:
            return best[1]

        # Then branch on tightest vertex domain
        for v, dom in enumerate(domains):
            bc = dom.bit_count()
            if bc > 1:
                must_on = 0 if (dom & DOM_NONE) == 0 else 1
                key = (1, must_on, bc, v)
                if best is None or key < best[0]:
                    best = (key, ("vertex", v, dom))
        return None if best is None else best[1]

    def final_verify_and_extract(domains):
        # All singleton?
        chosen_state_idx = []
        for dom in domains:
            if dom == 0 or (dom & (dom - 1)) != 0:
                return None
            chosen_state_idx.append(dom.bit_length() - 1)

        masks = [STATE_MASKS[i] for i in chosen_state_idx]

        # Edge consistency and adjacency
        adj = [[] for _ in range(vcount)]
        active_vertices = []

        for r in range(side):
            for c in range(side):
                v = vid(r, c)
                sm = masks[v]

                # Boundary check
                if r == 0 and (sm & DIR_BITS[U]):
                    return None
                if r == n and (sm & DIR_BITS[D]):
                    return None
                if c == 0 and (sm & DIR_BITS[L]):
                    return None
                if c == n and (sm & DIR_BITS[R]):
                    return None

                deg = 0
                for di in range(4):
                    if sm & DIR_BITS[di]:
                        nr, nc = r + DR[di], c + DC[di]
                        if not (0 <= nr <= n and 0 <= nc <= n):
                            return None
                        u = vid(nr, nc)
                        if not (masks[u] & DIR_BITS[OPP[di]]):
                            return None
                        deg += 1
                if deg not in (0, 2):
                    return None
                if deg == 2:
                    active_vertices.append(v)

        # Build adjacency without duplicates
        for r in range(side):
            for c in range(side):
                v = vid(r, c)
                if c < n and (masks[v] & DIR_BITS[R]):
                    u = vid(r, c + 1)
                    if masks[u] & DIR_BITS[L]:
                        adj[v].append(u)
                        adj[u].append(v)
                if r < n and (masks[v] & DIR_BITS[D]):
                    u = vid(r + 1, c)
                    if masks[u] & DIR_BITS[U]:
                        adj[v].append(u)
                        adj[u].append(v)

        if not active_vertices:
            return None

        # Single cycle check
        start = min(active_vertices)
        q = [start]
        seen = {start}
        while q:
            x = q.pop()
            if len(adj[x]) != 2:
                return None
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    q.append(y)
        if len(seen) != len(active_vertices):
            return None

        # Exact clue arithmetic
        for r, c, tok in clue_positions:
            v = vid(r, c)
            sm = masks[v]
            k = int(tok[1:])

            if tok[0] == "W":
                if sm not in (10, 5):
                    return None
            else:
                if sm not in (9, 3, 12, 6):
                    return None

            dirs = [di for di in range(4) if sm & DIR_BITS[di]]
            if len(dirs) != 2:
                return None

            total = 0
            for di in dirs:
                length = 1
                cr, cc = r + DR[di], c + DC[di]
                while True:
                    if not (0 <= cr <= n and 0 <= cc <= n):
                        return None
                    cm = masks[vid(cr, cc)]
                    if cm == 0:
                        return None
                    if not (cm & DIR_BITS[OPP[di]]):
                        return None

                    if di in (L, R) and cm == 10:
                        cr += DR[di]
                        cc += DC[di]
                        length += 1
                        continue
                    if di in (U, D) and cm == 5:
                        cr += DR[di]
                        cc += DC[di]
                        length += 1
                        continue
                    break
                total += length

            if total != k:
                return None

        # Extract ordered loop path
        nbrs0 = sorted(adj[start])
        prev = None
        cur = start
        nxt = nbrs0[0]
        path = [rc(start)]

        while True:
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break
            a, b = adj[cur]
            nxt = b if a == prev else a

        return path

    # Initial propagation
    domains = domains0[:]
    rem = [lst[:] for lst in rem0]
    if not propagate(domains, rem):
        return "No Solution"

    # DFS
    def dfs(domains, rem):
        answer = final_verify_and_extract(domains)
        if answer is not None:
            return answer

        branch = choose_branch(domains, rem)
        if branch is None:
            return None

        kind = branch[0]

        if kind == "clue":
            i = branch[1]
            alive = branch[2]
            order = sorted(alive, key=lambda ci: -len(candidates[i][ci]))
            for ci in order:
                ndom = domains[:]
                nrem = [lst[:] for lst in rem]
                nrem[i] = [ci]
                cand = candidates[i][ci]
                ok = True
                for v, mask_bits in cand.items():
                    nd = ndom[v] & mask_bits
                    if nd == 0:
                        ok = False
                        break
                    ndom[v] = nd
                if not ok:
                    continue
                if propagate(ndom, nrem):
                    res = dfs(ndom, nrem)
                    if res is not None:
                        return res
            return None

        # Vertex branching
        v = branch[1]
        dom = branch[2]
        bits = [STATE_BITS[i] for i in range(len(STATE_MASKS)) if dom & STATE_BITS[i]]

        def state_order_key(bit):
            idx = bit.bit_length() - 1
            mask = STATE_MASKS[idx]
            is_none = 1 if mask == 0 else 0
            # Prefer non-none, then higher-degree/turn-ish states first
            degree = ((mask & 1) > 0) + ((mask & 2) > 0) + ((mask & 4) > 0) + ((mask & 8) > 0)
            return (is_none, -degree, idx)

        bits.sort(key=state_order_key)

        for bit in bits:
            ndom = domains[:]
            nrem = [lst[:] for lst in rem]
            ndom[v] = bit
            if propagate(ndom, nrem):
                res = dfs(ndom, nrem)
                if res is not None:
                    return res
        return None

    ans = dfs(domains, rem)
    return ans if ans is not None else "No Solution"


