    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [1, 17, 9, 20, 23, 10, 11], 'col_sum': [15, 13, 9, 22, 27, 9, 7]}

# Weighted binary-grid solver.
# Default weights are 1..n for rows and columns unless explicitly provided.

def generate_exact_masks(weights, target):
    n = len(weights)
    if target < 0:
        return []
    total = sum(weights)
    if target > total:
        return []

    # reachable[i] is a bitset of all sums reachable using weights[i:].
    reachable = [0] * (n + 1)
    reachable[n] = 1  # sum 0
    for i in range(n - 1, -1, -1):
        w = weights[i]
        reachable[i] = reachable[i + 1] | (reachable[i + 1] << w)

    if ((reachable[0] >> target) & 1) == 0:
        return []

    out = []

    def dfs(i, rem, mask):
        if ((reachable[i] >> rem) & 1) == 0:
            return
        if i == n:
            if rem == 0:
                out.append(mask)
            return
        w = weights[i]
        # Human-like branch preference: if remaining target is large, try taking the weight first.
        if rem >= w and ((reachable[i + 1] >> (rem - w)) & 1):
            dfs(i + 1, rem - w, mask | (1 << i))
        if ((reachable[i + 1] >> rem) & 1):
            dfs(i + 1, rem, mask)

    dfs(0, target, 0)
    return out


def summarize_domains(domains, fullmask):
    ors = [0] * len(domains)
    ands = [fullmask] * len(domains)
    for idx, dom in enumerate(domains):
        if not dom:
            return None, None
        o = 0
        a = fullmask
        for m in dom:
            o |= m
            a &= m
        ors[idx] = o
        ands[idx] = a
    return ors, ands


def propagate(row_domains, col_domains):
    nrows = len(row_domains)
    ncols = len(col_domains)
    row_full = (1 << ncols) - 1
    col_full = (1 << nrows) - 1

    while True:
        changed = False

        row_or, row_and = summarize_domains(row_domains, row_full)
        if row_or is None:
            return None
        col_or, col_and = summarize_domains(col_domains, col_full)
        if col_or is None:
            return None

        # Filter row domains from column possibilities.
        new_row_domains = []
        for i, dom in enumerate(row_domains):
            allow1 = 0
            allow0 = 0
            bit_i = 1 << i
            for j in range(ncols):
                if col_or[j] & bit_i:
                    allow1 |= 1 << j
                if not (col_and[j] & bit_i):
                    allow0 |= 1 << j

            inv_allow1 = (~allow1) & row_full
            inv_allow0 = (~allow0) & row_full
            nd = []
            for m in dom:
                if (m & inv_allow1) == 0 and ((((~m) & row_full) & inv_allow0) == 0):
                    nd.append(m)
            if not nd:
                return None
            if len(nd) != len(dom):
                changed = True
            new_row_domains.append(nd)
        row_domains = new_row_domains

        row_or, row_and = summarize_domains(row_domains, row_full)
        if row_or is None:
            return None

        # Filter column domains from row possibilities.
        new_col_domains = []
        for j, dom in enumerate(col_domains):
            allow1 = 0
            allow0 = 0
            bit_j = 1 << j
            for i in range(nrows):
                if row_or[i] & bit_j:
                    allow1 |= 1 << i
                if not (row_and[i] & bit_j):
                    allow0 |= 1 << i

            inv_allow1 = (~allow1) & col_full
            inv_allow0 = (~allow0) & col_full
            nd = []
            for m in dom:
                if (m & inv_allow1) == 0 and ((((~m) & col_full) & inv_allow0) == 0):
                    nd.append(m)
            if not nd:
                return None
            if len(nd) != len(dom):
                changed = True
            new_col_domains.append(nd)
        col_domains = new_col_domains

        row_or, row_and = summarize_domains(row_domains, row_full)
        if row_or is None:
            return None
        col_or, col_and = summarize_domains(col_domains, col_full)
        if col_or is None:
            return None

        # Direct cell-level consistency check.
        for i in range(nrows):
            bit_i = 1 << i
            for j in range(ncols):
                bit_j = 1 << j
                row_has1 = bool(row_or[i] & bit_j)
                row_has0 = not bool(row_and[i] & bit_j)
                col_has1 = bool(col_or[j] & bit_i)
                col_has0 = not bool(col_and[j] & bit_i)
                if not ((row_has1 and col_has1) or (row_has0 and col_has0)):
                    return None

        if not changed:
            return row_domains, col_domains


def state_key(row_domains, col_domains):
    return (
        tuple(tuple(dom) for dom in row_domains),
        tuple(tuple(dom) for dom in col_domains),
    )


def choose_branch_variable(row_domains, col_domains):
    nrows = len(row_domains)
    ncols = len(col_domains)
    row_full = (1 << ncols) - 1
    col_full = (1 << nrows) - 1

    row_or, row_and = summarize_domains(row_domains, row_full)
    col_or, col_and = summarize_domains(col_domains, col_full)

    best = None

    for i, dom in enumerate(row_domains):
        if len(dom) > 1:
            uncertain = ((row_or[i] ^ row_and[i]) & row_full).bit_count()
            score = (len(dom), -uncertain, 0, i)
            if best is None or score < best:
                best = score

    for j, dom in enumerate(col_domains):
        if len(dom) > 1:
            uncertain = ((col_or[j] ^ col_and[j]) & col_full).bit_count()
            score = (len(dom), -uncertain, 1, j)
            if best is None or score < best:
                best = score

    if best is None:
        return None
    _, _, kind, idx = best
    return kind, idx  # kind 0=row, 1=col


def ordered_row_patterns(i, dom, col_domains):
    bit_i = 1 << i
    support1 = []
    support0 = []
    for cd in col_domains:
        c1 = 0
        c0 = 0
        for m in cd:
            if m & bit_i:
                c1 += 1
            else:
                c0 += 1
        support1.append(c1)
        support0.append(c0)

    def score(mask):
        s = 0
        for j in range(len(col_domains)):
            s += support1[j] if ((mask >> j) & 1) else support0[j]
        return s

    return sorted(dom, key=score)


def ordered_col_patterns(j, dom, row_domains):
    bit_j = 1 << j
    support1 = []
    support0 = []
    for rd in row_domains:
        c1 = 0
        c0 = 0
        for m in rd:
            if m & bit_j:
                c1 += 1
            else:
                c0 += 1
        support1.append(c1)
        support0.append(c0)

    def score(mask):
        s = 0
        for i in range(len(row_domains)):
            s += support1[i] if ((mask >> i) & 1) else support0[i]
        return s

    return sorted(dom, key=score)


def build_answer(row_domains, ncols):
    grid = []
    for dom in row_domains:
        m = dom[0]
        grid.append(['B' if ((m >> j) & 1) else None for j in range(ncols)])
    return grid


def verify_answer(grid, row_weights, col_weights, row_sum, col_sum):
    nrows = len(grid)
    ncols = len(grid[0]) if nrows else 0

    for i in range(nrows):
        s = 0
        for j in range(ncols):
            if grid[i][j] == 'B':
                s += col_weights[j]
        if s != row_sum[i]:
            return False

    for j in range(ncols):
        s = 0
        for i in range(nrows):
            if grid[i][j] == 'B':
                s += row_weights[i]
        if s != col_sum[j]:
            return False

    return True


def solve(observation):
    row_sum = list(observation['row_sum'])
    col_sum = list(observation['col_sum'])
    nrows = len(row_sum)
    ncols = len(col_sum)

    row_weights = list(observation.get('row_weight', list(range(1, nrows + 1))))
    col_weights = list(observation.get('col_weight', list(range(1, ncols + 1))))

    if len(row_weights) != nrows or len(col_weights) != ncols:
        return "No Solution"

    # Global weighted consistency:
    # sum_i row_weight[i] * row_sum[i] == sum_j col_weight[j] * col_sum[j]
    lhs = sum(row_weights[i] * row_sum[i] for i in range(nrows))
    rhs = sum(col_weights[j] * col_sum[j] for j in range(ncols))
    if lhs != rhs:
        return "No Solution"

    row_domains = []
    for target in row_sum:
        dom = generate_exact_masks(col_weights, target)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for target in col_sum:
        dom = generate_exact_masks(row_weights, target)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    failed = set()

    def search(rdom, cdom):
        state = propagate(rdom, cdom)
        if state is None:
            return None
        rdom, cdom = state

        key = state_key(rdom, cdom)
        if key in failed:
            return None

        solved = all(len(d) == 1 for d in rdom) and all(len(d) == 1 for d in cdom)
        if solved:
            ans = build_answer(rdom, ncols)
            if verify_answer(ans, row_weights, col_weights, row_sum, col_sum):
                return ans
            failed.add(key)
            return None

        choice = choose_branch_variable(rdom, cdom)
        if choice is None:
            failed.add(key)
            return None

        kind, idx = choice

        if kind == 0:
            patterns = ordered_row_patterns(idx, rdom[idx], cdom)
            for pat in patterns:
                nr = [list(d) for d in rdom]
                nc = [list(d) for d in cdom]
                nr[idx] = [pat]
                res = search(nr, nc)
                if res is not None:
                    return res
        else:
            patterns = ordered_col_patterns(idx, cdom[idx], rdom)
            for pat in patterns:
                nr = [list(d) for d in rdom]
                nc = [list(d) for d in cdom]
                nc[idx] = [pat]
                res = search(nr, nc)
                if res is not None:
                    return res

        failed.add(key)
        return None

    result = search(row_domains, col_domains)
    return str(result) if result is not None else "No Solution"


