from collections import deque, defaultdict


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    # Normalize region ids to dense 0..R-1
    reg_map = {}
    room_of = [0] * m
    next_reg = 0
    for r in range(n):
        for c in range(n):
            x = region[r][c]
            if x not in reg_map:
                reg_map[x] = next_reg
                next_reg += 1
            room_of[idx(r, c)] = reg_map[x]
    room_count = next_reg

    rooms_cells = [[] for _ in range(room_count)]
    rooms_clue = [None] * room_count
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            rid = room_of[i]
            rooms_cells[rid].append(i)
            if data[r][c] is not None:
                if rooms_clue[rid] is None:
                    rooms_clue[rid] = data[r][c]
                elif rooms_clue[rid] != data[r][c]:
                    return "No Solution"

    neighbors = [[] for _ in range(m)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    room_local_pos = [{} for _ in range(room_count)]
    for rid, cells in enumerate(rooms_cells):
        for p, i in enumerate(cells):
            room_local_pos[rid][i] = p

    outside_neighbors = [[] for _ in range(m)]
    for i in range(m):
        rid = room_of[i]
        outside_neighbors[i] = [j for j in neighbors[i] if room_of[j] != rid]

    # Generate all independent black-placement patterns for a room.
    def gen_room_patterns(cells, clue):
        k = len(cells)
        local = {cells[i]: i for i in range(k)}
        adjmask = [0] * k
        for i, cell in enumerate(cells):
            mask = 0
            for nb in neighbors[cell]:
                if nb in local:
                    mask |= 1 << local[nb]
            adjmask[i] = mask

        patterns = []

        def dfs(pos, chosen_mask, forbidden_mask, count_black):
            if clue is not None:
                rem = k - pos
                if count_black > clue:
                    return
                if count_black + rem < clue:
                    return
            if pos == k:
                if clue is None or count_black == clue:
                    patterns.append(chosen_mask)
                return

            # White at pos
            dfs(pos + 1, chosen_mask, forbidden_mask, count_black)

            # Black at pos
            if ((forbidden_mask >> pos) & 1) == 0 and (clue is None or count_black < clue):
                dfs(
                    pos + 1,
                    chosen_mask | (1 << pos),
                    forbidden_mask | (1 << pos) | adjmask[pos],
                    count_black + 1,
                )

        dfs(0, 0, 0, 0)
        return patterns

    room_patterns = []
    for rid in range(room_count):
        pats = gen_room_patterns(rooms_cells[rid], rooms_clue[rid])
        if not pats:
            return "No Solution"
        room_patterns.append(pats)

    # Build exact row/column line constraints for the "at most 2 room-blocks in a white run" rule.
    def build_line(cells):
        blocks = []
        prev = None
        block_id = -1
        for i in cells:
            rid = room_of[i]
            if rid != prev:
                block_id += 1
                prev = rid
            blocks.append(block_id)

        patterns = []

        def dfs(pos, active_blocks, last_block, blackmask):
            if pos == len(cells):
                patterns.append(blackmask)
                return

            # Put black here: current white run stops.
            dfs(pos + 1, 0, -1, blackmask | (1 << pos))

            # Put white here: continue/start run if valid.
            b = blocks[pos]
            if active_blocks == 0:
                dfs(pos + 1, 1, b, blackmask)
            elif b == last_block:
                dfs(pos + 1, active_blocks, last_block, blackmask)
            elif b == last_block + 1 and active_blocks < 2:
                dfs(pos + 1, active_blocks + 1, b, blackmask)

        dfs(0, 0, -1, 0)
        return {"cells": cells, "patterns": patterns}

    rows = [build_line([idx(r, c) for c in range(n)]) for r in range(n)]
    cols = [build_line([idx(r, c) for r in range(n)]) for c in range(n)]

    row_of = [0] * m
    row_pos = [0] * m
    col_of = [0] * m
    col_pos = [0] * m
    for r in range(n):
        for p, i in enumerate(rows[r]["cells"]):
            row_of[i] = r
            row_pos[i] = p
    for c in range(n):
        for p, i in enumerate(cols[c]["cells"]):
            col_of[i] = c
            col_pos[i] = p

    def set_cell(assign, i, val):
        cur = assign[i]
        if cur == -1:
            assign[i] = val
            return True
        return cur == val

    def connectivity_propagate(assign):
        whites = [i for i, v in enumerate(assign) if v == 0]
        if not whites:
            return True, False

        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for nb in neighbors[x]:
                if assign[nb] != 1 and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)

        for w in whites:
            if w not in seen:
                return False, False

        changed = False
        for i, v in enumerate(assign):
            if v == -1 and i not in seen:
                assign[i] = 1
                changed = True
        return True, changed

    def filter_room_patterns(assign, allowed, rid):
        cells = rooms_cells[rid]
        kept = []
        for pat in allowed:
            ok = True
            for lp, cell in enumerate(cells):
                bit = (pat >> lp) & 1
                v = assign[cell]
                if v == 1 and not bit:
                    ok = False
                    break
                if v == 0 and bit:
                    ok = False
                    break
                if bit:
                    for nb in outside_neighbors[cell]:
                        if assign[nb] == 1:
                            ok = False
                            break
                    if not ok:
                        break
            if ok:
                kept.append(pat)
        return kept

    def filter_line_patterns(assign, allowed, line_cells):
        kept = []
        for pat in allowed:
            ok = True
            for p, cell in enumerate(line_cells):
                bit = (pat >> p) & 1
                v = assign[cell]
                if v == 1 and not bit:
                    ok = False
                    break
                if v == 0 and bit:
                    ok = False
                    break
            if ok:
                kept.append(pat)
        return kept

    def propagate(assign, room_allowed, row_allowed, col_allowed):
        while True:
            changed = False

            # Black adjacency.
            for i, v in enumerate(assign):
                if v == 1:
                    for nb in neighbors[i]:
                        if assign[nb] == 1:
                            return None
                        if assign[nb] == -1:
                            assign[nb] = 0
                            changed = True

            # Room constraints.
            for rid in range(room_count):
                new_allowed = filter_room_patterns(assign, room_allowed[rid], rid)
                if not new_allowed:
                    return None
                if len(new_allowed) != len(room_allowed[rid]):
                    room_allowed[rid] = new_allowed
                    changed = True

                cells = rooms_cells[rid]
                k = len(cells)
                andmask = (1 << k) - 1
                ormask = 0
                for pat in new_allowed:
                    andmask &= pat
                    ormask |= pat

                for lp, cell in enumerate(cells):
                    if assign[cell] == -1:
                        if (andmask >> lp) & 1:
                            if not set_cell(assign, cell, 1):
                                return None
                            changed = True
                        elif ((ormask >> lp) & 1) == 0:
                            if not set_cell(assign, cell, 0):
                                return None
                            changed = True

            # Exact line-rule constraints on rows.
            for r in range(n):
                line_cells = rows[r]["cells"]
                new_allowed = filter_line_patterns(assign, row_allowed[r], line_cells)
                if not new_allowed:
                    return None
                if len(new_allowed) != len(row_allowed[r]):
                    row_allowed[r] = new_allowed
                    changed = True

                L = len(line_cells)
                andmask = (1 << L) - 1
                ormask = 0
                for pat in new_allowed:
                    andmask &= pat
                    ormask |= pat

                for p, cell in enumerate(line_cells):
                    if assign[cell] == -1:
                        if (andmask >> p) & 1:
                            if not set_cell(assign, cell, 1):
                                return None
                            changed = True
                        elif ((ormask >> p) & 1) == 0:
                            if not set_cell(assign, cell, 0):
                                return None
                            changed = True

            # Exact line-rule constraints on columns.
            for c in range(n):
                line_cells = cols[c]["cells"]
                new_allowed = filter_line_patterns(assign, col_allowed[c], line_cells)
                if not new_allowed:
                    return None
                if len(new_allowed) != len(col_allowed[c]):
                    col_allowed[c] = new_allowed
                    changed = True

                L = len(line_cells)
                andmask = (1 << L) - 1
                ormask = 0
                for pat in new_allowed:
                    andmask &= pat
                    ormask |= pat

                for p, cell in enumerate(line_cells):
                    if assign[cell] == -1:
                        if (andmask >> p) & 1:
                            if not set_cell(assign, cell, 1):
                                return None
                            changed = True
                        elif ((ormask >> p) & 1) == 0:
                            if not set_cell(assign, cell, 0):
                                return None
                            changed = True

            # Connectivity of whites.
            ok, conn_changed = connectivity_propagate(assign)
            if not ok:
                return None
            if conn_changed:
                changed = True

            if not changed:
                break

        return assign, room_allowed, row_allowed, col_allowed

    def final_check(assign):
        # No unknowns.
        if any(v == -1 for v in assign):
            return False

        # Black non-adjacency.
        for i, v in enumerate(assign):
            if v == 1:
                for nb in neighbors[i]:
                    if assign[nb] == 1:
                        return False

        # Room clues.
        for rid, cells in enumerate(rooms_cells):
            clue = rooms_clue[rid]
            if clue is not None:
                if sum(assign[i] == 1 for i in cells) != clue:
                    return False

        # Line rule.
        for line in rows + cols:
            cells = line["cells"]
            prev_black = True
            block_count = 0
            prev_rid = None
            for cell in cells:
                if assign[cell] == 1:
                    prev_black = True
                    block_count = 0
                    prev_rid = None
                else:
                    rid = room_of[cell]
                    if prev_black:
                        prev_black = False
                        block_count = 1
                        prev_rid = rid
                    else:
                        if rid != prev_rid:
                            block_count += 1
                            prev_rid = rid
                            if block_count > 2:
                                return False

        # White connectivity.
        whites = [i for i, v in enumerate(assign) if v == 0]
        if whites:
            seen = set([whites[0]])
            dq = deque([whites[0]])
            while dq:
                x = dq.popleft()
                for nb in neighbors[x]:
                    if assign[nb] == 0 and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(whites):
                return False

        return True

    def count_support(patterns, pos):
        black = 0
        white = 0
        for pat in patterns:
            if (pat >> pos) & 1:
                black += 1
            else:
                white += 1
        return black, white

    def choose_branch(assign, room_allowed, row_allowed, col_allowed):
        # Prefer the smallest remaining structured constraint.
        best = None

        for rid, allowed in enumerate(room_allowed):
            if 1 < len(allowed):
                score = len(allowed)
                if best is None or score < best[0]:
                    best = (score, "room", rid)

        for r, allowed in enumerate(row_allowed):
            if 1 < len(allowed):
                score = len(allowed)
                if best is None or score < best[0]:
                    best = (score, "row", r)

        for c, allowed in enumerate(col_allowed):
            if 1 < len(allowed):
                score = len(allowed)
                if best is None or score < best[0]:
                    best = (score, "col", c)

        # If every structured constraint still has many options, branch on a single highly constrained cell.
        if best is None or best[0] > 4:
            cell_best = None
            for i, v in enumerate(assign):
                if v != -1:
                    continue
                rid = room_of[i]
                rp = room_local_pos[rid][i]
                rr = row_of[i]
                rrp = row_pos[i]
                cc = col_of[i]
                ccp = col_pos[i]

                rb, rw = count_support(room_allowed[rid], rp)
                hb, hw = count_support(row_allowed[rr], rrp)
                vb, vw = count_support(col_allowed[cc], ccp)

                can_black = rb > 0 and hb > 0 and vb > 0 and all(assign[nb] != 1 for nb in neighbors[i])
                can_white = rw > 0 and hw > 0 and vw > 0

                if not can_black and not can_white:
                    return ("dead", i)
                if can_black and not can_white:
                    return ("cell", i, [1])
                if can_white and not can_black:
                    return ("cell", i, [0])

                score = min(rb, rw) + min(hb, hw) + min(vb, vw)
                # Try black first if it is rarer.
                vals = [1, 0] if (rb * hb * vb) <= (rw * hw * vw) else [0, 1]
                if cell_best is None or score < cell_best[0]:
                    cell_best = (score, i, vals)
            if cell_best is not None:
                return ("cell", cell_best[1], cell_best[2])

        if best is None:
            return None
        return best[1], best[2]

    def clone_allowed(lst):
        return [x[:] for x in lst]

    def dfs(assign, room_allowed, row_allowed, col_allowed):
        state = propagate(assign, room_allowed, row_allowed, col_allowed)
        if state is None:
            return None
        assign, room_allowed, row_allowed, col_allowed = state

        if all(v != -1 for v in assign):
            return assign if final_check(assign) else None

        branch = choose_branch(assign, room_allowed, row_allowed, col_allowed)
        if branch is None:
            return assign if final_check(assign) else None
        if branch[0] == "dead":
            return None

        kind = branch[0]

        if kind == "cell":
            i = branch[1]
            vals = branch[2]
            for val in vals:
                na = assign[:]
                if not set_cell(na, i, val):
                    continue
                ans = dfs(na, clone_allowed(room_allowed), clone_allowed(row_allowed), clone_allowed(col_allowed))
                if ans is not None:
                    return ans
            return None

        if kind == "room":
            rid = branch[1]
            cells = rooms_cells[rid]
            allowed = room_allowed[rid]
            # Slightly human-like ordering: more black first if clue exists and positive.
            allowed = sorted(allowed, key=lambda p: bin(p).count("1"), reverse=True)
            for pat in allowed:
                na = assign[:]
                ok = True
                for lp, cell in enumerate(cells):
                    val = 1 if ((pat >> lp) & 1) else 0
                    if not set_cell(na, cell, val):
                        ok = False
                        break
                if not ok:
                    continue
                nr = clone_allowed(room_allowed)
                nr[rid] = [pat]
                ans = dfs(na, nr, clone_allowed(row_allowed), clone_allowed(col_allowed))
                if ans is not None:
                    return ans
            return None

        if kind == "row":
            r = branch[1]
            cells = rows[r]["cells"]
            allowed = row_allowed[r]
            allowed = sorted(allowed, key=lambda p: bin(p).count("1"), reverse=True)
            for pat in allowed:
                na = assign[:]
                ok = True
                for p, cell in enumerate(cells):
                    val = 1 if ((pat >> p) & 1) else 0
                    if not set_cell(na, cell, val):
                        ok = False
                        break
                if not ok:
                    continue
                nrw = clone_allowed(row_allowed)
                nrw[r] = [pat]
                ans = dfs(na, clone_allowed(room_allowed), nrw, clone_allowed(col_allowed))
                if ans is not None:
                    return ans
            return None

        if kind == "col":
            c = branch[1]
            cells = cols[c]["cells"]
            allowed = col_allowed[c]
            allowed = sorted(allowed, key=lambda p: bin(p).count("1"), reverse=True)
            for pat in allowed:
                na = assign[:]
                ok = True
                for p, cell in enumerate(cells):
                    val = 1 if ((pat >> p) & 1) else 0
                    if not set_cell(na, cell, val):
                        ok = False
                        break
                if not ok:
                    continue
                ncl = clone_allowed(col_allowed)
                ncl[c] = [pat]
                ans = dfs(na, clone_allowed(room_allowed), clone_allowed(row_allowed), ncl)
                if ans is not None:
                    return ans
            return None

        return None

    initial_assign = [-1] * m
    initial_room_allowed = [p[:] for p in room_patterns]
    initial_row_allowed = [line["patterns"][:] for line in rows]
    initial_col_allowed = [line["patterns"][:] for line in cols]

    ans = dfs(initial_assign, initial_room_allowed, initial_row_allowed, initial_col_allowed)
    if ans is None:
        return "No Solution"

    out = []
    for r in range(n):
        row_out = []
        for c in range(n):
            v = ans[idx(r, c)]
            row_out.append("B" if v == 1 else None)
        out.append(row_out)
    return out


if __name__ == "__main__":
    print(solve(OBSERVATION))

