from itertools import combinations

def solve(observation):
    data = observation['data']
    n = len(data)
    nn = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    def parse_coord(key):
        s = key.strip()
        if s[0] == '(' and s[-1] == ')':
            s = s[1:-1]
        a, b = s.split(',')
        return float(a), float(b)

    prefix = [0] * (n + 1)
    for v in range(1, n + 1):
        prefix[v] = prefix[v - 1] | (1 << v)
    full = prefix[n]

    def is_single(mask):
        return mask and (mask & (mask - 1) == 0)

    def min_val(mask):
        return (mask & -mask).bit_length() - 1

    def max_val(mask):
        return mask.bit_length() - 1

    def mask_range(lo, hi):
        if lo > hi:
            return 0
        return prefix[hi] & ~prefix[lo - 1]

    def iter_values(mask):
        while mask:
            bit = mask & -mask
            yield bit.bit_length() - 1
            mask ^= bit

    rows = [[idx(r, c) for c in range(n)] for r in range(n)]
    cols = [[idx(r, c) for r in range(n)] for c in range(n)]
    units = rows + cols

    direct = set()

    for key, sym in observation.get('horizontal', {}).items():
        r_f, c_f = parse_coord(key)
        r = int(round(r_f))
        c = int(round(c_f - 0.5))
        left = idx(r, c)
        right = idx(r, c + 1)
        if sym == '<':
            direct.add((left, right))
        elif sym == '>':
            direct.add((right, left))
        else:
            return "No Solution"

    for key, sym in observation.get('vertical', {}).items():
        r_f, c_f = parse_coord(key)
        r = int(round(r_f - 0.5))
        c = int(round(c_f))
        top = idx(r, c)
        bottom = idx(r + 1, c)
        if sym == '^':
            direct.add((top, bottom))
        elif sym == 'v':
            direct.add((bottom, top))
        else:
            return "No Solution"

    out = [[] for _ in range(nn)]
    indeg = [0] * nn
    for u, v in direct:
        out[u].append(v)
        indeg[v] += 1

    stack = [i for i in range(nn) if indeg[i] == 0]
    topo = []
    head = 0
    while head < len(stack):
        u = stack[head]
        head += 1
        topo.append(u)
        for v in out[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                stack.append(v)

    if len(topo) != nn:
        return "No Solution"

    longest_pred = [0] * nn
    for u in topo:
        base = longest_pred[u] + 1
        for v in out[u]:
            if base > longest_pred[v]:
                longest_pred[v] = base

    longest_succ = [0] * nn
    for u in reversed(topo):
        best = 0
        for v in out[u]:
            cand = 1 + longest_succ[v]
            if cand > best:
                best = cand
        longest_succ[u] = best

    reach = [0] * nn
    for u in reversed(topo):
        bits = 0
        for v in out[u]:
            bits |= (1 << v) | reach[v]
        reach[u] = bits

    closure = []
    ineq_degree = [0] * nn
    for u in range(nn):
        bits = reach[u]
        ineq_degree[u] += bits.bit_count()
        while bits:
            bit = bits & -bits
            v = bit.bit_length() - 1
            closure.append((u, v))
            ineq_degree[v] += 1
            bits ^= bit

    bound_mask = [0] * nn
    for u in range(nn):
        lo = 1 + longest_pred[u]
        hi = n - longest_succ[u]
        bm = mask_range(lo, hi)
        if bm == 0:
            return "No Solution"
        bound_mask[u] = bm

    domains = [full] * nn
    for r in range(n):
        for c in range(n):
            u = idx(r, c)
            val = data[r][c]
            if val is None:
                domains[u] = bound_mask[u]
            else:
                if not (1 <= val <= n):
                    return "No Solution"
                giv = 1 << val
                if not (giv & bound_mask[u]):
                    return "No Solution"
                domains[u] = giv

    def propagate_unit(dom, unit):
        changed = False

        fixed_seen = 0
        unsolved = []
        occ_count = [0] * (n + 1)
        occ_pos = [-1] * (n + 1)

        for u in unit:
            d = dom[u]
            if d == 0:
                return None
            if is_single(d):
                if fixed_seen & d:
                    return None
                fixed_seen |= d
            else:
                unsolved.append(u)
            bits = d
            while bits:
                bit = bits & -bits
                v = bit.bit_length() - 1
                occ_count[v] += 1
                if occ_count[v] == 1:
                    occ_pos[v] = u
                bits ^= bit

        for v in range(1, n + 1):
            if occ_count[v] == 0:
                return None

        if fixed_seen:
            forbid = ~fixed_seen
            for u in unsolved:
                nd = dom[u] & forbid
                if nd == 0:
                    return None
                if nd != dom[u]:
                    dom[u] = nd
                    changed = True

        occ_count = [0] * (n + 1)
        occ_pos = [-1] * (n + 1)
        uns = []
        for u in unit:
            d = dom[u]
            if d == 0:
                return None
            if not is_single(d):
                uns.append((u, d))
            bits = d
            while bits:
                bit = bits & -bits
                v = bit.bit_length() - 1
                occ_count[v] += 1
                if occ_count[v] == 1:
                    occ_pos[v] = u
                bits ^= bit

        for v in range(1, n + 1):
            if occ_count[v] == 0:
                return None
            if occ_count[v] == 1:
                u = occ_pos[v]
                nd = 1 << v
                if dom[u] != nd:
                    dom[u] = nd
                    changed = True

        uns = [(u, dom[u]) for u in unit if not is_single(dom[u])]
        if len(uns) >= 2:
            by_mask = {}
            for u, d in uns:
                by_mask.setdefault(d, []).append(u)

            for mask, cells in by_mask.items():
                k = mask.bit_count()
                if k > 1 and k == len(cells):
                    cellset = set(cells)
                    for u, d in uns:
                        if u not in cellset:
                            nd = d & ~mask
                            if nd == 0:
                                return None
                            if nd != d:
                                dom[u] = nd
                                changed = True

            uns = [(u, dom[u]) for u in unit if not is_single(dom[u])]
            m = len(uns)
            max_k = min(4, m - 1)
            for k in range(2, max_k + 1):
                for comb in combinations(range(m), k):
                    union = 0
                    for i in comb:
                        union |= uns[i][1]
                    if union.bit_count() != k:
                        continue
                    chosen = {uns[i][0] for i in comb}
                    for u, d in uns:
                        if u not in chosen:
                            nd = d & ~union
                            if nd == 0:
                                return None
                            if nd != d:
                                dom[u] = nd
                                changed = True

        return changed

    def propagate(dom):
        while True:
            changed = False

            for u in range(nn):
                d = dom[u]
                nd = d & bound_mask[u]
                if nd == 0:
                    return None
                if nd != d:
                    dom[u] = nd
                    changed = True

            for u, v in closure:
                du = dom[u]
                dv = dom[v]

                mx = max_val(dv)
                ndu = du & prefix[mx - 1] if mx > 1 else 0
                if ndu == 0:
                    return None
                if ndu != du:
                    dom[u] = ndu
                    du = ndu
                    changed = True

                mn = min_val(du)
                ndv = dv & (full & ~prefix[mn])
                if ndv == 0:
                    return None
                if ndv != dv:
                    dom[v] = ndv
                    changed = True

            for unit in units:
                res = propagate_unit(dom, unit)
                if res is None:
                    return None
                if res:
                    changed = True

            if not changed:
                return dom

    failed = set()

    def solved(dom):
        return all(is_single(d) for d in dom)

    def entropy(dom):
        return sum(d.bit_count() - 1 for d in dom)

    def choose_cell(dom):
        best_u = -1
        best_key = (n + 1, float('inf'))
        for u, d in enumerate(dom):
            bc = d.bit_count()
            if bc > 1:
                key = (bc, -ineq_degree[u])
                if key < best_key:
                    best_key = key
                    best_u = u
        return best_u

    def search(dom):
        dom = propagate(dom[:])
        if dom is None:
            return None

        key = tuple(dom)
        if key in failed:
            return None

        if solved(dom):
            return dom

        u = choose_cell(dom)
        if u < 0:
            return dom

        candidates = []
        viable_mask = 0

        for v in iter_values(dom[u]):
            ndom = dom[:]
            ndom[u] = 1 << v
            pd = propagate(ndom)
            if pd is not None:
                viable_mask |= 1 << v
                candidates.append(pd)

        if viable_mask == 0:
            failed.add(key)
            return None

        if viable_mask != dom[u]:
            ndom = dom[:]
            ndom[u] = viable_mask
            res = search(ndom)
            if res is not None:
                return res
            failed.add(key)
            return None

        candidates.sort(key=entropy)
        for pd in candidates:
            res = search(pd)
            if res is not None:
                return res

        failed.add(key)
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(result[idx(r, c)].bit_length() - 1)
        grid.append(row)
    return grid

if __name__ == "__main__":
    print(solve(OBSERVATION))

