from collections import deque

# Directions
U, R, D, L = 1, 2, 4, 8
DIRBITS = [U, R, D, L]
DR = [-1, 0, 1, 0]
DC = [0, 1, 0, -1]
OPP = [2, 3, 0, 1]

# Allowed node states:
# 0 = unused
# 1 = vertical
# 2 = horizontal
# 3..6 = corners
MASKS = [0, U | D, L | R, U | R, R | D, D | L, L | U]
MASK_TO_ID = {m: i for i, m in enumerate(MASKS)}
STATEBIT = [1 << i for i in range(len(MASKS))]
FULL_DOMAIN = (1 << len(MASKS)) - 1
OFF_BIT = 1 << 0
NONZERO_DOMAIN = FULL_DOMAIN ^ OFF_BIT


def bit_count(x):
    return x.bit_count()


def is_singleton(x):
    return x != 0 and (x & (x - 1)) == 0


def singleton_id(x):
    return x.bit_length() - 1


def iter_state_ids(domain_bits):
    while domain_bits:
        b = domain_bits & -domain_bits
        yield b.bit_length() - 1
        domain_bits ^= b


class Solver:
    def __init__(self, observation):
        self.data = observation["data"]
        self.size = len(self.data)
        self.V = self.size * self.size

        self.rc_to_idx = lambda r, c: r * self.size + c
        self.idx_to_rc = lambda idx: (idx // self.size, idx % self.size)

        self.nei = [[-1] * 4 for _ in range(self.V)]
        for r in range(self.size):
            for c in range(self.size):
                v = self.rc_to_idx(r, c)
                for d in range(4):
                    nr, nc = r + DR[d], c + DC[d]
                    if 0 <= nr < self.size and 0 <= nc < self.size:
                        self.nei[v][d] = self.rc_to_idx(nr, nc)

        # Base domains from clue type
        self.base_domains = [FULL_DOMAIN for _ in range(self.V)]
        self.clues = []
        self.clue_nodes = set()

        white_domain = STATEBIT[MASK_TO_ID[U | D]] | STATEBIT[MASK_TO_ID[L | R]]
        black_domain = (
            STATEBIT[MASK_TO_ID[U | R]]
            | STATEBIT[MASK_TO_ID[R | D]]
            | STATEBIT[MASK_TO_ID[D | L]]
            | STATEBIT[MASK_TO_ID[L | U]]
        )

        for r in range(self.size):
            for c in range(self.size):
                token = self.data[r][c]
                if token is None:
                    continue
                v = self.rc_to_idx(r, c)
                t = token[0]
                k = int(token[1:])
                self.clues.append((v, t, k))
                self.clue_nodes.add(v)
                self.base_domains[v] = white_domain if t == "W" else black_domain

        # Adjacency compatibility between node states
        self.compat = [[0] * len(MASKS) for _ in range(4)]
        for d in range(4):
            od = OPP[d]
            for sid, sm in enumerate(MASKS):
                want = 1 if (sm & DIRBITS[d]) else 0
                comp = 0
                for tid, tm in enumerate(MASKS):
                    have = 1 if (tm & DIRBITS[od]) else 0
                    if want == have:
                        comp |= STATEBIT[tid]
                self.compat[d][sid] = comp

        # Generate clue options
        self.clue_options = []
        for v, t, k in self.clues:
            opts = self.generate_clue_options(v, t, k)
            if not opts:
                self.impossible = True
                return
            self.clue_options.append(opts)

        self.impossible = False

    def statebit_for_mask(self, mask):
        return STATEBIT[MASK_TO_ID[mask]]

    def add_restriction(self, opt, node, allow_bits):
        allow_bits &= self.base_domains[node]
        if allow_bits == 0:
            return False
        if node in opt:
            allow_bits &= opt[node]
            if allow_bits == 0:
                return False
        opt[node] = allow_bits
        return True

    def straight_mask_for_dir(self, d):
        return U | D if d in (0, 2) else L | R

    def endpoint_turn_bits(self, d):
        # Arm arrives at endpoint from opposite direction of d.
        if d == 0:   # moving upward; endpoint must have D + (L or R)
            masks = [D | L, D | R]
        elif d == 1: # moving right; endpoint must have L + (U or D)
            masks = [L | U, L | D]
        elif d == 2: # moving down; endpoint must have U + (L or R)
            masks = [U | L, U | R]
        else:        # moving left; endpoint must have R + (U or D)
            masks = [R | U, R | D]
        bits = 0
        for m in masks:
            bits |= self.statebit_for_mask(m)
        return bits

    def add_arm(self, opt, start, d, length):
        cur = start
        for step in range(1, length + 1):
            nxt = self.nei[cur][d]
            if nxt == -1:
                return False
            cur = nxt
            if step < length:
                allow = self.statebit_for_mask(self.straight_mask_for_dir(d))
            else:
                allow = self.endpoint_turn_bits(d)
            if not self.add_restriction(opt, cur, allow):
                return False
        return True

    def generate_clue_options(self, v, t, k):
        opts = []
        seen = set()

        if k < 2:
            return []

        if t == "W":
            configs = [
                (U | D, (0, 2)),  # vertical
                (L | R, (3, 1)),  # horizontal
            ]
        else:
            configs = [
                (U | R, (0, 1)),
                (R | D, (1, 2)),
                (D | L, (2, 3)),
                (L | U, (3, 0)),
            ]

        for clue_mask, dirs in configs:
            clue_bits = self.statebit_for_mask(clue_mask)
            for a in range(1, k):
                b = k - a
                opt = {}
                if not self.add_restriction(opt, v, clue_bits):
                    continue
                if not self.add_arm(opt, v, dirs[0], a):
                    continue
                if not self.add_arm(opt, v, dirs[1], b):
                    continue
                key = tuple(sorted(opt.items()))
                if key not in seen:
                    seen.add(key)
                    opts.append(opt)

        return opts

    def propagate(self, domains, remains):
        changed = True
        while changed:
            changed = False

            # 1) Node adjacency arc-consistency
            local = True
            while local:
                local = False
                for v in range(self.V):
                    dv = domains[v]
                    new_dv = dv
                    for sid in iter_state_ids(dv):
                        sm = MASKS[sid]
                        ok = True
                        for d in range(4):
                            n = self.nei[v][d]
                            has_edge = 1 if (sm & DIRBITS[d]) else 0
                            if n == -1:
                                if has_edge:
                                    ok = False
                                    break
                            else:
                                if (domains[n] & self.compat[d][sid]) == 0:
                                    ok = False
                                    break
                        if not ok:
                            new_dv &= ~STATEBIT[sid]
                    if new_dv == 0:
                        return None
                    if new_dv != dv:
                        domains[v] = new_dv
                        local = True
                        changed = True

            # 2) Clue-option filtering and limited GAC-like propagation
            for ci, opts in enumerate(self.clue_options):
                rem = remains[ci]
                new_rem = []
                for oi in rem:
                    opt = opts[oi]
                    ok = True
                    for node, allow in opt.items():
                        if (domains[node] & allow) == 0:
                            ok = False
                            break
                    if ok:
                        new_rem.append(oi)

                if not new_rem:
                    return None

                if len(new_rem) != len(rem):
                    remains[ci] = new_rem
                    rem = new_rem
                    changed = True

                total = len(rem)
                presence = {}
                unions = {}
                for oi in rem:
                    for node, allow in opts[oi].items():
                        presence[node] = presence.get(node, 0) + 1
                        unions[node] = unions.get(node, 0) | allow

                for node, cnt in presence.items():
                    if cnt == total:
                        nd = domains[node] & unions[node]
                        if nd == 0:
                            return None
                        if nd != domains[node]:
                            domains[node] = nd
                            changed = True

            # 3) Prevent already-fixed premature closed cycles
            if self.has_premature_assigned_cycle(domains):
                return None

        return domains, remains

    def has_premature_assigned_cycle(self, domains):
        assigned = {}
        for v, d in enumerate(domains):
            if is_singleton(d):
                sid = singleton_id(d)
                mask = MASKS[sid]
                if mask != 0:
                    assigned[v] = mask

        visited = set()
        for start in assigned:
            if start in visited:
                continue
            stack = [start]
            comp = []
            closed = True
            while stack:
                v = stack.pop()
                if v in visited:
                    continue
                visited.add(v)
                comp.append(v)
                mask = assigned[v]
                for d in range(4):
                    if not (mask & DIRBITS[d]):
                        continue
                    n = self.nei[v][d]
                    if n == -1 or n not in assigned or not (assigned[n] & DIRBITS[OPP[d]]):
                        closed = False
                    else:
                        if n not in visited:
                            stack.append(n)

            if closed:
                comp_set = set(comp)
                # If any outside node is forced to be used, a closed cycle here is fatal.
                for v, dom in enumerate(domains):
                    if v in comp_set:
                        continue
                    if (dom & OFF_BIT) == 0:
                        return True
        return False

    def choose_branch(self, domains, remains):
        # Prefer clue-option branching first: usually much more informative.
        best_clue = None
        best_len = 10**9
        for ci, rem in enumerate(remains):
            if 1 < len(rem) < best_len:
                best_len = len(rem)
                best_clue = ci

        if best_clue is not None:
            return ("clue", best_clue)

        best_node = None
        best_count = 10**9
        best_score = -1
        for v, dom in enumerate(domains):
            cnt = bit_count(dom)
            if cnt <= 1:
                continue
            # Tie-break toward nodes that are forced-used or clue-adjacent-ish by neighborhood pressure
            forced_used_bias = 1 if (dom & OFF_BIT) == 0 else 0
            neighbor_pressure = 0
            for d in range(4):
                n = self.nei[v][d]
                if n != -1 and bit_count(domains[n]) <= 2:
                    neighbor_pressure += 1
            score = forced_used_bias * 10 + neighbor_pressure
            if cnt < best_count or (cnt == best_count and score > best_score):
                best_count = cnt
                best_score = score
                best_node = v

        if best_node is not None:
            return ("node", best_node)
        return (None, None)

    def order_clue_options(self, ci):
        rem = self.remains_work[ci]
        opts = self.clue_options[ci]
        # More restrictive / larger footprint first
        return sorted(rem, key=lambda oi: (-len(opts[oi]), oi))

    def order_node_states(self, dom):
        sids = list(iter_state_ids(dom))
        # Off first for non-clue nodes; otherwise straights before turns
        def key(sid):
            mask = MASKS[sid]
            if mask == 0:
                return (0, 0)
            if mask in (U | D, L | R):
                return (1, 0)
            return (1, 1)
        sids.sort(key=key)
        return sids

    def extract_solution(self, domains):
        masks = [MASKS[singleton_id(d)] for d in domains]

        # Check reciprocal edges
        for v in range(self.V):
            m = masks[v]
            for d in range(4):
                n = self.nei[v][d]
                has = 1 if (m & DIRBITS[d]) else 0
                if n == -1:
                    if has:
                        return None
                else:
                    rev = 1 if (masks[n] & DIRBITS[OPP[d]]) else 0
                    if has != rev:
                        return None

        used = [v for v, m in enumerate(masks) if m != 0]
        if not used:
            return None

        # All clues must be on the loop
        for v in self.clue_nodes:
            if masks[v] == 0:
                return None

        # Connected single cycle
        start = used[0]
        seen = set([start])
        stack = [start]
        while stack:
            v = stack.pop()
            m = masks[v]
            for d in range(4):
                if m & DIRBITS[d]:
                    n = self.nei[v][d]
                    if n not in seen:
                        seen.add(n)
                        stack.append(n)

        if len(seen) != len(used):
            return None

        edge_count = sum((m != 0) * 2 for m in masks) // 2
        if edge_count != len(used):
            return None

        # Extract ordered cycle path
        start = min(used, key=lambda x: self.idx_to_rc(x))
        neighs = []
        for d in range(4):
            if masks[start] & DIRBITS[d]:
                neighs.append(self.nei[start][d])
        if len(neighs) != 2:
            return None

        path = [self.idx_to_rc(start)]
        prev = start
        cur = neighs[0]

        for _ in range(len(used) + 1):
            path.append(self.idx_to_rc(cur))
            if cur == start:
                if len(path) == len(used) + 1:
                    return path
                return None
            nexts = []
            m = masks[cur]
            for d in range(4):
                if m & DIRBITS[d]:
                    nexts.append(self.nei[cur][d])
            if len(nexts) != 2:
                return None
            nxt = nexts[0] if nexts[1] == prev else nexts[1]
            prev, cur = cur, nxt

        return None

    def dfs(self, domains, remains):
        res = self.propagate(domains, remains)
        if res is None:
            return None
        domains, remains = res

        if all(is_singleton(d) for d in domains):
            return self.extract_solution(domains)

        # Small hack so order_clue_options can inspect current remains without threading more args
        self.remains_work = remains

        kind, which = self.choose_branch(domains, remains)
        if kind is None:
            return None

        if kind == "clue":
            ci = which
            for oi in self.order_clue_options(ci):
                new_domains = domains[:]
                new_remains = [lst[:] for lst in remains]
                new_remains[ci] = [oi]
                ans = self.dfs(new_domains, new_remains)
                if ans is not None:
                    return ans
            return None

        v = which
        for sid in self.order_node_states(domains[v]):
            new_domains = domains[:]
            new_remains = [lst[:] for lst in remains]
            new_domains[v] = STATEBIT[sid]
            ans = self.dfs(new_domains, new_remains)
            if ans is not None:
                return ans
        return None

    def solve(self):
        if self.impossible:
            return None
        domains = self.base_domains[:]
        remains = [list(range(len(opts))) for opts in self.clue_options]
        return self.dfs(domains, remains)


def solve(observation):
    solver = Solver(observation)
    path = solver.solve()
    return repr(path) if path is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'tree': [[None, 'T', None, None, None, None, None, 'T'], [None, None, None, None, 'T', None, None, None], ['T', None, None, None, None, None, None, None], [None, None, None, 'T', None, None, None, None], [None, None, None, None, None, None, None, 'T'], [None, None, 'T', None, None, None, 'T', None], [None, 'T', 'T', None, None, None, 'T', None], [None, None, None, None, 'T', None, None, None]], 'row_tent_counts': [2, 1, 1, 2, 0, 2, 2, 2], 'col_tent_counts': [2, 0, 3, 1, 1, 2, 1, 2]}

def solve(observation):
    tree_grid = observation['tree']
    row_targets = observation['row_tent_counts']
    col_targets = observation['col_tent_counts']

    if not tree_grid or not tree_grid[0]:
        return "No Solution"

    R = len(tree_grid)
    C = len(tree_grid[0])

    if len(row_targets) != R or len(col_targets) != C:
        return "No Solution"

    if sum(row_targets) != sum(col_targets):
        return "No Solution"

    trees = []
    for r in range(R):
        if len(tree_grid[r]) != C:
            return "No Solution"
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))

    if sum(row_targets) != len(trees):
        return "No Solution"

    def in_bounds(r, c):
        return 0 <= r < R and 0 <= c < C

    ortho = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Count how many trees are orthogonally adjacent to each cell.
    adj_tree_count = [[0] * C for _ in range(R)]
    for tr, tc in trees:
        for dr, dc in ortho:
            nr, nc = tr + dr, tc + dc
            if in_bounds(nr, nc) and tree_grid[nr][nc] != 'T':
                adj_tree_count[nr][nc] += 1

    # Candidate tent cells: empty cells orthogonally adjacent to exactly one tree.
    tree_candidates = []
    for tr, tc in trees:
        cells = []
        seen = set()
        for dr, dc in ortho:
            nr, nc = tr + dr, tc + dc
            if in_bounds(nr, nc) and tree_grid[nr][nc] != 'T' and adj_tree_count[nr][nc] == 1:
                if (nr, nc) not in seen:
                    seen.add((nr, nc))
                    cells.append((nr, nc))
        if not cells:
            return "No Solution"
        tree_candidates.append(cells)

    cand_cells = []
    cand_tree = []
    tree_masks = []

    for t, cells in enumerate(tree_candidates):
        mask = 0
        for cell in cells:
            idx = len(cand_cells)
            cand_cells.append(cell)
            cand_tree.append(t)
            mask |= 1 << idx
        tree_masks.append(mask)

    M = len(cand_cells)
    cand_row = [rc[0] for rc in cand_cells]
    cand_col = [rc[1] for rc in cand_cells]

    row_masks = [0] * R
    col_masks = [0] * C
    for i, (r, c) in enumerate(cand_cells):
        bit = 1 << i
        row_masks[r] |= bit
        col_masks[c] |= bit

    # Conflict = tents touch orthogonally or diagonally.
    conflict_by_tree = [dict() for _ in range(M)]
    conflict_degree = [0] * M

    for i in range(M):
        r1, c1 = cand_cells[i]
        t1 = cand_tree[i]
        for j in range(i + 1, M):
            t2 = cand_tree[j]
            if t1 == t2:
                continue
            r2, c2 = cand_cells[j]
            if max(abs(r1 - r2), abs(c1 - c2)) <= 1:
                b1 = 1 << i
                b2 = 1 << j
                conflict_by_tree[i][t2] = conflict_by_tree[i].get(t2, 0) | b2
                conflict_by_tree[j][t1] = conflict_by_tree[j].get(t1, 0) | b1
                conflict_degree[i] += 1
                conflict_degree[j] += 1

    def is_singleton(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def singleton_index(mask):
        return (mask & -mask).bit_length() - 1

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def propagate(domains):
        domains = list(domains)
        processed_singletons = set()

        def propagate_lines(line_masks, targets, coord_of_candidate):
            changed = False
            for line_idx, line_mask in enumerate(line_masks):
                assigned = 0
                possible = []
                forced_count = 0

                for t, dm in enumerate(domains):
                    if is_singleton(dm):
                        idx = singleton_index(dm)
                        if coord_of_candidate[idx] == line_idx:
                            assigned += 1
                    else:
                        in_line = dm & line_mask
                        if in_line:
                            forced = (in_line == dm)
                            possible.append((t, in_line, forced))
                            if forced:
                                forced_count += 1

                need = targets[line_idx] - assigned

                if need < 0 or need > len(possible):
                    return None
                if forced_count > need:
                    return None

                if need == 0:
                    for t, in_line, _ in possible:
                        new_dm = domains[t] & ~in_line
                        if new_dm == 0:
                            return None
                        if new_dm != domains[t]:
                            domains[t] = new_dm
                            changed = True
                elif need == len(possible):
                    for t, in_line, _ in possible:
                        new_dm = in_line
                        if new_dm == 0:
                            return None
                        if new_dm != domains[t]:
                            domains[t] = new_dm
                            changed = True
                elif forced_count == need:
                    for t, in_line, forced in possible:
                        if not forced:
                            new_dm = domains[t] & ~in_line
                            if new_dm == 0:
                                return None
                            if new_dm != domains[t]:
                                domains[t] = new_dm
                                changed = True
            return changed

        while True:
            progress = False

            for t, dm in enumerate(domains):
                if dm == 0:
                    return None
                if is_singleton(dm):
                    idx = singleton_index(dm)
                    if idx not in processed_singletons:
                        processed_singletons.add(idx)
                        for ot, banned in conflict_by_tree[idx].items():
                            new_dm = domains[ot] & ~banned
                            if new_dm == 0:
                                return None
                            if new_dm != domains[ot]:
                                domains[ot] = new_dm
                                progress = True

            row_result = propagate_lines(row_masks, row_targets, cand_row)
            if row_result is None:
                return None
            if row_result:
                progress = True

            col_result = propagate_lines(col_masks, col_targets, cand_col)
            if col_result is None:
                return None
            if col_result:
                progress = True

            if not progress:
                break

        return domains

    def verify_solution(domains):
        if any(not is_singleton(dm) for dm in domains):
            return False

        tents = []
        row_counts = [0] * R
        col_counts = [0] * C

        for t, dm in enumerate(domains):
            idx = singleton_index(dm)
            r, c = cand_cells[idx]
            tents.append((r, c, t))
            row_counts[r] += 1
            col_counts[c] += 1

            if tree_grid[r][c] == 'T':
                return False
            if adj_tree_count[r][c] != 1:
                return False

            tr, tc = trees[t]
            if abs(tr - r) + abs(tc - c) != 1:
                return False

        if row_counts != row_targets or col_counts != col_targets:
            return False

        tent_positions = [(r, c) for r, c, _ in tents]
        for i in range(len(tent_positions)):
            r1, c1 = tent_positions[i]
            for j in range(i + 1, len(tent_positions)):
                r2, c2 = tent_positions[j]
                if max(abs(r1 - r2), abs(c1 - c2)) <= 1:
                    return False

        return True

    dead = set()

    def choose_branch_tree(domains):
        best_t = None
        best_key = None
        for t, dm in enumerate(domains):
            bc = dm.bit_count()
            if bc <= 1:
                continue
            impact = 0
            for idx in iter_bits(dm):
                impact += conflict_degree[idx]
            key = (bc, -impact)
            if best_key is None or key < best_key:
                best_key = key
                best_t = t
        return best_t

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        key = tuple(domains)
        if key in dead:
            return None

        done = True
        for dm in domains:
            if not is_singleton(dm):
                done = False
                break

        if done:
            return domains if verify_solution(domains) else None

        t = choose_branch_tree(domains)
        if t is None:
            dead.add(key)
            return None

        options = list(iter_bits(domains[t]))
        options.sort(key=lambda idx: (-conflict_degree[idx], cand_row[idx], cand_col[idx]))

        for idx in options:
            new_domains = list(domains)
            new_domains[t] = 1 << idx
            result = search(new_domains)
            if result is not None:
                return result

        dead.add(key)
        return None

    result = search(tree_masks)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(C)] for _ in range(R)]
    for dm in result:
        idx = singleton_index(dm)
        r, c = cand_cells[idx]
        answer[r][c] = 't'

    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

