from collections import defaultdict

U, R, D, L = 1, 2, 4, 8
DIRS = (U, R, D, L)
DR = {U: -1, R: 0, D: 1, L: 0}
DC = {U: 0, R: 1, D: 0, L: -1}
OPP = {U: D, R: L, D: U, L: R}

EMPTY = 0
TURN_MASKS = (U | R, R | D, D | L, L | U)   # 3,6,12,9
STRAIGHT_MASKS = (U | D, L | R)              # 5,10
VALID_MASKS = (EMPTY,) + TURN_MASKS + STRAIGHT_MASKS
ALL_VALID_BITS = sum(1 << m for m in VALID_MASKS)
EMPTY_BIT = 1 << EMPTY
USED_BITS = ALL_VALID_BITS ^ EMPTY_BIT

INCLUDE_BITS = {d: sum(1 << m for m in VALID_MASKS if m & d) for d in DIRS}
EXCLUDE_BITS = {d: ALL_VALID_BITS ^ INCLUDE_BITS[d] for d in DIRS}

TURN_SET = set(TURN_MASKS)
STRAIGHT_SET = set(STRAIGHT_MASKS)

def solve(observation):
    data = observation['data']
    h = len(data)
    if h == 0:
        return "No Solution"
    w = len(data[0])
    if any(len(row) != w for row in data):
        return "No Solution"

    def vid(r, c):
        return r * w + c

    def rc(v):
        return divmod(v, w)

    def move(r, c, d, steps=1):
        return r + DR[d] * steps, c + DC[d] * steps

    def in_bounds(r, c):
        return 0 <= r < h and 0 <= c < w

    def axis_straight(d):
        return U | D if d in (U, D) else L | R

    def perpendiculars(d):
        return (L, R) if d in (U, D) else (U, D)

    def state_dirs(mask):
        return [d for d in DIRS if mask & d]

    def bits_iter(x):
        while x:
            b = x & -x
            yield b.bit_length() - 1
            x ^= b

    def is_singleton_domain(dom):
        return dom != 0 and (dom & (dom - 1)) == 0

    def singleton_state(dom):
        return dom.bit_length() - 1 if is_singleton_domain(dom) else None

    # Build edge list once.
    edges = []
    for r in range(h):
        for c in range(w):
            v = vid(r, c)
            if c + 1 < w:
                edges.append((v, vid(r, c + 1), R, L))
            if r + 1 < h:
                edges.append((v, vid(r + 1, c), D, U))

    # Base domains from boundary + clue type.
    domains0 = [0] * (h * w)
    clue_info = []
    clue_vids = []
    for r in range(h):
        for c in range(w):
            possible_dirs = 0
            for d in DIRS:
                nr, nc = move(r, c, d)
                if in_bounds(nr, nc):
                    possible_dirs |= d

            allowed = []
            for m in VALID_MASKS:
                if m & ~possible_dirs:
                    continue
                allowed.append(m)

            token = data[r][c]
            if token is not None:
                color = token[0]
                k = int(token[1:])
                if color == 'W':
                    allowed = [m for m in allowed if m in STRAIGHT_SET]
                elif color == 'B':
                    allowed = [m for m in allowed if m in TURN_SET]
                else:
                    return "No Solution"
                clue_info.append((r, c, color, k))
                clue_vids.append(vid(r, c))

            dom = 0
            for m in allowed:
                dom |= 1 << m
            domains0[vid(r, c)] = dom

    if any(dom == 0 for dom in domains0):
        return "No Solution"

    # Human-like clue templating:
    # each candidate explicitly describes the straight arms implied by a clue.
    clue_candidates = []
    clue_candidate_clue_state = []

    def add_req(req, v, s):
        if v in req:
            return req[v] == s
        req[v] = s
        return True

    def candidate_ok(req):
        for v, s in req.items():
            if not (domains0[v] & (1 << s)):
                return False
        return True

    for (r, c, color, k) in clue_info:
        candidates = []
        candidate_states = []
        seen = set()

        if color == 'W':
            # Horizontal run: left length a, right length b, a+b=k.
            for a in range(1, k):
                b = k - a
                if c - a >= 0 and c + b < w:
                    for left_exit in perpendiculars(L):
                        for right_exit in perpendiculars(R):
                            req = {}
                            ok = True
                            ok &= add_req(req, vid(r, c), L | R)
                            for i in range(1, a):
                                ok &= add_req(req, vid(r, c - i), L | R)
                            for i in range(1, b):
                                ok &= add_req(req, vid(r, c + i), L | R)
                            ok &= add_req(req, vid(r, c - a), OPP(L) | left_exit)   # endpoint points to clue with R
                            ok &= add_req(req, vid(r, c + b), OPP(R) | right_exit)  # endpoint points to clue with L
                            if ok and candidate_ok(req):
                                key = tuple(sorted(req.items()))
                                if key not in seen:
                                    seen.add(key)
                                    candidates.append(req)
                                    candidate_states.append(L | R)

                # Vertical run: up length a, down length b, a+b=k.
                if r - a >= 0 and r + b < h:
                    for up_exit in perpendiculars(U):
                        for down_exit in perpendiculars(D):
                            req = {}
                            ok = True
                            ok &= add_req(req, vid(r, c), U | D)
                            for i in range(1, a):
                                ok &= add_req(req, vid(r - i, c), U | D)
                            for i in range(1, b):
                                ok &= add_req(req, vid(r + i, c), U | D)
                            ok &= add_req(req, vid(r - a, c), OPP(U) | up_exit)     # endpoint points to clue with D
                            ok &= add_req(req, vid(r + b, c), OPP(D) | down_exit)   # endpoint points to clue with U
                            if ok and candidate_ok(req):
                                key = tuple(sorted(req.items()))
                                if key not in seen:
                                    seen.add(key)
                                    candidates.append(req)
                                    candidate_states.append(U | D)

        else:
            # Black clue is a turn; choose turn shape, then split k across its two outgoing arms.
            for clue_state in TURN_MASKS:
                dirs = state_dirs(clue_state)
                d1, d2 = dirs[0], dirs[1]
                for a in range(1, k):
                    b = k - a

                    er1, ec1 = move(r, c, d1, a)
                    er2, ec2 = move(r, c, d2, b)
                    if not (in_bounds(er1, ec1) and in_bounds(er2, ec2)):
                        continue

                    for exit1 in perpendiculars(d1):
                        for exit2 in perpendiculars(d2):
                            req = {}
                            ok = True
                            ok &= add_req(req, vid(r, c), clue_state)

                            for i in range(1, a):
                                rr, cc = move(r, c, d1, i)
                                ok &= add_req(req, vid(rr, cc), axis_straight(d1))
                            for i in range(1, b):
                                rr, cc = move(r, c, d2, i)
                                ok &= add_req(req, vid(rr, cc), axis_straight(d2))

                            ok &= add_req(req, vid(er1, ec1), OPP(d1) | exit1)
                            ok &= add_req(req, vid(er2, ec2), OPP(d2) | exit2)

                            if ok and candidate_ok(req):
                                key = tuple(sorted(req.items()))
                                if key not in seen:
                                    seen.add(key)
                                    candidates.append(req)
                                    candidate_states.append(clue_state)

        if not candidates:
            return "No Solution"

        clue_candidates.append(candidates)
        clue_candidate_clue_state.append(candidate_states)

    clue_count = len(clue_info)
    clue_domains0 = [(1 << len(clue_candidates[i])) - 1 for i in range(clue_count)]

    def arc_consistency(domains):
        changed = True
        while changed:
            changed = False
            for v, w2, d, od in edges:
                dv = domains[v]
                dw = domains[w2]

                new_dv = 0
                if dw & INCLUDE_BITS[od]:
                    new_dv |= dv & INCLUDE_BITS[d]
                if dw & EXCLUDE_BITS[od]:
                    new_dv |= dv & EXCLUDE_BITS[d]

                new_dw = 0
                if dv & INCLUDE_BITS[d]:
                    new_dw |= dw & INCLUDE_BITS[od]
                if dv & EXCLUDE_BITS[d]:
                    new_dw |= dw & EXCLUDE_BITS[od]

                if new_dv == 0 or new_dw == 0:
                    return False

                if new_dv != dv:
                    domains[v] = new_dv
                    changed = True
                if new_dw != dw:
                    domains[w2] = new_dw
                    changed = True
        return True

    def forced_cycle_exists(domains):
        adj = defaultdict(list)
        used_vertices = set()

        for v, w2, d, od in edges:
            dv = domains[v]
            dw = domains[w2]
            forced_present = ((dv & EXCLUDE_BITS[d]) == 0) and ((dw & EXCLUDE_BITS[od]) == 0)
            if forced_present:
                adj[v].append(w2)
                adj[w2].append(v)
                used_vertices.add(v)
                used_vertices.add(w2)

        seen = set()
        for start in used_vertices:
            if start in seen:
                continue
            stack = [start]
            comp = []
            seen.add(start)
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)

            if comp and all(len(adj[x]) == 2 for x in comp):
                comp_set = set(comp)
                outside_can_be_used = False
                for v in range(h * w):
                    if v not in comp_set and (domains[v] & USED_BITS):
                        outside_can_be_used = True
                        break
                if outside_can_be_used:
                    return True
        return False

    def propagate(domains, clue_domains):
        changed = True
        while changed:
            changed = False

            if not arc_consistency(domains):
                return False

            for i in range(clue_count):
                old_cd = clue_domains[i]
                new_cd = 0
                rem = []

                for j in bits_iter(old_cd):
                    req = clue_candidates[i][j]
                    ok = True
                    for v, s in req.items():
                        if not (domains[v] & (1 << s)):
                            ok = False
                            break
                    if ok:
                        new_cd |= 1 << j
                        rem.append(j)

                if new_cd == 0:
                    return False

                if new_cd != old_cd:
                    clue_domains[i] = new_cd
                    changed = True

                # Restrict clue cell to the union of clue states among remaining candidates.
                cr, cc, _, _ = clue_info[i]
                cv = vid(cr, cc)
                poss = 0
                for j in rem:
                    poss |= 1 << clue_candidate_clue_state[i][j]
                nd = domains[cv] & poss
                if nd == 0:
                    return False
                if nd != domains[cv]:
                    domains[cv] = nd
                    changed = True

                # Intersect exact requirements common to every remaining candidate.
                if rem:
                    common = dict(clue_candidates[i][rem[0]])
                    for j in rem[1:]:
                        req = clue_candidates[i][j]
                        for v in list(common.keys()):
                            if req.get(v) != common[v]:
                                del common[v]
                    for v, s in common.items():
                        nd = domains[v] & (1 << s)
                        if nd == 0:
                            return False
                        if nd != domains[v]:
                            domains[v] = nd
                            changed = True

            if not arc_consistency(domains):
                return False

            if forced_cycle_exists(domains):
                return False

        return True

    def validate_full(domains):
        states = [singleton_state(dom) for dom in domains]
        if any(s is None for s in states):
            return None

        # Edge consistency / build adjacency.
        adj = [[] for _ in range(h * w)]
        for r in range(h):
            for c in range(w):
                v = vid(r, c)
                s = states[v]
                for d in DIRS:
                    nr, nc = move(r, c, d)
                    if not in_bounds(nr, nc):
                        if s & d:
                            return None
                        continue
                    wv = vid(nr, nc)
                    sw = states[wv]
                    if bool(s & d) != bool(sw & OPP[d]):
                        return None
                    if (s & d) and v < wv:
                        adj[v].append(wv)
                        adj[wv].append(v)

        used = [v for v in range(h * w) if states[v] != EMPTY]
        if not used:
            return None
        if any(len(adj[v]) not in (0, 2) for v in range(h * w)):
            return None
        if any(states[cv] == EMPTY for cv in clue_vids):
            return None

        # Single connected component of used vertices.
        start = used[0]
        stack = [start]
        seen = {start}
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        if any(v not in seen for v in used):
            return None

        def walk_length(start_v, d):
            cur = start_v
            length = 0
            while True:
                r0, c0 = rc(cur)
                nr, nc = move(r0, c0, d)
                if not in_bounds(nr, nc):
                    return None
                nxt = vid(nr, nc)
                length += 1
                st = states[nxt]
                if st in TURN_SET:
                    return length
                if st not in STRAIGHT_SET:
                    return None
                if not (st & d and st & OPP[d]):
                    return None
                cur = nxt

        # Re-check all clue conditions directly from final loop.
        for r, c, color, k in clue_info:
            v = vid(r, c)
            st = states[v]
            dirs = state_dirs(st)
            if len(dirs) != 2:
                return None
            if color == 'W':
                if st not in STRAIGHT_SET:
                    return None
                if dirs[0] == OPP[dirs[1]] or dirs[1] == OPP[dirs[0]]:
                    pass
                else:
                    return None
            else:
                if st not in TURN_SET:
                    return None
                if dirs[0] == OPP[dirs[1]] or dirs[1] == OPP[dirs[0]]:
                    return None

            total = 0
            for d in dirs:
                length = walk_length(v, d)
                if length is None:
                    return None
                total += length
            if total != k:
                return None

        # Recover ordered loop.
        loop_start = min(used)
        path = [rc(loop_start)]
        prev = None
        cur = loop_start
        while True:
            nbs = adj[cur]
            if len(nbs) != 2:
                return None
            nxt = nbs[0] if nbs[0] != prev else nbs[1]
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if cur == loop_start:
                break

        return path

    def choose_clue(clue_domains):
        best = None
        best_count = 10**9
        for i, cd in enumerate(clue_domains):
            cnt = cd.bit_count()
            if 1 < cnt < best_count:
                best_count = cnt
                best = i
        return best

    def choose_vertex(domains):
        best = None
        best_score = (10**9, -1)
        for v, dom in enumerate(domains):
            cnt = dom.bit_count()
            if cnt <= 1:
                continue
            # Prefer smaller domain, then more neighboring constraints.
            r, c = rc(v)
            deg = sum(1 for d in DIRS if in_bounds(r + DR[d], c + DC[d]))
            score = (cnt, -deg)
            if score < best_score:
                best_score = score
                best = v
        return best

    def search(domains, clue_domains):
        if not propagate(domains, clue_domains):
            return None

        solved = validate_full(domains)
        if solved is not None:
            return solved

        clue_choice = choose_clue(clue_domains)
        if clue_choice is not None:
            rem = list(bits_iter(clue_domains[clue_choice]))
            rem.sort(key=lambda j: -len(clue_candidates[clue_choice][j]))
            for j in rem:
                nd = domains[:]
                ncd = clue_domains[:]
                ncd[clue_choice] = 1 << j
                ans = search(nd, ncd)
                if ans is not None:
                    return ans
            return None

        v = choose_vertex(domains)
        if v is None:
            return None

        dom = domains[v]
        branches = []

        # First split on empty vs used when possible; this is usually the strongest binary deduction.
        if (dom & EMPTY_BIT) and (dom & USED_BITS):
            branches.append(dom & USED_BITS)
            branches.append(EMPTY_BIT)
        else:
            vals = list(bits_iter(dom))
            # Prefer non-empty exact states before empty.
            vals.sort(key=lambda s: (s == EMPTY, s))
            for s in vals:
                branches.append(1 << s)

        for bdom in branches:
            nd = domains[:]
            ncd = clue_domains[:]
            nd[v] = bdom
            ans = search(nd, ncd)
            if ans is not None:
                return ans

        return None

    result = search(domains0[:], clue_domains0[:])
    return result if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, 'W', None, None, 'W', None, 'W', None], ['B', None, None, None, None, 'W', 'W', None], [None, None, 'W', None, None, None, 'W', None], [None, None, None, None, None, 'B', None, 'W'], [None, None, 'W', 'W', None, None, None, None], [None, 'W', None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B']]}

# General Masyu-on-dots solver.
# The loop runs on orthogonal edges between adjacent dot coordinates.
# Each dot has degree 0 or 2, all clue dots have degree 2.
# White clue: straight through, and at least one adjacent step along the loop turns.
# Black clue: turn, and both adjacent steps along the loop go straight.

N_BIT = 1
E_BIT = 2
S_BIT = 4
W_BIT = 8

DIRS = (N_BIT, E_BIT, S_BIT, W_BIT)
DRDC = {
    N_BIT: (-1, 0),
    E_BIT: (0, 1),
    S_BIT: (1, 0),
    W_BIT: (0, -1),
}
OPP = {
    N_BIT: S_BIT,
    E_BIT: W_BIT,
    S_BIT: N_BIT,
    W_BIT: E_BIT,
}

MASK_0 = 0
MASK_NS = N_BIT | S_BIT
MASK_EW = E_BIT | W_BIT
MASK_NE = N_BIT | E_BIT
MASK_NW = N_BIT | W_BIT
MASK_SE = S_BIT | E_BIT
MASK_SW = S_BIT | W_BIT

VALID_MASKS = (MASK_0, MASK_NS, MASK_EW, MASK_NE, MASK_NW, MASK_SE, MASK_SW)
ALL_VALID_BITS = sum(1 << m for m in VALID_MASKS)
USED_BITS = ALL_VALID_BITS ^ (1 << MASK_0)

USE_EDGE = {d: sum(1 << m for m in VALID_MASKS if (m & d)) for d in DIRS}
NO_EDGE = {d: ALL_VALID_BITS ^ USE_EDGE[d] for d in DIRS}

TURN_BITS = (1 << MASK_NE) | (1 << MASK_NW) | (1 << MASK_SE) | (1 << MASK_SW)
STRAIGHT_BITS = (1 << MASK_NS) | (1 << MASK_EW)
NS_BITSET = 1 << MASK_NS
EW_BITSET = 1 << MASK_EW

WHITE_BASE = NS_BITSET | EW_BITSET
BLACK_BASE = (1 << MASK_NE) | (1 << MASK_NW) | (1 << MASK_SE) | (1 << MASK_SW)
NORMAL_BASE = ALL_VALID_BITS

WHITE_NS_N_ANY = NS_BITSET | (1 << MASK_SE) | (1 << MASK_SW)
WHITE_NS_N_TURN = (1 << MASK_SE) | (1 << MASK_SW)
WHITE_NS_S_ANY = NS_BITSET | (1 << MASK_NE) | (1 << MASK_NW)
WHITE_NS_S_TURN = (1 << MASK_NE) | (1 << MASK_NW)

WHITE_EW_W_ANY = EW_BITSET | (1 << MASK_NE) | (1 << MASK_SE)
WHITE_EW_W_TURN = (1 << MASK_NE) | (1 << MASK_SE)
WHITE_EW_E_ANY = EW_BITSET | (1 << MASK_NW) | (1 << MASK_SW)
WHITE_EW_E_TURN = (1 << MASK_NW) | (1 << MASK_SW)


def bit_count(x):
    return x.bit_count()


def is_singleton(dom):
    return dom != 0 and (dom & (dom - 1)) == 0


def singleton_mask(dom):
    return dom.bit_length() - 1


def mask_uses(mask, d):
    return (mask & d) != 0


def iter_masks(dom):
    for m in VALID_MASKS:
        if dom & (1 << m):
            yield m


def solve(observation):
    data = observation['data']
    n = len(data)
    vcount = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    neighbors = [{} for _ in range(vcount)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            for d, (dr, dc) in DRDC.items():
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    neighbors[i][d] = idx(rr, cc)

    clue = [None] * vcount
    domains0 = [0] * vcount

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            t = data[r][c]
            clue[i] = t
            if t == 'W':
                dom = WHITE_BASE
            elif t == 'B':
                dom = BLACK_BASE
            else:
                dom = NORMAL_BASE

            # Boundary feasibility.
            for m in VALID_MASKS:
                if dom & (1 << m):
                    ok = True
                    for d in DIRS:
                        if (m & d) and d not in neighbors[i]:
                            ok = False
                            break
                    if not ok:
                        dom &= ~(1 << m)

            if dom == 0:
                return "No Solution"
            domains0[i] = dom

    required_vertices = [i for i in range(vcount) if clue[i] is not None]

    def possible_edge(domains, i, d, j):
        return (domains[i] & USE_EDGE[d]) and (domains[j] & USE_EDGE[OPP[d]])

    def forced_on_edge(domains, i, d):
        return (domains[i] & NO_EDGE[d]) == 0

    def possible_used(dom):
        return (dom & USED_BITS) != 0

    def required_used(dom):
        return (dom & (1 << MASK_0)) == 0

    def white_mask_supported(domains, i, mask):
        r, c = rc(i)
        if mask == MASK_NS:
            if N_BIT not in neighbors[i] or S_BIT not in neighbors[i]:
                return False
            ni = neighbors[i][N_BIT]
            si = neighbors[i][S_BIT]
            nd = domains[ni]
            sd = domains[si]
            north_any = nd & WHITE_NS_N_ANY
            south_any = sd & WHITE_NS_S_ANY
            north_turn = nd & WHITE_NS_N_TURN
            south_turn = sd & WHITE_NS_S_TURN
            return bool(north_any and south_any and (north_turn or south_turn))
        if mask == MASK_EW:
            if W_BIT not in neighbors[i] or E_BIT not in neighbors[i]:
                return False
            wi = neighbors[i][W_BIT]
            ei = neighbors[i][E_BIT]
            wd = domains[wi]
            ed = domains[ei]
            west_any = wd & WHITE_EW_W_ANY
            east_any = ed & WHITE_EW_E_ANY
            west_turn = wd & WHITE_EW_W_TURN
            east_turn = ed & WHITE_EW_E_TURN
            return bool(west_any and east_any and (west_turn or east_turn))
        return False

    def black_mask_supported(domains, i, mask):
        if mask == MASK_NE:
            return (
                N_BIT in neighbors[i] and E_BIT in neighbors[i] and
                (domains[neighbors[i][N_BIT]] & NS_BITSET) and
                (domains[neighbors[i][E_BIT]] & EW_BITSET)
            )
        if mask == MASK_NW:
            return (
                N_BIT in neighbors[i] and W_BIT in neighbors[i] and
                (domains[neighbors[i][N_BIT]] & NS_BITSET) and
                (domains[neighbors[i][W_BIT]] & EW_BITSET)
            )
        if mask == MASK_SE:
            return (
                S_BIT in neighbors[i] and E_BIT in neighbors[i] and
                (domains[neighbors[i][S_BIT]] & NS_BITSET) and
                (domains[neighbors[i][E_BIT]] & EW_BITSET)
            )
        if mask == MASK_SW:
            return (
                S_BIT in neighbors[i] and W_BIT in neighbors[i] and
                (domains[neighbors[i][S_BIT]] & NS_BITSET) and
                (domains[neighbors[i][W_BIT]] & EW_BITSET)
            )
        return False

    def apply_singleton_clue_neighbor_rules(domains):
        changed = False
        for i in required_vertices:
            dom = domains[i]
            if not is_singleton(dom):
                continue
            m = singleton_mask(dom)
            if clue[i] == 'W':
                if m == MASK_NS:
                    ni = neighbors[i].get(N_BIT)
                    si = neighbors[i].get(S_BIT)
                    if ni is None or si is None:
                        return None
                    nd = domains[ni] & WHITE_NS_N_ANY
                    sd = domains[si] & WHITE_NS_S_ANY
                    if nd == 0 or sd == 0:
                        return None
                    if (nd & WHITE_NS_N_TURN) == 0:
                        sd2 = sd & WHITE_NS_S_TURN
                        if sd2 == 0:
                            return None
                        sd = sd2
                    if (sd & WHITE_NS_S_TURN) == 0:
                        nd2 = nd & WHITE_NS_N_TURN
                        if nd2 == 0:
                            return None
                        nd = nd2
                    if nd != domains[ni]:
                        domains[ni] = nd
                        changed = True
                    if sd != domains[si]:
                        domains[si] = sd
                        changed = True
                elif m == MASK_EW:
                    wi = neighbors[i].get(W_BIT)
                    ei = neighbors[i].get(E_BIT)
                    if wi is None or ei is None:
                        return None
                    wd = domains[wi] & WHITE_EW_W_ANY
                    ed = domains[ei] & WHITE_EW_E_ANY
                    if wd == 0 or ed == 0:
                        return None
                    if (wd & WHITE_EW_W_TURN) == 0:
                        ed2 = ed & WHITE_EW_E_TURN
                        if ed2 == 0:
                            return None
                        ed = ed2
                    if (ed & WHITE_EW_E_TURN) == 0:
                        wd2 = wd & WHITE_EW_W_TURN
                        if wd2 == 0:
                            return None
                        wd = wd2
                    if wd != domains[wi]:
                        domains[wi] = wd
                        changed = True
                    if ed != domains[ei]:
                        domains[ei] = ed
                        changed = True
            elif clue[i] == 'B':
                if m == MASK_NE:
                    ni = neighbors[i].get(N_BIT)
                    ei = neighbors[i].get(E_BIT)
                    if ni is None or ei is None:
                        return None
                    nd = domains[ni] & NS_BITSET
                    ed = domains[ei] & EW_BITSET
                    if nd == 0 or ed == 0:
                        return None
                    if nd != domains[ni]:
                        domains[ni] = nd
                        changed = True
                    if ed != domains[ei]:
                        domains[ei] = ed
                        changed = True
                elif m == MASK_NW:
                    ni = neighbors[i].get(N_BIT)
                    wi = neighbors[i].get(W_BIT)
                    if ni is None or wi is None:
                        return None
                    nd = domains[ni] & NS_BITSET
                    wd = domains[wi] & EW_BITSET
                    if nd == 0 or wd == 0:
                        return None
                    if nd != domains[ni]:
                        domains[ni] = nd
                        changed = True
                    if wd != domains[wi]:
                        domains[wi] = wd
                        changed = True
                elif m == MASK_SE:
                    si = neighbors[i].get(S_BIT)
                    ei = neighbors[i].get(E_BIT)
                    if si is None or ei is None:
                        return None
                    sd = domains[si] & NS_BITSET
                    ed = domains[ei] & EW_BITSET
                    if sd == 0 or ed == 0:
                        return None
                    if sd != domains[si]:
                        domains[si] = sd
                        changed = True
                    if ed != domains[ei]:
                        domains[ei] = ed
                        changed = True
                elif m == MASK_SW:
                    si = neighbors[i].get(S_BIT)
                    wi = neighbors[i].get(W_BIT)
                    if si is None or wi is None:
                        return None
                    sd = domains[si] & NS_BITSET
                    wd = domains[wi] & EW_BITSET
                    if sd == 0 or wd == 0:
                        return None
                    if sd != domains[si]:
                        domains[si] = sd
                        changed = True
                    if wd != domains[wi]:
                        domains[wi] = wd
                        changed = True
        return changed

    def global_checks(domains):
        # Connectivity of all definitely-used vertices through possibly-on edges.
        req = [i for i in range(vcount) if required_used(domains[i])]
        if req:
            parent = list(range(vcount))

            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x

            def union(a, b):
                ra, rb = find(a), find(b)
                if ra != rb:
                    parent[rb] = ra

            for i in range(vcount):
                if not possible_used(domains[i]):
                    continue
                for d, j in neighbors[i].items():
                    if i < j and possible_used(domains[j]) and possible_edge(domains, i, d, j):
                        union(i, j)

            root = find(req[0])
            for i in req[1:]:
                if find(i) != root:
                    return False

        # Forced-on cycle detection.
        forced_adj = [[] for _ in range(vcount)]
        forced_deg = [0] * vcount
        for i in range(vcount):
            for d, j in neighbors[i].items():
                if i < j and forced_on_edge(domains, i, d):
                    forced_adj[i].append(j)
                    forced_adj[j].append(i)
                    forced_deg[i] += 1
                    forced_deg[j] += 1
                    if forced_deg[i] > 2 or forced_deg[j] > 2:
                        return False

        seen = [False] * vcount
        locked_cycle_vertices = None
        for i in range(vcount):
            if seen[i] or forced_deg[i] == 0:
                continue
            stack = [i]
            comp = []
            seen[i] = True
            all_deg2 = True
            while stack:
                x = stack.pop()
                comp.append(x)
                if forced_deg[x] != 2:
                    all_deg2 = False
                for y in forced_adj[x]:
                    if not seen[y]:
                        seen[y] = True
                        stack.append(y)
            if all_deg2:
                comp_set = set(comp)
                if locked_cycle_vertices is not None:
                    return False
                for k in range(vcount):
                    if k not in comp_set and required_used(domains[k]):
                        return False
                locked_cycle_vertices = comp_set

        return True

    def propagate(domains):
        while True:
            changed = False

            # Edge consistency.
            for i in range(vcount):
                dom = domains[i]
                new_dom = dom
                for d, j in neighbors[i].items():
                    dj = domains[j]
                    if (dj & USE_EDGE[OPP[d]]) == 0:
                        new_dom &= NO_EDGE[d]
                    if (dj & NO_EDGE[OPP[d]]) == 0:
                        new_dom &= USE_EDGE[d]
                if new_dom == 0:
                    return None
                if new_dom != dom:
                    domains[i] = new_dom
                    changed = True

            # Clue mask support.
            for i in required_vertices:
                dom = domains[i]
                new_dom = dom
                if clue[i] == 'W':
                    if dom & NS_BITSET and not white_mask_supported(domains, i, MASK_NS):
                        new_dom &= ~NS_BITSET
                    if dom & EW_BITSET and not white_mask_supported(domains, i, MASK_EW):
                        new_dom &= ~EW_BITSET
                else:
                    if dom & (1 << MASK_NE) and not black_mask_supported(domains, i, MASK_NE):
                        new_dom &= ~(1 << MASK_NE)
                    if dom & (1 << MASK_NW) and not black_mask_supported(domains, i, MASK_NW):
                        new_dom &= ~(1 << MASK_NW)
                    if dom & (1 << MASK_SE) and not black_mask_supported(domains, i, MASK_SE):
                        new_dom &= ~(1 << MASK_SE)
                    if dom & (1 << MASK_SW) and not black_mask_supported(domains, i, MASK_SW):
                        new_dom &= ~(1 << MASK_SW)
                if new_dom == 0:
                    return None
                if new_dom != dom:
                    domains[i] = new_dom
                    changed = True

            # Strong singleton clue propagation.
            res = apply_singleton_clue_neighbor_rules(domains)
            if res is None:
                return None
            if res:
                changed = True

            if not global_checks(domains):
                return None

            if not changed:
                return domains

    def choose_var(domains):
        best = None
        best_key = None
        for i in range(vcount):
            dom = domains[i]
            sz = bit_count(dom)
            if sz <= 1:
                continue
            # Priority:
            # 1) clue vertices
            # 2) vertices that must be used
            # 3) smaller domain
            # 4) more constrained by possible edges
            is_clue = 0 if clue[i] is not None else 1
            must_use = 0 if required_used(dom) else 1
            poss_edges = 0
            for d, j in neighbors[i].items():
                if possible_edge(domains, i, d, j):
                    poss_edges += 1
            key = (is_clue, must_use, sz, poss_edges)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def ordered_masks_for_var(domains, i):
        dom = domains[i]
        ms = list(iter_masks(dom))
        # Favor clue-consistent informative masks first.
        if clue[i] == 'W':
            return [m for m in (MASK_NS, MASK_EW) if dom & (1 << m)]
        if clue[i] == 'B':
            order = (MASK_NE, MASK_NW, MASK_SE, MASK_SW)
            return [m for m in order if dom & (1 << m)]
        # For ordinary vertices: favor used states over unused when forced structure is dense.
        # This often closes deductions faster.
        used = [m for m in ms if m != MASK_0]
        unused = [m for m in ms if m == MASK_0]
        return used + unused

    def final_solution(domains):
        masks = []
        for dom in domains:
            if not is_singleton(dom):
                return None
            masks.append(singleton_mask(dom))

        used_vertices = [i for i, m in enumerate(masks) if m != MASK_0]
        if not used_vertices:
            return None

        adj = [[] for _ in range(vcount)]
        edge_count = 0
        for i in range(vcount):
            m = masks[i]
            deg = 0
            for d, j in neighbors[i].items():
                uses = bool(m & d)
                if uses != bool(masks[j] & OPP[d]):
                    return None
                if uses:
                    deg += 1
                    if i < j:
                        adj[i].append(j)
                        adj[j].append(i)
                        edge_count += 1
            if (m == MASK_0 and deg != 0) or (m != MASK_0 and deg != 2):
                return None

        # Single cycle over all used vertices.
        start = used_vertices[0]
        stack = [start]
        seen = {start}
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        if len(seen) != len(used_vertices):
            return None
        if edge_count != len(used_vertices):
            return None

        # Reconstruct ordered cycle.
        path = []
        prev = None
        cur = start
        while True:
            path.append(rc(cur))
            nbrs = adj[cur]
            if prev is None:
                nxt = nbrs[0]
            else:
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
            prev, cur = cur, nxt
            if cur == start:
                path.append(rc(start))
                break

        # Sanity: all clue vertices must be on the loop.
        for i in required_vertices:
            if masks[i] == MASK_0:
                return None
        return path

    def dfs(domains):
        domains = propagate(domains[:])
        if domains is None:
            return None

        sol = final_solution(domains)
        if sol is not None:
            return sol

        i = choose_var(domains)
        if i is None:
            return None

        for m in ordered_masks_for_var(domains, i):
            nd = domains[:]
            nd[i] = 1 << m
            ans = dfs(nd)
            if ans is not None:
                return ans
        return None

    ans = dfs(domains0)
    return ans if ans is not None else "No Solution"


