    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1, 1, 2, 2, 2], [0, 0, 1, 1, 2, 2, 2, 2, 2, 2], [3, 3, 3, 3, 2, 2, 2, 2, 2, 2], [3, 3, 3, 3, 2, 2, 2, 2, 2, 2], [3, 3, 3, 3, 2, 2, 2, 2, 2, 2], [3, 4, 4, 4, 6, 6, 6, 7, 7, 2], [3, 4, 4, 4, 4, 6, 6, 7, 7, 2], [3, 4, 4, 4, 4, 6, 10, 7, 7, 7], [3, 4, 4, 4, 4, 6, 10, 7, 7, 10], [4, 4, 4, 4, 4, 6, 10, 10, 10, 10]]}

from collections import defaultdict, deque

# ---- Tetromino geometry -----------------------------------------------------

def _normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

def _rot(cells):
    return [(-c, r) for r, c in cells]

def _ref(cells):
    return [(r, -c) for r, c in cells]

def _all_orientations(base):
    seen = set()
    cur = list(base)
    for _ in range(4):
        seen.add(_normalize(cur))
        seen.add(_normalize(_ref(cur)))
        cur = _rot(cur)
    return sorted(seen)

BASE_SHAPES = {
    "I": [(0, 0), (0, 1), (0, 2), (0, 3)],
    "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
    "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
    "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
}

ORIENTATIONS = {k: _all_orientations(v) for k, v in BASE_SHAPES.items()}

# ---- Utility ----------------------------------------------------------------

def bit_iter(mask):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length() - 1
        mask ^= lsb

def popcount(x):
    return x.bit_count()

# ---- Solver core -------------------------------------------------------------

def solve(observation):
    data = observation.get("data")
    if not data or not isinstance(data, list) or not all(isinstance(row, list) for row in data):
        return "No Solution"

    R = len(data)
    C = len(data[0])
    if any(len(row) != C for row in data):
        return "No Solution"

    # Region indexing
    region_ids = sorted({v for row in data for v in row})
    reg_index = {rid: i for i, rid in enumerate(region_ids)}
    reg_count = len(region_ids)

    cell_region = [0] * (R * C)
    regions = [[] for _ in range(reg_count)]
    for r in range(R):
        for c in range(C):
            idx = r * C + c
            ri = reg_index[data[r][c]]
            cell_region[idx] = ri
            regions[ri].append(idx)

    # Orth adjacency for cells
    cell_neighbors = [0] * (R * C)
    for r in range(R):
        for c in range(C):
            idx = r * C + c
            mask = 0
            if r > 0:
                mask |= 1 << ((r - 1) * C + c)
            if r + 1 < R:
                mask |= 1 << ((r + 1) * C + c)
            if c > 0:
                mask |= 1 << (r * C + c - 1)
            if c + 1 < C:
                mask |= 1 << (r * C + c + 1)
            cell_neighbors[idx] = mask

    # Region adjacency graph
    region_neighbors = [set() for _ in range(reg_count)]
    for r in range(R):
        for c in range(C):
            a = reg_index[data[r][c]]
            if r + 1 < R:
                b = reg_index[data[r + 1][c]]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)
            if c + 1 < C:
                b = reg_index[data[r][c + 1]]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)

    # 2x2 masks
    square_masks = []
    for r in range(R - 1):
        for c in range(C - 1):
            m = 0
            m |= 1 << (r * C + c)
            m |= 1 << (r * C + c + 1)
            m |= 1 << ((r + 1) * C + c)
            m |= 1 << ((r + 1) * C + c + 1)
            square_masks.append(m)

    def creates_full_2x2(shaded_mask, add_mask):
        union = shaded_mask | add_mask
        for sm in square_masks:
            if (union & sm) == sm:
                return True
        return False

    # Candidate generation: all placements of each tetromino inside each region.
    candidates = []
    reg_cands = [[] for _ in range(reg_count)]
    region_cell_set = [set(cells) for cells in regions]

    for ri in range(reg_count):
        seen = set()
        allowed = region_cell_set[ri]
        for typ, variants in ORIENTATIONS.items():
            for shape in variants:
                max_r = max(r for r, c in shape)
                max_c = max(c for r, c in shape)
                for ar in range(R - max_r):
                    for ac in range(C - max_c):
                        cells = []
                        ok = True
                        for dr, dc in shape:
                            rr, cc = ar + dr, ac + dc
                            idx = rr * C + cc
                            if idx not in allowed:
                                ok = False
                                break
                            cells.append(idx)
                        if ok:
                            key = (typ, tuple(sorted(cells)))
                            if key in seen:
                                continue
                            seen.add(key)
                            cellmask = 0
                            neighmask = 0
                            for idx in cells:
                                cellmask |= 1 << idx
                            for idx in cells:
                                neighmask |= cell_neighbors[idx]
                            cand = {
                                "region": ri,
                                "type": typ,
                                "cells": tuple(sorted(cells)),
                                "cellmask": cellmask,
                                "neighmask": neighmask,
                            }
                            cid = len(candidates)
                            candidates.append(cand)
                            reg_cands[ri].append(cid)

    if any(not reg_cands[ri] for ri in range(reg_count)):
        return "No Solution"

    # Compact per-region local indexing for bitmask domains.
    global_to_local = []
    local_to_global = []
    for ri in range(reg_count):
        g2l = {}
        l2g = []
        for li, cid in enumerate(reg_cands[ri]):
            g2l[cid] = li
            l2g.append(cid)
        global_to_local.append(g2l)
        local_to_global.append(l2g)

    # Candidate metadata by local index
    cand_type = []
    cand_cellmask = []
    cand_neighmask = []
    for ri in range(reg_count):
        cand_type.append([candidates[cid]["type"] for cid in reg_cands[ri]])
        cand_cellmask.append([candidates[cid]["cellmask"] for cid in reg_cands[ri]])
        cand_neighmask.append([candidates[cid]["neighmask"] for cid in reg_cands[ri]])

    # Supports for adjacency-different-type and touching+different-type.
    diff_support = [dict() for _ in range(reg_count)]
    touch_support = [dict() for _ in range(reg_count)]

    for a in range(reg_count):
        for b in region_neighbors[a]:
            if b in diff_support[a]:
                continue
            na = len(reg_cands[a])
            nb = len(reg_cands[b])
            da = [0] * na
            db = [0] * nb
            ta = [0] * na
            tb = [0] * nb
            for ia, cida in enumerate(reg_cands[a]):
                ca = candidates[cida]
                for ib, cidb in enumerate(reg_cands[b]):
                    cb = candidates[cidb]
                    if ca["type"] != cb["type"]:
                        da[ia] |= 1 << ib
                        db[ib] |= 1 << ia
                        if ca["neighmask"] & cb["cellmask"]:
                            ta[ia] |= 1 << ib
                            tb[ib] |= 1 << ia
            diff_support[a][b] = da
            diff_support[b][a] = db
            touch_support[a][b] = ta
            touch_support[b][a] = tb

    all_domain = tuple((1 << len(reg_cands[ri])) - 1 for ri in range(reg_count))

    # Human-like propagation:
    # 1) eliminate region placements that already make a forbidden 2x2 with fixed shading
    # 2) arc-consistency on "adjacent regions must use different tetromino types"
    # 3) possible-touch reachability: every unassigned region must still be connectable
    #    to the currently connected shaded cluster through some chain of touch-capable regions.

    def revise(domains, a, b):
        changed = False
        dom_a = domains[a]
        dom_b = domains[b]
        new_a = dom_a
        support = diff_support[a][b]
        for ia in bit_iter(dom_a):
            if not (support[ia] & dom_b):
                new_a &= ~(1 << ia)
                changed = True
        if changed:
            domains[a] = new_a
        return changed

    def propagate(domains, assigned_mask, shaded_mask):
        # Unary filtering against current fixed shaded cells.
        for ri in range(reg_count):
            if (assigned_mask >> ri) & 1:
                continue
            dom = domains[ri]
            new_dom = dom
            for li in bit_iter(dom):
                if creates_full_2x2(shaded_mask, cand_cellmask[ri][li]):
                    new_dom &= ~(1 << li)
            if new_dom != dom:
                domains[ri] = new_dom
            if not domains[ri]:
                return False

        # Arc consistency for different-type constraint.
        q = deque()
        for a in range(reg_count):
            for b in region_neighbors[a]:
                q.append((a, b))
        while q:
            a, b = q.popleft()
            before = domains[a]
            if revise(domains, a, b):
                if not domains[a]:
                    return False
                if domains[a] != before:
                    for c in region_neighbors[a]:
                        if c != b:
                            q.append((c, a))

        # Touch-graph reachability from the assigned connected component.
        if assigned_mask:
            root = (assigned_mask & -assigned_mask).bit_length() - 1
            seen = {root}
            dq = deque([root])
            while dq:
                a = dq.popleft()
                da = domains[a]
                for b in region_neighbors[a]:
                    if b in seen:
                        continue
                    db = domains[b]
                    possible = False
                    sup = touch_support[a][b]
                    for ia in bit_iter(da):
                        if sup[ia] & db:
                            possible = True
                            break
                    if possible:
                        seen.add(b)
                        dq.append(b)
            if len(seen) != reg_count:
                return False

        return True

    fail_cache = set()

    def choose_start_region(domains):
        best = None
        best_key = None
        for ri in range(reg_count):
            k = (popcount(domains[ri]), len(region_neighbors[ri]))
            if best is None or k < best_key:
                best = ri
                best_key = k
        return best

    def frontier_candidates(domains, assigned_mask, neigh_mask):
        items = []
        unassigned_mask = ((1 << reg_count) - 1) ^ assigned_mask
        for ri in range(reg_count):
            if not ((unassigned_mask >> ri) & 1):
                continue
            dom = domains[ri]
            touchable = 0
            for li in bit_iter(dom):
                if cand_cellmask[ri][li] & neigh_mask:
                    touchable |= 1 << li
            if touchable:
                # Most constrained frontier region first.
                items.append((popcount(touchable), popcount(dom), -len(region_neighbors[ri]), ri, touchable))
        items.sort()
        return items

    def candidate_order(ri, dom_mask, domains):
        scored = []
        for li in bit_iter(dom_mask):
            cm = cand_cellmask[ri][li]
            score = 0
            # Favor placements that can touch more future regions.
            for nb in region_neighbors[ri]:
                dnb = domains[nb]
                if not dnb:
                    continue
                sup = touch_support[ri][nb][li]
                if sup & dnb:
                    score += 1
            # Mild preference for less 2x2 pressure.
            local_square_penalty = 0
            for sm in square_masks:
                if cm & sm:
                    local_square_penalty += 1
            scored.append((-score, local_square_penalty, li))
        scored.sort()
        return [li for _, __, li in scored]

    def build_answer(domains):
        grid = [[None for _ in range(C)] for _ in range(R)]
        for ri in range(reg_count):
            dom = domains[ri]
            if dom == 0 or dom & (dom - 1):
                return None
            li = dom.bit_length() - 1
            typ = cand_type[ri][li]
            for idx in candidates[reg_cands[ri][li]]["cells"]:
                rr, cc = divmod(idx, C)
                grid[rr][cc] = typ
        # Final connectivity verification
        shaded = [idx for r in range(R) for c in range(C) if grid[r][c] is not None for idx in [r * C + c]]
        if not shaded:
            return None
        q = deque([shaded[0]])
        seen = {shaded[0]}
        shaded_set = set(shaded)
        while q:
            x = q.popleft()
            nbr = cell_neighbors[x]
            for y in bit_iter(nbr):
                if y in shaded_set and y not in seen:
                    seen.add(y)
                    q.append(y)
        if len(seen) != len(shaded):
            return None
        for sm in square_masks:
            cnt = 0
            for idx in bit_iter(sm):
                rr, cc = divmod(idx, C)
                if grid[rr][cc] is not None:
                    cnt += 1
            if cnt == 4:
                return None
        return grid

    def search(domains, assigned_mask, shaded_mask, neigh_mask):
        key = (assigned_mask, shaded_mask, domains)
        if key in fail_cache:
            return None

        domains = list(domains)
        if not propagate(domains, assigned_mask, shaded_mask):
            fail_cache.add(key)
            return None
        domains = tuple(domains)

        if assigned_mask == (1 << reg_count) - 1:
            ans = build_answer(domains)
            if ans is not None:
                return ans
            fail_cache.add(key)
            return None

        if assigned_mask == 0:
            ri = choose_start_region(domains)
            dom_mask = domains[ri]
        else:
            frontier = frontier_candidates(domains, assigned_mask, neigh_mask)
            if not frontier:
                fail_cache.add(key)
                return None
            _, _, _, ri, dom_mask = frontier[0]

        for li in candidate_order(ri, dom_mask, domains):
            cm = cand_cellmask[ri][li]
            if assigned_mask and not (cm & neigh_mask):
                continue
            if creates_full_2x2(shaded_mask, cm):
                continue

            new_domains = list(domains)
            new_domains[ri] = 1 << li
            new_assigned = assigned_mask | (1 << ri)
            new_shaded = shaded_mask | cm

            new_neigh = neigh_mask
            for idx in candidates[reg_cands[ri][li]]["cells"]:
                new_neigh |= cell_neighbors[idx]

            result = search(tuple(new_domains), new_assigned, new_shaded, new_neigh)
            if result is not None:
                return result

        fail_cache.add(key)
        return None

    result = search(all_domain, 0, 0, 0)
    if result is None:
        return "No Solution"
    return repr(result)

