OBSERVATION = {'row_sum': [19, 19, 8, 11, 10, 7, 22, 3], 'col_sum': [11, 19, 7, 10, 24, 14, 7, 4]}

from functools import lru_cache


# The puzzle image provides only row/column target sums.
# The line-weights are assumed to be positional: rows have weights 1..R, columns have weights 1..C.


@lru_cache(maxsize=None)
def patterns_for_target(length, target):
    # All bitmasks over positions 0..length-1 whose weighted sum
    # (using weights 1..length) equals target.
    total = length * (length + 1) // 2
    if target < 0 or target > total:
        return ()
    out = []

    def dfs(pos, rem, mask):
        if pos < 0:
            if rem == 0:
                out.append(mask)
            return

        # Remaining lower weights are 1..pos, total:
        lower_total = pos * (pos + 1) // 2
        w = pos + 1

        # Include current weight if still feasible.
        if rem >= w and rem - w <= lower_total:
            dfs(pos - 1, rem - w, mask | (1 << pos))

        # Exclude current weight if still feasible.
        if rem <= lower_total:
            dfs(pos - 1, rem, mask)

    dfs(length - 1, target, 0)
    return tuple(out)


def summarize_domains(domains):
    # For each line-domain:
    #   AND => bits forced to 1 in every candidate
    #   OR  => bits that can be 1 in at least one candidate
    ands = []
    ors = []
    for dom in domains:
        if not dom:
            return None
        a = dom[0]
        o = dom[0]
        for mask in dom[1:]:
            a &= mask
            o |= mask
        ands.append(a)
        ors.append(o)
    return tuple(ands), tuple(ors)


def propagate(row_domains, col_domains, m, n):
    # Full generalized arc-consistency for row-pattern / column-pattern variables.
    # A row pattern bit and a column pattern bit on the same cell must agree.
    while True:
        changed = False

        col_summary = summarize_domains(col_domains)
        if col_summary is None:
            return None
        col_and, col_or = col_summary

        new_rows = list(row_domains)
        for r, dom in enumerate(row_domains):
            bit_r = 1 << r
            force1 = 0
            force0 = 0

            for c in range(n):
                bit_c = 1 << c
                if col_and[c] & bit_r:
                    force1 |= bit_c
                elif not (col_or[c] & bit_r):
                    force0 |= bit_c

            if force1 & force0:
                return None

            if force1 or force0:
                filtered = tuple(
                    mask
                    for mask in dom
                    if (mask & force1) == force1 and (mask & force0) == 0
                )
                if not filtered:
                    return None
                if len(filtered) != len(dom):
                    new_rows[r] = filtered
                    changed = True

        row_domains = tuple(new_rows)

        row_summary = summarize_domains(row_domains)
        if row_summary is None:
            return None
        row_and, row_or = row_summary

        new_cols = list(col_domains)
        for c, dom in enumerate(col_domains):
            bit_c = 1 << c
            force1 = 0
            force0 = 0

            for r in range(m):
                bit_r = 1 << r
                if row_and[r] & bit_c:
                    force1 |= bit_r
                elif not (row_or[r] & bit_c):
                    force0 |= bit_r

            if force1 & force0:
                return None

            if force1 or force0:
                filtered = tuple(
                    mask
                    for mask in dom
                    if (mask & force1) == force1 and (mask & force0) == 0
                )
                if not filtered:
                    return None
                if len(filtered) != len(dom):
                    new_cols[c] = filtered
                    changed = True

        col_domains = tuple(new_cols)

        if not changed:
            return row_domains, col_domains


def validate_row_masks(row_masks, row_targets, col_targets):
    m = len(row_targets)
    n = len(col_targets)

    for r, mask in enumerate(row_masks):
        s = 0
        for c in range(n):
            if mask & (1 << c):
                s += c + 1
        if s != row_targets[r]:
            return False

    for c in range(n):
        s = 0
        bit_c = 1 << c
        for r, mask in enumerate(row_masks):
            if mask & bit_c:
                s += r + 1
        if s != col_targets[c]:
            return False

    return True


def choose_branch(row_domains, col_domains, m, n):
    row_and, row_or = summarize_domains(row_domains)
    col_and, col_or = summarize_domains(col_domains)

    best_axis = None
    best_idx = None
    best_size = None
    best_impact = None

    for r, dom in enumerate(row_domains):
        k = len(dom)
        if k > 1:
            impact = 0
            bit_r = 1 << r
            for c in range(n):
                if (col_or[c] & bit_r) and not (col_and[c] & bit_r):
                    impact += 1
            if (
                best_size is None
                or k < best_size
                or (k == best_size and impact > best_impact)
            ):
                best_axis = "row"
                best_idx = r
                best_size = k
                best_impact = impact

    for c, dom in enumerate(col_domains):
        k = len(dom)
        if k > 1:
            impact = 0
            bit_c = 1 << c
            for r in range(m):
                if (row_or[r] & bit_c) and not (row_and[r] & bit_c):
                    impact += 1
            if (
                best_size is None
                or k < best_size
                or (k == best_size and impact > best_impact)
            ):
                best_axis = "col"
                best_idx = c
                best_size = k
                best_impact = impact

    if best_axis is None:
        return None

    if best_axis == "row":
        r = best_idx
        bit_r = 1 << r
        one_counts = [0] * n
        zero_counts = [0] * n
        for c in range(n):
            cnt1 = 0
            cnt0 = 0
            for mask in col_domains[c]:
                if mask & bit_r:
                    cnt1 += 1
                else:
                    cnt0 += 1
            one_counts[c] = cnt1
            zero_counts[c] = cnt0

        def score(mask):
            s = 0
            for c in range(n):
                s += one_counts[c] if (mask & (1 << c)) else zero_counts[c]
            return s

        candidates = tuple(sorted(row_domains[r], key=score))
        return best_axis, best_idx, candidates

    c = best_idx
    bit_c = 1 << c
    one_counts = [0] * m
    zero_counts = [0] * m
    for r in range(m):
        cnt1 = 0
        cnt0 = 0
        for mask in row_domains[r]:
            if mask & bit_c:
                cnt1 += 1
            else:
                cnt0 += 1
        one_counts[r] = cnt1
        zero_counts[r] = cnt0

    def score(mask):
        s = 0
        for r in range(m):
            s += one_counts[r] if (mask & (1 << r)) else zero_counts[r]
        return s

    candidates = tuple(sorted(col_domains[c], key=score))
    return best_axis, best_idx, candidates


def search(row_domains, col_domains, row_targets, col_targets, dead):
    m = len(row_targets)
    n = len(col_targets)

    propagated = propagate(row_domains, col_domains, m, n)
    if propagated is None:
        return None
    row_domains, col_domains = propagated

    state = (row_domains, col_domains)
    if state in dead:
        return None

    if all(len(dom) == 1 for dom in row_domains):
        row_masks = tuple(dom[0] for dom in row_domains)
        if validate_row_masks(row_masks, row_targets, col_targets):
            return row_masks
        dead.add(state)
        return None

    choice = choose_branch(row_domains, col_domains, m, n)
    if choice is None:
        dead.add(state)
        return None

    axis, idx, candidates = choice

    if axis == "row":
        for mask in candidates:
            new_rows = list(row_domains)
            new_rows[idx] = (mask,)
            result = search(tuple(new_rows), col_domains, row_targets, col_targets, dead)
            if result is not None:
                return result
    else:
        for mask in candidates:
            new_cols = list(col_domains)
            new_cols[idx] = (mask,)
            result = search(row_domains, tuple(new_cols), row_targets, col_targets, dead)
            if result is not None:
                return result

    dead.add(state)
    return None


def solve(observation):
    row_targets = observation["row_sum"]
    col_targets = observation["col_sum"]

    m = len(row_targets)
    n = len(col_targets)

    row_domains = []
    for target in row_targets:
        dom = patterns_for_target(n, target)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for target in col_targets:
        dom = patterns_for_target(m, target)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    result = search(tuple(row_domains), tuple(col_domains), tuple(row_targets), tuple(col_targets), set())
    if result is None:
        return "No Solution"

    grid = []
    for r in range(m):
        mask = result[r]
        grid.append(["B" if (mask & (1 << c)) else None for c in range(n)])

    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, 3, None], [None, None, 1, None, None], [None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None]]}

from collections import deque


def solve(observation):
    data = observation["data"]
    if not data or not data[0]:
        return "No Solution"

    R, C = len(data), len(data[0])
    cells = [(r, c) for r in range(R) for c in range(C)]
    cell_to_idx = {cell: i for i, cell in enumerate(cells)}
    N = len(cells)

    def in_bounds(r, c):
        return 0 <= r < R and 0 <= c < C

    neighbors = {}
    for r, c in cells:
        ns = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if in_bounds(rr, cc):
                ns.append((rr, cc))
        neighbors[(r, c)] = tuple(ns)

    clues = []
    clue_cells = set()
    for r in range(R):
        for c in range(C):
            v = data[r][c]
            if v is not None:
                clues.append((r, c, v))
                clue_cells.add((r, c))

    # Trivial no-clue case.
    if not clues:
        black = set(cells)
        for r in range(R - 1):
            for c in range(C - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= black:
                    return "No Solution"
        ans = [['B' for _ in range(C)] for _ in range(R)]
        return repr(ans)

    # Two numbered cells cannot touch orthogonally, since both are white and would merge islands.
    for r, c, _ in clues:
        for nr, nc in neighbors[(r, c)]:
            if (nr, nc) in clue_cells and (nr, nc) != (r, c):
                return "No Solution"

    # Generate all connected exact-size island shapes for each clue.
    def generate_shapes(root, size):
        if size <= 0:
            return []

        # Human-style feasibility filter:
        # - cannot include another clue
        # - cannot include a cell adjacent to another clue, because islands may not touch
        # - Manhattan distance from root must be < size
        allowed = set()
        rr0, cc0 = root
        for cell in cells:
            if cell != root and cell in clue_cells:
                continue
            if abs(cell[0] - rr0) + abs(cell[1] - cc0) >= size:
                continue
            if cell != root:
                bad = False
                for nb in neighbors[cell]:
                    if nb in clue_cells and nb != root:
                        bad = True
                        break
                if bad:
                    continue
            allowed.add(cell)

        if root not in allowed:
            return []

        # Connectivity component around the clue.
        comp = set()
        dq = deque([root])
        comp.add(root)
        while dq:
            cur = dq.popleft()
            for nb in neighbors[cur]:
                if nb in allowed and nb not in comp:
                    comp.add(nb)
                    dq.append(nb)

        if len(comp) < size:
            return []

        allowed = comp
        allowed_neighbors = {cell: {nb for nb in neighbors[cell] if nb in allowed} for cell in allowed}

        if size == 1:
            return [frozenset([root])]

        res = []
        seen = set()

        def rec(shape, frontier):
            fshape = frozenset(shape)
            if fshape in seen:
                return
            seen.add(fshape)

            if len(shape) == size:
                res.append(fshape)
                return

            # Quick upper bound: if even the whole clue-component is too small, stop.
            if len(allowed) < size:
                return

            for cell in sorted(frontier):
                shape.add(cell)
                new_frontier = (frontier | allowed_neighbors[cell]) - shape
                rec(shape, new_frontier)
                shape.remove(cell)

        start_shape = {root}
        start_frontier = set(allowed_neighbors[root]) - start_shape
        rec(start_shape, start_frontier)
        return res

    islands = []
    for i, (r, c, size) in enumerate(clues):
        shapes = generate_shapes((r, c), size)
        if not shapes:
            return "No Solution"
        islands.append(
            {
                "id": i,
                "root": (r, c),
                "size": size,
                "shapes": shapes,
            }
        )

    M = len(islands)

    # Precompute candidate membership masks per island per cell.
    membership = []
    for isl in islands:
        shapes = isl["shapes"]
        masks = [0] * N
        for si, shp in enumerate(shapes):
            bit = 1 << si
            for cell in shp:
                masks[cell_to_idx[cell]] |= bit
        membership.append(masks)

    # Precompute expanded area for each shape (shape + orthogonal border).
    expanded = []
    for isl in islands:
        ex = []
        for shp in isl["shapes"]:
            s = set(shp)
            for cell in shp:
                s.update(neighbors[cell])
            ex.append(frozenset(s))
        expanded.append(ex)

    # Compatibility masks: shapes of different islands must be disjoint and non-touching.
    compat = [[None] * M for _ in range(M)]
    for i in range(M):
        for j in range(M):
            if i == j:
                continue
            sj_len = len(islands[j]["shapes"])
            arr = [0] * len(islands[i]["shapes"])
            for a, shp_a in enumerate(islands[i]["shapes"]):
                ex_a = expanded[i][a]
                mask = 0
                for b, shp_b in enumerate(islands[j]["shapes"]):
                    if shp_b.isdisjoint(ex_a):
                        mask |= 1 << b
                arr[a] = mask
            compat[i][j] = arr

    all_domain_masks = [(1 << len(islands[i]["shapes"])) - 1 for i in range(M)]

    two_by_two_blocks = []
    for r in range(R - 1):
        for c in range(C - 1):
            two_by_two_blocks.append(
                (
                    cell_to_idx[(r, c)],
                    cell_to_idx[(r + 1, c)],
                    cell_to_idx[(r, c + 1)],
                    cell_to_idx[(r + 1, c + 1)],
                )
            )

    def bit_indices(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def revise(domains, i, j):
        di = domains[i]
        dj = domains[j]
        new_di = di
        m = di
        while m:
            b = m & -m
            a = b.bit_length() - 1
            if compat[i][j][a] & dj == 0:
                new_di ^= b
            m ^= b
        if new_di != di:
            domains[i] = new_di
            return True
        return False

    def black_connectivity_possible(forced_white, forced_black):
        # Necessary condition:
        # all forced-black cells must lie in one component of cells that are not forced white.
        if not any(forced_black):
            return True

        start = None
        for idx in range(N):
            if forced_black[idx]:
                start = idx
                break

        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            r, c = cells[cur]
            for nb in neighbors[(r, c)]:
                ni = cell_to_idx[nb]
                if forced_white[ni]:
                    continue
                if ni not in seen:
                    seen.add(ni)
                    dq.append(ni)

        for idx in range(N):
            if forced_black[idx] and idx not in seen:
                return False
        return True

    def propagate(domains):
        domains = domains[:]

        while True:
            changed = False

            # Pairwise arc consistency between island-shape domains.
            for i in range(M):
                if domains[i] == 0:
                    return None
                for j in range(M):
                    if i == j:
                        continue
                    if revise(domains, i, j):
                        if domains[i] == 0:
                            return None
                        changed = True

            # Derive forced white / forced black cells from current domains.
            forced_white_owner = [-1] * N
            forced_white = [False] * N
            possible_white = [False] * N

            for i in range(M):
                di = domains[i]
                if di == 0:
                    return None
                masks = membership[i]
                for idx in range(N):
                    cm = masks[idx]
                    if di & cm:
                        possible_white[idx] = True
                    if (di & cm) == di:
                        owner = forced_white_owner[idx]
                        if owner != -1 and owner != i:
                            return None
                        forced_white_owner[idx] = i
                        forced_white[idx] = True

            forced_black = [not possible_white[idx] for idx in range(N)]

            # Human-style sea rule: no 2x2 can already be forced black.
            for a, b, c, d in two_by_two_blocks:
                if forced_black[a] and forced_black[b] and forced_black[c] and forced_black[d]:
                    return None

            # Human-style sea rule: forced black cells must still be connectable.
            if not black_connectivity_possible(forced_white, forced_black):
                return None

            if not changed:
                return domains

    def final_check(domains):
        white = set()
        for i in range(M):
            di = domains[i]
            if di == 0 or (di & (di - 1)) != 0:
                return None
            idx = di.bit_length() - 1
            white.update(islands[i]["shapes"][idx])

        black = set(cells) - white

        # No 2x2 black.
        for r in range(R - 1):
            for c in range(C - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= black:
                    return None

        # Black connected.
        if black:
            start = next(iter(black))
            seen = {start}
            dq = deque([start])
            while dq:
                cur = dq.popleft()
                for nb in neighbors[cur]:
                    if nb in black and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(black):
                return None

        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                row.append(None if (r, c) in white else 'B')
            ans.append(row)
        return ans

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        complete = True
        choice_i = -1
        best_count = 10**9

        for i in range(M):
            cnt = domains[i].bit_count()
            if cnt > 1:
                complete = False
                if cnt < best_count:
                    best_count = cnt
                    choice_i = i

        if complete:
            return final_check(domains)

        # Most-constrained island first, least-compatible candidate first.
        cand_list = list(bit_indices(domains[choice_i]))

        def score(a):
            total = 0
            for j in range(M):
                if j == choice_i:
                    continue
                total += (compat[choice_i][j][a] & domains[j]).bit_count()
            return total

        cand_list.sort(key=score)

        for a in cand_list:
            new_domains = domains[:]
            new_domains[choice_i] = 1 << a
            res = search(new_domains)
            if res is not None:
                return res
        return None

    result = search(all_domain_masks)
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

