def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n
    full_mask = (1 << n) - 1

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    row_of = [i // n for i in range(m)]
    col_of = [i % n for i in range(m)]

    lt_masks = [0] * (n + 1)   # values < v
    gt_masks = [0] * (n + 1)   # values > v
    for v in range(1, n + 1):
        lt_masks[v] = (1 << (v - 1)) - 1
        gt_masks[v] = full_mask & ~((1 << v) - 1)

    def parse_coord(key):
        s = key.strip()
        if s[0] == "(" and s[-1] == ")":
            s = s[1:-1]
        a, b = s.split(",")
        return float(a.strip()), float(b.strip())

    def build_constraints(vertical_flipped=False):
        adj = [[] for _ in range(m)]  # (other_idx, rel) where rel=-1 means self<other, rel=+1 means self>other

        def add_less(a, b):
            adj[a].append((b, -1))
            adj[b].append((a, +1))

        for key, sym in observation.get("horizontal", {}).items():
            r, x = parse_coord(key)
            r = int(round(r))
            c = int(round(x - 0.5))
            left = r * n + c
            right = r * n + (c + 1)
            if sym == "<":
                add_less(left, right)
            elif sym == ">":
                add_less(right, left)

        for key, sym in observation.get("vertical", {}).items():
            y, c = parse_coord(key)
            r = int(round(y - 0.5))
            c = int(round(c))
            top = r * n + c
            bottom = (r + 1) * n + c

            if not vertical_flipped:
                # Standard interpretation used here:
                # '^' => top < bottom
                # 'v' => top > bottom
                if sym == "^":
                    add_less(top, bottom)
                elif sym == "v":
                    add_less(bottom, top)
            else:
                # Fallback if a source uses the opposite vertical convention.
                if sym == "^":
                    add_less(bottom, top)
                elif sym == "v":
                    add_less(top, bottom)

        return adj

    def min_value(mask):
        return (mask & -mask).bit_length()

    def max_value(mask):
        return mask.bit_length()

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def mask_to_value(mask):
        return mask.bit_length()

    def iter_bits(mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask -= bit

    def solve_internal(vertical_flipped=False):
        adj = build_constraints(vertical_flipped)

        peers = []
        ineq_degree = [len(adj[i]) for i in range(m)]
        for idx in range(m):
            r = row_of[idx]
            c = col_of[idx]
            seen = set(rows[r] + cols[c])
            seen.discard(idx)
            peers.append(tuple(seen))

        domains = [full_mask] * m
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    domains[r * n + c] = 1 << (v - 1)

        def filter_unit(cells, domains, prune):
            cands = [domains[idx] for idx in cells]

            prefix = [set() for _ in range(n + 1)]
            prefix[0].add(0)
            for i in range(n):
                cur = cands[i]
                nxt = prefix[i + 1]
                for used in prefix[i]:
                    avail = cur & ~used
                    bits = avail
                    while bits:
                        bit = bits & -bits
                        bits -= bit
                        nxt.add(used | bit)
                if not nxt:
                    return False

            suffix = [set() for _ in range(n + 1)]
            suffix[n].add(0)
            for i in range(n - 1, -1, -1):
                cur = cands[i]
                nxt = suffix[i]
                for used in suffix[i + 1]:
                    avail = cur & ~used
                    bits = avail
                    while bits:
                        bit = bits & -bits
                        bits -= bit
                        nxt.add(used | bit)
                if not nxt:
                    return False

            for i, idx in enumerate(cells):
                supported = 0
                right_sets = suffix[i + 1]
                for left_used in prefix[i]:
                    avail = cands[i] & ~left_used
                    bits = avail
                    while bits:
                        bit = bits & -bits
                        bits -= bit
                        remaining = full_mask ^ left_used ^ bit
                        if remaining in right_sets:
                            supported |= bit
                if supported == 0:
                    return False
                if supported != domains[idx]:
                    if not prune(idx, supported):
                        return False
            return True

        def propagate(domains):
            queue = list(range(m))
            in_queue = [True] * m

            dirty_rows = [True] * n
            dirty_cols = [True] * n
            row_stack = list(range(n))
            col_stack = list(range(n))

            def enqueue(idx):
                if not in_queue[idx]:
                    in_queue[idx] = True
                    queue.append(idx)

            def mark_units(idx):
                r = row_of[idx]
                c = col_of[idx]
                if not dirty_rows[r]:
                    dirty_rows[r] = True
                    row_stack.append(r)
                if not dirty_cols[c]:
                    dirty_cols[c] = True
                    col_stack.append(c)

            def prune(idx, new_mask):
                old = domains[idx]
                if new_mask == 0:
                    return False
                if new_mask != old:
                    domains[idx] = new_mask
                    enqueue(idx)
                    mark_units(idx)
                return True

            def revise_less(a, b):
                # Enforce domains[a] < domains[b] by repeated bound tightening.
                ma = domains[a]
                mb = domains[b]
                while True:
                    if ma == 0 or mb == 0:
                        return False
                    na = ma & lt_masks[max_value(mb)]
                    if na == 0:
                        return False
                    nb = mb & gt_masks[min_value(na)]
                    if nb == 0:
                        return False
                    na2 = na & lt_masks[max_value(nb)]
                    if na2 == 0:
                        return False
                    if na2 == ma and nb == mb:
                        break
                    ma, mb = na2, nb

                if ma != domains[a]:
                    if not prune(a, ma):
                        return False
                if mb != domains[b]:
                    if not prune(b, mb):
                        return False
                return True

            while queue or row_stack or col_stack:
                while queue:
                    idx = queue.pop()
                    in_queue[idx] = False

                    mask = domains[idx]
                    if mask == 0:
                        return False

                    if is_single(mask):
                        bit = mask
                        r = row_of[idx]
                        c = col_of[idx]

                        for j in rows[r]:
                            if j != idx and (domains[j] & bit):
                                if not prune(j, domains[j] & ~bit):
                                    return False
                        for j in cols[c]:
                            if j != idx and (domains[j] & bit):
                                if not prune(j, domains[j] & ~bit):
                                    return False

                    for other, rel in adj[idx]:
                        if rel == -1:
                            if not revise_less(idx, other):
                                return False
                        else:
                            if not revise_less(other, idx):
                                return False

                if row_stack:
                    r = row_stack.pop()
                    dirty_rows[r] = False
                    if not filter_unit(rows[r], domains, prune):
                        return False
                    continue

                if col_stack:
                    c = col_stack.pop()
                    dirty_cols[c] = False
                    if not filter_unit(cols[c], domains, prune):
                        return False
                    continue

            return True

        failed = set()

        def choose_cell(domains):
            best_idx = -1
            best_key = None
            for idx, mask in enumerate(domains):
                bc = mask.bit_count()
                if bc <= 1:
                    continue
                peer_pressure = 0
                for p in peers[idx]:
                    if domains[p].bit_count() > 1:
                        peer_pressure += 1
                span = max_value(mask) - min_value(mask)
                key = (bc, -ineq_degree[idx], -peer_pressure, span)
                if best_key is None or key < best_key:
                    best_key = key
                    best_idx = idx
            return best_idx

        def order_values(idx, domains):
            mask = domains[idx]
            ordered = []
            for bit in iter_bits(mask):
                v = bit.bit_length()
                score = 0

                for p in peers[idx]:
                    if domains[p] & bit:
                        score += 1

                for other, rel in adj[idx]:
                    omin = min_value(domains[other])
                    omax = max_value(domains[other])
                    if rel == -1:
                        # idx < other
                        if v >= omax:
                            score += 1000
                        else:
                            score += max(0, v - omin)
                    else:
                        # idx > other
                        if v <= omin:
                            score += 1000
                        else:
                            score += max(0, omax - v)

                ordered.append((score, v, bit))

            ordered.sort()
            return [bit for _, _, bit in ordered]

        def dfs(domains):
            domains = domains[:]
            if not propagate(domains):
                return None

            state = tuple(domains)
            if state in failed:
                return None

            idx = choose_cell(domains)
            if idx == -1:
                return domains

            for bit in order_values(idx, domains):
                child = domains[:]
                child[idx] = bit
                result = dfs(child)
                if result is not None:
                    return result

            failed.add(state)
            return None

        result = dfs(domains)
        if result is None:
            return None

        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                row.append(mask_to_value(result[r * n + c]))
            grid.append(row)
        return grid

    # Try the standard vertical convention first; if needed, try the flipped one.
    for vertical_flipped in (False, True):
        ans = solve_internal(vertical_flipped)
        if ans is not None:
            return repr(ans)

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'W', None, None, None, 'W', None], ['W', None, None, None, 'W', None, None, 'W'], ['B', None, None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B'], [None, 'W', None, 'B', None, None, None, None], [None, None, None, None, 'W', 'W', None, None], [None, None, None, 'B', 'W', None, None, 'W'], ['B', None, None, None, None, None, 'W', None]]}

from collections import deque

# State encoding on each dot:
# OFF=0
# VERT=1   (U,D)
# HORIZ=2  (L,R)
# UR=3
# RD=4
# DL=5
# LU=6

U, R, D, L = 0, 1, 2, 3
OPP = [D, L, U, R]

OFF, VERT, HORIZ, UR, RD, DL, LU = range(7)
TURN_STATES = (UR, RD, DL, LU)

DIRBIT = [1 << d for d in range(4)]
STATE_EDGES = [
    0,
    DIRBIT[U] | DIRBIT[D],
    DIRBIT[L] | DIRBIT[R],
    DIRBIT[U] | DIRBIT[R],
    DIRBIT[R] | DIRBIT[D],
    DIRBIT[D] | DIRBIT[L],
    DIRBIT[L] | DIRBIT[U],
]
USES = [[1 if (STATE_EDGES[s] & DIRBIT[d]) else 0 for d in range(4)] for s in range(7)]

ALL_STATE_BITS = (1 << 7) - 1
OFFBIT = 1 << OFF
USED_BITS = ALL_STATE_BITS ^ OFFBIT
TURN_BITS = sum(1 << s for s in TURN_STATES)

MASK_STATES = [[] for _ in range(1 << 7)]
for m in range(1 << 7):
    MASK_STATES[m] = [s for s in range(7) if (m >> s) & 1]

COUNT_BITS = [m.bit_count() for m in range(1 << 7)]
SINGLETON_STATE = [-1] * (1 << 7)
for s in range(7):
    SINGLETON_STATE[1 << s] = s

DIR_TRUE = [0] * 4
for d in range(4):
    m = 0
    for s in range(7):
        if USES[s][d]:
            m |= 1 << s
    DIR_TRUE[d] = m
DIR_FALSE = [ALL_STATE_BITS ^ DIR_TRUE[d] for d in range(4)]

TURN_WITH = [0] * 4
for d in range(4):
    m = 0
    for s in TURN_STATES:
        if USES[s][d]:
            m |= 1 << s
    TURN_WITH[d] = m

STRAIGHT_REQ = [1 << VERT, 1 << HORIZ, 1 << VERT, 1 << HORIZ]


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    vcount = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    clues = [data[r][c] for r in range(n) for c in range(n)]

    neighbors = [[-1, -1, -1, -1] for _ in range(vcount)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i][U] = idx(r - 1, c)
            if c + 1 < n:
                neighbors[i][R] = idx(r, c + 1)
            if r + 1 < n:
                neighbors[i][D] = idx(r + 1, c)
            if c > 0:
                neighbors[i][L] = idx(r, c - 1)

    affect = []
    for i in range(vcount):
        s = {i}
        for j in neighbors[i]:
            if j != -1:
                s.add(j)
        affect.append(tuple(s))

    clue_weight = []
    for i in range(vcount):
        c = clues[i]
        if c == 'B':
            clue_weight.append(0)
        elif c == 'W':
            clue_weight.append(1)
        else:
            clue_weight.append(2)

    adjacent_clues = [0] * vcount
    for i in range(vcount):
        cnt = 0
        for j in neighbors[i]:
            if j != -1 and clues[j] is not None:
                cnt += 1
        adjacent_clues[i] = cnt

    def initial_domain(i):
        clue = clues[i]
        if clue == 'W':
            base = (1 << VERT) | (1 << HORIZ)
        elif clue == 'B':
            base = TURN_BITS
        else:
            base = ALL_STATE_BITS

        m = 0
        for s in MASK_STATES[base]:
            ok = True
            for d in range(4):
                if USES[s][d] and neighbors[i][d] == -1:
                    ok = False
                    break
            if ok:
                m |= 1 << s
        return m

    def filter_domain(i, dom):
        clue = clues[i]
        old = dom[i]
        new = 0

        for s in MASK_STATES[old]:
            ok = True

            # Edge consistency with neighbor domains.
            for d in range(4):
                j = neighbors[i][d]
                use = USES[s][d]
                if j == -1:
                    if use:
                        ok = False
                        break
                    continue
                need = DIR_TRUE[OPP[d]] if use else DIR_FALSE[OPP[d]]
                if (dom[j] & need) == 0:
                    ok = False
                    break
            if not ok:
                continue

            # Clue-specific semantics.
            if clue == 'W':
                if s == VERT:
                    a = neighbors[i][U]
                    b = neighbors[i][D]
                    if a == -1 or b == -1:
                        continue
                    if ((dom[a] & TURN_WITH[D]) == 0) and ((dom[b] & TURN_WITH[U]) == 0):
                        continue
                elif s == HORIZ:
                    a = neighbors[i][L]
                    b = neighbors[i][R]
                    if a == -1 or b == -1:
                        continue
                    if ((dom[a] & TURN_WITH[R]) == 0) and ((dom[b] & TURN_WITH[L]) == 0):
                        continue
                else:
                    continue

            elif clue == 'B':
                if s not in TURN_STATES:
                    continue
                for d in range(4):
                    if USES[s][d]:
                        j = neighbors[i][d]
                        if j == -1 or (dom[j] & STRAIGHT_REQ[d]) == 0:
                            ok = False
                            break
                if not ok:
                    continue

            new |= 1 << s

        return new

    def propagate(dom):
        q = deque(range(vcount))
        inq = [True] * vcount

        def enqueue(i):
            if not inq[i]:
                inq[i] = True
                q.append(i)

        def touch(i):
            for k in affect[i]:
                enqueue(k)

        def intersect(i, mask):
            nm = dom[i] & mask
            if nm == 0:
                return False
            if nm != dom[i]:
                dom[i] = nm
                touch(i)
            return True

        while q:
            i = q.popleft()
            inq[i] = False

            nm = filter_domain(i, dom)
            if nm == 0:
                return False
            if nm != dom[i]:
                dom[i] = nm
                touch(i)

            mi = dom[i]
            clue = clues[i]

            # Generic edge forcing:
            # if all states use an edge, neighbor must use the opposite;
            # if no state uses an edge, neighbor must not use the opposite.
            for d in range(4):
                j = neighbors[i][d]
                if j == -1:
                    continue
                opp = OPP[d]
                if (mi & DIR_TRUE[d]) == 0:
                    if not intersect(j, DIR_FALSE[opp]):
                        return False
                elif (mi & DIR_FALSE[d]) == 0:
                    if not intersect(j, DIR_TRUE[opp]):
                        return False

            # Black-circle stronger forcing:
            # any mandatory exiting direction requires the adjacent vertex to be straight.
            if clue == 'B':
                for d in range(4):
                    if (mi & DIR_FALSE[d]) == 0:
                        j = neighbors[i][d]
                        if j == -1 or not intersect(j, STRAIGHT_REQ[d]):
                            return False

            # White-circle disjunctive forcing once orientation is fixed.
            if mi == (1 << VERT) and clue == 'W':
                a = neighbors[i][U]
                b = neighbors[i][D]
                if a == -1 or b == -1:
                    return False
                can_a = dom[a] & TURN_WITH[D]
                can_b = dom[b] & TURN_WITH[U]
                if not can_a and not can_b:
                    return False
                if not can_a:
                    if not intersect(b, TURN_WITH[U]):
                        return False
                if not can_b:
                    if not intersect(a, TURN_WITH[D]):
                        return False

            elif mi == (1 << HORIZ) and clue == 'W':
                a = neighbors[i][L]
                b = neighbors[i][R]
                if a == -1 or b == -1:
                    return False
                can_a = dom[a] & TURN_WITH[R]
                can_b = dom[b] & TURN_WITH[L]
                if not can_a and not can_b:
                    return False
                if not can_a:
                    if not intersect(b, TURN_WITH[L]):
                        return False
                if not can_b:
                    if not intersect(a, TURN_WITH[R]):
                        return False

        return True

    def bad_closed_subloop(dom):
        assigned = [SINGLETON_STATE[m] for m in dom]
        seen = [False] * vcount
        found_closed = False

        for start in range(vcount):
            s0 = assigned[start]
            if s0 in (-1, OFF) or seen[start]:
                continue

            stack = [start]
            seen[start] = True
            comp = []

            while stack:
                i = stack.pop()
                comp.append(i)
                s = assigned[i]
                for d in range(4):
                    if not USES[s][d]:
                        continue
                    j = neighbors[i][d]
                    if j == -1:
                        return True
                    sj = assigned[j]
                    if sj in (-1, OFF):
                        continue
                    if USES[sj][OPP[d]] and not seen[j]:
                        seen[j] = True
                        stack.append(j)

            comp_set = set(comp)
            frontier = 0
            for i in comp:
                s = assigned[i]
                for d in range(4):
                    if not USES[s][d]:
                        continue
                    j = neighbors[i][d]
                    if j == -1:
                        return True
                    sj = assigned[j]
                    if not (j in comp_set and sj not in (-1, OFF) and USES[sj][OPP[d]]):
                        frontier += 1

            if frontier not in (0, 2):
                return True

            if frontier == 0:
                if found_closed:
                    return True
                found_closed = True
                for k in range(vcount):
                    if k in comp_set:
                        continue
                    if clues[k] is not None:
                        return True
                    sk = assigned[k]
                    if sk not in (-1, OFF):
                        return True
                    if (dom[k] & OFFBIT) == 0:
                        return True

        return False

    def choose_var(dom):
        best = None
        best_key = None
        for i in range(vcount):
            cnt = COUNT_BITS[dom[i]]
            if cnt <= 1:
                continue
            key = (
                cnt,
                0 if (dom[i] & OFFBIT) == 0 else 1,
                clue_weight[i],
                -adjacent_clues[i],
            )
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def order_states(i, dom):
        mask = dom[i]
        clue = clues[i]
        if clue == 'B':
            base = [UR, RD, DL, LU]
        elif clue == 'W':
            base = [VERT, HORIZ]
        else:
            base = [OFF, VERT, HORIZ, UR, RD, DL, LU]

        out = []
        for s in base:
            if not ((mask >> s) & 1):
                continue
            score = 0
            for d in range(4):
                j = neighbors[i][d]
                if j == -1:
                    continue
                need = DIR_TRUE[OPP[d]] if USES[s][d] else DIR_FALSE[OPP[d]]
                score += COUNT_BITS[dom[j] & need]
            if s == OFF:
                score -= 0.1
            out.append((score, s))
        out.sort()
        return [s for _, s in out]

    def verify_and_extract(dom):
        states = [SINGLETON_STATE[m] for m in dom]
        if any(s == -1 for s in states):
            return None

        used_neighbors = [[] for _ in range(vcount)]
        used_vertices = []

        for i, s in enumerate(states):
            if s == OFF:
                continue
            used_vertices.append(i)
            for d in range(4):
                if not USES[s][d]:
                    continue
                j = neighbors[i][d]
                if j == -1:
                    return None
                sj = states[j]
                if sj == -1 or not USES[sj][OPP[d]]:
                    return None
                used_neighbors[i].append(j)

        if not used_vertices:
            return None

        for i in used_vertices:
            if len(used_neighbors[i]) != 2:
                return None

        # Final clue checks.
        for i, clue in enumerate(clues):
            s = states[i]
            if clue == 'W':
                if s == OFF or s not in (VERT, HORIZ):
                    return None
                if s == VERT:
                    a = neighbors[i][U]
                    b = neighbors[i][D]
                    sa = states[a] if a != -1 else -1
                    sb = states[b] if b != -1 else -1
                    turn_a = sa in TURN_STATES and USES[sa][D]
                    turn_b = sb in TURN_STATES and USES[sb][U]
                    if not (turn_a or turn_b):
                        return None
                else:
                    a = neighbors[i][L]
                    b = neighbors[i][R]
                    sa = states[a] if a != -1 else -1
                    sb = states[b] if b != -1 else -1
                    turn_a = sa in TURN_STATES and USES[sa][R]
                    turn_b = sb in TURN_STATES and USES[sb][L]
                    if not (turn_a or turn_b):
                        return None
            elif clue == 'B':
                if s not in TURN_STATES:
                    return None
                for d in range(4):
                    if USES[s][d]:
                        j = neighbors[i][d]
                        sj = states[j]
                        if d in (U, D):
                            if sj != VERT:
                                return None
                        else:
                            if sj != HORIZ:
                                return None

        # Single cycle connectivity.
        start = min(used_vertices)
        seen = {start}
        prev = -1
        cur = start

        # Pick a deterministic first step.
        n0, n1 = used_neighbors[start]
        nxt = n0 if rc(n0) <= rc(n1) else n1

        path = [rc(start), rc(nxt)]
        prev, cur = start, nxt

        while cur != start:
            a, b = used_neighbors[cur]
            nxt = a if a != prev else b
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if len(path) > len(used_vertices) + 1:
                return None

        if len(path) != len(used_vertices) + 1:
            return None
        if len(seen) == 0:
            return None

        visited_vertices = set(path[:-1])
        if len(visited_vertices) != len(used_vertices):
            return None

        return path

    def search(dom):
        if not propagate(dom):
            return None
        if bad_closed_subloop(dom):
            return None

        i = choose_var(dom)
        if i is None:
            return verify_and_extract(dom)

        for s in order_states(i, dom):
            ndom = dom[:]
            ndom[i] = 1 << s
            ans = search(ndom)
            if ans is not None:
                return ans
        return None

    dom0 = [initial_domain(i) for i in range(vcount)]
    if any(m == 0 for m in dom0):
        return "No Solution"

    ans = search(dom0)
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [1, None, None, None, None], [5, None, None, None, None]], 'horizontal': {'(0,0.5)': '<', '(0,1.5)': '<', '(2,1.5)': '<', '(2,3.5)': '>', '(4,3.5)': '>'}, 'vertical': {'(0.5,1)': '^', '(1.5,0)': '^', '(1.5,4)': '^', '(2.5,2)': '^', '(3.5,3)': '^'}}

# General Futoshiki solver with strong propagation:
# - row/column all-different propagation
# - hidden singles
# - naked/hidden subsets
# - inequality arc consistency
# - inequality graph lower/upper bounds
# - MRV-guided depth-first search only after propagation stalls

def solve(observation):
    n = len(observation['data'])
    cell_count = n * n
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def popcount(mask):
        return mask.bit_count()

    def min_value(mask):
        return (mask & -mask).bit_length()

    def max_value(mask):
        return mask.bit_length()

    def values_from_mask(mask):
        vals = []
        while mask:
            b = mask & -mask
            vals.append(b.bit_length())
            mask ^= b
        return vals

    greater_mask = [0] * (n + 1)
    lower_mask = [0] * (n + 1)
    for v in range(1, n + 1):
        gm = 0
        lm = 0
        for w in range(v + 1, n + 1):
            gm |= bit(w)
        for w in range(1, v):
            lm |= bit(w)
        greater_mask[v] = gm
        lower_mask[v] = lm

    def idx(r, c):
        return r * n + c

    def parse_coord(key):
        if isinstance(key, tuple):
            return key
        s = key.strip()
        if s[0] == '(' and s[-1] == ')':
            s = s[1:-1]
        a, b = s.split(',')
        return float(a), float(b)

    row_units = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_units = [[idx(r, c) for r in range(n)] for c in range(n)]
    units = row_units + col_units

    def build_relations(vertical_caret_means_top_less):
        rels = []

        for key, sym in observation.get('horizontal', {}).items():
            r_f, cp_f = parse_coord(key)
            r = int(round(r_f))
            c = int(round(cp_f - 0.5))
            left = idx(r, c)
            right = idx(r, c + 1)
            if sym == '<':
                rels.append((left, right))
            elif sym == '>':
                rels.append((right, left))
            else:
                return None

        for key, sym in observation.get('vertical', {}).items():
            rp_f, c_f = parse_coord(key)
            r = int(round(rp_f - 0.5))
            c = int(round(c_f))
            top = idx(r, c)
            bottom = idx(r + 1, c)
            if sym == '^':
                if vertical_caret_means_top_less:
                    rels.append((top, bottom))
                else:
                    rels.append((bottom, top))
            elif sym == 'v':
                if vertical_caret_means_top_less:
                    rels.append((bottom, top))
                else:
                    rels.append((top, bottom))
            else:
                return None

        # Remove duplicates while preserving order
        seen = set()
        out = []
        for a, b in rels:
            if a == b:
                return None
            if (a, b) not in seen:
                seen.add((a, b))
                out.append((a, b))
        return out

    def inequality_bounds(relations):
        succ = [[] for _ in range(cell_count)]
        pred = [[] for _ in range(cell_count)]
        indeg = [0] * cell_count
        for a, b in relations:
            succ[a].append(b)
            pred[b].append(a)
            indeg[b] += 1

        queue = [i for i in range(cell_count) if indeg[i] == 0]
        topo = []
        qh = 0
        while qh < len(queue):
            u = queue[qh]
            qh += 1
            topo.append(u)
            for v in succ[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    queue.append(v)

        if len(topo) != cell_count:
            return None  # inequality cycle => impossible

        lower_steps = [0] * cell_count
        for u in topo:
            best = 0
            for p in pred[u]:
                cand = lower_steps[p] + 1
                if cand > best:
                    best = cand
            lower_steps[u] = best

        upper_steps = [0] * cell_count
        for u in reversed(topo):
            best = 0
            for v in succ[u]:
                cand = upper_steps[v] + 1
                if cand > best:
                    best = cand
            upper_steps[u] = best

        bounds = []
        for i in range(cell_count):
            lo = 1 + lower_steps[i]
            hi = n - upper_steps[i]
            if lo > hi:
                return None
            m = 0
            for v in range(lo, hi + 1):
                m |= bit(v)
            bounds.append(m)
        return bounds, succ, pred

    def apply_inequalities(domains, relations):
        changed = False
        for a, b in relations:
            ma = domains[a]
            mb = domains[b]

            new_a = 0
            temp = ma
            while temp:
                ba = temp & -temp
                va = ba.bit_length()
                if greater_mask[va] & mb:
                    new_a |= ba
                temp ^= ba

            if new_a == 0:
                return None
            if new_a != ma:
                domains[a] = new_a
                ma = new_a
                changed = True

            new_b = 0
            temp = mb
            while temp:
                bb = temp & -temp
                vb = bb.bit_length()
                if lower_mask[vb] & ma:
                    new_b |= bb
                temp ^= bb

            if new_b == 0:
                return None
            if new_b != mb:
                domains[b] = new_b
                changed = True
        return changed

    def apply_unit(domains, unit):
        changed = False

        fixed = 0
        for i in unit:
            m = domains[i]
            if m == 0:
                return None
            if is_single(m):
                if fixed & m:
                    return None
                fixed |= m

        if fixed:
            for i in unit:
                m = domains[i]
                if not is_single(m):
                    nm = m & ~fixed
                    if nm == 0:
                        return None
                    if nm != m:
                        domains[i] = nm
                        changed = True

        # Hidden singles / missing-value checks
        for v in range(1, n + 1):
            bv = bit(v)
            pos = []
            for i in unit:
                if domains[i] & bv:
                    pos.append(i)
            if not pos:
                return None
            if len(pos) == 1 and domains[pos[0]] != bv:
                domains[pos[0]] = bv
                changed = True

        # Naked subsets and Hall contradictions on value masks
        for valmask in range(1, full_mask + 1):
            k = popcount(valmask)
            if k <= 1 or k >= n:
                continue
            subset_cells = []
            for i in unit:
                if domains[i] & ~valmask == 0:
                    subset_cells.append(i)
            c = len(subset_cells)
            if c > k:
                return None
            if c == k and c:
                subset_set = set(subset_cells)
                for i in unit:
                    if i not in subset_set:
                        m = domains[i]
                        nm = m & ~valmask
                        if nm == 0:
                            return None
                        if nm != m:
                            domains[i] = nm
                            changed = True

        # Hidden subsets
        for valmask in range(1, full_mask + 1):
            k = popcount(valmask)
            if k <= 1 or k >= n:
                continue
            cells = []
            for i in unit:
                if domains[i] & valmask:
                    cells.append(i)
            c = len(cells)
            if c < k:
                return None
            if c == k and c:
                for i in cells:
                    m = domains[i]
                    nm = m & valmask
                    if nm == 0:
                        return None
                    if nm != m:
                        domains[i] = nm
                        changed = True

        return changed

    def propagate(domains, relations):
        while True:
            any_change = False

            res = apply_inequalities(domains, relations)
            if res is None:
                return None
            if res:
                any_change = True

            for unit in units:
                res = apply_unit(domains, unit)
                if res is None:
                    return None
                if res:
                    any_change = True

            if not any_change:
                return domains

    def choose_branch_cell(domains, relations):
        # MRV, then degree in inequalities, then row/col pressure
        deg = [0] * cell_count
        for a, b in relations:
            deg[a] += 1
            deg[b] += 1

        best_i = None
        best_key = None
        for i, m in enumerate(domains):
            pc = popcount(m)
            if pc <= 1:
                continue
            r, c = divmod(i, n)
            row_unfixed = sum(1 for j in row_units[r] if not is_single(domains[j]))
            col_unfixed = sum(1 for j in col_units[c] if not is_single(domains[j]))
            key = (pc, -deg[i], -(row_unfixed + col_unfixed))
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
        return best_i

    def candidate_order(domains, i):
        # Prefer values that are rarer in row/column to mimic human-focused trials.
        r, c = divmod(i, n)
        scores = []
        for v in values_from_mask(domains[i]):
            bv = bit(v)
            row_count = sum(1 for j in row_units[r] if domains[j] & bv)
            col_count = sum(1 for j in col_units[c] if domains[j] & bv)
            scores.append((row_count + col_count, v))
        scores.sort()
        return [v for _, v in scores]

    def dfs(domains, relations):
        domains = propagate(domains, relations)
        if domains is None:
            return None

        solved = True
        for m in domains:
            if not is_single(m):
                solved = False
                break
        if solved:
            return domains

        i = choose_branch_cell(domains, relations)
        if i is None:
            return None

        for v in candidate_order(domains, i):
            new_domains = domains[:]
            new_domains[i] = bit(v)
            res = dfs(new_domains, relations)
            if res is not None:
                return res
        return None

    def domains_to_grid(domains):
        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                row.append(min_value(domains[idx(r, c)]))
            grid.append(row)
        return grid

    # Vertical '^' / 'v' conventions vary by source. Try the common one first,
    # then the opposite convention if needed.
    for vertical_caret_means_top_less in (True, False):
        relations = build_relations(vertical_caret_means_top_less)
        if relations is None:
            continue

        bounds_pack = inequality_bounds(relations)
        if bounds_pack is None:
            continue
        bound_masks, _, _ = bounds_pack

        domains = bound_masks[:]
        ok = True
        for r in range(n):
            for c in range(n):
                given = observation['data'][r][c]
                if given is not None:
                    m = bit(given)
                    cell = idx(r, c)
                    domains[cell] &= m
                    if domains[cell] == 0:
                        ok = False
                        break
            if not ok:
                break
        if not ok:
            continue

        result = dfs(domains, relations)
        if result is not None:
            return str(domains_to_grid(result))

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

