from collections import defaultdict, deque

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = n * n
    all_mask = (1 << m) - 1

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    def first_bit(mask):
        return (mask & -mask).bit_length() - 1

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    cell_region = [0] * m
    region_cells = defaultdict(list)
    clue_by_region = {}
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            rid = region[r][c]
            cell_region[i] = rid
            region_cells[rid].append(i)
            v = data[r][c]
            if v is not None:
                if rid in clue_by_region and clue_by_region[rid] != v:
                    return "No Solution"
                clue_by_region[rid] = v

    region_ids = sorted(region_cells)
    region_mask = {}
    for rid in region_ids:
        mask = 0
        for i in region_cells[rid]:
            mask |= 1 << i
        region_mask[rid] = mask

    neighbors = [0] * m
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            mask = 0
            if r > 0:
                mask |= 1 << idx(r - 1, c)
            if r + 1 < n:
                mask |= 1 << idx(r + 1, c)
            if c > 0:
                mask |= 1 << idx(r, c - 1)
            if c + 1 < n:
                mask |= 1 << idx(r, c + 1)
            neighbors[i] = mask

    def union_neighbors(mask):
        out = 0
        for i in iter_bits(mask):
            out |= neighbors[i]
        return out

    numbered_regions = sorted(clue_by_region)

    region_patterns = {}
    for rid in numbered_regions:
        cells = region_cells[rid]
        k = clue_by_region[rid]
        if k < 0 or k > len(cells):
            return "No Solution"
        pats = []

        if k == 0:
            pats.append((0, 0))
        else:
            L = len(cells)

            def bt(start, remain, chosen, forbidden):
                if remain == 0:
                    pats.append((chosen, union_neighbors(chosen)))
                    return
                if L - start < remain:
                    return
                for j in range(start, L):
                    i = cells[j]
                    bit = 1 << i
                    if forbidden & bit:
                        continue
                    bt(j + 1, remain - 1, chosen | bit, forbidden | bit | neighbors[i])

            bt(0, k, 0, 0)

        if not pats:
            return "No Solution"
        region_patterns[rid] = pats

    clauses_set = set()

    def add_line_clauses(line_cells):
        segments = []
        start = 0
        while start < len(line_cells):
            rid = cell_region[line_cells[start]]
            j = start
            seg = 0
            while j < len(line_cells) and cell_region[line_cells[j]] == rid:
                seg |= 1 << line_cells[j]
                j += 1
            segments.append(seg)
            start = j
        for i in range(len(segments) - 2):
            clauses_set.add(segments[i] | segments[i + 1] | segments[i + 2])

    for r in range(n):
        add_line_clauses([idx(r, c) for c in range(n)])
    for c in range(n):
        add_line_clauses([idx(r, c) for r in range(n)])

    clauses = sorted(clauses_set, key=lambda x: (x.bit_count(), x))
    cell_clauses = [[] for _ in range(m)]
    for ci, cmask in enumerate(clauses):
        for i in iter_bits(cmask):
            cell_clauses[i].append(ci)

    def white_component(start_i, allowed):
        seen = 1 << start_i
        dq = [start_i]
        while dq:
            u = dq.pop()
            nxt = neighbors[u] & allowed & ~seen
            while nxt:
                b = nxt & -nxt
                v = b.bit_length() - 1
                nxt ^= b
                seen |= b
                dq.append(v)
        return seen

    def connectivity_and_forced_white(black_mask, white_mask):
        allowed = all_mask ^ black_mask
        if white_mask == 0:
            return True, 0
        root = first_bit(white_mask)
        comp = white_component(root, allowed)
        if white_mask & ~comp:
            return False, 0
        if white_mask.bit_count() < 2:
            return True, 0

        total_white = (white_mask & comp).bit_count()
        disc = [-1] * m
        low = [0] * m
        subw = [0] * m
        time = 0
        forced = 0

        def dfs(u, parent):
            nonlocal time, forced
            disc[u] = low[u] = time
            time += 1
            subw[u] = 1 if ((white_mask >> u) & 1) else 0

            sep_white_parts = 0
            sum_sep_whites = 0

            nxt = neighbors[u] & comp
            while nxt:
                b = nxt & -nxt
                v = b.bit_length() - 1
                nxt ^= b
                if v == parent:
                    continue
                if disc[v] == -1:
                    dfs(v, u)
                    subw[u] += subw[v]
                    if low[v] < low[u]:
                        low[u] = low[v]
                    if low[v] >= disc[u] and subw[v] > 0:
                        sep_white_parts += 1
                        sum_sep_whites += subw[v]
                else:
                    if disc[v] < low[u]:
                        low[u] = disc[v]

            if ((white_mask >> u) & 1) == 0:
                if parent == -1:
                    if sep_white_parts >= 2:
                        forced |= 1 << u
                else:
                    rem_white = total_white - sum_sep_whites
                    parts = sep_white_parts + (1 if rem_white > 0 else 0)
                    if parts >= 2:
                        forced |= 1 << u

        dfs(root, -1)
        return True, forced

    def filter_domains(black_mask, white_mask):
        domains = {}
        for rid in numbered_regions:
            rm = region_mask[rid]
            must_black = black_mask & rm
            ok = []
            for patt, adj in region_patterns[rid]:
                if must_black & ~patt:
                    continue
                if patt & white_mask:
                    continue
                if adj & black_mask & ~patt:
                    continue
                ok.append((patt, adj))
            if not ok:
                return None
            domains[rid] = ok
        return domains

    def propagate(black_mask, white_mask):
        while True:
            if black_mask & white_mask:
                return None

            if union_neighbors(black_mask) & black_mask:
                return None

            changed = False

            forced_white = union_neighbors(black_mask) & ~(black_mask | white_mask)
            if forced_white:
                white_mask |= forced_white
                changed = True

            domains = {}
            for rid in numbered_regions:
                rm = region_mask[rid]
                must_black = black_mask & rm
                ok = []
                union_p = 0
                inter_p = rm
                for patt, adj in region_patterns[rid]:
                    if must_black & ~patt:
                        continue
                    if patt & white_mask:
                        continue
                    if adj & black_mask & ~patt:
                        continue
                    ok.append((patt, adj))
                    union_p |= patt
                    inter_p &= patt
                if not ok:
                    return None
                domains[rid] = ok

                fb = inter_p & ~black_mask
                fw = (rm & ~union_p) & ~white_mask

                if fb & white_mask:
                    return None
                if fw & black_mask:
                    return None

                if fb:
                    black_mask |= fb
                    changed = True
                if fw:
                    white_mask |= fw
                    changed = True

            for cmask in clauses:
                if cmask & black_mask:
                    continue
                if cmask & ~(black_mask | white_mask) == 0:
                    return None
                unk = cmask & ~(black_mask | white_mask)
                if unk and (unk & (unk - 1) == 0):
                    if unk & white_mask:
                        return None
                    black_mask |= unk
                    changed = True

            ok, forced = connectivity_and_forced_white(black_mask, white_mask)
            if not ok:
                return None
            forced &= ~(black_mask | white_mask)
            if forced:
                white_mask |= forced
                changed = True

            if not changed:
                domains = filter_domains(black_mask, white_mask)
                if domains is None:
                    return None
                return black_mask, white_mask, domains

    def complete_solution(black_mask):
        if union_neighbors(black_mask) & black_mask:
            return False
        for rid in numbered_regions:
            if (black_mask & region_mask[rid]).bit_count() != clue_by_region[rid]:
                return False
        for cmask in clauses:
            if (cmask & black_mask) == 0:
                return False
        white = all_mask ^ black_mask
        if white == 0:
            return False
        root = first_bit(white)
        comp = white_component(root, white)
        return comp == white

    fail = set()

    def choose_branch(black_mask, white_mask, domains):
        best_rid = None
        best_size = 10**9
        for rid in numbered_regions:
            d = domains[rid]
            if len(d) > 1:
                s = len(d)
                if s < best_size:
                    best_size = s
                    best_rid = rid
        if best_rid is not None:
            pats = [p for p, _ in domains[best_rid]]
            pats.sort(key=lambda x: x.bit_count())
            return ("region", best_rid, pats)

        best_clause = None
        best_unk = None
        for cmask in clauses:
            if cmask & black_mask:
                continue
            unk = cmask & ~(black_mask | white_mask)
            k = unk.bit_count()
            if k >= 2:
                if best_unk is None or k < best_unk:
                    best_unk = k
                    best_clause = cmask
        if best_clause is not None:
            cand = list(iter_bits(best_clause & ~(black_mask | white_mask)))
            cand.sort(key=lambda i: (-len(cell_clauses[i]), -(neighbors[i] & ~(black_mask | white_mask)).bit_count()))
            return ("cell", cand[0])

        unknown = all_mask & ~(black_mask | white_mask)
        if unknown:
            cand = list(iter_bits(unknown))
            cand.sort(key=lambda i: (-len(cell_clauses[i]), -(neighbors[i] & unknown).bit_count()))
            return ("cell", cand[0])

        return None

    def dfs(black_mask, white_mask):
        prop = propagate(black_mask, white_mask)
        if prop is None:
            return None
        black_mask, white_mask, domains = prop
        key = (black_mask, white_mask)
        if key in fail:
            return None

        if complete_solution(black_mask):
            return black_mask

        branch = choose_branch(black_mask, white_mask, domains)
        if branch is None:
            fail.add(key)
            return None

        if branch[0] == "region":
            rid = branch[1]
            rm = region_mask[rid]
            for patt in branch[2]:
                nb = black_mask | patt
                nw = white_mask | (rm & ~patt)
                ans = dfs(nb, nw)
                if ans is not None:
                    return ans
        else:
            i = branch[1]
            bit = 1 << i
            ans = dfs(black_mask | bit, white_mask)
            if ans is not None:
                return ans
            ans = dfs(black_mask, white_mask | bit)
            if ans is not None:
                return ans

        fail.add(key)
        return None

    sol_black = dfs(0, 0)
    if sol_black is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            i = idx(r, c)
            row.append('B' if ((sol_black >> i) & 1) else None)
        out.append(row)
    return out

if __name__ == "__main__":
    print(solve(OBSERVATION))

