# General solver for the "isolated domino shading" puzzle:
# 1) each region contains exactly 2 shaded cells
# 2) every shaded cell belongs to a domino
# 3) different dominoes may not touch orthogonally
# 4) dominoes may cross region borders
#
# The solver works on domino candidates, then uses strong region-based propagation:
# - each region must realize its remaining quota by a tiny set of local "ways"
# - impossible contributors are removed immediately
# - candidates present in every possible way for a region are forced
# - branching chooses the region with the fewest remaining ways

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0:
        return repr([])
    m = len(data[0])

    def cell_id(r, c):
        return r * m + c

    def rc(idx):
        return divmod(idx, m)

    # Compress region labels to dense 0..R-1
    raw_labels = sorted({x for row in data for x in row})
    reg_map = {v: i for i, v in enumerate(raw_labels)}
    region_of = [0] * (n * m)
    region_cells = [[] for _ in raw_labels]
    for r in range(n):
        for c in range(m):
            rid = reg_map[data[r][c]]
            idx = cell_id(r, c)
            region_of[idx] = rid
            region_cells[rid].append(idx)
    R = len(region_cells)

    # Orthogonal neighbors
    nbrs = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            u = cell_id(r, c)
            if r > 0:
                nbrs[u].append(cell_id(r - 1, c))
            if r + 1 < n:
                nbrs[u].append(cell_id(r + 1, c))
            if c > 0:
                nbrs[u].append(cell_id(r, c - 1))
            if c + 1 < m:
                nbrs[u].append(cell_id(r, c + 1))

    # All domino candidates (all orthogonally adjacent cell pairs)
    candidates = []
    cand_regs = []          # list of tuples: ((region, count), ...)
    cand_cells = []         # list of (u, v)
    touch_sets = []         # cells occupied or orth-adjacent to occupied cells
    for r in range(n):
        for c in range(m):
            u = cell_id(r, c)
            for dr, dc in ((0, 1), (1, 0)):
                rr, cc = r + dr, c + dc
                if rr >= n or cc >= m:
                    continue
                v = cell_id(rr, cc)

                counts = {}
                ru = region_of[u]
                rv = region_of[v]
                counts[ru] = counts.get(ru, 0) + 1
                counts[rv] = counts.get(rv, 0) + 1
                reginfo = tuple(sorted(counts.items()))

                touch = {u, v}
                touch.update(nbrs[u])
                touch.update(nbrs[v])

                cand_cells.append((u, v))
                cand_regs.append(reginfo)
                touch_sets.append(touch)
                candidates.append(len(candidates))

    D = len(candidates)

    # Conflict graph on domino candidates:
    # same cell, or orthogonally touching through any shaded cell.
    conflict_masks = [0] * D
    for i in range(D):
        ti = touch_sets[i]
        ui, vi = cand_cells[i]
        own_i = {ui, vi}
        for j in range(i + 1, D):
            uj, vj = cand_cells[j]
            if uj in ti or vj in ti:
                conflict_masks[i] |= 1 << j
                conflict_masks[j] |= 1 << i

    # Region contributor lists by contribution amount
    region_contrib1 = [[] for _ in range(R)]
    region_contrib2 = [[] for _ in range(R)]
    region_contrib_mask = [0] * R
    for d in range(D):
        bit = 1 << d
        for rid, cnt in cand_regs[d]:
            region_contrib_mask[rid] |= bit
            if cnt == 1:
                region_contrib1[rid].append(d)
            elif cnt == 2:
                region_contrib2[rid].append(d)

    all_avail = (1 << D) - 1

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def popcount(x):
        return x.bit_count()

    def apply_select(d, avail, selected, rem):
        bit = 1 << d
        if selected & bit:
            return avail, selected, rem, True
        if not (avail & bit):
            return avail, selected, rem, False
        if selected & conflict_masks[d]:
            return avail, selected, rem, False

        selected |= bit
        avail &= ~bit
        avail &= ~conflict_masks[d]

        rem = list(rem)
        for rid, cnt in cand_regs[d]:
            rem[rid] -= cnt
            if rem[rid] < 0:
                return avail, selected, tuple(rem), False
        return avail, selected, tuple(rem), True

    def compute_ways_for_region(rid, avail, rem_val):
        # Ways are represented as tuples of candidate indices.
        if rem_val == 0:
            return [()]
        if rem_val == 1:
            ways = []
            for d in region_contrib1[rid]:
                if avail & (1 << d):
                    ways.append((d,))
            return ways
        if rem_val == 2:
            ways = []
            for d in region_contrib2[rid]:
                if avail & (1 << d):
                    ways.append((d,))
            ones = [d for d in region_contrib1[rid] if avail & (1 << d)]
            for i, d1 in enumerate(ones):
                bad = conflict_masks[d1]
                for d2 in ones[i + 1:]:
                    if not (bad & (1 << d2)):
                        ways.append((d1, d2))
            return ways
        return []

    def propagate(avail, selected, rem):
        # Human-style repeated deduction:
        # - if a region needs 0 more, all remaining contributors to it are forbidden
        # - for each region, compute all remaining ways to reach its quota
        # - candidates not in any way are eliminated
        # - candidates in every way are forced
        while True:
            for x in rem:
                if x < 0 or x > 2:
                    return None

            progressed = False

            # Closed regions cannot accept any more shaded cells.
            for rid in range(R):
                if rem[rid] == 0:
                    bad = avail & region_contrib_mask[rid]
                    if bad:
                        avail &= ~bad
                        progressed = True
                        break
            if progressed:
                continue

            # Region-by-region feasibility and forcing
            for rid in range(R):
                ways = compute_ways_for_region(rid, avail, rem[rid])
                if not ways:
                    return None

                union_mask = 0
                inter_mask = None
                for w in ways:
                    wm = 0
                    for d in w:
                        wm |= 1 << d
                    union_mask |= wm
                    inter_mask = wm if inter_mask is None else (inter_mask & wm)

                # Remaining contributors that never appear in any feasible way are impossible.
                removable = avail & region_contrib_mask[rid] & ~union_mask
                if removable:
                    avail &= ~removable
                    progressed = True
                    break

                # Candidates that appear in every feasible way are forced.
                if inter_mask:
                    d = next(iter_bits(inter_mask))
                    avail, selected, rem, ok = apply_select(d, avail, selected, rem)
                    if not ok:
                        return None
                    progressed = True
                    break

            if progressed:
                continue

            # Stable: recompute all ways for branching.
            ways_map = {}
            for rid in range(R):
                ways = compute_ways_for_region(rid, avail, rem[rid])
                if not ways:
                    return None
                ways_map[rid] = ways
            return avail, selected, rem, ways_map

    def search(avail, selected, rem):
        state = propagate(avail, selected, rem)
        if state is None:
            return None
        avail, selected, rem, ways_map = state

        if all(x == 0 for x in rem):
            return selected

        # Choose the most constrained unsatisfied region.
        target = None
        target_ways = None
        best_key = None
        for rid in range(R):
            if rem[rid] == 0:
                continue
            ways = ways_map[rid]
            key = (len(ways), len(region_cells[rid]))
            if best_key is None or key < best_key:
                best_key = key
                target = rid
                target_ways = ways

        # Try the most constraining ways first.
        def way_score(w):
            wm = 0
            pressure = 0
            for d in w:
                wm |= 1 << d
                pressure += popcount(conflict_masks[d])
            return (-len(w), -pressure, wm)

        for way in sorted(target_ways, key=way_score):
            a2, s2, r2 = avail, selected, rem
            wmask = 0

            ok = True
            for d in way:
                wmask |= 1 << d
                a2, s2, r2, ok = apply_select(d, a2, s2, r2)
                if not ok:
                    break
            if not ok:
                continue

            # Commit that this chosen way is exactly how the target region is completed.
            other = a2 & region_contrib_mask[target] & ~wmask
            if other:
                a2 &= ~other

            ans = search(a2, s2, r2)
            if ans is not None:
                return ans

        return None

    rem0 = tuple(2 for _ in range(R))
    selected = search(all_avail, 0, rem0)
    if selected is None:
        return "No Solution"

    shaded = set()
    for d in iter_bits(selected):
        u, v = cand_cells[d]
        shaded.add(u)
        shaded.add(v)

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('S' if cell_id(r, c) in shaded else None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'tree': [[None, None, 'T', None, None, None, None, None], ['T', None, 'T', None, None, None, None, 'T'], [None, None, None, None, None, None, None, None], [None, 'T', None, None, 'T', None, None, None], [None, None, None, 'T', None, None, None, 'T'], [None, None, None, None, None, None, 'T', None], [None, None, 'T', None, None, 'T', None, 'T'], [None, None, None, None, None, None, None, None]], 'row_tent_counts': [2, 1, 1, 3, 0, 3, 1, 1], 'col_tent_counts': [1, 2, 1, 2, 0, 2, 0, 4]}

# General Tents solver using human-like propagation plus constrained search.
# Key modeling choice:
# - A tent cell must be orthogonally adjacent to exactly one tree.
#   Therefore any empty cell adjacent to 2+ trees is never a legal tent.
# - Each remaining legal tent cell belongs to exactly one tree's domain.
# - Search assigns exactly one option per tree while enforcing:
#   * row/column counts
#   * no king-move touching between tents
#   * one tent per tree

def solve(observation):
    tree_grid = observation['tree']
    row_target = list(observation['row_tent_counts'])
    col_target = list(observation['col_tent_counts'])

    R = len(tree_grid)
    C = len(tree_grid[0]) if R else 0

    tree_cells = []
    tree_index = {}
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                tree_index[(r, c)] = len(tree_cells)
                tree_cells.append((r, c))

    T = len(tree_cells)

    if sum(row_target) != T or sum(col_target) != T:
        return "No Solution"

    orth = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    king = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    # Candidate options: legal tent cells adjacent to exactly one tree.
    tree_options = [[] for _ in range(T)]
    option_tree = []
    option_pos = []

    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                continue
            adj_trees = []
            for dr, dc in orth:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and tree_grid[nr][nc] == 'T':
                    adj_trees.append(tree_index[(nr, nc)])
            if len(adj_trees) == 1:
                t = adj_trees[0]
                idx = len(option_tree)
                option_tree.append(t)
                option_pos.append((r, c))
                tree_options[t].append(idx)

    # Every tree must have at least one legal tent option.
    for t in range(T):
        if not tree_options[t]:
            return "No Solution"

    O = len(option_tree)

    # Bitmasks for each tree domain.
    initial_domains = [0] * T
    for t in range(T):
        mask = 0
        for i in tree_options[t]:
            mask |= 1 << i
        initial_domains[t] = mask

    # Row/column masks over options.
    row_mask = [0] * R
    col_mask = [0] * C
    for i, (r, c) in enumerate(option_pos):
        b = 1 << i
        row_mask[r] |= b
        col_mask[c] |= b

    # Conflict mask: options whose tent cells touch (including diagonally).
    conflict_mask = [0] * O
    conflict_degree = [0] * O
    for i in range(O):
        r1, c1 = option_pos[i]
        mask = 0
        for j in range(O):
            if i == j:
                continue
            r2, c2 = option_pos[j]
            if abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1:
                mask |= 1 << j
        conflict_mask[i] = mask
        conflict_degree[i] = mask.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def assign_tree(domains, row_need, col_need, selected, t, bit):
        cur = domains[t]
        if not (cur & bit):
            return False

        if selected[t] is not None:
            return selected[t] == bit

        selected[t] = bit
        domains[t] = bit

        i = bit.bit_length() - 1
        r, c = option_pos[i]

        row_need[r] -= 1
        col_need[c] -= 1
        if row_need[r] < 0 or col_need[c] < 0:
            return False

        ban = conflict_mask[i]
        if ban:
            for u in range(T):
                if u == t:
                    continue
                d = domains[u]
                nd = d & ~ban
                if nd != d:
                    if nd == 0:
                        return False
                    if selected[u] is not None and nd != selected[u]:
                        return False
                    domains[u] = nd

        return True

    def propagate(domains, row_need, col_need, selected):
        # Repeatedly apply:
        # 1) singleton tree domains
        # 2) row min/max deductions
        # 3) column min/max deductions
        while True:
            changed = False

            if any(x < 0 for x in row_need) or any(x < 0 for x in col_need):
                return False
            remaining_trees = sum(1 for x in selected if x is None)
            if sum(row_need) != remaining_trees or sum(col_need) != remaining_trees:
                return False

            # Forced singletons.
            for t in range(T):
                d = domains[t]
                if d == 0:
                    return False
                if selected[t] is None and (d & (d - 1)) == 0:
                    if not assign_tree(domains, row_need, col_need, selected, t, d):
                        return False
                    changed = True

            # Row bounds and line-forcing.
            for r in range(R):
                need = row_need[r]
                rm = row_mask[r]
                forced = 0
                possible = 0
                mixed = []

                for t in range(T):
                    if selected[t] is not None:
                        continue
                    d = domains[t]
                    in_row = d & rm
                    if in_row:
                        possible += 1
                        if in_row == d:
                            forced += 1
                        else:
                            mixed.append((t, d, in_row))

                if need < forced or need > possible:
                    return False

                if need == forced:
                    # Only already-row-forced trees may occupy this row.
                    for t, d, in_row in mixed:
                        nd = d & ~in_row
                        if nd != d:
                            if nd == 0:
                                return False
                            domains[t] = nd
                            changed = True
                elif need == possible:
                    # Every tree that can be in this row must be in this row.
                    for t, d, in_row in mixed:
                        if in_row != d:
                            domains[t] = in_row
                            changed = True

            # Column bounds and line-forcing.
            for c in range(C):
                need = col_need[c]
                cm = col_mask[c]
                forced = 0
                possible = 0
                mixed = []

                for t in range(T):
                    if selected[t] is not None:
                        continue
                    d = domains[t]
                    in_col = d & cm
                    if in_col:
                        possible += 1
                        if in_col == d:
                            forced += 1
                        else:
                            mixed.append((t, d, in_col))

                if need < forced or need > possible:
                    return False

                if need == forced:
                    for t, d, in_col in mixed:
                        nd = d & ~in_col
                        if nd != d:
                            if nd == 0:
                                return False
                            domains[t] = nd
                            changed = True
                elif need == possible:
                    for t, d, in_col in mixed:
                        if in_col != d:
                            domains[t] = in_col
                            changed = True

            if not changed:
                return True

    def choose_tree(domains, selected):
        # Most constrained tree first.
        best_t = None
        best_key = None
        for t in range(T):
            if selected[t] is not None:
                continue
            d = domains[t]
            size = d.bit_count()
            total_conf = 0
            for b in iter_bits(d):
                total_conf += conflict_degree[b.bit_length() - 1]
            key = (size, -total_conf)
            if best_key is None or key < best_key:
                best_key = key
                best_t = t
        return best_t

    def ordered_options(mask, row_need, col_need):
        opts = []
        for b in iter_bits(mask):
            i = b.bit_length() - 1
            r, c = option_pos[i]
            # Try more constraining placements first.
            score = (
                conflict_degree[i],
                -row_need[r],
                -col_need[c],
            )
            opts.append((score, b))
        opts.sort(reverse=True)
        return [b for _, b in opts]

    def dfs(domains, row_need, col_need, selected):
        if not propagate(domains, row_need, col_need, selected):
            return None

        if all(x is not None for x in selected):
            if all(v == 0 for v in row_need) and all(v == 0 for v in col_need):
                return selected
            return None

        t = choose_tree(domains, selected)
        if t is None:
            return None

        for bit in ordered_options(domains[t], row_need, col_need):
            ndom = domains[:]
            nrow = row_need[:]
            ncol = col_need[:]
            nsel = selected[:]
            if assign_tree(ndom, nrow, ncol, nsel, t, bit):
                res = dfs(ndom, nrow, ncol, nsel)
                if res is not None:
                    return res

        return None

    selected = [None] * T
    result = dfs(initial_domains[:], row_target[:], col_target[:], selected)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(C)] for _ in range(R)]
    for bit in result:
        i = bit.bit_length() - 1
        r, c = option_pos[i]
        answer[r][c] = 't'
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

