# General Masyu solver on an N x N dot grid.
# The model uses local vertex-pattern domains plus aggressive propagation:
# - every dot has one of the allowed degree-0/2 patterns
# - white clues are straight, with at least one adjacent turn
# - black clues are turns, with straight continuation on both adjacent sides
# - arc consistency on neighboring vertices
# - targeted white-clue propagation
# - premature forced-cycle rejection
# Search branches on the most constrained vertex, prioritizing clues.

import sys

U, R, D, L = 1, 2, 4, 8
OPP = {U: D, R: L, D: U, L: R}
DIRS = (U, R, D, L)
DRC = {U: (-1, 0), R: (0, 1), D: (1, 0), L: (0, -1)}
VERT = U | D
HORZ = L | R

K_NONE = 0
K_WHITE = 1
K_BLACK = 2

VALID_PATTERNS = [0, 3, 5, 6, 9, 10, 12]  # {}, UR, UD, RD, UL, LR, DL
TURN_PATTERNS = {3, 6, 9, 12}

def solve(observation):
    sys.setrecursionlimit(10000)
    data = observation["data"]
    n = len(data)
    total = n * n

    kinds = [K_NONE] * total
    clue_indices = []
    for r in range(n):
        for c in range(n):
            v = r * n + c
            if data[r][c] == "W":
                kinds[v] = K_WHITE
                clue_indices.append(v)
            elif data[r][c] == "B":
                kinds[v] = K_BLACK
                clue_indices.append(v)

    neighbors = [[] for _ in range(total)]
    neighbor_of = [{} for _ in range(total)]
    avail_mask = [0] * total
    edges = []
    for r in range(n):
        for c in range(n):
            v = r * n + c
            for d in DIRS:
                rr = r + DRC[d][0]
                cc = c + DRC[d][1]
                if 0 <= rr < n and 0 <= cc < n:
                    u = rr * n + cc
                    neighbors[v].append((d, u))
                    neighbor_of[v][d] = u
                    avail_mask[v] |= d
            if c + 1 < n:
                edges.append((v, v + 1, R))
            if r + 1 < n:
                edges.append((v, v + n, D))

    def init_domain(v):
        a = avail_mask[v]
        k = kinds[v]
        pats = []
        if k == K_NONE:
            pats.append(0)
            for p in VALID_PATTERNS[1:]:
                if (p & a) == p:
                    pats.append(p)
        elif k == K_WHITE:
            for p in (VERT, HORZ):
                if (p & a) == p:
                    pats.append(p)
        else:
            for p in TURN_PATTERNS:
                if (p & a) == p:
                    pats.append(p)
        mask = 0
        for p in pats:
            mask |= 1 << p
        return mask

    domains0 = [init_domain(v) for v in range(total)]
    if any(m == 0 for m in domains0):
        return "No Solution"

    clue_set = set(clue_indices)

    def bitcount(x):
        return x.bit_count()

    def iter_patterns(mask):
        for p in VALID_PATTERNS:
            if (mask >> p) & 1:
                yield p

    def singleton_pattern(mask):
        for p in VALID_PATTERNS:
            if mask == (1 << p):
                return p
        return None

    def is_turn_with_edge_to_center(q, edge_to_center):
        if not (q & edge_to_center):
            return False
        if edge_to_center in (L, R):
            return q != HORZ
        return q != VERT

    def pair_compatible(kv, p, ku, q, d_from_v_to_u):
        pv = 1 if (p & d_from_v_to_u) else 0
        qu = 1 if (q & OPP[d_from_v_to_u]) else 0
        if pv != qu:
            return False
        if pv:
            if kv == K_BLACK:
                need = VERT if d_from_v_to_u in (U, D) else HORZ
                if q != need:
                    return False
            if ku == K_BLACK:
                need = VERT if d_from_v_to_u in (U, D) else HORZ
                if p != need:
                    return False
        return True

    def support_exists(domains, v, p, d, require_turn=False):
        u = neighbor_of[v][d]
        m = domains[u]
        edge_to_center = OPP[d]
        for q in iter_patterns(m):
            if pair_compatible(kinds[v], p, kinds[u], q, d):
                if require_turn and not is_turn_with_edge_to_center(q, edge_to_center):
                    continue
                return True
        return False

    def white_singleton_neighbor_prune(domains, v):
        changed = False
        p = singleton_pattern(domains[v])
        if p is None or kinds[v] != K_WHITE:
            return True, False

        if p == HORZ:
            if L not in neighbor_of[v] or R not in neighbor_of[v]:
                return False, changed
            left = neighbor_of[v][L]
            right = neighbor_of[v][R]
            lt = support_exists(domains, v, p, L, require_turn=True)
            rt = support_exists(domains, v, p, R, require_turn=True)
            if not (lt or rt):
                return False, changed
            if not lt:
                old = domains[right]
                new = 0
                for q in iter_patterns(old):
                    if pair_compatible(kinds[v], p, kinds[right], q, R) and is_turn_with_edge_to_center(q, L):
                        new |= 1 << q
                if new == 0:
                    return False, changed
                if new != old:
                    domains[right] = new
                    changed = True
            if not rt:
                old = domains[left]
                new = 0
                for q in iter_patterns(old):
                    if pair_compatible(kinds[v], p, kinds[left], q, L) and is_turn_with_edge_to_center(q, R):
                        new |= 1 << q
                if new == 0:
                    return False, changed
                if new != old:
                    domains[left] = new
                    changed = True

        elif p == VERT:
            if U not in neighbor_of[v] or D not in neighbor_of[v]:
                return False, changed
            up = neighbor_of[v][U]
            down = neighbor_of[v][D]
            ut = support_exists(domains, v, p, U, require_turn=True)
            dt = support_exists(domains, v, p, D, require_turn=True)
            if not (ut or dt):
                return False, changed
            if not ut:
                old = domains[down]
                new = 0
                for q in iter_patterns(old):
                    if pair_compatible(kinds[v], p, kinds[down], q, D) and is_turn_with_edge_to_center(q, U):
                        new |= 1 << q
                if new == 0:
                    return False, changed
                if new != old:
                    domains[down] = new
                    changed = True
            if not dt:
                old = domains[up]
                new = 0
                for q in iter_patterns(old):
                    if pair_compatible(kinds[v], p, kinds[up], q, U) and is_turn_with_edge_to_center(q, D):
                        new |= 1 << q
                if new == 0:
                    return False, changed
                if new != old:
                    domains[up] = new
                    changed = True
        else:
            return False, changed

        return True, changed

    def forced_edge_state(domains, v, u, d_from_v_to_u):
        on_possible = False
        off_possible = False
        mv = domains[v]
        mu = domains[u]
        for p in iter_patterns(mv):
            for q in iter_patterns(mu):
                if pair_compatible(kinds[v], p, kinds[u], q, d_from_v_to_u):
                    if p & d_from_v_to_u:
                        on_possible = True
                    else:
                        off_possible = True
                    if on_possible and off_possible:
                        return 0
        if on_possible and not off_possible:
            return 1
        if off_possible and not on_possible:
            return -1
        return 0

    def premature_forced_cycle(domains):
        adj = [[] for _ in range(total)]
        used_vertices = set()
        forced_edge_count = 0
        for v, u, d in edges:
            st = forced_edge_state(domains, v, u, d)
            if st == 1:
                adj[v].append(u)
                adj[u].append(v)
                used_vertices.add(v)
                used_vertices.add(u)
                forced_edge_count += 1

        if forced_edge_count == 0:
            return False

        seen = set()
        cycle_components = []
        for s in used_vertices:
            if s in seen:
                continue
            stack = [s]
            comp = []
            seen.add(s)
            ecount2 = 0
            while stack:
                x = stack.pop()
                comp.append(x)
                ecount2 += len(adj[x])
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            ecount = ecount2 // 2
            if ecount == len(comp) and all(len(adj[x]) == 2 for x in comp):
                cycle_components.append(set(comp))

        if not cycle_components:
            return False
        if len(cycle_components) > 1:
            return True

        comp = cycle_components[0]
        if any(v not in comp for v in clue_set):
            return True

        for v, u, d in edges:
            st = forced_edge_state(domains, v, u, d)
            if st == 1 and (v not in comp or u not in comp):
                return True

        return False

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            for v in range(total):
                old = domains[v]
                new = 0
                for p in iter_patterns(old):
                    ok = True

                    for d, u in neighbors[v]:
                        supported = False
                        for q in iter_patterns(domains[u]):
                            if pair_compatible(kinds[v], p, kinds[u], q, d):
                                supported = True
                                break
                        if not supported:
                            ok = False
                            break

                    if not ok:
                        continue

                    if kinds[v] == K_WHITE:
                        if p == HORZ:
                            if L not in neighbor_of[v] or R not in neighbor_of[v]:
                                continue
                            lt = support_exists(domains, v, p, L, require_turn=True)
                            rt = support_exists(domains, v, p, R, require_turn=True)
                            if not (lt or rt):
                                continue
                        elif p == VERT:
                            if U not in neighbor_of[v] or D not in neighbor_of[v]:
                                continue
                            ut = support_exists(domains, v, p, U, require_turn=True)
                            dt = support_exists(domains, v, p, D, require_turn=True)
                            if not (ut or dt):
                                continue
                        else:
                            continue

                    new |= 1 << p

                if new == 0:
                    return None
                if new != old:
                    domains[v] = new
                    changed = True

            for v in clue_indices:
                if kinds[v] == K_WHITE and bitcount(domains[v]) == 1:
                    ok, ch = white_singleton_neighbor_prune(domains, v)
                    if not ok:
                        return None
                    if ch:
                        changed = True

            if premature_forced_cycle(domains):
                return None

        return domains

    def choose_vertex(domains):
        best = None
        best_key = None

        def clue_neighbors_count(v):
            cnt = 0
            for _, u in neighbors[v]:
                if kinds[u] != K_NONE:
                    cnt += 1
            return cnt

        for pass_clues in (True, False):
            for v in range(total):
                if bitcount(domains[v]) <= 1:
                    continue
                if pass_clues and kinds[v] == K_NONE:
                    continue
                nonzero = sum(1 for p in iter_patterns(domains[v]) if p != 0)
                key = (
                    bitcount(domains[v]),
                    0 if kinds[v] != K_NONE else 1,
                    -clue_neighbors_count(v),
                    nonzero,
                    v,
                )
                if best is None or key < best_key:
                    best = v
                    best_key = key
            if best is not None:
                return best
        return None

    def pattern_order(v, mask):
        pats = list(iter_patterns(mask))
        if kinds[v] == K_WHITE:
            return pats
        if kinds[v] == K_BLACK:
            score = []
            for p in pats:
                s = 0
                for d in DIRS:
                    if p & d:
                        u = neighbor_of[v][d]
                        need = VERT if d in (U, D) else HORZ
                        s += 0 if ((domains_current[u] >> need) & 1) else 1
                score.append((s, p))
            score.sort()
            return [p for _, p in score]
        if 0 in pats and len(pats) > 1:
            pats.remove(0)
            pats.append(0)
        return pats

    def final_validate_and_build(domains):
        patterns = [singleton_pattern(m) for m in domains]
        if any(p is None for p in patterns):
            return None

        adj = [[] for _ in range(total)]
        used = set()

        for v, u, d in edges:
            pv = patterns[v]
            pu = patterns[u]
            if bool(pv & d) != bool(pu & OPP[d]):
                return None
            if pv & d:
                adj[v].append(u)
                adj[u].append(v)
                used.add(v)
                used.add(u)

        for v in range(total):
            deg = len(adj[v])
            if patterns[v] == 0:
                if deg != 0:
                    return None
            else:
                if deg != 2:
                    return None

        for v in clue_indices:
            p = patterns[v]
            if kinds[v] == K_WHITE:
                if p not in (HORZ, VERT):
                    return None
                if p == HORZ:
                    left = neighbor_of[v].get(L)
                    right = neighbor_of[v].get(R)
                    if left is None or right is None:
                        return None
                    if not (patterns[left] != HORZ or patterns[right] != HORZ):
                        return None
                else:
                    up = neighbor_of[v].get(U)
                    down = neighbor_of[v].get(D)
                    if up is None or down is None:
                        return None
                    if not (patterns[up] != VERT or patterns[down] != VERT):
                        return None
            else:
                if p not in TURN_PATTERNS:
                    return None
                for d in DIRS:
                    if p & d:
                        u = neighbor_of[v].get(d)
                        if u is None:
                            return None
                        need = VERT if d in (U, D) else HORZ
                        if patterns[u] != need:
                            return None

        if not clue_indices:
            return None

        if any(len(adj[v]) != 2 for v in clue_indices):
            return None

        start = min(used) if used else None
        if start is None:
            return None

        seen = set()
        stack = [start]
        seen.add(start)
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)

        if used != seen:
            return None
        if not clue_set.issubset(used):
            return None

        path = []
        cur = start
        prev = None
        path.append((cur // n, cur % n))
        while True:
            nxts = adj[cur]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append((nxt // n, nxt % n))
            prev, cur = cur, nxt
            if cur == start:
                break

        return path

    def search(domains):
        d = propagate(domains)
        if d is None:
            return None

        v = choose_vertex(d)
        if v is None:
            return final_validate_and_build(d)

        global domains_current
        domains_current = d
        for p in pattern_order(v, d[v]):
            nd = d.copy()
            nd[v] = 1 << p
            ans = search(nd)
            if ans is not None:
                return ans
        return None

    domains_current = domains0
    ans = search(domains0[:])
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 4, 3, 1, 5], [4, 3, 5, 3, 1], [5, 2, 5, 4, 3], [3, 3, 4, 1, 2], [4, 5, 2, 3, 4]]}

from collections import deque

def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    neighbors = [[] for _ in range(m)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    row_counts = []
    for r in range(n):
        d = {}
        for c in range(n):
            v = data[r][c]
            d[v] = d.get(v, 0) + 1
        row_counts.append(d)

    col_counts = []
    for c in range(n):
        d = {}
        for r in range(n):
            v = data[r][c]
            d[v] = d.get(v, 0) + 1
        col_counts.append(d)

    groups = []
    cell_group_ids = [[] for _ in range(m)]

    for r in range(n):
        pos = {}
        for c in range(n):
            pos.setdefault(data[r][c], []).append(idx(r, c))
        for cells in pos.values():
            if len(cells) > 1:
                gid = len(groups)
                groups.append(tuple(cells))
                for i in cells:
                    cell_group_ids[i].append(gid)

    for c in range(n):
        pos = {}
        for r in range(n):
            pos.setdefault(data[r][c], []).append(idx(r, c))
        for cells in pos.values():
            if len(cells) > 1:
                gid = len(groups)
                groups.append(tuple(cells))
                for i in cells:
                    cell_group_ids[i].append(gid)

    static_forces = {}
    static_conflict = False

    def add_static(i, val):
        nonlocal static_conflict
        prev = static_forces.get(i)
        if prev is not None and prev != val:
            static_conflict = True
        else:
            static_forces[i] = val

    # Unique in both row and column => must be white.
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if row_counts[r][v] == 1 and col_counts[c][v] == 1:
                add_static(idx(r, c), 0)

    # Pattern: a ? a in row/column => middle must be white.
    for r in range(n):
        for c in range(n - 2):
            if data[r][c] == data[r][c + 2]:
                add_static(idx(r, c + 1), 0)
    for c in range(n):
        for r in range(n - 2):
            if data[r][c] == data[r + 2][c]:
                add_static(idx(r + 1, c), 0)

    # Pattern: a a a contiguous => black, white, black.
    for r in range(n):
        for c in range(n - 2):
            if data[r][c] == data[r][c + 1] == data[r][c + 2]:
                add_static(idx(r, c), 1)
                add_static(idx(r, c + 1), 0)
                add_static(idx(r, c + 2), 1)
    for c in range(n):
        for r in range(n - 2):
            if data[r][c] == data[r + 1][c] == data[r + 2][c]:
                add_static(idx(r, c), 1)
                add_static(idx(r + 1, c), 0)
                add_static(idx(r + 2, c), 1)

    if static_conflict:
        return "No Solution"

    def assign(state, i, val):
        cur = state[i]
        if cur == val:
            return 0
        if cur != -1:
            return -1
        state[i] = val
        return 1

    def connected_component_passable(state, start):
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in neighbors[x]:
                if state[y] != 1 and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return seen

    def all_components_passable(state):
        seen = set()
        comps = []
        for i in range(m):
            if state[i] == 1 or i in seen:
                continue
            comp = []
            dq = deque([i])
            seen.add(i)
            while dq:
                x = dq.popleft()
                comp.append(x)
                for y in neighbors[x]:
                    if state[y] != 1 and y not in seen:
                        seen.add(y)
                        dq.append(y)
            comps.append(comp)
        return comps

    def connectivity_propagate(state):
        progress = False
        passable_exists = any(s != 1 for s in state)
        if not passable_exists:
            return None

        whites = [i for i, s in enumerate(state) if s == 0]

        if whites:
            main = connected_component_passable(state, whites[0])
            for w in whites:
                if w not in main:
                    return None

            seen = set(main)
            for i in range(m):
                if state[i] == 1 or i in seen:
                    continue
                comp = []
                dq = deque([i])
                seen.add(i)
                while dq:
                    x = dq.popleft()
                    comp.append(x)
                    for y in neighbors[x]:
                        if state[y] != 1 and y not in seen:
                            seen.add(y)
                            dq.append(y)
                if len(comp) > 1:
                    return None
                res = assign(state, comp[0], 1)
                if res == -1:
                    return None
                if res == 1:
                    progress = True
        else:
            comps = all_components_passable(state)
            large = [comp for comp in comps if len(comp) > 1]
            if len(large) > 1:
                return None
            if len(large) == 1:
                large_set = set(large[0])
                for comp in comps:
                    if len(comp) == 1 and comp[0] not in large_set:
                        res = assign(state, comp[0], 1)
                        if res == -1:
                            return None
                        if res == 1:
                            progress = True

        return progress

    def basic_feasible(state):
        # No adjacent blacks.
        for i, s in enumerate(state):
            if s == 1:
                for j in neighbors[i]:
                    if state[j] == 1:
                        return False

        # Duplicate groups: at most one white.
        for group in groups:
            w = 0
            for i in group:
                if state[i] == 0:
                    w += 1
                    if w > 1:
                        return False

        # If whites exist, they must still be connectable through non-black cells.
        whites = [i for i, s in enumerate(state) if s == 0]
        if whites:
            comp = connected_component_passable(state, whites[0])
            for w in whites:
                if w not in comp:
                    return False

        # Some cell must remain potentially white.
        if not any(s != 1 for s in state):
            return False

        return True

    shallow_cache = {}

    def propagate(state, enable_singletons):
        while True:
            progress = False

            for i, val in static_forces.items():
                res = assign(state, i, val)
                if res == -1:
                    return False
                if res == 1:
                    progress = True

            for i, s in enumerate(state):
                if s == 1:
                    for j in neighbors[i]:
                        res = assign(state, j, 0)
                        if res == -1:
                            return False
                        if res == 1:
                            progress = True

            for group in groups:
                white_seen = None
                for i in group:
                    if state[i] == 0:
                        if white_seen is not None:
                            return False
                        white_seen = i
                if white_seen is not None:
                    for i in group:
                        if i != white_seen:
                            res = assign(state, i, 1)
                            if res == -1:
                                return False
                            if res == 1:
                                progress = True

            conn = connectivity_propagate(state)
            if conn is None:
                return False
            if conn:
                progress = True

            if not basic_feasible(state):
                return False

            if enable_singletons:
                forced = False
                unknowns = [i for i, s in enumerate(state) if s == -1]
                unknowns.sort(key=lambda i: (len(cell_group_ids[i]) == 0, -sum(len(groups[g]) for g in cell_group_ids[i]), -len(neighbors[i])))
                for i in unknowns:
                    if not possible_assign(state, i, 0):
                        res = assign(state, i, 1)
                        if res == -1:
                            return False
                        if res == 1:
                            progress = True
                            forced = True
                            break
                    if not possible_assign(state, i, 1):
                        res = assign(state, i, 0)
                        if res == -1:
                            return False
                        if res == 1:
                            progress = True
                            forced = True
                            break
                if forced:
                    continue

            if not progress:
                break

        return basic_feasible(state)

    def possible_assign(state, i, val):
        key = (tuple(state), i, val)
        if key in shallow_cache:
            return shallow_cache[key]
        test = state.copy()
        res = assign(test, i, val)
        if res == -1:
            shallow_cache[key] = False
            return False
        ok = propagate(test, enable_singletons=False)
        shallow_cache[key] = ok
        return ok

    def final_valid(state):
        if any(s == -1 for s in state):
            return False
        if not any(s == 0 for s in state):
            return False

        for i, s in enumerate(state):
            if s == 1:
                for j in neighbors[i]:
                    if state[j] == 1:
                        return False

        for r in range(n):
            seen = set()
            for c in range(n):
                i = idx(r, c)
                if state[i] != 1:
                    v = data[r][c]
                    if v in seen:
                        return False
                    seen.add(v)

        for c in range(n):
            seen = set()
            for r in range(n):
                i = idx(r, c)
                if state[i] != 1:
                    v = data[r][c]
                    if v in seen:
                        return False
                    seen.add(v)

        whites = [i for i, s in enumerate(state) if s == 0]
        comp = connected_component_passable(state, whites[0])
        return len(comp) == len(whites)

    def choose_cell(state):
        best_i = None
        best_metric = None
        best_opts = None
        for i, s in enumerate(state):
            if s != -1:
                continue
            can_w = possible_assign(state, i, 0)
            can_b = possible_assign(state, i, 1)
            if not can_w and not can_b:
                return i, (False, False)
            options = int(can_w) + int(can_b)
            degree = sum(len(groups[g]) for g in cell_group_ids[i]) + len(neighbors[i])
            metric = (options, -degree)
            if best_metric is None or metric < best_metric:
                best_metric = metric
                best_i = i
                best_opts = (can_w, can_b)
                if options == 1:
                    break
        return best_i, best_opts

    def dfs(state, already_propagated=False):
        if not already_propagated:
            if not propagate(state, enable_singletons=True):
                return None

        if all(s != -1 for s in state):
            return state if final_valid(state) else None

        i, (can_w, can_b) = choose_cell(state)
        if i is None:
            return None
        if not can_w and not can_b:
            return None

        branches = []
        if can_w:
            st = state.copy()
            if assign(st, i, 0) != -1 and propagate(st, enable_singletons=True):
                branches.append(st)
        if can_b:
            st = state.copy()
            if assign(st, i, 1) != -1 and propagate(st, enable_singletons=True):
                branches.append(st)

        branches.sort(key=lambda st: st.count(-1))

        for st in branches:
            res = dfs(st, already_propagated=True)
            if res is not None:
                return res
        return None

    init_state = [-1] * m
    solution = dfs(init_state)
    if solution is None:
        return "No Solution"

    mask = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if solution[idx(r, c)] == 1 else None)
        mask.append(row)
    return str(mask)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[1, 5, 3, 4, 1], [5, 3, 5, 3, 1], [3, 5, 4, 1, 5], [5, 1, 2, 3, 4], [2, 1, 1, 1, 3]]}

# Generalized Hitori solver.
# Returns a mask grid with 'B' for black cells and None for white cells.

U = 0
W = 1
B = 2


class HitoriSolver:
    def __init__(self, board):
        self.board = board
        self.n = len(board)
        self.m = self.n * self.n
        self.adj = [[] for _ in range(self.m)]
        self.conflicts = [set() for _ in range(self.m)]
        self.memo_unsat = set()

        for r in range(self.n):
            for c in range(self.n):
                i = self.idx(r, c)
                if r > 0:
                    self.adj[i].append(self.idx(r - 1, c))
                if r + 1 < self.n:
                    self.adj[i].append(self.idx(r + 1, c))
                if c > 0:
                    self.adj[i].append(self.idx(r, c - 1))
                if c + 1 < self.n:
                    self.adj[i].append(self.idx(r, c + 1))

        # Duplicate constraints in rows.
        for r in range(self.n):
            groups = {}
            for c in range(self.n):
                v = board[r][c]
                groups.setdefault(v, []).append(self.idx(r, c))
            for cells in groups.values():
                if len(cells) >= 2:
                    for i in range(len(cells)):
                        a = cells[i]
                        for j in range(i + 1, len(cells)):
                            b = cells[j]
                            self.conflicts[a].add(b)
                            self.conflicts[b].add(a)

        # Duplicate constraints in columns.
        for c in range(self.n):
            groups = {}
            for r in range(self.n):
                v = board[r][c]
                groups.setdefault(v, []).append(self.idx(r, c))
            for cells in groups.values():
                if len(cells) >= 2:
                    for i in range(len(cells)):
                        a = cells[i]
                        for j in range(i + 1, len(cells)):
                            b = cells[j]
                            self.conflicts[a].add(b)
                            self.conflicts[b].add(a)

        self.no_conflict_cells = [i for i in range(self.m) if not self.conflicts[i]]

    def idx(self, r, c):
        return r * self.n + c

    def rc(self, i):
        return divmod(i, self.n)

    def component_summary(self, status):
        avail = [i for i in range(self.m) if status[i] != B]
        if not avail:
            return []

        seen = [False] * self.m
        comps = []
        for start in avail:
            if seen[start]:
                continue
            stack = [start]
            seen[start] = True
            nodes = []
            white_count = 0
            while stack:
                x = stack.pop()
                nodes.append(x)
                if status[x] == W:
                    white_count += 1
                for y in self.adj[x]:
                    if status[y] != B and not seen[y]:
                        seen[y] = True
                        stack.append(y)
            comps.append((nodes, white_count))
        return comps

    def component_contradiction(self, status):
        comps = self.component_summary(status)
        if not comps:
            return True

        white_comps = sum(1 for _, wc in comps if wc > 0)
        if white_comps > 1:
            return True

        if len(comps) == 1:
            return False

        if white_comps == 1:
            # Every other component must vanish entirely; any connected component
            # of size > 1 cannot become all-black because adjacent black cells are forbidden.
            for nodes, wc in comps:
                if wc == 0 and len(nodes) > 1:
                    return True
            return False

        # No fixed white component yet. At most one multi-cell component can survive.
        large = sum(1 for nodes, wc in comps if len(nodes) > 1)
        return large > 1

    def apply_queue(self, status, queue):
        while queue:
            i, color = queue.pop()
            cur = status[i]
            if cur == color:
                continue
            if cur != U:
                return None
            status[i] = color
            if color == W:
                for j in self.conflicts[i]:
                    queue.append((j, B))
            else:
                for j in self.adj[i]:
                    queue.append((j, W))
        return status

    def candidate_score(self, status, i):
        unresolved_conf = 0
        for j in self.conflicts[i]:
            if status[j] != B:
                unresolved_conf += 1
        avail_adj = 0
        for j in self.adj[i]:
            if status[j] != B:
                avail_adj += 1
        return unresolved_conf * 10 + avail_adj * 2 + len(self.conflicts[i])

    def ordered_unknowns(self, status):
        cells = [i for i in range(self.m) if status[i] == U]
        cells.sort(key=lambda i: self.candidate_score(status, i), reverse=True)
        return cells

    def propagate_core(self, status, initial_queue, force_black_impossible):
        status = status[:]
        queue = list(initial_queue)

        while True:
            status = self.apply_queue(status, queue)
            if status is None:
                return None

            if self.component_contradiction(status):
                return None

            if not force_black_impossible:
                return status

            progress = False
            for i in self.ordered_unknowns(status):
                trial = self.propagate_core(status, [(i, B)], force_black_impossible=False)
                if trial is None:
                    queue.append((i, W))
                    progress = True
                    break

            if not progress:
                return status

    def propagate_full(self, status):
        status = self.propagate_core(status, [], force_black_impossible=True)
        if status is None:
            return None

        while True:
            progress = False
            for i in self.ordered_unknowns(status):
                can_black = self.propagate_core(status, [(i, B)], force_black_impossible=False) is not None
                if not can_black:
                    status = self.propagate_core(status, [(i, W)], force_black_impossible=True)
                    if status is None:
                        return None
                    progress = True
                    break

                can_white = self.propagate_core(status, [(i, W)], force_black_impossible=False) is not None
                if not can_white:
                    status = self.propagate_core(status, [(i, B)], force_black_impossible=True)
                    if status is None:
                        return None
                    progress = True
                    break

            if not progress:
                return status

    def validate_complete(self, status):
        if any(s == U for s in status):
            return False

        # No adjacent black cells.
        for i in range(self.m):
            if status[i] == B:
                for j in self.adj[i]:
                    if status[j] == B:
                        return False

        # Duplicate rule.
        for i in range(self.m):
            if status[i] == W:
                for j in self.conflicts[i]:
                    if status[j] == W:
                        return False

        whites = [i for i in range(self.m) if status[i] == W]
        if not whites:
            return False

        # White connectivity.
        seen = set([whites[0]])
        stack = [whites[0]]
        while stack:
            x = stack.pop()
            for y in self.adj[x]:
                if status[y] == W and y not in seen:
                    seen.add(y)
                    stack.append(y)
        return len(seen) == len(whites)

    def choose_branch_cell(self, status):
        unknowns = self.ordered_unknowns(status)
        if not unknowns:
            return None
        return unknowns[0]

    def branch_order(self, status, i):
        unresolved_conf = sum(1 for j in self.conflicts[i] if status[j] != B)
        avail_adj = sum(1 for j in self.adj[i] if status[j] != B)
        if unresolved_conf >= avail_adj:
            return [W, B]
        return [B, W]

    def search(self, status):
        key = tuple(status)
        if key in self.memo_unsat:
            return None

        status = self.propagate_full(status)
        if status is None:
            self.memo_unsat.add(key)
            return None

        t = tuple(status)
        if t in self.memo_unsat:
            return None

        # Fast finish attempt: all remaining unknowns as white.
        final_try = [W if s == U else s for s in status]
        if self.validate_complete(final_try):
            return final_try

        cell = self.choose_branch_cell(status)
        if cell is None:
            self.memo_unsat.add(t)
            return None

        trials = []
        for color in self.branch_order(status, cell):
            s2 = self.propagate_core(status, [(cell, color)], force_black_impossible=True)
            if s2 is not None:
                trials.append((s2.count(U), tuple(s2)))

        if not trials:
            self.memo_unsat.add(t)
            return None

        trials.sort()
        for _, child in trials:
            res = self.search(list(child))
            if res is not None:
                return res

        self.memo_unsat.add(t)
        return None

    def solve_mask(self):
        status = [U] * self.m
        initial = [(i, W) for i in self.no_conflict_cells]
        status = self.propagate_core(status, initial, force_black_impossible=True)
        if status is None:
            return None

        result = self.search(status)
        if result is None:
            return None

        mask = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                s = result[self.idx(r, c)]
                row.append('B' if s == B else None)
            mask.append(row)
        return mask


def solve(observation):
    board = observation['data']
    solver = HitoriSolver(board)
    ans = solver.solve_mask()
    return ans if ans is not None else "No Solution"


