# General solver for the numbered loop-on-dots puzzle:
# - single orthogonal loop
# - clue vertices are mandatory loop vertices
# - white clue: straight-through
# - black clue: turn
# - number = sum of the two maximal straight run lengths starting from the clue
#
# The solver mirrors human deduction:
# 1) enumerate every locally legal length-pattern for each clue
# 2) repeatedly eliminate clue-patterns that conflict with current vertex domains
# 3) propagate ordinary loop consistency (degree-2 / edge matching via state domains)
# 4) branch only on the most constrained clue, then on the most constrained vertex

import sys

S_EMPTY = 0
S_UD = 1
S_LR = 2
S_UR = 3
S_UL = 4
S_DR = 5
S_DL = 6

STATE_DIR_MASK = [
    0,          # empty
    1 | 2,      # U D
    4 | 8,      # L R
    1 | 8,      # U R
    1 | 4,      # U L
    2 | 8,      # D R
    2 | 4,      # D L
]

DIR_U, DIR_D, DIR_L, DIR_R = 0, 1, 2, 3
DR = [-1, 1, 0, 0]
DC = [0, 0, -1, 1]
DBIT = [1, 2, 4, 8]
OPP = [DIR_D, DIR_U, DIR_R, DIR_L]

STATE_BIT = [1 << i for i in range(7)]
FULL_DOMAIN = (1 << 7) - 1
TURN_DOMAIN = STATE_BIT[S_UR] | STATE_BIT[S_UL] | STATE_BIT[S_DR] | STATE_BIT[S_DL]
WHITE_DOMAIN = STATE_BIT[S_UD] | STATE_BIT[S_LR]
NONEMPTY_DOMAIN = FULL_DOMAIN ^ STATE_BIT[S_EMPTY]

TURN_STATES = (S_UR, S_UL, S_DR, S_DL)

STRAIGHT_STATE_FOR_DIR = {
    DIR_U: S_UD,
    DIR_D: S_UD,
    DIR_L: S_LR,
    DIR_R: S_LR,
}

TURN_MASK_REQUIRING_DIR = {
    DBIT[DIR_U]: STATE_BIT[S_UR] | STATE_BIT[S_UL],
    DBIT[DIR_D]: STATE_BIT[S_DR] | STATE_BIT[S_DL],
    DBIT[DIR_L]: STATE_BIT[S_UL] | STATE_BIT[S_DL],
    DBIT[DIR_R]: STATE_BIT[S_UR] | STATE_BIT[S_DR],
}

TURN_STATE_TO_DIRS = {
    S_UR: (DIR_U, DIR_R),
    S_UL: (DIR_U, DIR_L),
    S_DR: (DIR_D, DIR_R),
    S_DL: (DIR_D, DIR_L),
}

WHITE_STATE_TO_DIRS = {
    S_UD: (DIR_U, DIR_D),
    S_LR: (DIR_L, DIR_R),
}

INCLUDE = [[bool(STATE_DIR_MASK[s] & DBIT[d]) for d in range(4)] for s in range(7)]

SUPPORT = [[0] * 7 for _ in range(4)]
for d in range(4):
    od = OPP[d]
    for s in range(7):
        need = INCLUDE[s][d]
        mask = 0
        for t in range(7):
            if INCLUDE[t][od] == need:
                mask |= STATE_BIT[t]
        SUPPORT[d][s] = mask


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation['data']
    h = len(data)
    w = len(data[0])

    def vid(r, c):
        return r * w + c

    def rc(v):
        return divmod(v, w)

    def inside(r, c):
        return 0 <= r < h and 0 <= c < w

    neighbors = [[-1] * 4 for _ in range(h * w)]
    for r in range(h):
        for c in range(w):
            v = vid(r, c)
            for d in range(4):
                nr, nc = r + DR[d], c + DC[d]
                if inside(nr, nc):
                    neighbors[v][d] = vid(nr, nc)

    clues = []
    clue_pos_set = set()
    initial_domains = [FULL_DOMAIN] * (h * w)

    # Border legality.
    for r in range(h):
        for c in range(w):
            v = vid(r, c)
            dom = FULL_DOMAIN
            for s in range(7):
                if not (dom & STATE_BIT[s]):
                    continue
                ok = True
                if r == 0 and INCLUDE[s][DIR_U]:
                    ok = False
                if r == h - 1 and INCLUDE[s][DIR_D]:
                    ok = False
                if c == 0 and INCLUDE[s][DIR_L]:
                    ok = False
                if c == w - 1 and INCLUDE[s][DIR_R]:
                    ok = False
                if not ok:
                    dom &= ~STATE_BIT[s]
            initial_domains[v] = dom

    # Clue type legality.
    for r in range(h):
        for c in range(w):
            tok = data[r][c]
            if tok is None:
                continue
            v = vid(r, c)
            clue_pos_set.add(v)
            t = tok[0]
            k = int(tok[1:])
            if t == 'W':
                initial_domains[v] &= WHITE_DOMAIN
            else:
                initial_domains[v] &= TURN_DOMAIN
            if initial_domains[v] == 0:
                return "No Solution"
            clues.append({
                'pos': v,
                'r': r,
                'c': c,
                'type': t,
                'k': k,
                'token': tok,
                'cands': [],
            })

    def add_restr(restr, v, mask):
        prev = restr.get(v, FULL_DOMAIN)
        new = prev & mask
        if new == 0:
            return False
        restr[v] = new
        return True

    # Enumerate all local length-patterns for each clue.
    for clue in clues:
        r, c = clue['r'], clue['c']
        k = clue['k']
        cand_list = []

        if clue['type'] == 'W':
            state_options = (S_UD, S_LR)
            state_dirs_map = WHITE_STATE_TO_DIRS
        else:
            state_options = TURN_STATES
            state_dirs_map = TURN_STATE_TO_DIRS

        for clue_state in state_options:
            if not (initial_domains[clue['pos']] & STATE_BIT[clue_state]):
                continue
            d1, d2 = state_dirs_map[clue_state]

            for a in range(1, k):
                b = k - a
                restr = {}
                ok = True

                if not add_restr(restr, clue['pos'], STATE_BIT[clue_state]):
                    continue

                for d, length in ((d1, a), (d2, b)):
                    sr, sc = r, c
                    straight_state = STRAIGHT_STATE_FOR_DIR[d]

                    for step in range(1, length):
                        nr, nc = sr + DR[d] * step, sc + DC[d] * step
                        if not inside(nr, nc):
                            ok = False
                            break
                        v = vid(nr, nc)
                        if not add_restr(restr, v, STATE_BIT[straight_state]):
                            ok = False
                            break
                    if not ok:
                        break

                    er, ec = sr + DR[d] * length, sc + DC[d] * length
                    if not inside(er, ec):
                        ok = False
                        break
                    ev = vid(er, ec)
                    endpoint_mask = TURN_MASK_REQUIRING_DIR[DBIT[OPP[d]]]
                    if not add_restr(restr, ev, endpoint_mask):
                        ok = False
                        break

                if not ok:
                    continue

                # Early filtering against static legality.
                for v, mask in restr.items():
                    if initial_domains[v] & mask == 0:
                        ok = False
                        break
                if not ok:
                    continue

                pairs = tuple(sorted(restr.items()))
                cand_list.append((pairs, STATE_BIT[clue_state], len(pairs)))

        # Remove duplicates that can arise through equivalent construction.
        uniq = {}
        for cand in cand_list:
            uniq[cand[0]] = cand
        clue['cands'] = sorted(uniq.values(), key=lambda x: (-x[2], x[0]))

        if not clue['cands']:
            return "No Solution"

    domains0 = initial_domains[:]
    remaining0 = [list(range(len(clue['cands']))) for clue in clues]

    def enforce_arc(domains):
        changed = False
        while True:
            local_change = False
            for v in range(h * w):
                dom = domains[v]
                newdom = 0
                for s in range(7):
                    if not (dom & STATE_BIT[s]):
                        continue
                    ok = True
                    for d in range(4):
                        nv = neighbors[v][d]
                        if nv == -1:
                            if INCLUDE[s][d]:
                                ok = False
                                break
                        else:
                            if domains[nv] & SUPPORT[d][s] == 0:
                                ok = False
                                break
                    if ok:
                        newdom |= STATE_BIT[s]
                if newdom == 0:
                    return False, changed or local_change
                if newdom != dom:
                    domains[v] = newdom
                    local_change = True
            changed |= local_change
            if not local_change:
                break
        return True, changed

    def propagate(domains, remaining):
        while True:
            any_change = False

            for ci, clue in enumerate(clues):
                cur = remaining[ci]
                new = []
                for idx in cur:
                    pairs, clue_state_mask, _ = clue['cands'][idx]
                    ok = True
                    for v, mask in pairs:
                        if domains[v] & mask == 0:
                            ok = False
                            break
                    if ok:
                        new.append(idx)

                if not new:
                    return None

                if len(new) != len(cur):
                    remaining[ci] = new
                    any_change = True

                # Every remaining candidate constrains the clue vertex.
                union_mask = 0
                for idx in new:
                    union_mask |= clue['cands'][idx][1]
                v = clue['pos']
                nd = domains[v] & union_mask
                if nd == 0:
                    return None
                if nd != domains[v]:
                    domains[v] = nd
                    any_change = True

                # If only one length-pattern remains, enforce all of it.
                if len(new) == 1:
                    pairs = clue['cands'][new[0]][0]
                    for v2, mask in pairs:
                        nd2 = domains[v2] & mask
                        if nd2 == 0:
                            return None
                        if nd2 != domains[v2]:
                            domains[v2] = nd2
                            any_change = True

            ok, ac_change = enforce_arc(domains)
            if not ok:
                return None
            any_change |= ac_change

            if not any_change:
                break

        return domains, remaining

    def singleton_state(dom):
        return dom.bit_length() - 1

    def build_state_list(domains):
        states = [0] * (h * w)
        for v, dom in enumerate(domains):
            if dom.bit_count() != 1:
                return None
            states[v] = singleton_state(dom)
        return states

    def segment_length(states, start_v, d):
        cur = start_v
        steps = 0
        while True:
            nv = neighbors[cur][d]
            if nv == -1:
                return None
            steps += 1
            s = states[nv]
            if s == S_EMPTY:
                return None
            if not INCLUDE[s][OPP[d]]:
                return None

            if s == STRAIGHT_STATE_FOR_DIR[d]:
                if not INCLUDE[s][d]:
                    return None
                cur = nv
                continue

            # Must be a turn endpoint: includes opposite(d), excludes d.
            if INCLUDE[s][d]:
                return None
            return steps

    def final_path_from_states(states):
        used = [v for v, s in enumerate(states) if s != S_EMPTY]
        if not used:
            return None

        adj = {v: set() for v in used}
        used_set = set(used)

        for v in used:
            s = states[v]
            for d in range(4):
                if not INCLUDE[s][d]:
                    continue
                nv = neighbors[v][d]
                if nv == -1 or nv not in used_set:
                    return None
                if not INCLUDE[states[nv]][OPP[d]]:
                    return None
                adj[v].add(nv)

        for v in used:
            if len(adj[v]) != 2:
                return None

        # Single cycle connectivity.
        start = min(used, key=rc)
        stack = [start]
        seen = {start}
        while stack:
            v = stack.pop()
            for nv in adj[v]:
                if nv not in seen:
                    seen.add(nv)
                    stack.append(nv)
        if len(seen) != len(used):
            return None

        # Clue checks, including the numbered straight-run condition.
        for clue in clues:
            v = clue['pos']
            s = states[v]
            if clue['type'] == 'W':
                if s not in (S_UD, S_LR):
                    return None
            else:
                if s not in TURN_STATES:
                    return None

            dirs = [d for d in range(4) if INCLUDE[s][d]]
            if len(dirs) != 2:
                return None

            total = 0
            for d in dirs:
                L = segment_length(states, v, d)
                if L is None:
                    return None
                total += L
            if total != clue['k']:
                return None

        # Recover an ordered closed walk.
        path = [rc(start)]
        prev = None
        cur = start
        while True:
            nbs = sorted(adj[cur], key=rc)
            if prev is None:
                nxt = nbs[0]
            else:
                nxt = nbs[0] if nbs[0] != prev else nbs[1]
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break

        return path

    fail_cache = set()

    def state_key(domains, remaining):
        return (
            tuple(domains),
            tuple(tuple(lst) for lst in remaining),
        )

    def search(domains, remaining):
        propagated = propagate(domains, remaining)
        if propagated is None:
            return None
        domains, remaining = propagated

        key = state_key(domains, remaining)
        if key in fail_cache:
            return None

        all_singleton = all(dom.bit_count() == 1 for dom in domains)
        if all_singleton:
            states = build_state_list(domains)
            path = final_path_from_states(states)
            if path is not None:
                return path
            fail_cache.add(key)
            return None

        # Branch first on the most constrained clue-pattern choice.
        best_ci = None
        best_count = 10**9
        for ci, lst in enumerate(remaining):
            c = len(lst)
            if 1 < c < best_count:
                best_count = c
                best_ci = ci

        if best_ci is not None:
            order = remaining[best_ci][:]
            order.sort(key=lambda idx: -clues[best_ci]['cands'][idx][2])
            for idx in order:
                ndom = domains[:]
                nrem = [lst[:] for lst in remaining]
                nrem[best_ci] = [idx]
                ans = search(ndom, nrem)
                if ans is not None:
                    return ans
            fail_cache.add(key)
            return None

        # Otherwise branch on the tightest vertex domain.
        best_v = None
        best_size = 10**9
        for v, dom in enumerate(domains):
            bc = dom.bit_count()
            if 1 < bc < best_size:
                best_size = bc
                best_v = v

        if best_v is None:
            fail_cache.add(key)
            return None

        dom = domains[best_v]
        states = [s for s in range(7) if dom & STATE_BIT[s]]

        # Slightly prefer empty at non-clues to keep the loop minimal unless forced.
        if best_v in clue_pos_set:
            order = states
        else:
            priority = {
                S_EMPTY: 0,
                S_UD: 1,
                S_LR: 2,
                S_UR: 3,
                S_UL: 4,
                S_DR: 5,
                S_DL: 6,
            }
            order = sorted(states, key=lambda s: priority[s])

        for s in order:
            ndom = domains[:]
            nrem = [lst[:] for lst in remaining]
            ndom[best_v] = STATE_BIT[s]
            ans = search(ndom, nrem)
            if ans is not None:
                return ans

        fail_cache.add(key)
        return None

    ans = search(domains0, remaining0)
    if ans is None:
        return "No Solution"
    return repr(ans)


