# General solver for the numbered black/white loop puzzle.
# The solver is clue-driven:
# - It enumerates all feasible local clue patterns as maximal straight runs.
# - It propagates edge consequences from clue domains and vertex degree rules.
# - It prunes premature cycles.
# - It backtracks on the smallest clue domain first, then on edges only if needed.

import sys

sys.setrecursionlimit(10000)


def solve(observation):
    data = observation["data"]
    N = len(data) - 1
    W = N + 1

    def vid(r, c):
        return r * W + c

    def rc_of(v):
        return divmod(v, W)

    HCOUNT = (N + 1) * N
    VBASE = HCOUNT
    ECOUNT = HCOUNT + N * (N + 1)

    def h_id(r, c):
        return r * N + c

    def v_id(r, c):
        return VBASE + r * W + c

    edge_endpoints = [None] * ECOUNT
    for r in range(N + 1):
        for c in range(N):
            e = h_id(r, c)
            edge_endpoints[e] = (vid(r, c), vid(r, c + 1))
    for r in range(N):
        for c in range(N + 1):
            e = v_id(r, c)
            edge_endpoints[e] = (vid(r, c), vid(r + 1, c))

    incident_mask = [0] * (W * W)
    incident_edges = [[] for _ in range(W * W)]
    dir_edge = {}
    for r in range(W):
        for c in range(W):
            m = {}
            if r > 0:
                e = v_id(r - 1, c)
                m["U"] = e
                incident_mask[vid(r, c)] |= 1 << e
                incident_edges[vid(r, c)].append(e)
            if r < N:
                e = v_id(r, c)
                m["D"] = e
                incident_mask[vid(r, c)] |= 1 << e
                incident_edges[vid(r, c)].append(e)
            if c > 0:
                e = h_id(r, c - 1)
                m["L"] = e
                incident_mask[vid(r, c)] |= 1 << e
                incident_edges[vid(r, c)].append(e)
            if c < N:
                e = h_id(r, c)
                m["R"] = e
                incident_mask[vid(r, c)] |= 1 << e
                incident_edges[vid(r, c)].append(e)
            dir_edge[(r, c)] = m

    clues = []
    clue_vids = set()
    clue_at = {}
    for r in range(W):
        for c in range(W):
            tok = data[r][c]
            if tok is not None:
                color = tok[0]
                k = int(tok[1:])
                idx = len(clues)
                clues.append((r, c, color, k))
                clue_vids.add(vid(r, c))
                clue_at[(r, c)] = (color, k, idx)

    def iter_bits(mask):
        while mask:
            lb = mask & -mask
            yield lb.bit_length() - 1
            mask ^= lb

    def valid_horizontal(r, c1, c2, length):
        if not (0 <= c1 < c2 <= N):
            return False
        t1 = data[r][c1]
        t2 = data[r][c2]
        if t1 is not None and t1[0] == "W":
            return False
        if t2 is not None and t2[0] == "W":
            return False
        for c in range(c1 + 1, c2):
            tok = data[r][c]
            if tok is None:
                continue
            if tok[0] == "B":
                return False
            if int(tok[1:]) != length:
                return False
        return True

    def valid_vertical(r1, r2, c, length):
        if not (0 <= r1 < r2 <= N):
            return False
        t1 = data[r1][c]
        t2 = data[r2][c]
        if t1 is not None and t1[0] == "W":
            return False
        if t2 is not None and t2[0] == "W":
            return False
        for r in range(r1 + 1, r2):
            tok = data[r][c]
            if tok is None:
                continue
            if tok[0] == "B":
                return False
            if int(tok[1:]) != length:
                return False
        return True

    def horizontal_segment_masks(r, c1, c2):
        on = 0
        off = 0
        for c in range(c1, c2):
            on |= 1 << h_id(r, c)
        for c in range(c1 + 1, c2):
            if r > 0:
                off |= 1 << v_id(r - 1, c)
            if r < N:
                off |= 1 << v_id(r, c)
        if c1 > 0:
            off |= 1 << h_id(r, c1 - 1)
        if c2 < N:
            off |= 1 << h_id(r, c2)
        return on, off

    def vertical_segment_masks(r1, r2, c):
        on = 0
        off = 0
        for r in range(r1, r2):
            on |= 1 << v_id(r, c)
        for r in range(r1 + 1, r2):
            if c > 0:
                off |= 1 << h_id(r, c - 1)
            if c < N:
                off |= 1 << h_id(r, c)
        if r1 > 0:
            off |= 1 << v_id(r1 - 1, c)
        if r2 < N:
            off |= 1 << v_id(r2, c)
        return on, off

    patterns = []
    branch_order = []
    edge_activity = [0] * ECOUNT

    for (r, c, color, k) in clues:
        local = []
        if color == "W":
            for a in range(1, k):
                b = k - a
                c1, c2 = c - a, c + b
                if valid_horizontal(r, c1, c2, k):
                    on, off = horizontal_segment_masks(r, c1, c2)
                    local.append((on, off))
                r1, r2 = r - a, r + b
                if valid_vertical(r1, r2, c, k):
                    on, off = vertical_segment_masks(r1, r2, c)
                    local.append((on, off))
        else:
            for hlen in range(1, k):
                vlen = k - hlen
                # up + left
                if valid_horizontal(r, c - hlen, c, hlen) and valid_vertical(r - vlen, r, c, vlen):
                    on1, off1 = horizontal_segment_masks(r, c - hlen, c)
                    on2, off2 = vertical_segment_masks(r - vlen, r, c)
                    local.append((on1 | on2, off1 | off2))
                # up + right
                if valid_horizontal(r, c, c + hlen, hlen) and valid_vertical(r - vlen, r, c, vlen):
                    on1, off1 = horizontal_segment_masks(r, c, c + hlen)
                    on2, off2 = vertical_segment_masks(r - vlen, r, c)
                    local.append((on1 | on2, off1 | off2))
                # down + left
                if valid_horizontal(r, c - hlen, c, hlen) and valid_vertical(r, r + vlen, c, vlen):
                    on1, off1 = horizontal_segment_masks(r, c - hlen, c)
                    on2, off2 = vertical_segment_masks(r, r + vlen, c)
                    local.append((on1 | on2, off1 | off2))
                # down + right
                if valid_horizontal(r, c, c + hlen, hlen) and valid_vertical(r, r + vlen, c, vlen):
                    on1, off1 = horizontal_segment_masks(r, c, c + hlen)
                    on2, off2 = vertical_segment_masks(r, r + vlen, c)
                    local.append((on1 | on2, off1 | off2))

        # deduplicate exact duplicate patterns
        seen = set()
        dedup = []
        for p in local:
            if p not in seen:
                seen.add(p)
                dedup.append(p)
        local = dedup

        if not local:
            return "No Solution"

        patterns.append(local)
        order = sorted(range(len(local)), key=lambda j: (-(local[j][0].bit_count() + local[j][1].bit_count()), j))
        branch_order.append(order)
        for on, off in local:
            m = on | off
            while m:
                lb = m & -m
                edge_activity[lb.bit_length() - 1] += 1
                m ^= lb

    init_domains = [(1 << len(pats)) - 1 for pats in patterns]
    all_edge_mask = (1 << ECOUNT) - 1

    def cycle_status(on_bits):
        if on_bits == 0:
            return 0, None
        adj = {}
        for e in iter_bits(on_bits):
            a, b = edge_endpoints[e]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
        visited = set()
        cycle_comp = None
        cycle_edges = 0
        for start in adj:
            if start in visited:
                continue
            stack = [start]
            comp = []
            closed = True
            deg_sum = 0
            while stack:
                v = stack.pop()
                if v in visited:
                    continue
                visited.add(v)
                comp.append(v)
                deg = len(adj[v])
                deg_sum += deg
                if deg != 2:
                    closed = False
                for nb in adj[v]:
                    if nb not in visited:
                        stack.append(nb)
            if closed:
                if cycle_comp is not None:
                    return -1, None
                cycle_comp = set(comp)
                cycle_edges = deg_sum // 2
        if cycle_comp is not None:
            if cycle_edges != on_bits.bit_count():
                return -1, None
            return 1, cycle_comp
        return 0, None

    def propagate(domains, on_bits, off_bits):
        domains = list(domains)
        while True:
            changed = False

            # Filter clue domains and derive consensus edges.
            for i, pats in enumerate(patterns):
                dom = domains[i]
                new_dom = 0
                first = True
                all_on = 0
                all_off = 0
                for j in iter_bits(dom):
                    pon, poff = pats[j]
                    if (pon & off_bits) or (poff & on_bits):
                        continue
                    new_dom |= 1 << j
                    if first:
                        all_on = pon
                        all_off = poff
                        first = False
                    else:
                        all_on &= pon
                        all_off &= poff
                if new_dom == 0:
                    return None
                if new_dom != dom:
                    domains[i] = new_dom
                    changed = True
                force_on = all_on & ~on_bits
                if force_on & off_bits:
                    return None
                if force_on:
                    on_bits |= force_on
                    changed = True
                force_off = all_off & ~off_bits
                if force_off & on_bits:
                    return None
                if force_off:
                    off_bits |= force_off
                    changed = True

            # Degree propagation at every vertex.
            for v in range(W * W):
                inc = incident_mask[v]
                onm = inc & on_bits
                offm = inc & off_bits
                unk = inc & ~(on_bits | off_bits)
                onc = onm.bit_count()
                unkc = unk.bit_count()

                allowed = [2] if v in clue_vids else [0, 2]
                feasible = [d for d in allowed if onc <= d <= onc + unkc]
                if not feasible:
                    return None

                # If only degree 0 remains, all unknown edges must be off.
                if feasible == [0]:
                    if unk & on_bits:
                        return None
                    if unk:
                        off_bits |= unk
                        changed = True
                    continue

                # If only degree 2 remains, maybe force.
                if 2 in feasible and len(feasible) == 1:
                    if onc > 2:
                        return None
                    if onc == 2:
                        rem = unk & ~off_bits
                        if rem:
                            off_bits |= rem
                            changed = True
                    elif onc + unkc == 2:
                        rem = unk & ~on_bits
                        if rem:
                            if rem & off_bits:
                                return None
                            on_bits |= rem
                            changed = True
                    elif onc + unkc < 2:
                        return None

                # General useful deductions.
                if onc > 2:
                    return None
                if onc == 2:
                    rem = unk & ~off_bits
                    if rem:
                        off_bits |= rem
                        changed = True
                elif onc == 1 and unkc == 0:
                    return None
                elif onc == 1 and unkc == 1:
                    rem = unk & ~on_bits
                    if rem:
                        if rem & off_bits:
                            return None
                        on_bits |= rem
                        changed = True
                elif onc == 0 and unkc == 1 and 0 in feasible and 2 not in feasible:
                    rem = unk & ~off_bits
                    if rem:
                        off_bits |= rem
                        changed = True
                elif onc == 0 and unkc == 1 and 2 not in feasible:
                    rem = unk & ~off_bits
                    if rem:
                        off_bits |= rem
                        changed = True

            # Cycle pruning.
            status, comp = cycle_status(on_bits)
            if status == -1:
                return None
            if status == 1:
                for r, c, _, _ in clues:
                    if vid(r, c) not in comp:
                        return None

            if not changed:
                return domains, on_bits, off_bits

    failed = set()

    def choose_edge(on_bits, off_bits):
        unknown = all_edge_mask & ~(on_bits | off_bits)
        best_e = None
        best_score = -1
        for e in iter_bits(unknown):
            a, b = edge_endpoints[e]
            score = edge_activity[e] * 10
            for v in (a, b):
                deg_on = (incident_mask[v] & on_bits).bit_count()
                deg_unk = (incident_mask[v] & unknown).bit_count()
                if v in clue_vids:
                    score += 5
                if deg_on == 1:
                    score += 4
                if deg_unk <= 2:
                    score += 2
            if score > best_score:
                best_score = score
                best_e = e
        return best_e

    def reconstruct_path(on_bits):
        adj = {}
        verts = set()
        for e in iter_bits(on_bits):
            a, b = edge_endpoints[e]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
            verts.add(a)
            verts.add(b)
        if not verts:
            return None
        start = min(verts)
        path = [rc_of(start)]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            if len(nbrs) != 2:
                return None
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(rc_of(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break
        return path

    def search(domains, on_bits, off_bits):
        state = propagate(domains, on_bits, off_bits)
        if state is None:
            return None
        domains, on_bits, off_bits = state

        key = (on_bits, off_bits, tuple(domains))
        if key in failed:
            return None

        status, comp = cycle_status(on_bits)
        if status == 1:
            if all(vid(r, c) in comp for r, c, _, _ in clues):
                return on_bits

        # Branch on smallest non-singleton clue domain first.
        best_i = None
        best_sz = 10**9
        for i, dom in enumerate(domains):
            sz = dom.bit_count()
            if sz > 1 and sz < best_sz:
                best_sz = sz
                best_i = i
                if sz == 2:
                    break

        if best_i is not None:
            dom = domains[best_i]
            ordered = [j for j in branch_order[best_i] if dom & (1 << j)]
            for j in ordered:
                nd = list(domains)
                nd[best_i] = 1 << j
                ans = search(nd, on_bits, off_bits)
                if ans is not None:
                    return ans
            failed.add(key)
            return None

        # If clues are fixed but graph still incomplete, branch on an edge.
        e = choose_edge(on_bits, off_bits)
        if e is None:
            failed.add(key)
            return None

        bit = 1 << e

        # Prefer ON first when it helps existing partial paths.
        a, b = edge_endpoints[e]
        prefer_on = False
        if ((incident_mask[a] & on_bits).bit_count() == 1) or ((incident_mask[b] & on_bits).bit_count() == 1):
            prefer_on = True
        order = [1, 0] if prefer_on else [0, 1]

        for val in order:
            if val == 1:
                if bit & off_bits:
                    continue
                ans = search(domains, on_bits | bit, off_bits)
            else:
                if bit & on_bits:
                    continue
                ans = search(domains, on_bits, off_bits | bit)
            if ans is not None:
                return ans

        failed.add(key)
        return None

    result_on = search(init_domains, 0, 0)
    if result_on is None:
        return "No Solution"
    path = reconstruct_path(result_on)
    if path is None:
        return "No Solution"
    return repr(path)


